function runtimeEntryProcessAlive(entry) {
	const match = /^pptxgen\.(\d+)\./.exec(String(entry || ''))
	if (!match) return false
	const pid = Number(match[1])
	if (!Number.isSafeInteger(pid) || pid <= 0) return false
	if (pid === process.pid) return true
	try {
		process.kill(pid, 0)
		return true
	} catch (_) {
		return false
	}
}

function resolvePptxRuntimeEntry() {
	const source = DIST_RUNTIME_SOURCE
	if (process.env.BETTERPPTX_IMPORT_DIST_DIRECT === '1') return source
	const runtimeDir = path.resolve(process.env.BETTERPPTX_RUNTIME_DIR || path.join(process.cwd(), '.betterpptx-runtime'))
	try {
		const st = fsNode.statSync(source)
		fsNode.mkdirSync(runtimeDir, { recursive: true })
		const runtime = path.join(runtimeDir, `pptxgen.${process.pid}.${Math.round(st.mtimeMs)}.${st.size}.mjs`)
		if (!fsNode.existsSync(runtime)) {
			fsNode.copyFileSync(source, runtime)
			try {
				const now = new Date()
				fsNode.utimesSync(runtime, now, now)
			} catch (_) {}
		}
		const staleRuntimeMs = Math.max(60_000, Number(process.env.BETTERPPTX_RUNTIME_STALE_MS || 10 * 60 * 1000))
		const now = Date.now()
		for (const entry of fsNode.readdirSync(runtimeDir)) {
			if (entry.startsWith('pptxgen.') && entry.endsWith('.mjs') && entry !== path.basename(runtime)) {
				try {
					const candidate = path.join(runtimeDir, entry)
					const candidateStat = fsNode.statSync(candidate)
					if (now - candidateStat.mtimeMs > staleRuntimeMs && !runtimeEntryProcessAlive(entry)) fsNode.rmSync(candidate, { force: true })
				} catch (_) {}
			}
		}
		return runtime
	} catch (err) {
		process.stderr.write(`[betterpptx] runtime bundle shadow-copy failed; importing dist directly: ${err?.message || err}\n`)
		return source
	}
}
const PPTX_RUNTIME_FILE = resolvePptxRuntimeEntry()
const PPTX_ENTRY = pathToFileURL(PPTX_RUNTIME_FILE).href
const PptxRuntimeModulePromise = import(PPTX_ENTRY)
const PptxGenJSPromise = PptxRuntimeModulePromise.then(m => m.default || m.PptxGenJS || m)

async function attachResolvedShapeFillImage(slide, fill) {
	if (!slide || !fill || typeof fill !== 'object') return
	const runtime = await PptxRuntimeModulePromise
	const PptxRuntime = runtime.default || runtime.PptxGenJS || runtime
	if (typeof PptxRuntime.attachShapeFillImage !== 'function') {
		throw new Error('The native runtime does not expose the governed shape-fill asset bridge.')
	}
	PptxRuntime.attachShapeFillImage(slide, fill)
}

async function defaultMediaCoverDataUri() {
	const runtime = await PptxRuntimeModulePromise
	const PptxRuntime = runtime.default || runtime.PptxGenJS || runtime
	const value = PptxRuntime.defaultMediaCoverDataUri
	if (typeof value !== 'string' || !/^data:image\/png;base64,/i.test(value)) throw new Error('The native runtime does not expose its media poster default.')
	return value
}

function ensurePptxRuntimeShadowFresh() {
	if (path.resolve(PPTX_RUNTIME_FILE) === path.resolve(DIST_RUNTIME_SOURCE)) return
	try {
		const sourceStat = fsNode.statSync(DIST_RUNTIME_SOURCE)
		let runtimeStat = null
		try {
			runtimeStat = fsNode.statSync(PPTX_RUNTIME_FILE)
		} catch (_) {}
		if (runtimeStat && runtimeStat.size === sourceStat.size) return
		fsNode.mkdirSync(path.dirname(PPTX_RUNTIME_FILE), { recursive: true })
		fsNode.copyFileSync(DIST_RUNTIME_SOURCE, PPTX_RUNTIME_FILE)
		try {
			const now = new Date()
			fsNode.utimesSync(PPTX_RUNTIME_FILE, now, now)
		} catch (_) {}
	} catch (err) {
		process.stderr.write(`[betterpptx] runtime shadow-copy refresh failed: ${err?.message || err}\n`)
	}
}

