// Public, sanitized chart capability summary. The executable catalog itself is
// still resolved behind opaque ids; this summary only tells an AI client what
// semantic families and per-family gallery states are available. Keeping it
// derived from the same catalog prevents help.capabilities from drifting back
// to the old nine-chart description while chart.recommend exposes the full map.
async function publicChartCatalogSummary() {
	const catalog = await loadChartPresetModule()
	const tiles = catalog.listChartGalleryUiPresets({ limit: 2000 })
	const executable = tiles.filter(tile => tile.serializationStatus === 'package-backed' || tile.serializationStatus === 'native-engine')
	const perType = {}
	for (const tile of executable) {
		const row = perType[tile.chartType] || { styles: 0, colors: 0, layouts: 0 }
		if (tile.galleryKind === 'styles') row.styles += 1
		if (tile.galleryKind === 'colors') row.colors += 1
		if (tile.galleryKind === 'layouts') row.layouts += 1
		perType[tile.chartType] = row
	}
	return {
		contractVersion: 'betterpptx.chart-plan.v1',
		canonicalSemantics: Object.keys(perType),
		executableGalleryStates: executable.length,
		galleryKinds: ['styles', 'colors', 'layouts'],
		perType,
		styleResourceCatalog: { packageVariants: 49, styleFamilies: 13, colorFamilies: 12, treatmentPresets: 24 },
		supportClassification: {
			native: ['area', 'area3D', 'bar', 'bar3D', 'bubble', 'bubble3D', 'doughnut', 'line', 'line3D', 'pie', 'pie3D', 'ofPie', 'radar', 'scatter', 'treemap', 'sunburst', 'histogram', 'pareto', 'boxWhisker', 'waterfall', 'funnel', 'regionMap'],
			nativeComposite: ['combo'],
			preserveEdit: ['stock', 'surface'],
		},
		selection: 'The AI searches the unranked public catalog, chooses exact ids, and passes an opaque chartGalleryTilePresetId; the engine validates applicability before mutation.',
	}
}

