async function resolveProductChartPlan({ chartType, chartMulti, options = {} } = {}) {
	const source = options && typeof options === 'object' ? options : {}
	const selectorKeys = [
		'chartPresetId', 'chartGalleryTilePresetId', 'chartStylePresetId',
		'chartGalleryVariant', 'chartStyleId', 'chartStyleModernId',
		'chartColorStyleId', 'chartLayoutPresetId', 'chartTreatmentPresetId',
		'chartTreatmentPresetIds',
	]
	const hasSelector = selectorKeys.some(key => source[key] !== undefined && source[key] !== null)
	const semanticOnlyType = chartType != null && ['area3D', 'line3D', 'pie3D', 'surface3D', 'stock'].includes(String(chartType))
	if (!hasSelector && !semanticOnlyType) return { plan: {}, mode: 'none', selectedChartType: chartType }
	if (chartMulti && source.chartGalleryTilePresetId) {
		throw new Error('Exact Ribbon tile replay is only available for a single chart; use chartStylePresetId or treatment presets for a combo chart.')
	}
	const { resolveChartPlan } = await loadChartPlanModule()
	const resolution = await resolveChartPlan({
		chartType: chartType || undefined,
		chartPresetId: source.chartPresetId,
		chartGalleryTilePresetId: source.chartGalleryTilePresetId,
		chartStylePresetId: source.chartStylePresetId,
		chartGalleryVariant: source.chartGalleryVariant,
		chartStyleId: source.chartStyleId,
		chartStyleModernId: source.chartStyleModernId,
		chartColorStyleId: source.chartColorStyleId,
		chartLayoutPresetId: source.chartLayoutPresetId,
		chartTreatmentPresetId: source.chartTreatmentPresetId,
		chartTreatmentPresetIds: source.chartTreatmentPresetIds,
	}, path.resolve(__dirname, '..'))
	return {
		...resolution,
		selectedChartType: resolution.plan?.chartType || chartType,
	}
}

function mergeResolvedChartOptions(plan = {}, requested = {}) {
	const source = requested && typeof requested === 'object' ? { ...requested } : {}
	const explicitKeys = Array.isArray(source._authoringExplicitOptionKeys)
		? source._authoringExplicitOptionKeys.map(String)
		: null
	delete source._authoringExplicitOptionKeys
	// Primitive callers author every supplied option explicitly. Semantic
	// Director calls carry a private key list so catalog treatments may replace
	// compiler fallbacks without replacing the AI's actual design decisions.
	if (!explicitKeys) return { ...(plan || {}), ...source }
	const merged = { ...source, ...(plan || {}) }
	for (const key of explicitKeys) if (Object.prototype.hasOwnProperty.call(source, key)) merged[key] = source[key]
	return merged
}

