function estimatePublicHelpTokens(value) {
	if (value == null) return 1
	if (Array.isArray(value)) return 1 + value.reduce((total, item) => total + estimatePublicHelpTokens(item), 0)
	if (typeof value === 'object') {
		return 1 + Object.entries(value).reduce((total, [key, child]) => total + Math.max(1, Math.ceil(Array.from(key).length / 9)) + estimatePublicHelpTokens(child), 0)
	}
	if (typeof value === 'string') return Math.max(1, Math.ceil(Array.from(value).length / 6))
	return 1
}

function publicHelpBudgetInteger(name, fallback, minimum, maximum) {
	const value = Number(process.env[name])
	return Number.isInteger(value) && value >= minimum && value <= maximum ? value : fallback
}

function publicHelpResponseBudget(payload) {
	// Summary is the cold-client response and stays deliberately compact. A
	// focused full response carries the same contract with fuller recipes, so
	// it gets a larger service default. Both ceilings remain configurable by
	// deployment; an explicit environment ceiling is never hidden.
	const focusedDetail = payload?.detail && payload.detail !== 'summary'
	const configuredMaxBytes = publicHelpBudgetInteger('BETTERPPTX_PUBLIC_HELP_MAX_BYTES', focusedDetail ? 64 * 1024 : 16 * 1024, 8 * 1024, 96 * 1024)
	const configuredProxyMaxTokens = publicHelpBudgetInteger('BETTERPPTX_PUBLIC_HELP_MAX_PROXY_TOKENS', focusedDetail ? 10000 : 2500, 1000, 20000)
	const configurationSource = process.env.BETTERPPTX_PUBLIC_HELP_MAX_BYTES || process.env.BETTERPPTX_PUBLIC_HELP_MAX_PROXY_TOKENS ? 'environment-override' : 'service-default'
	const staticBudget = {
		configured: { maxBytes: configuredMaxBytes, maxProxyTokens: configuredProxyMaxTokens, source: configurationSource },
		proxy: { status: 'approximate', method: 'Heuristic estimate: strings/6, names/9, containers/1.', withinConfiguredLimit: null },
		actualTokenizer: { status: 'not-measured', reason: 'Requires host measurement.' },
		connectorVisiblePayload: { status: 'estimated-server-boundary', structuredContentBytes: null, textFallbackBytes: null, estimatedCompleteToolResultBytes: null, protocolEnvelopeBytes: null, duplicationExpectedForCompatibility: true, note: 'Result includes structured content and a text fallback; connector bytes and host tokens require host measurement.' },
	}
	// The dispatcher applies the same public boundary sanitizer after the
	// handler returns. Measure that public projection so the reported size is
	// the size a client actually receives, not the maintainer-side object.
	const measuredPayload = isPublicBlackBoxMode() ? sanitizePublicResult(payload) : payload
	let measuredBytes = 0
	let estimatedTokens = 0
	for (let attempt = 0; attempt < 16; attempt++) {
		const budget = {
			...staticBudget,
			status: measuredBytes <= configuredMaxBytes ? 'within-configured-byte-budget' : 'over-configured-byte-budget',
			measuredBytes,
			estimatedTokens,
			proxy: { ...staticBudget.proxy, withinConfiguredLimit: estimatedTokens <= configuredProxyMaxTokens },
			connectorVisiblePayload: {
				...staticBudget.connectorVisiblePayload,
				structuredContentBytes: measuredBytes,
				textFallbackBytes: measuredBytes,
				estimatedCompleteToolResultBytes: measuredBytes * 2 + 256,
			},
		}
		const candidate = { ...measuredPayload, responseBudget: budget }
		const nextBytes = Buffer.byteLength(JSON.stringify(candidate), 'utf8')
		const nextTokens = estimatePublicHelpTokens(candidate)
		if (nextBytes === measuredBytes && nextTokens === estimatedTokens) return candidate
		measuredBytes = nextBytes
		estimatedTokens = nextTokens
	}
	const budget = {
		...staticBudget,
		status: measuredBytes <= configuredMaxBytes ? 'within-configured-byte-budget' : 'over-configured-byte-budget',
		measuredBytes,
		estimatedTokens,
		proxy: { ...staticBudget.proxy, withinConfiguredLimit: estimatedTokens <= configuredProxyMaxTokens },
		connectorVisiblePayload: {
			...staticBudget.connectorVisiblePayload,
			structuredContentBytes: measuredBytes,
			textFallbackBytes: measuredBytes,
			estimatedCompleteToolResultBytes: measuredBytes * 2 + 256,
		},
	}
	return { ...measuredPayload, responseBudget: budget }
}

