async function handleAuthoringBaselineCatalog(args = {}, context = {}) {
	if (args.motionWindowRequirements !== undefined && args.view !== 'motion-comparisons') throw Object.assign(new Error('Source movement windows require view motion-comparisons.'),{code:'MOTION_COMPARISON_SCOPE_INVALID'})
	if (args.preparationTarget !== undefined && args.view !== 'motion-comparisons') throw Object.assign(new Error('Target preparation comparisons require view motion-comparisons.'),{code:'MOTION_COMPARISON_SCOPE_INVALID'})
	if (args.view === 'motion-comparisons') {
		if (args.controlId || args.intent) throw Object.assign(new Error('Motion comparison pages use family, query and motionRequirements; use controls for intent or an exact controlId.'),{code:'MOTION_COMPARISON_SCOPE_INVALID'})
		if ((args.family || args.surface) && (args.family || args.surface) !== 'presenter-motion') throw Object.assign(new Error('Motion comparisons require family presenter-motion.'),{code:'MOTION_REQUIREMENT_FAMILY_REQUIRED'})
		if (args.preparationTarget !== undefined) validateMotionComparisonTarget(args.preparationTarget,args.limit??12)
		if (args.motionWindowRequirements !== undefined) validateMotionWindowRequirements(args.motionWindowRequirements)
		let filteredEntries;const globalPreparation=args.preparationTarget?.scope==='filtered-catalog';
		const catalog=publicBaselineCatalog({...args,family:'presenter-motion',limit:args.limit??12},globalPreparation?{captureFilteredEntries:entries=>{filteredEntries=entries}}:{})
		let page=motionComparisonPage(catalog)
		if (args.motionWindowRequirements !== undefined) page=motionComparisonWindows(page,catalog,args.motionWindowRequirements)
		return args.preparationTarget === undefined ? page : globalPreparation?motionComparisonCatalogReadiness(page,filteredEntries,args.preparationTarget,context,dispatchMotionPreparationProfileCatalog,dispatchMotionPreparationProfileList):motionComparisonTargetReadiness(page,args.preparationTarget,context,dispatchMotionPreparationProfileList)
	}
	if (args.view === 'lesson' || args.lessonId) return publicAuthoringLesson(args.lessonId || args.query || args.q)
	if (args.view === 'controls' || args.controlId || args.intent) return publicControlRegistry(args)
	const catalog = publicBaselineCatalog({ ...args, limit: args.limit ?? 12 })
	if (!isPublicBlackBoxMode()) return catalog
	// Public discovery is intentionally bounded. The full typed schemas remain
	// available on the individual MCP tool definitions; repeating them on every
	// catalog row makes a small page enormous and obscures the semantic choices.
	return {
		...catalog,
		principle: {
			aiIsDesignMaster: true,
			engineRole: 'expose-and-execute',
			catalogDoesNotSelect: true,
		},
		catalogClosure: undefined,
		entries: catalog.entries.map(({ publicSchema: _publicSchema, overrideFields: _overrideFields, source: _source, ...entry }) => entry),
	}
}

async function handleAuthStatus(_args = {}, context = {}) {
	const state = getAuthState(context)
	const securedFreeValueIdentity = Boolean(context.installHash || context.quotaIdentityHash)
	const identityBasis = context.authenticated === true
		? context.authenticationBasis || 'verified-account'
		: context.installHash
		? 'installation-fingerprint'
		: context.quotaIdentityHash
			? 'connector-subject-hmac'
			: context.resourceIdentityHash
				? 'connector-continuity-only'
				: 'session-only'
	const [deckPublications, narrationPreparations, talkingHeads, rigged3dPersonas] = await Promise.all([
		getFreeValueStatus('betterpptx.deck.save', {}, context),
		getFreeValueStatus('betterpptx.narration.synthesize', {}, context),
		getFreeValueStatus('betterpptx.avatar.render_job', {}, context),
		getFreeValueStatus('betterpptx.assets.generate_rigged3d', { imageHandles: ['eligible://front', 'eligible://side'] }, context),
	])
	return {
		...state,
		identityAssurance: {
			secured: context.authenticated === true,
			authenticated: context.authenticated === true,
			basis: identityBasis,
			freeValueQuotaEligible: securedFreeValueIdentity,
			opaque: true,
			note: context.authenticated === true
				? 'A verified account access token binds resource ownership and rolling allowances. No raw account identifier is exposed.'
				: 'No authenticated account is established. An opaque fingerprint alone does not authenticate its sender. Public protected operations require sign-in.',
		},
		freeAllowances: { deckPublications, narrationPreparations, talkingHeads, rigged3dPersonas },
		workflowStages: workflowStageEntitlements(context),
		billingDryRun: publicBillingDryRunSummary(getBillingTelemetrySummary()),
		billing: await publicBillingStatus(context),
	}
}

function handleAuthGetProfile(_args = {}, context = {}) {
	if (context.authenticated !== true || !context.installHash) {
		throw Object.assign(new Error('A verified BetterPPTX account access token is required.'), {
			code: 'AUTHENTICATION_REQUIRED',
			retryable: true,
		})
	}
	const id = crypto.createHash('sha256')
		.update(`betterpptx-profile-v1\0${context.installHash}`)
		.digest('base64url')
	return { id: `bpptx_${id}` }
}

