async function handleBillingRedeemPromo(args = {}, context = {}) {
	if (String(process.env.BETTERPPTX_BILLING_MODEL || '').trim().toLowerCase() === 'pay_per_job') {
		const error = new Error('Reusable promotional balances are disabled in pay-per-job mode. A bounded job-sponsorship route is not configured for this deployment.')
		error.code = 'PROMO_JOB_SPONSOR_NOT_CONFIGURED'
		error.details = {
			paymentModel: 'one_payment_per_job',
			recovery: 'Use the exact x402 quote for the job, or ask the owner to configure a bounded job-sponsorship campaign.',
		}
		throw error
	}
	const customerHash = String(context.installHash || '').trim()
	if (!customerHash) {
		const error = new Error('A stable installation identity is required to redeem a promo code.')
		error.code = 'PROMO_CUSTOMER_REQUIRED'
		throw error
	}
	return redeemPromoTopup({
		code: args.promoCode,
		packId: args.packId,
		customerHash,
		customerEmail: args.customerEmail,
		idempotencyKey: args.idempotencyKey || '',
		env: process.env,
		ledger: createBillingLedgerStore(),
	})
}

async function handleBillingEstimate(args = {}, context = {}) {
	const toolName = args.toolName || args.tool || 'betterpptx.deck.save'
	const toolArgs = { ...(args.toolArgs || {}) }
	if (toolName === 'betterpptx.deck.generate_from_spec' && (toolArgs.specHandle || toolArgs.specArtifact?.handle)) {
		const resolved = await resolveCanonicalSpecSource(toolArgs)
		toolArgs.spec = resolved.spec
	}
	if (toolName === 'betterpptx.deck.generate_from_spec' && toolArgs.spec && typeof toolArgs.spec === 'object' && !Array.isArray(toolArgs.spec)) await hydrateSpecGenAssets(toolArgs.spec, context)
	const deckId = toolArgs.deckId || args.deckId
	const preparedNarrationTimingBySlide = toolName === 'betterpptx.deck.generate_from_spec'
		&& toolArgs?.spec && typeof toolArgs.spec === 'object' && !Array.isArray(toolArgs.spec)
		? await preparedNarrationTimingBySlideForSpec(toolArgs.spec)
		: null
	const estimate = publicBillingEstimate({
		toolName,
		args: { ...toolArgs, ...(deckId ? { deckId } : {}) },
		entry: deckId ? getDeck(deckId) : null,
		preparedNarrationTimingBySlide,
		validatePreparedScene: (modelAsset, scene) => {
			const parsed = parseGenRigged3dHandle(modelAsset)
			return resolvePreparedMotionScene(parsed ? getCachedGeneratedRigged3d(parsed.hash) : null, scene)
		},
	})
	const freeAllowance = await getFreeValueStatus(toolName, toolArgs, context, { purpose: 'estimate' })
	if (!freeAllowance.eligible) return { ...estimate, freeAllowance }
	// A spec quote remains useful on a sponsored publication route: its binding
	// freezes the exact spec/plan/timeline and unsubsidized cost inputs even
	// though the customer-facing estimate is zero. Save remains the sole point
	// that atomically reserves and commits the publication allowance.
	const preserveIntegrityBinding = toolName === 'betterpptx.deck.generate_from_spec'
	const sponsoredClassification = freeAllowance.category === 'deck-publication'
		? 'sponsored-publication'
		: `sponsored-${freeAllowance.category}`
	const { quoteBinding: paidQuoteBinding, ...estimateWithoutBinding } = estimate
	const freeEstimate = preserveIntegrityBinding
		? { ...estimateWithoutBinding, ...(paidQuoteBinding ? { quoteBinding: paidQuoteBinding } : {}) }
		: estimateWithoutBinding
	const zeroCustomerMetrics = (metrics) => metrics && typeof metrics === 'object'
		? {
			...metrics,
			specEstimatedCredits: 0,
			finalSaveEstimatedCredits: 0,
		}
		: metrics
	return {
		...freeEstimate,
		metrics: zeroCustomerMetrics(estimate.metrics),
		unsubsidizedEstimate: {
			estimatedCredits: estimate.estimatedCredits ?? null,
			quoteCapCredits: estimate.quoteCapCredits ?? null,
			priceUsdc: estimate.priceUsdc ?? null,
			amountAtomic: estimate.amountAtomic ?? null,
			specEstimatedCredits: estimate.specEstimatedCredits ?? null,
			finalSaveEstimatedCredits: estimate.finalSaveEstimatedCredits ?? null,
			note: 'Operational cost absorbed by BetterPPTX for this bounded free allowance.',
		},
		estimatedCredits: 0,
		quoteCapCredits: 0,
		priceUsdc: 0,
		amountAtomic: '0',
		specEstimatedCredits: 0,
		finalSaveEstimatedCredits: 0,
		estimate: estimate.estimate && typeof estimate.estimate === 'object'
			? {
				...estimate.estimate,
				metrics: zeroCustomerMetrics(estimate.estimate.metrics),
				estimatedCredits: 0,
				quoteCapCredits: 0,
				priceUsdc: 0,
				amountAtomic: '0',
				customerChargeClassification: sponsoredClassification,
			}
			: estimate.estimate,
		confirmationRequired: false,
		billingRequired: false,
		readyForExecution: true,
		freeAllowance,
		authorization: 'bounded-free-allowance',
		customerChargeClassification: sponsoredClassification,
	}
}

