function unclassifiedRuntimeErrorCode(code) {
	const value = String(code || 'OPERATION_FAILED')
	return /^\d+$/.test(value) || [
		'TOOL_ERROR', 'OPERATION_FAILED', 'UNKNOWN', 'INTERNAL', 'UNAVAILABLE',
		'DEADLINE_EXCEEDED', 'RESOURCE_EXHAUSTED', 'ABORTED', 'INVALID_ARGUMENT',
		'PERMISSION_DENIED', 'UNAUTHENTICATED', 'NOT_FOUND', 'CANCELLED',
	].includes(value)
}

function publicDurableOperationStatus(operation = {}) {
	const out = {
		operationId: operation.operationId || '',
		state: operation.state || 'unknown',
		queueClass: operation.queueClass || 'default',
		attempt: Number(operation.attempt || 0),
		createdAt: operation.createdAt || '',
		updatedAt: operation.updatedAt || '',
	}
	if (operation.state === 'running' || operation.state === 'retry' || operation.state === 'queued') {
		out.retryAfterMs = Number(process.env.BETTERPPTX_OPERATION_STATUS_RETRY_AFTER_MS || 2000)
		if (operation.leaseExpiresAt) out.leaseExpiresAt = operation.leaseExpiresAt
		out.next = { type: 'retry_or_poll', tool: 'betterpptx.operation.status' }
	}
	if (operation.state === 'succeeded') {
		out.result = sanitizePublicResult(restorePersistedSpecHandoffProvenance(cloneForResult(operation.result || {})))
		out.next = { type: 'use_result' }
	}
	if (operation.state === 'failed' || operation.state === 'cancelled') {
		const failureCode = String(operation.error?.code || 'OPERATION_FAILED')
		out.error = {
			code: failureCode,
			message: isPublicBlackBoxMode() && unclassifiedRuntimeErrorCode(failureCode)
				? 'The operation did not complete successfully; its artifact outcome has not been confirmed.'
				: operation.error?.message || 'Operation failed.',
		}
		if (failureCode === 'OPERATION_RESULT_PERSISTENCE_FAILED' || unclassifiedRuntimeErrorCode(failureCode)) {
			out.executionState = 'unconfirmed'
			out.artifact_state = 'unchanged_or_unknown'
			out.retry_safe = false
			out.next = { type: 'recover_operation', tool: 'betterpptx.operation.status',
				reason: 'Completion could not be confirmed; do not start a duplicate mutation with a new key.' }
		} else out.next = { type: 'new_idempotency_key' }
	}
	return out
}

async function ownedDurableOperation(args = {}, context = {}) {
	if (!_operationStore || _operationStore.disabled || typeof _operationStore.getOperation !== 'function') {
		const err = new Error('Durable operation status is not enabled.')
		err.code = 'OPERATION_STORE_DISABLED'
		throw err
	}
	const operationId = String(args.operationId || '').trim()
	if (!/^op_[0-9a-f]{32}$/i.test(operationId)) {
		const err = new Error('operationId must be an opaque BetterPPTX operation id.')
		err.code = 'OPERATION_ID_INVALID'
		throw err
	}
	const operation = await _operationStore.getOperation(operationId)
	if (!operation) {
		const err = new Error('Operation was not found.')
		err.code = 'OPERATION_NOT_FOUND'
		throw err
	}
	const boundInstall = String(operation.installHash || '')
	const requestInstall = String(context.installHash || context.resourceIdentityHash || context.billingCustomerHash || context.sessionId || '')
	const maintainer = isLocalMaintainerMode() && !isProductionBillingEnvironment()
	if ((!boundInstall || !requestInstall || boundInstall !== requestInstall) && !maintainer) {
		const err = new Error('Operation was not found.')
		err.code = 'OPERATION_NOT_FOUND'
		throw err
	}
	return operation
}

async function handleOperationStatus(args = {}, context = {}) {
	const operation = await ownedDurableOperation(args, context)
	const status = publicDurableOperationStatus(operation)
	// The operation is owner-bound above. Refresh only the browser link, never
	// the saved package or publication count, so an expired link is recoverable.
	if (status.state === 'succeeded' && typeof status.result?.downloadUrl === 'string'
		&& typeof _artifactStore?.issueBrowserDownload === 'function') {
		try {
			const fresh = await _artifactStore.issueBrowserDownload({
				downloadUrl: status.result.downloadUrl,
				downloadName: status.result.downloadName,
			})
			status.result.downloadUrl = fresh.downloadUrl
			status.result.artifact = { ...(status.result.artifact || {}), downloadLinkExpiresAt: fresh.downloadLinkExpiresAt }
		} catch {
			status.result.downloadUrl = null
			status.result.artifact = { ...(status.result.artifact || {}), state: 'unavailable' }
		}
	}
	return status
}

async function handleOperationReadFile(args = {}, context = {}) {
	const operation = await ownedDurableOperation(args, context)
	const status = publicDurableOperationStatus(operation)
	const saved = status.state === 'succeeded' ? status.result : null
	if (!saved || typeof saved.downloadUrl !== 'string' || typeof saved.downloadName !== 'string'
		|| !saved.downloadName.toLowerCase().endsWith('.pptx')
		|| !/^[a-f0-9]{64}$/i.test(String(saved.packageSha256 || ''))
		|| typeof _artifactStore?.readArtifactChunk !== 'function') {
		throw Object.assign(new Error('The completed operation has no retrievable presentation artifact.'), { code: 'ARTIFACT_NOT_AVAILABLE' })
	}
	const offset = args.offset === undefined ? 0 : Number(args.offset)
	const maxBytes = args.maxBytes === undefined ? 32768 : Number(args.maxBytes)
	const mode = args.mode || 'link'
	const resourceDeliveryPolicy = {
		maxDirectResourceBytes: DEFAULT_CLIENT_SAFE_EMBED_BYTES,
		sizeBasis: 'decoded-artifact-bytes',
		largerFiles: 'browser-download-link',
		limitBasis: 'conservative-product-policy-not-a-universal-host-limit',
	}
	if (!Number.isSafeInteger(offset) || offset < 0 || !Number.isSafeInteger(maxBytes)
		|| maxBytes < 1 || maxBytes > 32768 || !['link', 'chunk', 'resource'].includes(mode)) {
		throw Object.assign(new Error('Use a nonnegative integer offset, maxBytes from 1 to 32768, and mode link, chunk or resource.'), { code: 'ARTIFACT_READ_ARGUMENT_INVALID' })
	}
	const readLimit = mode === 'resource' ? undefined : maxBytes
	if (mode !== 'chunk' && offset !== 0) {
		throw Object.assign(new Error('Link and resource modes require offset zero.'), { code: 'ARTIFACT_READ_ARGUMENT_INVALID' })
	}
	// Probe a single byte before deciding the transport. Never pass a large file
	// through a model-visible tool result merely because the MCP wire allows it.
	const probe = await _artifactStore.readArtifactChunk({
		downloadUrl: saved.downloadUrl, downloadName: saved.downloadName, offset: 0, maxBytes: 1,
	})
	const linkOnly = shouldOfferDownloadLink(mode, probe.totalBytes)
	if (linkOnly) {
		if (Number.isSafeInteger(saved.bytes) && saved.bytes !== probe.totalBytes) {
			throw Object.assign(new Error('The stored artifact size does not match its publication record.'), { code: 'ARTIFACT_IDENTITY_MISMATCH' })
		}
		const fresh = await _artifactStore.issueBrowserDownload({ downloadUrl: saved.downloadUrl, downloadName: saved.downloadName })
		return {
			ok: true, operationId: String(args.operationId), mode: 'link',
			resourceDeliveryPolicy,
			fileName: saved.downloadName, downloadName: saved.downloadName,
			mimeType: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
			totalBytes: probe.totalBytes, bytes: probe.totalBytes, packageSha256: saved.packageSha256,
			downloadUrl: fresh.downloadUrl, downloadLinkExpiresAt: fresh.downloadLinkExpiresAt,
			artifactExpiresAt: saved.artifact?.expiresAt || null,
			deliveryReason: mode === 'link' ? 'requested-link' : 'resource-exceeds-conservative-client-size',
		}
	}
	let embeddedBytes
	if (mode === 'resource') {
		// Check the size before allocating or serializing a potentially large file.
		embeddedBytes = assertEmbeddedPresentationSize(probe.totalBytes, saved.bytes)
	}
	const { bytes, totalBytes } = await _artifactStore.readArtifactChunk({
		downloadUrl: saved.downloadUrl, downloadName: saved.downloadName, offset,
		maxBytes: mode === 'resource' ? embeddedBytes : readLimit,
	})
	if (mode === 'resource') verifyEmbeddedPresentation(bytes, totalBytes, saved.packageSha256)
	if (Number.isSafeInteger(saved.bytes) && saved.bytes !== totalBytes) {
		throw Object.assign(new Error('The stored artifact size does not match its publication record.'), { code: 'ARTIFACT_IDENTITY_MISMATCH' })
	}
	return {
		ok: true,
		operationId: String(args.operationId),
		fileName: saved.downloadName,
		mimeType: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
		totalBytes,
		packageSha256: saved.packageSha256,
		offset,
		bytesReturned: bytes.length,
		nextOffset: offset + bytes.length < totalBytes ? offset + bytes.length : null,
		encoding: 'base64',
		mode,
		resourceDeliveryPolicy,
		dataBase64: bytes.toString('base64'),
	}
}

async function handleMonetizedMcpPriceListing(args = {}, context = {}) {
	const toolArgs = args.toolArgs || args.args || {}
	const deckId = args.deckId || toolArgs.deckId
	const hasExplicitQuote = args.premiumQuote || args.quoteCapCredits || args.estimatedCredits
	if (hasExplicitQuote && isPublicBlackBoxMode() && !isLocalMaintainerMode()) {
		throw Object.assign(new Error('Executable prices are calculated by the service from the authored specification or owned deck, not supplied by the caller.'), { code: 'SERVER_QUOTE_REQUIRED' })
	}
	// Connector clients may carry the interrupted tool arguments under
	// toolArgs.  The public price-listing contract remains spec/deckId based,
	// but accepting the connector envelope here prevents a valid exact spec from
	// degrading into an unpriced placeholder before the wallet can authorize it.
	const quotedSpec = args.spec && typeof args.spec === 'object' && !Array.isArray(args.spec)
		? args.spec
		: (toolArgs.spec && typeof toolArgs.spec === 'object' && !Array.isArray(toolArgs.spec) ? toolArgs.spec : null)
	const hasSpecQuote = Boolean(quotedSpec)
	if (hasSpecQuote) await hydrateSpecGenAssets(quotedSpec, context)
	const { spec: _spec, premiumQuote: _premiumQuote, toolArgs: _toolArgs, args: _nestedArgs, ...listingArgs } = args
	const quoteInputArgs = { ...toolArgs, ...(_nestedArgs && typeof _nestedArgs === 'object' ? _nestedArgs : {}), ...listingArgs }
	delete quoteInputArgs.spec
	delete quoteInputArgs.premiumQuote
	const premiumQuote = hasExplicitQuote
		? args.premiumQuote || {
			quoteCapCredits: args.quoteCapCredits,
			estimatedCredits: args.estimatedCredits,
			rateCardVersion: args.rateCardVersion,
			toolName: args.toolName || args.tool || 'betterpptx.deck.save',
			deckId,
		}
		: hasSpecQuote
			? buildSpecPremiumPresentationQuote({
				spec: quotedSpec,
				args: {
					...quoteInputArgs,
					plan: listingArgs.plan || 'premium',
					toolName: args.toolName || args.tool || 'betterpptx.deck.generate_from_spec',
				},
				deckId,
				preparedNarrationTimingBySlide: await preparedNarrationTimingBySlideForSpec(quotedSpec),
			})
		: deckId
			? publicBillingEstimate({
				toolName: args.toolName || args.tool || 'betterpptx.deck.save',
				args: { ...toolArgs, deckId },
				entry: getDeck(deckId),
			})
			: null
	return listMonetizedMcpPrices(listingArgs, context, { premiumQuote })
}

function handleMonetizedMcpPaymentMethods() {
	return listMonetizedMcpPaymentMethods()
}

async function handleMonetizedMcpJobStatus(args = {}) {
	return getMonetizedMcpJobStatus(args)
}

function unwrapPaidServiceToolResult(label, result) {
	if (result?.ok === true && result.data && typeof result.data === 'object') return result.data
	const error = result?.error || result?.data?.error || {}
	const err = new Error(error.message || `${label} failed.`)
	err.code = error.code || 'PAID_SERVICE_TOOL_FAILED'
	err.details = error.details || { status: 'failed' }
	throw err
}

function paidServiceIdempotencyKey(prefix, quoteId, params = {}) {
	const digest = crypto.createHash('sha256')
		.update(`${prefix}:${quoteId}:${JSON.stringify(params)}`)
		.digest('hex')
		.slice(0, 24)
	return `monetized-mcp-${prefix}-${digest}`
}

function paidServiceFileName(params = {}, quoteId = '') {
	const raw = String(params.fileName || params.outputName || '').trim()
	const base = raw || `betterpptx-paid-${String(quoteId || 'deck').slice(0, 16)}.pptx`
	const safe = base.replace(/[\\/:*?"<>|]+/g, '-').replace(/\s+/g, ' ').trim().slice(0, 96)
	return /\.pptx$/i.test(safe) ? safe : `${safe || 'betterpptx-paid-deck'}.pptx`
}

async function executeMonetizedMcpPaidItem({ itemId, params = {}, envelope = {}, quote = {}, settlementPack = {} }, context = {}) {
	if (itemId !== MONETIZED_MCP_GENERATE_DECK_ITEM_ID) {
		const err = new Error('Unsupported paid service item.')
		err.code = 'PAID_SERVICE_ITEM_UNSUPPORTED'
		throw err
	}
	if (!params.spec || typeof params.spec !== 'object' || Array.isArray(params.spec)) {
		const err = new Error('params.spec is required for this paid BetterPPTX service item.')
		err.code = 'PAID_SERVICE_SPEC_REQUIRED'
		throw err
	}
	const serviceContext = {
		...context,
		installHash: envelope.installHash || context.installHash,
		sessionId: context.sessionId || `monetized-mcp:${quote.quoteId || envelope.jti || 'purchase'}`,
		...(quote.settlementMode === 'job' || quote.paymentModel === 'one_payment_per_job'
			? {
				// This marker is created only inside the already-settled purchase
				// handler.  It lets the compiler execute the paid bounded job as a
				// premium operation while keeping the public entitlement/ledger
				// accountless.
				__paidJobAuthorization: {
					paymentModel: 'one_payment_per_job',
					settled: true,
					jobId: String(envelope.jobId || quote.jobId || ''),
					quoteId: String(quote.quoteId || ''),
					bindingDigest: String(quote.jobPayment?.binding?.bindingDigest || ''),
				},
			}
			: {}),
	}
	const generateResult = await callBetterPptxTool('betterpptx.deck.generate_from_spec', {
		spec: params.spec,
		phase: 'commit',
		commitMode: 'createNew',
		plan: 'premium',
		validateAfterCompile: params.validateAfterCompile !== false,
		billingConfirmed: true,
		...(quote.packMetadata?.quoteBinding ? { quoteBinding: quote.packMetadata.quoteBinding } : {}),
		idempotencyKey: paidServiceIdempotencyKey('generate', quote.quoteId || envelope.jti, params.spec),
	}, serviceContext)
	const generated = unwrapPaidServiceToolResult('deck.generate_from_spec', generateResult)
	const saveResult = params.save === false
		? null
		: await callBetterPptxTool('betterpptx.deck.save', {
			deckId: generated.deckId,
			fileName: paidServiceFileName(params, quote.quoteId),
			idempotencyKey: paidServiceIdempotencyKey('save', quote.quoteId || envelope.jti, { deckId: generated.deckId, fileName: params.fileName || '' }),
		}, serviceContext)
	const saved = saveResult ? unwrapPaidServiceToolResult('deck.save', saveResult) : null
	return {
		ok: true,
		service: 'generate_deck_from_spec',
		deckId: generated.deckId,
		slideCount: saved?.slideCount || generated.slides?.length || generated.data?.slides?.length || 0,
		...(saved?.downloadUrl ? { downloadUrl: saved.downloadUrl, downloadName: saved.downloadName } : {}),
		artifact: saved?.artifact || (params.save === false ? { state: 'not_saved' } : undefined),
		...(quote.settlementMode === 'job' || quote.paymentModel === 'one_payment_per_job'
			? { paymentModel: 'one_payment_per_job', jobId: quote.jobId || null }
			: { includedCredits: settlementPack.credits }),
		warnings: [
			...(Array.isArray(generated.warnings) ? generated.warnings : []),
			...(Array.isArray(saved?.warnings) ? saved.warnings : []),
		],
		next: saved?.downloadUrl
			? { recommendedTool: null, reason: 'The paid deck artifact is ready.' }
			: { recommendedTool: 'betterpptx.deck.save', reason: 'Save the generated paid deck if an artifact URL is needed.' },
	}
}

async function handleMonetizedMcpPurchase(args = {}, context = {}) {
	return makeMonetizedMcpPurchase(args, {
		executePaidItem: input => executeMonetizedMcpPaidItem(input, context),
	})
}

async function handleDeckNew(args, capability = null) {
	if (capability !== SPEC_COMPILER_CAPABILITY) {
		const err = new Error('Direct deck construction is disabled. A running BetterPPTX MCP endpoint must compile an Authoring Excellence JSON spec through betterpptx.deck.generate_from_spec.')
		err.code = 'JSON_SPEC_AUTHORING_REQUIRED'
		err.details = {
			status: 'json_spec_authoring_required',
			blockedTool: 'betterpptx.deck.new',
			reason: 'The engine allocates a new deck only inside the generate_from_spec compiler transaction; there is no maintainer, dev, or primitive-direct bypass.',
			nextAction: { recommendedTool: 'betterpptx.deck.generate_from_spec', reason: 'Connect as an MCP client, discover the Authoring Excellence contract, dry-run the JSON spec, and compile it through generate_from_spec.' },
		}
		throw err
	}
	const pptx = await newPptx()
	const inheritanceThemeBaseline = cloneJson(pptx.theme || {})
	pptx.layout = args.layout || 'LAYOUT_WIDE'
	const inheritanceLayoutBaseline = pptx.layout
	pptx.title = cleanMetadataValue(args.title, `${BETTERPPTX_BRAND} presentation`)
	pptx.subject = cleanMetadataValue(args.subject, `${BETTERPPTX_BRAND} presentation`)
	pptx.author = cleanMetadataValue(args.author, BETTERPPTX_BRAND)
	pptx.company = cleanMetadataValue(args.company, BETTERPPTX_BRAND)
	pptx.revision = cleanRevisionValue(args.revision, '1')
	const documentMetadata = documentMetadataProvenance('authoring-spec', [
		{ field: 'dc:title', input: args.title, output: pptx.title },
		{ field: 'dc:subject', input: args.subject, output: pptx.subject },
		{ field: 'dc:creator', input: args.author, output: pptx.author },
		{ field: 'cp:revision', input: args.revision, output: pptx.revision },
		{ part: 'docProps/app.xml', field: 'Company', input: args.company, output: pptx.company },
	])
	if (typeof args.rtlMode === 'boolean') pptx.rtlMode = args.rtlMode
	if (args.theme) pptx.theme = args.theme
	if (args.enableIterateEngine === true) {
		const PptxGenJS = await PptxGenJSPromise
		if (typeof PptxGenJS.enableIterateEngine === 'function') PptxGenJS.enableIterateEngine()
	}
	const directorMode = normalizeDirectorMode(args.directorMode || args.authoringMode || 'director-strict', 'new')
	const warnings = directorMode === 'ai-sovereign'
		? ['AI-sovereign authoring is active: Director planning is disabled; complete validation remains required before save.']
		: ['New-deck creation uses the assisted Authoring Excellence Director contract.']
	const director = makeDirectorState({
		mode: directorMode,
		sourceType: 'new',
		intent: args.intent || args.subject || args.title,
	})
	const id = registerDeck({
		pptx,
		inheritanceThemeBaseline,
		inheritanceLayoutBaseline,
		createdAt: new Date().toISOString(),
		sourceType: 'new',
		creationPath: 'betterpptx.deck.generate_from_spec',
		documentMetadataProvenance: documentMetadata,
		director,
	})
	const entry = getDeck(id)
	return {
		deckId: id,
		layout: pptx.layout,
		title: pptx.title,
		version: pptx.version,
		director: publicDirectorStatus(entry),
		warnings,
	}
}

