function normalizeAssetKind(kind) {
	if (!kind) return null
	const s = String(kind).trim()
	const aliases = {
		customshape: 'customShape',
		customshapes: 'customShape',
		customgeometry: 'customShape',
		customgeometries: 'customShape',
		customgeom: 'customShape',
		customgeoms: 'customShape',
		freeform: 'customShape',
		freeforms: 'customShape',
		shapescene: 'shapeScene',
		shapescenes: 'shapeScene',
		shape: 'shapeScene',
		shapes: 'shapeScene',
		shapejson: 'shapeScene',
		model: 'model3d',
		model3d: 'model3d',
		models: 'model3d',
		glb: 'model3d',
	}
	return aliases[s.toLowerCase()] || s
}

function assetQueryTerms(query) {
	return [...new Set(String(query || '')
		.toLowerCase()
		.split(/[^a-z0-9]+/i)
		.map(s => s.trim())
		.filter(s => s.length >= 2))]
}

function aiCollectionPublicSummary(collection) {
	return {
		id: collection.id,
		title: collection.title,
		bestFor: collection.bestFor,
		sampleQueries: collection.sampleQueries || [],
	}
}

function collectionTerms(collection, keys = ['triggers', 'terms', 'categories', 'title', 'id']) {
	return assetQueryTerms(keys.flatMap(key => collection[key] || []).join(' '))
}

function collectionPhraseMatches(collection, text, termSet) {
	const normalized = String(text || '').toLowerCase()
	const triggerPhrases = uniqueAssetStrings([collection.id, collection.title, collection.triggers])
	for (const phrase of triggerPhrases) {
		const p = String(phrase || '').toLowerCase().trim()
		if (!p) continue
		const phraseTerms = assetQueryTerms(p)
		if (phraseTerms.length && phraseTerms.every(term => termSet.has(term))) return true
		if (p.includes(' ') && normalized.includes(p)) return true
	}
	return false
}

function buildAssetIntentQueryContext(contextText) {
	const rawTerms = assetQueryTerms(contextText)
	const rawSet = new Set(rawTerms)
	const expanded = new Set(rawTerms)
	const matchedCollections = []
	for (const collection of MICROSOFT_STOCK3D_AI_COLLECTIONS) {
		if (!collectionPhraseMatches(collection, contextText, rawSet)) continue
		matchedCollections.push(collection)
		for (const term of collectionTerms(collection, ['terms', 'categories', 'title', 'id'])) expanded.add(term)
	}
	return {
		rawTerms,
		terms: [...expanded],
		expandedTerms: [...expanded].filter(term => !rawSet.has(term)),
		matchedCollections,
	}
}

function classifyMicrosoftStock3DRecord(record) {
	const category = String(record?.category || record?.category_slug || '').toLowerCase()
	const haystack = [
		record?.title,
		record?.title_slug,
		record?.category,
		record?.category_slug,
		record?.tags?.tokens,
		record?.tags?.navigation_tags,
		record?.glb_metadata?.nodes_names,
	].flat().filter(Boolean).join(' ')
	const termSet = new Set(assetQueryTerms(haystack))
	const matches = []
	for (const collection of MICROSOFT_STOCK3D_AI_COLLECTIONS) {
		const categories = uniqueAssetStrings(collection.categories).map(value => value.toLowerCase())
		const categoryMatch = categories.some(value => value === category)
		const termMatch = collectionTerms(collection, ['terms']).some(term => termSet.has(term))
		if (categoryMatch || termMatch) matches.push(collection)
	}
	return matches
}

function mergeAiCollections(...groups) {
	const byId = new Map()
	for (const collection of groups.flat(2)) {
		if (!collection?.id || byId.has(collection.id)) continue
		byId.set(collection.id, collection)
	}
	return [...byId.values()]
}

function buildAssetCatalogGuide(result = {}) {
	const matchedCollections = result.matchedCollections || []
	const allCollections = MICROSOFT_STOCK3D_AI_COLLECTIONS.map(aiCollectionPublicSummary)
	return {
		workflow: [
			'Search with the real slide intent, not just the object name; query expansion maps abstract needs to concrete Microsoft Stock 3D objects.',
			'Prefer the first Microsoft Stock handle when it is semantically relevant; it is PowerPoint-native and can be passed directly to slide.add_model3d.',
			'Use useCase for story context such as "board strategy", "medical explainer", or "security incident" when the object is not obvious.',
		],
		microsoftStockOrganization: {
			models: '1,294 unique GLB models, deduped from 1,707 Office category records.',
			categories: '59 Office-style categories plus AI-facing intent collections.',
			handles: 'Stable model3d://microsoft-stock/<sha>/<slug> handles; no file paths are needed.',
		},
		matchedIntents: matchedCollections.map(aiCollectionPublicSummary),
		availableIntents: matchedCollections.length ? undefined : allCollections,
		suggestedQueries: matchedCollections.length
			? uniqueAssetStrings(matchedCollections.flatMap(collection => collection.sampleQueries)).slice(0, 8)
			: uniqueAssetStrings(MICROSOFT_STOCK3D_AI_COLLECTIONS.flatMap(collection => collection.sampleQueries?.[0])).slice(0, 12),
		selectionRules: [
			'Use sizePolicy="standard" for portable decks and "large-ok" when visual detail matters.',
			'Use animated:true results intentionally for motion-oriented slides; static models are safer for dense business slides.',
			'For broad business prompts, ask for the outcome or metaphor: strategy, risk, growth, finance, operations, people, or technology.',
		],
	}
}

function uniqueAssetStrings(values) {
	return [...new Set((values || [])
		.flatMap(value => Array.isArray(value) ? value : [value])
		.map(value => String(value || '').trim())
		.filter(Boolean))]
}

function titleFromAssetPath(value, fallback = 'asset') {
	const base = path.basename(String(value || fallback), path.extname(String(value || fallback)))
	const cleaned = base
		.replace(/-[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i, '')
		.replace(/[_-]+/g, ' ')
		.replace(/\s+/g, ' ')
		.trim()
	return cleaned || fallback
}

function safeAssetHandlePart(value, fallback = 'asset') {
	const slug = String(value || fallback)
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, '-')
		.replace(/^-+|-+$/g, '')
	return slug || fallback
}

function normalizeCatalogSource(value) {
	const s = String(value || '').trim().toLowerCase()
	if (!s) return null
	if (['microsoft', 'ms', 'office', 'powerpoint', 'stock', 'stock3d', 'microsoft-stock', 'microsoft-powerpoint-stock-3d'].includes(s)) return MICROSOFT_STOCK3D_SOURCE
	if (['iconscout', 'iconscout-private', 'private-iconscout'].includes(s)) return ICONSCOUT_SOURCE
	if (['toxsam', 'open-source', 'opensource', 'open3d', 'cc0', 'open-source-3d', 'toxsam-open-source-3d'].includes(s)) return TOXSAM_SOURCE
	if (['toxsam-quality', 'open-source-quality', 'open3d-quality', 'toxsam-open-source-3d-quality'].includes(s)) return TOXSAM_QUALITY_SOURCE
	if (['sketchfab', 'sketchfab-live', 'sketchfab-imported', 'live-sketchfab'].includes(s)) return SKETCHFAB_SOURCE
	return s
}

function catalogSourceMatches(item, source) {
	if (!source) return true
	if (item.source === source || item.sourceKey === source) return true
	if (source === TOXSAM_SOURCE && item.sourceFamily === TOXSAM_SOURCE) return true
	return false
}

function normalizeModelSizePolicy(value) {
	const s = String(value || 'standard').trim().toLowerCase()
	if (['small', 'low', 'light', 'compact'].includes(s)) return 'compact'
	if (['normal', 'default', 'standard'].includes(s)) return 'standard'
	if (['medium', 'balanced'].includes(s)) return 'balanced'
	if (['large', 'large-ok', 'high'].includes(s)) return 'large-ok'
	if (['all', 'any', 'unrestricted', 'none'].includes(s)) return 'unrestricted'
	return 'standard'
}

function assetModelSizeMiB(item) {
	const direct = Number(item?.sizeMiB)
	if (Number.isFinite(direct) && direct > 0) return direct
	const bytes = Number(item?.bytes || 0)
	return Number.isFinite(bytes) && bytes > 0 ? bytes / MODEL_BYTES_PER_MIB : 0
}

function modelSizeRankAdjustment(item) {
	if (item?.kind !== 'model3d') return 0
	const mib = assetModelSizeMiB(item)
	if (!mib) return 0
	if (mib <= 1) return 6
	if (mib <= 5) return 4
	if (mib <= 10) return 2
	if (mib <= 15) return -2
	if (mib <= 25) return -6
	return -14
}

