const SKETCHFAB_ALLOWED_LICENSES = new Set(['cc0', 'by'])
const SKETCHFAB_SHAREALIKE_LICENSES = new Set(['by-sa'])
const SKETCHFAB_STANDARD_LICENSES = new Set(['free-st'])
const SKETCHFAB_RESTRICTED_LICENSES = new Set(['by-nc', 'by-nc-sa', 'by-nc-nd', 'ed'])
const SKETCHFAB_NO_DERIVATIVE_LICENSES = new Set(['by-nd'])
const SKETCHFAB_LICENSE_DETAILS = {
	cc0: { slug: 'cc0', label: 'CC0 Public Domain', commercialUse: true, attributionRequired: false, url: 'http://creativecommons.org/publicdomain/zero/1.0/' },
	by: { slug: 'by', label: 'CC Attribution', commercialUse: true, attributionRequired: true, url: 'http://creativecommons.org/licenses/by/4.0/' },
	'by-sa': { slug: 'by-sa', label: 'CC Attribution-ShareAlike', commercialUse: true, attributionRequired: true, shareAlike: true, url: 'http://creativecommons.org/licenses/by-sa/4.0/' },
	'free-st': { slug: 'free-st', label: 'Free Standard', commercialUse: true, attributionRequired: false, standardTerms: true, url: 'https://sketchfab.com/licenses' },
}

function sketchfabCacheRoot() {
	if (process.env.BETTERPPTX_SKETCHFAB_CACHE_DIR) return path.resolve(process.env.BETTERPPTX_SKETCHFAB_CACHE_DIR)
	if (process.env.K_SERVICE || process.env.BETTERPPTX_REQUIRE_SHARED_STORES === '1') {
		return path.resolve('/tmp', 'betterpptx-sketchfab-assets')
	}
	return path.resolve(ASSETS_ROOT, 'outputs', 'sketchfab-assets')
}

function sketchfabManifestPath() {
	return path.join(sketchfabCacheRoot(), 'manifest.json')
}

function sketchfabAuthFromEnv() {
	const apiKey = process.env.SKETCHFAB_API_KEY || process.env.SKETCHFAB_API_TOKEN || process.env.SKETCHFAB_TOKEN
	if (apiKey) return { type: 'service-api-key', header: `Token ${apiKey}` }
	return null
}

function sketchfabLicenseSlug(license) {
	const text = String(license?.slug || license?.label || license?.fullName || '').trim().toLowerCase()
	if (!text) return ''
	if (text === 'cc0 public domain' || text === 'public domain') return 'cc0'
	if (text === 'cc attribution' || text === 'creative commons attribution') return 'by'
	if (text.includes('noncommercial') || text.includes('non-commercial')) {
		if (text.includes('noderivs') || text.includes('no derivatives')) return 'by-nc-nd'
		if (text.includes('sharealike') || text.includes('share alike')) return 'by-nc-sa'
		return 'by-nc'
	}
	if (text.includes('noderivs') || text.includes('no derivatives')) return 'by-nd'
	if (text.includes('sharealike') || text.includes('share alike')) return 'by-sa'
	if (text.includes('free standard')) return 'free-st'
	if (text === 'standard') return 'st'
	if (text === 'editorial') return 'ed'
	return text
}

function sketchfabLicensePolicy(args = {}) {
	const policy = String(args.licensePolicy || args.rightsPolicy || 'commercial-safe').trim().toLowerCase()
	const requested = args.allowedLicenseSlugs || args.licenses || args.licenseSlugs
	if (requested) {
		const slugs = uniqueAssetStrings([Array.isArray(requested) ? requested : String(requested).split(/[,\s]+/)])
			.map(item => item.toLowerCase())
			.filter(Boolean)
		return { policy: 'custom', slugs }
	}
	if (policy === 'cc0' || policy === 'cc0-only' || policy === 'public-domain') return { policy: 'cc0-only', slugs: ['cc0'] }
	if (policy === 'commercial-with-sharealike' || policy === 'commercial-sa') return { policy: 'commercial-with-sharealike', slugs: ['cc0', 'by', 'by-sa'] }
	if (policy === 'commercial-broad' || policy === 'free-commercial-broad') return { policy: 'commercial-broad', slugs: ['cc0', 'by', 'by-sa', 'free-st'] }
	if (policy === 'any-downloadable' || policy === 'any') return { policy: 'any-downloadable', slugs: [] }
	return { policy: 'commercial-safe', slugs: ['cc0', 'by'] }
}

function sketchfabLicenseAllowed(model, args = {}) {
	const slug = sketchfabLicenseSlug(model?.license)
	if (!slug) return false
	const { slugs } = sketchfabLicensePolicy(args)
	if (slugs.length && !slugs.includes(slug)) return false
	if (SKETCHFAB_RESTRICTED_LICENSES.has(slug)) return false
	if (SKETCHFAB_NO_DERIVATIVE_LICENSES.has(slug) && args.allowNoDerivatives !== true) return false
	if (SKETCHFAB_SHAREALIKE_LICENSES.has(slug) && args.allowShareAlike !== true && !slugs.includes(slug)) return false
	if (SKETCHFAB_STANDARD_LICENSES.has(slug) && args.allowStandardLicense !== true && !slugs.includes(slug)) return false
	return SKETCHFAB_ALLOWED_LICENSES.has(slug)
		|| (args.allowShareAlike === true && SKETCHFAB_SHAREALIKE_LICENSES.has(slug))
		|| (args.allowStandardLicense === true && SKETCHFAB_STANDARD_LICENSES.has(slug))
		|| slugs.includes(slug)
}

function sketchfabModelArchive(model, preferred = 'auto') {
	const archives = model?.archives || {}
	const order = preferred && preferred !== 'auto' ? [preferred] : ['glb', 'gltf']
	for (const key of order) {
		if (archives?.[key]) return { format: key, ...archives[key] }
	}
	return null
}

function sketchfabModelSizeMiB(model, preferred = 'auto') {
	const archive = sketchfabModelArchive(model, preferred)
	return archive?.size ? Math.round((Number(archive.size) / MODEL_BYTES_PER_MIB) * 100) / 100 : null
}

function sketchfabUidFromInput(args = {}) {
	const raw = String(args.uid || args.modelUid || args.modelId || args.id || args.url || args.viewerUrl || args.sketchfabUrl || args.handle || args.sketchfabHandle || args.model || '').trim()
	if (!raw) return ''
	if (/^[a-f0-9]{32}$/i.test(raw)) return raw.toLowerCase()
	let fromHandle = raw.match(/^sketchfab:\/\/models?\/([a-f0-9]{32})(?:[/?#]|$)/i)
		|| raw.match(/^model3d:\/\/sketchfab\/([a-f0-9]{32})(?:[/?#]|$)/i)
	if (fromHandle) return fromHandle[1].toLowerCase()
	try {
		const url = new URL(raw)
		if (!/(^|\.)sketchfab\.com$/i.test(url.hostname)) return ''
		const match = url.pathname.match(/\/3d-models\/[^/?#]*-([a-f0-9]{32})(?:[/?#]|$)/i)
			|| url.pathname.match(/\/models\/([a-f0-9]{32})(?:[/?#]|$)/i)
		return match ? match[1].toLowerCase() : ''
	} catch {
		return ''
	}
}

function sketchfabTitleSlug(value, fallback = 'sketchfab-model') {
	return safeAssetHandlePart(String(value || fallback).slice(0, 80))
}

function sketchfabHandleForModel(model) {
	const uid = String(model?.uid || '').toLowerCase()
	return `model3d://sketchfab/${uid}/${sketchfabTitleSlug(model?.name)}`
}

function sketchfabCandidateHandle(uid) {
	return `sketchfab://models/${String(uid || '').toLowerCase()}`
}

function sketchfabBestThumbnail(model, preferredWidth = 720) {
	const images = Array.isArray(model?.thumbnails?.images) ? model.thumbnails.images : []
	if (!images.length) return null
	return [...images].sort((a, b) => Math.abs(Number(a.width || 0) - preferredWidth) - Math.abs(Number(b.width || 0) - preferredWidth))[0] || null
}

function sketchfabRights(model) {
	const slug = sketchfabLicenseSlug(model?.license)
	const detail = SKETCHFAB_LICENSE_DETAILS[slug] || { slug, label: model?.license?.label || slug || 'Unknown', commercialUse: sketchfabLicenseAllowed(model, { licensePolicy: 'any-downloadable', allowShareAlike: true, allowStandardLicense: true, allowNoDerivatives: true }) }
	return {
		slug,
		label: model?.license?.label || detail.label,
		fullName: model?.license?.fullName || detail.fullName,
		url: model?.license?.url || model?.license?.uri || detail.url,
		commercialAllowed: !!detail.commercialUse,
		creditRequired: detail.attributionRequired !== false,
		shareAlike: !!detail.shareAlike,
		standardTerms: !!detail.standardTerms,
	}
}

function sketchfabAttribution(model) {
	const author = model?.user?.displayName || model?.user?.username || 'Sketchfab creator'
	const title = model?.name || 'Sketchfab model'
	const url = model?.viewerUrl || `https://sketchfab.com/3d-models/${model?.uid || ''}`
	const rights = sketchfabRights(model)
	return `${title} by ${author} on Sketchfab (${rights.label || rights.slug || 'license'}): ${url}`
}

function publicSketchfabModel(model, { includeDescription = false } = {}) {
	const archive = sketchfabModelArchive(model)
	const thumbnail = sketchfabBestThumbnail(model)
	return {
		uid: model?.uid,
		id: model?.uid,
		handle: sketchfabCandidateHandle(model?.uid),
		name: model?.name,
		title: model?.name,
		viewerUrl: model?.viewerUrl,
		sketchfabUrl: model?.viewerUrl,
		embedUrl: model?.embedUrl,
		isDownloadable: !!model?.isDownloadable,
		publishedAt: model?.publishedAt,
		stats: {
			viewCount: model?.viewCount,
			likeCount: model?.likeCount,
			commentCount: model?.commentCount,
			animationCount: model?.animationCount,
			faceCount: model?.faceCount,
			vertexCount: model?.vertexCount,
		},
		user: model?.user ? {
			uid: model.user.uid,
			username: model.user.username,
			displayName: model.user.displayName,
			profileUrl: model.user.profileUrl || model.user.uri,
		} : undefined,
		rights: sketchfabRights(model),
		attribution: sketchfabAttribution(model),
		categories: Array.isArray(model?.categories) ? model.categories.map(item => item?.name || item?.slug).filter(Boolean) : [],
		keywords: Array.isArray(model?.tags) ? model.tags.map(item => item?.name || item?.slug || item).filter(Boolean).slice(0, 24) : [],
		thumbnail: thumbnail ? { url: thumbnail.url, width: thumbnail.width, height: thumbnail.height, bytes: thumbnail.size } : undefined,
		archives: model?.archives ? Object.fromEntries(Object.entries(model.archives).map(([format, item]) => [format, {
			format,
			sizeMiB: item?.size ? Math.round((Number(item.size) / MODEL_BYTES_PER_MIB) * 100) / 100 : undefined,
			textureCount: item?.textureCount,
			textureMaxResolution: item?.textureMaxResolution,
			faceCount: item?.faceCount,
			vertexCount: item?.vertexCount,
		}])) : undefined,
		preferredArchive: archive ? {
			format: archive.format,
			sizeMiB: archive.size ? Math.round((Number(archive.size) / MODEL_BYTES_PER_MIB) * 100) / 100 : undefined,
			sizeTier: archive.size ? modelSizeTier(Number(archive.size)) : undefined,
		} : undefined,
		...(includeDescription && model?.description ? { description: String(model.description).slice(0, 2000) } : {}),
	}
}

async function sketchfabFetchJson(url, auth = null, { timeoutMs = 30000, maxBytes = 2 * 1024 * 1024 } = {}) {
	const res = await safeFetchToBuffer(url, {
		timeoutMs,
		maxBytes,
		headers: {
			Accept: 'application/json',
			...(auth?.header ? { Authorization: auth.header } : {}),
		},
	})
	let body
	try { body = JSON.parse(res.buffer.toString('utf8')) }
	catch { body = { raw: res.buffer.toString('utf8').slice(0, 1000) } }
	return { ok: res.ok, status: res.status, statusText: res.statusText, body }
}

function sketchfabMaxModelMiB(args = {}) {
	const explicit = Number(args.maxModelSizeMb ?? args.maxArchiveSizeMb ?? args.maxSizeMb)
	if (Number.isFinite(explicit) && explicit > 0) return explicit
	return MODEL_SIZE_POLICY_LIMITS_MB[normalizeModelSizePolicy(args.sizePolicy)] || MODEL_SIZE_POLICY_LIMITS_MB.standard
}

function sketchfabSearchUrl(args = {}, count = 24) {
	const q = String(args.q || args.query || args.search || args.name || '').trim()
	const url = new URL(`${SKETCHFAB_API_ROOT}/search`)
	url.searchParams.set('type', 'models')
	if (q) url.searchParams.set('q', q)
	url.searchParams.set('downloadable', args.downloadable === false ? 'false' : 'true')
	url.searchParams.set('count', String(Math.max(1, Math.min(100, count))))
	const cursor = args.cursor || args.pageCursor
	if (cursor) url.searchParams.set('cursor', String(cursor))
	const { slugs } = sketchfabLicensePolicy(args)
	if (slugs.length) url.searchParams.set('licenses', slugs.join(','))
	if (args.categories) url.searchParams.set('categories', Array.isArray(args.categories) ? args.categories.join(',') : String(args.categories))
	const tags = args.tags ?? args.keywords
	if (tags) url.searchParams.set('tags', Array.isArray(tags) ? tags.join(',') : String(tags))
	if (args.animated !== undefined) url.searchParams.set('animated', args.animated ? 'true' : 'false')
	if (args.staffpicked !== undefined) url.searchParams.set('staffpicked', args.staffpicked ? 'true' : 'false')
	if (args.sortBy || args.sort_by) url.searchParams.set('sort_by', String(args.sortBy || args.sort_by))
	return url.href
}

function filterSketchfabModels(models, args = {}) {
	const maxMiB = sketchfabMaxModelMiB(args)
	const maxBytes = Number.isFinite(maxMiB) ? maxMiB * MODEL_BYTES_PER_MIB : Number.POSITIVE_INFINITY
	const preferredFormat = String(args.format || 'auto').toLowerCase()
	const commercialUseOnly = args.commercialUseOnly !== false
	let excludedByLicense = 0
	let excludedBySize = 0
	let excludedByDownloadable = 0
	let excludedByAge = 0
	const results = []
	for (const model of models || []) {
		if (args.downloadable !== false && model?.isDownloadable !== true) {
			excludedByDownloadable += 1
			continue
		}
		if (args.excludeAgeRestricted !== false && model?.isAgeRestricted === true) {
			excludedByAge += 1
			continue
		}
		if (commercialUseOnly && !sketchfabLicenseAllowed(model, args)) {
			excludedByLicense += 1
			continue
		}
		const archive = sketchfabModelArchive(model, preferredFormat)
		if (archive?.size && Number(archive.size) > maxBytes) {
			excludedBySize += 1
			continue
		}
		results.push(model)
	}
	return { results, excludedByLicense, excludedBySize, excludedByDownloadable, excludedByAge, maxModelSizeMb: Number.isFinite(maxMiB) ? maxMiB : null }
}

async function findSketchfabModelFromArgs(args = {}) {
	const uid = sketchfabUidFromInput(args)
	if (uid) {
		const modelResult = await sketchfabFetchJson(`${SKETCHFAB_API_ROOT}/models/${uid}`, sketchfabAuthFromEnv(), { timeoutMs: Number(args.timeoutMs || 30000) })
		if (!modelResult.ok) {
			const err = new Error(`Sketchfab model lookup failed with HTTP ${modelResult.status}.`)
			err.code = 'SKETCHFAB_MODEL_LOOKUP_FAILED'
			err.details = { status: modelResult.status, message: modelResult.body?.detail || modelResult.body?.error }
			throw err
		}
		return modelResult.body
	}
	const query = String(args.query || args.q || args.name || '').trim()
	if (!query) {
		const err = new Error('Provide a Sketchfab uid, model URL, sketchfab:// handle, or query/name.')
		err.code = 'SKETCHFAB_MODEL_REQUIRED'
		throw err
	}
	const searchResult = await runSketchfabSearch({ ...args, query, maxResults: Math.max(1, Number(args.searchLimit || 12)) })
	if (!searchResult.results.length) {
		const err = new Error('No matching Sketchfab model passed the current license and size policy.')
		err.code = 'SKETCHFAB_NO_MATCH'
		err.details = { query, sizePolicy: searchResult.sizePolicy, licensePolicy: searchResult.licensePolicy }
		throw err
	}
	const requestedName = String(args.name || '').trim().toLowerCase()
	if (requestedName) {
		return searchResult._models.find(item => String(item.name || '').trim().toLowerCase() === requestedName) || searchResult._models[0]
	}
	return searchResult._models[0]
}

async function sha256Path(filePath) {
	const buffer = await fs.readFile(filePath)
	return crypto.createHash('sha256').update(buffer).digest('hex')
}

function safeSketchfabFileStem(model) {
	return `${sketchfabTitleSlug(model?.name)}-${String(model?.uid || '').toLowerCase()}`
}

async function writeBufferFile(filePath, buffer) {
	await fs.mkdir(path.dirname(filePath), { recursive: true })
	await fs.writeFile(filePath, buffer)
	return filePath
}

async function extractSketchfabZip(zipPath, outDir) {
	const zip = await JSZip.loadAsync(await fs.readFile(zipPath))
	const entries = []
	await fs.mkdir(outDir, { recursive: true })
	for (const [name, entry] of Object.entries(zip.files)) {
		const normalized = String(name || '').replace(/\\/g, '/').replace(/^\/+/, '')
		if (!normalized || normalized.includes('\0')) continue
		const target = path.resolve(outDir, normalized)
		const relative = path.relative(outDir, target)
		if (relative.startsWith('..') || path.isAbsolute(relative)) {
			throw new Error(`Refusing unsafe Sketchfab archive entry: ${name}`)
		}
		if (entry.dir) {
			await fs.mkdir(target, { recursive: true })
			continue
		}
		await fs.mkdir(path.dirname(target), { recursive: true })
		await fs.writeFile(target, await entry.async('nodebuffer'))
		entries.push(normalized)
	}
	return entries
}

async function findFirstModelFile(rootDir) {
	const files = []
	async function walk(dir) {
		const entries = await fs.readdir(dir, { withFileTypes: true })
		for (const entry of entries) {
			const full = path.join(dir, entry.name)
			if (entry.isDirectory()) await walk(full)
			else if (/\.(glb|gltf)$/i.test(entry.name)) files.push(full)
		}
	}
	await walk(rootDir)
	files.sort((a, b) => {
		const ae = path.extname(a).toLowerCase()
		const be = path.extname(b).toLowerCase()
		if (ae !== be) return ae === '.glb' ? -1 : 1
		const as = path.basename(a).toLowerCase() === 'scene.gltf' ? 0 : 1
		const bs = path.basename(b).toLowerCase() === 'scene.gltf' ? 0 : 1
		return as - bs || a.localeCompare(b)
	})
	return files[0] || null
}

async function convertSketchfabGltfToGlb(gltfPath, glbPath) {
	const [{ NodeIO }, { ALL_EXTENSIONS }] = await Promise.all([
		import('@gltf-transform/core'),
		import('@gltf-transform/extensions'),
	])
	const io = new NodeIO().registerExtensions(ALL_EXTENSIONS)
	const document = await io.read(gltfPath)
	await fs.mkdir(path.dirname(glbPath), { recursive: true })
	await io.write(glbPath, document)
	return glbPath
}

async function maybeDownloadSketchfabThumbnail(model, outDir, timeoutMs = 30000) {
	const thumbnail = sketchfabBestThumbnail(model)
	if (!thumbnail?.url) return null
	try {
		const fetched = await safeFetchToBuffer(thumbnail.url, { maxBytes: 3 * 1024 * 1024, timeoutMs, requireImage: true })
		if (!fetched.ok) return null
		const ext = String(fetched.headers?.['content-type'] || '').toLowerCase().includes('png') ? 'png' : 'jpg'
		const filePath = path.join(outDir, `poster.${ext}`)
		await writeBufferFile(filePath, fetched.buffer)
		return filePath
	} catch {
		return null
	}
}

function readSketchfabManifest() {
	return readJsonFileSync(sketchfabManifestPath(), { source: SKETCHFAB_SOURCE, assets: [] })
}

async function writeSketchfabManifest(manifest) {
	const filePath = sketchfabManifestPath()
	await fs.mkdir(path.dirname(filePath), { recursive: true })
	await fs.writeFile(filePath, `${JSON.stringify({ ...manifest, updatedAt: new Date().toISOString() }, null, 2)}\n`, 'utf8')
}

async function upsertSketchfabManifestAsset(asset) {
	const manifest = readSketchfabManifest()
	const assets = Array.isArray(manifest.assets) ? manifest.assets : []
	const index = assets.findIndex(item => item.uid === asset.uid || item.handle === asset.handle)
	if (index >= 0) assets[index] = { ...assets[index], ...asset }
	else assets.push(asset)
	await writeSketchfabManifest({
		...manifest,
		source: SKETCHFAB_SOURCE,
		provider: 'Sketchfab',
		generatedAt: manifest.generatedAt || new Date().toISOString(),
		assets,
	})
	invalidateUnifiedAssetCatalog()
}

function publicSketchfabImportedAsset(asset, full = false) {
	const base = {
		handle: asset.handle,
		modelAsset: asset.handle,
		addModel3DOptions: { modelAsset: asset.handle, nativeOnly: true },
		uid: asset.uid,
		id: asset.uid,
		name: asset.title || asset.name,
		title: asset.title || asset.name,
		source: SKETCHFAB_SOURCE,
		sourceLabel: 'Sketchfab',
		sourceUrl: asset.sourceUrl,
		viewerUrl: asset.sourceUrl,
		rights: asset.rights,
		attribution: asset.attribution,
		sizeMiB: asset.sizeMiB,
		sizeTier: asset.sizeTier,
		sha256: full ? asset.sha256 : undefined,
		importedAt: asset.importedAt,
	}
	return Object.fromEntries(Object.entries(base).filter(([, value]) => value !== undefined && value !== null))
}

function buildSketchfabImportedAssets() {
	const cacheRoot = sketchfabCacheRoot()
	const manifest = readSketchfabManifest()
	if (!Array.isArray(manifest.assets)) return []
	return manifest.assets.map(asset => {
		let filePath
		try { filePath = resolveSketchfabCachePath(cacheRoot, asset.file) }
		catch { return null }
		if (!asset?.handle || !fsNode.existsSync(filePath)) return null
		let previewPath
		try { previewPath = asset.preview ? resolveSketchfabCachePath(cacheRoot, asset.preview) : undefined }
		catch { previewPath = undefined }
		const tags = uniqueAssetStrings([
			'3d', 'model', 'glb', 'sketchfab', 'live-import',
			asset.title,
			asset.uid,
			asset.rights?.slug,
			asset.categories,
			asset.keywords,
		]).map(tag => tag.toLowerCase().replace(/\s+/g, '-'))
		const item = {
			kind: 'model3d',
			source: SKETCHFAB_SOURCE,
			sourceKey: SKETCHFAB_SOURCE,
			sourceLabel: 'Sketchfab imported models',
			sourcePriority: 34,
			role: 'Imported Sketchfab model selected through live search and official Download API',
			handle: asset.handle,
			title: asset.title || asset.name,
			name: path.basename(filePath),
			sourceCategory: 'Sketchfab',
			tags,
			usage: 'Use when the locally curated catalog does not contain a semantically strong small model. Preserve the returned attribution with the generated presentation.',
			path: filePath,
			modelAsset: filePath,
			rel: relFromCwd(filePath),
			preview: previewPath && fsNode.existsSync(previewPath) ? previewPath : undefined,
			posterAsset: previewPath && fsNode.existsSync(previewPath) ? previewPath : undefined,
			addModel3DOptions: { modelAsset: filePath, nativeOnly: true },
			sourceUrl: asset.sourceUrl,
			rights: asset.rights,
			attribution: asset.attribution,
			uid: asset.uid,
			sha256: asset.sha256,
			catalog: {
				provider: 'Sketchfab',
				importedAt: asset.importedAt,
			},
			...statSummary(filePath),
		}
		item.searchText = makeCatalogSearchText(item)
		return item
	}).filter(Boolean)
}

function resolveSketchfabCachePath(root, relativePath) {
	const base = path.resolve(root)
	const target = path.resolve(base, String(relativePath || ''))
	const relative = path.relative(base, target)
	if (!relative || relative.startsWith('..') || path.isAbsolute(relative)) {
		throw new Error('Sketchfab cache manifest contains an unsafe asset reference.')
	}
	return target
}

function sketchfabRelativePath(cacheRoot, filePath) {
	return path.relative(cacheRoot, filePath).replace(/\\/g, '/')
}

function sketchfabFormatSizeMiB(item) {
	const size = Number(item?.size || item?.bytes || item?.contentLength || 0)
	return Number.isFinite(size) && size > 0 ? Math.round((size / MODEL_BYTES_PER_MIB) * 100) / 100 : undefined
}

function summarizeSketchfabDownloadFormats(payload = {}) {
	return Object.fromEntries(Object.entries(payload || {}).map(([format, item]) => [format, {
		format,
		available: !!item?.url,
		sizeMiB: sketchfabFormatSizeMiB(item),
		expiresAt: item?.expires || item?.expiresAt,
	}]))
}

function selectSketchfabDownloadFormat(payload = {}, requestedFormat = 'auto', maxBytes = Number.POSITIVE_INFINITY) {
	const requested = String(requestedFormat || 'auto').trim().toLowerCase()
	const order = requested === 'auto' ? ['glb', 'gltf'] : [requested]
	const supported = new Set(['glb', 'gltf'])
	const candidates = []
	for (const format of order) {
		const item = payload?.[format]
		if (!item?.url) continue
		const size = Number(item.size || item.bytes || item.contentLength || 0)
		candidates.push({ format, item, size: Number.isFinite(size) ? size : 0 })
	}
	if (!candidates.length && requested === 'auto') {
		for (const [format, item] of Object.entries(payload || {})) {
			if (!supported.has(String(format).toLowerCase()) || !item?.url) continue
			const size = Number(item.size || item.bytes || item.contentLength || 0)
			candidates.push({ format, item, size: Number.isFinite(size) ? size : 0 })
		}
	}
	if (requested !== 'auto' && !supported.has(requested)) {
		return { ok: false, code: 'unsupported-format', message: 'PowerPoint import currently supports Sketchfab GLB and glTF download formats.' }
	}
	if (!candidates.length) {
		return { ok: false, code: 'no-supported-format', message: 'No GLB or glTF Sketchfab download format is available for this model.' }
	}
	const oversized = []
	for (const candidate of candidates) {
		if (candidate.size > 0 && candidate.size > maxBytes) {
			oversized.push(candidate)
			continue
		}
		return { ok: true, ...candidate }
	}
	const smallest = oversized.sort((a, b) => a.size - b.size)[0]
	return {
		ok: false,
		code: 'too-large',
		message: 'Available Sketchfab download formats exceed the configured model size ceiling.',
		format: smallest?.format,
		sizeMiB: smallest?.size ? Math.round((smallest.size / MODEL_BYTES_PER_MIB) * 100) / 100 : undefined,
	}
}

function sketchfabRuntimeConfig(auth = sketchfabAuthFromEnv()) {
	return {
		authConfigured: !!auth,
		authMode: auth?.type || 'none',
		authentication: auth ? 'configured Sketchfab service API key' : 'missing Sketchfab service API key',
		cacheMode: process.env.BETTERPPTX_SKETCHFAB_CACHE_DIR ? 'configured' : (process.env.K_SERVICE ? 'cloud-run-ephemeral-default' : 'local-default'),
	}
}

async function runSketchfabSearch(args = {}) {
	const requestedLimit = Math.max(1, Math.min(50, Number(args.maxResults || args.limit || 12) || 12))
	const fetchCount = Math.max(requestedLimit, Math.min(100, requestedLimit * 4))
	const auth = sketchfabAuthFromEnv()
	const response = await sketchfabFetchJson(sketchfabSearchUrl(args, fetchCount), auth, {
		timeoutMs: Number(args.timeoutMs || 30000),
		maxBytes: 4 * 1024 * 1024,
	})
	if (!response.ok) {
		const err = new Error(`Sketchfab search failed with HTTP ${response.status}.`)
		err.code = 'SKETCHFAB_SEARCH_FAILED'
		err.details = { status: response.status, message: response.body?.detail || response.body?.error }
		throw err
	}
	const rawModels = Array.isArray(response.body?.results) ? response.body.results : []
	const filtered = filterSketchfabModels(rawModels, args)
	const models = filtered.results.slice(0, requestedLimit)
	const { policy, slugs } = sketchfabLicensePolicy(args)
	const sizePolicy = normalizeModelSizePolicy(args.sizePolicy)
	return {
		provider: 'Sketchfab',
		query: String(args.query || args.q || args.search || args.name || '').trim() || null,
		count: models.length,
		truncated: filtered.results.length > models.length || !!response.body?.next,
		next: response.body?.next || null,
		cursor: response.body?.cursors || null,
		licensePolicy: {
			policy,
			allowedLicenseSlugs: slugs.length ? slugs : null,
			commercialUseOnly: args.commercialUseOnly !== false,
		},
		sizePolicy: {
			policy: sizePolicy,
			maxModelSizeMb: filtered.maxModelSizeMb,
			excludedBySize: filtered.excludedBySize,
		},
		excluded: {
			byLicense: filtered.excludedByLicense,
			bySize: filtered.excludedBySize,
			byDownloadable: filtered.excludedByDownloadable,
			byAge: filtered.excludedByAge,
		},
		results: models.map(model => publicSketchfabModel(model, { includeDescription: args.full === true || args.format === 'full' })),
		_models: models,
	}
}

async function handleSketchfabSearch(args = {}) {
	const result = await runSketchfabSearch(args)
	const { _models, ...publicResult } = result
	return {
		...publicResult,
		usage: 'Inspect a sketchfab:// candidate when you need more details, then import it to receive a model3d:// handle for betterpptx.slide.add_model3d.',
	}
}

async function handleSketchfabInspect(args = {}) {
	const model = await findSketchfabModelFromArgs(args)
	const result = {
		provider: 'Sketchfab',
		model: publicSketchfabModel(model, { includeDescription: args.includeDescription !== false }),
		runtime: sketchfabRuntimeConfig(),
	}
	if (args.inspectDownload === true || args.includeDownload === true || args.download === true) {
		const auth = sketchfabAuthFromEnv()
		if (!auth) {
			result.download = {
				status: 'auth-required',
				message: 'Sketchfab download inspection requires the installed Sketchfab service API key.',
			}
		} else {
			const download = await sketchfabFetchJson(`${SKETCHFAB_API_ROOT}/models/${model.uid}/download`, auth, {
				timeoutMs: Number(args.timeoutMs || 30000),
				maxBytes: 1024 * 1024,
			})
			result.download = download.ok
				? { status: 'available', formats: summarizeSketchfabDownloadFormats(download.body) }
				: { status: 'unavailable', httpStatus: download.status, message: download.body?.detail || download.body?.error || download.statusText }
		}
	}
	return result
}

async function handleSketchfabImport(args = {}) {
	const model = await findSketchfabModelFromArgs(args)
	const maxMiB = sketchfabMaxModelMiB(args)
	const maxBytes = Number.isFinite(maxMiB) ? Math.floor(maxMiB * MODEL_BYTES_PER_MIB) : Number.POSITIVE_INFINITY
	const publicModel = publicSketchfabModel(model, { includeDescription: args.includeDescription === true })
	const cacheRoot = sketchfabCacheRoot()
	const manifest = readSketchfabManifest()
	const existing = (Array.isArray(manifest.assets) ? manifest.assets : []).find(asset => asset.uid === model.uid || asset.handle === sketchfabHandleForModel(model))
	if (existing && args.refresh !== true) {
		try {
			const existingPath = resolveSketchfabCachePath(cacheRoot, existing.file)
			if (fsNode.existsSync(existingPath)) {
				return {
					status: 'available',
					provider: 'Sketchfab',
					model: publicModel,
					asset: publicSketchfabImportedAsset(existing, true),
					runtime: sketchfabRuntimeConfig(),
					message: 'Model was already imported; returning the existing model3d handle.',
				}
			}
		} catch (_) {}
	}
	if (model?.isDownloadable !== true) {
		return {
			status: 'not-downloadable',
			provider: 'Sketchfab',
			model: publicModel,
			message: 'This Sketchfab model is not marked downloadable by Sketchfab.',
		}
	}
	if (args.commercialUseOnly !== false && !sketchfabLicenseAllowed(model, args)) {
		return {
			status: 'blocked-by-rights',
			provider: 'Sketchfab',
			model: publicModel,
			licensePolicy: sketchfabLicensePolicy(args),
			message: 'This model does not match the requested commercial-use license policy.',
		}
	}
	const archive = sketchfabModelArchive(model, args.format || args.downloadFormat || 'auto')
	if (archive?.size && Number(archive.size) > maxBytes) {
		return {
			status: 'too-large',
			provider: 'Sketchfab',
			model: publicModel,
			sizePolicy: { policy: normalizeModelSizePolicy(args.sizePolicy), maxModelSizeMb: maxMiB },
			message: 'This model exceeds the configured model size ceiling before download.',
		}
	}
	const auth = sketchfabAuthFromEnv()
	if (!auth) {
		return {
			status: 'auth-required',
			provider: 'Sketchfab',
			model: publicModel,
			runtime: sketchfabRuntimeConfig(auth),
			cloudRun: {
				authentication: 'Configure the Sketchfab API key once as a Cloud Run secret.',
				note: 'Search and metadata inspection work without the key; imports use the installed service API key.',
			},
		}
	}
	const download = await sketchfabFetchJson(`${SKETCHFAB_API_ROOT}/models/${model.uid}/download`, auth, {
		timeoutMs: Number(args.timeoutMs || 30000),
		maxBytes: 1024 * 1024,
	})
	if (!download.ok) {
		return {
			status: 'download-request-failed',
			provider: 'Sketchfab',
			model: publicModel,
			httpStatus: download.status,
			message: download.body?.detail || download.body?.error || download.statusText,
		}
	}
	const selected = selectSketchfabDownloadFormat(download.body, args.downloadFormat || args.format || 'auto', maxBytes)
	if (!selected.ok) {
		return {
			status: selected.code,
			provider: 'Sketchfab',
			model: publicModel,
			download: { formats: summarizeSketchfabDownloadFormats(download.body) },
			sizePolicy: { policy: normalizeModelSizePolicy(args.sizePolicy), maxModelSizeMb: maxMiB },
			message: selected.message,
		}
	}
	const assetDir = path.join(cacheRoot, 'models', String(model.uid || '').toLowerCase())
	const downloadsDir = path.join(assetDir, 'downloads')
	const extractedDir = path.join(assetDir, 'extracted')
	const stem = safeSketchfabFileStem(model)
	const finalGlbPath = path.join(assetDir, `${stem}.glb`)
	await fs.mkdir(assetDir, { recursive: true })
	const fetched = await safeFetchToBuffer(selected.item.url, {
		timeoutMs: Number(args.downloadTimeoutMs || args.timeoutMs || 120000),
		maxBytes,
	})
	if (!fetched.ok) {
		return {
			status: 'download-failed',
			provider: 'Sketchfab',
			model: publicModel,
			httpStatus: fetched.status,
			message: fetched.statusText || 'Sketchfab temporary download URL did not return successfully.',
		}
	}
	if (selected.format === 'glb') {
		await writeBufferFile(finalGlbPath, fetched.buffer)
	} else {
		const zipPath = path.join(downloadsDir, `${stem}-gltf.zip`)
		await writeBufferFile(zipPath, fetched.buffer)
		await fs.rm(extractedDir, { recursive: true, force: true })
		await extractSketchfabZip(zipPath, extractedDir)
		const modelFile = await findFirstModelFile(extractedDir)
		if (!modelFile) {
			return {
				status: 'unsupported-format',
				provider: 'Sketchfab',
				model: publicModel,
				message: 'Downloaded glTF archive did not contain a .glb or .gltf model file.',
			}
		}
		if (/\.glb$/i.test(modelFile)) await fs.copyFile(modelFile, finalGlbPath)
		else {
			if (args.convertGltf === false) {
				return {
					status: 'conversion-required',
					provider: 'Sketchfab',
					model: publicModel,
					message: 'Downloaded asset is glTF; allow conversion to GLB or request format="glb".',
				}
			}
			await convertSketchfabGltfToGlb(modelFile, finalGlbPath)
		}
	}
	const stat = await fs.stat(finalGlbPath)
	if (Number.isFinite(maxBytes) && stat.size > maxBytes) {
		return {
			status: 'too-large-after-conversion',
			provider: 'Sketchfab',
			model: publicModel,
			sizePolicy: { policy: normalizeModelSizePolicy(args.sizePolicy), maxModelSizeMb: maxMiB },
			message: 'The imported GLB exceeds the configured model size ceiling after conversion.',
		}
	}
	// SERVER/SERVICE cost only (the model content is free-licensed): the archive download +
	// extract/convert + write is the real cost — record the import bytes so the metrology fit
	// prices model3d-import as its own family instead of it being a free unmeasured egress.
	recordResourceUsage({ model3dImportBytes: Math.max(0, Number(fetched?.buffer?.length) || Number(stat.size) || 0), externalCalls: 1, storageWriteBytes: Number(stat.size) || 0 })
	const posterPath = args.downloadThumbnail === false ? null : await maybeDownloadSketchfabThumbnail(model, assetDir, Number(args.timeoutMs || 30000))
	const sha256 = await sha256Path(finalGlbPath)
	const importedAt = new Date().toISOString()
	const asset = {
		uid: String(model.uid || '').toLowerCase(),
		handle: sketchfabHandleForModel(model),
		title: model.name || 'Sketchfab model',
		name: model.name || 'Sketchfab model',
		file: sketchfabRelativePath(cacheRoot, finalGlbPath),
		preview: posterPath ? sketchfabRelativePath(cacheRoot, posterPath) : undefined,
		sourceUrl: model.viewerUrl || `https://sketchfab.com/3d-models/${model.uid}`,
		rights: sketchfabRights(model),
		attribution: sketchfabAttribution(model),
		categories: Array.isArray(model.categories) ? model.categories.map(item => item?.name || item?.slug).filter(Boolean) : [],
		keywords: Array.isArray(model.tags) ? model.tags.map(item => item?.name || item?.slug || item).filter(Boolean).slice(0, 48) : [],
		importedAt,
		selectedFormat: {
			format: selected.format,
			sizeMiB: selected.size ? Math.round((selected.size / MODEL_BYTES_PER_MIB) * 100) / 100 : undefined,
		},
		bytes: stat.size,
		sizeMiB: Math.round((stat.size / MODEL_BYTES_PER_MIB) * 100) / 100,
		sizeTier: modelSizeTier(stat.size),
		sha256,
	}
	await upsertSketchfabManifestAsset(asset)
	return {
		status: 'imported',
		provider: 'Sketchfab',
		model: publicModel,
		asset: publicSketchfabImportedAsset(asset, true),
		selectedFormat: asset.selectedFormat,
		runtime: sketchfabRuntimeConfig(auth),
		usage: 'Use asset.addModel3DOptions with betterpptx.slide.add_model3d. Keep the returned attribution in deck notes or source credits when the rights require credit.',
	}
}

function readJsonFileSync(filePath, fallback = null) {
	try { return JSON.parse(fsNode.readFileSync(filePath, 'utf8')) }
	catch { return fallback }
}

function crossPlatformBasename(filePath) {
	return path.basename(String(filePath || '').replace(/\\/g, '/'))
}

function relFromCwd(filePath) {
	return path.relative(process.cwd(), filePath).replace(/\\/g, '/')
}

function compactGlbMetadata(metadata) {
	if (!metadata || typeof metadata !== 'object') return undefined
	const out = {
		generator: metadata.asset?.generator,
		version: metadata.asset?.version,
		nodes: metadata.nodes_count,
		meshes: metadata.meshes_count,
		materials: metadata.materials_count,
		textures: metadata.textures_count,
		animations: metadata.animations_count,
		scenes: metadata.scenes_count,
		validGlbHeader: metadata.valid_glb_header,
	}
	return Object.fromEntries(Object.entries(out).filter(([, value]) => value !== undefined && value !== null))
}

function makeCatalogSearchText(item) {
	return [
		item.title,
		item.name,
		item.role,
		item.source,
		item.sourceLabel,
		item.sourceCategory,
		item.usage,
		item.license,
		item.provenance,
		item.attribution,
		item.handle,
		...(item.tags || []),
		...(item.aliases || []),
		...(item.categories || []),
		...(item.aiCollections || []).flatMap(collection => [collection.id, collection.title, collection.bestFor, ...(collection.sampleQueries || [])]),
		...(item.aiBestFor || []),
		...(item.aiSearchHints || []),
	].filter(Boolean).join(' ').toLowerCase()
}

// Source-quality + poster weighting. Semantic matchScore alone made the low-poly
// CC0 dump ("toxsam-open-source-3d") win generic queries (a flat grey "battery"
// box). Give genuine weight to high-quality sources (Khronos PBR, premium, MS
// Stock, quality tier) and to poster-backed (vettable, fallback-safe) models, and
// demote the low-poly dump so it only surfaces as a last resort.
function catalogQualitySignals(item) {
	const src = String(item.source || item.sourceFamily || '').toLowerCase()
	const poster = !!(item.posterAsset || item.preview || item.posterHandle || item.poster)
	let quality = 0
	if (/(khronos|premium|microsoft|stock3d|reference|-quality)/.test(src)) quality += 2200
	if (src === 'toxsam-open-source-3d') quality -= 5200
	return { quality, posterBonus: poster ? 900 : 0, poster, lowPoly: src === 'toxsam-open-source-3d' }
}

function scoreCatalogAsset(item, terms, queryPhrase) {
	const sig = catalogQualitySignals(item)
	if (!terms.length) {
		const titleQuality = /[a-z0-9]{2,}/i.test(String(item.title || item.name || '')) ? 6 : -20
		return { matchScore: 1, score: Number(item.sourcePriority || 0) + titleQuality + sig.quality + sig.posterBonus }
	}
	const semanticTerms = terms.filter(term => !CATALOG_GENERIC_SEARCH_TERMS.has(term))
	const scoringTerms = semanticTerms.length ? semanticTerms : terms
	const title = String(item.title || item.name || '').toLowerCase()
	const category = String(item.sourceCategory || '').toLowerCase()
	const tags = (item.tags || []).map(tag => String(tag).toLowerCase())
	const aliases = (item.aliases || []).map(alias => String(alias).toLowerCase())
	const haystack = item.searchText || makeCatalogSearchText(item)
	let matchScore = 0
	if (queryPhrase && title.includes(queryPhrase)) matchScore += 120
	if (queryPhrase && aliases.some(alias => alias.includes(queryPhrase))) matchScore += 90
	if (queryPhrase && tags.some(tag => tag.includes(queryPhrase))) matchScore += 70
	// Preserve the author's strongest semantic phrase even when the query also carries
	// audience/use-case words (for example, "solar system classroom model"). A full
	// query-string match is intentionally rare, so without this bridge a generic
	// intent expansion (science/education) can outrank the exact domain object.
	// Prefer the longest contiguous title/alias phrase of two or more query tokens;
	// this remains semantic selection, not a client-authored asset handle.
	const queryTokens = assetQueryTerms(queryPhrase)
	for (let size = Math.min(4, queryTokens.length); size >= 2; size -= 1) {
		let phraseMatched = false
		for (let start = 0; start + size <= queryTokens.length; start += 1) {
			const phrase = queryTokens.slice(start, start + size).join(' ')
			if (!phrase) continue
			if (title.includes(phrase)) {
				matchScore += size >= 3 ? 260 : 190
				phraseMatched = true
				break
			}
			if (aliases.some(alias => alias.includes(phrase))) {
				matchScore += size >= 3 ? 210 : 150
				phraseMatched = true
				break
			}
		}
		if (phraseMatched) break
	}
	for (const term of scoringTerms) {
		if (title === term) matchScore += 100
		else if (title.split(/\s+/).includes(term)) matchScore += 70
		else if (title.includes(term)) matchScore += 45
		if (category.includes(term)) matchScore += 34
		if (aliases.some(alias => alias.includes(term))) matchScore += 30
		if (tags.some(tag => tag === term)) matchScore += 28
		else if (tags.some(tag => tag.includes(term))) matchScore += 18
		if (haystack.includes(term)) matchScore += 8
	}
	return { matchScore, score: matchScore * 100 + Number(item.sourcePriority || 0) + sig.quality + sig.posterBonus }
}

function buildMicrosoftStock3DAssets() {
	const libraryDir = path.resolve(ASSETS_ROOT, 'outputs', 'microsoft_stock3d_library')
	const recordsDir = path.join(libraryDir, 'records')
	const localGlbDir = path.join(libraryDir, 'glb')
	let recordFiles = []
	try {
		recordFiles = fsNode.readdirSync(recordsDir)
	} catch {
		return []
	}
	const bySha = new Map()
	recordFiles = recordFiles
		.filter(file => file.toLowerCase().endsWith('.json'))
		.sort((a, b) => a.localeCompare(b))
	for (const file of recordFiles) {
		const rows = readJsonFileSync(path.join(recordsDir, file), [])
		if (!Array.isArray(rows)) continue
		for (const record of rows) {
			// Records store the absolute glb path from the capture machine (e.g.
			// C:\MyDoc\...), which won't exist here. Resolve to the local glb dir by
			// basename; otherwise the whole Microsoft Stock 3D library is dropped and
			// the picker falls back to low-poly sources.
			const rawGlb = String(record?.glb || '')
			const localGlb = rawGlb ? path.join(localGlbDir, crossPlatformBasename(rawGlb)) : ''
			const glbPath = localGlb && fsNode.existsSync(localGlb) ? localGlb : path.resolve(rawGlb)
			if (!record?.title || !fsNode.existsSync(glbPath)) continue
			const sha = String(record.sha256 || '').trim()
			const key = sha || glbPath.toLowerCase()
			const aiCollections = classifyMicrosoftStock3DRecord(record)
			const tags = uniqueAssetStrings([
				'3d', 'model', 'glb', 'microsoft', 'powerpoint', 'office', 'stock', 'native-powerpoint', 'flagship',
				record?.category,
				record?.category_slug,
				record?.title,
				record?.tags?.tokens,
				record?.tags?.navigation_tags,
				record?.tags?.colors,
				record?.tags?.animated ? ['animated', 'motion'] : ['static'],
				record?.glb_metadata?.nodes_names,
				aiCollections.flatMap(collection => ['intent', collection.id, collection.title]),
			]).map(tag => tag.toLowerCase().replace(/\s+/g, '-'))
			const current = bySha.get(key)
			const category = String(record.category || record.category_slug || 'Microsoft Stock 3D')
			const title = String(record.title)
			if (current) {
				current.categories = uniqueAssetStrings([current.categories, category])
				current.aliases = uniqueAssetStrings([current.aliases, title])
				current.tags = uniqueAssetStrings([current.tags, tags])
				current.aiCollections = mergeAiCollections(current.aiCollections, aiCollections)
				current.aiBestFor = uniqueAssetStrings([current.aiBestFor, current.aiCollections.map(collection => collection.bestFor)]).slice(0, 6)
				current.aiSearchHints = uniqueAssetStrings([current.aiSearchHints, current.aiCollections.flatMap(collection => collection.sampleQueries || [])]).slice(0, 12)
				current.duplicateCount += 1
				current.rawRecordCount += 1
				current.alsoAppearsIn = current.categories.filter(item => item !== current.sourceCategory)
				current.searchText = makeCatalogSearchText(current)
				continue
			}
			const titleSlug = safeAssetHandlePart(record.title_slug || title)
			const shaPart = sha ? sha.slice(0, 16) : safeAssetHandlePart(path.basename(glbPath, '.glb'))
			const item = {
				kind: 'model3d',
				source: MICROSOFT_STOCK3D_SOURCE,
				sourceKey: MICROSOFT_STOCK3D_SOURCE,
				sourceLabel: 'Microsoft PowerPoint Stock 3D',
				sourcePriority: 100,
				role: 'Flagship native Microsoft PowerPoint Stock 3D model',
				handle: `model3d://microsoft-stock/${shaPart}/${titleSlug}`,
				title,
				name: `${title}.glb`,
				sourceCategory: category,
				categories: [category],
				aliases: [title],
				tags,
				aiCollections,
				aiBestFor: aiCollections.map(collection => collection.bestFor).slice(0, 6),
				aiSearchHints: uniqueAssetStrings(aiCollections.flatMap(collection => collection.sampleQueries || [])).slice(0, 12),
				usage: `Primary choice for native PowerPoint 3D: use for ${category.toLowerCase()} scenes, quick visual embellishment, and presentation-native model3d objects when the topic matches "${title}".`,
				license: String(record.license_scope_note || 'Cached for reuse inside Microsoft 365/PowerPoint files.'),
				provenance: String(record.provenance || 'Inserted via PowerPoint Microsoft Stock 3D Models picker, then extracted from PPTX package.'),
				nativePowerPointStock: true,
				officeUseOnly: record.office_use_only !== false,
				animated: !!record?.tags?.animated || Number(record?.glb_metadata?.animations_count || 0) > 0,
				path: glbPath,
				modelAsset: glbPath,
				rel: relFromCwd(glbPath),
				addModel3DOptions: { modelAsset: glbPath, nativeOnly: true },
				sha256: sha || undefined,
				dedupeKey: key,
				duplicateCount: 1,
				rawRecordCount: 1,
				bytes: Number(record.bytes || statSummary(glbPath).bytes || 0),
				glb: compactGlbMetadata(record.glb_metadata),
				catalog: {
					resultIndex: record.catalog_result_index,
					visibleResultCount: record.visible_result_count,
					app: record.catalog_context?.app,
					build: record.catalog_context?.build,
					market: record.catalog_context?.mkt,
				},
				...statSummary(glbPath),
			}
			item.searchText = makeCatalogSearchText(item)
			bySha.set(key, item)
		}
	}
	return [...bySha.values()]
}

function buildIconScoutAssets() {
	const root = path.resolve(ASSETS_ROOT, 'demos', 'betterpptx-private-assets', 'iconscout')
	const manifest = readJsonFileSync(path.join(root, 'manifest.json'), null)
	if (!Array.isArray(manifest?.assets)) return []
	const vendor = manifest.vendor || 'iconscout'
	return manifest.assets.map(asset => {
		const filePath = path.resolve(root, String(asset.file || ''))
		if (!asset?.handle || !fsNode.existsSync(filePath)) return null
		const isModel = asset.category === 'models3d' || String(asset.format || '').toLowerCase() === 'glb'
		const title = String(asset.title || asset.name || titleFromAssetPath(asset.file || asset.handle, 'IconScout asset'))
		const previewPath = asset.preview ? path.resolve(root, String(asset.preview)) : undefined
		const tags = uniqueAssetStrings([
			isModel ? ['3d', 'model', 'glb'] : ['icon', 'image', 'png'],
			'iconscout',
			'private',
			asset.asset,
			asset.format,
			asset.tags,
			title,
		]).map(tag => tag.toLowerCase().replace(/\s+/g, '-'))
		const item = {
			kind: isModel ? 'model3d' : 'icon',
			source: ICONSCOUT_SOURCE,
			sourceKey: ICONSCOUT_SOURCE,
			sourceLabel: 'Private IconScout cache',
			sourcePriority: isModel ? 82 : 78,
			role: isModel ? 'Private IconScout quick-embellishment 3D model' : 'Private IconScout navigation and embellishment icon',
			handle: String(asset.handle),
			title,
			name: path.basename(filePath),
			sourceCategory: isModel ? 'IconScout 3D' : 'IconScout icons',
			tags,
			usage: String(asset.usage || 'Use for quick navigation, UI metaphor, and visual embellishment when the semantic tags match the slide content. Verify item-level rights before redistribution.'),
			license: String(asset.license || 'IconScout asset license. Verify item-level rights before redistribution.'),
			provenance: `${vendor} local private cache`,
			sourceUrl: asset.sourceUrl || undefined,
			privateAsset: true,
			path: filePath,
			rel: relFromCwd(filePath),
			preview: previewPath && fsNode.existsSync(previewPath) ? previewPath : undefined,
			...(isModel ? {
				modelAsset: filePath,
				addModel3DOptions: { modelAsset: filePath, nativeOnly: true },
			} : {
				imageAsset: filePath,
				addImageOptions: { path: filePath },
			}),
			...statSummary(filePath),
		}
		item.searchText = makeCatalogSearchText(item)
		return item
	}).filter(Boolean)
}

function buildToxSamAssets() {
	const root = path.resolve(ASSETS_ROOT, 'demos', 'betterpptx-online-assets')
	const manifest = readJsonFileSync(path.join(root, 'manifest.json'), null)
	if (!Array.isArray(manifest?.assets)) return []
	return manifest.assets.map(asset => {
		const sourceKey = String(asset.sourceKey || '')
		if (![OPEN_SOURCE_3D_SOURCE_KEY, OPEN_SOURCE_3D_QUALITY_SOURCE_KEY].includes(sourceKey)) return null
		if (asset.category !== 'models3d' || !asset.file) return null
		const filePath = path.resolve(root, String(asset.file))
		if (!fsNode.existsSync(filePath)) return null
		const previewPath = asset.preview ? path.resolve(root, String(asset.preview)) : undefined
		const isQuality = sourceKey === OPEN_SOURCE_3D_QUALITY_SOURCE_KEY
		const title = String(asset.upstreamAssetName || asset.title || asset.altText || titleFromAssetPath(asset.file, 'ToxSam open-source model'))
		const source = isQuality ? TOXSAM_QUALITY_SOURCE : TOXSAM_SOURCE
		const tags = uniqueAssetStrings([
			'3d', 'model', 'glb', 'cc0', 'open-source', 'toxsam', 'polygonal-mind',
			isQuality ? ['presentation-optimized', 'quality'] : [],
			asset.projectName,
			asset.projectId,
			asset.tags,
			title,
		]).map(tag => tag.toLowerCase().replace(/\s+/g, '-'))
		const item = {
			kind: 'model3d',
			source,
			sourceFamily: TOXSAM_SOURCE,
			sourceKey: source,
			sourceLabel: isQuality ? 'ToxSam open-source 3D quality derivative' : 'ToxSam open-source 3D assets',
			sourcePriority: isQuality ? 58 : 46,
			role: isQuality ? 'Presentation-optimized CC0 contextual 3D model' : 'Relevant CC0 contextual 3D model',
			handle: String(asset.handle || `model3d://open-3d/${safeAssetHandlePart(asset.projectId || 'project')}/${safeAssetHandlePart(title)}`),
			title,
			name: path.basename(filePath),
			sourceCategory: String(asset.projectName || asset.projectId || 'ToxSam open-source 3D'),
			tags,
			usage: String(asset.usage || 'Use when Microsoft Stock 3D and IconScout do not provide a relevant object, or when a CC0 contextual/environment model is useful.'),
			license: String(asset.license || 'CC0'),
			provenance: 'Mirrored from toxsam/open-source-3D-assets and related CC0 repositories.',
			sourceUrl: asset.sourceUrl || undefined,
			attribution: asset.attribution || 'Polygonal Mind',
			cc0: String(asset.license || '').toUpperCase() === 'CC0',
			path: filePath,
			modelAsset: filePath,
			rel: relFromCwd(filePath),
			preview: previewPath && fsNode.existsSync(previewPath) ? previewPath : undefined,
			posterAsset: previewPath && fsNode.existsSync(previewPath) ? previewPath : undefined,
			addModel3DOptions: {
				modelAsset: filePath,
				...(previewPath && fsNode.existsSync(previewPath) ? { posterAsset: previewPath } : { nativeOnly: true }),
			},
			project: {
				id: asset.projectId || undefined,
				name: asset.projectName || undefined,
			},
			...statSummary(filePath),
		}
		item.searchText = makeCatalogSearchText(item)
		return item
	}).filter(Boolean)
}

function agencyReferenceRoot() {
	return path.resolve(ASSETS_ROOT, 'demos', 'betterpptx-reference-assets', '3d-gradient-style-agency')
}

function agencyShapeSceneRoot() {
	return path.join(agencyReferenceRoot(), 'shape-scenes')
}

function cloneJson(value) {
	return value == null ? value : JSON.parse(JSON.stringify(value))
}

function agencySceneSlideNumber(scene, fileName = '') {
	const text = [scene?.handle, scene?.title, fileName].filter(Boolean).join(' ')
	const match = text.match(/slide[-\s_]*(\d+)/i)
	return match ? Number(match[1]) : null
}

function buildShapeSceneItem(filePath, source) {
	const scene = readJsonFileSync(filePath, null)
	const fileName = path.basename(filePath)
	const title = String(scene?.title || titleFromAssetPath(fileName, 'Reference shape scene'))
	const handle = String(scene?.handle || `shapeScene://reference/${safeAssetHandlePart(path.basename(fileName, path.extname(fileName)))}`)
	const tags = uniqueAssetStrings([
		source.source,
		source.kind,
		source.role,
		title,
		scene?.tags,
		scene?.counts?.customGeometry ? ['customGeometry', 'custom-shape-library'] : [],
	]).map(tag => tag.toLowerCase().replace(/\s+/g, '-'))
	const item = {
		kind: 'shapeScene',
		role: source.role,
		source: source.source,
		sourceKey: source.source,
		sourceLabel: source.sourceLabel,
		sourcePriority: source.sourcePriority,
		handle,
		title,
		name: fileName,
		sourceCategory: source.sourceLabel,
		tags,
		usage: String(scene?.recommendedUse || 'Use as a reference custom-geometry scene, or inspect its editable custom-shape specimens before inserting individual shapes.'),
		path: filePath,
		rel: relFromCwd(filePath),
		shapeScene: {
			handle,
			slideNumber: agencySceneSlideNumber(scene, fileName),
			counts: scene?.counts || {},
			specimenCount: Array.isArray(scene?.expressiveSpecimens) ? scene.expressiveSpecimens.length : 0,
			preview: scene?.preview,
		},
		...statSummary(filePath),
	}
	item.searchText = makeCatalogSearchText(item)
	return item
}

function customShapeHandle(scene, specimen, specimenIndex, fileName = '') {
	const slideNumber = agencySceneSlideNumber(scene, fileName)
	const scenePart = slideNumber ? `agency-slide-${String(slideNumber).padStart(2, '0')}` : safeAssetHandlePart(scene?.handle || fileName, 'agency-scene')
	const specimenPart = safeAssetHandlePart(specimen?.sourceName || specimen?.name || `shape-${specimenIndex + 1}`, `shape-${specimenIndex + 1}`)
	return `customShape://agency/${scenePart}/${specimenPart}`
}

function buildCustomShapeAssets() {
	const root = agencyShapeSceneRoot()
	let files = []
	try {
		files = fsNode.readdirSync(root)
			.filter(name => /\.json$/i.test(name))
			.sort()
	} catch {
		return []
	}
	const assets = []
	for (const fileName of files) {
		const filePath = path.join(root, fileName)
		const scene = readJsonFileSync(filePath, null)
		const specimens = Array.isArray(scene?.expressiveSpecimens) ? scene.expressiveSpecimens : []
		const slideNumber = agencySceneSlideNumber(scene, fileName)
		for (let index = 0; index < specimens.length; index++) {
			const specimen = specimens[index]
			const object = specimen?.object
			if (!object || object.shapeType !== 'custGeom' || !Array.isArray(object.points) || object.points.length === 0) continue
			const handle = customShapeHandle(scene, specimen, index, fileName)
			const title = String(specimen.sourceName || specimen.name || `Agency custom shape ${index + 1}`)
			const tags = uniqueAssetStrings([
				'customGeometry',
				'customShape',
				'freeform',
				'editable',
				'agency-reference',
				scene?.tags,
				title,
				specimen.name,
				specimen.sourceName,
				slideNumber ? `slide-${String(slideNumber).padStart(2, '0')}` : [],
				object.fill?.color ? `fill-${object.fill.color}` : [],
				object.line?.color ? `line-${object.line.color}` : [],
			]).map(tag => tag.toLowerCase().replace(/\s+/g, '-'))
			const item = {
				kind: 'customShape',
				role: 'Editable reference custom geometry specimen',
				source: 'reference',
				sourceKey: 'reference',
				sourceLabel: 'Reference custom geometry specimens',
				sourcePriority: 64,
				handle,
				title,
				name: String(specimen.name || title),
				sourceCategory: 'Custom geometry',
				tags,
				usage: 'Insert with betterpptx.custom_geometry.insert, then pass options for any supported ShapeProps tweak; x/y/w/h rescale the stored path, or pass points to replace the path.',
				path: filePath,
				rel: relFromCwd(filePath),
				sceneHandle: String(scene?.handle || ''),
				sceneTitle: String(scene?.title || ''),
				slideNumber,
				specimenIndex: index,
				sourceName: specimen.sourceName ? String(specimen.sourceName) : undefined,
				pointCount: Number(specimen.pointCount || object.points.length || 0),
				area: Number(specimen.area || (Number(object.w || 0) * Number(object.h || 0)) || 0),
				object: cloneJson(object),
				customGeometry: {
					handle,
					sceneHandle: String(scene?.handle || ''),
					slideNumber,
					specimenIndex: index,
					sourceName: specimen.sourceName ? String(specimen.sourceName) : undefined,
					pointCount: Number(specimen.pointCount || object.points.length || 0),
					defaultBox: { x: object.x, y: object.y, w: object.w, h: object.h },
					defaultFill: object.fill,
					defaultLine: object.line,
				},
				...statSummary(filePath),
			}
			item.searchText = makeCatalogSearchText(item)
			assets.push(item)
		}
	}
	return assets
}

function publicCustomShapeHandle(handle) {
	const digest = crypto.createHash('sha256').update(String(handle || '')).digest('hex').slice(0, 32)
	return `customShape://public/${digest}`
}

function publicShapeSceneHandle(handle) {
	const digest = crypto.createHash('sha256').update(String(handle || '')).digest('hex').slice(0, 32)
	return `shapeScene://public/${digest}`
}

function resolvePublicShapeSceneHandle(handle) {
	const wanted = String(handle || '').trim()
	if (!wanted.startsWith('shapeScene://public/')) return wanted
	return buildCustomShapeAssets().find(item => publicShapeSceneHandle(item.sceneHandle) === wanted)?.sceneHandle || wanted
}

function findCustomShapeAsset(handle) {
	const wanted = String(handle || '').trim()
	if (!wanted) return null
	return buildCustomShapeAssets().find(item => item.handle === wanted || publicCustomShapeHandle(item.handle) === wanted) || null
}

function buildDirectoryAssetItems(source) {
	const absRoot = path.resolve(ASSETS_ROOT, source.root)
	const items = []
	function walk(dir) {
		let entries
		try { entries = fsNode.readdirSync(dir, { withFileTypes: true }) } catch { return }
		for (const entry of entries) {
			const full = path.join(dir, entry.name)
			if (entry.isDirectory()) {
				walk(full)
				continue
			}
			if (!source.pattern.test(entry.name)) continue
			if (source.kind === 'shapeScene') {
				const sceneItem = buildShapeSceneItem(full, source)
				items.push(sceneItem)
				continue
			}
			const title = titleFromAssetPath(entry.name)
			const rel = relFromCwd(full)
			const item = {
				kind: source.kind,
				role: source.role,
				source: source.source,
				sourceKey: source.source,
				sourceLabel: source.sourceLabel,
				sourcePriority: source.sourcePriority,
				handle: source.kind === 'model3d' ? `model3d://${source.source}/${safeAssetHandlePart(path.basename(entry.name, path.extname(entry.name)))}` : undefined,
				title,
				name: entry.name,
				sourceCategory: source.sourceLabel,
				tags: uniqueAssetStrings([source.source, source.kind, source.role, title, path.dirname(rel).split(/[\\/]/)]).map(tag => tag.toLowerCase().replace(/\s+/g, '-')),
				usage: source.kind === 'model3d' ? 'Use as a maintained local model when it matches the requested narrative or for test/reference scenes.' : 'Use as a local design support asset when the query matches.',
				...(source.license ? { license: String(source.license) } : {}),
				path: full,
				rel,
				...(source.kind === 'model3d' ? { modelAsset: full, addModel3DOptions: { modelAsset: full, nativeOnly: true } } : {}),
				...statSummary(full),
			}
			item.searchText = makeCatalogSearchText(item)
			items.push(item)
		}
	}
	walk(absRoot)
	return items
}

function currentUnifiedAssetCatalogCacheKey() {
	let sketchfabMtime = 0
	try { sketchfabMtime = Math.round(fsNode.statSync(sketchfabManifestPath()).mtimeMs) }
	catch (_) {}
	return `${ASSETS_ROOT}|${sketchfabManifestPath()}|${sketchfabMtime}`
}

function invalidateUnifiedAssetCatalog() {
	unifiedAssetCatalogCache = null
	unifiedAssetCatalogCacheKey = ''
}

function loadUnifiedAssetCatalog({ refresh = false } = {}) {
	const cacheKey = currentUnifiedAssetCatalogCacheKey()
	if (!refresh && unifiedAssetCatalogCache && unifiedAssetCatalogCacheKey === cacheKey) {
		return unifiedAssetCatalogCache
	}
	const catalog = [
		...buildMicrosoftStock3DAssets(),
		...buildIconScoutAssets(),
		...buildToxSamAssets(),
		...buildSketchfabImportedAssets(),
		...buildCustomShapeAssets(),
		...ASSET_CATALOG.flatMap(buildDirectoryAssetItems),
	]
	unifiedAssetCatalogCache = catalog
	unifiedAssetCatalogCacheKey = cacheKey
	return catalog
}

function listAssetFiles({ kind, query, q: queryAlias, intent, useCase, aiContext, source, maxResults = 60, includeDuplicates = false, preferNative = true, sizePolicy = 'standard', maxModelSizeMb, maxGlbSizeMb, maxSizeMb } = {}) {
	const normalizedKind = normalizeAssetKind(kind)
	const rawQuery = String(query ?? queryAlias ?? '').trim()
	const q = rawQuery.toLowerCase()
	const contextText = [rawQuery, intent, useCase, aiContext].filter(Boolean).join(' ')
	const intentContext = buildAssetIntentQueryContext(contextText)
	const terms = intentContext.terms
	const sourceFilter = normalizeCatalogSource(source)
	const limit = Math.max(1, Math.min(500, Number(maxResults) || 60))
	const normalizedSizePolicy = normalizeModelSizePolicy(sizePolicy)
	const explicitMax = Number(maxModelSizeMb ?? maxGlbSizeMb ?? maxSizeMb)
	const maxModelSize = Number.isFinite(explicitMax) && explicitMax > 0
		? explicitMax
		: MODEL_SIZE_POLICY_LIMITS_MB[normalizedSizePolicy]
	const groups = {}
	const scored = []
	const fallback = []
	let excludedBySize = 0
	for (const item of loadUnifiedAssetCatalog()) {
		if (normalizedKind && item.kind !== normalizedKind) continue
		if (!catalogSourceMatches(item, sourceFilter)) continue
		if (!includeDuplicates && item.duplicateOf) continue
		if (item.kind === 'model3d' && Number.isFinite(maxModelSize)) {
			const mib = assetModelSizeMiB(item)
			if (mib && mib > maxModelSize) {
				excludedBySize += 1
				continue
			}
		}
		const groupKey = item.source || item.sourceKey || 'local'
		if (!groups[groupKey]) groups[groupKey] = { source: groupKey, label: item.sourceLabel || groupKey, count: 0, matches: 0, priority: item.sourcePriority || 0 }
		groups[groupKey].count += 1
		const scoredItem = { ...item }
		if (preferNative !== false && scoredItem.source === MICROSOFT_STOCK3D_SOURCE) scoredItem.sourcePriority = Math.max(Number(scoredItem.sourcePriority || 0), 100)
		const score = scoreCatalogAsset(scoredItem, terms, q)
		scoredItem.matchScore = score.matchScore
		scoredItem.score = score.score + modelSizeRankAdjustment(scoredItem)
		fallback.push(scoredItem)
		if (terms.length && score.matchScore <= 0) continue
		groups[groupKey].matches += 1
		scored.push(scoredItem)
	}
	const pool = terms.length && scored.length === 0 ? fallback : scored
	const fallbackUsed = !!(terms.length && scored.length === 0 && fallback.length)
	const sortedPool = pool
		.sort((a, b) => (b.score || 0) - (a.score || 0) || String(a.title || a.name || '').localeCompare(String(b.title || b.name || '')))
	const dedupedPool = includeDuplicates ? sortedPool : []
	if (!includeDuplicates) {
		const seen = new Map()
		for (const item of sortedPool) {
			const semanticKey = item.dedupeKey || `${item.source || 'local'}|${item.kind}|${safeAssetHandlePart(item.title || item.name)}`
			const existing = seen.get(semanticKey)
			if (existing) {
				existing.semanticDuplicateCount = Number(existing.semanticDuplicateCount || 1) + 1
				continue
			}
			item.semanticDuplicateCount = 1
			seen.set(semanticKey, item)
			dedupedPool.push(item)
		}
	}
	const finalPool = includeDuplicates ? sortedPool : dedupedPool
	const finalResults = finalPool.slice(0, limit)
	return {
		query: q || null,
		intent: intent || null,
		useCase: useCase || null,
		kind: normalizedKind || null,
		source: sourceFilter || null,
		count: finalResults.length,
		truncated: finalPool.length > finalResults.length,
		fallbackUsed,
		sourcePolicy: {
			primary: MICROSOFT_STOCK3D_SOURCE,
			secondary: ICONSCOUT_SOURCE,
			contextualFallback: TOXSAM_SOURCE,
			rationale: 'Prefer Microsoft PowerPoint Stock 3D when semantically relevant because it is native to PowerPoint. Use IconScout for quick navigation and embellishment. Use ToxSam/CC0 contextual models when the content match is stronger or licensing needs CC0.',
		},
		sizePolicy: {
			policy: normalizedSizePolicy,
			maxModelSizeMb: Number.isFinite(maxModelSize) ? maxModelSize : null,
			excludedBySize,
			rationale: 'Default model3d catalog results use low-size GLBs so embedded PowerPoint files stay portable. Use sizePolicy="large-ok" or "unrestricted" only when detail matters more than file size.',
		},
		queryExpansion: {
			rawTerms: intentContext.rawTerms,
			expandedTerms: intentContext.expandedTerms.slice(0, 80),
			matchedIntents: intentContext.matchedCollections.map(aiCollectionPublicSummary),
		},
		catalogGuide: buildAssetCatalogGuide({ matchedCollections: intentContext.matchedCollections }),
		matchedCollections: intentContext.matchedCollections,
		groups,
		results: finalResults,
		assets: finalResults,
		recommendation: 'Choose the highest-scoring semantically relevant low-size result. For model3d results, pass addModel3DOptions or modelAsset to slide.add_model3d. Microsoft Stock 3D entries are de-duplicated by SHA-256, keep category aliases for search, and include AI intent collections for abstract business/story prompts.',
	}
}

// Semantic 3D front-door resolver: pick the single best native catalog model for an
// author's intent (query/context/intent/useCase). Returns a compact selection with the
// opaque handle plus the resolved private path, or null when nothing matches. Shared by
// the spec compiler (compile-time pick, injected via specCompileOptions.resolveModel3d)
// and handleAddModel3D (execution-time safety net). Same ranking as assets.catalog.
function selectCatalogModel3d(selection = {}) {
	const query = String(selection.query || selection.context || selection.prompt || '').trim()
	const intent = selection.intent ? String(selection.intent).trim() : ''
	const useCase = selection.useCase ? String(selection.useCase).trim() : ''
	const aiContext = selection.aiContext ? String(selection.aiContext).trim() : ''
	if (!query && !intent && !useCase && !aiContext) return null
	let result
	try {
		result = listAssetFiles({
			kind: 'model3d',
			query,
			intent,
			useCase,
			aiContext,
			maxResults: 1,
			preferNative: selection.preferNative !== false,
			sizePolicy: selection.sizePolicy || 'standard',
			...(Number.isFinite(Number(selection.maxModelSizeMb)) && Number(selection.maxModelSizeMb) > 0
				? { maxModelSizeMb: Number(selection.maxModelSizeMb) }
				: {}),
		})
	} catch {
		return null
	}
	const top = (result?.results || [])[0]
	if (!top || top.kind !== 'model3d' || !top.handle) return null
	return {
		handle: top.handle,
		title: top.title || top.name || null,
		source: top.sourceLabel || top.source || null,
		path: top.modelAsset || top.path || null,
		posterHandle: top.posterHandle || top.posterAsset || null,
		sizeMiB: assetModelSizeMiB(top) || null,
		animated: !!top.animated,
	}
}

function publicCatalogSourceLabel(item) {
	if (item.source === MICROSOFT_STOCK3D_SOURCE) return 'Microsoft PowerPoint Stock 3D'
	if (item.kind === 'model3d') return 'Catalog 3D model'
	if (item.kind === 'icon') return 'Catalog icon'
	if (item.kind === 'shapeScene' || item.kind === 'customShape') return 'Catalog custom geometry'
	return 'Catalog asset'
}

function publicCatalogEntry(item) {
	const entry = {
		kind: item.kind,
		handle: publicCatalogHandleForItem(item),
		title: item.title || item.name,
		category: item.kind === 'model3d' ? '3D model' : 'Presentation asset',
		source: 'BetterPPTX public catalog',
		usage: item.kind === 'model3d'
			? 'Put this opaque handle on a semantic kind:"model3d" block and compile it through betterpptx.deck.generate_from_spec.'
			: 'Use this public catalog choice only through the corresponding semantic deck-spec block.',
	}
	const aiCollections = Array.isArray(item.aiCollections) ? item.aiCollections : []
	if (aiCollections.length || item.aiBestFor?.length || item.aiSearchHints?.length) {
		entry.ai = {
			collections: aiCollections.map(aiCollectionPublicSummary),
			bestFor: item.aiBestFor || aiCollections.map(collection => collection.bestFor).filter(Boolean),
			searchHints: item.aiSearchHints || uniqueAssetStrings(aiCollections.flatMap(collection => collection.sampleQueries || [])).slice(0, 8),
			selectionHint: aiCollections.length
				? `Good fit for ${aiCollections.map(collection => collection.title.toLowerCase()).slice(0, 3).join(', ')}.`
				: undefined,
		}
	}
	if (item.kind === 'shapeScene') {
		entry.handle = publicShapeSceneHandle(item.handle)
		entry.title = 'Editable custom-geometry collection'
		entry.category = 'Custom geometry'
		entry.source = 'BetterPPTX public catalog'
		entry.usage = 'Use this collection only to narrow a custom-geometry catalog query; choose an exact shape handle before authoring.'
		entry.shapeScene = {
			handle: entry.handle,
			semanticFilterField: 'betterpptx.custom_geometry.catalog collectionHandle',
			useWith: ['betterpptx.custom_geometry.catalog', 'betterpptx.deck.generate_from_spec'],
		}
	}
	if (item.kind === 'customShape') {
		entry.handle = publicCustomShapeHandle(item.handle)
		entry.title = 'Editable custom geometry'
		entry.category = 'Custom geometry'
		entry.source = 'BetterPPTX public catalog'
		entry.usage = 'Put this opaque handle on a semantic kind:"customGeometry" block and compile it through betterpptx.deck.generate_from_spec.'
		entry.customGeometry = {
			handle: entry.handle,
			nativeEditable: true,
			semanticSpecField: 'content[].handle',
		}
	}
	if (item.kind === 'model3d') {
		const sizeMiB = assetModelSizeMiB(item)
		entry.model3d = {
			handle: item.handle,
			posterAvailable: !!(item.posterAsset || item.preview),
			animated: !!item.animated,
			sizeMiB: sizeMiB ? Math.round(sizeMiB * 100) / 100 : undefined,
			sizeTier: item.sizeTier || (item.bytes ? modelSizeTier(item.bytes) : undefined),
		}
		entry.semanticSpec = {
			kind: 'model3d',
			modelAsset: entry.handle,
		}
	}
	return entry
}

function publicAssetCatalogResult(result, maxResults = 60) {
	const allowedKinds = new Set(['model3d', 'shapeScene', 'customShape'])
	const publicItems = [...(result.results || result.assets || [])]
		.filter(item => allowedKinds.has(item?.kind))
		.sort((left, right) => String(left?.title || left?.name || '').localeCompare(String(right?.title || right?.name || '')) || String(left?.handle || '').localeCompare(String(right?.handle || '')))
	const limit = Math.max(1, Math.min(60, Number(maxResults) || 60))
	const publicEntries = publicItems.slice(0, limit).map(publicCatalogEntry)
	return {
		query: result.query,
		intent: result.intent,
		useCase: result.useCase,
		kind: result.kind,
		count: publicEntries.length,
		truncated: Boolean(result.truncated || publicItems.length > publicEntries.length),
		fallbackUsed: result.fallbackUsed,
		...((result.kind === 'model3d' || result.kind == null) ? { sizePolicy: result.sizePolicy } : {}),
		queryExpansion: result.queryExpansion,
		catalogGuide: {
			policy: 'unranked-ai-selection',
			workflow: [
				'Search with the real story need and inspect factual compatibility fields.',
				'The AI chooses one exact handle; BetterPPTX does not rank aesthetic fit or choose the visual treatment.',
				'Put the chosen handle on the corresponding semantic content block and compile it through betterpptx.deck.generate_from_spec.',
			],
		},
		assets: publicEntries,
		results: publicEntries,
		recommendation: 'Choose one semantically relevant opaque handle yourself. Put a 3D handle in content[].modelAsset or a custom-geometry handle in content[].handle, then compile only through betterpptx.deck.generate_from_spec.',
	}
}

// M21 — licensed stock media search (Pexels/Pixabay). Public-safe by construction:
// handles + author + license + preview URL only; API keys never appear in a response.
async function handleAssetsSearchStock(args = {}) {
	const out = await searchStock({
		query: args.query,
		kind: args.kind,
		provider: args.provider,
		orientation: args.orientation,
		perPage: args.perPage,
	})
	recordResourceUsage({ externalCalls: 1 })
	return {
		ok: true,
		query: out.query,
		kind: out.kind,
		providers: stockProviderStatus(),
		results: out.results,
		...(out.providerErrors ? { providerErrors: out.providerErrors } : {}),
		usage: 'Put a result handle in the deck spec as the image source (content[].image = "stock://...") or media source (content[].path for kind:"media"). The license record is attached to the deck automatically at commit.',
	}
}

// G3: the tenant boundary for durable generated assets. v1 anchors on the session identity —
// the same boundary the entitlement layer uses (sessionKey) — with an env override for the dev
// harness; account/license-level identity replaces this with F3. Store paths are tenant-prefixed,
// so cross-tenant access is structurally impossible (a lookup can only name its own prefix).
function genAssetTenantFor(context = {}) {
	if (enforceAssetOwnership()) {
		const owner = currentResourceOwner()
		return `owner-${owner.kind}-${owner.id}`
	}
	return resolveGenAssetTenantIdentity({
		accountId: process.env.BETTERPPTX_ACCOUNT_ID || context?.accountId,
		licenseId: process.env.BETTERPPTX_LICENSE_ID || context?.licenseId,
		tenantId: process.env.BETTERPPTX_GEN_ASSET_TENANT,
		sessionId: context?.sessionId || 'stdio-default',
	}).tenantId
}
// Hydrate every generated image / rigged-3D handle a spec references from the durable store into
// the process caches, so the synchronous compiler/materializers keep their existing APIs.
async function hydrateSpecGenAssets(spec, context) {
	await authorizeAssetReferences(spec)
	try {
		const text = JSON.stringify(spec || {})
		const riggedHashes = new Set()
		const imageHashes = new Set()
		for (const m of text.matchAll(/gen:\/\/(?:trellis\/)?rigged3d\/([a-f0-9]{8,64})/g)) riggedHashes.add(m[1])
		for (const m of text.matchAll(/gen:\/\/(?:(?:flux\/)?image)\/([a-f0-9]{8,64})/g)) imageHashes.add(m[1])
		if (!riggedHashes.size && !imageHashes.size) return
		const tenant = genAssetTenantFor(context)
		await Promise.all([
			...[...riggedHashes].map(h => hydrateGeneratedRigged3d(h, tenant)),
			...[...imageHashes].map(h => hydrateGeneratedImage(h, tenant)),
		])
	} catch (err) {
		if (enforceAssetOwnership()) throw err
		console.warn(`[gen-asset-store] spec hydration failed: ${err?.message || err}`)
	}
}

// G1 (release safety): tool results are a PUBLIC surface. Generation provenance — which model,
// runner, or host produced the bytes — stays server-side (gen cache + meter labels). Clients get
// only the user-facing license facts. Never put upstream project names/URLs in these records.
function publicGeneratedLicense(kind) {
	return {
		type: 'generated',
		commercialUse: 'allowed',
		attributionRequired: false,
		notice: `AI-generated ${kind} created by BetterPPTX for this presentation. Commercial use permitted; no attribution required.`,
	}
}

function publicPocNative3dLicense() {
	return {
		type: 'generated',
		commercialUse: 'not-cleared',
		attributionRequired: null,
		notice: 'Proof-of-concept native 3D flow artifact. Not cleared for production resale; production presenter authoring uses the Meshy → Mixamo path.',
	}
}

// Research-only semantic execution override. It is intentionally gated by the
// local maintainer boundary so a public request cannot turn an uncalibrated
// judge into an acceptance signal. It never enables auto-accept or promotion.
function semanticResearchExecutionOverride(request = {}) {
	return request.semanticJudgeResearchOverride === true
		&& isLocalMaintainerMode()
		&& process.env.BETTERPPTX_IMAGE_AUTHORING_RESEARCH_OVERRIDE === '1'
}

async function generatedImageStructuralQa(entry = {}, request = {}) {
	const data = String(entry.dataUri || '')
	const match = data.match(/^data:(image\/(?:png|jpeg|webp));base64,([A-Za-z0-9+/=\r\n]+)$/i)
	let encodedPayloadValid = false
	if (match) {
		try {
			const bytes = Buffer.from(match[2].replace(/\s+/g, ''), 'base64')
			const mime = match[1].toLowerCase()
			encodedPayloadValid = bytes.length >= 32 && (
				(mime === 'image/png' && bytes.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])))
				|| (mime === 'image/jpeg' && bytes[0] === 0xff && bytes[1] === 0xd8)
				|| (mime === 'image/webp' && bytes.subarray(0, 4).toString('ascii') === 'RIFF' && bytes.subarray(8, 12).toString('ascii') === 'WEBP')
			)
		} catch { encodedPayloadValid = false }
	}
	const width = Number(entry.width)
	const height = Number(entry.height)
	const requested = String(request.aspect || 'square').trim().toLowerCase()
	const targetRatio = ['portrait', 'tall'].includes(requested) ? 768 / 1280
		: ['landscape', 'wide'].includes(requested) ? 1280 / 768
		: 1
	const actualRatio = width > 0 && height > 0 ? width / height : 0
	const aspectDeviation = actualRatio ? Math.abs(actualRatio - targetRatio) / targetRatio : 1
	const checks = {
		encodedPayloadValid,
		dimensionsPresent: Number.isFinite(width) && width > 0 && Number.isFinite(height) && height > 0,
		requestedAspectHonored: aspectDeviation <= 0.05,
	}
	const pass = Object.values(checks).every(Boolean)
	const report = {
		status: pass ? 'pass' : 'fail',
		scope: 'structural-raster',
		checks,
		requestedAspect: requested,
		dimensions: checks.dimensionsPresent ? { width, height } : null,
		aspectDeviation: Math.round(aspectDeviation * 10000) / 10000,
		note: 'This gate verifies raster integrity metadata and crop geometry. It does not claim semantic, anatomical, typography, or aesthetic correctness.',
	}
	if (!pass) {
		const error = new Error('Generated image failed the structural raster quality gate.')
		error.code = 'GENERATED_IMAGE_QA_FAILED'
		error.details = report
		throw error
	}
	const dataMatch = data.match(/^data:[^,]+,(.+)$/s)
	let deterministic = { status: 'not-run', scope: 'deterministic-image-quality', note: 'No decodable image bytes were available for the CPU evaluator.' }
	if (dataMatch) {
		try {
			const imageBytes = Buffer.from(dataMatch[1].replace(/\s+/g, ''), 'base64')
			// No-text is a hard gate. If the caller did not provide a completed OCR result,
			// attempt the pinned local adapter; unavailable OCR remains fail-closed and is never
			// converted into an empty-text pass.
			// Generated pixels are an explicit no-text contract. Use a slightly more
			// sensitive confidence floor than the general OCR adapter default so small
			// poster/label remnants do not pass merely because they are blurry; callers
			// may still provide a stricter explicit value through ocrOptions.
			const ocrOptions = request.noText === true
				? { minConfidence: 40, ...(request.ocrOptions || {}) }
				: request.ocrOptions
			const ocr = entry.ocr || request.ocr || (request.noText === true ? await runLocalOcr(imageBytes, ocrOptions) : undefined)
			deterministic = await evaluateImageQuality(imageBytes, {
				aspect: request.aspect,
				focalRegion: request.focalRegion,
				quietRegion: request.quietRegion,
				noText: request.noText === true,
				ocr,
				actualGpuSeconds: entry.gpuSeconds,
				usdPerGpuSecond: request.usdPerGpuSecond,
				costCeilingUsd: request.costCeilingUsd,
			})
		} catch (error) {
			deterministic = { status: 'fail', scope: 'deterministic-image-quality', blockingIssues: ['EVALUATOR_ERROR'], note: String(error?.message || error) }
		}
	}
	report.deterministic = deterministic
	if (request.enforceDeterministicQuality === true && request.deferEnforcement !== true && deterministic.status !== 'pass') {
		const error = new Error('Generated image failed the deterministic image-quality gate.')
		error.code = 'GENERATED_IMAGE_DETERMINISTIC_QA_FAILED'
		error.details = deterministic
		throw error
	}
	let semanticJudgeWorkerResult = request.semanticJudgeWorkerResult
	if (!semanticJudgeWorkerResult && (request.semanticJudgeWorkerEnabled === true || request.semanticQuality === true) && deterministic.status === 'pass' && dataMatch) {
		semanticJudgeWorkerResult = await invokeSemanticJudgeWorker({ dataUri: data, request })
		// Keep private Qwen usage in the owner-visible metrology ledger. The raw
		// worker payload never enters the public result; only bounded counters and
		// generic operational labels are recorded here.
		const metering = semanticJudgeWorkerResult?.metering
		const attempts = Math.max(0, Number(semanticJudgeWorkerResult?.attempts || 0))
		if (attempts > 0 || metering) {
			recordResourceUsage({
				externalCalls: attempts,
				semanticJudgeOps: attempts,
				semanticJudgeGpuSeconds: Number(metering?.gpuSeconds || 0),
			})
			recordResourceLabels({
				semanticJudgeColdStart: metering?.coldStart ? 'true' : 'false',
				...(metering?.gpuType ? { semanticJudgeGpuType: metering.gpuType } : {}),
			})
		}
	}
	const semanticOptions = {
		deterministicReport: deterministic,
		minimumScore: request.semanticMinimumScore,
		minimumConfidence: request.semanticMinimumConfidence,
		hardMinimum: request.semanticHardMinimum,
		researchExecutionOverride: semanticResearchExecutionOverride(request),
	}
	const semantic = semanticJudgeWorkerResult
		? evaluateWorkerJudgeResponse(semanticJudgeWorkerResult, semanticOptions)
		: evaluateSemanticJudge(request.semanticJudgeResult, semanticOptions)
	report.semantic = semantic
	report.repairPlan = { status: 'not-run', ...diagnoseRepair({ deterministic, semantic }) }
	const semanticExecutionAccepted = semantic.status === 'pass' || (semantic.status === 'research-pass' && semantic.executionAccepted === true)
	if (request.enforceSemanticQuality === true && request.deferEnforcement !== true && !semanticExecutionAccepted) {
		const error = new Error('Generated image failed the independent semantic judge gate.')
		error.code = 'GENERATED_IMAGE_SEMANTIC_QA_FAILED'
		error.details = semantic
		throw error
	}
	return report
}

// Generation may need one bounded repair attempt before a hard quality gate can
// be enforced.  Keep the final assertion centralized so initial candidate QA is
// diagnostic (and repairable), while the accepted raster is still fail-closed.
function enforceGeneratedImageQuality(report = {}, request = {}) {
	if (request.enforceDeterministicQuality === true && report.deterministic?.status !== 'pass') {
		const error = new Error('Generated image failed the deterministic image-quality gate.')
		error.code = 'GENERATED_IMAGE_DETERMINISTIC_QA_FAILED'
		error.details = report.deterministic || report
		throw error
	}
	const semantic = report.semantic || {}
	const semanticExecutionAccepted = semantic.status === 'pass' || (semantic.status === 'research-pass' && semantic.executionAccepted === true)
	if (request.enforceSemanticQuality === true && !semanticExecutionAccepted) {
		const error = new Error('Generated image failed the independent semantic judge gate.')
		error.code = 'GENERATED_IMAGE_SEMANTIC_QA_FAILED'
		error.details = semantic
		throw error
	}
}

async function resolveImageGenerationReferences(request = {}, context = {}) {
	const productionPolicyError = generatedImageUnavailableInProductionError()
	if (productionPolicyError) throw productionPolicyError
	const raw = request.referenceHandles ?? request.referenceAssets ?? []
	const handles = (Array.isArray(raw) ? raw : [raw]).map(value => String(value || '').trim()).filter(Boolean)
	if (handles.length > 4) {
		const error = new Error('Use at most four reference images for one generation request.')
		error.code = 'IMAGE_GEN_TOO_MANY_REFERENCES'
		throw error
	}
	const images = []
	const digests = []
	for (const handle of handles) {
		const parsed = parseGenHandle(handle)
		if (!parsed) {
			const error = new Error('Reference images must be durable generated-image handles returned for this account.')
			error.code = 'IMAGE_GEN_REFERENCE_HANDLE_INVALID'
			throw error
		}
		const entry = getCachedGeneratedImage(parsed.hash) || await hydrateGeneratedImage(parsed.hash, genAssetTenantFor(context))
		if (!entry?.dataUri) {
			const error = new Error('A reference image is unavailable for this account. Generate or resolve it first, then retry the edit.')
			error.code = 'IMAGE_GEN_REFERENCE_UNAVAILABLE'
			throw error
		}
		const base64 = String(entry.dataUri).replace(/^data:[^,]*,/, '').trim()
		if (!base64) {
			const error = new Error('A reference image could not be decoded.')
			error.code = 'IMAGE_GEN_REFERENCE_INVALID'
			throw error
		}
		images.push(base64)
		digests.push(parsed.hash)
	}
	return { handles, images, digests }
}

const DEFAULT_IMAGE_REPAIR_COST_CEILING_USD = 0.05
const DEFAULT_MODAL_GPU_USD_PER_SECOND = 0.000542

function compositionRepairConstraint(request = {}) {
	const quiet = request.quietRegion && typeof request.quietRegion === 'object' ? request.quietRegion : null
	const focal = request.focalRegion && typeof request.focalRegion === 'object' ? request.focalRegion : null
	const regionText = region => {
		if (!region) return null
		const x = Number(region.x); const y = Number(region.y); const w = Number(region.w); const h = Number(region.h)
		if (![x, y, w, h].every(Number.isFinite)) return null
		return `x=${x}%, y=${y}%, width=${w}%, height=${h}%`
	}
	const quietText = regionText(quiet)
	const focalText = regionText(focal)
	if (!quietText && !focalText) return ''
	const parts = [
		'Composition repair is a hard layout contract, not a stylistic suggestion.',
		quietText ? `Make the quiet copy-safe region (${quietText}) genuinely low-detail and low-edge-density: use one continuous, nearly uniform wall/sky/surface with no objects, foliage, windows, furniture, texture, horizon, or high-contrast transitions inside it.` : '',
		focalText ? `Keep the focal subject fully inside the focal region (${focalText}) and concentrate the visual mass there.` : '',
		'Use a strong crop/reframe if necessary; do not add text, labels, signs, screens, or decorative detail to fill the quiet lane.',
	].filter(Boolean)
	return parts.join(' ')
}

// IMG6 provider-backed repair. The only generation callbacks used here are the audited
// private Modal lanes; the adapter never invokes an external AI API. Semantic judging is
// intentionally not re-used from the original candidate, so an absent private judge abstains.
async function maybeRepairGeneratedImage(initialEntry, initialQa, request = {}, context = {}) {
	const options = request.repair && typeof request.repair === 'object' ? request.repair : {}
	if (options.enabled !== true) return { entry: initialEntry, qa: initialQa, repair: null, calls: 0 }
	const needsRepair = initialQa?.status !== 'pass' || initialQa?.deterministic?.status !== 'pass' || initialQa?.semantic?.status === 'reject'
	if (!needsRepair) return { entry: initialEntry, qa: initialQa, repair: { status: 'not-needed', attempts: [] }, calls: 0 }
	let calls = 0
	let repairGpuSeconds = 0
	const repair = await runProviderBackedImageRepair({
		initialCandidate: { entry: initialEntry },
		initialQuality: initialQa,
		maxAttempts: options.maxAttempts ?? 2,
		costCeilingUsd: options.costCeilingUsd ?? DEFAULT_IMAGE_REPAIR_COST_CEILING_USD,
		initialCostUsd: Number(initialEntry.gpuSeconds || 0) * Number(options.usdPerGpuSecond || DEFAULT_MODAL_GPU_USD_PER_SECOND),
		evaluate: async candidate => generatedImageStructuralQa(candidate.entry, {
			...request,
			enforceDeterministicQuality: false,
			enforceSemanticQuality: false,
			semanticJudgeResult: undefined,
			semanticJudgeWorkerResult: undefined,
		}),
		generate: async ({ action, instruction }) => {
			const source = initialEntry
			const usesReference = action !== 'regenerate'
			const reference = usesReference ? String(source.base64 || source.dataUri || '').replace(/^data:[^,]*,/, '').trim() : ''
			if (usesReference && !reference) return null
			const compositionConstraint = action === 'reframe' ? compositionRepairConstraint(request) : ''
			const candidate = await generateImage({
				prompt: `${request.prompt || 'presentation visual'}\nRepair instruction: ${instruction}${compositionConstraint ? `\n${compositionConstraint}` : ''}`,
				provider: usesReference ? 'modal-edit' : 'modal',
				aspect: request.aspect,
				style: request.style,
				steps: request.steps,
				capability: usesReference ? 'edit' : 'create',
				referenceImages: usesReference ? [reference] : [],
				referenceDigests: usesReference ? [String(source.promptHash || '')] : [],
			})
			calls += 1
			const gpuSeconds = Number(candidate.gpuSeconds || 0)
			repairGpuSeconds += gpuSeconds
			recordResourceUsage({ externalCalls: 1, imageGenOps: 1, imageGenImages: 1, imageGenGpuSeconds: gpuSeconds })
			recordResourceLabels({ imageGenCapability: `repair-${action}`, imageGenColdStart: candidate.coldStart ? 'true' : 'false', ...(candidate.gpuType ? { imageGenGpuType: candidate.gpuType } : {}) })
			return { entry: candidate, costUsd: gpuSeconds * Number(options.usdPerGpuSecond || DEFAULT_MODAL_GPU_USD_PER_SECOND) }
		},
	})
	const best = repair.bestCandidate?.entry ? repair.bestCandidate.entry : initialEntry
	const bestQa = repair.bestQuality || initialQa
	if (best?.promptHash && best.promptHash !== initialEntry.promptHash) cacheGeneratedImage(best)
	return { entry: best, qa: { ...bestQa, repairPlan: { status: repair.status, ...diagnoseRepair(bestQa), attempts: repair.attempts, totalCostUsd: repair.totalCostUsd } }, repair, calls, repairGpuSeconds }
}

// Optional premium/research ensemble. The public Visual Director supplies only
// provider-neutral candidate/evaluation plans; this private engine path executes
// the bounded create/reference lanes, runs deterministic hard gates, and applies
// the owner sharpness selector. It is deliberately opt-in and abstains unless
// the plan explicitly requests the research sharpness criterion.
async function ensureGeneratedImageEnsemble(request = {}, context = {}) {
	const candidatePlan = request.candidatePlan && typeof request.candidatePlan === 'object' ? request.candidatePlan : {}
	const evaluationPlan = request.evaluationPlan && typeof request.evaluationPlan === 'object' ? request.evaluationPlan : {}
	const enabled = candidatePlan.crossModelEnsemble === true && evaluationPlan.sharpnessFirstResearch === true
	if (!enabled) return null
	const references = await resolveImageGenerationReferences(request, context)
	const laneList = [...new Set((Array.isArray(candidatePlan.capabilityLanes) ? candidatePlan.capabilityLanes : []).map(value => String(value || '').trim().toLowerCase()).filter(value => value === 'create' || value === 'reference'))]
	const lanes = laneList.length ? laneList : ['create', 'reference']
	const maxCandidates = Math.max(1, Math.min(4, Math.round(Number(candidatePlan.initialCandidates) || lanes.length)))
	const hardCeiling = Math.max(1, Math.min(8, Math.round(Number(candidatePlan.hardGenerationCallCeiling) || maxCandidates)))
	const referenceAwareCapability = normalizeImageCapability(request.capability, references.handles.length)
	const prompt = request.prompt
	const style = request.style
	const aspect = request.aspect
	const steps = request.steps
	const tenantId = genAssetTenantFor(context)
	// Preserve ordinary cached handles when a premium plan is dry-run seeded or
	// already accepted. A cache hit is authoritative and must not spend the
	// second lane merely because the request also carries a candidate plan.
	const baseHash = imageRequestHashFor({ prompt, style, aspect, steps, capability: referenceAwareCapability, referenceDigests: references.digests })
	const selectionHash = imageEnsembleSelectionHashFor({ baseHash, candidatePlan, evaluationPlan, referenceDigests: references.digests })
	if (!request.force) {
		const durableSelection = await loadGeneratedImageEnsembleSelection(selectionHash, tenantId)
		if (durableSelection?.finalHash) {
			const durableEntry = getCachedGeneratedImage(durableSelection.finalHash) || await hydrateGeneratedImage(durableSelection.finalHash, tenantId)
			if (durableEntry?.dataUri) {
				const selectionEvidence = {
					status: durableSelection.selection?.status || 'selected', reason: durableSelection.selection?.reason || 'DURABLE_SELECTION_REUSE',
					policy: durableSelection.selection?.policy || 'hard-gates-then-owner-sharpness-proxy', selectedLane: durableSelection.selectedLane,
					ranked: durableSelection.selection?.ranked || [], selectionIndexHash: selectionHash, reused: true,
				}
				const hydratedEntry = cacheGeneratedImage({ ...durableEntry, promptHash: durableSelection.finalHash, handle: `gen://image/${durableSelection.finalHash}`, ensembleSelection: selectionEvidence })
				const durableQa = await generatedImageStructuralQa(hydratedEntry, { ...request, enforceDeterministicQuality: false, enforceSemanticQuality: false, semanticJudgeResult: undefined, semanticJudgeWorkerResult: undefined })
				if (durableQa?.deterministic?.status === 'pass') {
					return {
						handle: hydratedEntry.handle, promptHash: hydratedEntry.promptHash, capability: hydratedEntry.capability || referenceAwareCapability,
						width: hydratedEntry.width, height: hydratedEntry.height, cached: true, gpuSeconds: 0, repairCalls: 0, attempts: 0,
						qa: { ...durableQa, ensembleSelection: selectionEvidence }, entry: hydratedEntry, candidates: [],
						selectionIndexHash: selectionHash,
					}
				}
			}
		}
	}
	if (!request.force && (getCachedGeneratedImage(baseHash) || await hydrateGeneratedImage(baseHash, tenantId))) return null
	const candidates = []
	let createCandidate = null
	let calls = 0
	let gpuSeconds = 0
	let attempts = 0
	const sortedLanes = [...lanes].sort((a, b) => (a === 'create' ? -1 : 1) - (b === 'create' ? -1 : 1))
	for (const lane of sortedLanes.slice(0, Math.min(maxCandidates, hardCeiling))) {
		if (calls >= hardCeiling) break
		let capability = lane === 'create' ? 'create' : 'reference'
		let referenceImages = lane === 'create' ? references.images : references.images
		let referenceDigests = lane === 'create' ? references.digests : references.digests
		if (lane === 'reference' && referenceImages.length === 0 && createCandidate?.result?.dataUri) {
			referenceImages = [createCandidate.result.dataUri]
			referenceDigests = [createCandidate.result.promptHash]
		}
		if (capability !== 'create' && referenceImages.length === 0) continue
		if (capability === 'create' && referenceImages.length > 0 && references.handles.length > 0) {
			// A source-backed ensemble must keep the authored reference; the create
			// lane is only valid for source-less premium comparison.
			capability = referenceAwareCapability === 'create' ? 'create' : referenceAwareCapability
			if (capability !== 'create') continue
		}
		const result = cacheGeneratedImage(await generateImage({
			prompt,
			provider: lane === 'reference' ? 'modal-edit' : request.provider,
			aspect,
			style,
			steps,
			capability,
			referenceImages,
			referenceDigests,
		}))
		calls += 1
		gpuSeconds += Number(result.gpuSeconds || 0)
		attempts += Math.max(1, Number(result.attempts) || 1)
		recordResourceUsage({ externalCalls: 1, imageGenOps: 1, imageGenImages: 1, imageGenGpuSeconds: Number(result.gpuSeconds || 0) })
		recordResourceLabels({ imageGenEnsemble: 'true', imageGenLane: lane, imageGenProvider: result.provider, imageGenModel: result.model, imageGenCapability: capability, imageGenColdStart: result.coldStart ? 'true' : 'false', ...(result.gpuType ? { imageGenGpuType: result.gpuType } : {}) })
		const qa = await generatedImageStructuralQa(result, { ...request, enforceDeterministicQuality: false, enforceSemanticQuality: false, semanticJudgeResult: undefined, semanticJudgeWorkerResult: undefined })
		const item = { lane, result, qa, quality: qa?.deterministic || { status: 'fail', blockingIssues: ['DETERMINISTIC_QA_MISSING'] } }
		candidates.push(item)
		if (lane === 'create') createCandidate = item
	}
	const selection = selectSharpestCandidate(candidates)
	if (selection.status !== 'selected' || !selection.selected?.result) {
		const error = new Error('Premium visual ensemble produced no deterministic sharpness winner.')
		error.code = 'IMAGE_GEN_ENSEMBLE_ABSTAINED'
		error.details = { selection: { status: selection.status, reason: selection.reason, ranked: selection.ranked }, candidates: candidates.map(item => ({ lane: item.lane, quality: item.quality })) }
		throw error
	}
	const selected = selection.selected
	const selectionSalt = crypto.createHash('sha256').update(JSON.stringify({ prompt, style, aspect, steps, lanes: sortedLanes.slice(0, maxCandidates), selectedLane: selected.lane, ranked: selection.ranked, referenceDigests: references.digests })).digest('hex').slice(0, 16)
	const finalCapability = selected.result.capability || (selected.lane === 'reference' ? 'reference' : 'create')
	const finalHash = imageRequestHashFor({ prompt: `${prompt}\n[owner-sharpness-selection:${selectionSalt}]`, style, aspect, steps, capability: finalCapability, referenceDigests: selected.result.referenceDigests || [] })
	const finalEntry = { ...selected.result, promptHash: finalHash, handle: `gen://image/${finalHash}`, ensembleSelection: { status: selection.status, reason: selection.reason, policy: selection.policy, selectedLane: selected.lane, ranked: selection.ranked, selectionIndexHash: selectionHash, reused: false } }
	cacheGeneratedImage(finalEntry)
	const persistedImage = await persistGeneratedImage(finalHash, tenantId)
	const persistedSelection = await persistGeneratedImageEnsembleSelection({
		selectionHash, tenantId, baseHash, finalHash, selectedLane: selected.lane,
		selection: finalEntry.ensembleSelection,
		candidateHashes: candidates.map(item => ({ lane: item.lane, hash: item.result.promptHash })),
		referenceDigests: references.digests,
	})
	return {
		handle: finalEntry.handle,
		promptHash: finalEntry.promptHash,
		capability: finalEntry.capability || finalCapability,
		width: finalEntry.width,
		height: finalEntry.height,
		cached: false,
		gpuSeconds,
		repairCalls: 0,
		attempts,
		qa: { ...selected.qa, ensembleSelection: { ...finalEntry.ensembleSelection, persistedImage: persistedImage.ok === true, persistedSelection: persistedSelection.ok === true } },
		entry: finalEntry,
		candidates: candidates.map(item => ({ lane: item.lane, quality: item.quality, handle: item.result.handle })),
		selectionIndexHash: selectionHash,
	}
}

// M-genA — capability-routed generated image. Generates NOW, caches by a request hash, returns an
// opaque gen:// handle (never the bytes). Reference handles are hydrated only inside the caller's
// tenant boundary and converted to bytes immediately before the private worker call. The metered
// generation is the USD operation; embedding the resulting handle later is free.
async function ensureGeneratedImage(request = {}, context = {}) {
	const productionPolicyError = generatedImageUnavailableInProductionError()
	if (productionPolicyError) throw productionPolicyError
	const ensembleResult = await ensureGeneratedImageEnsemble(request, context)
	if (ensembleResult) {
		enforceGeneratedImageQuality(ensembleResult.qa, request)
		if (!ensembleResult.cached) captureProducedAsset(ensembleResult.handle, generatedImageBytes(ensembleResult.entry))
		return ensembleResult
	}
	const references = await resolveImageGenerationReferences(request, context)
	const capability = normalizeImageCapability(request.capability, references.handles.length)
	const hash = imageRequestHashFor({
		prompt: request.prompt,
		style: request.style,
		aspect: request.aspect,
		steps: request.steps,
		capability,
		referenceDigests: references.digests,
	})
	if (!request.force) {
		const cached = getCachedGeneratedImage(hash) || await hydrateGeneratedImage(hash, genAssetTenantFor(context))
		if (cached) {
			const qa = await generatedImageStructuralQa(cached, { ...request, deferEnforcement: true })
			const hydratedEntry = { ...cached, promptHash: hash, handle: `gen://image/${hash}` }
			const repaired = await maybeRepairGeneratedImage(hydratedEntry, qa, request, context)
			enforceGeneratedImageQuality(repaired.qa, request)
			recordResourceUsage({ externalCalls: 0, imageGenOps: 0, imageGenImages: 0, imageGenGpuSeconds: 0 })
			recordResourceLabels({ imageGenProvider: cached.provider, imageGenModel: cached.model, imageGenCapability: capability, imageGenCacheHit: 'true', ...(cached.gpuType ? { imageGenGpuType: cached.gpuType } : {}) })
			if (repaired.entry.promptHash !== hash) await persistGeneratedImage(repaired.entry.promptHash, genAssetTenantFor(context))
			if (repaired.calls > 0 && repaired.entry.promptHash !== hash) captureProducedAsset(repaired.entry.handle, generatedImageBytes(repaired.entry))
			return { handle: repaired.entry.handle, promptHash: repaired.entry.promptHash, capability: repaired.entry.capability || capability, width: repaired.entry.width, height: repaired.entry.height, cached: repaired.entry.promptHash === hash, gpuSeconds: repaired.repairGpuSeconds || 0, repairCalls: repaired.calls, qa: repaired.qa, entry: repaired.entry }
		}
	}
	const result = cacheGeneratedImage(await generateImage({
		prompt: request.prompt,
		provider: request.provider,
		aspect: request.aspect,
		style: request.style,
		steps: request.steps,
		capability,
		referenceImages: references.images,
		referenceDigests: references.digests,
	}))
	recordResourceUsage({ externalCalls: 1, imageGenOps: 1, imageGenImages: 1, imageGenGpuSeconds: result.gpuSeconds || 0 })
	recordResourceLabels({ imageGenProvider: result.provider, imageGenModel: result.model, imageGenCapability: capability, imageGenColdStart: result.coldStart ? 'true' : 'false', ...(result.gpuType ? { imageGenGpuType: result.gpuType } : {}) })
	const qa = await generatedImageStructuralQa(result, { ...request, deferEnforcement: true })
	const repaired = await maybeRepairGeneratedImage(result, qa, request, context)
	enforceGeneratedImageQuality(repaired.qa, request)
	const finalEntry = repaired.entry
	captureProducedAsset(finalEntry.handle, generatedImageBytes(finalEntry))
	if (finalEntry.promptHash !== result.promptHash) cacheGeneratedImage(finalEntry)
	await persistGeneratedImage(finalEntry.promptHash, genAssetTenantFor(context))
	return { handle: finalEntry.handle, promptHash: finalEntry.promptHash, capability: finalEntry.capability || capability, width: finalEntry.width, height: finalEntry.height, cached: false, gpuSeconds: Number(result.gpuSeconds || 0) + Number(repaired.repairGpuSeconds || 0), repairCalls: repaired.calls, qa: repaired.qa, entry: finalEntry }
}

async function handleAssetsGenerateImage(args = {}, context = {}) {
	const usage = publicGeneratedImagePolicy().available
		? 'Put this handle straight into the deck spec as content[].image (or slide.add_image path). Generated images are commercially usable with no attribution required; the license record rides the deck automatically. Regenerating the same prompt returns the same cached handle (no new cost unless force:true). The same-session cache is the primary path; a configured durable tenant store enables rehydration after restart. Prefer betterpptx.assets.search_stock (free real photos/illustrations) or native editable PowerPoint content when those fit — generation is a metered compute cost.'
		: 'Generated-image materialization is disabled by deployment policy. Keep the visual concept in authored intent and use native editable PowerPoint content or an approved supplied/stock asset until the policy is enabled.'
	const result = await ensureGeneratedImage(args, context)
	return {
		ok: true,
		handle: result.handle,
		dimensions: { width: result.width, height: result.height },
		license: publicGeneratedLicense('image'),
		qualityGate: result.qa,
		capability: result.capability,
		...(result.cached ? { cached: true } : {}),
		_billing: { imageCount: 1 + Number(result.repairCalls || 0), gpuSeconds: result.gpuSeconds || 0, cached: result.cached === true, ...(result.repairCalls ? { repairCalls: result.repairCalls } : {}) },
		usage,
	}
}

// Resolve the SOURCE image for rigged-3D generation into base64 + a stable basis for cache dedup. The
// image can be a gen://flux handle from generate_image, an imageUrl (safe remote fetch), raw imageBase64,
// or a prompt — in which case a source image is generated via Flux FIRST (composing both generators).
async function resolveRigged3dSourceImage(args = {}) {
	if (args.imageBase64) {
		const b64 = String(args.imageBase64).replace(/^data:[^,]*,/, '').trim()
		if (!b64) throw new Error('imageBase64 was empty.')
		return { imageBase64: b64, imageBasis: `b64:${crypto.createHash('sha256').update(b64).digest('hex').slice(0, 24)}` }
	}
	const genParsed = parseGenHandle(args.imageHandle)
	if (genParsed) {
		const productionPolicyError = generatedImageUnavailableInProductionError()
		if (productionPolicyError) throw productionPolicyError
		const cached = getCachedGeneratedImage(genParsed.hash)
		if (!cached) throw new Error(`${args.imageHandle} was not generated in this session — call betterpptx.assets.generate_image first, then pass its handle as imageHandle.`)
		const b64 = String(cached.dataUri || '').replace(/^data:[^,]*,/, '').trim()
		return { imageBase64: b64, imageBasis: args.imageHandle, sourceImageHandle: args.imageHandle }
	}
	if (args.imageUrl) {
		const materialized = await materializeSpecAssetSource({ url: args.imageUrl, kind: 'image', maxBytes: Number(process.env.BETTERPPTX_SPEC_RESOLVE_MAX_IMAGE_MB || 16) * 1048576 })
		const bytes = materialized.filePath ? await fs.readFile(materialized.filePath) : Buffer.from(materialized.bytes)
		return { imageBase64: bytes.toString('base64'), imageBasis: `url:${args.imageUrl}` }
	}
	if (args.prompt) {
		const productionPolicyError = generatedImageUnavailableInProductionError()
		if (productionPolicyError) throw productionPolicyError
		const img = cacheGeneratedImage(await generateImage({ prompt: args.prompt, style: args.style, aspect: 'square' }))
		captureProducedAsset(img.handle, generatedImageBytes(img))
		recordResourceUsage({ externalCalls: 1, imageGenOps: 1, imageGenImages: 1, imageGenGpuSeconds: img.gpuSeconds || 0 })
		recordResourceLabels({ imageGenProvider: img.provider, imageGenModel: img.model, imageGenColdStart: img.coldStart ? 'true' : 'false', ...(img.gpuType ? { imageGenGpuType: img.gpuType } : {}) })
		return { imageBase64: String(img.base64 || ''), imageBasis: img.handle, sourceImageHandle: img.handle }
	}
	throw new Error('Provide a source image: imageHandle (gen://image/…), imageUrl, imageBase64, or a prompt.')
}

function imageDataUriFromBytes(bytes) {
	const input = Buffer.from(bytes)
	const mime = input.length >= 8 && input.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))
		? 'image/png'
		: input.length >= 3 && input[0] === 0xff && input[1] === 0xd8 && input[2] === 0xff
			? 'image/jpeg'
			: null
	if (!mime) throw new Error('Personalized rigged-persona inputs must be PNG or JPEG images.')
	return `data:${mime};base64,${input.toString('base64')}`
}

function imageDataUriFromString(value) {
	const raw = String(value || '').trim()
	const match = /^data:image\/(?:png|jpe?g);base64,([A-Za-z0-9+/=\r\n]+)$/i.exec(raw)
	if (!match) throw new Error('Personalized rigged-persona data URIs must be PNG or JPEG base64 data.')
	return imageDataUriFromBytes(Buffer.from(match[1].replace(/\s+/g, ''), 'base64'))
}

// Resolve an ORDERED 1-4 image set into immutable data URIs before hashing or sending it to the
// private Meshy adapter. Exactly one plural input family is accepted so front/side/back order is explicit.
async function resolveRigged3dSourceImages(args = {}) {
	const families = [
		['imageBase64s', args.imageBase64s],
		['imageUrls', args.imageUrls],
		['imageHandles', args.imageHandles],
	].filter(([, values]) => Array.isArray(values) && values.length)
	if (families.length !== 1) throw new Error('Provide exactly one ordered personalized-avatar image array: imageBase64s, imageUrls, or imageHandles.')
	const [kind, values] = families[0]
	if (values.length < 1 || values.length > 4) throw new Error('Provide 1 to 4 full-body images of the same person from different angles.')
	if (kind === 'imageBase64s') {
		return { images: values.map((value, index) => {
			const raw = String(value || '').trim()
			if (!raw) throw new Error(`imageBase64s[${index}] was empty.`)
			if (/^data:image\/(?:png|jpe?g);base64,/i.test(raw)) return imageDataUriFromString(raw)
			return imageDataUriFromBytes(Buffer.from(raw.replace(/\s+/g, ''), 'base64'))
		}) }
	}
	if (kind === 'imageHandles') {
		const productionPolicyError = generatedImageUnavailableInProductionError()
		if (productionPolicyError) throw productionPolicyError
		const images = []
		const sourceImageHandles = []
		for (const value of values) {
			const handle = String(value || '')
			const parsed = parseGenHandle(handle)
			if (!parsed) throw new Error(`${handle} is not a generated image handle.`)
			const cached = getCachedGeneratedImage(parsed.hash)
			if (!cached?.dataUri) throw new Error(`${handle} was not generated in this session — call betterpptx.assets.generate_image first.`)
			images.push(String(cached.dataUri))
			sourceImageHandles.push(handle)
		}
		return { images, sourceImageHandles }
	}
	const images = []
	for (const value of values) {
		const url = String(value || '').trim()
		// Meshy's image_urls field accepts both public HTTPS URLs and PNG/JPEG
		// data URIs. Preserve the latter locally; only remote URLs go through
		// the HTTP(S)-only safe materializer.
		if (/^data:image\/(?:png|jpe?g);base64,/i.test(url)) {
			images.push(imageDataUriFromString(url))
			continue
		}
		const materialized = await materializeSpecAssetSource({ url, kind: 'image', maxBytes: Number(process.env.BETTERPPTX_SPEC_RESOLVE_MAX_IMAGE_MB || 16) * 1048576 })
		const bytes = materialized.filePath ? await fs.readFile(materialized.filePath) : Buffer.from(materialized.bytes)
		images.push(imageDataUriFromBytes(bytes))
	}
	return { images }
}

// Generate a NEW rigged 3D model from a source image: TRELLIS.2 (image→textured mesh) → UniRig (auto-rig
// → skeleton + skin weights), self-hosted on Modal L40S. Returns a gen://trellis/rigged3d/{hash} handle
// for slide.add_model3d (glbFile). Cache-first, so regenerating the same image+params is free.
async function handleGenerateRigged3d(args = {}, context = {}) {
	if (enforceAssetOwnership()) await assetGrants.checkReady()
	if (isPublicBlackBoxMode() && args.experimentalConfirmed !== true) {
		const err = new Error('Rigged persona generation is partial and experimental. Set experimentalConfirmed:true only after reviewing current stage readiness, source/identity authorization, cost, and the limitation that the result is not a production-ready 3D presenter.')
		err.code = 'RIGGED_PERSONA_EXPERIMENTAL_CONFIRMATION_REQUIRED'
		err.details = {
			status: 'blocked',
			productionReady: false,
			feature: 'rigged-persona-generation',
			stages: PUBLIC_PERSONA_CAPABILITY_CONTRACT.capabilities.find(capability => capability.id === 'rigged-persona-generation')?.stageReadiness || [],
			nextAction: { tool: 'betterpptx.help.tool_recipe', request: { surface: 'rigged-persona', detail: 'full' } },
		}
		throw err
	}
	const personalized = [args.imageBase64s, args.imageUrls, args.imageHandles].some(values => Array.isArray(values) && values.length)
	const environmentMode = process.env.BETTERPPTX_NATIVE3D_MODE
	const pipeline = resolveNative3dPipeline({
		personalized,
		production: args.production === true,
		environmentMode,
		ownerCleared: String(process.env.BETTERPPTX_NATIVE3D_OWNER_CLEARANCE || '').trim().toLowerCase() === 'approved',
		providerConfigured: meshyAvatarProviderStatus().configured,
	})
	if (!pipeline.ok) throw new Error(pipeline.message)
	const usage = personalized
		? 'Production personalized native 3D uses 1–4 ordered full-body views → Meshy → Mixamo → native PowerPoint 3D. Put the returned handle into slide.add_model3d or spec.presenter.model; provider terms, owner approval, and live acceptance remain required before production enablement.'
		: 'PoC/flow-test native 3D only: the self-hosted single-image generator may validate compilation, fallback, packaging, and playback. It is not production resale-cleared; production presenter authoring requires the Meshy → Mixamo path.'
	if (personalized) {
		const source = await resolveRigged3dSourceImages(args)
		const options = {
			images: source.images,
			heightMeters: args.heightMeters ?? 1.7,
			targetPolycount: args.targetPolycount ?? 220000,
			hdTexture: args.hdTexture !== false,
		}
		const hash = meshyAvatarHashFor(options)
		if (!args.force) {
			const cached = getCachedGeneratedRigged3d(hash) || await hydrateGeneratedRigged3d(hash, genAssetTenantFor(context))
			if (cached) {
				recordResourceUsage({ externalCalls: 0, model3dGenProviderCredits: 0, model3dGenBytes: cached.glbBytes })
				recordResourceLabels({ model3dGenProvider: cached.provider, model3dGenModel: cached.model, model3dGenMeshResolution: cached.meshResolution, model3dGenCacheHit: 'true', model3dGenPerformed: 'true', model3dGenTier: String(cached.tier || '') })
				return { ok: true, handle: `gen://rigged3d/${hash}`, pipeline: pipeline.pipeline, rigged: true, performed: true, glbBytes: cached.glbBytes, meshResolution: cached.meshResolution, clipMap: cached.clipMap, tier: cached.tier, confidence: cached.confidence, imageCount: source.images.length, ...(source.sourceImageHandles ? { sourceImages: source.sourceImageHandles } : {}), license: publicProductionNative3dLicense(), cached: true, _billing: { providerCredits: 0, gpuSeconds: 0, bakeSeconds: 0, cached: true }, usage }
			}
		}
		const result = cacheGeneratedRigged3d(await generatePersonalizedMeshyAvatar(options))
		captureProducedAsset(result.handle, generatedRigged3dBytes(result))
		await persistGeneratedRigged3d(result.promptHash, genAssetTenantFor(context))
		recordResourceUsage({ externalCalls: 2, model3dGenProviderCredits: result.providerCredits || 0, model3dGenBytes: result.glbBytes })
		recordResourceLabels({ model3dGenProvider: result.provider, model3dGenModel: result.model, model3dGenMeshResolution: result.meshResolution, model3dGenPerformed: 'true', model3dGenTier: String(result.tier || ''), model3dGenConfidence: String(result.confidence ?? '') })
		return { ok: true, handle: result.handle, pipeline: pipeline.pipeline, rigged: true, performed: true, glbBytes: result.glbBytes, meshResolution: result.meshResolution, clipMap: result.clipMap, tier: result.tier, confidence: result.confidence, imageCount: source.images.length, ...(source.sourceImageHandles ? { sourceImages: source.sourceImageHandles } : {}), license: publicProductionNative3dLicense(), _billing: { providerCredits: result.providerCredits || 0, gpuSeconds: result.gpuSeconds || 0, bakeSeconds: result.bakeSeconds || 0, cached: false }, usage }
	}
	const perform = args.perform === true  // bake presenter gesture clips (Baker); implies rig
	const rig = perform || args.rig !== false
	const quality = args.quality || 'ppt-lite'
	const source = await resolveRigged3dSourceImage(args)
	if (!args.force) {
		const hash = rigged3dHashFor({ imageBasis: source.imageBasis, style: args.style, rig, quality, perform })
		// G3: the process cache first, then the durable tenant store (restart / other instance).
		const cached = getCachedGeneratedRigged3d(hash) || await hydrateGeneratedRigged3d(hash, genAssetTenantFor(context))
		if (cached) {
			// CACHE HIT — no new GPU/CPU compute, but still emit a $0-but-VISIBLE meter row (owner directive:
			// every request measured). Zero the compute counters; keep the attribution labels + a cacheHit flag.
			recordResourceUsage({ externalCalls: 0, model3dGenGpuSeconds: 0, model3dGenBakeCpuSeconds: 0, model3dGenBytes: cached.glbBytes })
			recordResourceLabels({ model3dGenProvider: cached.provider, model3dGenModel: cached.model, model3dGenMeshResolution: cached.meshResolution, model3dGenCacheHit: 'true', ...(cached.gpuType ? { model3dGenGpuType: cached.gpuType } : {}), ...(cached.performed ? { model3dGenPerformed: 'true', ...(cached.tier ? { model3dGenTier: String(cached.tier) } : {}) } : {}) })
			return { ok: true, handle: `gen://rigged3d/${hash}`, pipeline: pipeline.pipeline, rigged: cached.rigged, performed: cached.performed, glbBytes: cached.glbBytes, meshResolution: cached.meshResolution, ...(cached.performed ? { clipMap: cached.clipMap, tier: cached.tier, confidence: cached.confidence } : {}), ...(source.sourceImageHandle ? { sourceImage: source.sourceImageHandle } : {}), license: publicPocNative3dLicense(), cached: true, usage }
		}
	}
	const result = cacheGeneratedRigged3d(await generateRigged3d({
		imageBase64: source.imageBase64,
		imageBasis: source.imageBasis,
		style: args.style,
		rig,
		quality,
		perform,
	}))
	// G3: write-through to the durable tenant store — a restart or another instance can serve
	captureProducedAsset(result.handle, generatedRigged3dBytes(result))
	// this asset without re-paying the GPU generation. Fail-safe: a store outage logs and the
	// process cache still serves this session.
	await persistGeneratedRigged3d(result.promptHash, genAssetTenantFor(context))
	// EVERY cost dimension recorded for CEO visibility + fair pricing (owner directive), each on its OWN axis:
	//  - model3dGenGpuSeconds: L40S GPU wall time (gen + rig + cold model-load) — the GPU-fair-priced total.
	//  - model3dGenBakeCpuSeconds: Baker CPU-container time — its OWN (CPU-margin, not GPU-fair) cost line.
	//  - model3dGenGen/RigGpuSeconds: per-stage split (metrics-only; sum == the GPU total, no extra USD).
	// Cold-vs-warm, which-GPU, and performer quality (performed/tier/confidence) ride as attribution LABELS.
	recordResourceUsage({
		externalCalls: 1,
		model3dGenGpuSeconds: result.gpuSeconds,
		model3dGenBakeCpuSeconds: result.bakeSeconds || 0,
		model3dGenGenGpuSeconds: result.genSeconds || 0,
		model3dGenRigGpuSeconds: result.rigSeconds || 0,
		model3dGenBytes: result.glbBytes,
	})
	recordResourceLabels({
		model3dGenProvider: result.provider,
		model3dGenModel: result.model,
		model3dGenMeshResolution: result.meshResolution,
		model3dGenColdStart: result.coldStart ? 'true' : 'false',
		...(result.gpuType ? { model3dGenGpuType: result.gpuType } : {}),
		model3dGenPerformed: result.performed ? 'true' : 'false',
		...(result.performed ? { model3dGenTier: String(result.tier ?? ''), model3dGenConfidence: result.confidence == null ? '' : String(result.confidence) } : {}),
	})
	return {
		ok: true,
		handle: result.handle,
		rigged: result.rigged,
		performed: result.performed,
		glbBytes: result.glbBytes,
		meshResolution: result.meshResolution,
		...(result.performed ? { clipMap: result.clipMap, tier: result.tier, confidence: result.confidence } : {}),
		...(source.sourceImageHandle ? { sourceImage: source.sourceImageHandle } : {}),
		pipeline: pipeline.pipeline,
		license: publicPocNative3dLicense(),
		usage,
	}
}

async function handleAssetCatalog(args = {}) {
	const publicMode = isPublicBlackBoxMode()
	const requestedLimit = Math.max(1, Math.min(60, Number(args.maxResults) || 60))
	const result = listAssetFiles(publicMode && !args.kind ? { ...args, maxResults: 500 } : args)
	return publicMode ? publicAssetCatalogResult(result, requestedLimit) : result
}

function publicCustomShapeEntry(asset, format = 'summary') {
	if (!isPublicBlackBoxMode()) {
		const entry = {
			kind: 'customShape', handle: asset.handle, title: asset.title || asset.name,
			sceneHandle: asset.sceneHandle, slideNumber: asset.slideNumber, sourceName: asset.sourceName,
			pointCount: asset.pointCount, area: Math.round(Number(asset.area || 0) * 1000) / 1000,
			defaultBox: asset.customGeometry?.defaultBox, defaultFill: asset.customGeometry?.defaultFill,
			defaultLine: asset.customGeometry?.defaultLine, tags: asset.tags || [], usage: asset.usage,
			insertTool: 'betterpptx.custom_geometry.insert',
			editable: ['geometry box', 'path scaling', 'path points', 'fill', 'line', 'rotation', 'effects', '3D shape options', 'flip', 'transparency', 'hyperlink', 'animation', 'objectName', 'any supported ShapeProps via options'],
		}
		if (format === 'full') {
			entry.sceneTitle = asset.sceneTitle
			entry.specimenIndex = asset.specimenIndex
			entry.objectSummary = {
				shapeType: 'custGeom', x: asset.object?.x, y: asset.object?.y,
				w: asset.object?.w, h: asset.object?.h, fill: asset.object?.fill,
				line: asset.object?.line, pointCount: asset.pointCount,
			}
		}
		return entry
	}
	return {
		kind: 'customShape',
		handle: publicCustomShapeHandle(asset.handle),
		title: 'Editable custom geometry',
		nativeEditable: true,
		semanticSpec: { kind: 'customGeometry', handleField: 'content[].handle' },
		usage: 'Put this opaque handle on a semantic kind:"customGeometry" block and compile it through betterpptx.deck.generate_from_spec. BetterPPTX owns geometry and placement.',
	}
}

function roundGeomNumber(value) {
	const n = Number(value)
	return Number.isFinite(n) ? Math.round(n * 10000) / 10000 : value
}

function scaleGeomNumber(value, factor) {
	const n = Number(value)
	return Number.isFinite(n) ? roundGeomNumber(n * factor) : value
}

function scaleCustomGeometryPoints(points, sourceW, sourceH, targetW, targetH) {
	const sx = Number(sourceW) ? Number(targetW) / Number(sourceW) : 1
	const sy = Number(sourceH) ? Number(targetH) / Number(sourceH) : 1
	return (points || []).map(point => {
		if (!point || typeof point !== 'object') return point
		if (point.close) return { close: true }
		const out = { ...point }
		if ('x' in out) out.x = scaleGeomNumber(out.x, sx)
		if ('y' in out) out.y = scaleGeomNumber(out.y, sy)
		if (out.curve && typeof out.curve === 'object') {
			const curve = { ...out.curve }
			for (const key of ['x1', 'x2', 'wR']) {
				if (key in curve) curve[key] = scaleGeomNumber(curve[key], sx)
			}
			for (const key of ['y1', 'y2', 'hR']) {
				if (key in curve) curve[key] = scaleGeomNumber(curve[key], sy)
			}
			out.curve = curve
		}
		return out
	})
}

function getOverrideValue(args, overrides, key, fallback) {
	if (args && Object.prototype.hasOwnProperty.call(args, key)) return args[key]
	if (overrides && Object.prototype.hasOwnProperty.call(overrides, key)) return overrides[key]
	return fallback
}

function materializeCustomShapeAddArgs(asset, args = {}) {
	const base = cloneJson(asset?.object || {})
	const overrides = args.options && typeof args.options === 'object' ? args.options : {}
	const sourceW = Number(base.w || 1) || 1
	const sourceH = Number(base.h || 1) || 1
	const w = Number(getOverrideValue(args, overrides, 'w', base.w ?? 1)) || sourceW
	const h = Number(getOverrideValue(args, overrides, 'h', base.h ?? 1)) || sourceH
	const out = {
		...cloneJson(base),
		...cloneJson(overrides),
		deckId: args.deckId,
		slideIndex: args.slideIndex,
		x: Number(getOverrideValue(args, overrides, 'x', base.x ?? 0)) || 0,
		y: Number(getOverrideValue(args, overrides, 'y', base.y ?? 0)) || 0,
		w,
		h,
		objectName: String(getOverrideValue(args, overrides, 'objectName', base.name || asset.name || 'custom-shape')),
	}
	for (const key of Object.keys(args || {})) {
		if (['deckId', 'slideIndex', 'handle', 'options', 'idempotencyKey', 'idempotency_key'].includes(key)) continue
		if (args[key] !== undefined) out[key] = cloneJson(args[key])
	}
	delete out.kind
	delete out.shapeType
	delete out.name
	const pointOverride = getOverrideValue(args, overrides, 'points', undefined)
	out.points = Array.isArray(pointOverride)
		? cloneJson(pointOverride)
		: scaleCustomGeometryPoints(base.points || [], sourceW, sourceH, out.w, out.h)
	out.objectName = String(out.objectName || base.name || asset.name || 'custom-shape')
	return out
}

async function handleCustomGeometryCatalog(args = {}) {
	const query = String(args.query || args.q || '').trim().toLowerCase()
	const useCase = String(args.useCase || '').trim()
	const terms = assetQueryTerms([query, useCase].filter(Boolean).join(' '))
	const limit = Math.max(1, Math.min(Number(args.limit || args.maxResults || 30), 200))
	const format = isPublicBlackBoxMode() ? 'summary' : (args.format === 'full' ? 'full' : 'summary')
	const sceneHandle = isPublicBlackBoxMode()
		? resolvePublicShapeSceneHandle(args.collectionHandle || args.sceneHandle)
		: String(args.sceneHandle || '').trim()
	const slideNumber = Number(args.slideNumber ?? args.slide)
	const minPoints = Number(args.minPoints)
	const maxPoints = Number(args.maxPoints)
	const candidates = buildCustomShapeAssets()
		.filter(asset => !sceneHandle || asset.sceneHandle === sceneHandle)
		.filter(asset => !Number.isFinite(slideNumber) || asset.slideNumber === slideNumber)
		.filter(asset => !Number.isFinite(minPoints) || Number(asset.pointCount || 0) >= minPoints)
		.filter(asset => !Number.isFinite(maxPoints) || Number(asset.pointCount || 0) <= maxPoints)
		.map(asset => {
			const score = scoreCatalogAsset(asset, terms, query)
			return { asset, score: score.score, matchScore: score.matchScore }
		})
		.filter(item => !terms.length || item.matchScore > 0)
		.sort((a, b) => b.score - a.score || Number(a.asset.slideNumber || 0) - Number(b.asset.slideNumber || 0) || Number(b.asset.area || 0) - Number(a.asset.area || 0))
	const results = candidates.slice(0, limit).map(item => publicCustomShapeEntry(item.asset, format))
	return {
		brand: BETTERPPTX_BRAND,
		kind: 'customShape',
		query: query || null,
		count: results.length,
		totalAvailable: candidates.length,
		truncated: candidates.length > results.length,
		assets: results,
		workflow: isPublicBlackBoxMode()
			? [
				'Choose one exact opaque handle using story fit; the catalog is unranked.',
				'Put the handle on a semantic kind:"customGeometry" block in betterpptx.deck.generate_from_spec.',
				'Use semantic placement and let BetterPPTX own geometry; do not author points or coordinates.',
			]
			: [
				'Use betterpptx.custom_geometry.inspect to fetch the point payload for one handle.',
				'Use betterpptx.custom_geometry.insert to place it as editable native custGeom.',
				'Pass options for any supported ShapeProps tweak; x/y/w/h rescale the stored path, or pass points to replace/edit it.',
			],
	}
}

async function handleCustomGeometryInspect(args = {}) {
	const asset = findCustomShapeAsset(args.handle)
	if (!asset) throw new Error(`Unknown custom geometry handle: ${args.handle}`)
	const includePoints = args.includePoints !== false
	const addArgs = materializeCustomShapeAddArgs(asset, args)
	const object = cloneJson(addArgs)
	delete object.deckId
	delete object.slideIndex
	if (!includePoints) object.points = { omitted: true, pointCount: addArgs.points.length }
	return {
		brand: BETTERPPTX_BRAND,
		...publicCustomShapeEntry(asset, 'full'),
		object,
		addFreeformArgs: object,
	}
}

async function handleCustomGeometryInsert(args = {}) {
	const asset = findCustomShapeAsset(args.handle)
	if (!asset) throw new Error(`Unknown custom geometry handle: ${args.handle}`)
	const addArgs = materializeCustomShapeAddArgs(asset, args)
	const result = await handleAddFreeform(addArgs)
	return {
		...result,
		handle: asset.handle,
		sourceName: asset.sourceName,
		objectName: addArgs.objectName,
		x: addArgs.x,
		y: addArgs.y,
		w: addArgs.w,
		h: addArgs.h,
		editable: true,
	}
}

function cleanHex(value, fallback) {
	const s = String(value || '').replace(/^#/, '').trim()
	return /^[0-9a-f]{6}$/i.test(s) ? s.toUpperCase() : fallback
}

function rgbFactor(hex, alpha = 1) {
	const h = cleanHex(hex, 'FFFFFF')
	return [
		parseInt(h.slice(0, 2), 16) / 255,
		parseInt(h.slice(2, 4), 16) / 255,
		parseInt(h.slice(4, 6), 16) / 255,
		Math.max(0, Math.min(1, Number(alpha) || 1)),
	]
}

function safeStem(text, fallback = 'contextual-model') {
	const s = String(text || fallback).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '')
	return s || fallback
}

function inferIconKind(context, requested) {
	if (requested && requested !== 'auto') return requested
	const text = String(context || '').toLowerCase()
	if (/(arrow|navigation|navigate|next|previous|back|forward|route|direction|wayfind|wayfinding|flow|path|redirect|morph)/.test(text)) return 'arrow'
	if (/(interface|ui|ux|screen|window|browser|dashboard|app|button|form|cursor|click|mobile|web)/.test(text)) return 'interface'
	if (/(team|group|collaborat|workshop|meeting|audience|people)/.test(text)) return 'team'
	if (/(person|human|presenter|expert|advisor|operator|employee|leader|customer|stakeholder)/.test(text)) return 'person'
	if (/(profile|avatar|user|account|identity)/.test(text)) return 'user'
	if (/(robot|agent|assistant|automation|ai worker|copilot)/.test(text)) return 'robot'
	if (/(device|laptop|tablet|phone|terminal|console|hardware|machine)/.test(text)) return 'device'
	if (/(package|parcel|box|shipment|delivery|container|cube object|product box)/.test(text)) return 'package'
	if (/(aircraft|airplane|aeroplane|aviation|airline|airport|flight|flying|jet|biplane|plane|aerospace|airmail|airshow)/.test(text)) return 'aircraft'
	if (/(ship|boat|maritime|naval|sail|submarine|ferry|ocean|harbor|harbour)/.test(text)) return 'ship'
	if (/(building|tower|office|factory|city|airport|terminal|hangar|architecture)/.test(text)) return 'building'
	if (/(product|artifact|object|prop|tool|module|component|item)/.test(text)) return 'product'
	if (/(building|office|factory|city|environment|scene|landscape|room|space|world)/.test(text)) return 'scene'
	if (/(vehicle|car|truck|train|mobility|transport|fleet)/.test(text)) return 'vehicle'
	if (/(award|trophy|winner|goal|achievement|success|milestone)/.test(text)) return 'trophy'
	if (/(bell|notification|alert|alarm|reminder)/.test(text)) return 'bell'
	if (/(toggle|switch|on\/off|setting|control|preference)/.test(text)) return 'toggle'
	if (/(cloud|upload|download|sync|backup|deploy)/.test(text)) return 'cloud'
	if (/(security|secure|trust|risk|compliance|guard|protect|privacy|auth)/.test(text)) return 'shield'
	if (/(data|database|warehouse|layer|stack|platform|pipeline|storage)/.test(text)) return 'stack'
	if (/(signal|launch|beacon|radar|broadcast|growth|momentum|attention)/.test(text)) return 'beacon'
	if (/(idea|creative|spark|innovation|magic|wow|epoustoufl|extraordinary)/.test(text)) return 'spark'
	if (/(strategy|architecture|system|decision|transformation|design|model)/.test(text)) return 'prism'
	return 'prism'
}

function iconKindReason(kind) {
	return {
		arrow: 'navigation/direction or reusable flow state',
		interface: 'user interface/screen interaction',
		user: 'profile/identity or audience',
		person: 'a human role in the story',
		team: 'multiple people or collaboration',
		robot: 'AI agent or automation worker',
		device: 'a physical/digital device object',
		package: 'delivery, container, or packaged offering',
		product: 'a generic reusable product/object prop',
		aircraft: 'aircraft, aviation, or flight',
		ship: 'ship, boat, or maritime transport',
		building: 'building, terminal, or architectural place',
		scene: 'environment, place, or physical context',
		vehicle: 'movement, transport, or operational fleet',
		trophy: 'achievement, milestone, or goal',
		toggle: 'controls/settings state',
		bell: 'notifications or alerting',
		cloud: 'cloud transfer/synchronization',
		shield: 'trust/protection',
		stack: 'data/layers',
		beacon: 'signal/momentum',
		spark: 'innovation/impact',
		prism: 'strategy/architecture',
	}[kind] || 'the requested narrative motif'
}

