function exportedPublicChartData(value) {
	if (Array.isArray(value)) return value.map(exportedPublicChartData)
	if (!value || typeof value !== 'object') return value
	const out = {}
	for (const [key, child] of Object.entries(value)) {
		// Chart update/replay state uses underscore-prefixed bookkeeping such as
		// `_dataIndex`. It is never part of the public series/category vocabulary.
		if (key.startsWith('_') || child === undefined) continue
		out[key] = exportedPublicChartData(child)
	}
	return out
}

