	const placeholder = opts.placeholder && typeof opts.placeholder === 'object'
		? opts.placeholder
		: opts.phType
			? {
				type: opts.phType,
				...(opts.phIdx !== undefined ? { idx: opts.phIdx } : {}),
				...(opts.phSz !== undefined ? { size: opts.phSz } : {}),
				...(opts.phOrient !== undefined ? { orient: opts.phOrient } : {}),
				...(opts.phHasCustomPrompt !== undefined ? { hasCustomPrompt: opts.phHasCustomPrompt } : {}),
			}
			: null
	const adjunctCandidate = {
		...(typeof opts.rounding === 'boolean' ? { rounding: opts.rounding } : {}),
		...(obj.hyperlink && typeof obj.hyperlink === 'object'
			? { hyperlink: Object.fromEntries(Object.entries(obj.hyperlink).filter(([key]) => key !== '_rId')) }
			: {}),
		...(placeholder ? { placeholder } : {}),
	}
	let pictureAdjuncts = null
	try {
		pictureAdjuncts = Object.keys(adjunctCandidate).length ? validatePictureAdjuncts(adjunctCandidate, 'exported picture adjuncts') : null
	} catch {
		pictureAdjuncts = null
	}
