function exportedXmlDoc(xml) {
	const text = String(xml || '').trim()
	if (!text || !text.includes('<')) return null
	const parseIssues = []
	try {
		const doc = new DOMParser({
			errorHandler: {
				warning: () => {},
				error: message => { parseIssues.push(String(message)) },
				fatalError: message => { parseIssues.push(String(message)) },
			},
		}).parseFromString(text, 'application/xml')
		if (parseIssues.length || doc?.getElementsByTagName?.('parsererror')?.length) return null
		return doc
	} catch (_) {
		return null
	}
}

function exportedXmlText(node) {
	let text = ''
	function walk(current) {
		if (!current) return
		if (current.nodeType === 3 || current.nodeType === 4) {
			text += current.nodeValue || ''
			return
		}
		for (let child = current.firstChild; child; child = child.nextSibling) walk(child)
	}
	walk(node)
	return text
}

function exportedCacheValues(node) {
	if (!node) return []
	const pts = _xmlDescendants(node, 'pt')
		.map((pt, order) => ({ pt, order, index: Number(_xmlAttr(pt, 'idx') ?? order) }))
		.sort((a, b) => a.index - b.index || a.order - b.order)
	const values = []
	for (const { pt } of pts) {
		const v = _xmlFirstDescendant(pt, 'v')
		values.push(exportedXmlText(v || pt).trim())
	}
	return values
}

function exportedChartTypeFromXml(doc) {
	const map = {
		areaChart: 'area',
		barChart: 'bar',
		bubbleChart: 'bubble',
		doughnutChart: 'doughnut',
		lineChart: 'line',
		pieChart: 'pie',
		radarChart: 'radar',
		scatterChart: 'scatter',
	}
	for (const node of _xmlDescendants(doc)) {
		const local = _xmlLocalName(node)
		if (map[local]) return map[local]
	}
	return 'bar'
}

function exportedChartSeriesFromXml(chartXml) {
	const doc = exportedXmlDoc(chartXml)
	if (!doc) return null
	const series = _xmlDescendants(doc, 'ser')
	const data = []
	for (let index = 0; index < series.length; index += 1) {
		const ser = series[index]
		const tx = _xmlFirstDescendant(ser, 'tx')
		const nameValues = exportedCacheValues(tx)
		const cat = _xmlFirstDescendant(ser, 'cat')
		const val = _xmlFirstDescendant(ser, 'val')
		const labels = exportedCacheValues(cat)
		const rawValues = exportedCacheValues(val)
		const values = rawValues.map(value => {
			const n = Number(value)
			return Number.isFinite(n) ? n : 0
		})
		if (labels.length || values.length) {
			data.push({
				name: nameValues.find(Boolean) || `Series ${index + 1}`,
				labels,
				values,
			})
		}
	}
	if (!data.length) return null
	return { chartType: exportedChartTypeFromXml(doc), data }
}

function exportedPassthroughRelPart({ pptx, slide, slideIndex, obj, typeNeedle }) {
	const ids = new Set(collectRelationshipIds(obj?.passthrough?.xml || ''))
	if (!ids.size) return null
	const slidePart = `ppt/slides/slide${slideIndex + 1}.xml`
	const normalizedNeedle = typeNeedle ? String(typeNeedle).toLowerCase() : ''
	const rel = (slide?._rawRels || []).find(item => ids.has(item.id) && (!normalizedNeedle || String(item.type || '').toLowerCase().includes(normalizedNeedle)))
	if (!rel || rel.targetMode === 'External' || isExternalTarget(rel.target)) return null
	const partPath = resolvePackageTarget(slidePart, rel.target)
	return partPath ? _rawPartByPath(pptx, partPath) : null
}

function exportedPassthroughChartFields({ pptx, slide, slideIndex, obj }) {
	const part = exportedPassthroughRelPart({ pptx, slide, slideIndex, obj, typeNeedle: '/chart' })
	const chartXml = part ? _getRawPartText(part) : ''
	const parsed = exportedChartSeriesFromXml(chartXml)
	if (!parsed) return null
	return {
		kind: 'chart-panel',
		fields: {
			chartType: parsed.chartType,
			data: parsed.data,
		},
	}
}

function exportedPassthroughTableFields(obj = {}) {
	const doc = exportedXmlDoc(obj?.passthrough?.xml)
	if (!doc) return null
	const table = _xmlFirstDescendant(doc, 'tbl')
	if (!table) return null
	const rows = []
	for (const tr of _xmlDescendants(table, 'tr')) {
		const cells = _xmlElementChildren(tr).filter(child => _xmlLocalName(child) === 'tc')
		if (!cells.length) continue
		rows.push(cells.map(cell => _xmlDescendants(cell, 't').map(exportedXmlText).join('').trim()))
	}
	if (!rows.length) return null
	// M20 — promoted foreign tables carry their meaning proposal (header/column types).
	const tableSemantics = _deriveTableSemantics(rows)
	return { kind: 'table-panel', fields: { rows, ...(tableSemantics ? { tableSemantics } : {}) } }
}

function exportedPassthroughEquationFields(obj = {}) {
	const doc = exportedXmlDoc(obj?.passthrough?.xml)
	if (!doc) return null
	const hasMath = _xmlDescendants(doc).some(node => String(node.namespaceURI || '').includes('/officeDocument/2006/math') || _xmlLocalName(node) === 'oMath')
	if (!hasMath) return null
	const parts = _xmlDescendants(doc, 't').map(exportedXmlText).map(text => text.trim()).filter(Boolean)
	const source = parts.join('')
	if (!source) return null
	return { kind: 'equation', fields: { source, sourceFormat: 'plain' } }
}

function exportedPassthroughSmartArtFields({ pptx, slide, slideIndex, obj }) {
	const part = exportedPassthroughRelPart({ pptx, slide, slideIndex, obj, typeNeedle: '/diagramdata' })
	const dataXml = part ? _getRawPartText(part) : ''
	const doc = exportedXmlDoc(dataXml)
	if (!doc) return null
	const nodes = _xmlDescendants(doc, 'pt')
		.map(pt => _xmlDescendants(pt, 't').map(exportedXmlText).join('').trim())
		.filter(Boolean)
	if (!nodes.length) return null
	return {
		kind: 'smartart',
		fields: {
			layout: obj.options?._passthroughSourceFormat || 'process',
			nodes,
		},
	}
}

function exportedPassthroughStructuredFields({ pptx, slide, slideIndex, obj }) {
	const opts = obj.options || {}
	const originalType = opts._passthroughOriginalType || inferPassthroughOriginalType(obj?.passthrough?.xml || '', null)
	if (originalType === 'chart') return exportedPassthroughChartFields({ pptx, slide, slideIndex, obj })
	if (originalType === 'table') return exportedPassthroughTableFields(obj)
	if (originalType === 'smartart') return exportedPassthroughSmartArtFields({ pptx, slide, slideIndex, obj })
	const chart = exportedPassthroughChartFields({ pptx, slide, slideIndex, obj })
	if (chart) return chart
	const table = exportedPassthroughTableFields(obj)
	if (table) return table
	const smartart = exportedPassthroughSmartArtFields({ pptx, slide, slideIndex, obj })
	if (smartart) return smartart
	const equation = exportedPassthroughEquationFields(obj)
	if (equation) return equation
	return null
}

function exportedRawSourceStructuredFields(obj = {}) {
	const rawXml = obj.options?._rawSourceShapeXml
	if (typeof rawXml !== 'string' || !rawXml.trim()) return null
	return exportedPassthroughEquationFields({
		...obj,
		passthrough: { xml: rawXml },
	})
}

function exportedPlaceholderText(obj = {}) {
	if (typeof obj.text === 'string') return obj.text
	if (!Array.isArray(obj.text)) return undefined
	return obj.text.map(run => typeof run === 'string' ? run : String(run?.text ?? '')).join('')
}

function exportedNativePlaceholderDefinitions(carrier = {}) {
	return (carrier._slideObjects || []).flatMap((obj, index) => {
		const opts = obj?.options || {}
		const type = opts._placeholderType ?? opts.phType
		if ((_shapeKind(obj) !== 'placeholder' && obj?._type !== 'placeholder') || !type) return []
		// A physical hdr placeholder on a slide layout is rejected by repair-disabled
		// PowerPoint. Imported raw carriers remain package-preserved, but current-spec
		// export must never turn that preservation-only token into authoring input.
		if (String(type) === 'hdr') return []
		const name = String(opts.placeholder || opts.objectName || `${type}-${index + 1}`).replace(/^Placeholder\s+/i, '')
		const out = { name, type: semanticPlaceholderType(String(type), 'exported placeholder type') }
		if (opts._placeholderIdx !== undefined && opts._placeholderIdx !== null) out.idx = Number(opts._placeholderIdx)
		if (opts._placeholderSz !== undefined && opts._placeholderSz !== null) out.size = String(opts._placeholderSz)
		if (String(type) !== 'clipArt' && opts._placeholderOrient !== undefined && opts._placeholderOrient !== null) out.orient = String(opts._placeholderOrient)
		if (opts._placeholderHasCustomPrompt !== undefined && opts._placeholderHasCustomPrompt !== null) out.hasCustomPrompt = Boolean(opts._placeholderHasCustomPrompt)
		for (const key of ['x', 'y', 'w', 'h']) if (Number.isFinite(Number(opts[key]))) out[key] = Number(opts[key])
		if (opts.margin !== undefined) out.margin = cloneForResult(opts.margin)
		const text = exportedPlaceholderText(obj)
		if (text !== undefined) out.text = text
		if (opts._betterpptxPlaceholderStyle && typeof opts._betterpptxPlaceholderStyle === 'object') out.style = cloneForResult(opts._betterpptxPlaceholderStyle)
		return [out]
	})
}

function exportedNativeOwnedObjectOptions(options = {}) {
	const out = {}
	for (const key of ['x', 'y', 'w', 'h', 'objectName', 'fill', 'line', 'shadow', 'rotate', 'flipH', 'flipV', 'fontFace', 'fontSize', 'color', 'bold', 'italic', 'align', 'valign', 'margin']) {
		if (options[key] !== undefined && options[key] !== null) out[key] = cloneForResult(options[key])
	}
	return out
}

function exportedNativeOwnedObjects(carrier = {}) {
	return (carrier._slideObjects || []).flatMap(obj => {
		if (!obj || obj._type === 'placeholder' || obj.options?._placeholderType) return []
		const options = exportedNativeOwnedObjectOptions(obj.options || {})
		if (obj._type === 'text') return [{ text: { text: exportedPlaceholderText(obj) || '', options } }]
		if (obj._type === 'shape') {
			const kind = String(obj.shape || '').toLowerCase() === 'line' ? 'line' : 'rect'
			return [{ [kind]: options }]
		}
		return []
	})
}

function exportedPlaceholderBinding(opts = {}) {
	const native = {
		phType: opts._placeholderType ?? opts.phType ?? opts._phType,
		phIdx: opts._placeholderIdx ?? opts.phIdx ?? opts._phIdx,
		phSz: opts._placeholderSz ?? opts.phSz ?? opts._phSz,
		phOrient: opts._placeholderOrient ?? opts.phOrient ?? opts._phOrient,
		phHasCustomPrompt: opts._placeholderHasCustomPrompt ?? opts.phHasCustomPrompt ?? opts._phHasCustomPrompt ?? opts.hasCustomPrompt,
		hasBarePh: opts.hasBarePh === true,
		placeholder: opts.placeholder,
	}
	return publicPlaceholderBindingFromNative(native)
}

function nativeCarrierDimensions(carrier = {}) {
	const source = carrier._presLayout || {}
	const widthEmu = Number(source.width || source._sizeW || 0)
	const heightEmu = Number(source.height || source._sizeH || 0)
	if (!(widthEmu > 0 && heightEmu > 0)) return null
	return { width: Number((widthEmu / 914400).toFixed(6)), height: Number((heightEmu / 914400).toFixed(6)) }
}

const INHERITANCE_COLOR_SLOTS = Object.freeze(['dk1', 'lt1', 'dk2', 'lt2', 'accent1', 'accent2', 'accent3', 'accent4', 'accent5', 'accent6', 'hlink', 'folHlink'])

function projectedInheritanceName(value, fallback, used) {
	let name = String(value || '').trim().replace(/[^A-Za-z0-9._:-]+/g, '_').replace(/^_+|_+$/g, '')
	if (!name) name = fallback
	let unique = name
	let suffix = 2
	while (used.has(unique.toLocaleLowerCase())) unique = `${name}_${suffix++}`
	used.add(unique.toLocaleLowerCase())
	return unique
}

function projectedHexColor(value) {
	const color = String(value || '').replace(/^#/, '').toUpperCase()
	return /^[0-9A-F]{6}$/.test(color) ? color : null
}

function projectedAuditTheme(theme = {}) {
	const out = {}
	const name = String(theme?.name || '').trim()
	if (name) out.name = name.slice(0, 255)
	const head = String(theme?.fonts?.headFontFace || '').trim()
	const body = String(theme?.fonts?.bodyFontFace || '').trim()
	if (head) out.headFontFace = head.slice(0, 256)
	if (body) out.bodyFontFace = body.slice(0, 256)
	const lang = String(theme?.lang || '').trim()
	if (/^[A-Za-z]{2,8}(?:-[A-Za-z0-9]{1,8})*$/.test(lang)) out.lang = lang
	const colorScheme = {}
	for (const slot of INHERITANCE_COLOR_SLOTS) {
		const color = projectedHexColor(theme?.colorScheme?.[slot] ?? theme?.palette?.[slot])
		if (color) colorScheme[slot] = color
	}
	if (Object.keys(colorScheme).length) {
		out.colorScheme = colorScheme
		out.palette = INHERITANCE_COLOR_SLOTS.map(slot => colorScheme[slot]).filter(Boolean)
	}
	return Object.keys(out).length ? out : null
}

function projectedAuditHeaderFooter(value) {
	if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined
	const out = {}
	for (const key of ['date', 'header', 'footer', 'slideNumber']) {
		if (typeof value[key] === 'boolean') out[key] = value[key]
	}
	return Object.keys(out).length ? out : undefined
}

function projectedAuditSlideNumber(value) {
	if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined
	const out = {}
	for (const key of ['x', 'y', 'w', 'h', 'fontSize']) {
		if (Number.isFinite(Number(value[key]))) out[key] = Number(value[key])
	}
	if (value.margin !== undefined && (Number.isFinite(Number(value.margin)) || Array.isArray(value.margin))) out.margin = cloneForResult(value.margin)
	if (['left', 'center', 'right'].includes(value.align)) out.align = value.align
	if (['top', 'middle', 'bottom'].includes(value.valign)) out.valign = value.valign
	const fontFace = String(value.fontFace || '').trim()
	if (fontFace) out.fontFace = fontFace.slice(0, 256)
	const color = projectedHexColor(value.color)
	if (color && (!value.colorType || value.colorType === 'rgb')) out.color = color
	if (typeof value.bold === 'boolean') out.bold = value.bold
	return Object.keys(out).length ? out : undefined
}

function projectedAuditBackground(value) {
	if (!value || typeof value !== 'object' || Array.isArray(value) || value.type !== 'solid') return undefined
	const color = projectedHexColor(value.color)
	if (!color || (value.colorType && value.colorType !== 'rgb')) return undefined
	return { type: 'solid', color }
}

function projectedAuditPlaceholders(placeholders = []) {
	return (Array.isArray(placeholders) ? placeholders : []).flatMap((placeholder, index) => {
		const nativeType = String(placeholder?.type || 'body')
		if (nativeType === 'hdr') return []
		let type
		try { type = semanticPlaceholderType(nativeType, `imported placeholder ${index + 1}`) }
		catch (_) { return [] }
		const name = String(placeholder?.name || `${type}-${index + 1}`).trim() || `${type}-${index + 1}`
		const out = { name: name.slice(0, 128), type }
		const idx = placeholder?.idx === '' || placeholder?.idx == null ? null : Number(placeholder.idx)
		if (Number.isInteger(idx) && idx >= 0 && idx <= 4294967295) out.idx = idx
		if (['full', 'half', 'quarter'].includes(placeholder?.size)) out.size = placeholder.size
		if (nativeType !== 'clipArt' && ['horz', 'vert'].includes(placeholder?.orient)) out.orient = placeholder.orient
		if (typeof placeholder?.hasCustomPrompt === 'boolean') out.hasCustomPrompt = placeholder.hasCustomPrompt
		const bbox = placeholder?.bbox || placeholder?.rect
		if (bbox && Number.isFinite(Number(bbox.x)) && Number.isFinite(Number(bbox.y)) && Number(bbox.w) > 0 && Number(bbox.h) > 0) {
			Object.assign(out, { x: Number(bbox.x), y: Number(bbox.y), w: Number(bbox.w), h: Number(bbox.h) })
		}
		if (placeholder?.style && typeof placeholder.style === 'object') {
			try { out.style = normalizePlaceholderDefinition({ ...out, style: placeholder.style }, `imported placeholder ${index + 1}`).style }
			catch (_) {}
		}
		return [out]
	})
}

function projectedAuditColorMap(value, field) {
	try { return normalizeInheritanceColorMap(value, field) || undefined }
	catch (_) { return undefined }
}

function projectedAuditTextStyles(value, field) {
	try { return normalizeInheritanceTextStyles(value, field) || undefined }
	catch (_) { return undefined }
}

function projectedAuditOwnedObjects(objects = []) {
	return (Array.isArray(objects) ? objects : []).flatMap((object, index) => {
		const bbox = object?.bbox
		if (!bbox || !Number.isFinite(Number(bbox.x)) || !Number.isFinite(Number(bbox.y)) || !(Number(bbox.w) > 0) || Number(bbox.h) < 0) return []
		const kind = String(object?.kind || '')
		if (!['sp', 'cxnSp'].includes(kind)) return []
		const options = {
			x: Number(bbox.x), y: Number(bbox.y), w: Number(bbox.w), h: Number(bbox.h),
			objectName: String(object?.name || `fixed-${index + 1}`).slice(0, 128),
		}
		const fill = object?.fill
		if (fill?.type === 'none') options.fill = { color: 'FFFFFF', transparency: 100 }
		else if (fill?.type === 'solid' && fill.color && ['rgb', 'scheme'].includes(String(fill.colorType || 'rgb'))) {
			options.fill = {
				color: String(fill.color),
				...(fill.alpha != null ? { transparency: Number(Math.max(0, Math.min(100, 100 - Number(fill.alpha))).toFixed(3)) } : {}),
			}
		}
		const line = object?.line
		if (line && (!line.colorType || ['rgb', 'scheme'].includes(String(line.colorType)))) {
			options.line = {
				...(line.color ? { color: String(line.color) } : {}),
				...(line.widthPt != null ? { width: Number(line.widthPt) } : {}),
				...(line.dashType ? { dash: String(line.dashType) } : {}),
			}
		}
		if (kind === 'cxnSp') return [{ line: options }]
		if (object?.text) return [{ text: { text: String(object.text), options } }]
		if (!object?.preset || ['rect', 'roundRect'].includes(String(object.preset))) return [{ rect: options }]
		return []
	})
}

function projectImportedInheritanceDefinitions(entry = {}, pptx = {}) {
	const audit = entry?.layoutAudit
	if (!audit || (!Array.isArray(audit.layouts) && !Array.isArray(audit.masters))) return null
	const width = Number(audit.slideSize?.widthInches || nativeCarrierDimensions(pptx.slideLayouts?.[0])?.width)
	const height = Number(audit.slideSize?.heightInches || nativeCarrierDimensions(pptx.slideLayouts?.[0])?.height)
	if (!(width > 0 && height > 0)) return null
	const masterNames = new Map()
	const masterNamesByRaw = new Map()
	const layoutNames = new Map()
	const layoutNamesByRaw = new Map()
	const usedMasterNames = new Set()
	const usedLayoutNames = new Set()
	const slideBindings = new Map((audit.slideBindings || []).map(binding => [Number(binding?.slideNumber), binding]))
	const firstBoundLayoutNumber = slideBindings.get(1)?.layoutNumber
	const firstBoundLayout = (audit.layouts || []).find(layout => Number(layout?.number) === Number(firstBoundLayoutNumber))
	const selectedMasterNumber = Number(firstBoundLayout?.masterNumber ?? audit.masters?.[0]?.number)
	const selectedMaster = (audit.masters || []).find(master => Number(master?.number) === selectedMasterNumber) || audit.masters?.[0] || null
	const selectedLayouts = (audit.layouts || []).filter(layout => Number(layout?.masterNumber) === Number(selectedMaster?.number))
	const masters = []
	if (selectedMaster) {
		const title = projectedInheritanceName(selectedMaster.name, 'Master_1', usedMasterNames)
		masterNames.set(Number(selectedMaster.number), title)
		masterNamesByRaw.set(String(selectedMaster.name || ''), title)
		const placeholders = projectedAuditPlaceholders(selectedMaster.placeholders)
		const objects = projectedAuditOwnedObjects(selectedMaster.fixedObjects)
		masters.push({
			title,
			...(projectedAuditBackground(selectedMaster.background) ? { background: projectedAuditBackground(selectedMaster.background) } : {}),
			...(projectedAuditSlideNumber(selectedMaster.slideNumber) ? { slideNumber: projectedAuditSlideNumber(selectedMaster.slideNumber) } : {}),
			...(projectedAuditHeaderFooter(selectedMaster.headerFooter) ? { headerFooter: projectedAuditHeaderFooter(selectedMaster.headerFooter) } : {}),
			...(projectedAuditColorMap(selectedMaster.colorMap, 'imported master colorMap') ? { colorMap: projectedAuditColorMap(selectedMaster.colorMap, 'imported master colorMap') } : {}),
			...(projectedAuditTextStyles(selectedMaster.textStyles, 'imported master textStyles') ? { textStyles: projectedAuditTextStyles(selectedMaster.textStyles, 'imported master textStyles') } : {}),
			...(placeholders.length ? { placeholders } : {}),
			...(objects.length ? { objects } : {}),
		})
	}
	const layouts = selectedLayouts.map((layout, index) => {
		const name = projectedInheritanceName(layout?.name, `Layout_${index + 1}`, usedLayoutNames)
		layoutNames.set(Number(layout?.number), name)
		layoutNamesByRaw.set(String(layout?.name || ''), name)
		const placeholders = projectedAuditPlaceholders(layout?.placeholders)
		const objects = projectedAuditOwnedObjects(layout?.fixedObjects)
		const parent = masterNames.get(Number(layout?.masterNumber))
		return {
			name, width, height,
			...(layout?.type != null ? { type: String(layout.type) } : {}),
			...(parent ? { masterName: parent } : {}),
			...(index === 0 ? { activate: true } : { activate: false }),
			...(projectedAuditBackground(layout?.background) ? { background: projectedAuditBackground(layout.background) } : {}),
			...(projectedAuditSlideNumber(layout?.slideNumber) ? { slideNumber: projectedAuditSlideNumber(layout.slideNumber) } : {}),
			...(projectedAuditHeaderFooter(layout?.headerFooter) ? { headerFooter: projectedAuditHeaderFooter(layout.headerFooter) } : {}),
			...(projectedAuditColorMap(layout?.colorMapOverride, 'imported layout colorMapOverride') ? { colorMapOverride: projectedAuditColorMap(layout.colorMapOverride, 'imported layout colorMapOverride') } : {}),
			...(placeholders.length ? { placeholders } : {}),
			...(objects.length ? { objects } : {}),
		}
	})
	return {
		theme: projectedAuditTheme(audit.theme),
		layouts,
		masters,
		layoutNames,
		layoutNamesByRaw,
		masterNames,
		masterNamesByRaw,
		layoutsByNumber: new Map(selectedLayouts.map(layout => [Number(layout?.number), layout])),
		slideBindings,
		multipleMasterScopePreservedOnly: (audit.masters || []).length > 1,
	}
}

function exportedNativeCarrierDefinition(carrier = {}, kind = 'layout', activeLayout = '') {
	const dimensions = nativeCarrierDimensions(carrier)
	if (!dimensions) return null
	const placeholders = exportedNativePlaceholderDefinitions(carrier)
	const objects = exportedNativeOwnedObjects(carrier)
	const common = {
		...(carrier.background !== undefined && carrier.background !== null ? { background: cloneForResult(carrier.background) } : {}),
		...(carrier._margin !== undefined ? { margin: cloneForResult(carrier._margin) } : {}),
		...(carrier._slideNumberProps ? { slideNumber: cloneForResult(carrier._slideNumberProps) } : {}),
		...(carrier._headerFooter ? { headerFooter: cloneForResult(carrier._headerFooter) } : {}),
		...(placeholders.length ? { placeholders } : {}),
		...(objects.length ? { objects } : {}),
	}
	if (kind === 'master') return {
		title: String(carrier._name || 'Master'),
		...common,
		...(carrier._colorMap ? { colorMap: cloneForResult(carrier._colorMap) } : {}),
		...(carrier._textStyles ? { textStyles: cloneForResult(carrier._textStyles) } : {}),
	}
	return {
		name: String(carrier._name || 'Layout'),
		...dimensions,
		...(carrier._presLayout?.type ? { type: String(carrier._presLayout.type) } : {}),
		...common,
		...(carrier._betterpptxMasterName ? { masterName: String(carrier._betterpptxMasterName) } : {}),
		...(carrier._colorMapOverride ? { colorMapOverride: cloneForResult(carrier._colorMapOverride) } : {}),
		activate: String(carrier._name || '') === activeLayout,
	}
}

function exportedLayoutDefinitions(pptx = {}, authoredLayouts = [], importedProjection = null) {
	const layout = String(pptx.layout || '')
	const authoredNames = new Set((authoredLayouts || []).map(item => String(item?.name || '')).filter(Boolean))
	const native = (pptx.slideLayouts || [])
		.filter(item => item?._betterpptxCarrierKind === 'layout' || authoredNames.has(String(item?._name || '')))
		.map(item => exportedNativeCarrierDefinition(item, 'layout', layout))
		.filter(Boolean)
	if (native.length) return native
	if (importedProjection?.layouts?.length) return cloneForResult(importedProjection.layouts)
	const activeLayout = pptx.presLayout || pptx._presLayout || pptx.LAYOUTS?.[layout] || null
	const widthEmu = Number(activeLayout?.width || activeLayout?._sizeW || 0)
	const heightEmu = Number(activeLayout?.height || activeLayout?._sizeH || 0)
	const exactLayout = Number.isFinite(widthEmu) && widthEmu > 0 && Number.isFinite(heightEmu) && heightEmu > 0
		? {
			width: Number((widthEmu / 914400).toFixed(6)),
			height: Number((heightEmu / 914400).toFixed(6)),
			...(activeLayout?.type ? { type: String(activeLayout.type) } : {}),
		}
		: null
	if (/^imported_\d+x\d+$/i.test(layout) && exactLayout) {
		return [{
			name: layout,
			...exactLayout,
			activate: true,
		}]
	}
	if (layout && !['LAYOUT_4x3', 'LAYOUT_16x9', 'LAYOUT_16x10', 'LAYOUT_WIDE'].includes(layout) && exactLayout) {
		return [{ name: layout, ...exactLayout, activate: true }]
	}
	return []
}

function exportedMasterDefinitions(pptx = {}, authoredMasters = [], importedProjection = null) {
	const authoredNames = new Set((authoredMasters || []).map(item => String(item?.title || item?.name || '')).filter(Boolean))
	const physical = (pptx.slideMasters || [pptx.masterSlide])
		.filter(item => item?._betterpptxOwnedMaster || authoredNames.has(String(item?._betterpptxSemanticMasterName || item?._name || '')))
		.map(item => exportedNativeCarrierDefinition(item, 'master', String(pptx.layout || '')))
		.filter(Boolean)
	const logical = (pptx.slideLayouts || [])
		.filter(item => item?._betterpptxCarrierKind === 'master' || authoredNames.has(String(item?._name || '')))
		.map(item => exportedNativeCarrierDefinition(item, 'master', String(pptx.layout || '')))
		.filter(Boolean)
	const native = [...physical, ...logical.filter(item => !physical.some(master => master.title === item.title))]
	if (native.length) return native
	return importedProjection?.masters?.length ? cloneForResult(importedProjection.masters) : []
}

function preservationSnapshotObject(obj = {}) {
	const rawXml = obj.options?._rawSourceShapeXml
	if (typeof rawXml === 'string' && rawXml.trim()) {
		return {
			type: 'passthrough',
			_type: 'passthrough',
			options: {
				objectName: obj.options?.objectName || null,
				spid: obj.options?.spid,
				x: obj.options?.x,
				y: obj.options?.y,
				w: obj.options?.w,
				h: obj.options?.h,
				_decypherEditHandle: obj.options?._decypherEditHandle,
				_decypherEditability: obj.options?._decypherEditability,
				_passthroughOriginalType: _shapeKind(obj) || 'shape',
				_passthroughPreservation: 'raw-shape',
			},
			passthrough: { xml: rawXml },
		}
	}
	const cloned = cloneForResult(obj)
	if ((_shapeKind(cloned) === 'image' || cloned?._type === 'image') && cloned && typeof cloned === 'object') {
		const imageSource = cloned.path || cloned.image || cloned.options?.path
		if (typeof imageSource === 'string' && !/^asset:\/\/locked\//i.test(imageSource) && !/^data:image\//i.test(imageSource)) {
			try {
				const imagePath = path.resolve(imageSource)
				if (fsNode.existsSync(imagePath)) {
					const extn = path.extname(imagePath).replace(/^\./, '') || 'png'
					const locked = lockGeneratedAssetDescriptor(imagePath, 'image', {
						extn,
						mimeType: mimeForExt(extn),
					})
					if (cloned.path) cloned.path = locked.handle
					else cloned.image = locked.handle
					if (cloned.options?.path === imageSource) cloned.options.path = locked.handle
				}
			} catch (_) {}
		}
	}
	if ((_shapeKind(cloned) === 'media' || cloned?._type === 'media') && cloned && typeof cloned === 'object') {
		const mediaSource = cloned.media || cloned.path || cloned.options?.path
		if (typeof mediaSource === 'string' && !/^asset:\/\/locked\//i.test(mediaSource)) {
			try {
				const mediaPath = path.resolve(mediaSource)
				if (fsNode.existsSync(mediaPath)) {
					const locked = lockGeneratedAssetDescriptor(mediaPath, 'media', {
						extn: path.extname(mediaPath).replace(/^\./, '') || (cloned.mtype === 'audio' ? 'mp3' : 'mp4'),
						mimeType: cloned.mtype === 'audio' ? 'audio/mpeg' : 'video/mp4',
					})
					if (cloned.media) cloned.media = locked.handle
					else cloned.path = locked.handle
					if (cloned.options?.path === mediaSource) cloned.options.path = locked.handle
				}
			} catch (_) {}
		}
	}
	return cloned
}

function collectRawPackagePartGraphForSnapshot(pptx, rootPartPath, out = new Map()) {
	const normalized = normalizeZipPartPath(rootPartPath)
	if (!normalized || out.has(normalized)) return out
	const part = _rawPartByPath(pptx, normalized)
	if (!part) return out
	out.set(normalized, cloneForResult(part))
	const relsPath = relsPathForPart(normalized)
	const relsPart = _rawPartByPath(pptx, relsPath)
	if (relsPart && !out.has(relsPath)) {
		out.set(relsPath, cloneForResult(relsPart))
		for (const rel of parseRelationshipEntries(_getRawPartText(relsPart))) {
			if (rel.targetMode === 'External' || isExternalTarget(rel.target)) continue
			const child = resolvePackageTarget(normalized, rel.target)
			if (child) collectRawPackagePartGraphForSnapshot(pptx, child, out)
		}
	}
	return out
}

function rawDependenciesForPreservation(entry, slideIndex, snapshotObject, sourceObj = {}) {
	const slide = entry?.pptx?.slides?.[slideIndex]
	const ids = new Set(collectRelationshipIds(snapshotObject?.passthrough?.xml || ''))
	const rawSourceRels = Array.isArray(sourceObj?.options?._rawSourceRels) ? sourceObj.options._rawSourceRels : []
	const slideRawRels = Array.isArray(slide?._rawRels) ? slide._rawRels : []
	const rawRels = []
	const seenRelIds = new Set()
	for (const rel of [...rawSourceRels, ...slideRawRels.filter(item => ids.has(item.id))]) {
		if (!rel?.id || seenRelIds.has(rel.id)) continue
		seenRelIds.add(rel.id)
		rawRels.push(cloneForResult(rel))
	}
	const rawPackageParts = new Map()
	const slidePart = `ppt/slides/slide${slideIndex + 1}.xml`
	for (const rel of rawRels) {
		if (rel.targetMode === 'External' || isExternalTarget(rel.target)) continue
		const targetPart = resolvePackageTarget(slidePart, rel.target)
		if (targetPart) collectRawPackagePartGraphForSnapshot(entry.pptx, targetPart, rawPackageParts)
	}
	return {
		...(rawRels.length ? { rawRels } : {}),
		...(rawPackageParts.size ? { rawPackageParts: Array.from(rawPackageParts.values()) } : {}),
	}
}

function mergeRawPackagePartsForPreservation(pptx, rawPackageParts = []) {
	if (!Array.isArray(rawPackageParts) || !rawPackageParts.length) return 0
	pptx._rawPackageParts ||= []
	const existing = new Set(pptx._rawPackageParts.map(part => normalizeZipPartPath(part?.path || '')))
	let added = 0
	for (const part of rawPackageParts) {
		const normalized = normalizeZipPartPath(part?.path || '')
		if (!normalized || existing.has(normalized)) continue
		pptx._rawPackageParts.push(cloneForResult(part))
		existing.add(normalized)
		added++
	}
	return added
}

function nativePackagePreservationHandleForExport(deckId) {
	try {
		const entry = getDeck(deckId)
		const pptx = entry.pptx || {}
		const rawPackageParts = Array.isArray(pptx._rawPackageParts) ? pptx._rawPackageParts : []
		const rawSlideMasters = Array.isArray(pptx._rawSlideMasters) ? pptx._rawSlideMasters : []
		const rawPresentationFonts = Array.isArray(pptx._rawPresentationFonts) ? pptx._rawPresentationFonts : []
		const rawPresentationExtraRels = Array.isArray(pptx._rawPresentationExtraRels) ? pptx._rawPresentationExtraRels : []
		const rawRootExtraRels = Array.isArray(pptx._rawRootExtraRels) ? pptx._rawRootExtraRels : []
		const rawPresentationContentType = typeof pptx._rawPresentationContentType === 'string' ? pptx._rawPresentationContentType : ''
		const rawDefaultTextStyleXml = typeof pptx._rawDefaultTextStyleXml === 'string' ? pptx._rawDefaultTextStyleXml : ''
		if (!rawPackageParts.length && !rawSlideMasters.length && !rawPresentationFonts.length && !rawPresentationExtraRels.length && !rawRootExtraRels.length && !rawPresentationContentType && !rawDefaultTextStyleXml) return null
		const locked = lockOpaqueNativeSnapshot({
			deckId,
			slideIndex: -1,
			index: -1,
			objectName: 'deck.native-package',
			kind: 'nativePackage',
			object: { type: 'nativePackage', options: { objectName: 'deck.native-package' } },
			rawPackageParts,
			rawSlideMasters,
			rawPresentationFonts,
			rawPresentationExtraRels,
			rawRootExtraRels,
			rawPresentationContentType,
			rawDefaultTextStyleXml,
			createdAt: new Date().toISOString(),
		})
		const { handle, snapshot } = locked
		entry.opaqueNativePreservation ||= {}
		entry.opaqueNativePreservation[handle] = snapshot
		opaqueNativePreservationRegistry.set(handle, snapshot)
		return handle
	} catch (error) { if (enforceAssetOwnership()) throw error }
	return null
}

function preservationHandleForExport(deckId, slideIndex, index, obj = {}) {
	try {
		const entry = getDeck(deckId)
		const snapshotObject = preservationSnapshotObject(obj)
		const dependencies = rawDependenciesForPreservation(entry, slideIndex, snapshotObject, obj)
		// A CHART object's identity lives in TWO places: the graphicFrame (the object) and its
		// slide-level _relsChart relationship (rId + data + Target). Snapshot the rel too, or a
		// replay restores the frame pointing at a relationship that no longer exists (the frame's
		// r:id then resolves to whatever rel got that number — PowerPoint refuses the file).
		let chartRel = null
		if ((obj?._type === 'chart' || _shapeKind(obj) === 'chart') && Number.isFinite(Number(obj.chartRid))) {
			const slide = entry.pptx.slides[slideIndex]
			const rel = (slide?._relsChart || []).find(r => Number(r?.rId) === Number(obj.chartRid))
			if (rel) chartRel = cloneForResult(rel)
		}
		// GENERIC PAYLOAD PAIRING — any object whose payload lives in _relsMedia references it
		// via *Rid fields (model3dRid/rasterRid for 3D, fallbackRid for equations, imageRid…).
		// Capture those rels WITH the payload EMBEDDED (base64) so the preservation handle is
		// SELF-CONTAINED — the same handle principle authoring uses: handle → the restore
		// rebuilds frame + relationship + payload together, on any machine, foreign or ours.
		let mediaRels = null
		{
			const slide = entry.pptx.slides[slideIndex]
			const rids = []
			for (const [key, value] of Object.entries(obj || {})) {
				if (/^[a-z][A-Za-z]*Rid$/.test(key) && key !== 'chartRid' && Number.isFinite(Number(value))) rids.push(Number(value))
			}
			if (rids.length && Array.isArray(slide?._relsMedia)) {
				const captured = []
				for (const rid of rids) {
					const rel = slide._relsMedia.find(r => Number(r?.rId) === rid)
					if (!rel) continue
					const clone = cloneForResult(rel)
					if ((!clone.data || !String(clone.data).trim()) && clone.path) {
						try { clone.data = fsNode.readFileSync(clone.path).toString('base64') } catch { /* payload stays path-less; restore falls back */ }
					}
					delete clone.path   // never persist local paths inside a locked snapshot
					if (clone.data && String(clone.data).trim()) captured.push(clone)
				}
				if (captured.length) mediaRels = captured
			}
		}
		// A native SMARTART object spans the graphicFrame + FIVE diagram relationships (_rawRels)
		// + the diagram payload parts (_nativePackageParts). Snapshot all of it, or a replay
		// restores a frame whose r:dm/lo/qs/cs pointers resolve to unrelated relationships.
		let smartArtRels = null
		let smartArtParts = null
		if (obj?._type === 'smartart' && obj.smartArt) {
			const slide = entry.pptx.slides[slideIndex]
			const rids = new Set([obj.smartArt.dataRid, obj.smartArt.layoutRid, obj.smartArt.quickStyleRid, obj.smartArt.colorStyleRid, obj.smartArt.drawingRid].filter(Boolean))
			const rels = (slide?._rawRels || []).filter(r => rids.has(r?.id))
			if (rels.length) smartArtRels = cloneForResult(rels)
			const partIndexMatch = String((rels[0] || {}).target || '').match(/(\d+)\.xml$/)
			const partIndex = partIndexMatch ? partIndexMatch[1] : null
			if (partIndex) {
				const partRe = new RegExp(`^ppt/diagrams/(?:_rels/)?(?:data|layout|quickStyle|colors|drawing)${partIndex}\\.xml(?:\\.rels)?$`)
				const parts = (slide?._nativePackageParts || []).filter(p => partRe.test(String(p?.path || '')))
				if (parts.length) smartArtParts = cloneForResult(parts)
			}
		}
		const locked = lockOpaqueNativeSnapshot({
			deckId,
			slideIndex,
			index,
			objectName: obj.options?.objectName || null,
			kind: snapshotObject?.type || snapshotObject?._type || _shapeKind(obj) || 'unknown',
			object: snapshotObject,
			...(chartRel ? { chartRel } : {}),
			...(smartArtRels ? { smartArtRels } : {}),
			...(smartArtParts ? { smartArtParts } : {}),
			...(mediaRels ? { mediaRels } : {}),
			...dependencies,
			createdAt: new Date().toISOString(),
		})
		const { handle, snapshot } = locked
		entry.opaqueNativePreservation ||= {}
		entry.opaqueNativePreservation[handle] = snapshot
		opaqueNativePreservationRegistry.set(handle, snapshot)
		return handle
	} catch (error) { if (enforceAssetOwnership()) throw error }
	const fallback = JSON.stringify({
		deckId,
		slideIndex,
		index,
		objectName: obj.options?.objectName || null,
		kind: _shapeKind(obj) || 'unknown',
		source: obj.options?._decypherEditHandle?.id || null,
	})
	const digest = crypto.createHash('sha256').update(fallback).digest('hex').slice(0, 32)
	return `opaque://betterpptx/${digest}`
}

function isValidMarginValue(value) {
	if (value === undefined || value === null) return true
	if (typeof value === 'number' && Number.isFinite(value) && value >= 0) return true
	return Array.isArray(value) && value.length === 4 && value.every(item => typeof item === 'number' && Number.isFinite(item) && item >= 0)
}

function cloneOpaqueNativeObjectForInsertion(snapshot, args = {}) {
	if (!snapshot?.object) {
		const err = new Error('Opaque native preservation handle is not available.')
		err.code = 'OPAQUE_NATIVE_HANDLE_UNAVAILABLE'
		throw err
	}
	const obj = cloneForResult(snapshot.object)
	obj.options ||= {}
	if (!isValidMarginValue(obj.options.margin)) delete obj.options.margin
	if (args.objectName) obj.options.objectName = args.objectName
	const rect = args.rect && typeof args.rect === 'object' ? args.rect : null
	if (rect) {
		for (const key of ['x', 'y', 'w', 'h']) {
			if (rect[key] !== undefined) obj.options[key] = rect[key]
		}
	}
	const style = args.style && typeof args.style === 'object' ? args.style : null
	if (style) {
		for (const key of ['fill', 'line', 'color', 'transparency', 'rotate', 'shadow', 'glow', 'reflection', 'softEdges']) {
			if (style[key] !== undefined) obj.options[key] = style[key]
		}
	}
	return obj
}

async function handlePreserveOpaqueNative(args = {}) {
	const slide = getSlide(args.deckId, args.slideIndex)
	const handle = String(args.preservationHandle || '').trim()
	if (!handle) {
		const err = new Error('opaqueNative preservation requires preservationHandle.')
		err.code = 'OPAQUE_NATIVE_HANDLE_REQUIRED'
		throw err
	}
	if (args.delete === true) {
		return {
			ok: true,
			slideIndex: args.slideIndex,
			preservationHandle: handle,
			action: 'delete-skipped-during-regeneration',
		}
	}
	const entry = getDeck(args.deckId)
	const snapshot = await authorizedOpaqueNativeSnapshot(entry, handle)
	mergeRawPackagePartsForPreservation(entry.pptx, snapshot?.rawPackageParts)
	if (Array.isArray(snapshot?.rawRels) && snapshot.rawRels.length) {
		slide._rawRels ||= []
		const existing = new Set(slide._rawRels.map(rel => rel?.id).filter(Boolean))
		for (const rel of snapshot.rawRels) {
			if (!rel?.id || existing.has(rel.id)) continue
			slide._rawRels.push(cloneForResult(rel))
			existing.add(rel.id)
		}
	}
	const obj = cloneOpaqueNativeObjectForInsertion(snapshot, args)
	// SELF-CONTAINED PAYLOAD restore — the snapshot carried the object's _relsMedia rels with
	// their bytes embedded (model3d GLB + poster, equation raster, images). Re-link them with
	// fresh rIds and a collision-free target namespace, rewrite the object's *Rid pointers,
	// and the frame + relationship + payload land TOGETHER (audio/video media objects keep
	// their dedicated branch below: their playback trio needs contiguous rIds by construction).
	if (Array.isArray(snapshot?.mediaRels) && snapshot.mediaRels.length && obj?._type !== 'media' && _shapeKind(obj) !== 'media') {
		const nextRelIdLocal = s => {
			let max = 0
			for (const r of s._rels || []) max = Math.max(max, Number(r?.rId) || 0)
			for (const r of s._relsChart || []) max = Math.max(max, Number(r?.rId) || 0)
			for (const r of s._relsMedia || []) max = Math.max(max, Number(r?.rId) || 0)
			for (const r of s._rawRels || []) {
				const n = String(r?.id || '').startsWith('rId') ? Number(String(r.id).substring(3)) : Number(r?.id)
				if (Number.isFinite(n)) max = Math.max(max, n)
			}
			return max + 1
		}
		slide._relsMedia ||= []
		const idMap = new Map()
		for (const relSnap of snapshot.mediaRels) {
			const rel = cloneForResult(relSnap)
			const oldId = Number(rel.rId)
			rel.rId = nextRelIdLocal(slide)
			const extn = rel.extn || String(rel.Target || '').split('.').pop() || 'bin'
			rel.Target = `../media/preserved-${args.slideIndex + 1}-${slide._relsMedia.length + 1}.${extn}`
			delete rel.isDuplicate
			slide._relsMedia.push(rel)
			idMap.set(oldId, rel.rId)
		}
		for (const [key, value] of Object.entries(obj)) {
			if (/^[a-z][A-Za-z]*Rid$/.test(key) && idMap.has(Number(value))) obj[key] = idMap.get(Number(value))
		}
		slide._slideObjects ||= []
		slide._slideObjects.push(obj)
		return {
			ok: true,
			slideIndex: args.slideIndex,
			preservationHandle: handle,
			objectName: obj.options?.objectName || snapshot.objectName,
			kind: snapshot.kind,
			action: 'preserved',
		}
	}
	if ((_shapeKind(obj) === 'image' || obj?._type === 'image') && typeof slide.addImage === 'function') {
		const imageSource = obj.path || obj.image || obj.options?.path
		if (!imageSource && !obj.data) {
			const err = new Error('Opaque image preservation handle is missing its locked image asset.')
			err.code = 'OPAQUE_IMAGE_ASSET_MISSING'
			throw err
		}
		const imageOpts = {
			...(obj.options || {}),
		}
		if (imageSource) imageOpts.path = resolveGeneratedAssetRefs(imageSource)
		else if (obj.data) imageOpts.data = obj.data
		slide.addImage(imageOpts)
		const inserted = slide._slideObjects?.[slide._slideObjects.length - 1] || obj
		return {
			ok: true,
			slideIndex: args.slideIndex,
			preservationHandle: handle,
			objectName: inserted.options?.objectName || obj.options?.objectName || snapshot.objectName,
			kind: snapshot.kind,
			action: 'preserved',
		}
	}
	if ((_shapeKind(obj) === 'media' || obj?._type === 'media') && typeof slide.addMedia === 'function') {
		const mediaSource = obj.media || obj.path || obj.options?.path
		if (!mediaSource) {
			const err = new Error('Opaque media preservation handle is missing its locked media asset.')
			err.code = 'OPAQUE_MEDIA_ASSET_MISSING'
			throw err
		}
		const mediaOpts = {
			...(obj.options || {}),
			type: obj.mtype === 'audio' ? 'audio' : 'video',
			path: resolveGeneratedAssetRefs(mediaSource),
		}
		if (mediaOpts.cover) mediaOpts.cover = resolveGeneratedAssetRefs(mediaOpts.cover)
		slide.addMedia(mediaOpts)
		const inserted = slide._slideObjects?.[slide._slideObjects.length - 1] || obj
		return {
			ok: true,
			slideIndex: args.slideIndex,
			preservationHandle: handle,
			objectName: inserted.options?.objectName || obj.options?.objectName || snapshot.objectName,
			kind: snapshot.kind,
			action: 'preserved',
		}
	}
	const nextRelId = s => {
		let max = 0
		for (const r of s._rels || []) max = Math.max(max, Number(r?.rId) || 0)
		for (const r of s._relsChart || []) max = Math.max(max, Number(r?.rId) || 0)
		for (const r of s._relsMedia || []) max = Math.max(max, Number(r?.rId) || 0)
		for (const r of s._rawRels || []) {
			const n = String(r?.id || '').startsWith('rId') ? Number(String(r.id).substring(3)) : Number(r?.id)
			if (Number.isFinite(n)) max = Math.max(max, n)
		}
		return max + 1
	}
	// SMARTART restore — re-link the FIVE diagram relationships + payload parts the snapshot
	// carried, renumbered (fresh rIds + a fresh diagram part index) so nothing collides with
	// live objects or raw-scaffold copies on the replay deck.
	if (obj?._type === 'smartart' && obj.smartArt && Array.isArray(snapshot?.smartArtRels) && snapshot.smartArtRels.length) {
		const pptx = entry.pptx
		const usedIdx = []
		const scanIdx = p => { const m = String(p || '').match(/^ppt\/diagrams\/data(\d+)\.xml$/); if (m) usedIdx.push(Number(m[1])) }
		for (const s of pptx.slides) for (const part of s._nativePackageParts || []) scanIdx(part?.path)
		for (const part of pptx._rawPackageParts || []) scanIdx(part?.path)
		const newIdx = Math.max(0, ...usedIdx) + 1
		const startRid = nextRelId(slide)
		const oldRels = cloneForResult(snapshot.smartArtRels)
		const idMap = new Map()
		slide._rawRels ||= []
		oldRels.forEach((rel, i) => {
			const newId = `rId${startRid + i}`
			idMap.set(rel.id, newId)
			const newTarget = String(rel.target || '').replace(/(\d+)(\.xml)$/, `${newIdx}$2`)
			slide._rawRels.push({ id: newId, type: rel.type, target: newTarget })
		})
		const parts = cloneForResult(snapshot.smartArtParts || [])
		slide._nativePackageParts = slide._nativePackageParts || []
		for (const part of parts) {
			part.path = String(part.path || '').replace(/(\d+)(\.xml(?:\.rels)?)$/, `${newIdx}$2`)
			slide._nativePackageParts.push(part)
		}
		obj.smartArt = { ...obj.smartArt, partIndex: newIdx }
		for (const key of ['dataRid', 'layoutRid', 'quickStyleRid', 'colorStyleRid', 'drawingRid']) {
			if (idMap.has(obj.smartArt[key])) obj.smartArt[key] = idMap.get(obj.smartArt[key])
		}
		slide._slideObjects ||= []
		slide._slideObjects.push(obj)
		return {
			ok: true,
			slideIndex: args.slideIndex,
			preservationHandle: handle,
			objectName: obj.options?.objectName || snapshot.objectName,
			kind: snapshot.kind,
			action: 'preserved',
		}
	}
	// CHART restore — re-link the slide-level chart relationship the snapshot carried, with a
	// FRESH rId + globalId/Target so nothing collides on the replay deck; the chart XML then
	// regenerates from the rel's data at save (semantic regeneration, no raw-part collision).
	if ((obj?._type === 'chart' || _shapeKind(obj) === 'chart') && snapshot?.chartRel) {
		const pptx = entry.pptx
		const usedGlobalIds = pptx.slides.flatMap(s => (s._relsChart || []).map(r => Number(r?.globalId) || 0))
		const globalId = Math.max(0, ...usedGlobalIds) + 1
		const rel = cloneForResult(snapshot.chartRel)
		rel.rId = nextRelId(slide)
		rel.globalId = globalId
		rel.fileName = `${rel.chartFamily === 'chartEx' ? 'chartEx' : 'chart'}${globalId}.xml`
		rel.Target = `../charts/${rel.fileName}`
		slide._relsChart ||= []
		slide._relsChart.push(rel)
		obj.chartRid = rel.rId
		slide._slideObjects ||= []
		slide._slideObjects.push(obj)
		return {
			ok: true,
			slideIndex: args.slideIndex,
			preservationHandle: handle,
			objectName: obj.options?.objectName || snapshot.objectName,
			kind: snapshot.kind,
			action: 'preserved',
		}
	}
	if (_shapeKind(obj) === 'text' || _shapeKind(obj) === 'shape') _attachTextHyperlinkRelationships(slide, obj)
	slide._slideObjects ||= []
	slide._slideObjects.push(obj)
	return {
		ok: true,
		slideIndex: args.slideIndex,
		preservationHandle: handle,
		objectName: obj.options?.objectName || snapshot.objectName,
		kind: snapshot.kind,
		action: 'preserved',
	}
}

async function handlePreserveNativePackage(args = {}) {
	const entry = getDeck(args.deckId)
	const handle = String(args.preservationHandle || '').trim()
	if (!handle) {
		const err = new Error('native package preservation requires preservationHandle.')
		err.code = 'NATIVE_PACKAGE_HANDLE_REQUIRED'
		throw err
	}
	if (args.delete === true) {
		delete entry.pptx._rawPackageParts
		delete entry.pptx._rawSlideMasters
		delete entry.pptx._rawPresentationFonts
		delete entry.pptx._rawPresentationExtraRels
		delete entry.pptx._rawRootExtraRels
		delete entry.pptx._rawPresentationContentType
		delete entry.pptx._rawDefaultTextStyleXml
		return { ok: true, preservationHandle: handle, action: 'deleted' }
	}
	const snapshot = await authorizedOpaqueNativeSnapshot(entry, handle)
	if (!snapshot || snapshot.kind !== 'nativePackage') {
		const err = new Error('Native package preservation handle is not available.')
		err.code = 'NATIVE_PACKAGE_HANDLE_UNAVAILABLE'
		throw err
	}
	const rawPackagePartsAdded = mergeRawPackagePartsForPreservation(entry.pptx, snapshot.rawPackageParts)
	if (Array.isArray(snapshot.rawSlideMasters)) entry.pptx._rawSlideMasters = cloneForResult(snapshot.rawSlideMasters)
	if (Array.isArray(snapshot.rawPresentationFonts)) entry.pptx._rawPresentationFonts = cloneForResult(snapshot.rawPresentationFonts)
	if (Array.isArray(snapshot.rawPresentationExtraRels)) entry.pptx._rawPresentationExtraRels = cloneForResult(snapshot.rawPresentationExtraRels)
	if (Array.isArray(snapshot.rawRootExtraRels)) entry.pptx._rawRootExtraRels = cloneForResult(snapshot.rawRootExtraRels)
	if (typeof snapshot.rawPresentationContentType === 'string' && snapshot.rawPresentationContentType.trim()) entry.pptx._rawPresentationContentType = snapshot.rawPresentationContentType
	if (typeof snapshot.rawDefaultTextStyleXml === 'string' && snapshot.rawDefaultTextStyleXml.trim()) entry.pptx._rawDefaultTextStyleXml = snapshot.rawDefaultTextStyleXml
	return {
		ok: true,
		preservationHandle: handle,
		action: 'preserved',
		rawPackagePartsAdded,
		rawSlideMasters: Array.isArray(entry.pptx._rawSlideMasters) ? entry.pptx._rawSlideMasters.length : 0,
	}
}

function timingPreservationHandleForExport(deckId, slideIndex, slide = {}) {
	try {
		const entry = getDeck(deckId)
		const transitionXml = typeof slide._rawTransitionXml === 'string' ? slide._rawTransitionXml : ''
		const timingXml = typeof slide._rawTimingXml === 'string' ? slide._rawTimingXml : ''
		const slideExtLstXml = typeof slide._rawSlideExtLstXml === 'string' ? slide._rawSlideExtLstXml : ''
		if (!transitionXml.trim() && !timingXml.trim() && !slideExtLstXml.trim()) return null
		const locked = lockOpaqueNativeSnapshot({
			deckId,
			slideIndex,
			index: -1,
			objectName: `slide-${slideIndex + 1}.timing`,
			kind: 'nativeTiming',
			object: { type: 'nativeTiming', options: { objectName: `slide-${slideIndex + 1}.timing` } },
			transitionXml,
			timingXml,
			slideExtLstXml,
			// Carry the identity manifest so smart remap survives export_spec -> replay (plan §5).
			...(slide._nativeTimingManifest && typeof slide._nativeTimingManifest === 'object' ? { nativeTimingManifest: slide._nativeTimingManifest } : {}),
			createdAt: new Date().toISOString(),
		})
		const { handle, snapshot } = locked
		entry.opaqueNativePreservation ||= {}
		entry.opaqueNativePreservation[handle] = snapshot
		opaqueNativePreservationRegistry.set(handle, snapshot)
		return handle
	} catch (error) { if (enforceAssetOwnership()) throw error }
	const fallback = JSON.stringify({ deckId, slideIndex, kind: 'nativeTiming' })
	const digest = crypto.createHash('sha256').update(fallback).digest('hex').slice(0, 32)
	return `opaque://betterpptx/${digest}`
}

async function handlePreserveNativeTiming(args = {}) {
	const slide = getSlide(args.deckId, args.slideIndex)
	const handle = String(args.preservationHandle || '').trim()
	if (args.delete === true) {
		delete slide._rawTransitionXml
		delete slide._rawTimingXml
		delete slide._rawSlideExtLstXml
		return {
			ok: true,
			slideIndex: args.slideIndex,
			...(handle ? { preservationHandle: handle } : {}),
			action: 'deleted',
		}
	}
	if (!handle) {
		const err = new Error('native timing preservation requires preservationHandle.')
		err.code = 'NATIVE_TIMING_HANDLE_REQUIRED'
		throw err
	}
	const entry = getDeck(args.deckId)
	const snapshot = await authorizedOpaqueNativeSnapshot(entry, handle)
	if (!snapshot?.transitionXml && !snapshot?.timingXml && !snapshot?.slideExtLstXml) {
		const err = new Error('Native timing preservation handle is not available.')
		err.code = 'NATIVE_TIMING_HANDLE_UNAVAILABLE'
		throw err
	}
	if (snapshot.transitionXml) slide._rawTransitionXml = snapshot.transitionXml
	if (snapshot.timingXml && typeof slide.setRawTimingXml === 'function') slide.setRawTimingXml(snapshot.timingXml)
	else if (snapshot.timingXml) slide._rawTimingXml = snapshot.timingXml
	// Restore the identity manifest so smart remap works after replay (plan §5).
	if (snapshot.nativeTimingManifest && typeof snapshot.nativeTimingManifest === 'object') slide._nativeTimingManifest = snapshot.nativeTimingManifest
	if (snapshot.slideExtLstXml) slide._rawSlideExtLstXml = snapshot.slideExtLstXml
	return {
		ok: true,
		slideIndex: args.slideIndex,
		preservationHandle: handle,
		action: 'preserved',
	}
}

// M20 — STRUCTURED->SEMANTIC deepening for FOREIGN SmartArt. The diagram payload stays
// preserved with full fidelity; its MEANING (node texts, hierarchy, layout family) is
// extracted from the dgm dataModel part and OFFERED as a proposal so the AI can re-author
// the diagram the world way (a kind:"smartart" content block) instead of keeping it frozen.
function _smartArtPointText(inner) {
	const texts = []
	const re = /<a:t>([^<]*)<\/a:t>/g
	let match
	while ((match = re.exec(inner))) texts.push(match[1])
	return texts.join(' ').replace(/\s+/g, ' ').trim()
}

function _extractForeignSmartArtSemantics(slide, obj) {
	try {
		const dataRid = obj?.smartArt?.dataRid
		if (!dataRid) return null
		const rel = (slide?._rawRels || []).find(r => r?.id === dataRid)
		const partMatch = String(rel?.target || '').match(/data(\d+)\.xml$/)
		if (!partMatch) return null
		const part = (slide?._nativePackageParts || []).find(p => String(p?.path || '') === `ppt/diagrams/data${partMatch[1]}.xml`)
		if (!part?.data) return null
		const xml = part.encoding === 'base64' ? Buffer.from(part.data, 'base64').toString('utf8') : String(part.data)
		const points = new Map()
		let docId = null
		let layoutUrn = null
		const ptRe = /<dgm:pt\s+([^>]*?)>([\s\S]*?)<\/dgm:pt>/g
		let pt
		while ((pt = ptRe.exec(xml))) {
			const attrs = pt[1]
			const inner = pt[2]
			const modelId = (attrs.match(/modelId="([^"]+)"/) || [])[1]
			if (!modelId) continue
			const type = (attrs.match(/type="([^"]+)"/) || [])[1] || 'node'
			if (type === 'doc') {
				docId = modelId
				layoutUrn = (inner.match(/loTypeId="([^"]+)"/) || [])[1] || null
				continue
			}
			if (type !== 'node') continue
			points.set(modelId, { text: _smartArtPointText(inner), children: [] })
		}
		if (!points.size) return null
		const links = []
		const cxnRe = /<dgm:cxn\b[^>]*>/g
		let cxn
		while ((cxn = cxnRe.exec(xml))) {
			const tag = cxn[0]
			// dgm:cxn without an explicit type IS a parOf (parent-of) connection.
			const type = (tag.match(/\btype="([^"]+)"/) || [])[1] || 'parOf'
			if (type !== 'parOf') continue
			const srcId = (tag.match(/\bsrcId="([^"]+)"/) || [])[1]
			const destId = (tag.match(/\bdestId="([^"]+)"/) || [])[1]
			if (!srcId || !destId) continue
			links.push({ srcId, destId, srcOrd: Number((tag.match(/\bsrcOrd="([^"]+)"/) || [])[1] || 0) })
		}
		links.sort((a, b) => (a.srcId === b.srcId ? a.srcOrd - b.srcOrd : 0))
		const roots = []
		const attached = new Set()
		for (const link of links) {
			const child = points.get(link.destId)
			if (!child || attached.has(link.destId)) continue
			if (link.srcId === docId) {
				roots.push(child)
				attached.add(link.destId)
				continue
			}
			const parent = points.get(link.srcId)
			if (parent) {
				parent.children.push(child)
				attached.add(link.destId)
			}
		}
		for (const [id, point] of points) if (!attached.has(id)) roots.push(point)
		const shapeNode = point => ({ text: point.text, ...(point.children.length ? { children: point.children.map(shapeNode) } : {}) })
		const nodes = roots.map(shapeNode).filter(node => node.text || node.children)
		if (!nodes.length) return null
		return {
			layout: layoutUrn ? String(layoutUrn).split('/').pop() : null,
			...(layoutUrn ? { layoutUrn } : {}),
			nodeCount: points.size,
			nodes,
		}
	} catch {
		return null
	}
}

// M20 — table meaning PROPOSAL: header detection + per-column type inference over the
// exported cell texts. Never a verdict — the AI confirms by re-authoring rows/tableOptions.
function _deriveTableSemantics(rows) {
	try {
		if (!Array.isArray(rows) || rows.length < 2) return null
		const textOf = cell => (typeof cell === 'object' && cell !== null ? String(cell.text || '') : String(cell ?? ''))
		const grid = rows.map(row => (Array.isArray(row) ? row : []).map(textOf))
		const classify = value => {
			const v = String(value).trim()
			if (!v) return 'empty'
			if (/^[-+(]?[$€£¥]\s?-?[\d,.]+\)?$/.test(v) || /^[-+]?[\d,.]+\s?[$€£¥]$/.test(v)) return 'currency'
			if (/^[-+]?[\d,.]+\s?%$/.test(v)) return 'percent'
			if (/^[-+(]?\d[\d,.]*\)?$/.test(v)) return 'number'
			if (/^\d{4}-\d{2}-\d{2}$|^\d{1,2}[/.]\d{1,2}[/.]\d{2,4}$|^(?:Q[1-4]|FY)\s?\d{2,4}$/i.test(v)) return 'date'
			return 'text'
		}
		const body = grid.slice(1)
		const columnCount = Math.max(...grid.map(r => r.length))
		const columns = []
		for (let c = 0; c < columnCount; c += 1) {
			const counts = {}
			for (const row of body) {
				const kind = classify(row[c] ?? '')
				if (kind === 'empty') continue
				counts[kind] = (counts[kind] || 0) + 1
			}
			const type = Object.entries(counts).sort((a, b) => b[1] - a[1])[0]?.[0] || 'text'
			columns.push({ index: c, name: String(grid[0][c] || '').trim() || `column-${c + 1}`, type })
		}
		const headerRow = grid[0].some(v => String(v).trim())
			&& grid[0].every(v => ['text', 'empty'].includes(classify(v)))
			&& columns.some(col => !['text', 'empty'].includes(col.type))
		const totalsRow = /^(?:total|sum|subtotal|grand total)\b/i.test(String(grid[grid.length - 1][0] || '').trim())
		if (!headerRow && !totalsRow && columns.every(col => col.type === 'text')) return null
		return { headerRow, ...(totalsRow ? { totalsRow: true } : {}), columns, confidence: 'engine-proposal' }
	} catch {
		return null
	}
}

function _relationshipKindsForSlideObject(slide, obj = {}) {
	const rels = []
	const seen = new Set()
	const add = rel => {
		if (!rel) return
		const key = `${rel.id || rel.rId || ''}|${rel.type || ''}|${rel.target || rel.Target || ''}`
		if (seen.has(key)) return
		seen.add(key)
		rels.push(rel)
	}
	const ids = new Set(collectRelationshipIds(obj?.passthrough?.xml || ''))
	for (const rel of obj?.options?._rawSourceRels || []) add(rel)
	for (const rel of slide?._rawRels || []) if (ids.has(rel?.id)) add(rel)
	if (Number.isFinite(Number(obj?.chartRid))) {
		for (const rel of slide?._relsChart || []) if (Number(rel?.rId) === Number(obj.chartRid)) add(rel)
	}
	const smartArt = obj?.smartArt || {}
	const smartRids = new Set([smartArt.dataRid, smartArt.layoutRid, smartArt.quickStyleRid, smartArt.colorStyleRid, smartArt.drawingRid].filter(Boolean))
	for (const rel of slide?._rawRels || []) if (smartRids.has(rel?.id)) add(rel)
	for (const [key, value] of Object.entries(obj || {})) {
		if (!/^[a-z][A-Za-z]*Rid$/.test(key) || key === 'chartRid') continue
		for (const rel of slide?._relsMedia || []) if (Number(rel?.rId) === Number(value)) add(rel)
	}
	return _relationshipEdgeKinds(rels)
}

function opaqueNativeExportBlock({ deckId, slide, slideIndex, index, rawIndex, base, obj, kind, editHandle, editability }) {
	return {
		tier: kind === 'passthrough' ? 'opaqueNative' : 'preserved',
		block: {
			...base,
			kind: 'opaqueNative',
			preservationHandle: preservationHandleForExport(deckId, slideIndex, index, obj),
			visibleSummary: `${kind} object preserved from opened deck`,
			relationshipKinds: _relationshipKindsForSlideObject(slide, obj),
			editabilityTier: editability.tier,
			allowedEdits: editability.semantic ? ['retain', 'move', 'resize', 'recolor', 'delete'] : ['retain', 'move', 'resize', 'delete'],
		},
		editHandle: editHandle || _shapeEditHandle(obj, { index, rawIndex }),
		editability,
	}
}

const SEMANTIC_NATIVE_PRESERVATION_KINDS = new Set([
	'textBox',
	'textShape',
	'shape',
	'freeform',
	'customGeometry',
	'wordart',
	'text3d',
	'chart-panel',
	'table-panel',
	'image-feature',
	'media',
	'model3d',
	'equation',
	'smartart',
	'diagram',
])

function publicInteractiveActionEndpoint(endpoint) {
	if (!endpoint || typeof endpoint !== 'object' || Array.isArray(endpoint)) return endpoint === null ? null : undefined
	const out = { type: String(endpoint.type || '') }
	if (!out.type) return undefined
	for (const key of ['url', 'targetSlideId', 'jump', 'customShow', 'showAndReturn', 'tooltip', 'history', 'highlightClick', 'endSound']) {
		if (Object.prototype.hasOwnProperty.call(endpoint, key)) out[key] = cloneForResult(endpoint[key])
	}
	if (out.type === 'slide' && !out.targetSlideId && Number.isInteger(Number(endpoint.targetSlide)) && Number(endpoint.targetSlide) > 0) {
		out.targetSlideId = `slide-${Number(endpoint.targetSlide)}`
	}
	if (endpoint.sound && typeof endpoint.sound === 'object') {
		const source = String(endpoint.sound.source || '')
		if (source) out.sound = {
			source,
			format: 'wav',
			...(endpoint.sound.name ? { name: String(endpoint.sound.name) } : {}),
		}
	}
	return out
}

function publicInteractiveActionsFromOptions(options = {}) {
	if (!Object.prototype.hasOwnProperty.call(options, 'interactiveActions')) return undefined
	const value = options.interactiveActions
	if (value === null) return null
	if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined
	if (Object.prototype.hasOwnProperty.call(value, 'type')) return publicInteractiveActionEndpoint(value)
	const out = {}
	for (const trigger of ['click', 'hover']) {
		if (!Object.prototype.hasOwnProperty.call(value, trigger)) continue
		out[trigger] = publicInteractiveActionEndpoint(value[trigger])
	}
	return Object.keys(out).length ? out : undefined
}

const ACTION_BUTTON_SHAPE_NAMES = new Set([
	'actionButtonBackPrevious',
	'actionButtonBeginning',
	'actionButtonBlank',
	'actionButtonDocument',
	'actionButtonEnd',
	'actionButtonForwardNext',
	'actionButtonHelp',
	'actionButtonHome',
	'actionButtonInformation',
	'actionButtonMovie',
	'actionButtonReturn',
	'actionButtonSound',
])

function objectToExportSpecBlock({ deckId, pptx, slide, slideIndex, index, rawIndex, obj }) {
	const opts = obj.options || {}
	const kind = _shapeKind(obj) || 'unknown'
	const isActionButtonShape = ACTION_BUTTON_SHAPE_NAMES.has(obj.shape || opts.shapeName)
	const objectName = opts.objectName || `slide${slideIndex + 1}.object${index + 1}`
	const editHandle = _shapeEditHandle(obj, { index, rawIndex })
	const editability = _shapeEditability(obj, { index, rawIndex })
	const bbox = opts._nativePlaceholderInheritance === true ? null : (kind === 'table' ? exportedPortableTableBbox(opts) : exportedBbox(opts))
	const preserveGeometry = opts._nativePlaceholderInheritance === true ? false : exportedBboxAnomalous(bbox, pptx, kind)
	const placeholderBinding = exportedPlaceholderBinding(opts)
	const interactiveAction = publicInteractiveActionsFromOptions(opts)
	const objectHyperlink = opts.hyperlink && typeof opts.hyperlink === 'object' ? _sanitizeOpts(opts.hyperlink) : opts.hyperlink
	const base = {
		name: objectName,
		objectName,
		editHandle: editHandle.id,
		...(preserveGeometry ? { preserveGeometry: true } : bbox ? { bbox } : {}),
		...(placeholderBinding ? { placeholderBinding } : {}),
		...(interactiveAction !== undefined ? { action: interactiveAction } : {}),
		...(objectHyperlink !== undefined ? { hyperlink: objectHyperlink } : {}),
		...publicAccessibilityMetadataFromOptions(opts),
	}
	const style = exportedStyle(opts)
	delete style.hyperlink
	if (preserveGeometry) {
		return opaqueNativeExportBlock({ deckId, pptx, slide, slideIndex, index, rawIndex, base, obj, kind, editHandle, editability })
	}
	const rawSourceStructured = exportedRawSourceStructuredFields(obj)
	if (rawSourceStructured) {
		return {
			tier: 'structured',
			block: {
				...base,
				kind: rawSourceStructured.kind,
				visibleSummary: `${rawSourceStructured.kind} promoted from opened deck raw source`,
				...rawSourceStructured.fields,
				...(Object.keys(style).length ? { style } : {}),
			},
			editHandle,
			editability: {
				...editability,
				tier: 'promotable',
				semantic: true,
				tools: Array.from(new Set([...(editability.tools || []), 'betterpptx.deck.generate_from_spec'])),
			},
		}
	}
	if (kind === 'text' && !isActionButtonShape) {
		return {
			tier: 'semantic',
			block: {
				...base,
				kind: 'textBox',
				text: exportedTextSource(obj),
				...(Object.keys(style).length ? { style } : {}),
			},
			editHandle,
			editability,
		}
	}
	if (kind === 'zoom') {
		const zoomRel = (slide?._rels || []).find(rel => Number(rel?.rId) === Number(opts._zoomSlideRid) && String(rel?.data || '').toLowerCase() === 'slide')
		const targetSlideNumber = Number(zoomRel?.Target || (Number(opts._zoomSldId) - 255))
		const targetSlideId = String(opts._betterpptxZoomTargetSlideId || pptx?.slides?.[targetSlideNumber - 1]?._betterpptxSemanticId || '')
		if (!targetSlideId) return opaqueNativeExportBlock({ deckId, pptx, slide, slideIndex, index, rawIndex, base, obj, kind, editHandle, editability })
		return {
			tier: 'semantic',
			block: {
				...base,
				kind: 'slideZoom',
				targetSlideId,
				returnToParent: Boolean(opts._zoomReturnToParent),
				transitionDur: Number.isFinite(Number(opts._zoomTransitionDur)) ? Number(opts._zoomTransitionDur) : 1000,
				...(typeof opts._betterpptxZoomThumbnailDataUri === 'string' ? { thumbnailDataUri: opts._betterpptxZoomThumbnailDataUri } : {}),
			},
			editHandle,
			editability,
		}
	}
	if (kind === 'sectionZoom') {
		const targetSectionId = sectionZoomTargetSectionId(pptx, obj)
		if (!targetSectionId) return opaqueNativeExportBlock({ deckId, pptx, slide, slideIndex, index, rawIndex, base, obj, kind, editHandle, editability })
		return {
			tier: 'semantic',
			block: {
				...base,
				kind: 'sectionZoom',
				targetSectionId,
				transitionDur: Number.isFinite(Number(opts._zoomTransitionDur)) ? Number(opts._zoomTransitionDur) : 1000,
				...(typeof opts._betterpptxZoomThumbnailDataUri === 'string' ? { thumbnailDataUri: opts._betterpptxZoomThumbnailDataUri } : {}),
			},
			editHandle,
			editability,
		}
	}
	if (kind === 'group') {
		const group = obj.group || opts
		const children = exportedNativeGroupChildren(Array.isArray(group.children) ? group.children : [], objectName)
		return {
			tier: 'semantic',
			block: {
				...base,
				kind: 'group',
				children,
				...(group.chOff ? { chOff: cloneForResult(group.chOff) } : {}),
				...(group.chExt ? { chExt: cloneForResult(group.chExt) } : {}),
				...(group.rotate !== undefined ? { rotate: group.rotate } : {}),
				...(group.rotation !== undefined ? { rotation: group.rotation } : {}),
			},
			editHandle,
			editability,
		}
	}
	if (kind === 'shape' && (obj.shape === 'custGeom' || opts.shapeName === 'custGeom')) {
		return {
			tier: 'semantic',
			block: {
				...base,
				kind: 'freeform',
				...(Array.isArray(opts.points) ? { points: cloneForResult(opts.points) } : {}),
				...(Array.isArray(opts.paths) ? { paths: cloneForResult(opts.paths) } : {}),
				...(opts.booleanOperation ? { booleanOperation: opts.booleanOperation } : {}),
				...(Object.keys(style).length ? { style } : {}),
			},
			editHandle,
			editability,
		}
	}
	if (kind === 'shape' || kind === 'freeform' || isActionButtonShape) {
		return {
			tier: 'semantic',
			block: {
				...base,
				kind: kind === 'freeform' ? 'freeform' : 'shape',
				shapeName: obj.shape || opts.shapeName,
				...(Object.keys(style).length ? { style } : {}),
			},
			editHandle,
			editability,
		}
	}
	if (kind === 'connector') {
		const connector = obj.connector || opts
		const connectorState = recoverConnectorStyleState(connector)
		const connectorReadback = connectorStylePublicReadback(connectorState)
		const connectorStyle = { ...exportedStyle(connector), ...connectorEffectsPublicReadback(connector) }
		// Effective line values are serializer state, not the public authored
		// patch. Expose only the sparse override carrier so a semantic export can
		// be recompiled without accidentally pinning preset defaults.
		if (connectorReadback) {
			delete connectorStyle.line
			if (Object.keys(connectorReadback.line || {}).length) connectorStyle.line = connectorReadback.line
		}
		return {
			tier: 'semantic',
			block: {
				...base,
				kind: 'connector',
				connectorType: connector.connectorType || 'straightConnector1',
				...(connector.routing ? { routing: connector.routing } : {}),
				...(connectorReadback ? { connectorStylePresetId: connectorReadback.connectorStylePresetId } : {}),
				...(connector.startShapeId !== undefined ? { startShapeId: connector.startShapeId } : {}),
				...(connector.startConnectionIndex !== undefined ? { startConnectionIndex: connector.startConnectionIndex } : {}),
				...(connector.endShapeId !== undefined ? { endShapeId: connector.endShapeId } : {}),
				...(connector.endConnectionIndex !== undefined ? { endConnectionIndex: connector.endConnectionIndex } : {}),
				...(Object.keys(connectorStyle).length ? { style: connectorStyle } : {}),
			},
			editHandle,
			editability,
		}
	}
	if (kind === 'passthrough') {
		const promoted = exportedPassthroughStructuredFields({ pptx, slide, slideIndex, obj })
		if (promoted) {
			return {
				tier: 'structured',
				block: {
					...base,
					kind: promoted.kind,
					visibleSummary: `${promoted.kind} promoted from opened deck passthrough`,
					...promoted.fields,
					...(Object.keys(style).length ? { style } : {}),
				},
				editHandle,
				editability: {
					...editability,
					tier: 'promotable',
					semantic: true,
					tools: Array.from(new Set([...(editability.tools || []), 'betterpptx.deck.generate_from_spec'])),
				},
			}
		}
	}
	if (['chart', 'table', 'image', 'media', 'model3d', 'equation', 'smartart'].includes(kind) && editability.semantic === true) {
		const kindMap = {
			chart: 'chart-panel',
			table: 'table-panel',
			image: 'image-feature',
			media: 'media',
			model3d: 'model3d',
			equation: 'equation',
			smartart: 'smartart',
		}
		const structuredFields = kind === 'chart' ? exportedChartBlockFields(slide, obj)
			: kind === 'table' ? exportedTableBlockFields(obj)
				: kind === 'smartart' ? exportedSmartArtBlockFields(obj)
					: kind === 'equation' ? exportedEquationBlockFields(obj)
						: kind === 'media' ? exportedMediaBlockFields(slide, obj)
							: kind === 'image' ? exportedImageBlockFields(obj)
								: kind === 'model3d' ? exportedModel3DBlockFields(obj)
									: null
		if (['chart', 'table', 'smartart', 'equation', 'media', 'image', 'model3d'].includes(kind) && !structuredFields) {
			const preservedBlock = opaqueNativeExportBlock({ deckId, pptx, slide, slideIndex, index, rawIndex, base, obj, kind, editHandle, editability })
			// M20 — a FOREIGN diagram exports preserved (exact form) AND carries its extracted
			// meaning as a proposal, so the AI can re-author it semantically via elevate/spec.
			if (kind === 'smartart') {
				const semantics = _extractForeignSmartArtSemantics(slide, obj)
				if (semantics) {
					preservedBlock.block.smartArtSemantics = {
						...semantics,
						confidence: 'engine-proposal',
						reauthorVia: 'Replace this preserved object with a kind:"smartart" content block using these nodes (elevate then restyles it the world way), or keep the preservationHandle to retain the exact original.',
					}
				}
			}
			return preservedBlock
		}
		const tableSemantics = kind === 'table' && structuredFields?.rows ? _deriveTableSemantics(structuredFields.rows) : null
		return {
			tier: 'structured',
			block: {
				...base,
				kind: kindMap[kind],
				visibleSummary: `${kind} object exported from opened deck`,
				// An exported native image/media frame is already the complete
				// object. Recompilation must not synthesize a same-named World frame
				// behind it, which would duplicate its edit identity and reading-order
				// carrier.
				...(['image', 'media'].includes(kind) ? { noFrame: true } : {}),
				...(structuredFields || {}),
				...(tableSemantics ? { tableSemantics } : {}),
				...(Object.keys(style).length ? { style } : {}),
			},
			editHandle,
			editability,
		}
	}
	return {
		tier: kind === 'passthrough' ? 'opaqueNative' : 'preserved',
		block: {
			...base,
			kind: 'opaqueNative',
			preservationHandle: preservationHandleForExport(deckId, slideIndex, index, obj),
			visibleSummary: `${kind} object preserved from opened deck`,
			editabilityTier: editability.tier,
			allowedEdits: editability.semantic ? ['retain', 'move', 'resize', 'recolor', 'delete'] : ['retain', 'move', 'resize', 'delete'],
		},
		editHandle,
		editability,
	}
}

function uniqueExportObjectName(objectName, seen) {
	const base = String(objectName || 'object').trim() || 'object'
	if (!seen.has(base)) {
		seen.add(base)
		return { objectName: base, duplicate: false }
	}
	for (let suffix = 2; suffix < 10000; suffix += 1) {
		const candidate = `${base}.${suffix}`
		if (!seen.has(candidate)) {
			seen.add(candidate)
			return { objectName: candidate, duplicate: true, originalObjectName: base }
		}
	}
	const fallback = `${base}.${crypto.randomBytes(4).toString('hex')}`
	seen.add(fallback)
	return { objectName: fallback, duplicate: true, originalObjectName: base }
}

// R1 — reconstruct a slide's narration for LOSSLESS round-trip. New decks write the explicit
// [BetterPPTX-narration] ownership boundary; uploaded legacy decks using [narration] remain
// readable. Everything before the rubric is opaque user-owned notes and is never interpreted.
const BETTERPPTX_NARRATION_RUBRIC = '[BetterPPTX-narration]'
const LEGACY_NARRATION_RUBRIC = '[narration]'
const NARRATION_RUBRIC_PATTERN = /(^|\r?\n)[ \t]*\[(betterpptx-)?narration\][ \t]*(?:\r?\n|$)/gi

function _splitNarrationNotes(notesText) {
	const text = String(notesText || '')
	// The ownership delimiter is the final rubric line. Choosing the last match
	// makes the contract deterministic even if a user quoted the legacy token in
	// an earlier free-note paragraph: only the final block becomes narration.
	const matches = [...text.matchAll(NARRATION_RUBRIC_PATTERN)]
	const match = matches[matches.length - 1]
	if (!match) return { userNotes: text, narration: '', rubric: null, legacy: false }
	// The regex consumes the newline immediately before the marker. Canonical output owns one
	// additional separator newline, so remove exactly that one—not whitespace inside user notes.
	const userEnd = match.index
	const beforeMarker = text.slice(0, userEnd)
	return {
		userNotes: match[1] ? beforeMarker.replace(/\r?\n$/, '') : beforeMarker,
		narration: text.slice(match.index + match[0].length).trim(),
		rubric: match[2] ? BETTERPPTX_NARRATION_RUBRIC : LEGACY_NARRATION_RUBRIC,
		legacy: !match[2],
	}
}

function _composeNarrationNotes(userNotes, narration) {
	const user = String(userNotes || '')
	const script = String(narration || '').trim()
	if (!script) return user
	return `${user ? `${user}\n\n` : ''}${BETTERPPTX_NARRATION_RUBRIC}\n${script}`
}

function _extractNarrationScript(notesText) {
	return _splitNarrationNotes(notesText).narration
}
function exportedSlideNarration(entry, slideIndex) {
	const man = entry?.narrationManifest?.slides?.find(s => s.slideIndex === slideIndex)
	const script = _extractNarrationScript(_slideNotesText(entry.pptx.slides[slideIndex]))
	if (!script && !man) return null
	const narration = {}
	const norm = t => String(t || '').replace(/\s+/g, ' ').trim()
	// R-SEG — a segmented slide round-trips its REAL multi-clip structure (scripts + silences +
	// per-clip voices) from the manifest. Text is master: if the user edited the narration
	// rubric since the segments were built, the edited rubric wins and the slide exports as a
	// single re-splittable clip (the new pause boundaries are unknowable from prose).
	const manSegments = man?.segmented && Array.isArray(man.segments) ? man.segments.filter(s => s && String(s.script || '').trim()) : []
	const combined = manSegments.map(s => norm(s.script)).filter(Boolean).join(' ')
	if (manSegments.length && combined && (!script || norm(script) === combined)) {
			narration.segments = manSegments.map(s => ({
				script: String(s.script).trim(),
			...(narrationMs(s.gapBeforeMs) ? { gapBeforeMs: narrationMs(s.gapBeforeMs) } : {}),
			...(narrationMs(s.gapAfterMs) ? { gapAfterMs: narrationMs(s.gapAfterMs) } : {}),
				...(s.voiceId && s.voiceId !== man.voiceId ? { voice: s.voiceId } : {}),
				...(s.gender ? { gender: s.gender } : {}),
				...(s.speaker !== undefined ? { speaker: s.speaker } : {}),
			...(s.caption ? { caption: s.caption } : {}),
			...(Array.isArray(s.cues) && s.cues.length ? { cues: s.cues } : {}),
		}))
	} else if (script) {
		narration.script = script
	}
	// Hand-AUTHORED beats + captions round-trip as authored; auto-synced-build beats are NOT
	// exported — they are a derivation (Capability B) and re-derive against the replayed audio.
	if (Array.isArray(man?.authoredCues) && man.authoredCues.length) narration.cues = man.authoredCues
	if (man?.authoredCaptions) narration.captions = man.authoredCaptions
	if (man?.voiceId) narration.voice = man.voiceId
	if (man?.gender) narration.gender = man.gender
	if (man?.speaker !== undefined) narration.speaker = man.speaker
	const timing = {}
	if (man?.startDelayMs) timing.startDelayMs = man.startDelayMs
	if (man?.paddingMs !== undefined) timing.paddingMs = man.paddingMs
	if (Object.keys(timing).length) narration.timing = timing
	return Object.keys(narration).length ? narration : null
}

function exportedSlideRecordStudio(entry, slideIndex) {
	const slide = entry?.pptx?.slides?.[slideIndex]
	if (!slide) return null
	const capture = (slide._slideObjects || []).find(object => object?._type === 'media'
		&& String(object.mtype || '').toLowerCase() === 'video'
		&& object.options?._nativeRecordStudioCapture === true)
	if (!capture) return null
	const script = _extractNarrationScript(_slideNotesText(slide))
	const manifest = entry?.avatarManifest?.slides?.find(item => Number(item.slideIndex) === Number(slideIndex))
	const normalizedScript = String(script || '').replace(/\s+/g, ' ').trim()
	const currentHash = normalizedScript ? hashText(normalizedScript) : null
	const previousHash = manifest?.scriptHash || slide._nativeRecordStudioSession?.scriptHash || null
	const narrationChanged = Boolean(currentHash && previousHash && currentHash !== previousHash)
	return {
		enabled: true,
		objectName: String(capture.options?.objectName || `record-studio-capture-s${slideIndex + 1}`),
		script,
		nativeRecordStudio: true,
		reuseExisting: !narrationChanged,
		...(narrationChanged ? {
			replaceExistingRecordStudio: true,
			regenerationRequired: true,
			requiresCurrentSelfie: true,
			regenerationReason: 'The final BetterPPTX narration block changed; regenerate voice, presenter video, and authored timing from the edited text.',
		} : {}),
		notesOwnership: {
			canonicalFinalMarker: BETTERPPTX_NARRATION_RUBRIC,
			legacyReadableMarker: LEGACY_NARRATION_RUBRIC,
			beforeMarker: 'user-owned-opaque',
			afterMarker: 'betterpptx-owned-narration-source',
		},
	}
}

async function sourceSpecForBundle(deckId, mode = 'effectivePrecompile', deckVersion = null, specHandle = null) {
	// A fresh public client may already possess a submitted JSON-spec handle and
	// should be able to make a durable .betterpptx source bundle without first
	// compiling a narrated deck. This keeps source archival independent from
	// rendering/TTS availability while retaining the same locked-asset resolver.
	if (specHandle) {
		const submitted = await materializeJsonSpecHandle(specHandle)
		return {
			spec: cloneJson(submitted.spec),
			artifact: {
				stage: 'authorSubmittedSpec',
				sha256: submitted.rawSubmissionSha256,
				rawBytes: submitted.rawBytes,
				sourceKind: submitted.sourceKind,
			},
			source: 'assets.upload.jsonSpec',
		}
	}
	const entry = getDeck(deckId)
	const normalized = String(mode || 'effectivePrecompile').trim()
	if (normalized === 'current') {
		const exported = await handleExportSpec({ deckId, mode: 'current', detail: 'summary' })
		return { spec: exported.spec, artifact: null, source: 'deck.export_spec.current' }
	}
	const stageByMode = { authoredInput: 'authorSubmittedSpec', effectivePrecompile: 'effectivePrecompile' }
	const stage = stageByMode[normalized]
	if (!stage) {
		const err = new Error(`Unsupported source bundle mode ${normalized}.`)
		err.code = 'BUNDLE_EXPORT_MODE_UNSUPPORTED'
		err.details = { status: 'bundle_export_mode_unsupported', supportedModes: ['authoredInput', 'effectivePrecompile', 'current'] }
		throw err
	}
	const selected = [...(entry.specArtifactLineage || [])].reverse().find(item => item.stage === stage && (deckVersion == null || Number(item.deckVersion) === Number(deckVersion)))
	if (!selected) {
		const err = new Error(`No ${normalized} source artifact is available for the requested deck version.`)
		err.code = 'SPEC_ARTIFACT_NOT_FOUND'
		err.details = { status: 'spec_artifact_not_found', mode: normalized, deckVersion: deckVersion ?? null }
		throw err
	}
	let spec = selected.spec
	if (!spec && selected.sha256 && _deckSnapshotStore && !_deckSnapshotStore.disabled) spec = (await _deckSnapshotStore.getCanonicalSpec(selected.sha256)).spec
	if (!spec) {
		const err = new Error('The selected source artifact is unavailable for bundle export.')
		err.code = 'SPEC_ARTIFACT_CONTENT_UNAVAILABLE'
		err.details = { status: 'spec_artifact_content_unavailable', mode: normalized, deckVersion: selected.deckVersion ?? null }
		throw err
	}
	const descriptor = { ...selected }
	delete descriptor.spec
	return { spec: cloneJson(spec), artifact: descriptor, source: `deck.export_spec.${normalized}` }
}

async function resolveBundleLockedAsset(handle, options = {}) {
	await authorizeAssetReferences(handle)
	const filePath = resolveLockedAssetHandle(handle)
	if (options.bytes) return assertAssetBytes(handle, await fs.readFile(filePath))
	return filePath
}

async function publishSourceBundleArtifact(deckId, bundle, { fileName, outputDir } = {}) {
	const title = String(fileName || bundle.manifest.title || `betterpptx_${deckId}_source`).replace(/\.betterpptx$/i, '')
	const artifact = await _artifactStore.prepareArtifactTarget({
		fileName: `${title}.betterpptx`,
		outputDir,
		deckId,
		kind: 'betterpptx-source-bundle',
		extension: '.betterpptx',
		contentType: 'application/zip',
	})
	await fs.writeFile(artifact.target, bundle.bytes)
	const finalized = _artifactStore.finalizeSaveTarget ? await _artifactStore.finalizeSaveTarget(artifact) : artifact
	if (isPublicBlackBoxMode() && !String(finalized.downloadUrl || '').trim()) {
		try { await fs.rm(artifact.target, { force: true }) } catch {}
		const err = new Error('The source bundle could not be published as a client-accessible artifact.')
		err.code = 'PUBLIC_BUNDLE_ARTIFACT_UNAVAILABLE'
		err.details = { status: 'bundle_artifact_unavailable', recommendation: 'Configure public artifact delivery, then request the source bundle again.' }
		throw err
	}
	return {
		state: finalized.downloadUrl ? 'download_ready' : 'archived',
		...(finalized.expiresAt ? { downloadExpiresAt: finalized.expiresAt } : {}),
		...(finalized.downloadUrl ? { downloadUrl: finalized.downloadUrl, downloadName: finalized.downloadName } : {}),
	}
}

async function handleSpecExportBundle(args = {}) {
	const selected = await sourceSpecForBundle(args.deckId, args.mode || 'effectivePrecompile', args.deckVersion, args.specHandle)
	await authorizeAssetReferences(selected.spec)
	const bundle = await createSourceBundle(selected.spec, {
		resolveLockedAsset: resolveBundleLockedAsset,
		title: args.title || selected.spec.title,
		profile: args.profile || 'source-only',
	})
	const artifact = args.download === false ? null : await publishSourceBundleArtifact(args.deckId || null, bundle, { fileName: args.fileName, outputDir: args.outputDir })
	return {
		ok: true,
		mode: args.mode || 'effectivePrecompile',
		profile: bundle.manifest.profile,
		bundleSha256: bundle.bundleSha256,
		sourceDigest: bundle.sourceDigest,
		portability: bundle.manifest.portability,
		memberCount: bundle.memberCount,
		manifest: bundle.manifest,
		...(selected.artifact ? { sourceArtifact: selected.artifact } : {}),
		...(artifact ? { artifact } : {}),
		privacy: { rawXmlIncluded: false, localPathsIncluded: false, storageDetailsIncluded: false, privateImplementationIncluded: false },
		next: { recommendedTool: 'betterpptx.bundle.inspect', reason: 'A receiving AI can inspect and import this self-contained source bundle in a fresh session.' },
	}
}

async function bundleUploadBytes(args = {}) {
	const materialized = await materializeConnectorUploadSource(args, 'betterpptx source bundle')
	return Buffer.isBuffer(materialized.bytes) ? materialized.bytes : Buffer.from(materialized.bytes || '')
}

async function handleBundleInspect(args = {}) {
	const inspected = await inspectSourceBundle(await bundleUploadBytes(args))
	await authorizeAssetReferences(inspected.sourceSpec)
	return {
		ok: true,
		bundleSha256: inspected.bundleSha256,
		sourceDigest: inspected.sourceDigest,
		manifest: inspected.manifest,
		memberCount: inspected.manifest.members.length + 1,
		expandedBytes: inspected.totalBytes,
		privacy: { rawXmlIncluded: false, localPathsIncluded: false, storageDetailsIncluded: false, privateImplementationIncluded: false },
		next: { recommendedTool: 'betterpptx.bundle.import', reason: 'Import the verified source bundle, bind embedded assets, then pass the returned specHandle to generate_from_spec.' },
	}
}

async function handleBundleImport(args = {}) {
	const imported = await importSourceBundle(await bundleUploadBytes(args), {
		lockAsset: async (bytes, logicalPath) => {
			const ext = String(logicalPath).split('.').pop() || 'bin'
			return lockGeneratedAssetBufferDescriptor(bytes, 'bundle-asset', { extn: ext, mimeType: mimeForExt(ext) }).handle
		},
	})
	const specBytes = canonicalDeckSpecBytes(imported.reboundSpec)
	assertNoPublicLocalPathArgs(imported.reboundSpec)
	await authorizeAssetReferences(imported.reboundSpec)
	const specHandle = lockGeneratedAssetBufferDescriptor(specBytes, 'uploaded-jsonspec', { extn: 'json', mimeType: 'application/json' }).handle
	return {
		ok: true,
		bundleSha256: imported.bundleSha256,
		sourceDigest: imported.sourceDigest,
		manifest: imported.manifest,
		specHandle,
		specDigest: canonicalDeckSpecDigest(imported.reboundSpec),
		boundAssetCount: imported.boundAssetCount,
		portability: imported.manifest.portability,
		privacy: { rawXmlIncluded: false, localPathsIncluded: false, storageDetailsIncluded: false, privateImplementationIncluded: false },
		next: { recommendedTool: 'betterpptx.deck.generate_from_spec', reason: 'Run dryRun, resolve or lockedDryRun, then commit the imported immutable source through the governed JSON-spec workflow.' },
	}
}

async function handleExportSpec(args) {
	const entry = getDeck(args.deckId)
	const mode = String(args.mode || 'current').trim()
	if (mode !== 'current') {
		const stageByMode = {
			authoredInput: 'authorSubmittedSpec',
			effectivePrecompile: 'effectivePrecompile',
		}
		const stage = stageByMode[mode]
		if (!stage) {
			const err = new Error(`Unsupported spec export mode ${mode}.`)
			err.code = 'SPEC_EXPORT_MODE_UNSUPPORTED'
			err.details = { status: 'spec_export_mode_unsupported', supportedModes: ['current', ...Object.keys(stageByMode)] }
			throw err
		}
		const selected = [...(entry.specArtifactLineage || [])].reverse().find(item =>
			item.stage === stage && (args.deckVersion == null || Number(item.deckVersion) === Number(args.deckVersion)))
		if (!selected) {
			const err = new Error(`No ${mode} spec artifact is available for the requested deck version.`)
			err.code = 'SPEC_ARTIFACT_NOT_FOUND'
			err.details = {
				status: 'spec_artifact_not_found',
				mode,
				deckVersion: args.deckVersion ?? null,
				available: (entry.specArtifactLineage || []).map(item => ({ stage: item.stage, deckVersion: item.deckVersion, sha256: item.sha256 })),
			}
			throw err
		}
		let selectedSpec = selected.spec
		if (!selectedSpec && selected.sha256 && _deckSnapshotStore && !_deckSnapshotStore.disabled) {
			selectedSpec = (await _deckSnapshotStore.getCanonicalSpec(selected.sha256)).spec
		}
		if (!selectedSpec) {
			const err = new Error(`The ${mode} spec artifact metadata exists, but its immutable content is unavailable.`)
			err.code = 'SPEC_ARTIFACT_CONTENT_UNAVAILABLE'
			err.details = { status: 'spec_artifact_content_unavailable', mode, deckVersion: selected.deckVersion ?? null, sha256: selected.sha256 }
			throw err
		}
		const specArtifact = { ...selected }
		delete specArtifact.spec
		const artifact = args.download === true
			? await publishFinalizedSpecArtifact(args.deckId, entry, {
				fileName: args.fileName,
				outputDir: args.outputDir,
				stage,
				deckVersion: args.deckVersion,
			})
			: undefined
		return {
			ok: true,
			deckId: args.deckId,
			authoringRoute: cloneForResult(entry.authoringRoute || null),
			mode,
			spec: normalizeModel3dControlsInSpec(cloneJson(selectedSpec)),
			specArtifact,
			...(artifact ? { artifact } : {}),
			privacy: {
				rawXmlIncluded: false,
				localPathsIncluded: false,
				storageDetailsIncluded: false,
				privateImplementationIncluded: false,
			},
			next: { recommendedTool: 'betterpptx.deck.generate_from_spec', reason: 'Revise or recompile this immutable authoring artifact through the governed JSON-spec workflow.' },
		}
	}
	const { pptx } = entry
	const importedInheritanceProjection = (!Array.isArray(entry.authoredLayouts) || entry.authoredLayouts.length === 0)
		? projectImportedInheritanceDefinitions(entry, pptx)
		: null
	const detail = String(args.detail || 'summary').toLowerCase()
	let exportSlideSizeCache = null
	const slides = []
	const editabilityMap = []
	const byTier = {}
	// "preserved" = imported with FULL fidelity and wrapper-editable; NOT a drop. The old label
	// ("unsupported") wrongly implied absence — everything decyphered is in the deck.
	const preservedFindings = []
	entry.semanticHandles ||= {}
	for (let slideIndex = 0; slideIndex < pptx.slides.length; slideIndex += 1) {
		const slide = pptx.slides[slideIndex]
		if (slide?._betterpptxSummaryZoomOwner) continue
		const slideId = String(slide._betterpptxSemanticId || `slide-${slideIndex + 1}`)
		const content = []
		const sectionZooms = []
		const editable = _editableSlideObjects(slide)
		const seenObjectNames = new Set()
		// R1 — reconstruct the slide's narration FIRST: when it round-trips via slideSpec.narration
		// the embedded audio objects below are engine artifacts, not content.
		const slideRecordStudio = exportedSlideRecordStudio(entry, slideIndex)
		const slideNarration = slideRecordStudio || slide._narrationAuthored === false ? null : exportedSlideNarration(entry, slideIndex)
		for (let index = 0; index < editable.length; index += 1) {
			const { obj, rawIndex } = editable[index]
			// Engine-generated artifacts are NOT content — they regenerate from spec fields on
			// re-commit, so exporting them as blocks would DOUBLE them on every round-trip:
			//  - the invisible a11y title placeholder (slide.add creates it from `title:`), which
			//    also collides the deck-unique "slide-title" edit handle on multi-slide decks;
			//  - narration audio clips + caption boxes (rebuilt from slideSpec.narration).
			const o = obj?.options || {}
			if (o.objectName === 'slide-title' && o.placeholder === 'title' && Number(o.transparency) === 100) continue
			if ((slideNarration || slideRecordStudio) && (o.isNarration === true || o._nativeRecordStudioCapture === true || /narration[-.]audio|narration-caption/.test(String(o.objectName || '')))) continue
			const exported = objectToExportSpecBlock({ deckId: args.deckId, pptx, slide, slideIndex, index, rawIndex, obj })
			// PROVENANCE — an artifact-form object (icon pixels, model binary, geometry) whose
			// AUTHORED identity rode the sidecar re-exports as its semantic block: re-committing
			// regenerates it from intent instead of freezing the artifact. Current geometry wins
			// (the user may have moved/resized it in PowerPoint).
			const compiledObjectName = String(o.objectName || '')
			const canonicalSlide = (entry.canonicalRecompileSpec?.slides || []).find(candidate => String(candidate?.id || '') === slideId)
			const mappedSource = slide._specProvenance?.[compiledObjectName]
			const mappedName = String(mappedSource?.name || mappedSource?.objectName || '')
			const canonicalContent = canonicalSlide?.content || []
			const mappedMatches = mappedName ? canonicalContent.filter(candidate =>
				String(candidate?.name || candidate?.objectName || '') === mappedName && candidate?.kind === mappedSource.kind) : []
			// Commit binds exact native names to authored blocks. Use that association
			// before legacy naming recovery, including dotted and colliding author IDs.
			const canonicalBlock = mappedMatches.length === 1 ? mappedMatches[0] : mappedMatches.length > 1 ? null : canonicalContent.find(candidate => {
				const authoredName = String(candidate?.name || candidate?.objectName || '')
				return authoredName && (authoredName === compiledObjectName || compiledObjectName.includes(`.${authoredName}.`))
			})
			const provenance = slide._specProvenance?.[compiledObjectName] || canonicalBlock || null
			const provenanceKind = String(provenance?.kind || '')
			if (provenance && (
				['image', 'media', 'opaqueNative', 'shape', 'freeform'].includes(String(exported.block?.kind || ''))
				|| ['image', 'media', 'shape', 'freeform', 'customGeometry', 'custom-geometry'].includes(provenanceKind)
			)) {
				const rect = exported.block.bbox || {}
				const currentGeometry = Number.isFinite(rect.x) ? { x: rect.x, y: rect.y, w: rect.w, h: rect.h } : null
				exported.block = {
					...cloneForResult(provenance),
					name: provenance.name || o.objectName,
					objectName: o.objectName,
					...(currentGeometry && Object.prototype.hasOwnProperty.call(provenance, 'rect') ? { rect: currentGeometry } : {}),
					...(currentGeometry && Object.prototype.hasOwnProperty.call(provenance, 'bbox') ? { bbox: currentGeometry } : {}),
					...(!Object.prototype.hasOwnProperty.call(provenance, 'rect') && !Object.prototype.hasOwnProperty.call(provenance, 'bbox') ? {
						options: { ...(provenance.options || {}), ...(currentGeometry || {}) },
					} : {}),
					provenance: 'betterpptx-sidecar',
				}
				exported.tier = 'semantic'
			}
			// Preserve the author's slide-scoped identity in portable current source.
			// Compiler-native names remain useful evidence, but must not replace the
			// stable author id that timelines, patches, and cross-slide transitions use.
			const authoredObjectName = String(canonicalBlock?.name || canonicalBlock?.objectName || '').trim()
			if (authoredObjectName) {
				exported.block.name = authoredObjectName
				exported.block.objectName = authoredObjectName
			}
			const sampledPresenter = exported.block?.kind === 'model3d' && ['staticPose', 'motionFraming'].some(key => Object.prototype.hasOwnProperty.call(exported.block, key))
			if (!canonicalBlock && SEMANTIC_NATIVE_PRESERVATION_KINDS.has(exported.block?.kind) && obj?.options?._nativePlaceholderInheritance !== true && !sampledPresenter) {
				const handle = preservationHandleForExport(args.deckId, slideIndex, index, obj)
				exported.block.nativePreservation = {
					handle,
					mode: 'retain-unless-edited',
					disableBy: 'Remove nativePreservation or set preserveNative:false to regenerate this block from semantic fields.',
				}
			}
			const uniqueName = uniqueExportObjectName(exported.block.objectName, seenObjectNames)
			if (uniqueName.duplicate) {
				exported.block.originalObjectName ||= uniqueName.originalObjectName
				exported.block.objectName = uniqueName.objectName
				exported.block.name = uniqueName.objectName
			}
			if (exported.block?.kind === 'sectionZoom') {
				const { kind: _kind, ...sectionZoom } = exported.block
				sectionZooms.push(sectionZoom)
			} else {
				content.push(exported.block)
			}
			byTier[exported.tier] = (byTier[exported.tier] || 0) + 1
			editabilityMap.push({
				slideId,
				slideIndex,
				objectName: exported.block.objectName,
				nativeObjectName: compiledObjectName || exported.block.objectName,
				editHandle: exported.editHandle,
				tier: exported.tier,
				editability: exported.editability,
			})
			if (exported.editHandle?.id) {
				entry.semanticHandles[exported.editHandle.id] = {
					slideId,
					slideIndex,
					objectName: exported.block.objectName,
					editHandle: exported.editHandle.id,
					tier: exported.tier,
					kind: exported.block.kind || null,
				}
			}
			if (exported.tier === 'preserved' || exported.tier === 'opaqueNative') {
				preservedFindings.push({
					slideId,
					slideIndex,
					objectName: exported.block.objectName,
					kind: _shapeKind(obj) || 'unknown',
					note: 'Preserved with FULL fidelity (exact source form) and editable at the wrapper tier (move/resize/recolor/delete). Not yet semantically regenerable from the public spec — nothing was dropped.',
				})
			}
		}
		const importedBinding = importedInheritanceProjection?.slideBindings.get(slideIndex + 1) || null
		const importedLayout = importedBinding
			? importedInheritanceProjection?.layoutsByNumber.get(Number(importedBinding.layoutNumber))
			: null
		const auditedImportedLayout = importedBinding
			? (entry.layoutAudit?.layouts || []).find(layout => Number(layout?.number) === Number(importedBinding.layoutNumber))
			: null
		const outsideProjectedMasterScope = Boolean(importedInheritanceProjection?.multipleMasterScopePreservedOnly
			&& auditedImportedLayout
			&& !importedLayout)
		const rawLayoutName = slide._betterpptxLayoutName || slide._templateLayoutName || importedBinding?.layoutName || slide._slideLayout?._name || null
		const projectedImportedLayoutName = importedInheritanceProjection
			? (importedInheritanceProjection.layoutNames.get(Number(importedBinding?.layoutNumber))
				|| importedInheritanceProjection.layoutNamesByRaw.get(String(rawLayoutName || ''))
				|| null)
			: null
		const nativeLayoutNames = new Set(_nativeLayoutNames(pptx).map(_sanitizeLayoutToken))
		const replayableRawLayoutName = rawLayoutName && (
			slide._betterpptxLayoutName
			|| importedBinding
			|| nativeLayoutNames.has(_sanitizeLayoutToken(rawLayoutName))
		)
		const exportedLayoutName = slide._betterpptxLayoutBindingReset || outsideProjectedMasterScope
			? null
			: (entry._betterpptxTemplatePresetId
				? (replayableRawLayoutName ? rawLayoutName : null)
				: (projectedImportedLayoutName || (replayableRawLayoutName ? rawLayoutName : null)))
		const auditedLayout = importedLayout || (entry.layoutAudit?.layouts || []).find(layout => layout?.name === rawLayoutName)
		const auditedMaster = auditedLayout ? (entry.layoutAudit?.masters || []).find(master => master?.number === auditedLayout.masterNumber) : null
		const projectedImportedMasterName = importedInheritanceProjection?.masterNames.get(Number(auditedLayout?.masterNumber)) || null
		const exportedMasterName = slide._betterpptxLayoutBindingReset || outsideProjectedMasterScope ? null : (projectedImportedMasterName || slide._betterpptxMasterName
			|| slide._slideLayout?._betterpptxMasterName
			|| auditedMaster?.name
			|| pptx.masterSlide?._betterpptxSemanticMasterName
			|| null)
		const slideSpec = {
			id: slideId,
			title: slide._betterpptxTitle || slide._slideTitle || slide.title || `Slide ${slideIndex + 1}`,
			// R-LAYOUT — the authored intent pinned at compile time; for raw/uploaded decks that
			// never met the compiler it is INFERRED and marked as such (teamwork: an inference is
			// the MCP's proposal — the AI confirms or corrects it in the spec; re-committing pins it).
			...(slide._layoutIntent
				? { layoutIntent: slide._layoutIntent }
				: { layoutIntent: inferSlideLayoutIntent(slide, slideIndex, exportSlideSizeCache ||= exportedSlideSize(pptx)), layoutIntentInferred: true }),
			content,
			...(sectionZooms.length === 1 ? { sectionZoom: sectionZooms[0] } : sectionZooms.length ? { sectionZooms } : {}),
			...(slide._betterpptxLayoutPresetId ? { layoutPresetId: slide._betterpptxLayoutPresetId } : {}),
			...(exportedLayoutName ? { layoutName: exportedLayoutName } : {}),
			...(exportedMasterName ? { masterName: exportedMasterName } : {}),
			...(slide.hidden !== undefined ? { hidden: slide.hidden === true } : {}),
			...(slide.slideNumber !== undefined ? { slideNumber: _sanitizeOpts(slide.slideNumber) } : {}),
			...(slide._showMasterSp !== undefined ? { showMasterShapes: slide._showMasterSp !== false, showMasterBackground: slide._showMasterSp !== false } : {}),
			...(slide._showMasterPhAnim !== undefined ? { showMasterPhAnim: slide._showMasterPhAnim !== false } : {}),
			...((slide._colorMapOverride || importedBinding?.colorMapOverride) ? { colorMapOverride: cloneForResult(slide._colorMapOverride || importedBinding.colorMapOverride) } : {}),
			...(slide.background ? { background: _sanitizeOpts(slide.background) } : {}),
			...(slide.transition ? { transition: _sanitizeOpts(slide.transition) } : {}),
			...(slide._betterpptxAuthoredTimeline ? { timeline: cloneForResult(slide._betterpptxAuthoredTimeline) } : {}),
		}
		// R1 — round-trip opaque user notes separately from the BetterPPTX-owned narration block.
		const authorNotes = _splitNarrationNotes(_slideNotesText(slide)).userNotes
		if (authorNotes) slideSpec.notes = authorNotes
		if (slideNarration) slideSpec.narration = slideNarration
		if (slideRecordStudio) slideSpec.avatarNarration = slideRecordStudio
		const hasNativeTimingPreservation =
			(typeof slide._rawTransitionXml === 'string' && slide._rawTransitionXml.trim()) ||
			(typeof slide._rawTimingXml === 'string' && slide._rawTimingXml.trim()) ||
			(typeof slide._rawSlideExtLstXml === 'string' && slide._rawSlideExtLstXml.trim())
		if (hasNativeTimingPreservation) {
			const timingHandle = timingPreservationHandleForExport(args.deckId, slideIndex, slide)
			slideSpec.nativeTimingPreservation = {
				handle: timingHandle,
				mode: 'retain-unless-edited',
				disableBy: 'Remove nativeTimingPreservation or set preserveNativeTiming:false to regenerate slide timing from motion fields.',
			}
		}
		slides.push(slideSpec)
	}
	const sectionSummaries = _sectionSummaries(pptx)
	const summaryZoom = exportedSummaryZoom(pptx)
	const exportedAt = new Date().toISOString()
	const nativePackageHandle = nativePackagePreservationHandleForExport(args.deckId)
	const exportedSelectionManifest = entry.aiSelectionManifest?.source === 'ai-authored'
		? {
			schemaVersion: entry.aiSelectionManifest.schemaVersion,
			enforcement: entry.aiSelectionManifest.enforcement,
			policy: cloneForResult(entry.aiSelectionManifest.policy),
			selections: (entry.aiSelectionManifest.selections || []).map(selection => ({
				slideId: String(pptx.slides[Number(selection.slideIndex)]?._betterpptxSemanticId || `slide-${Number(selection.slideIndex) + 1}`),
				target: selection.resolvedObjectName || selection.target,
				capability: selection.capability,
				representation: selection.representation,
				...(selection.intent ? { intent: selection.intent } : {}),
				...(selection.coherenceReason ? { coherenceReason: selection.coherenceReason } : {}),
				...(selection.customReason ? { customReason: selection.customReason } : {}),
				selectors: cloneForResult(selection.requestedSelectors || {}),
				...(selection.nativeFeatures?.length ? { nativeFeatures: [...selection.nativeFeatures] } : {}),
			})),
		}
		: null
	const spec = {
		schemaVersion: 'betterpptx.deck-spec.v1',
		title: args.title || entry.title || pptx.title || pptx.subject || 'Exported BetterPPTX deck',
		subject: pptx.subject,
		author: pptx.author,
		company: pptx.company,
		revision: cleanRevisionValue(pptx.revision, '1'),
		rtlMode: Boolean(pptx.rtlMode),
		// R1 — round-trip the WORLD (styleIntent: artDirection + mode) so a re-commit re-applies it.
		...(entry.authoredStyleIntent ? { styleIntent: entry.authoredStyleIntent } : {}),
		...(entry.deliveryExperience ? { deliveryExperience: cloneForResult(entry.deliveryExperience) } : {}),
		...(pptx.showSettings && Object.keys(pptx.showSettings).length ? { showSettings: cloneForResult(pptx.showSettings) } : {}),
		...(entry.deliveryExperience?.mode === 'narrated-autoplay' ? {
			autoplay: { enabled: true, preserveTimedSlides: true, loop: pptx.showSettings?.loop === true, mode: pptx.showSettings?.mode || 'present' },
		} : {}),
		// Theme fonts and all twelve explicit OOXML color slots are authored source,
		// not derived presentation metadata.  Export them so a fresh client can
		// re-edit, reset, and recompile the same native design system.
		...(!entry._betterpptxTemplatePresetOwnsTheme
			? (entry.authoredTheme
				? { theme: cloneForResult(entry.authoredTheme) }
				: (importedInheritanceProjection?.theme
					? { theme: cloneForResult(importedInheritanceProjection.theme) }
					: (pptx.theme && typeof pptx.theme === 'object' ? { theme: cloneForResult(pptx.theme) } : {})))
			: {}),
		...(entry.authoredSemanticContract?.domainContract ? { domainContract: cloneForResult(entry.authoredSemanticContract.domainContract) } : {}),
		...(entry.authoredSemanticContract ? { semanticRoundtrip: cloneForResult(entry.authoredSemanticContract) } : {}),
		layout: ['LAYOUT_4x3', 'LAYOUT_16x9', 'LAYOUT_16x10', 'LAYOUT_WIDE'].includes(String(pptx.layout || ''))
			? pptx.layout
			: 'LAYOUT_WIDE',
		...(!entry._betterpptxTemplatePresetOwnsLayouts ? { layouts: (() => {
			const native = exportedLayoutDefinitions(pptx, entry.authoredLayouts, importedInheritanceProjection)
			return native.length ? native : (entry.authoredLayouts ? cloneForResult(entry.authoredLayouts) : [])
		})() } : {}),
		...(!entry._betterpptxTemplatePresetOwnsMasters ? (() => {
			const native = exportedMasterDefinitions(pptx, entry.authoredMasters, importedInheritanceProjection)
			if (native.length) return { masters: native }
			return entry.authoredMasters ? { masters: cloneForResult(entry.authoredMasters) } : {}
		})() : {}),
		...(entry.authoredLayoutContract ? { layoutContract: cloneForResult(entry.authoredLayoutContract) } : {}),
		...(entry._betterpptxThemePresetId ? { themePresetId: entry._betterpptxThemePresetId } : {}),
		...(entry._betterpptxMasterPresetId ? { masterPresetId: entry._betterpptxMasterPresetId } : {}),
		...(entry._betterpptxTemplatePresetId ? { template: { templatePresetId: entry._betterpptxTemplatePresetId } } : {}),
		authoringContract: {
			workflow: entry.director?.mode === 'ai-sovereign' ? AI_SOVEREIGN_WORKFLOW : DIRECTOR_WORKFLOW,
			...(entry.director?.mode === 'ai-sovereign' ? { creativeAuthority: 'ai', directorMode: 'off', verificationMode: 'complete' } : {}),
			level: 'roundtrip',
			coordinateSystem: 'inches',
			layerModel: 'flat-object-array',
			source: 'deck.export_spec',
			importedGeometryPolicy: 'preserve-native-geometry',
			textPolicy: 'preserve native geometry for imported objects that cannot be safely re-laid out semantically',
		},
		...(exportedSelectionManifest ? { selectionManifest: exportedSelectionManifest } : {}),
		...(nativePackageHandle ? {
			nativePackagePreservation: {
				handle: nativePackageHandle,
				mode: 'roundtrip-scaffold',
				disableBy: 'Remove nativePackagePreservation to regenerate deck theme/master/layout scaffolding from semantic spec fields.',
			},
		} : {}),
		sections: sectionSummaries.filter(section => !(pptx.sections?.[section.index]?._betterpptxSummaryZoomOwner)).map(section => ({
			id: section.id,
			title: section.title,
			slideIds: (section.slideIndexes || []).map(index => String(pptx.slides[index]?._betterpptxSemanticId || `slide-${index + 1}`)),
		})),
		...(summaryZoom ? { summaryZoom } : {}),
		...(Array.isArray(pptx.customShows) && pptx.customShows.length ? {
			customShows: pptx.customShows.map(show => ({
				name: String(show.name),
				id: Number(show.id),
				slides: Array.isArray(show.slides) && show.slides.length
					? show.slides.map(String)
					: (show.slideIndexes || []).map(slideIndex => String(pptx.slides[Number(slideIndex)]?._betterpptxSemanticId || `slide-${Number(slideIndex) + 1}`)),
			})),
		} : {}),
		slides,
	}
	storeExportedSpecBaseline(entry, spec, 'deck.export_spec')
	const artifact = args.download === true
		? await publishSpecArtifactFile(args.deckId, spec, specArtifactDescriptor(spec, { stage: 'current', entry, phase: 'export', commitMode: 'patch' }), {
			fileName: args.fileName,
			outputDir: args.outputDir,
			fallbackName: `betterpptx_${args.deckId}_current`,
		})
		: undefined
	return {
		ok: true,
		deckId: args.deckId,
		authoringRoute: cloneForResult(entry.authoringRoute || null),
		exportedAt,
		spec,
		...(artifact ? { artifact } : {}),
		staticPoses: slides.flatMap((slide, slideIndex) => (slide.content || []).filter(block => block.kind === 'model3d' && block.staticPose != null).map(block => ({ slideIndex, objectName: block.objectName, ...block.staticPose, appliesTo: 'stopped-edit-view', playbackStartOffsetApplied: false }))),
		editabilityMap: detail === 'summary'
			? editabilityMap.map(item => ({
				slideId: item.slideId,
				slideIndex: item.slideIndex,
				objectName: item.objectName,
				editHandle: item.editHandle.id,
				tier: item.tier,
				editabilityTier: item.editability.tier,
			}))
			: editabilityMap,
		byTier,
		preservedFindings,
		// M21 — permanent license trail for embedded stock media (provider, author, source).
		...(entry.stockAssets?.length ? { stockAssets: cloneForResult(entry.stockAssets) } : {}),
		privacy: {
			rawXmlIncluded: false,
			localPathsIncluded: false,
			privateImplementationIncluded: false,
		},
		next: preservedFindings.length
			? { recommendedTool: 'betterpptx.deck.generate_from_spec', reason: 'Revise semantic blocks; preserved blocks round-trip by handle with full fidelity (wrapper edits: move/resize/recolor/delete).' }
			: { recommendedTool: 'betterpptx.deck.generate_from_spec', reason: 'Revise the exported spec and commit through the spec workflow.' },
	}
}

// Deep merge `patch` into `target` (mutates target). Arrays in the patch
// REPLACE the corresponding arrays in target (no element-wise merge), because
// that's almost always what the AI client wants when editing.
function _deepMerge(target, patch) {
	if (!patch || typeof patch !== 'object' || Array.isArray(patch)) return patch
	if (!target || typeof target !== 'object') target = {}
	for (const k of Object.keys(patch)) {
		const v = patch[k]
		if (v === null) {
			delete target[k]
		} else if (Array.isArray(v)) {
			target[k] = v
		} else if (v && typeof v === 'object') {
			target[k] = _deepMerge(target[k] || {}, v)
		} else {
			target[k] = v
		}
	}
	return target
}

// Resolve the target shape — by index, objectName, or kind+nth filter
function _resolveShape(slide, target) {
	const editable = _editableSlideObjects(slide)
	if (target == null) throw new Error('update_shape: `target` is required')
	if (typeof target === 'number') return { obj: editable[target]?.obj, index: target, rawIndex: editable[target]?.rawIndex }
	if (typeof target === 'object') {
		if (typeof target.rawIndex === 'number') return { obj: (slide._slideObjects || [])[target.rawIndex], index: editable.findIndex(x => x.rawIndex === target.rawIndex), rawIndex: target.rawIndex }
		if (typeof target.index === 'number') return { obj: editable[target.index]?.obj, index: target.index, rawIndex: editable[target.index]?.rawIndex }
		if (target.objectName) {
			for (let i = 0; i < editable.length; i++) {
				if (editable[i].obj.options?.objectName === target.objectName) return { obj: editable[i].obj, index: i, rawIndex: editable[i].rawIndex }
			}
		}
	}
	return { obj: null, index: -1, rawIndex: -1 }
}

function _shapeKind(obj) {
	return obj?.type || obj?._type || null
}

function _accessibilityShapeKind(obj) {
	const kind = _shapeKind(obj)
	if (kind !== 'passthrough') return kind
	const semanticKind = String(obj?.options?._passthroughSemanticKind || obj?.options?._passthroughOriginalType || '').toLowerCase()
	return ['chart', 'table'].includes(semanticKind) ? semanticKind : kind
}

function _mergeEditability(base, imported) {
	if (!imported || typeof imported !== 'object') return base
	const tools = Array.from(new Set([...(imported.tools || []), ...(base.tools || [])]))
	const operations = Array.from(new Set([...(imported.operations || []), ...(base.operations || [])]))
	return {
		...base,
		...imported,
		tools,
		operations,
		limitations: imported.limitations || base.limitations,
		recreateWith: imported.recreateWith || base.recreateWith,
	}
}

function _shapeEditHandle(obj = {}, context = {}) {
	const opts = obj.options || {}
	const existing = opts._decypherEditHandle
	const objectName = opts.objectName
	const selectors = Array.from(new Set([
		...(Array.isArray(existing?.stableSelectors) ? existing.stableSelectors : []),
		objectName ? `objectName:${objectName}` : null,
		opts.spid != null ? `spid:${opts.spid}` : null,
		Number.isInteger(context.index) ? `index:${context.index}` : null,
		Number.isInteger(context.rawIndex) ? `rawIndex:${context.rawIndex}` : null,
	].filter(Boolean)))
	return {
		id: existing?.id || (opts.spid != null ? `spid:${opts.spid}` : objectName || `rawIndex:${context.rawIndex ?? 'unknown'}`),
		source: existing?.source || {
			kind: opts._decypherEditHandle ? 'decypher' : 'generated',
			objectName: objectName || null,
			shapeId: opts.spid ?? null,
		},
		stableSelectors: selectors,
	}
}

function _shapeEditability(obj = {}, context = {}) {
	const kind = _shapeKind(obj)
	const imported = obj.options?._decypherEditability || obj.options?._decypherEditHandle?.editability || null
	if (_isChartExPassthrough(obj)) {
		return _mergeEditability({
			tier: 'promotable',
			semantic: true,
			tools: ['betterpptx.slide.update_chart', 'betterpptx.slide.update_shape', 'betterpptx.slide.delete_shapes', 'betterpptx.slide.reorder_shape'],
			operations: ['chart-data', 'chart-type', 'style', 'geometry', 'animation-target'],
			note: 'Preserved ChartEx passthrough promotes to native editable ChartEx on first update_chart call.',
		}, imported)
	}
	if (kind === 'passthrough') {
		return _mergeEditability({
			tier: 'wrapper-editable',
			semantic: false,
			tools: ['betterpptx.slide.update_shape', 'betterpptx.slide.delete_shapes', 'betterpptx.slide.reorder_shape'],
			operations: ['wrapper-style', 'wrapper-metadata', 'z-order', 'delete'],
			note: 'Raw passthrough OOXML is preserved for repair safety. Move/restyle/delete the wrapper, or recreate/promote to a structured object for semantic edits.',
		}, imported)
	}
	const semanticTools = {
		text: ['betterpptx.slide.update_shape'],
		shape: ['betterpptx.slide.update_shape'],
		image: ['betterpptx.slide.update_shape'],
		freeform: ['betterpptx.slide.update_shape'],
		model3d: ['betterpptx.slide.update_shape'],
		equation: ['betterpptx.slide.update_equation', 'betterpptx.slide.update_shape'],
		table: ['betterpptx.slide.update_table', 'betterpptx.slide.update_shape'],
		chart: ['betterpptx.slide.update_chart', 'betterpptx.slide.update_shape'],
		smartart: ['betterpptx.slide.update_smartart', 'betterpptx.slide.update_shape'],
		media: ['betterpptx.slide.update_media', 'betterpptx.slide.update_shape'],
		zoom: ['betterpptx.deck.generate_from_spec'],
		sectionZoom: ['betterpptx.deck.generate_from_spec'],
		summaryZoom: ['betterpptx.deck.generate_from_spec'],
	}
	const tools = semanticTools[kind] || ['betterpptx.slide.update_shape']
	return _mergeEditability({
		tier: 'semantic',
		semantic: true,
		tools: [...tools, 'betterpptx.slide.delete_shapes', 'betterpptx.slide.reorder_shape'],
		operations: imported?.operations || ['style', 'geometry', 'animation-target'],
		note: 'Generated or structurally imported object has a direct mutation path.',
	}, imported)
}

function _availableShapeTargets(slide) {
	return _editableSlideObjects(slide)
		.map((x, i) => `[${i}]${x.obj.options?.objectName || _shapeKind(x.obj) || 'shape'}`)
		.join(', ')
}

function _resolveShapeForTool(slide, target, toolName) {
	const result = _resolveShape(slide, target)
	if (!result.obj) {
		throw new Error(`${toolName}: target not found. Available: ${_availableShapeTargets(slide)}`)
	}
	return result
}

function _resolveTypedShape(slide, target, kinds, toolName) {
	const result = _resolveShapeForTool(slide, target, toolName)
	const kind = _shapeKind(result.obj)
	if (!kinds.includes(kind)) {
		throw new Error(`${toolName}: target "${result.obj.options?.objectName || result.index}" is ${kind || 'unknown'}, expected ${kinds.join(' or ')}.`)
	}
	return result
}

const RAW_EFFECT_PATCH_KEYS = new Set(['shadow', 'glow', 'reflection', 'softEdges', 'blur', 'fillOverlay', 'textShadow', 'textGlow', 'textReflection', 'effect', 'effects'])
const RAW_FILL_PATCH_KEYS = new Set(['fill', 'color', 'transparency'])
const RAW_LINE_PATCH_KEYS = new Set(['line', 'border'])
const RAW_PICTURE_SPPR_PATCH_KEYS = new Set(['fill', 'line', 'border', 'shadow', 'glow', 'reflection', 'softEdges', 'blur', 'fillOverlay', 'effect', 'effects', 'effect3D', 'pictureStyle', 'rotate', 'flipH', 'flipV', 'rounding'])
const SHAPE_EFFECT_PRESET_PATCH_KEYS = new Set(['shapeEffectPresetIds', 'shapeEffectPresetId'])
const STYLE_EFFECT_PRESET_PATCH_KEYS = new Set(['shapeStylePresetId', 'wordArtStylePresetId', 'textEffectPresetIds', 'textEffectPresetId'])
const SHAPE_FORMATTING_PATCH_KEYS = new Set([...SHAPE_FORMATTING_COMPONENT_KEYS, ...SHAPE_FORMATTING_SELECTOR_KEYS])
const PICTURE_EXT_ADJUSTMENT_KEYS = new Set(['brightness', 'contrast', 'temperature', 'saturation', 'sharpness', 'transparency', 'artisticEffect'])
const TEXT_STYLE_PATCH_KEYS = new Set([
	'text', 'fontSize', 'fontFace', 'color', 'bold', 'italic', 'underline', 'strike',
	'fontFaceComplexScript', 'baseline', 'rtl', 'softBreakBefore', 'field', 'hyperlink',
	'subscript', 'superscript', 'breakLine', 'charSpacing', 'fit', 'wrap', 'margin', 'align',
	'valign', 'vert', 'rotate', 'autoFit', 'wordArt', 'text3D', 'textFill', 'textOutline', 'outline', 'lineSpacing',
	'paraSpaceBefore', 'paraSpaceAfter', 'lineSpacingMultiple', 'bullet', 'indent', 'hanging', 'indentLevel', 'tabStops', 'highlight',
	'transparency', 'textFill', 'textOutline', 'outline', 'lang', 'rtlMode', 'glow', 'shadow', 'reflection', 'softEdges', 'blur', 'fillOverlay', 'effects', 'textShadow', 'textGlow', 'textReflection',
])
const RUN_STYLE_PATCH_KEYS = new Set([
	'fontSize', 'fontFace', 'color', 'bold', 'italic', 'underline', 'strike',
	'fontFaceComplexScript', 'baseline', 'rtl', 'softBreakBefore', 'field', 'hyperlink',
	'subscript', 'superscript', 'breakLine', 'charSpacing', 'highlight',
	'transparency', 'textFill', 'textOutline', 'outline', 'lang', 'glow', 'shadow', 'reflection', 'softEdges', 'blur', 'fillOverlay', 'effects', 'textShadow', 'textGlow', 'textReflection', 'text3D',
])

function _patchHasAny(patch, keys) {
	if (!patch || typeof patch !== 'object') return false
	return Object.keys(patch).some(k => keys.has(k))
}

function _shapeSupportsFormattingState(obj) {
	const kind = _shapeKind(obj)
	return kind === 'shape' || (kind === 'text' && Boolean(obj?.shape || obj?.options?.shape))
}

function _legacyShapeFormattingState(options = {}) {
	const input = {}
	const hasPresetSelector = SHAPE_FORMATTING_SELECTOR_KEYS.some(key =>
		Object.prototype.hasOwnProperty.call(options, key) && options[key] != null && options[key] !== '')
	for (const key of SHAPE_FORMATTING_SELECTOR_KEYS) {
		if (Object.prototype.hasOwnProperty.call(options, key)) input[key] = _deepCloneData(options[key])
	}
	// Old preset execution materialized a recipe directly into options. When a
	// selector is present those materialized fields are inherited, not authored;
	// otherwise existing native fields are the initial direct-formatting state.
	if (!hasPresetSelector) {
		for (const key of SHAPE_FORMATTING_COMPONENT_KEYS) {
			if (Object.prototype.hasOwnProperty.call(options, key)) input[key] = _deepCloneData(options[key])
		}
	}
	return resolveShapeFormatting(input, null, { mode: 'replace', path: 'existing shape options' }).state
}

function _applyShapeFormattingPatch(obj, patch) {
	if (!_shapeSupportsFormattingState(obj) || !_patchHasAny(patch, SHAPE_FORMATTING_PATCH_KEYS)) return false
	const formattingPatch = {}
	const ordinaryPatch = {}
	for (const [key, value] of Object.entries(patch)) {
		if (SHAPE_FORMATTING_PATCH_KEYS.has(key)) formattingPatch[key] = value
		else ordinaryPatch[key] = value
	}
	const previousState = obj.options?._shapeFormattingState || _legacyShapeFormattingState(obj.options)
	const previousEffective = resolveShapeFormatting({}, previousState, { mode: 'patch', path: 'existing shape options' }).effectiveOptions
	const resolved = applyShapeFormattingToOptions(formattingPatch, previousState, 'patch')
	for (const key of Object.keys(previousEffective)) delete obj.options[key]
	for (const key of SHAPE_FORMATTING_SELECTOR_KEYS) delete obj.options[key]
	_deepMerge(obj.options, ordinaryPatch)
	Object.assign(obj.options, resolved.options)
	return true
}

function _legacyConnectorStyleState(options = {}) {
	const recovered = recoverConnectorStyleState(options)
	if (recovered) return recovered
	// Raw imported connector lines are compatibility payload, not evidence that
	// the caller authored every materialized line leaf. Ordinary legacy native
	// connectors, however, did store their explicit line directly in options.
	const authoredLine = Object.prototype.hasOwnProperty.call(options, '_rawConnectorLineXml')
		? undefined
		: options.line
	return resolveConnectorStyleComposition(
		authoredLine && typeof authoredLine === 'object' ? { line: normalizeConnectorLineOverrides(authoredLine, 'existing connector line') } : {},
		null,
		{ mode: 'replace' },
	)
}

function _applyConnectorStylePatch(obj, patch) {
	if (_shapeKind(obj) !== 'connector') return false
	const ownsSelector = Object.prototype.hasOwnProperty.call(patch, 'connectorStylePresetId')
	const ownsLine = Object.prototype.hasOwnProperty.call(patch, 'line')
	if (!ownsSelector && !ownsLine) return false

	const current = obj.options || obj.connector || {}
	const hadTypedState = current?._connectorStyleState?.schemaVersion === CONNECTOR_STYLE_STATE_VERSION
	const previousState = _legacyConnectorStyleState(current)
	const formattingPatch = {
		...(ownsSelector ? { connectorStylePresetId: normalizeConnectorStylePresetId(patch.connectorStylePresetId, 'slide.update_shape patch.connectorStylePresetId') } : {}),
		...(ownsLine ? { line: normalizeConnectorLineOverrides(patch.line, 'slide.update_shape patch.line') } : {}),
	}
	const ordinaryPatch = Object.fromEntries(Object.entries(patch).filter(([key]) => key !== 'connectorStylePresetId' && key !== 'line'))
	const rawStyleXml = current._rawConnectorStyleXml
	const rawLineXml = current._rawConnectorLineXml
	const base = { ...current }
	delete base.line
	delete base.connectorStylePresetId
	delete base._connectorStyleState
	delete base._rawConnectorLineXml
	delete base._rawConnectorStyleXml
	_deepMerge(base, ordinaryPatch)
	const state = resolveConnectorStyleComposition(formattingPatch, previousState, { mode: 'patch' })
	const next = applyConnectorStyleComposition(base, state).options

	// A typed line edit on an opened connector owns the a:ln subtree, but it
	// must not erase an unrelated imported p:style theme reference. A null-only
	// request against an unowned imported line is a no-op for that raw payload.
	if (!hadTypedState && !state.connectorStylePresetId && rawStyleXml !== undefined) next._rawConnectorStyleXml = rawStyleXml
	if (!hadTypedState && rawLineXml !== undefined && (!ownsLine || formattingPatch.line === null)) next._rawConnectorLineXml = rawLineXml

	obj.options = next
	obj.connector = next
	return true
}

function _patchHasPictureExtAdjustment(patch) {
	return _patchHasAny(patch?.imageAdjustments, PICTURE_EXT_ADJUSTMENT_KEYS)
}

function _pictureAdjustmentsNeedWdp(value) {
	if (!value || typeof value !== 'object' || Array.isArray(value)) return false
	const artistic = value.artisticEffect
	if (typeof artistic === 'string' && artistic.trim()) return true
	if (artistic && typeof artistic === 'object' && String(artistic.type || artistic.id || '').trim()) return true
	return ['temperature', 'saturation', 'sharpness'].some(key =>
		Object.prototype.hasOwnProperty.call(value, key) && value[key] !== null && Number.isFinite(Number(value[key])),
	)
}

function _deleteOwnKeys(target, keys, removed) {
	if (!target || typeof target !== 'object') return
	for (const key of keys) {
		if (Object.prototype.hasOwnProperty.call(target, key)) {
			delete target[key]
			removed.add(key)
		}
	}
}

function _textRunPatch(patch) {
	const out = {}
	for (const [key, value] of Object.entries(patch || {})) {
		// Whole-object hyperlink state lives on the object's non-visual carrier.
		// Run hyperlinks are authored only inside patch.text rich runs; copying a
		// top-level hyperlink into every run creates duplicate native carriers and
		// relationships during update/reset/re-edit.
		if (key !== 'hyperlink' && RUN_STYLE_PATCH_KEYS.has(key)) out[key] = value
	}
	return out
}

function _clearRawTextRunBlockers(text, removed, runPatch) {
	if (!Array.isArray(text)) return
	for (const item of text) {
		if (!item || typeof item !== 'object') continue
		if (item.options && typeof item.options === 'object') {
			_deleteOwnKeys(item.options, [
				'_rawRprXml',
				'_rawRprAttrs',
				'_rawRprChildXmlExact',
				'_rawRunChildXml',
				'_rawParagraphChildXmlExact',
				'_rawDefRPrChildXml',
				'_rawPPrXml',
				'_rawPPrAttrs',
			], removed)
			if (Object.keys(runPatch).length) _deepMerge(item.options, runPatch)
		} else if (Object.keys(runPatch).length) {
			item.options = _deepCloneData(runPatch)
		}
		if (Array.isArray(item.text)) _clearRawTextRunBlockers(item.text, removed, runPatch)
		if (Array.isArray(item.children)) _clearRawTextRunBlockers(item.children, removed, runPatch)
		if (Array.isArray(item.runs)) _clearRawTextRunBlockers(item.runs, removed, runPatch)
	}
}

function _clearRawEditBlockers(obj, patch) {
	const removed = new Set()
	if (!obj || !patch || typeof patch !== 'object') return []
	const opts = obj.options || (obj.options = {})
	const kind = _shapeKind(obj)
	const textStyleKeys = Object.keys(patch).filter(key => TEXT_STYLE_PATCH_KEYS.has(key))
	const onlyTextFill = Object.prototype.hasOwnProperty.call(patch, 'textFill') && Object.keys(patch).every(key => ['textFill', 'color', 'transparency'].includes(key))
	if ((kind === 'text' || kind === 'shape') && onlyTextFill) {
		// The native glyph serializer replaces just the fill in captured run
		// properties. Keep WordArt outline/effects and paragraph/body settings.
		// Whole-text/whole-run bypasses must still yield to the editable runs.
		_visitTextOptionCarriers(obj, options => _deleteOwnKeys(options, ['_rawTxBodyXml', '_rawRunChildXml', '_rawParagraphChildXmlExact'], removed))
		return Array.from(removed).sort()
	}
	const narrowText3DPatch = (kind === 'text' || kind === 'shape') && textStyleKeys.length === 1 && textStyleKeys[0] === 'text3D'
	const authoredPictureStyle = kind === 'image' && Object.prototype.hasOwnProperty.call(patch, 'pictureStyle') ? patch.pictureStyle : undefined
	const authoredPictureStyleOwns = component => authoredPictureStyle && typeof authoredPictureStyle === 'object' && Object.prototype.hasOwnProperty.call(authoredPictureStyle, component)
	if (kind === 'image' && _patchHasAny(patch, RAW_PICTURE_SPPR_PATCH_KEYS)) {
		_deleteOwnKeys(opts, ['_rawPicSpPrXml', '_emptySpPr'], removed)
	}
	if (kind === 'image' && Object.prototype.hasOwnProperty.call(patch, 'pictureStyle')) {
		if (authoredPictureStyle === null || authoredPictureStyleOwns('geometry')) _deleteOwnKeys(opts, ['_rawPicPrstGeomXml'], removed)
		if (authoredPictureStyle === null || authoredPictureStyleOwns('fill')) _deleteOwnKeys(opts, ['_rawFillXml', '_rawSpPrFillXml'], removed)
		if (authoredPictureStyle === null || authoredPictureStyleOwns('line')) _deleteOwnKeys(opts, ['_rawLineXml', '_rawLnXml'], removed)
		if (authoredPictureStyle === null || authoredPictureStyleOwns('effects')) _deleteOwnKeys(opts, ['_rawEffectLstXml', '_rawEffectDagXml', '_rawEffectXml'], removed)
		if (authoredPictureStyle === null || authoredPictureStyleOwns('threeD')) _deleteOwnKeys(opts, ['_rawSpPrScene3dXml', '_rawScene3dXml', '_rawSp3dXml'], removed)
	}
	if (_patchHasAny(patch, RAW_EFFECT_PATCH_KEYS)) {
		_deleteOwnKeys(opts, ['_rawEffectLstXml', '_rawEffectDagXml', '_rawEffectXml'], removed)
		if (!authoredPictureStyleOwns('effects') && opts.pictureStyle && typeof opts.pictureStyle === 'object') delete opts.pictureStyle.effects
	}
	if (Object.prototype.hasOwnProperty.call(patch, 'effect3D') || Object.prototype.hasOwnProperty.call(patch, 'text3D')) {
		_deleteOwnKeys(opts, ['_rawSpPrScene3dXml', '_rawScene3dXml', '_rawSp3dXml'], removed)
		if (!authoredPictureStyleOwns('threeD') && opts.pictureStyle && typeof opts.pictureStyle === 'object') delete opts.pictureStyle.threeD
	}
	if (_patchHasAny(patch, SHAPE_EFFECT_PRESET_PATCH_KEYS)) {
		_deleteOwnKeys(opts, ['_rawSpPrScene3dXml', '_rawScene3dXml', '_rawSp3dXml', '_rawEffectLstXml', '_rawEffectDagXml', '_rawEffectXml'], removed)
	}
	if (_patchHasAny(patch, STYLE_EFFECT_PRESET_PATCH_KEYS)) {
		if (Object.prototype.hasOwnProperty.call(patch, 'textEffectPresetIds') || Object.prototype.hasOwnProperty.call(patch, 'textEffectPresetId')) {
			_deleteOwnKeys(opts, ['_rawRprChildXmlExact', '_rawRprEffectXmlExact', '_rawBodyPrChildXml'], removed)
		} else {
			_deleteOwnKeys(opts, ['_rawShapeStyleXml', '_rawFillXml', '_rawLineXml', '_rawRprChildXmlExact', '_rawRprEffectXmlExact'], removed)
		}
	}
	const hasPictureFrameFillPatch = kind === 'image' && Object.prototype.hasOwnProperty.call(patch, 'fill')
	if (kind === 'image' ? hasPictureFrameFillPatch : _patchHasAny(patch, RAW_FILL_PATCH_KEYS)) {
		_deleteOwnKeys(opts, ['_rawFillXml', '_rawSpPrFillXml', '_rawBlipFillXml'], removed)
		if (kind === 'image' && !authoredPictureStyleOwns('fill') && opts.pictureStyle && typeof opts.pictureStyle === 'object') delete opts.pictureStyle.fill
	}
	if (_patchHasAny(patch, RAW_LINE_PATCH_KEYS)) {
		_deleteOwnKeys(opts, ['_rawLineXml', '_rawLnXml'], removed)
		if (!authoredPictureStyleOwns('line') && opts.pictureStyle && typeof opts.pictureStyle === 'object') delete opts.pictureStyle.line
	}
	if (kind === 'image' && (Object.prototype.hasOwnProperty.call(patch, 'transparency') || Object.prototype.hasOwnProperty.call(patch, 'imageAdjustments'))) {
		_deleteOwnKeys(opts, ['_rawBlipInnerXml'], removed)
		if (Object.prototype.hasOwnProperty.call(patch, 'imageAdjustments') || _patchHasPictureExtAdjustment(patch)) _deleteOwnKeys(opts, ['_rawBlipExtLstXml'], removed)
	}
	if (kind === 'image' && Object.prototype.hasOwnProperty.call(patch, 'sizing')) _deleteOwnKeys(opts, ['_rawBlipTailXml'], removed)
	if (kind === 'image' && Object.prototype.hasOwnProperty.call(patch, 'rounding')) _deleteOwnKeys(opts, ['_rawPicPrstGeomXml', '_picPrstGeom'], removed)
	if ((kind === 'text' || kind === 'shape') && _patchHasAny(patch, TEXT_STYLE_PATCH_KEYS)) {
		if (narrowText3DPatch) {
			// A Text3D edit owns only bodyPr scene3d/sp3d. Keep the surrounding
			// WordArt/autofit/flatTx/extLst fragment and every run-level native
			// payload; applyText3DOverridesToRaw has already updated the two owned
			// subtrees with a DOM merge.
			_deleteOwnKeys(opts, ['_rawTxBodyXml', '_rawBodyPrXml'], removed)
			return Array.from(removed).sort()
		}
		_deleteOwnKeys(opts, [
			'_rawTxBodyXml',
			'_rawBodyPrXml',
			'_rawBodyPrAttrs',
			'_rawBodyPrChildXml',
			'_rawLstStyleXml',
			'_rawPPrXml',
			'_rawPPrAttrs',
			'_rawEndParaRPrXml',
			'_rawEndParaRPrAttrs',
			'_rawDefRPrChildXml',
		], removed)
		_clearRawTextRunBlockers(obj.text, removed, _textRunPatch(patch))
		if (Array.isArray(opts.text)) _clearRawTextRunBlockers(opts.text, removed, _textRunPatch(patch))
	}
	return Array.from(removed).sort()
}

function _visitTextOptionCarriers(obj, visit) {
	if (!obj || typeof obj !== 'object') return
	if (obj.options && typeof obj.options === 'object') visit(obj.options)
	const walk = value => {
		if (!Array.isArray(value)) return
		for (const item of value) {
			if (Array.isArray(item)) {
				walk(item)
				continue
			}
			if (!item || typeof item !== 'object') continue
			if (item.options && typeof item.options === 'object') visit(item.options)
			walk(item.text)
			walk(item.children)
			walk(item.runs)
		}
	}
	walk(obj.text)
	walk(obj.options?.text)
	walk(obj.arrTabRows)
}

function _prepareTextFillPatch(obj, patch, path) {
	if (!Object.prototype.hasOwnProperty.call(patch, 'textFill')) return null
	if (!['text', 'shape'].includes(_shapeKind(obj))) throw new Error(`${path} requires an editable text or text-shape target.`)
	const states = new Map()
	_visitTextOptionCarriers(obj, options => {
		if (states.has(options)) return
		const compatibility = {}
		for (const key of ['color', 'transparency']) {
			if (Object.prototype.hasOwnProperty.call(patch, key)) compatibility[key] = patch[key]
			else if (Object.prototype.hasOwnProperty.call(options, key)) compatibility[key] = options[key]
		}
		const ownFill = Object.prototype.hasOwnProperty.call(options, 'textFill')
		const inherited = ownFill ? options.textFill : obj.options?.textFill
		// Legacy solid aliases remain an editable starting value; a sparse alpha
		// patch must preserve each run's independent RGB color, not homogenize it.
		const prior = inherited !== undefined ? inherited : Object.fromEntries(Object.entries(compatibility).filter(([, value]) => value !== undefined))
		states.set(options, { top: options === obj.options, compatibility, fill: patchTextFill(prior, patch.textFill, path) })
	})
	return states
}

function _applyTextFillPatch(obj, states) {
	for (const [original, state] of states || []) {
		const options = state.top ? obj.options : original
		const aliases = { ...state.compatibility, ...textFillCompatibilityOptions(state.fill) }
		options.textFill = _deepCloneData(state.fill)
		for (const key of ['color', 'transparency']) {
			if (Object.prototype.hasOwnProperty.call(aliases, key)) options[key] = aliases[key]
			else delete options[key]
		}
	}
}

function _validateTransformTextFillPatch(pptx, args) {
	if (!Object.prototype.hasOwnProperty.call(args.patch || {}, 'textFill')) return
	normalizeTextFill(args.patch.textFill, 'transform patch.textFill', { allowPartial: true })
	const filter = args.filter || {}
	const slides = pptx?.slides || []
	const start = Math.max(0, Number(filter.slideRange?.[0] ?? 0))
	const end = Math.min(slides.length - 1, Number(filter.slideRange?.[1] ?? slides.length - 1))
	for (let index = start; index <= end; index += 1) {
		for (const { obj } of _editableSlideObjects(slides[index])) if (matchesTransformFilter(obj, filter)) _prepareTextFillPatch(obj, args.patch, 'transform patch.textFill')
	}
}

function _validateNativeGradientLinePatch(obj, patch, path) {
	if (!Object.prototype.hasOwnProperty.call(patch || {}, 'line')) return
	const line = patch.line
	const current = obj?.options?.line
	const gradientInvolved = current?.type === 'gradient' || line?.type === 'gradient'
		|| ['gradientDirection', 'gradientAngle', 'gradientStops', 'rotateGradientWithShape'].some(key => Object.prototype.hasOwnProperty.call(line || {}, key))
	if (!gradientInvolved) return
	if (obj && _shapeKind(obj) === 'connector') throw new Error(`${path} gradients require an ordinary or freeform shape, not a connector.`)
	const previousState = obj?.options?._shapeFormattingState || (obj ? _legacyShapeFormattingState(obj.options) : null)
	// Pure composition validates the final choice, including sparse patches
	// against an existing gradient, before a dryRun can authorize mutation.
	resolveShapeFormatting({ line }, previousState, { mode: 'patch', path })
}

function _validateTransformNativeGradientLinePatch(pptx, args) {
	if (!Object.prototype.hasOwnProperty.call(args.patch || {}, 'line')) return
	const filter = args.filter || {}
	const slides = pptx?.slides || []
	const start = Math.max(0, Number(filter.slideRange?.[0] ?? 0))
	const end = Math.min(slides.length - 1, Number(filter.slideRange?.[1] ?? slides.length - 1))
	for (let index = start; index <= end; index += 1) {
		for (const { obj } of _editableSlideObjects(slides[index])) if (matchesTransformFilter(obj, filter)) _validateNativeGradientLinePatch(obj, args.patch, 'transform patch.line')
	}
}

function _textHyperlinkRelationshipIds(obj) {
	const ids = new Set()
	_visitTextOptionCarriers(obj, options => {
		const rId = Number(options.hyperlink?._rId)
		if (Number.isFinite(rId) && rId > 0) ids.add(rId)
	})
	return ids
}

function _nextSlideRelationshipId(slide) {
	let maxRid = 0
	const scan = rid => {
		const text = String(rid || '')
		const value = text.startsWith('rId') ? Number(text.slice(3)) : Number(text)
		if (Number.isFinite(value)) maxRid = Math.max(maxRid, value)
	}
	for (const rel of [...(slide._rawRels || []), ...(slide._rels || []), ...(slide._relsChart || []), ...(slide._relsMedia || [])]) scan(rel?.id ?? rel?.rId)
	return maxRid + 1
}

function _attachTextHyperlinkRelationships(slide, obj) {
	_visitTextOptionCarriers(obj, options => {
		const hyperlink = options.hyperlink
		if (!hyperlink || typeof hyperlink !== 'object') return
		const existingRid = Number(hyperlink._rId)
		const expectedData = hyperlink.slide ? 'slide' : 'dummy'
		const expectedTarget = String(hyperlink.url || hyperlink.slide)
		const existing = Number.isFinite(existingRid)
			? (slide._rels || []).find(rel => Number(rel?.rId) === existingRid && rel?.type === 'hyperlink')
			: null
		if (existing) {
			existing.data = expectedData
			existing.Target = expectedTarget
			return
		}
		const rId = _nextSlideRelationshipId(slide)
		slide._rels ||= []
		slide._rels.push({ type: 'hyperlink', data: expectedData, rId, Target: expectedTarget })
		hyperlink._rId = rId
	})
}

function _structuredHyperlinkCarriers(obj) {
	const carriers = []
	const seen = new Set()
	const add = hyperlink => {
		if (!hyperlink || typeof hyperlink !== 'object' || seen.has(hyperlink)) return
		seen.add(hyperlink)
		carriers.push(hyperlink)
	}
	_visitTextOptionCarriers(obj, options => add(options.hyperlink))
	add(obj?.hyperlink)
	return carriers
}

function _captureInternalHyperlinkTargets(pptx, toolName = 'slide operation') {
	const slides = pptx?.slides || []
	const records = []
	for (const [sourceIndex, sourceSlide] of slides.entries()) {
		for (const obj of sourceSlide?._slideObjects || []) {
			for (const hyperlink of _structuredHyperlinkCarriers(obj)) {
				if (hyperlink.slide === undefined) continue
				const targetIndex = Number(hyperlink.slide) - 1
				const targetSlide = slides[targetIndex]
				if (!targetSlide) throw new Error(`${toolName}: hyperlink on slide ${sourceIndex} targets missing one-based slide ${hyperlink.slide}.`)
				records.push({ sourceSlide, targetSlide, hyperlink, rId: Number(hyperlink._rId), objectName: obj.options?.objectName || _shapeKind(obj) || 'object' })
			}
		}
	}
	return records
}

function _retargetInternalHyperlinks(pptx, records) {
	const slideNumberByObject = new Map((pptx?.slides || []).map((slide, index) => [slide, index + 1]))
	for (const record of records || []) {
		const targetSlideNumber = slideNumberByObject.get(record.targetSlide)
		if (!slideNumberByObject.has(record.sourceSlide) || !targetSlideNumber) continue
		record.hyperlink.slide = targetSlideNumber
		if (!Number.isFinite(record.rId)) continue
		const relation = (record.sourceSlide._rels || []).find(rel => Number(rel?.rId) === record.rId && rel?.type === 'hyperlink')
		if (relation) {
			relation.data = 'slide'
			relation.Target = String(targetSlideNumber)
		}
	}
}

function _removeUnreferencedTextHyperlinkRelationships(slide, candidateIds) {
	if (!candidateIds?.size) return
	const stillUsed = new Set()
	for (const slideObj of slide._slideObjects || []) {
		for (const rId of _textHyperlinkRelationshipIds(slideObj)) stillUsed.add(rId)
	}
	slide._rels = (slide._rels || []).filter(rel => !candidateIds.has(Number(rel?.rId)) || stillUsed.has(Number(rel?.rId)))
}

function assertGraphicFramePlaceholderBinding(slide, obj, binding, path) {
	const kind = _shapeKind(obj)
	if (!['chart', 'table'].includes(kind) || binding === null) return
	const expectedType = kind === 'table' ? 'tbl' : 'chart'
	if (binding.phType !== undefined && binding.phType !== expectedType) {
		throw new Error(`${path}.type must be ${kind === 'table' ? 'table/tbl' : 'chart'} for a ${kind} object.`)
	}
	if (kind === 'table' && obj.options?.autoPage === true) {
		throw new Error(`${path} cannot bind an auto-paged table because each generated graphic frame would require a distinct placeholder identity.`)
	}
	const layoutObjects = slide?._slideLayout?._slideObjects || []
	const authoredName = typeof binding.placeholder === 'string' && binding.placeholder !== binding.phType
		? binding.placeholder
		: null
	const matches = layoutObjects.filter(candidate => {
		if (candidate?._type !== 'placeholder') return false
		const options = candidate.options || {}
		const type = options._placeholderType ?? options.phType ?? options._phType
		const idx = options._placeholderIdx ?? options.phIdx ?? options._phIdx
		if (authoredName && options.placeholder !== authoredName && options.objectName !== authoredName) return false
		if (binding.phType !== undefined && type !== binding.phType) return false
		if (binding.phIdx !== undefined && (idx === undefined || String(idx) !== String(binding.phIdx))) return false
		return true
	})
	if (matches.length !== 1) {
		throw new Error(`${path} must resolve to exactly one layout placeholder; found ${matches.length} matching ${authoredName || binding.phType || 'unnamed'} carrier(s).`)
	}
	const options = matches[0].options || {}
	const resolvedType = options._placeholderType ?? options.phType ?? options._phType
	if (resolvedType !== expectedType) throw new Error(`${path} resolves to ${resolvedType || 'an untyped placeholder'}, not the required ${expectedType} role.`)
}

async function handleUpdateShape(args) {
	const slide = getSlide(args.deckId, args.slideIndex)
	const { obj, index, rawIndex } = _resolveShapeForTool(slide, args.target, 'update_shape')
	if (!args.patch || typeof args.patch !== 'object') throw new Error('update_shape: `patch` (object) is required')
	const resolvedPatchInput = { ...args.patch }
	if (Object.prototype.hasOwnProperty.call(resolvedPatchInput, 'placeholderBinding')) {
		const binding = normalizePlaceholderBinding(resolvedPatchInput.placeholderBinding, 'slide.update_shape patch.placeholderBinding')
		assertGraphicFramePlaceholderBinding(slide, obj, binding, 'slide.update_shape patch.placeholderBinding')
		delete resolvedPatchInput.placeholderBinding
		if (binding === null) {
			for (const key of ['placeholder', 'phType', 'phIdx', 'phSz', 'phOrient', 'phHasCustomPrompt', 'hasCustomPrompt', 'hasBarePh']) resolvedPatchInput[key] = null
		} else {
			Object.assign(resolvedPatchInput, binding)
		}
	}
	let model3dLifecyclePatch = null
	if (Object.prototype.hasOwnProperty.call(resolvedPatchInput, 'motionFraming') && _shapeKind(obj) !== 'model3d') throw motionFramingError('motionFraming applies only to native model3d objects.', 'MODEL3D_MOTION_FRAMING_TARGET_UNSUPPORTED')
	if (_shapeKind(obj) === 'model3d') {
		if (Object.prototype.hasOwnProperty.call(resolvedPatchInput, 'motionFraming')) {
			normalizeModel3dMotionFraming(resolvedPatchInput.motionFraming, 'slide.update_shape patch.motionFraming')
			throw motionFramingError('Changing or resetting motionFraming requires generate_from_spec with replaceDeck or createNew using the authorized model asset and selected motion.', 'MODEL3D_MOTION_FRAMING_REBUILD_REQUIRED')
		}
		if (obj.options?.motionFraming && ['camera', 'trans', 'objViewport', 'model3dViewPresetId', 'scene', 'w', 'h'].some(key => Object.prototype.hasOwnProperty.call(resolvedPatchInput, key))) throw motionFramingError('Changing a motion-framed model view, frame size, or selected motion requires a model rebuild so its framing is recalculated.', 'MODEL3D_MOTION_FRAMING_REBUILD_REQUIRED')
		if (Object.prototype.hasOwnProperty.call(resolvedPatchInput, 'staticPose')) {
			throw staticPoseError('STATIC_POSE_REBUILD_REQUIRED', 'Changing or resetting staticPose requires generate_from_spec with commitMode replaceDeck or createNew, using the exported original modelAsset. In-place shape patches cannot replace the native model safely.')
		}
		const sourceKeys = ['modelAsset', 'model3DAsset', 'model', 'glbFile', 'rasterFile', 'posterAsset', 'poster']
		if (sourceKeys.some(key => Object.prototype.hasOwnProperty.call(resolvedPatchInput, key))) {
			throw new Error('update_shape: 3-D model assets and poster topology are create-only; replace them atomically with slide.delete_shapes followed by slide.add_model3d.')
		}
		const viewKeys = ['camera', 'trans', 'ambientLight', 'ptLights', 'objViewport']
		const hasViewPatch = viewKeys.some(key => Object.prototype.hasOwnProperty.call(resolvedPatchInput, key))
		const hasPresetPatch = Object.prototype.hasOwnProperty.call(resolvedPatchInput, 'model3dViewPresetId')
		if (hasViewPatch || hasPresetPatch) {
			const viewInput = Object.fromEntries([...viewKeys, 'model3dViewPresetId'].filter(key => Object.prototype.hasOwnProperty.call(resolvedPatchInput, key)).map(key => [key, resolvedPatchInput[key]]))
			normalizeModel3dOptions(viewInput, 'slide.update_shape patch')
			const previousPreset = obj.options?._model3dViewPresetId || null
			const authored = _deepCloneData(obj.options?._model3dAuthoredOverrides || {})
			for (const key of viewKeys) {
				if (!Object.prototype.hasOwnProperty.call(resolvedPatchInput, key)) continue
				if (resolvedPatchInput[key] === null) delete authored[key]
				else authored[key] = _deepCloneData(resolvedPatchInput[key])
			}
			const requestedPreset = hasPresetPatch ? resolvedPatchInput.model3dViewPresetId : previousPreset
			const effective = requestedPreset
				? applyModel3dViewPreset(authored, requestedPreset).options
				: authored
			const existingKeys = viewKeys.filter(key => Object.prototype.hasOwnProperty.call(obj.options || {}, key))
			for (const key of new Set([...existingKeys, ...viewKeys.filter(key => Object.prototype.hasOwnProperty.call(effective, key)), ...(hasPresetPatch ? viewKeys : [])])) {
				resolvedPatchInput[key] = Object.prototype.hasOwnProperty.call(effective, key) ? _deepCloneData(effective[key]) : null
			}
			delete resolvedPatchInput.model3dViewPresetId
			model3dLifecyclePatch = { presetId: requestedPreset || null, authoredOverrides: authored, clearRaw: Boolean(obj.options?._model3dXml) }
			if (model3dLifecyclePatch.clearRaw) {
				for (const key of ['_model3dXml', '_originalGlbRid', '_originalRasterRid']) delete obj.options[key]
			}
		}
	}
	if (_shapeKind(obj) === 'image' && ['source', 'path', 'data', 'url', 'image', 'handle'].some(key => Object.prototype.hasOwnProperty.call(resolvedPatchInput, key))) {
		throw new Error('update_shape: picture source is create-only; replace it atomically with slide.delete_shapes followed by slide.add_image.')
	}
	if (_shapeKind(obj) === 'image' && Object.prototype.hasOwnProperty.call(resolvedPatchInput, 'imageAdjustments')) {
		const currentUsesWdp = Number.isFinite(Number(obj.artisticEffectRid)) || _pictureAdjustmentsNeedWdp(obj.options?.imageAdjustments)
		const requestedUsesWdp = _pictureAdjustmentsNeedWdp(resolvedPatchInput.imageAdjustments)
		if (currentUsesWdp || requestedUsesWdp) {
			const error = new Error('update_shape: layered Picture Format adjustments (temperature, saturation, sharpness, or artisticEffect) are create/recreate-only because their HD Photo payload and visible preview must be replaced together.')
			error.code = 'PICTURE_LAYERED_ADJUSTMENT_RECREATE_REQUIRED'
			throw error
		}
	}
	let pictureHyperlinkPatch
	let hasPictureHyperlinkPatch = false
	if (Object.prototype.hasOwnProperty.call(resolvedPatchInput, 'pictureAdjuncts')) {
		if (_shapeKind(obj) !== 'image') throw new Error('update_shape patch.pictureAdjuncts applies only to native picture objects.')
		const validated = validatePictureAdjuncts(resolvedPatchInput.pictureAdjuncts, 'slide.update_shape patch.pictureAdjuncts')
		delete resolvedPatchInput.pictureAdjuncts
		const adjuncts = validated === null
			? { rounding: null, hyperlink: null, placeholder: null }
			: validated
		if (Object.prototype.hasOwnProperty.call(adjuncts, 'rounding')) resolvedPatchInput.rounding = adjuncts.rounding
		if (Object.prototype.hasOwnProperty.call(adjuncts, 'hyperlink')) {
			hasPictureHyperlinkPatch = true
			pictureHyperlinkPatch = adjuncts.hyperlink
		}
		if (Object.prototype.hasOwnProperty.call(adjuncts, 'placeholder')) {
			const placeholder = adjuncts.placeholder
			if (placeholder === null) {
				for (const key of ['placeholder', 'phType', 'phIdx', 'phSz', 'phOrient', 'phHasCustomPrompt', 'hasCustomPrompt', 'hasBarePh']) resolvedPatchInput[key] = null
			} else {
				const structured = typeof placeholder === 'string' ? { type: placeholder } : placeholder
				resolvedPatchInput.placeholder = structured.type
				resolvedPatchInput.phType = structured.type
				for (const [sourceKey, optionKey] of [['idx', 'phIdx'], ['size', 'phSz'], ['orient', 'phOrient']]) {
					resolvedPatchInput[optionKey] = structured[sourceKey] ?? null
				}
				resolvedPatchInput.phHasCustomPrompt = structured.hasCustomPrompt ?? null
			}
		}
	}
	if (resolvedPatchInput.fill) resolvedPatchInput.fill = resolveNativeFillAssetRefs(resolvedPatchInput.fill)
	if (resolvedPatchInput.picture) resolvedPatchInput.picture = resolveNativeFillAssetRefs({ picture: resolvedPatchInput.picture }).picture
	const connectorEffectsPatch = _shapeKind(obj) === 'connector'
		? patchConnectorEffects(obj.connector || obj.options, resolvedPatchInput, 'slide.update_shape patch')
		: null
	const authoredEffects = Object.prototype.hasOwnProperty.call(resolvedPatchInput, 'effects') ? _deepCloneData(resolvedPatchInput.effects) : undefined
	const textFillPatch = _prepareTextFillPatch(obj, resolvedPatchInput, 'slide.update_shape patch.textFill')
	const patch = normalizeVisualOptions(resolvedPatchInput, 'slide.update_shape patch', obj.options)
	const ownsTextHyperlinkState = (_shapeKind(obj) === 'text' || _shapeKind(obj) === 'shape')
		&& (Object.prototype.hasOwnProperty.call(patch, 'text') || Object.prototype.hasOwnProperty.call(patch, 'hyperlink'))
	const previousTextHyperlinkRids = ownsTextHyperlinkState ? _textHyperlinkRelationshipIds(obj) : new Set()
	if (ownsTextHyperlinkState && Object.prototype.hasOwnProperty.call(patch, 'hyperlink') && patch.hyperlink && obj.options?.hyperlink) {
		delete obj.options.hyperlink
	}
	if (authoredEffects !== undefined) patch.effects = authoredEffects
	if (!obj.options) obj.options = {}
	if (Object.prototype.hasOwnProperty.call(patch, 'text3D') && typeof obj.options._rawBodyPrChildXml === 'string') {
		obj.options._rawBodyPrChildXml = applyText3DOverridesToRaw(obj.options._rawBodyPrChildXml, patch.text3D)
	}
	const rawPreservationCleared = _clearRawEditBlockers(obj, patch)
	const shapeFormattingHandled = _applyShapeFormattingPatch(obj, patch)
	const connectorFormattingHandled = _applyConnectorStylePatch(obj, patch)
	if (!shapeFormattingHandled && !connectorFormattingHandled) _deepMerge(obj.options, patch)
	_applyTextFillPatch(obj, textFillPatch)
	if (connectorEffectsPatch) {
		// Replace the connector-only effect state atomically. Deep merging an old
		// combination array would otherwise restore a cleared component on replay.
		for (const key of CONNECTOR_EFFECT_FIELDS) delete obj.options[key]
		Object.assign(obj.options, connectorEffectsPatch)
		obj.connector = obj.options
	}
	if (model3dLifecyclePatch) {
		if (model3dLifecyclePatch.presetId) obj.options._model3dViewPresetId = model3dLifecyclePatch.presetId
		else delete obj.options._model3dViewPresetId
		obj.options._model3dAuthoredOverrides = model3dLifecyclePatch.authoredOverrides
	}
	if ((_shapeKind(obj) === 'text' || _shapeKind(obj) === 'shape') && obj.options?._bodyProp) {
		if (Object.prototype.hasOwnProperty.call(patch, 'vert')) {
			if (patch.vert == null) delete obj.options._bodyProp.vert
			else obj.options._bodyProp.vert = patch.vert
		}
		if (Object.prototype.hasOwnProperty.call(patch, 'wrap')) {
			if (patch.wrap == null) delete obj.options._bodyProp.wrap
			else obj.options._bodyProp.wrap = patch.wrap
		}
	}
	if (hasPictureHyperlinkPatch) {
		const oldRid = Number(obj.hyperlink?._rId)
		if (Number.isFinite(oldRid)) slide._rels = (slide._rels || []).filter(rel => Number(rel?.rId) !== oldRid)
		delete obj.options._rawHlinkClickXml
		delete obj.options._rawShapeHlinkClickXml
		if (pictureHyperlinkPatch === null) {
			delete obj.hyperlink
		} else {
			let maxRid = 0
			const scan = rid => {
				const text = String(rid || '')
				const n = text.startsWith('rId') ? Number(text.slice(3)) : Number(text)
				if (Number.isFinite(n)) maxRid = Math.max(maxRid, n)
			}
			for (const rel of [...(slide._rawRels || []), ...(slide._rels || []), ...(slide._relsChart || []), ...(slide._relsMedia || [])]) scan(rel?.id ?? rel?.rId)
			const rId = maxRid + 1
			slide._rels ||= []
			slide._rels.push({ type: 'hyperlink', data: pictureHyperlinkPatch.slide ? 'slide' : 'dummy', rId, Target: String(pictureHyperlinkPatch.url || pictureHyperlinkPatch.slide) })
			obj.hyperlink = { ...pictureHyperlinkPatch, _rId: rId }
		}
	}
	if (Object.prototype.hasOwnProperty.call(patch, 'fill') || Object.prototype.hasOwnProperty.call(patch, 'picture')) {
		// A changed fill must receive a fresh relationship. The previous media
		// part remains harmlessly unused; the library helper deduplicates the new
		// source and assigns the correct rId for the regenerated XML.
		delete obj.options._blipRid
		await attachResolvedShapeFillImage(slide, obj.options.fill)
	}
	if (!shapeFormattingHandled && !connectorFormattingHandled && _patchHasAny(patch, SHAPE_EFFECT_PRESET_PATCH_KEYS)) {
		const requestedPresetIds = obj.options.shapeEffectPresetIds ?? obj.options.shapeEffectPresetId
		if (requestedPresetIds == null || requestedPresetIds === '') {
			delete obj.options.shapeEffectPresetIds
			delete obj.options.shapeEffectPresetId
		} else {
			const applied = applyShapeEffectPresets(obj.options, requestedPresetIds).style
			obj.options = { ...applied, shapeEffectPresetIds: requestedPresetIds }
			delete obj.options.shapeEffectPresetId
		}
	}
	if (_patchHasAny(patch, STYLE_EFFECT_PRESET_PATCH_KEYS)) {
		if (!shapeFormattingHandled || Object.prototype.hasOwnProperty.call(patch, 'wordArtStylePresetId')) {
			const requestedStyleId = obj.options.wordArtStylePresetId ?? (!shapeFormattingHandled ? obj.options.shapeStylePresetId : null)
			if (requestedStyleId == null || requestedStyleId === '') {
				if (!shapeFormattingHandled) delete obj.options.shapeStylePresetId
				delete obj.options.wordArtStylePresetId
			} else {
				const applied = applyNativeStylePreset(obj.options, requestedStyleId).style
				obj.options = { ...applied, ...(obj.options.shapeStylePresetId ? { shapeStylePresetId: obj.options.shapeStylePresetId } : {}), ...(obj.options.wordArtStylePresetId ? { wordArtStylePresetId: obj.options.wordArtStylePresetId } : {}) }
			}
		}
		const requestedTextEffectIds = obj.options.textEffectPresetIds ?? obj.options.textEffectPresetId
		if (requestedTextEffectIds == null || requestedTextEffectIds === '') {
			delete obj.options.textEffectPresetIds
			delete obj.options.textEffectPresetId
		} else {
			const applied = applyTextEffectPresets(obj.options, requestedTextEffectIds).style
			obj.options = { ...applied, textEffectPresetIds: requestedTextEffectIds }
			delete obj.options.textEffectPresetId
		}
	}
	else if (Object.prototype.hasOwnProperty.call(patch, 'text3D')) {
		const requestedTextEffectIds = obj.options.textEffectPresetIds ?? obj.options.textEffectPresetId
		if (requestedTextEffectIds != null && requestedTextEffectIds !== '') {
			const applied = applyTextEffectPresets(obj.options, requestedTextEffectIds).style
			obj.options = { ...applied, textEffectPresetIds: requestedTextEffectIds }
			delete obj.options.textEffectPresetId
		}
	}
	// Top-level shape props like obj.text (for text boxes) live OUTSIDE options.
	// If the patch contains `text` and the object is a text shape, accept it at top level too.
	if (patch.text !== undefined && (obj.type === 'text' || obj._type === 'text')) {
		obj.text = patch.text
	}
	if (ownsTextHyperlinkState) {
		_attachTextHyperlinkRelationships(slide, obj)
		_removeUnreferencedTextHyperlinkRelationships(slide, previousTextHyperlinkRids)
	}
	// EDITION — text edit on a PRESERVED NATIVE (passthrough) shape: swap the words inside
	// the raw shape XML in place (first run carries the new text, later runs empty), so the
	// native styling survives exactly. Without this the text merged into options that the
	// passthrough renderer never reads — an ok:true that changed nothing in the package.
	let passthroughTextEdited = false
	if (typeof patch.text === 'string' && typeof obj.passthrough?.xml === 'string' && obj.passthrough.xml.includes('<a:t')) {
		let first = true
		obj.passthrough.xml = obj.passthrough.xml.replace(/(<a:t>)([\s\S]*?)(<\/a:t>)|<a:t\/>/g, (match, open, _inner, close) => {
			const replaced = first ? (open || '<a:t>') + escapeXmlAttr(patch.text) + (close || '</a:t>') : '<a:t></a:t>'
			first = false
			return replaced
		})
		passthroughTextEdited = !first
	}
	return {
		ok: true,
		slideIndex: args.slideIndex,
		index,
		rawIndex,
		objectName: obj.options?.objectName,
		patchedKeys: Object.keys(patch),
		rawPreservationCleared,
		...(passthroughTextEdited ? { passthroughTextEdited: true } : {}),
		...(model3dLifecyclePatch ? { model3dViewPresetId: model3dLifecyclePatch.presetId, model3dRawPreservationCleared: model3dLifecyclePatch.clearRaw } : {}),
	}
}

// Deck-level transform: walks every slide and every shape, applies a recipe.
// Two transform kinds (composable, generic):
//   • colorMap: { 'FFAAFF': '00FF00', ... } — replaces hex colours anywhere
//     in any shape's fill/line/text-run/color/etc.
//   • patch + filter: { kinds?, objectNames?, slideRange? } + the same deep
//     patch as update_shape — applies to every matching shape.
// Both can be used in the same call.
// ---------------------------------------------------------------------------
//  Color resolver — the single source of truth for "what should this hex
//  become?". Built once per transform call. Supports:
//    • colorMap:        explicit { OLDHEX: NEWHEX } find/replace
//    • colorTransform:  a generic color-math function applied to EVERY hex
//      ('invertLightness' | 'invert' | 'grayscale' | 'complement' |
//       'rotateHue:N' | 'darken:N' | 'lighten:N' | 'saturate:N' | 'desaturate:N')
//  colorMap wins for any hex it explicitly lists; colorTransform handles the rest.
//  Returns null for "leave unchanged" so callers can count real changes.
// ---------------------------------------------------------------------------
function makeColorTransformFn(spec) {
	let kind, amount
	if (typeof spec === 'string') {
		const idx = spec.indexOf(':')
		if (idx >= 0) { kind = spec.slice(0, idx); amount = parseFloat(spec.slice(idx + 1)) }
		else { kind = spec }
	} else if (spec && typeof spec === 'object') {
		kind = spec.kind; amount = spec.amount
	}
	if (!kind) return null
	return (hex) => {
		const r = parseInt(hex.slice(0, 2), 16), g = parseInt(hex.slice(2, 4), 16), b = parseInt(hex.slice(4, 6), 16)
		if (![r, g, b].every(Number.isFinite)) return null
		switch (kind) {
			case 'invert': return hexFromRgb(255 - r, 255 - g, 255 - b)
			case 'grayscale': { const y = 0.299 * r + 0.587 * g + 0.114 * b; return hexFromRgb(y, y, y) }
			default: break
		}
		let [h, s, l] = rgbToHsl(r, g, b)
		switch (kind) {
			case 'invertLightness': l = 1 - l; break
			case 'complement': h = (h + 180) % 360; break
			case 'rotateHue': h = (((h + (Number.isFinite(amount) ? amount : 180)) % 360) + 360) % 360; break
			case 'darken': l = Math.max(0, l - (Number.isFinite(amount) ? amount : 0.2)); break
			case 'lighten': l = Math.min(1, l + (Number.isFinite(amount) ? amount : 0.2)); break
			case 'saturate': s = Math.min(1, s + (Number.isFinite(amount) ? amount : 0.2)); break
			case 'desaturate': s = Math.max(0, s - (Number.isFinite(amount) ? amount : 0.2)); break
			default: return null
		}
		return hslToHex(h, s, l)
	}
}

function makeRecolorResolver({ colorMap, colorTransform } = {}) {
	const map = colorMap ? Object.fromEntries(
		Object.entries(colorMap).map(([k, v]) => [String(k).toUpperCase(), String(v).toUpperCase()])
	) : null
	const xform = colorTransform ? makeColorTransformFn(colorTransform) : null
	if (!map && !xform) return null
	return (hex) => {
		const upper = String(hex).toUpperCase()
		if (map && Object.prototype.hasOwnProperty.call(map, upper)) {
			return map[upper] === upper ? null : map[upper]
		}
		if (xform) {
			const out = xform(upper)
			return (out && out.toUpperCase() !== upper) ? out : null
		}
		return null
	}
}

function _remapColorsInString(value, recolor) {
	let count = 0
	const text = String(value ?? '')
	const out = text.replace(/\b([0-9A-F]{6})\b/gi, (match, hex) => {
		const next = recolor(hex)
		if (next == null) return match
		count++
		return next
	})
	return { value: out, count }
}

function _remapColorsInXmlString(value, recolor) {
	let count = 0
	let out = String(value ?? '')
	const remapAttr = (_match, prefix, hex, suffix) => {
		const next = recolor(hex)
		if (next == null) return `${prefix}${hex}${suffix}`
		count++
		return `${prefix}${next}${suffix}`
	}
	out = out.replace(/(<[A-Za-z_][\w.-]*:srgbClr\b[^>]*\bval\s*=\s*["'])([0-9A-Fa-f]{6})(["'])/g, remapAttr)
	out = out.replace(/(\blastClr\s*=\s*["'])([0-9A-Fa-f]{6})(["'])/g, remapAttr)
	out = out.replace(/(\b(?:color|fillcolor|strokecolor)\s*=\s*["']#?)([0-9A-Fa-f]{6})(["'])/g, remapAttr)
	return { value: out, count }
}

// Recolor structured pptxgenjs options/data IN PLACE.
//   • `seen` (WeakSet) guards against processing the SAME object/array twice —
//     pptxgenjs makes obj.options === obj.text[0].options for text shapes, so
//     without the guard a non-idempotent colorTransform (e.g. invertLightness)
//     would be applied twice and cancel itself out.
//   • SAFETY: a 6-digit token is only treated as a colour when it is EITHER a
//     string value that is EXACTLY 6 hex chars (e.g. options.color = 'FF0000',
//     chartColors:['FF0000',...]) OR appears inside a recognised colour XML
//     attribute (srgbClr/lastClr/color=). Bare 6-digit tokens inside arbitrary
//     strings (e.g. creationId="410006", coordinate fragments in native-hint
//     XML) are NEVER touched. This is what makes recolor safe on round-tripped
//     native decks (WordArt creationIds, etc.).
const _PURE_HEX_RE = /^[0-9A-Fa-f]{6}$/
function _remapColorsInPlace(value, recolor, seen) {
	if (!seen) seen = new WeakSet()
	let count = 0
	if (Array.isArray(value)) {
		if (seen.has(value)) return 0
		seen.add(value)
		for (let i = 0; i < value.length; i++) {
			const el = value[i]
			if (typeof el === 'string') {
				if (_PURE_HEX_RE.test(el)) {
					const next = recolor(el)
					if (next != null) { value[i] = next; count++ }
				} else {
					const remapped = _remapColorsInXmlString(el, recolor)
					if (remapped.value !== el) value[i] = remapped.value
					count += remapped.count
				}
			} else {
				count += _remapColorsInPlace(el, recolor, seen)
			}
		}
		return count
	}
	if (!value || typeof value !== 'object') return 0
	if (seen.has(value)) return 0
	seen.add(value)
	for (const k of Object.keys(value)) {
		const v = value[k]
		if (typeof v === 'string') {
			if (_PURE_HEX_RE.test(v)) {
				const next = recolor(v)
				if (next != null) { value[k] = next; count++ }
			} else {
				// Only recolour hex inside recognised colour XML attributes; never
				// bare numeric tokens in arbitrary strings (IDs, coordinates, ...).
				const remapped = _remapColorsInXmlString(v, recolor)
				if (remapped.value !== v) value[k] = remapped.value
				count += remapped.count
			}
		} else if (v && typeof v === 'object') {
			count += _remapColorsInPlace(v, recolor, seen)
		}
	}
	return count
}

function _remapPassthroughXmlInPlace(obj, recolor) {
	if (!obj?.passthrough?.xml) return 0
	const before = obj.passthrough.xml
	const remapped = _remapColorsInXmlString(before, recolor)
	if (remapped.value !== before) obj.passthrough.xml = remapped.value
	return remapped.count
}

function _rawPartLooksXml(part) {
	const p = String(part?.path || '').toLowerCase()
	return p.endsWith('.xml') || p.endsWith('.rels')
}

function _getRawPartText(part) {
	const data = part?.data
	if (data == null) return ''
	if (part.encoding === 'base64') return Buffer.from(String(data), 'base64').toString('utf8')
	return String(data)
}

function _setRawPartText(part, text) {
	if (part.encoding === 'base64') {
		part.data = Buffer.from(String(text), 'utf8').toString('base64')
	} else {
		part.data = String(text)
	}
}

function _headerFooterBoolean(policy, primary, alias) {
	const value = policy?.[primary] ?? policy?.[alias]
	return value === true || value === 1 || String(value).toLowerCase() === 'true' || String(value) === '1'
}

// Mutate only the native p:hf visibility node in an imported layout/master.
// Keeping this narrow preserves every unrelated source relationship and XML
// payload while allowing typed header/footer policy edits on opaque carriers.
function _setRawHeaderFooterPolicy(part, policy) {
	if (!part) return false
	const source = _getRawPartText(part)
	if (!source) return false
	const doc = new DOMParser().parseFromString(source, 'application/xml')
	const root = doc?.documentElement
	if (!root) return false
	let hf = _xmlDirectChild(root, 'hf')
	if (!policy) {
		if (hf) root.removeChild(hf)
		_setRawPartText(part, new XMLSerializer().serializeToString(doc))
		return true
	}
	if (!hf) {
		hf = doc.createElementNS('http://schemas.openxmlformats.org/presentationml/2006/main', 'p:hf')
		const before = _xmlElementChildren(root).find(child => ['timing', 'extLst'].includes(_xmlLocalName(child)))
		if (before) root.insertBefore(hf, before)
		else root.appendChild(hf)
	}
	hf.setAttribute('sldNum', _headerFooterBoolean(policy, 'slideNumber', 'showSlideNumber') ? '1' : '0')
	hf.setAttribute('hdr', _headerFooterBoolean(policy, 'header', 'showHeader') ? '1' : '0')
	hf.setAttribute('ftr', _headerFooterBoolean(policy, 'footer', 'showFooter') ? '1' : '0')
	hf.setAttribute('dt', _headerFooterBoolean(policy, 'date', 'showDate') ? '1' : '0')
	_setRawPartText(part, new XMLSerializer().serializeToString(doc))
	return true
}

function _remapRawPackagePartsInPlace(pptx, recolor) {
	const rawParts = Array.isArray(pptx?._rawPackageParts) ? pptx._rawPackageParts : []
	let partsTouched = 0
	let colorsRemapped = 0
	for (const part of rawParts) {
		if (!_rawPartLooksXml(part)) continue
		const before = _getRawPartText(part)
		if (!before) continue
		const remapped = _remapColorsInXmlString(before, recolor)
		if (remapped.value !== before) {
			_setRawPartText(part, remapped.value)
			partsTouched++
			colorsRemapped += remapped.count
		}
	}
	return { partsTouched, colorsRemapped }
}

async function handleTransformShapes(args) {
	const { pptx } = getDeck(args.deckId)
	_validateTransformTextFillPatch(pptx, args)
	_validateTransformNativeGradientLinePatch(pptx, args)
	const recolor = makeRecolorResolver({ colorMap: args.colorMap, colorTransform: args.colorTransform })
	const colorMap = recolor  // truthy gate: any color operation requested
	const filter = args.filter || {}
	const patchInput = args.patch || null
	const sliceFrom = filter.slideRange?.[0] ?? 0
	const sliceTo = filter.slideRange?.[1] ?? pptx.slides.length - 1
	let shapesTouched = 0
	let colorsRemapped = 0
	let rawXmlColorsRemapped = 0
	let rawTimingColorsRemapped = 0
	let rawPackagePartsTouched = 0
	const slideCounts = []
	for (let si = sliceFrom; si <= sliceTo && si < pptx.slides.length; si++) {
		const slide = pptx.slides[si]
		const objects = _editableSlideObjects(slide).map(x => x.obj)
		let slideTouched = 0
		for (let i = 0; i < objects.length; i++) {
			const obj = objects[i]
			const opts = obj.options || {}
			if (filter.kinds && filter.kinds.length > 0 && !filter.kinds.includes(obj.type || obj._type)) continue
			if (filter.objectNames && filter.objectNames.length > 0 && !filter.objectNames.includes(opts.objectName)) continue
			if (filter.objectNameRegex) {
				const rx = new RegExp(filter.objectNameRegex)
				if (!opts.objectName || !rx.test(opts.objectName)) continue
			}
			let touched = false
			if (recolor) {
				// One shared `seen` set per shape so shapes whose obj.options and
				// obj.text[0].options are the SAME reference aren't recolored twice.
				const seen = new WeakSet()
				const before = JSON.stringify(opts)
				const remappedInOptions = _remapColorsInPlace(opts, recolor, seen)
				let remappedInText = 0
				// Recolour run-level colours inside obj.text (array of runs). When
				// obj.text is a plain string it's literal display text — NOT a colour —
				// so we leave it alone (its colour lives in obj.options.color).
				if (Array.isArray(obj.text)) {
					remappedInText = _remapColorsInPlace(obj.text, recolor, seen)
				}
				const remappedInXml = _remapPassthroughXmlInPlace(obj, recolor)
				const after = JSON.stringify(opts)
				const remappedCount = remappedInOptions + remappedInText + remappedInXml
				if (before !== after || remappedCount > 0) {
					touched = true
					colorsRemapped += remappedInOptions + remappedInText
					rawXmlColorsRemapped += remappedInXml
				}
			}
			if (patchInput) {
				const textFillPatch = _prepareTextFillPatch(obj, patchInput, 'deck.transform_shapes patch.textFill')
				const patch = normalizeVisualOptions(patchInput, 'deck.transform_shapes patch', obj.options)
				if (!obj.options) obj.options = {}
				_clearRawEditBlockers(obj, patch)
				_deepMerge(obj.options, patch)
				_applyTextFillPatch(obj, textFillPatch)
				touched = true
			}
			if (touched) { shapesTouched++; slideTouched++ }
		}
		// Also update background colour via the resolver
		if (recolor && slide.background && slide.background.color) {
			const next = recolor(slide.background.color)
			if (next != null) { slide.background.color = next; colorsRemapped++ }
		}
		if (recolor && slide._rawTimingXml) {
			const remapped = _remapColorsInXmlString(slide._rawTimingXml, recolor)
			if (remapped.value !== slide._rawTimingXml) slide._rawTimingXml = remapped.value
			rawTimingColorsRemapped += remapped.count
		}
		if (recolor && slide._rawTransitionXml) {
			const remapped = _remapColorsInXmlString(slide._rawTransitionXml, recolor)
			if (remapped.value !== slide._rawTransitionXml) slide._rawTransitionXml = remapped.value
			rawTimingColorsRemapped += remapped.count
		}
		slideCounts.push({ slideIndex: si, shapesTouched: slideTouched })
	}
	if (recolor) {
		const rawRemap = _remapRawPackagePartsInPlace(pptx, recolor)
		rawPackagePartsTouched = rawRemap.partsTouched
		rawXmlColorsRemapped += rawRemap.colorsRemapped
	}
	return { ok: true, shapesTouched, colorsRemapped, rawXmlColorsRemapped, rawTimingColorsRemapped, rawPackagePartsTouched, slideCounts }
}

async function handleAnimateShapes(args) {
	const slide = getSlide(args.deckId, args.slideIndex)
	const animation = normalizeAnimation(validateAnimationFormatOptions(args.animation, 'animation'))
	const targets = []
	const objects = _editableSlideObjects(slide)
	let selectedObjects = objects
	if (Array.isArray(args.names) && args.names.length) {
		const descendants = []
		const visit = (children, rawIndex) => {
			for (const child of children || []) {
				if (child._nativeObject) descendants.push({ obj: child._nativeObject, rawIndex, descendant: true })
				if (child.kind === 'group') visit(child.children, rawIndex)
			}
		}
		for (const { obj, rawIndex } of objects) if ((obj.type || obj._type) === 'group') visit((obj.group || obj.options)?.children, rawIndex)
		const namedCandidates = [...objects, ...descendants]
		const selected = new Set()
		// Resolve the complete name set before adding even the first animation.
		for (const name of new Set(args.names)) {
			const matches = namedCandidates.filter(item => item.obj.options?.objectName === name)
			if (matches.length > 1) throw new Error(`Animation target name "${name}" is ambiguous; give each explicitly targeted object a unique name.`)
			if (!matches.length) throw new Error(`Animation target name "${name}" was not found among the slide's native editable objects. Opaque imported group children cannot be targeted.`)
			if (matches[0].descendant && Array.isArray(args.indices) && args.indices.length) throw new Error('Named descendant animations cannot be combined with top-level index selectors.')
			if (matches[0].descendant && (slide._slideObjects || []).some(obj => obj.passthrough?.xml)) throw new Error('Named descendant animation is unavailable while the slide contains opaque imported objects. Reconstruct the group as native editable objects first.')
			selected.add(matches[0])
		}
		selectedObjects = namedCandidates.filter(item => selected.has(item))
	}
	let appliedCount = 0
	const hadRawTiming = Boolean(slide._rawTimingXml)
	let replacedRawTiming = false
	for (let selectedIndex = 0; selectedIndex < selectedObjects.length; selectedIndex++) {
		const item = selectedObjects[selectedIndex]
		const { obj, rawIndex } = item
		const i = item.descendant ? null : objects.indexOf(item)
		const opts = obj.options || {}
		const passesName = !args.names || args.names.length === 0 || args.names.includes(opts.objectName)
		const passesKind = !args.kinds || args.kinds.length === 0 || args.kinds.includes(obj.type || obj._type)
		const passesIndex = !args.indices || args.indices.length === 0 || args.indices.includes(i)
		if (passesName && passesKind && passesIndex) {
			const a = args.staggerMs ? { ...animation, delay: (animation.delay || 0) + appliedCount * args.staggerMs } : animation
			slide.addAnimation(obj, a)
			targets.push({ index: i, rawIndex, objectName: opts.objectName, kind: obj.type || obj._type, ...(item.descendant ? { descendant: true } : {}) })
			appliedCount++
		}
	}
	if (appliedCount > 0 && slide._rawTimingXml && args.preserveExistingTiming !== true) {
		delete slide._rawTimingXml
		replacedRawTiming = true
	}
	return {
		slideIndex: args.slideIndex,
		animationsApplied: appliedCount,
		targets,
		replacedRawTiming,
		generatedAnimationsMaskedByRawTiming: hadRawTiming && appliedCount > 0 && args.preserveExistingTiming === true,
	}
}

async function handleSetTransitionsAll(args) {
	const { pptx } = getDeck(args.deckId)
	validateTransitionFormatOptions(args.transition, 'transition')
	if (Array.isArray(args.variants)) args.variants.forEach((item, index) => validateTransitionFormatOptions(item, `variants[${index}]`))
	const t = resolveTransitionPreset(args.transition || { type: 'fade', speed: 'medium' })
	const variants = (args.variants || []).map(resolveTransitionPreset)  // optional: list of transition objects to rotate through
	// fillOnly = treat this as a DEFAULT policy: keep any explicit per-slide transition
	// (e.g. a Morph on a key slide) and only fill slides that have none. A deck-wide
	// transitionPolicy compiles with fillOnly:true so per-slide authoring wins; an
	// explicit set_transitions_all (or force) overwrites every slide.
	const fillOnly = args.fillOnly === true
	let updated = 0
	for (let i = 0; i < pptx.slides.length; i++) {
		if (fillOnly && pptx.slides[i].transition) continue
		const useT = variants.length > 0 ? variants[i % variants.length] : t
		pptx.slides[i].transition = { ...useT }
		updated++
	}
	// A JSON-spec transition policy is an explicit Director timeline when it
	// supplies a positive per-slide dwell. Record that contract at the same
	// mutation boundary so save validation can rely on the authored timing.
	if (pptx.slides.length > 0 && pptx.slides.every(slide => Number(slide?.transition?.advanceAfterTime) > 0)) {
		markDirectorTimelineContract(getDeck(args.deckId), 'explicit-director-timeline')
	}
	return { ok: true, slidesUpdated: updated, fillOnly }
}

async function handleSetSlideTransition(args) {
	const slide = getSlide(args.deckId, args.slideIndex)
	validateTransitionFormatOptions(args.transition, 'transition')
	const transition = resolveTransitionPreset(args.transition || null)
	if (transition) slide.transition = { ...transition }
	else slide.transition = undefined
	return { ok: true, slideIndex: args.slideIndex, transition: slide.transition || null }
}

function _slideNotesText(slide) {
	return (slide?._slideObjects || [])
		.filter(obj => (obj?.type || obj?._type) === 'notes')
		.map(obj => obj?.text?.[0]?.text || '')
		.join('')
}

// Attach the narration SCRIPT under the BetterPPTX-owned rubric. User notes remain opaque and
// byte-stable apart from PowerPoint's own notes-text normalization. Legacy [narration] uploads
// are accepted and migrate to the canonical marker the next time BetterPPTX rewrites the block.
function _addNarrationNotes(slide, script) {
	if (!script) return
	const existing = _slideNotesText(slide) || ''
	const owned = _splitNarrationNotes(existing)
	const norm = t => String(t || '').replace(/\s+/g, ' ').trim()
	if (owned.rubric) {
		// TEXT IS MASTER — the rubric IS what is spoken. If the narration being embedded differs
		// from the current rubric (e.g. elevate derived a richer script over an authoring-time
		// message), REPLACE the rubric so notes and audio never diverge (a divergent rubric would
		// also make every future renarrate see a phantom edit). Canonicalize a legacy marker even
		// when the spoken words are unchanged.
		if (!owned.legacy && norm(owned.narration) === norm(script)) return
		_clearSlideNotes(slide)
		slide.addNotes(_composeNarrationNotes(owned.userNotes, script))
		return
	}
	_clearSlideNotes(slide)
	slide.addNotes(_composeNarrationNotes(existing, script))
}

function _clearSlideNotes(slide) {
	const before = (slide._slideObjects || []).length
	slide._slideObjects = (slide._slideObjects || []).filter(obj => (obj?.type || obj?._type) !== 'notes')
	return before - slide._slideObjects.length
}

async function handleInspectSlide(args) {
	const slide = getSlide(args.deckId, args.slideIndex)
	return {
		ok: true,
		slideIndex: args.slideIndex,
		slideNum: slide._slideNum,
		layoutName: slide._slideLayout?._name || slide._templateLayoutName || null,
		background: slide.background || null,
		color: slide.color,
		hidden: slide.hidden === true,
		showMasterShapes: slide._showMasterSp !== false,
		showMasterBackground: slide._showMasterSp !== false,
		showMasterPhAnim: slide._showMasterPhAnim !== false,
		transition: slide.transition || null,
		slideNumber: slide.slideNumber || null,
		notes: _slideNotesText(slide),
		objectCount: _editableSlideObjects(slide).length,
	}
}

async function handleUpdateSlide(args) {
	const slide = getSlide(args.deckId, args.slideIndex)
	const patch = { ...(args.patch && typeof args.patch === 'object' ? args.patch : args) }
	// "showMasterBackground" is PowerPoint's semantic UI label for the
	// p:sld@showMasterSp carrier. Normalize the alias once at the native
	// boundary; when both names are supplied, the canonical carrier wins.
	if (Object.prototype.hasOwnProperty.call(patch, 'showMasterShapes') && Object.prototype.hasOwnProperty.call(patch, 'showMasterBackground') && patch.showMasterShapes !== patch.showMasterBackground) {
		throw new Error('slide.update: showMasterShapes and showMasterBackground must agree when both are supplied.')
	}
	if (!Object.prototype.hasOwnProperty.call(patch, 'showMasterShapes') && Object.prototype.hasOwnProperty.call(patch, 'showMasterBackground')) {
		patch.showMasterShapes = patch.showMasterBackground
	}
	if (patch.background) patch.background = resolveNativeFillAssetRefs(normalizeSlideBackground(patch.background))
	const updated = []
	const has = key => Object.prototype.hasOwnProperty.call(patch, key)
	if (has('background')) {
		// Slide.background is an accessor backed by the private _background field;
		// deleting the accessor does not clear that field and leaves the old fill
		// visible to the XML serializer.  Assign undefined so an explicit JSON
		// null genuinely restores master/theme inheritance.
		if (patch.background == null) slide.background = undefined
		else slide.background = patch.background
		updated.push('background')
	}
	if (has('color')) {
		if (patch.color == null) delete slide.color
		else slide.color = patch.color
		updated.push('color')
	}
	if (has('hidden')) {
		// PresSlide.hidden is a boolean accessor backed by the private _hidden
		// slot; deleting the accessor leaves the old value in place.  A nullable
		// reset therefore means the native/default visible state.
		if (patch.hidden == null) slide.hidden = false
		else slide.hidden = Boolean(patch.hidden)
		updated.push('hidden')
	}
	if (has('showMasterShapes')) {
		if (patch.showMasterShapes == null) delete slide._showMasterSp
		else slide._showMasterSp = Boolean(patch.showMasterShapes)
		updated.push('showMasterShapes')
	}
	if (has('showMasterPhAnim')) {
		if (patch.showMasterPhAnim == null) delete slide._showMasterPhAnim
		else slide._showMasterPhAnim = Boolean(patch.showMasterPhAnim)
		updated.push('showMasterPhAnim')
	}
	if (has('colorMapOverride')) {
		slide._colorMapOverride = normalizeInheritanceColorMap(patch.colorMapOverride, 'slide.update colorMapOverride') || null
		updated.push('colorMapOverride')
	}
	if (has('slideNumber')) {
		// The public slideNumber setter also propagates to the presentation
		// master/layout.  A slide-level nullable reset must clear only this
		// slide's private carrier so inherited master/layout numbering remains
		// intact.
		if (patch.slideNumber == null) slide._slideNumberProps = undefined
		else slide.slideNumber = patch.slideNumber
		updated.push('slideNumber')
	}
	if (has('transition')) {
		if (patch.transition == null) slide.transition = undefined
		else {
			validateTransitionFormatOptions(patch.transition, 'slide.update transition')
			slide.transition = { ...resolveTransitionPreset(patch.transition) }
		}
		updated.push('transition')
	}
	if (has('notes') || has('notesMode')) {
		const mode = String(patch.notesMode || (patch.notes == null ? 'clear' : 'replace')).toLowerCase()
		if (!['replace', 'append', 'clear'].includes(mode)) throw new Error('slide.update: notesMode must be replace, append, or clear.')
		const text = patch.notes == null ? '' : String(patch.notes)
		let removed = 0
		if (mode === 'replace' || mode === 'clear') removed = _clearSlideNotes(slide)
		if (mode !== 'clear' && text) slide.addNotes(text)
		updated.push('notes')
		return { ok: true, slideIndex: args.slideIndex, updated, notesMode: mode, notesRemoved: removed, notes: _slideNotesText(slide) }
	}
	return {
		ok: true,
		slideIndex: args.slideIndex,
		updated,
		transition: slide.transition || null,
		background: slide.background || null,
		hidden: slide.hidden === true,
		showMasterShapes: slide._showMasterSp !== false,
		showMasterBackground: slide._showMasterSp !== false,
		showMasterPhAnim: slide._showMasterPhAnim !== false,
		colorMapOverride: slide._colorMapOverride || null,
		slideNumber: slide.slideNumber || null,
	}
}

function _selectShapeTargets(slide, args = {}, toolName = 'shape selection') {
	const editable = _editableSlideObjects(slide)
	const selected = new Map()
	const addResolved = resolved => {
		if (!resolved?.obj || resolved.rawIndex < 0) return
		selected.set(resolved.rawIndex, {
			obj: resolved.obj,
			index: resolved.index,
			rawIndex: resolved.rawIndex,
			objectName: resolved.obj.options?.objectName,
			kind: _shapeKind(resolved.obj),
		})
	}
	if (args.target != null) addResolved(_resolveShapeForTool(slide, args.target, toolName))
	for (const target of args.targets || []) addResolved(_resolveShapeForTool(slide, target, toolName))
	for (const index of args.indices || []) {
		const n = Number(index)
		if (Number.isInteger(n)) addResolved({ obj: editable[n]?.obj, index: n, rawIndex: editable[n]?.rawIndex })
	}
	for (const objectName of [...(args.names || []), ...(args.objectNames || [])]) {
		addResolved(_resolveShapeForTool(slide, { objectName }, toolName))
	}
	const kinds = Array.isArray(args.kinds) ? new Set(args.kinds.map(String)) : null
	let rx = null
	if (args.objectNameRegex) rx = new RegExp(String(args.objectNameRegex))
	if (kinds || rx) {
		for (let i = 0; i < editable.length; i++) {
			const obj = editable[i].obj
			const name = obj.options?.objectName || ''
			if (kinds && !kinds.has(String(_shapeKind(obj)))) continue
			if (rx && !rx.test(name)) continue
			addResolved({ obj, index: i, rawIndex: editable[i].rawIndex })
		}
	}
	const out = Array.from(selected.values()).sort((a, b) => a.rawIndex - b.rawIndex)
	if (!out.length && args.allowEmpty !== true) throw new Error(`${toolName}: no shapes matched. Available: ${_availableShapeTargets(slide)}`)
	return out
}

async function handleDeleteShapes(args) {
	const slide = getSlide(args.deckId, args.slideIndex)
	const targets = _selectShapeTargets(slide, args, 'slide.delete_shapes')
	for (const item of [...targets].sort((a, b) => b.rawIndex - a.rawIndex)) {
		const obj = item.obj
		const kind = _shapeKind(obj)
		const textHyperlinkRids = (kind === 'text' || kind === 'shape' || kind === 'table')
			? _textHyperlinkRelationshipIds(obj)
			: new Set()
		if (kind === 'image') {
			const ownedMediaRids = new Set([obj.imageRid, obj.artisticEffectRid].map(Number).filter(Number.isFinite))
			for (const rel of slide._relsMedia || []) {
				if (rel?.isSvgPng === true && ownedMediaRids.has(Number(rel.rId) + 1)) ownedMediaRids.add(Number(rel.rId))
				if (ownedMediaRids.has(Number(rel?.artisticEffectSourceRid))) ownedMediaRids.add(Number(rel.rId))
			}
			slide._relsMedia = (slide._relsMedia || []).filter(rel => !ownedMediaRids.has(Number(rel?.rId)))
			const hyperlinkRid = Number(obj.hyperlink?._rId)
			if (Number.isFinite(hyperlinkRid)) slide._rels = (slide._rels || []).filter(rel => Number(rel?.rId) !== hyperlinkRid)
		}
		if (kind === 'media') {
			const ownedMediaRids = new Set(_mediaRelationshipIds(obj))
			for (const track of obj.options?.closedCaptionTracks || []) {
				const rId = Number(track?.rId)
				if (Number.isFinite(rId) && rId > 0) ownedMediaRids.add(rId)
			}
			slide._relsMedia = (slide._relsMedia || []).filter(rel => !ownedMediaRids.has(Number(rel?.rId)))
			const spid = Number(obj.options?.spid)
			slide._animations = (slide._animations || []).filter(record => record?.target !== obj && !_isMediaAnimationRecord(record, spid, obj))
		}
		if (kind === 'model3d') {
			const ownedMediaRids = new Set([obj.model3dRid, obj.rasterRid].map(Number).filter(rid => Number.isFinite(rid) && rid > 0))
			if (ownedMediaRids.size) slide._relsMedia = (slide._relsMedia || []).filter(rel => !ownedMediaRids.has(Number(rel?.rId)))
			const spid = Number(obj.options?.spid)
			slide._animations = (slide._animations || []).filter(record => record?.target !== obj && (!Number.isFinite(spid) || Number(record?.targetSpid) !== spid))
		}
		if (kind === 'zoom' || kind === 'sectionZoom') {
			const imageRid = Number(obj.imageRid)
			const slideRid = Number(obj.options?._zoomSlideRid)
			if (Number.isFinite(imageRid)) slide._relsMedia = (slide._relsMedia || []).filter(rel => Number(rel?.rId) !== imageRid)
			if (Number.isFinite(slideRid)) slide._rels = (slide._rels || []).filter(rel => Number(rel?.rId) !== slideRid)
		}
		if (kind === 'summaryZoom') {
			const imageRids = new Set((obj.options?._summaryObjs || []).map(item => Number(item?.thumbRid)).filter(Number.isFinite))
			const slideRids = new Set((obj.options?._summaryObjs || []).map(item => Number(item?.slideRid)).filter(Number.isFinite))
			slide._relsMedia = (slide._relsMedia || []).filter(rel => !imageRids.has(Number(rel?.rId)))
			slide._rels = (slide._rels || []).filter(rel => !slideRids.has(Number(rel?.rId)))
		}
		if (kind === 'equation') {
			const fallbackRid = Number(obj.fallbackRid)
			if (Number.isFinite(fallbackRid) && fallbackRid > 0) {
				slide._relsMedia = (slide._relsMedia || []).filter(rel => Number(rel?.rId) !== fallbackRid)
			}
			const spid = Number(obj.options?.spid)
			if (Number.isFinite(spid)) slide._animations = (slide._animations || []).filter(record => record?.target !== obj && Number(record?.targetSpid) !== spid)
		}
		if (kind === 'chart') {
			const chartRid = Number(obj.chartRid)
			if (Number.isFinite(chartRid) && chartRid > 0) {
				slide._relsChart = (slide._relsChart || []).filter(rel => Number(rel?.rId) !== chartRid)
			}
			const numericRid = value => {
				const token = String(value ?? '').replace(/^rId/i, '')
				const rid = Number(token)
				return Number.isFinite(rid) && rid > 0 ? rid : null
			}
			const fallbackMediaRids = new Set([
				obj.fallbackRid,
				obj.imageRid,
				obj.options?._rawChartFallbackImageRid,
				obj.options?.fallbackRid,
				obj.options?.imageRid,
			].map(numericRid).filter(rid => rid !== null))
			if (fallbackMediaRids.size) {
				slide._relsMedia = (slide._relsMedia || []).filter(rel => !fallbackMediaRids.has(numericRid(rel?.rId)))
			}
		}
		slide._slideObjects.splice(item.rawIndex, 1)
		_removeUnreferencedTextHyperlinkRelationships(slide, textHyperlinkRids)
		if ((kind === 'media' || kind === 'model3d') && typeof slide._rawTimingXml === 'string' && slide._rawTimingXml.trim()) {
			const sanitized = sanitizeTimingXmlForSlide(slide._rawTimingXml, collectSlideObjectSpids(slide))
			if (sanitized.xml && sanitized.xml.trim()) {
				slide._rawTimingXml = sanitized.xml
				try {
					const manifest = buildNativeTimingManifest(slide, sanitized.xml)
					if (manifest) slide._nativeTimingManifest = manifest
					else delete slide._nativeTimingManifest
				} catch { delete slide._nativeTimingManifest }
			} else {
				delete slide._rawTimingXml
				delete slide._nativeTimingManifest
			}
		}
	}
	return {
		ok: true,
		slideIndex: args.slideIndex,
		deletedCount: targets.length,
		deleted: targets.map(({ index, rawIndex, objectName, kind }) => ({ index, rawIndex, objectName, kind })),
		remainingObjects: _editableSlideObjects(slide).length,
	}
}

async function handleReorderShape(args) {
	const slide = getSlide(args.deckId, args.slideIndex)
	const rawObjects = slide._slideObjects || []
	const resolved = _resolveShapeForTool(slide, args.target ?? args.fromIndex ?? args.index, 'slide.reorder_shape')
	const moving = rawObjects[resolved.rawIndex]
	if (!moving) throw new Error(`slide.reorder_shape: target not found. Available: ${_availableShapeTargets(slide)}`)
	const oldIndex = resolved.index
	rawObjects.splice(resolved.rawIndex, 1)
	const editableAfter = _editableSlideObjects(slide)
	let toIndex
	const position = String(args.position || '').toLowerCase()
	if (position === 'front') toIndex = editableAfter.length
	else if (position === 'back') toIndex = 0
	else if (position === 'forward') toIndex = Math.min(editableAfter.length, oldIndex + 1)
	else if (position === 'backward') toIndex = Math.max(0, oldIndex - 1)
	else if (args.toIndex != null) toIndex = Number(args.toIndex)
	else throw new Error('slide.reorder_shape: pass toIndex or position front|back|forward|backward.')
	if (!Number.isInteger(toIndex)) throw new Error(`slide.reorder_shape: invalid toIndex ${args.toIndex}.`)
	toIndex = Math.max(0, Math.min(toIndex, editableAfter.length))
	let destRaw
	if (!editableAfter.length) destRaw = rawObjects.length
	else if (toIndex <= 0) destRaw = editableAfter[0].rawIndex
	else if (toIndex >= editableAfter.length) destRaw = editableAfter[editableAfter.length - 1].rawIndex + 1
	else destRaw = editableAfter[toIndex].rawIndex
	rawObjects.splice(destRaw, 0, moving)
	const after = _resolveShape(slide, { rawIndex: destRaw })
	return {
		ok: true,
		slideIndex: args.slideIndex,
		objectName: moving.options?.objectName,
		kind: _shapeKind(moving),
		fromIndex: oldIndex,
		toIndex: after.index,
		rawIndex: destRaw,
	}
}

async function handleAutoplay(args) {
	const { pptx } = getDeck(args.deckId)
	const secs = args.secondsPerSlide ?? 6
	const advanceMs = secondsToMs(secs)
	pptx.showSettings = {
		...(pptx.showSettings || {}),
		useTimings: true,
		showAnimation: true,
		showNarration: args.showNarration === true ? true : (args.showNarration === false ? false : pptx.showSettings?.showNarration),
		loop: args.loop !== false,
		mode: args.mode || 'kiosk',
	}
	const defaultTransition = args.defaultTransition || { type: 'fade', speed: 'medium' }
	validateTransitionFormatOptions(defaultTransition, 'defaultTransition')
	for (const slide of pptx.slides) {
		const t = slide.transition || { ...defaultTransition }
		t.advanceOnClick = false
		if (!(args.preserveTimedSlides === true && Number(t.advanceAfterTime) > 0)) t.advanceAfterTime = advanceMs
		slide.transition = t
		_retimeRawTransitionXml(slide, t.advanceAfterTime)
	}
	return { ok: true, slidesUpdated: pptx.slides.length, secondsPerSlide: secs, advanceAfterTime: advanceMs, defaultAdvanceAfterTime: advanceMs, preserveTimedSlides: args.preserveTimedSlides === true, showSettings: pptx.showSettings }
}

// The autoplay sync spine (default). Sets PER-SLIDE auto-advance timing derived from each
// slide's narration script duration, so transitions + animations are timed to the spoken
// layer. Augments each slide's EXISTING transition (preserving the world visual transition —
// this runs after set_transitions_all) and keeps advanceOnClick so a presenter can still
// click through. Slides with explicit narration audio are skipped (perSlideMs null) — their
// add_narration op sets the real audio-driven timing.
async function handleApplyAutoTimings(args) {
	const { pptx } = getDeck(args.deckId)
	const perSlide = Array.isArray(args.perSlideMs) ? args.perSlideMs : []
	const advanceOnClick = args.advanceOnClick !== false
	pptx.showSettings = { ...(pptx.showSettings || {}), useTimings: true, showAnimation: true }
	let slidesUpdated = 0
	pptx.slides.forEach((slide, i) => {
		const raw = perSlide[i]
		if (raw == null || !Number.isFinite(Number(raw)) || Number(raw) <= 0) return
		const t = slide.transition || {}
		t.advanceAfterTime = clampAdvanceMs(Number(raw), 1000)
		t.advanceOnClick = advanceOnClick
		slide.transition = t
		slidesUpdated += 1
	})
	markDirectorTimelineContract(getDeck(args.deckId), 'explicit-director-timeline')
	return { ok: true, slidesUpdated, useTimings: true, advanceOnClick }
}

async function handleAddSlide(args) {
	const entry = getDeck(args.deckId)
	return runDeckIdempotent(entry, 'betterpptx.slide.add', args, async () => {
		const { pptx } = entry
		if (Object.prototype.hasOwnProperty.call(args, 'showMasterShapes') && Object.prototype.hasOwnProperty.call(args, 'showMasterBackground') && args.showMasterShapes !== args.showMasterBackground) {
			throw new Error('slide.add: showMasterShapes and showMasterBackground must agree when both are supplied.')
		}
		const resolvedBackground = args.background ? resolveNativeFillAssetRefs(normalizeSlideBackground(args.background)) : args.background
		const layoutBinding = _resolveSlideLayoutRequest(entry, args)
		// `layoutName` is the specific slide-layout relationship.  When both
		// selectors are present it must win over the legacy masterName alias;
		// otherwise a valid custom native layout is silently replaced by the
		// master pointer and its editable placeholder carrier never reaches the
		// slide.  A master-only request keeps the historical behavior.
		const nativeMasterName = layoutBinding.kind === 'native-master'
			? (args.layoutName != null ? layoutBinding.masterName : (args.masterName || layoutBinding.masterName))
			: args.masterName
		const slide = layoutBinding.kind === 'raw-template'
			? pptx.addSlide({ sectionTitle: args.sectionTitle })
			: pptx.addSlide({ masterName: nativeMasterName, sectionTitle: args.sectionTitle })
		if (args.layoutName != null) slide._betterpptxLayoutName = String(args.layoutName)
		if (args.masterName != null) slide._betterpptxMasterName = String(args.masterName)
		if (args.layoutPresetId != null) slide._betterpptxLayoutPresetId = String(args.layoutPresetId)
		if (args.templatePresetId != null) slide._betterpptxTemplatePresetId = String(args.templatePresetId)
		if (layoutBinding.kind === 'raw-template') {
			slide._betterpptxBaseSlideLayout = slide._slideLayout
			slide._rawSlideLayoutNumber = layoutBinding.layout.number
			slide._templateLayoutName = layoutBinding.layout.name
			slide._templateLayoutType = layoutBinding.layout.type
		}
		if (resolvedBackground) slide.background = resolvedBackground
		if (args.transition) {
			validateTransitionFormatOptions(args.transition, 'transition')
			slide.transition = resolveTransitionPreset(args.transition)
		}
		if (args.slideNumber) slide.slideNumber = args.slideNumber
		if (args.color) slide.color = args.color
		if (typeof args.hidden === 'boolean') slide.hidden = args.hidden
		if (typeof args.showMasterShapes === 'boolean') slide._showMasterSp = args.showMasterShapes
		else if (typeof args.showMasterBackground === 'boolean') slide._showMasterSp = args.showMasterBackground
		if (typeof args.showMasterPhAnim === 'boolean') slide._showMasterPhAnim = args.showMasterPhAnim
		if (Object.prototype.hasOwnProperty.call(args, 'colorMapOverride')) slide._colorMapOverride = normalizeInheritanceColorMap(args.colorMapOverride, 'slide.add colorMapOverride') || null
		if (args.notes) slide.addNotes(args.notes)
		// The compiler writes a narration rubric for every slide so text remains
		// the timing source. Keep the authored-vs-derived distinction on the
		// in-memory slide for canonical-spec export; derived fallback text must not
		// become a new TTS request after a cold-process rehydrate.
		if (typeof args.narrationAuthored === 'boolean') slide._narrationAuthored = args.narrationAuthored
		// Record the author's declared slide title for the accessibility gate. The visible
		// display heading carries it on-canvas; this preserves the title role without forcing
		// a top-anchored title placeholder that would disturb composition or morph pairing.
		if (args.title) {
			slide._betterpptxTitle = String(args.title)
			// Deeper accessibility: emit a REAL OOXML title placeholder (<p:ph type="title"/>)
			// so EXTERNAL checkers (PowerPoint's own Accessibility Checker + screen readers +
			// the outline/navigation pane) recognize the slide title too. Kept ON-slide (a
			// completely off-slide element is a package error) but FULLY TRANSPARENT + at the
			// very top edge, so it is screen-readable yet visually invisible — the display
			// heading carries the title on-canvas.
			try {
				slide.addText(String(args.title), {
					placeholder: 'title',
					x: 0.3, y: 0.02, w: 6, h: 0.32,
					fontSize: 12, color: '808080', transparency: 100, align: 'left',
					objectName: 'slide-title', altText: String(args.title),
				})
			} catch (_) { /* best-effort a11y title; visible heading + metadata still cover it */ }
		}
		return {
			ok: true,
			slideIndex: pptx.slides.length - 1,
			slideNum: slide._slideNum,
			layoutBinding: layoutBinding.kind === 'raw-template' ? {
				kind: layoutBinding.kind,
				layoutNumber: layoutBinding.layout.number,
				layoutName: layoutBinding.layout.name,
				layoutType: layoutBinding.layout.type,
			} : {
				kind: layoutBinding.kind,
				layoutName: layoutBinding.effective || nativeMasterName || slide._slideLayout?._name || null,
			},
		}
	})
}

function _deepCloneData(v) {
	if (v === undefined || v === null) return v
	try { return structuredClone(v) } catch (_) { return JSON.parse(JSON.stringify(v)) }
}

function _findChartRelForObject(sourceChartRels, chartObj) {
	const rels = Array.isArray(sourceChartRels) ? sourceChartRels : []
	return rels.find(rel => Number(rel?.rId) === Number(chartObj?.chartRid))
		|| rels.find(rel => rel?.opts === chartObj?.options)
		|| rels.find(rel => rel?.opts?.objectName && rel.opts.objectName === chartObj?.options?.objectName)
		|| null
}

function _appendRecreatedChartClone(newSlide, clonedObj, sourceChartRels) {
	if (_shapeKind(clonedObj) !== 'chart' || typeof newSlide?.addChart !== 'function') return false
	const sourceRel = _findChartRelForObject(sourceChartRels, clonedObj)
	const chartOptions = _deepCloneData(sourceRel?.opts || clonedObj?.options || {})
	const chartType = chartOptions?._type || sourceRel?.type
	if (!chartType) return false
	const chartData = _deepCloneData(sourceRel?.data || [])
	const beforeCount = Array.isArray(newSlide._slideObjects) ? newSlide._slideObjects.length : 0
	newSlide.addChart(chartType, chartData, chartOptions)
	const recreated = newSlide._slideObjects?.[newSlide._slideObjects.length - 1]
	if (!recreated || newSlide._slideObjects.length === beforeCount) return false
	for (const [key, value] of Object.entries(clonedObj || {})) {
		if (['_type', 'type', 'text', 'options', 'chartRid'].includes(key)) continue
		if (recreated[key] === undefined) recreated[key] = _deepCloneData(value)
	}
	return true
}

// Duplicate a slide into a NEW appended slide — a faithful, IDENTITY-PRESERVING
// clone (objects + their objectName/spid, all three rel arrays, background,
// layout). Preserving object identity is what lets PowerPoint MORPH match the
// objects across the consecutive pair and interpolate any subsequent edits — the
// "magic move". Passthrough objects clone verbatim so they keep their native
// a16:creationId (PowerPoint's own morph-match key); structured objects keep the
// same shape id + name, which morph's automatic matcher uses for duplicated-then-
// moved shapes. Optionally stamps a transition (e.g. morph) on the clone (the
// transition belongs on the slide being transitioned TO).
// Generic primitive: the AI client composes morph builds from this + update_shape.
async function handleDuplicateSlide(args) {
	const { pptx } = getDeck(args.deckId)
	const srcIndex = args.slideIndex
	const src = pptx.slides[srcIndex]
	if (!src) throw new Error(`duplicate_slide: slideIndex ${srcIndex} out of range (deck has ${pptx.slides.length} slides)`)
	const count = args.count === undefined ? 1 : Number(args.count)
	if (!Number.isInteger(count) || count > 1000) throw new Error('duplicate_slide: count must be an integer from 1 through 1000.')
	if (count < 1) throw new Error('duplicate_slide: count must be an integer from 1 through 1000.')
	if (args.id != null && count !== 1) throw new Error('duplicate_slide: id/newSlideId can be used only when count is 1; provide ids for multiple copies.')
	if (args.title != null && count !== 1) throw new Error('duplicate_slide: title can be used only when count is 1; provide titles for multiple copies.')
	if (args.ids !== undefined && (!Array.isArray(args.ids) || args.ids.length !== count)) throw new Error(`duplicate_slide: ids must contain exactly ${count} semantic slide IDs.`)
	if (args.titles !== undefined && (!Array.isArray(args.titles) || args.titles.length !== count)) throw new Error(`duplicate_slide: titles must contain exactly ${count} slide titles.`)
	if (args.transition != null) validateTransitionFormatOptions(args.transition, 'duplicate_slide transition')
	for (const [index, value] of (args.titles || (args.title != null ? [args.title] : [])).entries()) {
		if (!String(value || '').trim()) throw new Error(`duplicate_slide: title at copy ${index + 1} must be non-empty.`)
	}
	const usedSemanticIds = new Set((pptx.slides || []).map(slide => String(slide?._betterpptxSemanticId || '')).filter(Boolean))
	const requestedIds = args.ids || (args.id != null ? [args.id] : [])
	for (const [index, value] of requestedIds.entries()) {
		const id = String(value || '').trim()
		if (!/^[A-Za-z0-9._:-]+$/.test(id)) throw new Error(`duplicate_slide: semantic ID at copy ${index + 1} must match ^[A-Za-z0-9._:-]+$.`)
		if (usedSemanticIds.has(id)) throw new Error(`duplicate_slide: semantic slide ID ${id} already exists.`)
		usedSemanticIds.add(id)
	}
	const allocateSemanticId = copyIndex => {
		if (requestedIds[copyIndex] != null) return String(requestedIds[copyIndex]).trim()
		const sourceId = String(src._betterpptxSemanticId || `slide-${srcIndex + 1}`)
		const stem = `${sourceId}-copy`
		let suffix = copyIndex + 1
		let candidate = suffix === 1 ? stem : `${stem}-${suffix}`
		while (usedSemanticIds.has(candidate)) candidate = `${stem}-${++suffix}`
		usedSemanticIds.add(candidate)
		return candidate
	}
	const duplicateIds = Array.from({ length: count }, (_, index) => allocateSemanticId(index))
	const newSlideIndexes = []
	let source = src
	for (let n = 0; n < count; n++) {
		const newSlide = pptx.addSlide()
		// Visual + layout fidelity
		if (source.background !== undefined) newSlide.background = _deepCloneData(source.background)
		if (source.color !== undefined) newSlide.color = source.color
		if (typeof source.hidden === 'boolean') newSlide.hidden = source.hidden
		if (source.slideNumber !== undefined) newSlide.slideNumber = _deepCloneData(source.slideNumber)
		if (source._showMasterSp !== undefined) newSlide._showMasterSp = source._showMasterSp
		if (source._showMasterPhAnim !== undefined) newSlide._showMasterPhAnim = source._showMasterPhAnim
		if (source._colorMapOverride !== undefined) newSlide._colorMapOverride = _deepCloneData(source._colorMapOverride)
		// Preserve semantic/export ownership alongside the visual clone. Without
		// these markers, the compiler-authored narration rubric on a static slide
		// is misread as a new TTS request and the duplicate loses its stable slide
		// identity after reorder/delete workflows.
		newSlide._betterpptxSemanticId = duplicateIds[n]
		const requestedTitle = args.titles?.[n] ?? (n === 0 ? args.title : undefined)
		if (requestedTitle != null) newSlide._betterpptxTitle = String(requestedTitle)
		else if (source._betterpptxTitle !== undefined) newSlide._betterpptxTitle = source._betterpptxTitle
		if (source._narrationAuthored !== undefined) newSlide._narrationAuthored = source._narrationAuthored
		if (source._betterpptxLayoutPresetId !== undefined) newSlide._betterpptxLayoutPresetId = source._betterpptxLayoutPresetId
		if (source._betterpptxTemplatePresetId !== undefined) newSlide._betterpptxTemplatePresetId = source._betterpptxTemplatePresetId
		if (source._betterpptxLayoutName !== undefined) newSlide._betterpptxLayoutName = source._betterpptxLayoutName
		if (source._betterpptxMasterName !== undefined) newSlide._betterpptxMasterName = source._betterpptxMasterName
		if (source._betterpptxLayoutBindingReset !== undefined) newSlide._betterpptxLayoutBindingReset = source._betterpptxLayoutBindingReset
		if (source._templateLayoutName !== undefined) newSlide._templateLayoutName = source._templateLayoutName
		if (source._templateLayoutType !== undefined) newSlide._templateLayoutType = source._templateLayoutType
		if (source._rawSlideLayoutNumber) newSlide._rawSlideLayoutNumber = source._rawSlideLayoutNumber
		if (source._betterpptxBaseSlideLayout) newSlide._betterpptxBaseSlideLayout = source._betterpptxBaseSlideLayout
		if (source._slideLayout) newSlide._slideLayout = source._slideLayout
		if (source._rawTransitionXml) newSlide._rawTransitionXml = source._rawTransitionXml
		if (source._rawTimingXml) newSlide._rawTimingXml = source._rawTimingXml
		if (source._rawSlideExtLstXml) newSlide._rawSlideExtLstXml = source._rawSlideExtLstXml
		// Objects + relationships — identity (objectName + spid) carried inside options.
		// NOTE: imported passthrough shapes keep their relationships in `_rawRels`
		// (separate from the standard arrays); it MUST be cloned too or the clone's
		// passthrough r:embed/r:id refs dangle and PowerPoint refuses to open.
		newSlide._rels = _deepCloneData(source._rels) || []
		newSlide._relsMedia = _deepCloneData(source._relsMedia) || []
		newSlide._rawRels = _deepCloneData(source._rawRels) || []
		const clonedObjects = _deepCloneData(source._slideObjects) || []
		const sourceChartRels = source._relsChart || []
		newSlide._slideObjects = []
		newSlide._relsChart = []
		let recreatedCharts = 0
		for (const clonedObj of clonedObjects) {
			if (_appendRecreatedChartClone(newSlide, clonedObj, sourceChartRels)) {
				recreatedCharts++
			} else {
				newSlide._slideObjects.push(clonedObj)
			}
		}
		if (sourceChartRels.length && recreatedCharts < sourceChartRels.length) {
			const clonedChartRels = _deepCloneData(sourceChartRels) || []
			for (const rel of clonedChartRels) {
				if (!newSlide._relsChart.some(existing => Number(existing?.rId) === Number(rel?.rId))) {
					newSlide._relsChart.push(rel)
				}
			}
		}
		// Transition (e.g. morph) goes on the slide being transitioned TO (the clone)
		if (args.transition) newSlide.transition = { ...resolveTransitionPreset(args.transition) }
		else if (source.transition !== undefined) newSlide.transition = _deepCloneData(source.transition)
		newSlideIndexes.push(pptx.slides.length - 1)
		source = newSlide // chain so count>1 stacks successive copies
	}
	const editableKinds = (src._slideObjects || []).filter(o => { const k = o.type || o._type; return k && k !== 'notes' })
	return {
		ok: true,
		sourceSlideIndex: srcIndex,
		newSlideIndexes,
		semanticSlideIds: duplicateIds,
		slideCount: pptx.slides.length,
		clonedShapeCount: editableKinds.length,
	}
}

function _normalizeDeckSlideMetadata(pptx, options = {}) {
	const slides = pptx._slides || pptx.slides || []
	for (let i = 0; i < slides.length; i++) {
		const slide = slides[i]
		slide._slideNum = i + 1
		slide._rId = i + 2
		slide._slideId = i + 256
		if (typeof slide._name === 'string' && /^Slide \d+$/.test(slide._name)) slide._name = `Slide ${i + 1}`
	}
	const semanticSlideNumbers = new Map(slides.map((slide, index) => [String(slide?._betterpptxSemanticId || ''), index + 1]).filter(([id]) => id))
	for (const slide of slides) {
		for (const obj of slide?._slideObjects || []) {
			if (_shapeKind(obj) === 'zoom') {
				const targetSlideId = String(obj.options?._betterpptxZoomTargetSlideId || '')
				const targetSlideNumber = semanticSlideNumbers.get(targetSlideId)
				if (targetSlideNumber) {
					obj.options._zoomSldId = 255 + targetSlideNumber
					const relation = (slide._rels || []).find(rel => Number(rel?.rId) === Number(obj.options?._zoomSlideRid) && String(rel?.data || '').toLowerCase() === 'slide')
					if (relation) relation.Target = String(targetSlideNumber)
				}
			}
			const actions = obj.options?.interactiveActions
			if (!actions || typeof actions !== 'object') continue
			const endpoints = Object.prototype.hasOwnProperty.call(actions, 'type') ? [actions] : [actions.click, actions.hover]
			for (const endpoint of endpoints) {
				if (endpoint?.type !== 'slide' || typeof endpoint.targetSlideId !== 'string') continue
				const targetSlideNumber = semanticSlideNumbers.get(endpoint.targetSlideId)
				if (targetSlideNumber) endpoint.targetSlide = targetSlideNumber
			}
		}
	}
	const slideOrder = new Map(slides.map((slide, i) => [slide, i]))
	if (Array.isArray(pptx._sections)) {
		pptx._sections = pptx._sections
			.map(section => ({
				...section,
				_slides: (section._slides || [])
					.filter(slide => slideOrder.has(slide))
					.sort((a, b) => slideOrder.get(a) - slideOrder.get(b)),
			}))
			.filter(section => options.pruneEmptySections ? (section._slides || []).length > 0 : true)
	}
	const sections = pptx._sections || pptx.sections || []
	for (const [sectionIndex, section] of sections.entries()) semanticSectionId(section, sectionIndex)
	for (const slide of slides) {
		for (const obj of slide?._slideObjects || []) {
			if (_shapeKind(obj) === 'sectionZoom') {
				const targetId = sectionZoomTargetSectionId(pptx, obj)
				const resolved = sectionBySemanticId(pptx, targetId)
				if (!resolved || !(resolved.section?._slides || []).length) continue
				obj.options._betterpptxZoomTargetSectionId = targetId
				obj.options._zoomSectionId = resolved.section._id
				const relation = (slide._rels || []).find(rel => Number(rel?.rId) === Number(obj.options?._zoomSlideRid) && String(rel?.data || '').toLowerCase() === 'slide')
				if (relation) relation.Target = String(resolved.section._slides[0]._slideNum)
			}
			if (_shapeKind(obj) === 'summaryZoom') {
				const targetIds = summaryZoomSectionIds(pptx, obj)
				const summaryObjects = obj.options?._summaryObjs || []
				for (let index = 0; index < targetIds.length && index < summaryObjects.length; index += 1) {
					const resolved = sectionBySemanticId(pptx, targetIds[index])
					if (!resolved || !(resolved.section?._slides || []).length) continue
					const item = summaryObjects[index]
					item.sectionId = resolved.section._id
					const relation = (slide._rels || []).find(rel => Number(rel?.rId) === Number(item.slideRid) && String(rel?.data || '').toLowerCase() === 'slide')
					if (relation) relation.Target = String(resolved.section._slides[0]._slideNum)
				}
			}
		}
	}
	return slides
}

function _sectionSummaries(pptx) {
	const slideIndex = new Map((pptx.slides || []).map((slide, i) => [slide, i]))
	return (pptx.sections || []).map((section, index) => ({
		index,
		id: semanticSectionId(section, index),
		title: section.title,
		type: section._type || 'user',
		slideIndexes: (section._slides || []).map(slide => slideIndex.get(slide)).filter(i => typeof i === 'number'),
	}))
}

function assertSlideDeletionNavigationSafety(pptx, indexes = [], toolName = 'slide.delete', internalHyperlinks = null) {
	const unique = Array.from(new Set((indexes || []).map(Number)))
	if (!unique.length) return
	const deletingIndexes = new Set(unique)
	const deletingSlides = new Set(unique.map(index => pptx?.slides?.[index]).filter(Boolean))
	const deletingSemanticIds = new Set(unique.map(index => String(pptx?.slides?.[index]?._betterpptxSemanticId || '')).filter(Boolean))
	for (const record of internalHyperlinks || _captureInternalHyperlinkTargets(pptx, toolName)) {
		if (!deletingSlides.has(record.sourceSlide) && deletingSlides.has(record.targetSlide)) {
			throw new Error(`${toolName}: slide targeted by hyperlink ${record.objectName} must be retained or the hyperlink must be cleared/retargeted first.`)
		}
	}
	for (const [sourceIndex, sourceSlide] of (pptx?.slides || []).entries()) {
		if (deletingIndexes.has(sourceIndex)) continue
		for (const obj of sourceSlide?._slideObjects || []) {
			const zoomTargetId = _shapeKind(obj) === 'zoom' ? zoomTargetSlideId(pptx, sourceSlide, obj) : null
			if (zoomTargetId && deletingSemanticIds.has(zoomTargetId)) {
				throw new Error(`${toolName}: semantic slide ${zoomTargetId} is still targeted by Slide Zoom ${obj.options?.objectName || 'zoom'} on slide ${sourceIndex}. Delete or retarget that Slide Zoom first.`)
			}
			const actions = obj.options?.interactiveActions
			const endpoints = actions && typeof actions === 'object'
				? (Object.prototype.hasOwnProperty.call(actions, 'type') ? [actions] : [actions.click, actions.hover])
				: []
			for (const endpoint of endpoints) {
				if (endpoint?.type === 'slide' && deletingSemanticIds.has(String(endpoint.targetSlideId || ''))) {
					throw new Error(`${toolName}: semantic slide ${endpoint.targetSlideId} is still targeted by ${obj.options?.objectName || _shapeKind(obj) || 'object'} on slide ${sourceIndex}. Clear or retarget that action first.`)
				}
			}
		}
	}
}

async function handleDeleteSlide(args) {
	const { pptx } = getDeck(args.deckId)
	const indexes = Array.isArray(args.slideIndexes)
		? args.slideIndexes
		: (typeof args.slideIndex === 'number' ? [args.slideIndex] : [])
	const unique = Array.from(new Set(indexes.map(n => Number(n)))).sort((a, b) => b - a)
	if (!unique.length) throw new Error('slide.delete: pass slideIndex or slideIndexes.')
	for (const idx of unique) {
		if (!Number.isInteger(idx) || idx < 0 || idx >= pptx.slides.length) throw new Error(`slide.delete: bad slide index ${idx} (deck has ${pptx.slides.length} slides).`)
	}
	if (unique.length >= pptx.slides.length) throw new Error('slide.delete: deleting every slide would create an invalid presentation.')
	const internalHyperlinks = _captureInternalHyperlinkTargets(pptx, 'slide.delete')
	assertSlideDeletionNavigationSafety(pptx, unique, 'slide.delete', internalHyperlinks)
	const removed = []
	const slides = pptx._slides || pptx.slides
	for (const idx of unique) {
		const [slide] = slides.splice(idx, 1)
		removed.push({ slideIndex: idx, name: slide?._name, slideId: slide?._slideId })
	}
	_normalizeDeckSlideMetadata(pptx, { pruneEmptySections: true })
	_retargetInternalHyperlinks(pptx, internalHyperlinks)
	return {
		ok: true,
		deletedCount: removed.length,
		deleted: removed.sort((a, b) => a.slideIndex - b.slideIndex),
		slideCount: pptx.slides.length,
		sections: _sectionSummaries(pptx),
	}
}

async function handleReorderSlide(args) {
	const { pptx } = getDeck(args.deckId)
	const slides = pptx._slides || pptx.slides
	if (!slides.length) throw new Error('slide.reorder: deck has no slides.')
	let ordered
	if (Array.isArray(args.order)) {
		if (args.order.length !== slides.length) throw new Error(`slide.reorder: order must contain exactly ${slides.length} slide indexes.`)
		const seen = new Set(args.order)
		if (seen.size !== slides.length || args.order.some(i => !Number.isInteger(Number(i)) || i < 0 || i >= slides.length)) {
			throw new Error('slide.reorder: order must be a permutation of existing zero-based slide indexes.')
		}
		ordered = args.order.map(i => slides[Number(i)])
	} else {
		const fromIndex = Number(args.fromIndex ?? args.slideIndex)
		const toIndex = Number(args.toIndex)
		if (!Number.isInteger(fromIndex) || fromIndex < 0 || fromIndex >= slides.length) throw new Error(`slide.reorder: bad fromIndex ${fromIndex}.`)
		if (!Number.isInteger(toIndex) || toIndex < 0 || toIndex >= slides.length) throw new Error(`slide.reorder: bad toIndex ${toIndex}.`)
		ordered = slides.slice()
		const [moved] = ordered.splice(fromIndex, 1)
		ordered.splice(toIndex, 0, moved)
	}
	const internalHyperlinks = _captureInternalHyperlinkTargets(pptx, 'slide.reorder')
	slides.splice(0, slides.length, ...ordered)
	_normalizeDeckSlideMetadata(pptx)
	_retargetInternalHyperlinks(pptx, internalHyperlinks)
	return {
		ok: true,
		slideCount: pptx.slides.length,
		order: pptx.slides.map((slide, index) => ({ index, name: slide._name, slideId: slide._slideId })),
		sections: _sectionSummaries(pptx),
	}
}

function _layoutSummary(layout, index) {
	return {
		index,
		name: layout?._name,
		margin: layout?._margin,
		slideNum: layout?._slideNum,
		objectCount: Array.isArray(layout?._slideObjects) ? layout._slideObjects.length : 0,
		hasBackground: !!(layout?.background || layout?.bkgd),
		hasSlideNumber: !!layout?._slideNumberProps,
		relCounts: {
			media: Array.isArray(layout?._relsMedia) ? layout._relsMedia.length : 0,
			charts: Array.isArray(layout?._relsChart) ? layout._relsChart.length : 0,
			links: Array.isArray(layout?._rels) ? layout._rels.length : 0,
		},
	}
}

async function handleInspectLayouts(args) {
	const entry = getDeck(args.deckId)
	const { pptx } = entry
	const layouts = Object.entries(pptx.LAYOUTS || {}).map(([name, layout]) => ({
		name,
		width: layout.width,
		height: layout.height,
		sizeW: layout._sizeW,
		sizeH: layout._sizeH,
	}))
	return {
		deckId: args.deckId,
		activeLayout: pptx.layout,
		presLayout: pptx.presLayout,
		registeredLayouts: layouts,
		layoutAudit: entry.layoutAudit || null,
		nativeTemplateLayouts: entry.templateLayoutCarriers || [],
		nativeTemplateMasters: entry.templateMasterCarriers || [],
		templateRelationshipBindings: entry.templateRelationshipBindings || [],
		layoutPolicy: entry.layoutPolicy ? {
			strict: entry.layoutPolicy.strict,
			allowedLayouts: entry.layoutPolicy.allowedLayouts,
			defaultLayout: entry.layoutPolicy.defaultLayout,
		} : null,
		slideLayouts: (pptx.slideLayouts || []).map(_layoutSummary),
		master: _layoutSummary(pptx.masterSlide, 0),
		sections: _sectionSummaries(pptx),
		slides: (pptx.slides || []).map((slide, index) => ({
			index,
			name: slide._name,
			layoutName: slide._slideLayout?._name,
			rawLayoutNumber: slide._rawSlideLayoutNumber || null,
			templateLayoutName: slide._templateLayoutName || null,
			objectCount: Array.isArray(slide._slideObjects) ? slide._slideObjects.length : 0,
			hasBackground: !!(slide.background || slide.bkgd),
		})),
	}
}

function _getSection(pptx, index, toolName = 'deck.sections') {
	const section = (pptx.sections || [])[Number(index)]
	if (!section) throw new Error(`${toolName}: section index ${index} out of range (deck has ${(pptx.sections || []).length} sections).`)
	return section
}

function _removeSlideFromSections(pptx, slide) {
	for (const section of pptx.sections || []) {
		section._slides = (section._slides || []).filter(item => item !== slide)
	}
}

async function handleSections(args) {
	const { pptx } = getDeck(args.deckId)
	const action = args.action || 'list'
	if (action === 'list') return { ok: true, sections: _sectionSummaries(pptx) }
	if (!Array.isArray(pptx._sections)) pptx._sections = []
	if (action === 'add') {
		const title = String(args.title || '').trim()
		if (!title) throw new Error('deck.sections add: title is required.')
		const id = String(args.id || `section-${pptx._sections.length + 1}`).trim()
		if (!id) throw new Error('deck.sections add: id is required.')
		if (pptx._sections.some((section, index) => semanticSectionId(section, index) === id)) throw new Error(`deck.sections add: semantic section id ${id} already exists.`)
		const section = { _type: 'user', _slides: [], title, _betterpptxSemanticId: id }
		const index = Number.isInteger(Number(args.index)) ? Math.max(0, Math.min(Number(args.index), pptx._sections.length)) : pptx._sections.length
		pptx._sections.splice(index, 0, section)
	} else if (action === 'rename') {
		const section = _getSection(pptx, args.index)
		const title = String(args.title ?? args.newTitle ?? '').trim()
		if (!title) throw new Error('deck.sections rename: title/newTitle is required.')
		section.title = title
	} else if (action === 'delete') {
		const index = Number(args.index)
		const section = _getSection(pptx, index)
		const deletingId = semanticSectionId(section, index)
		for (const [slideIndex, slide] of (pptx.slides || []).entries()) {
			for (const obj of slide?._slideObjects || []) {
				if (_shapeKind(obj) === 'sectionZoom' && sectionZoomTargetSectionId(pptx, obj) === deletingId) throw new Error(`deck.sections delete: section ${deletingId} is still targeted by Section Zoom ${obj.options?.objectName || 'zoom'} on slide ${slideIndex}. Delete or retarget it first.`)
				if (_shapeKind(obj) === 'summaryZoom' && summaryZoomSectionIds(pptx, obj).includes(deletingId)) throw new Error(`deck.sections delete: section ${deletingId} is still targeted by Summary Zoom ${obj.options?.objectName || 'summary zoom'}. Delete or retarget it first.`)
			}
		}
		const slides = section._slides || []
		pptx._sections.splice(index, 1)
		const fallback = pptx._sections[Math.min(index, pptx._sections.length - 1)]
		if (fallback) {
			for (const slide of slides) if (!fallback._slides.includes(slide)) fallback._slides.push(slide)
		}
	} else if (action === 'move') {
		const from = Number(args.index)
		const to = Number(args.toIndex)
		const section = _getSection(pptx, from)
		if (!Number.isInteger(to) || to < 0 || to >= pptx._sections.length) throw new Error(`deck.sections move: bad toIndex ${args.toIndex}.`)
		pptx._sections.splice(from, 1)
		pptx._sections.splice(to, 0, section)
	} else if (action === 'assign_slide') {
		const section = _getSection(pptx, args.index)
		const indexes = Array.isArray(args.slideIndexes) ? args.slideIndexes : [args.slideIndex]
		for (const raw of indexes) {
			const slide = pptx.slides[Number(raw)]
			if (!slide) throw new Error(`deck.sections assign_slide: bad slide index ${raw}.`)
			_removeSlideFromSections(pptx, slide)
			section._slides.push(slide)
		}
	} else {
		throw new Error(`deck.sections: unsupported action "${action}".`)
	}
	_normalizeDeckSlideMetadata(pptx)
	return { ok: true, action, sections: _sectionSummaries(pptx) }
}

function _normalizeTableCell(cell, fallbackOptions = {}) {
	if (typeof cell === 'string' || typeof cell === 'number') {
		return { _type: 'tablecell', text: String(cell), options: _deepCloneData(fallbackOptions) || {} }
	}
	if (!cell || typeof cell !== 'object') {
		return { _type: 'tablecell', text: '', options: _deepCloneData(fallbackOptions) || {} }
	}
	return {
		_type: 'tablecell',
		text: cell.text === undefined || cell.text === null ? '' : cell.text,
		options: _deepMerge(_deepCloneData(fallbackOptions) || {}, cell.options || {}),
	}
}

function _tableRowsToInternal(rows) {
	return rows.map(row => row.map(cell => _normalizeTableCell(cell, {})))
}

function _tableCellPlainText(cell) {
	const value = cell && typeof cell === 'object' && !Array.isArray(cell) ? cell.text : cell
	return Array.isArray(value)
		? value.map(run => String(run?.text ?? '')).join('')
		: String(value ?? '')
}

function _recipeCellStyle(recipe, rows, rowIndex, columnIndex) {
	if (!recipe || typeof recipe !== 'object') return {}
	const lastRow = rows.length - 1
	const lastColumn = Math.max(0, ...(rows || []).map(row => Array.isArray(row) ? row.length - 1 : 0))
	const text = _tableCellPlainText(rows[rowIndex]?.[columnIndex]).trim()
	const styles = []
	if (rowIndex === 0 && recipe.header) styles.push(recipe.header)
	if (columnIndex === 0 && recipe.firstColumn) styles.push(recipe.firstColumn)
	if (columnIndex === lastColumn && recipe.lastColumn) styles.push(recipe.lastColumn)
	if (rowIndex === lastRow && recipe.totalRow) styles.push(recipe.totalRow)
	if (Array.isArray(recipe.bandedRows) && recipe.bandedRows.length) styles.push(recipe.bandedRows[rowIndex % recipe.bandedRows.length])
	if (Array.isArray(recipe.bandedColumns) && recipe.bandedColumns.length) styles.push(recipe.bandedColumns[columnIndex % recipe.bandedColumns.length])
	if (columnIndex === lastColumn && recipe.recommendedColumn) styles.push(recipe.recommendedColumn)
	if (columnIndex > 0 && /^[-+]?[$€£¥]?[\d,.]+(?:%|\s*(?:pts?|m|k|bn))?$/i.test(text) && recipe.numeric) styles.push(recipe.numeric)
	if (/^(?:on track|ahead|good|green|low|complete|completed|yes|pass)$/i.test(text) && recipe.statusGood) styles.push(recipe.statusGood)
	if (/^(?:watch|at risk|amber|medium|warning|pending)$/i.test(text) && recipe.statusWatch) styles.push(recipe.statusWatch)
	if (/^\+/.test(text) && recipe.positiveVariance) styles.push(recipe.positiveVariance)
	if (/^-/.test(text) && recipe.negativeVariance) styles.push(recipe.negativeVariance)
	return Object.assign({}, ...styles.filter(style => style && typeof style === 'object' && !Array.isArray(style)))
}

function _applySemanticTablePresetRows(rows, preset) {
	if (!preset?.cellStyleRecipe) return _deepCloneData(rows)
	return rows.map((row, rowIndex) => row.map((cell, columnIndex) => {
		const normalized = cell && typeof cell === 'object' && !Array.isArray(cell)
			? { text: _deepCloneData(cell.text), options: _deepCloneData(cell.options || {}) }
			: { text: cell === undefined || cell === null ? '' : cell, options: {} }
		normalized.options = { ..._recipeCellStyle(preset.cellStyleRecipe, rows, rowIndex, columnIndex), ...normalized.options }
		return normalized
	}))
}

function _publicTableOptionEntries(options = {}) {
	const fields = new Set(Object.keys(TABLE_OPTIONS_PUBLIC_SCHEMA.properties))
	return Object.fromEntries(Object.entries(options || {}).filter(([key]) => fields.has(key)))
}

async function _resolveAuthoredTablePlan(requestedOptions, rows) {
	const normalizedOptions = validateTableOptions(requestedOptions || {}, 'table options', { direct: true }) || {}
	const selectors = Object.fromEntries(TABLE_SELECTOR_FIELDS
		.filter(key => normalizedOptions[key] !== undefined && normalizedOptions[key] !== null)
		.map(key => [key, normalizedOptions[key]]))
	const explicitOptions = Object.fromEntries(Object.entries(_publicTableOptionEntries(normalizedOptions))
		.filter(([key, value]) => !TABLE_SELECTOR_FIELDS.includes(key) && value !== undefined && value !== null))
	const infrastructureOptions = Object.fromEntries(Object.entries(normalizedOptions)
		.filter(([key, value]) => !Object.prototype.hasOwnProperty.call(TABLE_OPTIONS_PUBLIC_SCHEMA.properties, key) && !TABLE_SELECTOR_FIELDS.includes(key) && value !== undefined && value !== null))
	let preset = null
	let resolved = {}
	if (selectors.tablePresetId) {
		const { tablePresetById } = await loadTablePresetModule()
		preset = tablePresetById(String(selectors.tablePresetId))
		if (!preset) {
			const error = new Error(`Unknown semantic table preset: ${selectors.tablePresetId}`)
			error.code = 'TABLE_PRESET_NOT_FOUND'
			throw error
		}
		resolved = { ...(preset.optionDefaults || {}), ...(preset.tableStyleOptions || {}) }
	} else if (selectors.tableStylePresetId) {
		const { resolveTableStylePreset } = await loadTablePresetModule()
		const style = resolveTableStylePreset(selectors.tableStylePresetId)
		if (!style) {
			const error = new Error(`Unknown table style preset: ${selectors.tableStylePresetId}`)
			error.code = 'TABLE_STYLE_PRESET_NOT_FOUND'
			error.details = { field: 'tableStylePresetId', correction: 'Search the unranked table catalog with includeNativeStyles=true and choose an opaque id with AI design judgment.' }
			throw error
		}
		resolved.tableStyleId = style.nativeId
	} else if (selectors.tableStyleId) resolved.tableStyleId = selectors.tableStyleId
	Object.assign(resolved, explicitOptions)
	delete resolved.tablePresetId
	delete resolved.tableStylePresetId
	resolved = { ...infrastructureOptions, ...resolved }
	const authoredRows = validateTableRows(rows, 'table rows')
	const materializedRows = preset ? _applySemanticTablePresetRows(authoredRows, preset) : _deepCloneData(authoredRows)
	resolved._tableAuthoringState = authoredTableState(selectors, explicitOptions, authoredRows)
	return { options: resolved, rows: materializedRows, state: resolved._tableAuthoringState, preset }
}

function _initialTableAuthoredState(table) {
	const state = table.options?._tableAuthoringState
	if (state && typeof state === 'object') return _deepCloneData(state)
	const publicOptions = _publicTableOptionEntries(table.options || {})
	const selectors = {}
	if (publicOptions.tableStyleId) selectors.tableStyleId = publicOptions.tableStyleId
	const explicitOptions = Object.fromEntries(Object.entries(publicOptions).filter(([key, value]) => !TABLE_SELECTOR_FIELDS.includes(key) && value !== undefined && value !== null))
	return authoredTableState(selectors, explicitOptions, exportedTableRows({ ...table, options: { ...(table.options || {}), _tableAuthoringState: undefined } }) || [])
}

function _applyAuthoredTableOptionsPatch(state, patch) {
	if (patch === null) return { selectors: {}, explicitOptions: {} }
	const next = {
		selectors: { ...(state.selectors || {}) },
		explicitOptions: { ...(state.explicitOptions || {}) },
	}
	if (!patch || typeof patch !== 'object') return next
	for (const field of TABLE_SELECTOR_FIELDS) {
		if (patch[field] === undefined) continue
		if (patch[field] === null) delete next.selectors[field]
		else {
			next.selectors = { [field]: _deepCloneData(patch[field]) }
		}
	}
	for (const [key, value] of Object.entries(patch)) {
		if (TABLE_SELECTOR_FIELDS.includes(key) || !Object.prototype.hasOwnProperty.call(TABLE_OPTIONS_PUBLIC_SCHEMA.properties, key)) continue
		if (value === null) delete next.explicitOptions[key]
		else if (value !== undefined) next.explicitOptions[key] = _deepCloneData(value)
	}
	return next
}

function _applyDirectTableInfrastructurePatch(options, patch) {
	if (!patch || typeof patch !== 'object') return options
	const publicOwned = new Set(Object.keys(TABLE_OPTIONS_PUBLIC_SCHEMA.properties))
	for (const [key, value] of Object.entries(patch)) {
		if (publicOwned.has(key) || TABLE_SELECTOR_FIELDS.includes(key)) continue
		if (value === null) delete options[key]
		else if (TABLE_GEOMETRY_KEYS.has(key)) options[key] = _tableGeometryToEmu(value)
		else if (value !== undefined) options[key] = _deepCloneData(value)
	}
	return options
}

// addTable stores x/y/w/h in EMU and the table grid divides options.w directly,
// while public patches author geometry in inches. Store patched geometry in the
// same unit, or an 11.5in table splits into gridCol w="4" (4 EMU) columns.
const TABLE_GEOMETRY_KEYS = new Set(['x', 'y', 'w', 'h'])
const TABLE_MIN_COLUMN_EMU = 45720 // 0.05in

function _tableGeometryToEmu(value) {
	if (typeof value !== 'number' || !Number.isFinite(value)) return _deepCloneData(value)
	// Values above 100 are already EMU (the library's inch2Emu convention).
	return Math.abs(value) > 100 ? Math.round(value) : Math.round(value * 914400)
}

function _tableGridColumnWidthsEmu(table) {
	const options = table?.options || {}
	const rawGrid = options._rawGridColXmls
	if (Array.isArray(rawGrid) && rawGrid.length) {
		return rawGrid.map(xml => Number(String(xml).match(/\bw="(-?\d+)"/)?.[1] ?? NaN))
	}
	const firstRow = table?.arrTabRows?.[0] || []
	const columnCount = firstRow.reduce((sum, cell) => sum + (Number.isInteger(cell?.options?.colspan) ? cell.options.colspan : 1), 0)
	if (!columnCount) return []
	const toEmu = value => typeof value === 'number' && value > 100 ? value : Math.round(914400 * Number(value))
	if (Array.isArray(options.colW)) {
		return Array.from({ length: columnCount }, (_, index) => {
			const width = toEmu(options.colW[index])
			return Number.isFinite(width) ? width : (typeof options.w === 'number' ? options.w : 1) / columnCount
		}).map(Math.round)
	}
	if (options.colW) return Array(columnCount).fill(Number(options.colW))
	if (options.w) return Array(columnCount).fill(Math.round((typeof options.w === 'number' ? options.w : 1) / columnCount))
	return Array(columnCount).fill(914400)
}

function tableGeometryValidationIssues(entry) {
	const issues = []
	;(entry?.pptx?.slides || []).forEach((slide, slideOffset) => {
		;(slide?._slideObjects || []).forEach((object, shapeIndex) => {
			if (object?._type !== 'table') return
			const widths = _tableGridColumnWidthsEmu(object)
			const collapsed = widths.map((width, column) => ({ column, width })).filter(item => !(item.width >= TABLE_MIN_COLUMN_EMU))
			if (!collapsed.length) return
			const objectName = object.options?.objectName || null
			issues.push({
				severity: 'error',
				code: 'TABLE_COLUMN_WIDTH_COLLAPSED',
				message: `Table ${objectName ? `"${objectName}" ` : ''}on slide ${slideOffset + 1} has ${collapsed.length} column(s) narrower than 0.05in (gridCol w=${collapsed.map(item => item.width).join(', ')} EMU); the table renders as a sliver.`,
				slideNumber: slideOffset + 1,
				shapeName: objectName || undefined,
				shapeIndex,
				suggestion: 'Re-send the table with rect/bbox in inches (for example {"w": 11.5}) or explicit tableOptions.colW in inches, one entry per column.',
				fix: 'Re-send the table through deck.generate_from_spec commitMode:"patch" with rect/bbox in inches or tableOptions.colW in inches, one entry per column.',
				autoFixAvailable: false,
				context: { columnWidthsEmu: widths, minimumColumnEmu: TABLE_MIN_COLUMN_EMU },
			})
		})
	})
	return issues
}

function _tableFallbackOptions(table) {
	const first = table.arrTabRows?.[0]?.[0]?.options
	return first && typeof first === 'object' ? first : {}
}

function _tableColumnCount(table) {
	return Math.max(0, ...(table.arrTabRows || []).map(row => row.length))
}

function _applyTableOperation(table, op) {
	if (!op || typeof op !== 'object') return false
	const rows = table.arrTabRows
	const fallback = _tableFallbackOptions(table)
	const kind = op.op || op.type
	if (kind === 'replaceRows') {
		if (!Array.isArray(op.rows)) throw new Error('update_table replaceRows: rows must be an array.')
		table.arrTabRows = op.rows.map(row => {
			if (!Array.isArray(row)) throw new Error('update_table replaceRows: every row must be an array.')
			return row.map(cell => _normalizeTableCell(cell, fallback))
		})
		delete table.options?._rawGridColXmls
		return true
	}
	if (kind === 'patchOptions') {
		table.options = _deepMerge(table.options || {}, op.patch || op.options || {})
		return true
	}
	if (kind === 'setCell' || kind === 'patchCell') {
		const r = Number(op.row)
		const c = Number(op.col)
		if (!rows[r] || !rows[r][c]) throw new Error(`update_table ${kind}: cell ${r},${c} not found.`)
		const cell = rows[r][c]
		if (op.text !== undefined) cell.text = op.text
		if (op.options) cell.options = _deepMerge(cell.options || {}, op.options)
		if (op.patch) _deepMerge(cell, op.patch)
		_clearRawEditBlockers({ _type: 'text', text: Array.isArray(cell.text) ? cell.text : [], options: cell.options || {} }, { text: op.text, ...(op.options || op.patch || {}) })
		return true
	}
	if (kind === 'addRow') {
		const width = _tableColumnCount(table) || (Array.isArray(op.cells) ? op.cells.length : 1)
		const cells = Array.isArray(op.cells) ? op.cells : Array.from({ length: width }, () => '')
		const row = Array.from({ length: width }, (_, i) => _normalizeTableCell(cells[i] ?? '', fallback))
		const index = Number.isInteger(Number(op.index)) ? Math.max(0, Math.min(Number(op.index), rows.length)) : rows.length
		rows.splice(index, 0, row)
		return true
	}
	if (kind === 'deleteRow') {
		const index = Number(op.index)
		if (!rows[index]) throw new Error(`update_table deleteRow: row ${op.index} not found.`)
		if (rows.length <= 1) throw new Error('update_table deleteRow: cannot delete the only row.')
		rows.splice(index, 1)
		return true
	}
	if (kind === 'addColumn') {
		const index = Number.isInteger(Number(op.index)) ? Math.max(0, Math.min(Number(op.index), _tableColumnCount(table))) : _tableColumnCount(table)
		const cells = Array.isArray(op.cells) ? op.cells : []
		for (let r = 0; r < rows.length; r++) rows[r].splice(index, 0, _normalizeTableCell(cells[r] ?? '', fallback))
		delete table.options?._rawGridColXmls
		return true
	}
	if (kind === 'deleteColumn') {
		const index = Number(op.index)
		if (!Number.isInteger(index) || index < 0 || index >= _tableColumnCount(table)) throw new Error(`update_table deleteColumn: bad column ${op.index}.`)
		if (_tableColumnCount(table) <= 1) throw new Error('update_table deleteColumn: cannot delete the only column.')
		for (const row of rows) row.splice(index, 1)
		delete table.options?._rawGridColXmls
		return true
	}
	throw new Error(`update_table: unsupported operation "${kind}".`)
}

async function handleUpdateTable(args) {
	validateDirectTableUpdate(args)
	const slide = getSlide(args.deckId, args.slideIndex)
	const { obj, index, rawIndex } = _resolveShapeForTool(slide, args.target, 'update_table')
	const kind = _shapeKind(obj)
	const previousTextHyperlinkRids = kind === 'table' ? _textHyperlinkRelationshipIds(obj) : new Set()
	const parsed = kind === 'passthrough' ? exportedPassthroughTableFields(obj) : null
	if (kind !== 'table' && kind !== 'passthrough') throw new Error(`update_table: target "${obj.options?.objectName || index}" is ${kind || 'unknown'}, expected table.`)
	if (kind === 'table' && !Array.isArray(obj.arrTabRows)) throw new Error('update_table: target is not a structurally editable table; raw/passthrough tables must be recreated through the closed table contract.')
	const baseRows = args.rows ?? (kind === 'table' ? exportedTableRows(obj) : parsed?.fields?.rows)
	if (!Array.isArray(baseRows) || !baseRows.length) throw new Error('update_table: the target has no closed editable row model; provide replacement rows to convert it.')

	let authoredState = kind === 'table'
		? _initialTableAuthoredState(obj)
		: authoredTableState({}, {}, baseRows)
	const infrastructureOptions = kind === 'table'
		? _deepCloneData(obj.options || {})
		: {
			x: obj.options?.x ?? 1,
			y: obj.options?.y ?? 1,
			w: obj.options?.w ?? '50%',
			h: obj.options?.h ?? '50%',
			objectName: obj.options?.objectName,
			spid: obj.options?.spid,
		}
	const candidate = { arrTabRows: _tableRowsToInternal(kind === 'table' ? (authoredState.rows || baseRows) : baseRows), options: infrastructureOptions }
	const operations = []
	if (Array.isArray(args.operations)) operations.push(...args.operations)
	if (Array.isArray(args.rows)) operations.push({ op: 'replaceRows', rows: args.rows })
	if (args.optionsPatch !== undefined) operations.push({ op: 'patchOptions', patch: args.optionsPatch })
	for (const key of ['setCell', 'patchCell', 'addRow', 'deleteRow', 'addColumn', 'deleteColumn']) if (args[key]) operations.push({ op: key, ...args[key] })
	const rootSelectorPatch = Object.fromEntries(TABLE_SELECTOR_FIELDS.filter(key => args[key] !== undefined).map(key => [key, args[key]]))
	if (Object.keys(rootSelectorPatch).length) operations.push({ op: 'patchOptions', patch: rootSelectorPatch })
	if (!operations.length) throw new Error('update_table: provide rows, optionsPatch, a governed selector, operations, or a cell/row/column operation.')

	let applied = 0
	for (const operation of operations) {
		const operationKind = operation.op || operation.type
		if (operationKind === 'patchOptions') {
			const patch = operation.patch ?? operation.options ?? null
			authoredState = { ...authoredState, ..._applyAuthoredTableOptionsPatch(authoredState, patch) }
			_applyDirectTableInfrastructurePatch(infrastructureOptions, patch)
			applied++
			continue
		}
		if (_applyTableOperation(candidate, operation)) applied++
	}
	delete candidate.options?._tableAuthoringState
	const publicRows = candidate.arrTabRows.map(row => row.map(exportedTableCell))
	validateTableRows(publicRows, 'update_table final rows')
	const requestedOwnedOptions = { ...(authoredState.selectors || {}), ...(authoredState.explicitOptions || {}) }
	const plan = await _resolveAuthoredTablePlan(requestedOwnedOptions, publicRows)
	const ownedFields = new Set([...Object.keys(TABLE_OPTIONS_PUBLIC_SCHEMA.properties), ...TABLE_SELECTOR_FIELDS, '_tableAuthoringState'])
	for (const field of ownedFields) delete infrastructureOptions[field]
	for (const key of Object.keys(infrastructureOptions)) if (key.startsWith('_raw')) delete infrastructureOptions[key]
	const finalOptions = { ...infrastructureOptions, ...plan.options }

	let target = obj
	let rawRelsRemoved = 0
	if (kind === 'passthrough') {
		const relIds = new Set(collectRelationshipIds(obj?.passthrough?.xml || ''))
		rawRelsRemoved = _removePassthroughRelsForObject(slide, obj, relIds)
		const replaced = _replaceSlideObjectInPlace(slide, rawIndex, () => { slide.addTable(plan.rows, finalOptions) })
		target = replaced.replacement
	} else {
		target.arrTabRows = _tableRowsToInternal(plan.rows)
		target.options = finalOptions
	}
	_attachTextHyperlinkRelationships(slide, target)
	_removeUnreferencedTextHyperlinkRelationships(slide, previousTextHyperlinkRids)
	return {
		ok: true,
		slideIndex: args.slideIndex,
		index,
		rawIndex,
		objectName: target.options?.objectName,
		operationsApplied: applied,
		rows: target.arrTabRows.length,
		columns: _tableColumnCount(target),
		...(kind === 'passthrough' ? { convertedFromPassthrough: 'table', rawRelsRemoved } : {}),
		...(plan.state.selectors?.tablePresetId ? { tablePresetId: plan.state.selectors.tablePresetId } : {}),
		...(plan.state.selectors?.tableStylePresetId ? { tableStylePresetId: plan.state.selectors.tableStylePresetId } : {}),
		...(plan.options.tableStyleId ? { tableStyleId: plan.options.tableStyleId } : {}),
	}
}

function _findChartRel(slide, chartObj) {
	const rels = slide._relsChart || []
	return rels.find(rel => rel.rId === chartObj.chartRid)
		|| rels.find(rel => rel.opts === chartObj.options)
		|| rels.find(rel => rel.opts?.objectName && rel.opts.objectName === chartObj.options?.objectName)
		|| null
}

function _normalizeChartDataForUpdate(data) {
	if (!Array.isArray(data)) return data
	return data.map((series, index) => {
		if (!series || typeof series !== 'object') return series
		const next = _deepCloneData(series)
		next._dataIndex = index
		if (Array.isArray(next.labels) && next.labels.length > 0 && !Array.isArray(next.labels[0])) {
			next.labels = [next.labels]
		}
		return next
	})
}

const CHARTEX_NATIVE_TYPES = new Set([
	'treemap',
	'sunburst',
	'histogram',
	'pareto',
	'boxWhisker',
	'boxwhisker',
	'waterfall',
	'funnel',
	'regionMap',
	'regionmap',
])

function _normalizeChartExType(type) {
	const text = typeof type === 'string' ? type : ''
	if (!text) return text
	const key = text.replace(/[\s_-]+/g, '').toLowerCase()
	if (key === 'boxwhisker') return 'boxWhisker'
	if (key === 'regionmap' || key === 'filledmap') return 'regionMap'
	return text
}

function _isChartExChartType(type) {
	if (Array.isArray(type)) return false
	const normalized = _normalizeChartExType(type)
	return CHARTEX_NATIVE_TYPES.has(normalized) || CHARTEX_NATIVE_TYPES.has(String(normalized || '').toLowerCase())
}

function _setChartRelFamilyForType(rel, type) {
	if (!rel) return
	const isChartEx = _isChartExChartType(type)
	const family = isChartEx ? 'chartEx' : 'legacy'
	rel.chartFamily = family
	if (!rel.opts || typeof rel.opts !== 'object') rel.opts = {}
	if (isChartEx) rel.opts._chartEx = true
	else delete rel.opts._chartEx
	const currentName = String(rel.fileName || '')
	const idMatch = currentName.match(/(\d+)\.xml$/) || String(rel.Target || '').match(/(\d+)\.xml$/)
	const id = idMatch ? idMatch[1] : String(rel.globalId || rel.rId || 1)
	const prefix = isChartEx ? 'chartEx' : 'chart'
	if (!currentName.startsWith(prefix)) {
		rel.fileName = `${prefix}${id}.xml`
		rel.Target = `../charts/${prefix}${id}.xml`
	}
}

function _isChartExPassthrough(obj) {
	if (!obj?.passthrough?.xml) return false
	const opts = obj.options || {}
	if (opts._passthroughOriginalType === 'chartEx' || opts._passthroughSourceFormat === 'chartEx') return true
	const xml = String(obj.passthrough.xml || '')
	return xml.includes('drawing/2014/chartex') || xml.includes('relationships/chartEx') || xml.includes('<cx:chart')
}

function _childrenByLocalName(node, localName) {
	const out = []
	if (!node?.childNodes) return out
	for (let i = 0; i < node.childNodes.length; i++) {
		const child = node.childNodes[i]
		if (child?.nodeType === 1 && child.localName === localName) out.push(child)
	}
	return out
}

function _descendantsByLocalName(node, localName) {
	const out = []
	const walk = current => {
		if (!current?.childNodes) return
		for (let i = 0; i < current.childNodes.length; i++) {
			const child = current.childNodes[i]
			if (child?.nodeType === 1) {
				if (child.localName === localName) out.push(child)
				walk(child)
			}
		}
	}
	walk(node)
	return out
}

function _xmlNodeText(node) {
	let text = ''
	if (!node?.childNodes) return text
	for (let i = 0; i < node.childNodes.length; i++) {
		const child = node.childNodes[i]
		if (child.nodeType === 3 || child.nodeType === 4) text += child.nodeValue || ''
	}
	return text
}

function _chartExLevelValues(dim) {
	const levels = _childrenByLocalName(dim, 'lvl')
	return levels.map(level => {
		const values = []
		for (const pt of _childrenByLocalName(level, 'pt')) {
			const idx = Number(pt.getAttribute('idx') || values.length)
			values[idx] = _xmlNodeText(pt)
		}
		return values.map(v => v ?? '')
	})
}

function _inferChartExType(layoutIds, chartXml) {
	const ids = new Set((layoutIds || []).map(id => String(id || '').toLowerCase()))
	if (ids.has('paretoline')) return 'pareto'
	if (ids.has('treemap')) return 'treemap'
	if (ids.has('sunburst')) return 'sunburst'
	if (ids.has('boxwhisker')) return 'boxWhisker'
	if (ids.has('waterfall')) return 'waterfall'
	if (ids.has('funnel')) return 'funnel'
	if (ids.has('regionmap')) return 'regionMap'
	if (String(chartXml || '').includes('<cx:binning')) return 'histogram'
	if (ids.has('clusteredcolumn')) return 'histogram'
	return 'histogram'
}

function _parseChartExStructuredData(chartXml) {
	const doc = new DOMParser().parseFromString(String(chartXml || ''), 'application/xml')
	const seriesEls = _descendantsByLocalName(doc, 'series')
	const dataEls = _descendantsByLocalName(doc, 'data')
	const dataById = new Map()
	const dimensionTypes = new Set()
	for (const dataEl of dataEls) {
		const id = dataEl.getAttribute('id')
		if (id === null || id === undefined) continue
		const strDims = _childrenByLocalName(dataEl, 'strDim')
		const numDims = _childrenByLocalName(dataEl, 'numDim')
		for (const dim of [...strDims, ...numDims]) {
			const dimType = dim.getAttribute('type')
			if (dimType) dimensionTypes.add(dimType)
		}
		const categoryDim = strDims.find(dim => dim.getAttribute('type') === 'cat') || strDims[0]
		const labels = categoryDim ? _chartExLevelValues(categoryDim) : []
		const valueDim = numDims.find(dim => ['val', 'size', 'colorVal'].includes(dim.getAttribute('type') || '')) || numDims[0]
		const numericLevels = valueDim ? _chartExLevelValues(valueDim) : []
		const values = (numericLevels[0] || []).map(value => {
			const n = Number(value)
			return Number.isFinite(n) ? n : 0
		})
		dataById.set(id, { labels, values })
	}
	const layoutIds = []
	const chartData = []
	for (const seriesEl of seriesEls) {
		const layoutId = seriesEl.getAttribute('layoutId')
		if (layoutId && !layoutIds.includes(layoutId)) layoutIds.push(layoutId)
		const dataIdEl = _childrenByLocalName(seriesEl, 'dataId')[0]
		const dataId = dataIdEl?.getAttribute('val')
		if (!dataId || !dataById.has(dataId)) continue
		const model = dataById.get(dataId)
		const labels = model.labels.length <= 1 ? (model.labels[0] || []) : model.labels
		chartData.push({
			name: `Series ${chartData.length + 1}`,
			labels,
			values: model.values,
		})
	}
	if (chartData.length === 0) {
		for (const model of dataById.values()) {
			const labels = model.labels.length <= 1 ? (model.labels[0] || []) : model.labels
			chartData.push({
				name: `Series ${chartData.length + 1}`,
				labels,
				values: model.values,
			})
		}
	}
	const chartType = _inferChartExType(layoutIds, chartXml)
	return {
		chartType,
		layoutIds,
		dimensionTypes: Array.from(dimensionTypes),
		chartData: chartData.length ? chartData : [{ name: 'Series 1', labels: ['Category 1'], values: [1] }],
	}
}

function _rawPartByPath(pptx, partPath) {
	const target = normalizeZipPartPath(partPath)
	return (pptx?._rawPackageParts || []).find(part => normalizeZipPartPath(part.path) === target) || null
}

function _collectRawChartPackageGraph(pptx, rootPartPath) {
	const paths = new Set()
	const visit = partPath => {
		const normalized = normalizeZipPartPath(partPath)
		if (!normalized.startsWith('ppt/charts/') || paths.has(normalized)) return
		const part = _rawPartByPath(pptx, normalized)
		if (!part) return
		paths.add(normalized)
		const relsPath = relsPathForPart(normalized)
		const relsPart = _rawPartByPath(pptx, relsPath)
		if (relsPart) {
			paths.add(relsPath)
			for (const rel of parseRelationshipEntries(_getRawPartText(relsPart))) {
				if (rel.targetMode === 'External' || isExternalTarget(rel.target)) continue
				const child = resolvePackageTarget(normalized, rel.target)
				if (child?.startsWith('ppt/charts/')) visit(child)
			}
		}
	}
	visit(rootPartPath)
	return paths
}

function _removeRawPackageParts(pptx, paths) {
	if (!paths?.size || !Array.isArray(pptx?._rawPackageParts)) return 0
	const before = pptx._rawPackageParts.length
	pptx._rawPackageParts = pptx._rawPackageParts.filter(part => !paths.has(normalizeZipPartPath(part.path)))
	return before - pptx._rawPackageParts.length
}

function _rawChartGraphStillReferenced(pptx, graphPaths) {
	if (!graphPaths?.size) return false
	const slides = Array.isArray(pptx?.slides) ? pptx.slides : []
	for (let i = 0; i < slides.length; i++) {
		const slide = slides[i]
		const slidePart = `ppt/slides/slide${i + 1}.xml`
		for (const rel of slide?._rawRels || []) {
			if (rel.targetMode === 'External' || isExternalTarget(rel.target)) continue
			const targetPart = resolvePackageTarget(slidePart, rel.target)
			if (targetPart && graphPaths.has(targetPart)) return true
		}
	}
	return false
}

function _chartExRawInfoForPassthrough(pptx, slide, slideIndex, obj) {
	const ids = new Set(collectRelationshipIds(obj?.passthrough?.xml || ''))
	const slidePart = `ppt/slides/slide${slideIndex + 1}.xml`
	const rawRels = Array.isArray(slide?._rawRels) ? slide._rawRels : []
	const referencedRels = rawRels.filter(rel => ids.has(rel.id))
	const chartRel = referencedRels.find(rel => String(rel.type || '').toLowerCase().endsWith('/chartex') || String(rel.type || '').includes('/chartEx'))
	const chartPartPath = chartRel && chartRel.targetMode !== 'External' ? resolvePackageTarget(slidePart, chartRel.target) : null
	const chartPart = chartPartPath ? _rawPartByPath(pptx, chartPartPath) : null
	const chartXml = chartPart ? _getRawPartText(chartPart) : ''
	return { ids, referencedRels, chartRel, chartPartPath, chartXml }
}

function _removePassthroughRelsForObject(slide, obj, relIds) {
	if (!relIds?.size || !Array.isArray(slide?._rawRels)) return 0
	const stillReferenced = new Set()
	for (const other of slide._slideObjects || []) {
		if (other === obj || !other?.passthrough?.xml) continue
		for (const id of collectRelationshipIds(other.passthrough.xml)) stillReferenced.add(id)
	}
	const before = slide._rawRels.length
	slide._rawRels = slide._rawRels.filter(rel => !relIds.has(rel.id) || stillReferenced.has(rel.id))
	return before - slide._rawRels.length
}

function _replaceSlideObjectInPlace(slide, rawIndex, createReplacement) {
	const objects = slide?._slideObjects || []
	if (!objects[rawIndex]) throw new Error('update: target raw object is no longer available for in-place replacement.')
	objects.splice(rawIndex, 1)
	const beforeAdd = objects.length
	createReplacement()
	const added = objects.splice(beforeAdd)
	if (!added.length) throw new Error('update: in-place replacement did not create an object.')
	objects.splice(rawIndex, 0, ...added)
	return { replacement: added[0], addedCount: added.length }
}

function _passthroughRelInfo({ pptx, slide, slideIndex, obj, typeNeedle }) {
	const ids = new Set(collectRelationshipIds(obj?.passthrough?.xml || ''))
	const normalizedNeedle = String(typeNeedle || '').toLowerCase()
	const slidePart = `ppt/slides/slide${slideIndex + 1}.xml`
	const referencedRels = (Array.isArray(slide?._rawRels) ? slide._rawRels : [])
		.filter(rel => ids.has(rel.id))
	const rel = referencedRels.find(item => {
		const type = String(item.type || '').toLowerCase()
		return !normalizedNeedle || type.includes(normalizedNeedle)
	})
	const partPath = rel && rel.targetMode !== 'External' ? resolvePackageTarget(slidePart, rel.target) : null
	const part = partPath ? _rawPartByPath(pptx, partPath) : null
	return {
		ids,
		referencedRels,
		rel,
		partPath,
		partXml: part ? _getRawPartText(part) : '',
	}
}

function _convertChartExPassthroughForUpdate({ pptx, slide, slideIndex, obj, rawIndex, args }) {
	const info = _chartExRawInfoForPassthrough(pptx, slide, slideIndex, obj)
	const parsed = info.chartXml ? _parseChartExStructuredData(info.chartXml) : {
		chartType: 'histogram',
		layoutIds: [],
		dimensionTypes: [],
		chartData: [{ name: 'Series 1', labels: ['Category 1'], values: [1] }],
	}
	const requestedType = args.chartMulti ?? args.chartType ?? args.type ?? parsed.chartType
	const nextType = Array.isArray(requestedType) ? _deepCloneData(requestedType) : _normalizeChartExType(requestedType)
	const data = args.data !== undefined ? _normalizeChartDataForUpdate(args.data) : _normalizeChartDataForUpdate(parsed.chartData)
	const opts = {
		x: obj.options?.x ?? 1,
		y: obj.options?.y ?? 1,
		w: obj.options?.w ?? '50%',
		h: obj.options?.h ?? '50%',
		objectName: obj.options?.objectName,
		spid: obj.options?.spid,
		_chartEx: !Array.isArray(nextType) && _isChartExChartType(nextType),
		...(parsed.layoutIds?.[0] && !Array.isArray(nextType) ? { chartExLayoutId: parsed.layoutIds[0] } : {}),
	}
	if (args.optionsPatch) _deepMerge(opts, args.optionsPatch)
	const rawGraphPaths = info.chartPartPath ? _collectRawChartPackageGraph(pptx, info.chartPartPath) : new Set()
	const rawRelsRemoved = _removePassthroughRelsForObject(slide, obj, info.ids)
	const rawPartsRemoved = _rawChartGraphStillReferenced(pptx, rawGraphPaths)
		? 0
		: _removeRawPackageParts(pptx, rawGraphPaths)
	slide.addChart(nextType, data, opts)
	const replacement = slide._slideObjects.pop()
	if (!replacement) throw new Error('update_chart: failed to create replacement ChartEx object.')
	slide._slideObjects.splice(rawIndex, 1, replacement)
	const rel = _findChartRel(slide, replacement)
	if (rel) _setChartRelFamilyForType(rel, nextType)
	return {
		replacement,
		chartType: nextType,
		seriesCount: Array.isArray(data) ? data.length : 0,
		rawRelsRemoved,
		rawPartsRemoved,
		chartEx: {
			layoutIds: parsed.layoutIds,
			dimensionTypes: parsed.dimensionTypes,
			chartPartPath: info.chartPartPath,
		},
	}
}

function _convertChartPassthroughForUpdate({ pptx, slide, slideIndex, obj, rawIndex, args }) {
	const info = _passthroughRelInfo({ pptx, slide, slideIndex, obj, typeNeedle: '/chart' })
	const parsed = info.partXml ? exportedChartSeriesFromXml(info.partXml) : null
	const requestedType = args.chartMulti ?? args.chartType ?? args.type ?? parsed?.chartType ?? 'bar'
	const data = args.data !== undefined ? args.data : (parsed?.data || [{ name: 'Series 1', labels: ['Category 1'], values: [1] }])
	const opts = {
		x: obj.options?.x ?? 1,
		y: obj.options?.y ?? 1,
		w: obj.options?.w ?? '50%',
		h: obj.options?.h ?? '50%',
		objectName: obj.options?.objectName,
		spid: obj.options?.spid,
	}
	if (args.optionsPatch) _deepMerge(opts, args.optionsPatch)
	const rawGraphPaths = info.partPath ? _collectRawChartPackageGraph(pptx, info.partPath) : new Set()
	const rawRelsRemoved = _removePassthroughRelsForObject(slide, obj, info.ids)
	const rawPartsRemoved = _rawChartGraphStillReferenced(pptx, rawGraphPaths)
		? 0
		: _removeRawPackageParts(pptx, rawGraphPaths)
	const { replacement } = _replaceSlideObjectInPlace(slide, rawIndex, () => {
		if (args.chartMulti) slide.addChart(normalizeMcpChartMulti(requestedType), opts)
		else slide.addChart(requestedType, normalizeMcpChartData(requestedType, data), opts)
	})
	const rel = _findChartRel(slide, replacement)
	if (rel) _setChartRelFamilyForType(rel, requestedType)
	return {
		replacement,
		chartType: requestedType,
		seriesCount: Array.isArray(data) ? data.length : 0,
		rawRelsRemoved,
		rawPartsRemoved,
	}
}

const CHART_STYLE_RESOURCE_KEYS = Object.freeze(['_rawChartStyleXml', '_rawChartStyleName'])
const CHART_COLOR_RESOURCE_KEYS = Object.freeze(['_rawChartColorsXml', '_rawChartColorsName'])

function _clearChartResourceKeys(options, keys) {
	if (!options || typeof options !== 'object') return
	for (const key of keys) delete options[key]
}

function _reexpandUpdatedChartSelectorResources(pptx, options, requestedOptions = {}) {
	if (!options || typeof options !== 'object') return
	const hasRequested = key => Object.prototype.hasOwnProperty.call(requestedOptions, key)
	const stylePresetReset = hasRequested('chartStylePresetId') && requestedOptions.chartStylePresetId === null
	const independentStyleRequest = ['chartGalleryTilePresetId', 'chartGalleryVariant', 'chartStyleId', 'chartStyleModernId']
		.some(key => hasRequested(key) && requestedOptions[key] !== null)
	const styleChanged = [
		'chartGalleryTilePresetId', 'chartStylePresetId', 'chartGalleryVariant',
		'chartStyleId', 'chartStyleModernId',
	].some(hasRequested)
	const colorChanged = hasRequested('chartColorStyleId')
	if (!styleChanged && !colorChanged) return
	if (stylePresetReset) {
		delete options.chartStylePresetId
		if (!independentStyleRequest) {
			for (const key of ['chartGalleryVariant', 'chartStyleId', 'chartStyleModernId', 'galleryId', 'styleCatalogId', 'colorCatalogId']) delete options[key]
		}
	}

	const gallery = pptx?.ChartGallery || pptx?._chartGallery
	const galleryId = Number(options.chartGalleryVariant)
	const galleryVariant = Number.isInteger(galleryId) ? gallery?.variants?.[galleryId] : null
	if (styleChanged) {
		_clearChartResourceKeys(options, CHART_STYLE_RESOURCE_KEYS)
		_clearChartResourceKeys(options, CHART_COLOR_RESOURCE_KEYS)
		if (galleryVariant?._rawChartStyleXml && galleryVariant?._rawChartStyleName) {
			for (const key of ['galleryId', 'styleCatalogId', 'colorCatalogId', 'chartStyleId']) {
				if (galleryVariant[key] !== undefined) options[key] = galleryVariant[key]
			}
			options._rawChartStyleXml = galleryVariant._rawChartStyleXml
			options._rawChartStyleName = galleryVariant._rawChartStyleName
		}
		if (galleryVariant?._rawChartColorsXml && galleryVariant?._rawChartColorsName) {
			options._rawChartColorsXml = galleryVariant._rawChartColorsXml
			options._rawChartColorsName = galleryVariant._rawChartColorsName
		}
	} else {
		_clearChartResourceKeys(options, CHART_COLOR_RESOURCE_KEYS)
	}

	const colorStyleId = Number(options.chartColorStyleId)
	const nativeColorXml = Number.isInteger(colorStyleId) ? gallery?.nativeColorCatalog?.[colorStyleId] : null
	if (nativeColorXml) {
		options._rawChartColorsXml = nativeColorXml
		options._rawChartColorsName = `mcp-chart-colors-native-${colorStyleId}.xml`
	} else if (colorChanged && galleryVariant?._rawChartColorsXml && galleryVariant?._rawChartColorsName) {
		// Nullable color reset restores the selected gallery variant's native
		// color resource instead of retaining the previously selected color part.
		options._rawChartColorsXml = galleryVariant._rawChartColorsXml
		options._rawChartColorsName = galleryVariant._rawChartColorsName
	}
}

async function handleUpdateChart(args) {
	validateDirectChartUpdate(args)
	const authoredOptionsPatch = args.optionsPatch
	const authoredSelectorPatch = Object.fromEntries(CHART_SELECTOR_FIELDS.filter(key => Object.prototype.hasOwnProperty.call(args, key)).map(key => [key, args[key]]))
	if (authoredOptionsPatch === null && Object.keys(authoredSelectorPatch).length) throw new Error('slide.update_chart cannot combine a full options reset with selector changes.')
	const { pptx } = getDeck(args.deckId)
	const slide = getSlide(args.deckId, args.slideIndex)
	const selectorKeys = [
		'chartPresetId', 'chartGalleryTilePresetId', 'chartStylePresetId',
		'chartGalleryVariant', 'chartStyleId', 'chartStyleModernId',
		'chartColorStyleId', 'chartLayoutPresetId', 'chartTreatmentPresetId',
		'chartTreatmentPresetIds',
	]
	const requestedOptions = {
		...(args.optionsPatch && typeof args.optionsPatch === 'object' ? args.optionsPatch : {}),
		...Object.fromEntries(selectorKeys.filter(key => args[key] !== undefined).map(key => [key, args[key]])),
	}
	const chartPlan = await resolveProductChartPlan({ chartType: args.chartType || args.type, chartMulti: args.chartMulti, options: requestedOptions })
	if (chartPlan.mode !== 'none') {
		args = {
			...args,
			...(args.chartType || args.type || args.chartMulti ? {} : (chartPlan.selectedChartType ? { chartType: chartPlan.selectedChartType } : {})),
			optionsPatch: mergeResolvedChartOptions(chartPlan.plan || {}, args.optionsPatch || {}),
		}
	}
	const { obj, index, rawIndex } = _resolveShapeForTool(slide, args.target, 'update_chart')
	if (_shapeKind(obj) !== 'chart') {
		const converted = _isChartExPassthrough(obj)
			? _convertChartExPassthroughForUpdate({ pptx, slide, slideIndex: args.slideIndex, obj, rawIndex, args })
			: (_shapeKind(obj) === 'passthrough' && (args.data !== undefined || args.chartType !== undefined || args.type !== undefined || args.chartMulti !== undefined)
				? _convertChartPassthroughForUpdate({ pptx, slide, slideIndex: args.slideIndex, obj, rawIndex, args })
				: null)
		if (!converted) {
			throw new Error(`update_chart: target "${obj.options?.objectName || index}" is ${_shapeKind(obj) || 'unknown'}, expected chart or editable ChartEx passthrough.`)
		}
		return {
			ok: true,
			slideIndex: args.slideIndex,
			index,
			rawIndex,
			objectName: converted.replacement.options?.objectName,
			chartType: converted.chartType,
			chartFamily: _isChartExChartType(converted.chartType) ? 'chartEx' : 'legacy',
			seriesCount: converted.seriesCount,
			optionsPatched: !!args.optionsPatch,
			convertedFromPassthrough: converted.chartEx ? 'chartEx' : 'chart',
			rawRelsRemoved: converted.rawRelsRemoved,
			rawPartsRemoved: converted.rawPartsRemoved,
			...(converted.chartEx ? { chartEx: converted.chartEx } : {}),
		}
	}
	const rel = _findChartRel(slide, obj)
	if (!rel) throw new Error('update_chart: chart relationship not found; raw/passthrough chart packages are not structurally editable through this tool.')
	if (args.data !== undefined) rel.data = _normalizeChartDataForUpdate(args.data)
	if (!rel.opts || typeof rel.opts !== 'object') rel.opts = obj.options || {}
	const currentType = rel.type ?? rel.opts?._type ?? obj.options?._type
	const requestedType = args.chartMulti !== undefined
		? args.chartMulti
		: (args.chartType !== undefined || args.type !== undefined ? _normalizeChartExType(args.chartType ?? args.type) : undefined)
	const nextType = requestedType !== undefined ? requestedType : currentType
	if (nextType === undefined || nextType === null || nextType === '') {
		throw new Error('update_chart: chart type could not be inferred; pass chartType when updating this chart.')
	}
	rel.type = _deepCloneData(nextType)
	const publicChartOptionFields = new Set(Object.keys(CHART_OPTIONS_PUBLIC_SCHEMA.properties))
	if (authoredOptionsPatch === null) {
		for (const key of publicChartOptionFields) delete rel.opts[key]
		_clearChartResourceKeys(rel.opts, CHART_STYLE_RESOURCE_KEYS)
		_clearChartResourceKeys(rel.opts, CHART_COLOR_RESOURCE_KEYS)
	} else {
		const effectivePatch = { ...(args.optionsPatch && typeof args.optionsPatch === 'object' ? args.optionsPatch : {}), ...authoredSelectorPatch }
		for (const [key, value] of Object.entries(effectivePatch)) {
			if (value === null) delete rel.opts[key]
			else if (value && typeof value === 'object' && !Array.isArray(value) && rel.opts[key] && typeof rel.opts[key] === 'object' && !Array.isArray(rel.opts[key])) _deepMerge(rel.opts[key], value)
			else rel.opts[key] = _deepCloneData(value)
		}
	}
	rel.opts._type = _deepCloneData(nextType)
	_setChartRelFamilyForType(rel, rel.type)
	// Imported legacy charts are eagerly re-emitted with an exact raw chart
	// replay payload. Once an edit is requested, that payload must no longer
	// outrank the updated semantic relationship data, otherwise save silently
	// writes the original chart XML while reporting a successful mutation.
	for (const key of ['_rawChartXml', '_rawChartRelsXml', '_rawChartWorkbookBase64', '_rawChartWorkbookName', '_rawChartFallbackImageBase64', '_rawChartFallbackImageContentType', '_rawChartFallbackImageRid']) {
		if (obj.options && Object.prototype.hasOwnProperty.call(obj.options, key)) delete obj.options[key]
		if (rel.opts && Object.prototype.hasOwnProperty.call(rel.opts, key)) delete rel.opts[key]
	}
	// addChartDefinition expands governed style/color selectors into concrete
	// per-chart Office resource parts. An in-place re-edit does not call that
	// creation boundary, so rebuild only those resources here and ensure the old
	// style/color XML cannot continue to win after the semantic selector changes.
	_reexpandUpdatedChartSelectorResources(pptx, rel.opts, requestedOptions)
	const priorState = rel.opts._chartAuthoringState && typeof rel.opts._chartAuthoringState === 'object' ? rel.opts._chartAuthoringState : {}
	const nextSelectors = authoredOptionsPatch === null ? {} : { ...(priorState.selectors || {}) }
	const nextExplicitOptions = authoredOptionsPatch === null ? {} : { ...(priorState.explicitOptions || {}) }
	if (authoredOptionsPatch && typeof authoredOptionsPatch === 'object') {
		for (const [key, value] of Object.entries(authoredOptionsPatch)) {
			if (CHART_SELECTOR_FIELDS.includes(key)) {
				if (value === null) delete nextSelectors[key]
				else nextSelectors[key] = _deepCloneData(value)
			} else if (publicChartOptionFields.has(key)) {
				if (value === null) delete nextExplicitOptions[key]
				else nextExplicitOptions[key] = _deepCloneData(value)
			}
		}
	}
	for (const [key, value] of Object.entries(authoredSelectorPatch)) {
		if (value === null) delete nextSelectors[key]
		else nextSelectors[key] = _deepCloneData(value)
	}
	rel.opts._chartAuthoringState = authoredChartState(nextSelectors, nextExplicitOptions)
	obj.options = rel.opts
	return {
		ok: true,
		slideIndex: args.slideIndex,
		index,
		rawIndex,
		objectName: obj.options?.objectName,
		chartType: rel.type,
		chartFamily: rel.chartFamily || 'legacy',
		seriesCount: Array.isArray(rel.data) ? rel.data.length : 0,
		optionsPatched: !!args.optionsPatch,
	}
}

function _removeSmartArtPackageRefs(slide, smartArt) {
	if (!smartArt || typeof smartArt !== 'object') return { relsRemoved: 0, partsRemoved: 0 }
	const relIds = new Set([smartArt.dataRid, smartArt.layoutRid, smartArt.quickStyleRid, smartArt.colorStyleRid, smartArt.drawingRid].filter(Boolean))
	const partPaths = new Set(Object.values(smartArt.partPaths || {}).filter(Boolean))
	let relsRemoved = 0
	let partsRemoved = 0
	if (Array.isArray(slide._rawRels) && relIds.size) {
		const before = slide._rawRels.length
		slide._rawRels = slide._rawRels.filter(rel => !relIds.has(rel.id))
		relsRemoved = before - slide._rawRels.length
	}
	if (Array.isArray(slide._nativePackageParts) && partPaths.size) {
		const before = slide._nativePackageParts.length
		slide._nativePackageParts = slide._nativePackageParts.filter(part => !partPaths.has(part.path))
		partsRemoved = before - slide._nativePackageParts.length
	}
	return { relsRemoved, partsRemoved }
}

function _replaceSmartArtNode(nodes, path, text) {
	if (!Array.isArray(nodes) || !path.length) return false
	const index = Number(path[0])
	if (!Number.isInteger(index) || index < 0 || index >= nodes.length) return false
	if (path.length === 1) {
		if (typeof nodes[index] === 'string') nodes[index] = String(text)
		else if (nodes[index] && typeof nodes[index] === 'object') nodes[index].text = String(text)
		else nodes[index] = String(text)
		return true
	}
	const child = nodes[index]
	if (!child || typeof child !== 'object') return false
	return _replaceSmartArtNode(child.children || (child.children = []), path.slice(1), text)
}

function _preservedSmartArtOptions(options = {}) {
	const safe = {}
	for (const key of [
		'fontFace', 'fontSize', 'color', 'textColors', 'palette', 'fill', 'line', 'shadow',
		'rightToLeft', 'title', 'accessibilityTitle', 'altText', 'isDecorative', 'margin', 'fit', 'transparency', 'textDirection',
	]) {
		if (options[key] !== undefined) safe[key] = _deepCloneData(options[key])
	}
	return safe
}

async function handleUpdateSmartArt(args) {
	const { pptx } = getDeck(args.deckId)
	const slide = getSlide(args.deckId, args.slideIndex)
	const { obj, index, rawIndex } = _resolveShapeForTool(slide, args.target, 'update_smartart')
	if (typeof slide.addSmartArt !== 'function') throw new Error('update_smartart: runtime does not expose slide.addSmartArt.')
	if (_shapeKind(obj) !== 'smartart') {
		const parsed = _shapeKind(obj) === 'passthrough'
			? exportedPassthroughSmartArtFields({ pptx, slide, slideIndex: args.slideIndex, obj })
			: null
		const prevOpts = obj.options || {}
		const nodes = _deepCloneData(args.nodes ?? parsed?.fields?.nodes ?? prevOpts._smartArtAuthoredNodes ?? prevOpts.nodes ?? [])
		if (args.nodeIndex !== undefined || Array.isArray(args.nodePath)) {
			const path = Array.isArray(args.nodePath) ? args.nodePath : [args.nodeIndex]
			if (!_replaceSmartArtNode(nodes, path, args.text ?? args.label ?? '')) {
				// A flat nodeIndex against a structured one-root layout is an
				// unsafe mutation, not a missing object. Let the topology contract
				// produce the actionable SMARTART_NODE_TOPOLOGY_INVALID diagnostic.
				if (args.nodePath === undefined && args.nodeIndex !== undefined) {
					if (!nodes.length) nodes.push({ text: 'Node 1', children: [] })
					else if (typeof nodes[0] !== 'object' || Array.isArray(nodes[0])) nodes[0] = { text: String(nodes[0] || 'Node 1'), children: [] }
					nodes.push('__unsafe_flat_update__')
				}
				else throw new Error(`update_smartart: node path ${path.join('.')} not found.`)
			}
		}
		if (_shapeKind(obj) !== 'passthrough' || !Array.isArray(nodes) || nodes.length === 0) {
			throw new Error(`update_smartart: target "${obj.options?.objectName || index}" is ${_shapeKind(obj) || 'unknown'}, expected smartart.`)
		}
		const opts = {
			..._preservedSmartArtOptions(prevOpts),
			mode: 'native',
			native: true,
			layoutId: args.layoutId ?? parsed?.fields?.layoutId,
			layoutName: args.layoutName ?? parsed?.fields?.layoutName,
			layout: args.layout ?? parsed?.fields?.layout ?? prevOpts.layout,
			quickStyleId: args.quickStyleId ?? parsed?.fields?.quickStyleId,
			colorStyleId: args.colorStyleId ?? parsed?.fields?.colorStyleId,
			x: prevOpts.x, y: prevOpts.y, w: prevOpts.w, h: prevOpts.h,
			objectName: prevOpts.objectName,
			spid: prevOpts.spid,
			nodes,
		}
		if (args.optionsPatch) _deepMerge(opts, args.optionsPatch)
		for (const key of ['text', 'label', 'nodeIndex', 'nodePath', 'target', 'deckId', 'slideIndex', 'action']) delete opts[key]
		const normalizedSmartArt = normalizeSmartArtOptions(opts, 'slide.update_smartart options')
		for (const key of Object.keys(opts)) delete opts[key]
		Object.assign(opts, normalizedSmartArt)
		Object.assign(opts, normalizeInternalAccessibilityMetadata(opts, 'slide.update_smartart options'))
		const resolvedLayout = await resolveSmartArtLayoutOption(opts)
		enforceSmartArtNodeTopology(opts, resolvedLayout)
		const info = _passthroughRelInfo({ pptx, slide, slideIndex: args.slideIndex, obj })
		const rawRelsRemoved = _removePassthroughRelsForObject(slide, obj, info.ids)
		const { replacement } = _replaceSlideObjectInPlace(slide, rawIndex, () => slide.addSmartArt(opts))
		return {
			ok: true,
			slideIndex: args.slideIndex,
			index,
			rawIndex,
			objectName: replacement?.options?.objectName,
			nodeCount: replacement?.smartArt?.nodes?.length || nodes.length,
			convertedFromPassthrough: 'smartart',
			rawRelsRemoved,
		}
	}
	const smartArt = obj.smartArt || {}
		const prevOpts = obj.options || {}
	const nodes = _deepCloneData(args.nodes ?? smartArt.authoredNodes ?? prevOpts._smartArtAuthoredNodes ?? prevOpts.nodes ?? [])
	if (args.nodeIndex !== undefined || Array.isArray(args.nodePath)) {
		const path = Array.isArray(args.nodePath) ? args.nodePath : [args.nodeIndex]
		if (!_replaceSmartArtNode(nodes, path, args.text ?? args.label ?? '')) {
			if (args.nodePath === undefined && args.nodeIndex !== undefined) {
				if (!nodes.length) nodes.push({ text: 'Node 1', children: [] })
				else if (typeof nodes[0] !== 'object' || Array.isArray(nodes[0])) nodes[0] = { text: String(nodes[0] || 'Node 1'), children: [] }
				nodes.push('__unsafe_flat_update__')
			}
			else throw new Error(`update_smartart: node path ${path.join('.')} not found.`)
		}
	}
	if (!Array.isArray(nodes) || nodes.length === 0) throw new Error('update_smartart: SmartArt nodes are required for mutation.')
	const opts = {
		..._preservedSmartArtOptions(prevOpts),
		mode: 'native',
		native: true,
		layoutId: args.layoutId ?? prevOpts.layoutId ?? smartArt.layoutId,
		layoutName: args.layoutName ?? prevOpts.layoutName ?? smartArt.layoutName,
		layout: args.layout ?? prevOpts.layout,
		quickStyleId: args.quickStyleId ?? prevOpts.quickStyleId ?? smartArt.quickStyleId,
		colorStyleId: args.colorStyleId ?? prevOpts.colorStyleId ?? smartArt.colorStyleId,
		x: prevOpts.x, y: prevOpts.y, w: prevOpts.w, h: prevOpts.h,
		objectName: prevOpts.objectName,
		spid: prevOpts.spid,
		nodes,
	}
	if (args.optionsPatch) _deepMerge(opts, args.optionsPatch)
	for (const key of ['text', 'label', 'nodeIndex', 'nodePath', 'target', 'deckId', 'slideIndex', 'action']) delete opts[key]
	const normalizedSmartArt = normalizeSmartArtOptions(opts, 'slide.update_smartart options')
	for (const key of Object.keys(opts)) delete opts[key]
	Object.assign(opts, normalizedSmartArt)
	Object.assign(opts, normalizeInternalAccessibilityMetadata(opts, 'slide.update_smartart options'))
	const resolvedLayout = await resolveSmartArtLayoutOption(opts)
	enforceSmartArtNodeTopology(opts, resolvedLayout)
	const removed = _removeSmartArtPackageRefs(slide, smartArt)
	const objects = slide._slideObjects || []
	objects.splice(rawIndex, 1)
	slide.addSmartArt(opts)
	const replacement = objects.pop()
	objects.splice(rawIndex, 0, replacement)
	return {
		ok: true,
		slideIndex: args.slideIndex,
		index,
		rawIndex,
		objectName: replacement?.options?.objectName,
		nodeCount: replacement?.smartArt?.nodes?.length || nodes.length,
		relsRemoved: removed.relsRemoved,
		partsRemoved: removed.partsRemoved,
	}
}

function _normalizeMediaVolume(value) {
	if (value === undefined || value === null || value === '') return undefined
	const n = Number(value)
	if (!Number.isFinite(n)) throw new Error(`update_media: invalid volume ${value}.`)
	if (n <= 1) return Math.round(Math.max(0, Math.min(1, n)) * 100000)
	if (n <= 100) return Math.round(Math.max(0, Math.min(100, n)) * 1000)
	return Math.round(Math.max(0, Math.min(100000, n)))
}

function _isMediaAnimationRecord(record, spid, obj) {
	if (!record) return false
	const effect = String(record.animation?.effect || '').toLowerCase()
	const type = String(record.animation?.type || '').toLowerCase()
	return (record.target === obj || record.shapeId === spid) && (
		type === 'media' || effect.startsWith('media') || ['play', 'pause', 'togglepause', 'stop'].includes(effect)
	)
}

// Imported/uploaded talking-head media can be reused through the semantic
// Director patch without exposing coordinates or asking the AI to rebuild the
// package.  This helper applies the same accepted frame and narration-led
// dwell used by newly authored avatar media.  It intentionally takes a
// semantic contract token, never a caller-supplied rectangle.
async function _applyAcceptedAvatarFrameContract(entry, slide, obj, args = {}) {
	const requested = String(args.avatarFrameContract || args.optionsPatch?.avatarFrameContract || '').trim().toLowerCase()
	if (requested !== 'ellipse-centered-cover-v1') return { applied: false, durationMs: null, advanceAfterTime: null }
	const isNativeRecordStudioCapture = obj?._type === 'media'
		&& String(obj.mtype || '').toLowerCase() === 'video'
		&& obj.options?._nativeRecordStudioCapture === true
	if (!isNativeRecordStudioCapture) {
		const err = new Error('The talking-head frame contract applies only to an authentic Avatar talking-head video capture. Ordinary media cannot be promoted into a talking head.')
		err.code = 'NATIVE_RECORD_STUDIO_CAPTURE_REQUIRED'
		throw err
	}
	const box = avatarVideoBox(args)
	obj.options = obj.options || {}
	Object.assign(obj.options, box, {
		rounding: true,
		_picPrstGeom: 'ellipse',
		avatarFrameContract: 'ellipse-centered-cover-v1',
		// This flag is reasserted only after the package-level native-session
		// evidence gate above. Geometry or a caller token can never create identity.
		isNarration: true,
		// PowerPoint does not paint a video poster while a native media node is
		// stopped unless the node explicitly opts into the stopped frame.  The
		// accepted presenter contract requires a visible talking head before and
		// during autoplay, so this is engine-owned state rather than an AI choice.
		showWhenStopped: String(obj.mtype || '').toLowerCase() === 'video' ? true : false,
		endOnStopAudio: true,
	})
	// A few imported Record Studio packages carry a separate poster picture at
	// the old presenter rectangle.  It is not the media's required cover; it is
	// a second visible presenter and can paint over the ellipse in PowerPoint.
	// Remove that collision at the semantic repair boundary so the AI never has
	// to name or delete an opaque/native picture block.
	let duplicatePresenterVisualsRemoved = 0
	const area = (x, y, w, h) => Math.max(0, Number(w) || 0) * Math.max(0, Number(h) || 0)
	const overlap = (a, b) => {
		const left = Math.max(Number(a.x) || 0, Number(b.x) || 0)
		const top = Math.max(Number(a.y) || 0, Number(b.y) || 0)
		const right = Math.min((Number(a.x) || 0) + (Number(a.w) || 0), (Number(b.x) || 0) + (Number(b.w) || 0))
		const bottom = Math.min((Number(a.y) || 0) + (Number(a.h) || 0), (Number(b.y) || 0) + (Number(b.h) || 0))
		return area(left, top, Math.max(0, right - left), Math.max(0, bottom - top))
	}
	for (let index = (slide._slideObjects || []).length - 1; index >= 0; index -= 1) {
		const candidate = slide._slideObjects[index]
		if (!candidate || candidate === obj) continue
		const kind = String(_shapeKind(candidate) || candidate._type || '').toLowerCase()
		const candidateName = String(candidate.options?.objectName || '').trim()
		const namedPresenterBackdrop = /^(?:avatar[-_\s]?backing|avatar[-_\s]?poster|picture(?:\s|$))/i.test(candidateName)
		if (!namedPresenterBackdrop && !['image', 'picture'].includes(kind)) continue
		const candidateRect = candidate.options || {}
		const candidateArea = area(candidateRect.x, candidateRect.y, candidateRect.w, candidateRect.h)
		const overlapRatio = candidateArea > 0 ? overlap(box, candidateRect) / candidateArea : 0
		const removeAsPresenterCollision = candidateArea > 0 && (namedPresenterBackdrop ? overlapRatio >= 0.2 : overlapRatio >= 0.5)
		if (removeAsPresenterCollision) {
			slide._slideObjects.splice(index, 1)
			duplicatePresenterVisualsRemoved += 1
		}
	}
	const mediaPath = typeof obj.media === 'string' && obj.media.trim()
		? obj.media
		: typeof obj.options.media === 'string' && obj.options.media.trim() ? obj.options.media : null
	let durationMs = Number(entry.avatarManifest?.slides?.find(item => Number(item.slideIndex) === Number(args.slideIndex))?.durationMs || 0)
	let sourceW = Number(obj.options._sizingSourceW)
	let sourceH = Number(obj.options._sizingSourceH)
	if (mediaPath) {
		try {
			const info = await probeMedia({ filePath: mediaPath })
			const video = (info.streams || []).find(stream => stream?.codec_type === 'video')
			if (video?.width > 0) sourceW = Number(video.width)
			if (video?.height > 0) sourceH = Number(video.height)
			const seconds = Number(info.format?.duration || video?.duration || 0)
			if (Number.isFinite(seconds) && seconds > 0) durationMs = Math.round(seconds * 1000)
		} catch {}
	}
	// Imported Record Studio packages frequently carry PowerPoint's generic
	// play-button cover.  That is not an identity frame and is invisible when
	// the native narration node is running.  Replace it at the shared semantic
	// repair boundary with a deterministic first frame from the approved media;
	// the public AI never sees the path or the generated asset handle.
	let generatedPosterData = null
	if (mediaPath && String(obj.mtype || '').toLowerCase() === 'video') {
		try {
			const posterDir = await fs.mkdtemp(path.join(os.tmpdir(), 'betterpptx-avatar-poster-'))
			const posterPath = path.join(posterDir, 'poster.png')
			await extractPosterPng({ inputPath: mediaPath, outputPath: posterPath })
			const coverData = `data:image/png;base64,${(await fs.readFile(posterPath)).toString('base64')}`
			generatedPosterData = coverData
			const coverRid = Number(obj.mediaCoverRid ?? (Number(obj.mediaRid) + 2))
			const coverRel = (slide._relsMedia || []).find(rel => Number(rel?.rId) === coverRid)
			if (coverRel) {
				coverRel.data = coverData
				coverRel.path = 'preencoded.png'
				coverRel.type = 'image/png'
				coverRel.extn = 'png'
			}
		} catch {}
	}
	// The generated first frame belongs only to the native media object's cover
	// relationship.  Do not add an independent same-box picture: PowerPoint can
	// keep that picture above the hardware video surface during playback, which
	// makes a structurally valid presenter appear missing.  One native media
	// object must exclusively own the accepted talking-head window.
	// Imported decks retain their raw timing tree.  Reassert the visible
	// presenter frame on that tree too; changing the object option alone cannot
	// affect an already-preserved <p:video> node.
	if (String(obj.mtype || '').toLowerCase() === 'video' && typeof slide._rawTimingXml === 'string' && slide._rawTimingXml.trim()) {
		try {
			const doc = new DOMParser().parseFromString(slide._rawTimingXml, 'text/xml')
			const targetSpid = String(Number(obj.options?.spid || 0))
			const local = node => String(node?.localName || node?.nodeName || '').split(':').pop()
			const walk = node => {
				if (!node) return
				if (node.nodeType === 1 && local(node) === 'cMediaNode') {
					const target = Array.from(node.getElementsByTagName('*')).find(child => local(child) === 'spTgt')
					if (target?.getAttribute('spid') === targetSpid) node.setAttribute('showWhenStopped', '1')
				}
				for (let index = 0; node.childNodes && index < node.childNodes.length; index += 1) walk(node.childNodes[index])
			}
			walk(doc?.documentElement)
			slide._rawTimingXml = new XMLSerializer().serializeToString(doc)
		} catch {}
	}
	// The accepted presenter window is fixed, but its centered-cover crop must be
	// derived from the approved media's actual dimensions. A 16:9 source uses
	// 21.875% left/right; a square source uses no crop; a 4:5 source uses 10%
	// top/bottom. This keeps identity framing correct without exposing source
	// dimensions or asking the AI to author crop geometry.
	if (sourceW > 0 && sourceH > 0) {
		obj.options.sizing = { type: 'cover', w: box.w, h: box.h }
		obj.options._sizingSourceW = sourceW
		obj.options._sizingSourceH = sourceH
		delete obj.options._rawBlipTailXml
	}
	const paddingMs = Math.max(0, narrationMs(args.paddingMs ?? args.optionsPatch?.paddingMs ?? 700))
	let existingAdvanceAfterTime = Number(slide.transition?.advanceAfterTime || 0)
	if (!(existingAdvanceAfterTime > 0) && typeof slide._rawTransitionXml === 'string' && slide._rawTransitionXml.trim()) {
		try {
			const doc = new DOMParser().parseFromString(slide._rawTransitionXml, 'text/xml')
			const visit = node => {
				if (!node) return 0
				if (node.nodeType === 1 && String(node.nodeName || '').split(':').pop() === 'transition') return Number(node.getAttribute('advTm') || 0)
				for (let i = 0; node.childNodes && i < node.childNodes.length; i++) {
					const candidate = visit(node.childNodes[i])
					if (candidate > 0) return candidate
				}
				return 0
			}
			existingAdvanceAfterTime = visit(doc?.documentElement)
		} catch {}
	}
	if (!(durationMs > 0) && existingAdvanceAfterTime > paddingMs) durationMs = existingAdvanceAfterTime - paddingMs
	const advanceAfterTime = durationMs > 0
		? clampAdvanceMs(durationMs + paddingMs, 1000)
		: existingAdvanceAfterTime > 0 ? clampAdvanceMs(existingAdvanceAfterTime, 1000) : null
	if (advanceAfterTime) {
		slide.transition = {
			...(slide.transition || { type: 'fade', speed: 'medium' }),
			advanceOnClick: false,
			advanceAfterTime,
		}
		if (typeof slide._rawTransitionXml === 'string' && slide._rawTransitionXml.trim()) {
			try {
				const doc = new DOMParser().parseFromString(slide._rawTransitionXml, 'text/xml')
				const transitions = []
				const visit = node => {
					if (!node) return
					if (node.nodeType === 1 && String(node.nodeName || '').split(':').pop() === 'transition') transitions.push(node)
					for (let i = 0; node.childNodes && i < node.childNodes.length; i++) visit(node.childNodes[i])
				}
				visit(doc?.documentElement)
				for (const transition of transitions) {
					transition.setAttribute('advClick', '0')
					transition.setAttribute('advTm', String(Math.round(advanceAfterTime)))
				}
				if (transitions.length) slide._rawTransitionXml = new XMLSerializer().serializeToString(doc)
			} catch {}
		}
		// Treat reused uploaded presenter media as a measured Director timeline
		// entry.  This is not a client-authored autoplay value: it is derived from
		// the existing media duration plus the engine's governed padding, and lets
		// the normal save gate see the same timeline contract as newly authored
		// avatar narration.
		recordAvatarManifestSlide(entry, {
			slideIndex: Number(args.slideIndex),
			videoObjectName: obj.options.objectName || obj.objectName || args.target?.objectName || null,
			durationMs,
			expectedDurationMs: durationMs,
			advanceAfterTime,
			startDelayMs: 0,
			paddingMs,
			mediaEndMs: durationMs,
			timelineEndMs: Math.max(durationMs, advanceAfterTime - paddingMs),
			mode: 'videoWithAudio',
			requestedCues: 0,
			cues: 0,
			captions: 0,
		})
		markDirectorTimelineContract(entry, 'avatar-media-reuse')
	}
	entry.pptx.showSettings = {
		...(entry.pptx.showSettings || {}),
		useTimings: true,
		showAnimation: true,
		showNarration: true,
		showMediaControls: args.showMediaControls ?? args.optionsPatch?.showMediaControls ?? true,
	}
	return {
		applied: true,
		durationMs: durationMs || null,
		advanceAfterTime,
		duplicatePresenterVisualsRemoved,
	}
}

// Imported Record Studio slides often carry a rich raw timing tree for shape
// animation, but omit the interactive media sequence that keeps the slideshow
// alive and lets the presenter toggle pause/resume. Preserve the authored raw
// timing and append only the narrow PowerPoint interactive sequence needed for
// the target media object. This is DOM-based XML assembly (never regex XML
// manipulation) and is intentionally idempotent.
function _ensureRawInteractiveMediaTiming(slide, spid) {
	const raw = typeof slide?._rawTimingXml === 'string' ? slide._rawTimingXml : ''
	if (!raw.trim() || !Number.isFinite(Number(spid))) return { xml: raw, added: false }
	try {
		const doc = new DOMParser().parseFromString(raw, 'text/xml')
		const elements = []
		const walk = node => {
			if (!node) return
			if (node.nodeType === 1) elements.push(node)
			for (let i = 0; node.childNodes && i < node.childNodes.length; i++) walk(node.childNodes[i])
		}
		walk(doc.documentElement)
		const local = node => String(node?.localName || node?.nodeName || '').split(':').pop()
		const find = name => elements.find(node => local(node) === name)
		const timing = find('timing')
		const tnLst = find('tnLst')
		if (!timing || !tnLst) return { xml: raw, added: false }
		const targetSpid = String(Math.trunc(Number(spid)))
		const alreadyInteractive = elements.some(node => local(node) === 'cTn' && node.getAttribute('nodeType') === 'interactiveSeq' && Array.from(node.getElementsByTagName('*')).some(child => local(child) === 'spTgt' && child.getAttribute('spid') === targetSpid))
		if (alreadyInteractive) return { xml: raw, added: false }
		const ids = elements.filter(node => local(node) === 'cTn').map(node => Number(node.getAttribute('id'))).filter(Number.isFinite)
		let nextId = Math.max(0, ...ids) + 1
		const ns = 'http://schemas.openxmlformats.org/presentationml/2006/main'
		const el = name => doc.createElementNS(ns, `p:${name}`)
		const attr = (node, values) => { for (const [key, value] of Object.entries(values)) node.setAttribute(key, String(value)); return node }
		const target = () => { const tgt = el('tgtEl'); tgt.appendChild(attr(el('spTgt'), { spid: targetSpid })); return tgt }
		const cond = (values = {}) => attr(el('cond'), values)
		const ctn = (values = {}) => attr(el('cTn'), values)
		const interactiveSeq = attr(el('seq'), { concurrent: 1, nextAc: 'seek' })
		const rootCtn = ctn({ id: nextId++, restart: 'whenNotActive', fill: 'hold', evtFilter: 'cancelBubble', nodeType: 'interactiveSeq' })
		const stCondLst = el('stCondLst'); const clickCond = cond({ evt: 'onClick', delay: 0 }); clickCond.appendChild(target()); stCondLst.appendChild(clickCond); rootCtn.appendChild(stCondLst)
		rootCtn.appendChild(attr(el('endSync'), { evt: 'end', delay: 0 })).appendChild(attr(el('rtn'), { val: 'all' }))
		const rootChildren = el('childTnLst'); const outerPar = el('par'); const outerCtn = ctn({ id: nextId++, fill: 'hold' }); const outerStart = el('stCondLst'); outerStart.appendChild(cond({ delay: 0 })); outerCtn.appendChild(outerStart)
		const outerChildren = el('childTnLst'); const innerPar = el('par'); const innerCtn = ctn({ id: nextId++, fill: 'hold' }); const innerStart = el('stCondLst'); innerStart.appendChild(cond({ delay: 0 })); innerCtn.appendChild(innerStart)
		const innerChildren = el('childTnLst'); const mediaPar = el('par'); const mediaCtn = ctn({ id: nextId++, presetID: 2, presetClass: 'mediacall', presetSubtype: 0, fill: 'hold', nodeType: 'clickEffect' }); const mediaStart = el('stCondLst'); mediaStart.appendChild(cond({ delay: 0 })); mediaCtn.appendChild(mediaStart)
		const mediaChildren = el('childTnLst'); const cmd = attr(el('cmd'), { type: 'call', cmd: 'togglePause' }); const bhvr = el('cBhvr'); bhvr.appendChild(ctn({ id: nextId++, dur: 1, fill: 'hold' })); bhvr.appendChild(target()); cmd.appendChild(bhvr); mediaChildren.appendChild(cmd); mediaCtn.appendChild(mediaChildren)
		mediaPar.appendChild(mediaCtn); innerChildren.appendChild(mediaPar); innerCtn.appendChild(innerChildren); innerPar.appendChild(innerCtn); outerChildren.appendChild(innerPar); outerCtn.appendChild(outerChildren); outerPar.appendChild(outerCtn); rootChildren.appendChild(outerPar); rootCtn.appendChild(rootChildren); interactiveSeq.appendChild(rootCtn)
		const nextCondLst = el('nextCondLst'); const nextCond = cond({ evt: 'onClick', delay: 0 }); nextCond.appendChild(target()); nextCondLst.appendChild(nextCond); interactiveSeq.appendChild(nextCondLst)
		const videoNode = elements.find(node => local(node) === 'video')
		const videoParent = videoNode?.parentNode
		if (videoParent) videoParent.insertBefore(interactiveSeq, videoNode)
		else tnLst.appendChild(interactiveSeq)
		return { xml: new XMLSerializer().serializeToString(doc), added: true }
	} catch {
		return { xml: raw, added: false }
	}
}

function _removeRawInteractiveMediaTiming(slide, spid) {
	const raw = typeof slide?._rawTimingXml === 'string' ? slide._rawTimingXml : ''
	if (!raw.trim() || !Number.isFinite(Number(spid))) return { xml: raw, removed: false }
	try {
		const doc = new DOMParser().parseFromString(raw, 'text/xml')
		const local = node => String(node?.localName || node?.nodeName || '').split(':').pop()
		const elements = []
		const walk = node => {
			if (!node) return
			if (node.nodeType === 1) elements.push(node)
			for (let i = 0; node.childNodes && i < node.childNodes.length; i++) walk(node.childNodes[i])
		}
		walk(doc.documentElement)
		const targetSpid = String(Math.trunc(Number(spid)))
		let removed = false
		for (const cTn of elements.filter(node => local(node) === 'cTn' && node.getAttribute('nodeType') === 'interactiveSeq')) {
			const ownsTarget = Array.from(cTn.getElementsByTagName('*')).some(child => local(child) === 'spTgt' && child.getAttribute('spid') === targetSpid)
			if (!ownsTarget) continue
			let container = cTn.parentNode
			while (container?.parentNode && !['seq', 'tnLst', 'timing'].includes(local(container))) container = container.parentNode
			if (local(container) !== 'seq') container = cTn
			container.parentNode?.removeChild(container)
			removed = true
		}
		return removed ? { xml: new XMLSerializer().serializeToString(doc), removed: true } : { xml: raw, removed: false }
	} catch {
		return { xml: raw, removed: false }
	}
}

// A preserved imported narration tree may schedule the native audio command
// after a later visual beat. For an avatar proof deck the narration is the
// master clock, so move only the positive-delay ancestor of that audio
// playFrom command to zero while leaving all other authored animation delays
// untouched.
function _ensureRawNarrationStartsImmediately(slide, spid) {
	const raw = typeof slide?._rawTimingXml === 'string' ? slide._rawTimingXml : ''
	if (!raw.trim() || !Number.isFinite(Number(spid))) return { xml: raw, changed: false }
	try {
		const doc = new DOMParser().parseFromString(raw, 'text/xml')
		const local = node => String(node?.localName || node?.nodeName || '').split(':').pop()
		const elements = []; const walk = node => { if (!node) return; if (node.nodeType === 1) elements.push(node); for (let i = 0; node.childNodes && i < node.childNodes.length; i++) walk(node.childNodes[i]) }; walk(doc.documentElement)
		const targetSpid = String(Math.trunc(Number(spid)))
		const cmd = elements.find(node => local(node) === 'cmd' && node.getAttribute('cmd') === 'playFrom(0.0' + ')' && Array.from(node.getElementsByTagName('*')).some(child => local(child) === 'spTgt' && child.getAttribute('spid') === targetSpid))
		if (!cmd) return { xml: raw, changed: false }
		let changed = false; let ancestor = cmd.parentNode
		while (ancestor) {
			if (local(ancestor) === 'cTn') {
				const conditions = Array.from(ancestor.childNodes || []).filter(node => local(node) === 'stCondLst').flatMap(node => Array.from(node.childNodes || []).filter(child => local(child) === 'cond'))
				for (const condition of conditions) {
					const delay = Number(condition.getAttribute('delay'))
					if (Number.isFinite(delay) && delay > 0) { condition.setAttribute('delay', '0'); changed = true }
				}
			}
			ancestor = ancestor.parentNode
		}
		const audioNode = elements.find(node => local(node) === 'audio' && Array.from(node.getElementsByTagName('*')).some(child => local(child) === 'spTgt' && child.getAttribute('spid') === targetSpid))
		if (audioNode) {
			const endLists = Array.from(audioNode.getElementsByTagName('*')).filter(node => local(node) === 'endCondLst')
			for (const endList of endLists) { if (endList.parentNode) { endList.parentNode.removeChild(endList); changed = true } }
		}
		return changed ? { xml: new XMLSerializer().serializeToString(doc), changed: true } : { xml: raw, changed: false }
	} catch {
		return { xml: raw, changed: false }
	}
}

function _captionTrackGuid(value, path) {
	if (value === undefined || value === null || String(value).trim() === '') return `{${crypto.randomUUID().toUpperCase()}}`
	const guid = String(value).trim()
	if (!/^\{?[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\}?$/i.test(guid)) {
		throw new Error(`${path}.id must be a GUID when provided.`)
	}
	return `{${guid.replace(/^\{|\}$/g, '').toUpperCase()}}`
}

function _replaceMediaCaptionTracks(slide, obj, tracks) {
	const previousTracks = Array.isArray(obj.options?.closedCaptionTracks) ? obj.options.closedCaptionTracks : []
	const previousRids = new Set(previousTracks.map(track => Number(track?.rId)).filter(Number.isFinite))
	slide._relsMedia = (slide._relsMedia || []).filter(rel => !previousRids.has(Number(rel?.rId)))
	delete obj.options.closedCaptionTracks
	if (!Array.isArray(tracks) || !tracks.length) return
	const serialized = []
	tracks.forEach((track, index) => {
		const rId = Number(nextRawRelationshipId(slide).slice(3))
		const language = String(track.language || track.lang || 'en-US')
		const label = String(track.label || language)
		const vtt = String(track.vtt ?? track.text ?? '')
		slide._relsMedia.push({
			path: 'preencoded.vtt',
			type: 'text/vtt',
			extn: 'vtt',
			data: `text/vtt;base64,${Buffer.from(vtt, 'utf8').toString('base64')}`,
			rId,
			Target: `../media/caption-${slide._slideNum}-${rId}.vtt`,
			isCaptionTrack: true,
		})
		serialized.push({ rId, language, label, isDefault: track.default === true, id: _captionTrackGuid(track.id, `closedCaptionTracks[${index}]`) })
	})
	obj.options.closedCaptionTracks = serialized
}

function _applyMediaOptionsPatch(slide, obj, normalizedOptionsPatch) {
	if (!normalizedOptionsPatch) return
	const optionsPatch = { ...normalizedOptionsPatch }
	const ownsCaptionTracks = Object.prototype.hasOwnProperty.call(optionsPatch, 'closedCaptionTracks')
	const captionTracks = optionsPatch.closedCaptionTracks
	delete optionsPatch.closedCaptionTracks
	if (Object.prototype.hasOwnProperty.call(optionsPatch, 'transparency')) delete obj.options._rawBlipInnerXml
	if (Object.prototype.hasOwnProperty.call(optionsPatch, 'sizing')) delete obj.options._rawBlipTailXml
	if (Object.prototype.hasOwnProperty.call(optionsPatch, 'rounding')) {
		delete obj.options._picPrstGeom
		delete obj.options._rawPicPrstGeomXml
	}
	_deepMerge(obj.options, optionsPatch)
	if (ownsCaptionTracks) _replaceMediaCaptionTracks(slide, obj, captionTracks)
}

function _removeOwnedMediaCommands(slide, obj, spid) {
	const before = (slide._animations || []).length
	slide._animations = (slide._animations || []).filter(record => !(record?._betterpptxOwnedMediaCommand === true && _isMediaAnimationRecord(record, spid, obj)))
	return before !== slide._animations.length
}

function _markOwnedMediaCommands(slide, startIndex) {
	for (const record of (slide._animations || []).slice(startIndex)) record._betterpptxOwnedMediaCommand = true
}

const MEDIA_SOURCE_PATCH_KEYS = Object.freeze(['source', 'path', 'link', 'data'])

async function _materializeAuthorizedMediaSource(source, expectedType, requestedExtn) {
	const resolved = typeof source === 'string' ? resolveGeneratedAssetRefs(source) : source
	let materialized
	if (typeof resolved === 'string' && resolved !== source && fsNode.existsSync(resolved)) {
		const bytes = await fs.readFile(resolved)
		const extn = extFromUrlOrPath(resolved, '')
		materialized = { filePath: resolved, bytes, extn, mimeType: mimeForExt(extn), source: 'authorized' }
	} else {
		materialized = await materializeSpecAssetSource({
			...(typeof source === 'string' && /^data:/i.test(source) ? { data: source }
				: typeof source === 'string' && /^https:\/\//i.test(source) ? { link: source }
					: { path: source }),
			kind: 'media replacement',
			maxBytes: Number(process.env.BETTERPPTX_SPEC_RESOLVE_MAX_MEDIA_MB || 64) * 1048576,
		})
	}
	const type = String(expectedType || 'video').toLowerCase() === 'audio' ? 'audio' : 'video'
	const detected = detectedMediaKind(materialized.bytes, materialized.mimeType)
	if (!detected || detected !== type) {
		const error = new Error(`update_media source payload is not valid ${type} content.`)
		error.code = 'MEDIA_REPLACEMENT_TYPE_MISMATCH'
		throw error
	}
	const allowed = type === 'audio' ? new Set(['mp3', 'm4a', 'wav', 'ogg', 'wma']) : new Set(['mp4', 'm4v', 'mov', 'webm', 'wmv'])
	const declared = String(requestedExtn || '').toLowerCase().replace(/^\./, '')
	const discovered = String(materialized.extn || extFromMime(materialized.mimeType, '')).toLowerCase().replace(/^\./, '')
	const extn = declared || discovered
	if (!allowed.has(extn)) {
		const error = new Error(`update_media extension .${extn || '(missing)'} is not supported for ${type}.`)
		error.code = 'MEDIA_REPLACEMENT_EXTENSION_INVALID'
		throw error
	}
	if (declared && discovered && declared !== discovered) {
		const error = new Error(`update_media declared .${declared} but the authorized source is .${discovered}.`)
		error.code = 'MEDIA_REPLACEMENT_EXTENSION_MISMATCH'
		throw error
	}
	return { ...materialized, type, extn, mimeType: mimeForExt(extn) }
}

async function _applyAtomicMediaPackagePatch(slide, obj, normalizedOptionsPatch) {
	if (!normalizedOptionsPatch || typeof normalizedOptionsPatch !== 'object') return normalizedOptionsPatch
	const patch = { ...normalizedOptionsPatch }
	const sourceKeys = MEDIA_SOURCE_PATCH_KEYS.filter(key => Object.prototype.hasOwnProperty.call(patch, key))
	if (sourceKeys.length > 1) {
		const error = new Error(`update_media.optionsPatch accepts exactly one source lane; received ${sourceKeys.join(', ')}.`)
		error.code = 'ASSET_SOURCE_AMBIGUOUS'
		throw error
	}
	const ownsSource = sourceKeys.length === 1
	const ownsCover = Object.prototype.hasOwnProperty.call(patch, 'cover')
	const ownsType = Object.prototype.hasOwnProperty.call(patch, 'type')
	const ownsExtn = Object.prototype.hasOwnProperty.call(patch, 'extn')
	if (!ownsSource && !ownsCover && !ownsType && !ownsExtn) return patch

	const currentType = String(obj.mtype || obj.options?.type || 'video').toLowerCase()
	const requestedType = patch.type == null ? currentType : String(patch.type).toLowerCase()
	if ((ownsType || ownsExtn) && !ownsSource && requestedType !== currentType) {
		throw new Error('update_media type changes require an authorized replacement source in the same atomic patch.')
	}
	if (ownsExtn && !ownsSource && patch.extn != null && String(patch.extn).toLowerCase() !== String(obj.options?.extn || '').toLowerCase()) {
		throw new Error('update_media extension changes require an authorized replacement source in the same atomic patch.')
	}
	if (ownsSource && (patch[sourceKeys[0]] === null || patch[sourceKeys[0]] === '')) {
		const error = new Error('update_media source cannot be cleared while retaining the media object; replace it or delete the media object.')
		error.code = 'MEDIA_SOURCE_RESET_REQUIRES_OBJECT_REMOVAL'
		throw error
	}
	if (ownsSource && ((currentType === 'online') !== (requestedType === 'online'))) {
		const error = new Error('update_media cannot change between online and packaged media in place; replace the media object.')
		error.code = 'MEDIA_TOPOLOGY_CHANGE_REQUIRES_RECREATE'
		throw error
	}

	const rels = Array.isArray(slide._relsMedia) ? slide._relsMedia : []
	let sourcePlan = null
	if (ownsSource && requestedType === 'online') {
		const value = String(patch[sourceKeys[0]])
		if (!/^https:\/\//i.test(value)) throw new Error('update_media online sources must use HTTPS.')
		const rel = rels.find(item => Number(item?.rId) === Number(obj.mediaRid))
		if (!rel) throw new Error('update_media online relationship is missing.')
		sourcePlan = { mode: 'online', value, rel, authored: publicSourceDescriptorForOptions({ source: value }, 'media') }
	} else if (ownsSource) {
		const value = patch[sourceKeys[0]]
		const materialized = await _materializeAuthorizedMediaSource(value, requestedType, patch.extn)
		const primary = rels.find(item => Number(item?.rId) === Number(obj.mediaRid))
		const companion = rels.find(item => Number(item?.rId) === Number(obj.mediaCompanionRid ?? (Number(obj.mediaRid) + 1)))
		if (!primary || !companion) throw new Error('update_media packaged media relationships are incomplete.')
		const existingTarget = String(primary.Target || `../media/media-${slide._slideNum}-${obj.mediaRid}`)
		const stem = existingTarget.includes('.') ? existingTarget.slice(0, existingTarget.lastIndexOf('.')) : existingTarget
		sourcePlan = {
			mode: 'packaged', value, materialized, primary, companion,
			target: `${stem}.${materialized.extn}`,
			authored: publicSourceDescriptorForOptions({ [sourceKeys[0]]: value }, 'media'),
		}
	}

	let coverPlan = null
	if (ownsCover) {
		const resetToDefault = patch.cover === null
		const data = resetToDefault
			? await defaultMediaCoverDataUri()
			: await materializeMediaCoverDataUri(patch.cover)
		const comma = data.indexOf(',')
		const bytes = Buffer.from(data.slice(comma + 1), 'base64')
		const extn = canonicalImageExtension(inferImageExtension('', bytes, ''))
		const rel = rels.find(item => Number(item?.rId) === Number(obj.mediaCoverRid ?? (Number(obj.mediaRid) + (currentType === 'online' ? 1 : 2))))
		if (!rel) throw new Error('update_media cover relationship is missing.')
		const existingTarget = String(rel.Target || `../media/image-${slide._slideNum}-${rel.rId}`)
		const stem = existingTarget.includes('.') ? existingTarget.slice(0, existingTarget.lastIndexOf('.')) : existingTarget
		coverPlan = {
			data,
			extn,
			rel,
			target: `${stem}.${extn}`,
			authored: resetToDefault ? null : publicSourceDescriptorForOptions({ source: patch.cover }, 'media cover'),
		}
	}

	if (sourcePlan?.mode === 'online') {
		sourcePlan.rel.Target = sourcePlan.value
		sourcePlan.rel.path = sourcePlan.value
		sourcePlan.rel.data = 'dummy'
		sourcePlan.rel.mediaRelationshipRole = 'online'
		obj.media = sourcePlan.value
		obj.mtype = 'online'
		obj.options.link = sourcePlan.value
		delete obj.options.path
		delete obj.options.data
		obj.options.type = 'online'
		obj.options.extn = 'mp4'
		obj.options._authoredMediaSource = sourcePlan.authored
	} else if (sourcePlan?.mode === 'packaged') {
		for (const [rel, role] of [[sourcePlan.primary, 'primary'], [sourcePlan.companion, 'companion']]) {
			rel.path = sourcePlan.materialized.filePath || `preencoded.${sourcePlan.materialized.extn}`
			rel.data = sourcePlan.materialized.filePath ? '' : `data:${sourcePlan.materialized.mimeType};base64,${Buffer.from(sourcePlan.materialized.bytes).toString('base64')}`
			rel.extn = sourcePlan.materialized.extn
			rel.type = sourcePlan.materialized.mimeType
			rel.Target = sourcePlan.target
			rel.isDuplicate = false
			rel.mediaRelationshipRole = role
		}
		obj.media = sourcePlan.materialized.filePath || `preencoded.${sourcePlan.materialized.extn}`
		obj.mtype = sourcePlan.materialized.type
		obj.options.type = sourcePlan.materialized.type
		obj.options.extn = sourcePlan.materialized.extn
		if (sourcePlan.materialized.filePath) {
			obj.options.path = sourcePlan.materialized.filePath
			delete obj.options.data
		} else {
			obj.options.data = `data:${sourcePlan.materialized.mimeType};base64,${Buffer.from(sourcePlan.materialized.bytes).toString('base64')}`
			delete obj.options.path
		}
		delete obj.options.link
		obj.options._authoredMediaSource = sourcePlan.authored
	}
	if (coverPlan) {
		coverPlan.rel.path = `preencoded.${coverPlan.extn}`
		coverPlan.rel.data = coverPlan.data
		coverPlan.rel.extn = coverPlan.extn
		coverPlan.rel.type = mimeForExt(coverPlan.extn)
		coverPlan.rel.Target = coverPlan.target
		coverPlan.rel.isDuplicate = false
		coverPlan.rel.mediaRelationshipRole = 'cover'
		obj.options.cover = coverPlan.data
		if (coverPlan.authored === null) delete obj.options._authoredMediaCover
		else obj.options._authoredMediaCover = coverPlan.authored
	}
	for (const key of [...MEDIA_SOURCE_PATCH_KEYS, 'type', 'extn', 'cover']) delete patch[key]
	return patch
}

async function handleUpdateMedia(args) {
	if (Object.prototype.hasOwnProperty.call(args || {}, 'mediaCommandTiming')) {
		const commandState = validateMediaCommandTiming(args.mediaCommandTiming, 'update_media.mediaCommandTiming')
		args = { ...args }
		delete args.mediaCommandTiming
		if (commandState === null) args.command = null
		else if (commandState) {
			args.command = commandState.command
			if (commandState.trigger !== undefined) args.trigger = commandState.trigger
			if (commandState.delayMs !== undefined) args.delay = commandState.delayMs
			if (commandState.durationMs !== undefined) args.duration = commandState.durationMs
			if (commandState.replaceExistingCommands !== undefined) args.replaceExistingCommands = commandState.replaceExistingCommands
			if (commandState.preserveExistingTiming !== undefined) args.preserveExistingTiming = commandState.preserveExistingTiming
		}
	}
	const entry = getDeck(args.deckId)
	const slide = getSlide(args.deckId, args.slideIndex)
	const { obj, index, rawIndex } = _resolveTypedShape(slide, args.target, ['media'], 'update_media')
	if (!obj.options) obj.options = {}
	const normalizedOptionsPatch = validateMediaFormatOptions(args.optionsPatch, 'update_media.optionsPatch')
	if (String(obj.mtype || obj.options.type || '').toLowerCase() === 'audio'
		&& normalizedOptionsPatch?.showWhenStopped !== undefined
		&& normalizedOptionsPatch.showWhenStopped !== null) {
		throw new Error('update_media.optionsPatch.showWhenStopped is only for video or online media; PowerPoint does not retain it for audio.')
	}
	const residualOptionsPatch = await _applyAtomicMediaPackagePatch(slide, obj, normalizedOptionsPatch)
	_applyMediaOptionsPatch(slide, obj, residualOptionsPatch)
	const avatarFrame = await _applyAcceptedAvatarFrameContract(entry, slide, obj, args)
	// Maintainer-only replacement for an imported recorded-media payload.  This
	// changes the engine media relationship data, while leaving the imported
	// shape XML, p15 narration marker, raw timing, ink package, and laser trace
	// untouched.  It is deliberately not available through the public black-box
	// surface because that surface must never accept local filesystem paths.
	const replacementPathArg = args.replacementMediaPath ?? args.mediaPath
	let replacementMedia = false
	let replacementCoverData = args.coverDataUri || args.cover || null
	if (replacementPathArg !== undefined) {
		if (isPublicBlackBoxMode()) {
			const err = new Error('update_media media replacement is maintainer-only.')
			err.code = 'MEDIA_REPLACEMENT_NOT_PUBLIC'
			throw err
		}
		const replacementPath = resolveGeneratedAssetRefs(replacementPathArg)
		if (typeof replacementPath !== 'string' || !fsNode.existsSync(replacementPath)) {
			const err = new Error(`update_media: replacement media was not found: ${replacementPathArg}`)
			err.code = 'MEDIA_REPLACEMENT_NOT_FOUND'
			throw err
		}
		const extn = (path.extname(replacementPath).replace(/^\./, '') || (obj.mtype === 'audio' ? 'mp3' : 'mp4')).toLowerCase()
		const mediaType = mimeForExt(extn)
		const expectedKind = obj.mtype === 'audio' ? 'audio' : 'video'
		if (!mediaType.startsWith(`${expectedKind}/`)) throw new Error(`update_media: .${extn} is not a supported ${expectedKind} payload.`)
		const rid = Number(obj.mediaRid)
		const companionRid = Number(obj.mediaCompanionRid ?? (rid + 1))
		const coverRid = Number(obj.mediaCoverRid ?? (rid + 2))
		const mediaRels = Array.isArray(slide._relsMedia) ? slide._relsMedia : []
		const payloadRels = mediaRels.filter(rel => Number(rel?.rId) === rid || Number(rel?.rId) === companionRid)
		if (payloadRels.length < 2) {
			const err = new Error('update_media: imported media payload relationships are incomplete.')
			err.code = 'MEDIA_REPLACEMENT_RELATIONSHIPS_MISSING'
			throw err
		}
		const existingMediaTarget = String(payloadRels[0]?.Target || `../media/media-${slide._slideNum}-${rid}`)
		const mediaTargetStem = existingMediaTarget.includes('.') ? existingMediaTarget.slice(0, existingMediaTarget.lastIndexOf('.')) : existingMediaTarget
		const replacementTarget = `${mediaTargetStem}.${extn}`
		for (const rel of payloadRels) {
			rel.path = replacementPath
			rel.data = ''
			rel.extn = extn
			rel.type = mediaType
			rel.Target = replacementTarget
			rel.isDuplicate = false
			rel.mediaRelationshipRole = Number(rel.rId) === rid ? 'primary' : 'companion'
		}
		obj.media = replacementPath
		obj.options.path = replacementPath
		delete obj.options.data
		delete obj.options.link
		obj.options.type = obj.mtype
		obj.options.extn = extn
		if (replacementCoverData) {
			const coverData = replacementCoverData
			if (typeof coverData !== 'string' || !coverData.toLowerCase().includes('base64,')) {
				throw new Error('update_media: cover must be a base64 data URI.')
			}
			const coverRel = mediaRels.find(rel => Number(rel?.rId) === coverRid && String(rel?.type || '').toLowerCase().includes('image'))
			if (!coverRel) {
				const err = new Error('update_media: imported media cover relationship is missing.')
				err.code = 'MEDIA_REPLACEMENT_COVER_RELATIONSHIP_MISSING'
				throw err
			}
			const comma = coverData.indexOf(',')
			const coverHeader = comma >= 0 ? coverData.slice(0, comma) : ''
			const coverBytes = Buffer.from(comma >= 0 ? coverData.slice(comma + 1) : '', 'base64')
			const coverExtn = inferImageExtension(coverHeader.replace(/^data:/i, '').split(';', 1)[0], coverBytes, '')
			const coverType = mimeForExt(coverExtn)
			if (!coverExtn || !coverType.startsWith('image/')) throw new Error('update_media: cover payload is not a supported image.')
			coverRel.path = `preencoded.${coverExtn}`
			coverRel.data = coverData
			coverRel.extn = coverExtn === 'jpg' ? 'jpeg' : coverExtn
			coverRel.type = coverType
			const existingCoverTarget = String(coverRel.Target || `../media/image-${slide._slideNum}-${coverRid}`)
			const coverTargetStem = existingCoverTarget.includes('.') ? existingCoverTarget.slice(0, existingCoverTarget.lastIndexOf('.')) : existingCoverTarget
			coverRel.Target = `${coverTargetStem}.${coverExtn === 'jpg' ? 'jpeg' : coverExtn}`
			coverRel.isDuplicate = false
			coverRel.mediaRelationshipRole = 'cover'
			obj.options.cover = coverData
		}
		// Imported Record Studio shapes keep their native timing/annotation XML,
		// but their old media fill may still stretch a replacement video. Apply
		// the same aspect-preserving cover crop and round window used for newly
		// authored avatar media.
		const geometry = await prepareAvatarVideoForPlacement({ normalizedVideoPath: replacementPath, coverDataUri: replacementCoverData }, args)
		if (geometry.videoWidth && geometry.videoHeight) {
			obj.options.sizing = { type: 'cover', w: obj.options.w, h: obj.options.h }
			obj.options._sizingSourceW = geometry.videoWidth
			obj.options._sizingSourceH = geometry.videoHeight
			// The imported shape may carry a raw stretch tail from the old media;
			// drop only that fill tail so the serializer can emit the new srcRect.
			delete obj.options._rawBlipTailXml
		}
		obj.options.rounding = args.rounding ?? args.optionsPatch?.rounding ?? true
		replacementMedia = true
	}
	const playback = args.playback || {}
	// Preserve the Record Studio avatar window when an imported/generated deck is
	// round-tripped through update_media. Imported media may not expose its
	// ellipse flag in the object model, so carry an explicit authoring patch into
	// the serializer instead of silently reverting to a rectangular frame.
	if (String(obj.mtype || '').toLowerCase() === 'video' && args.rounding !== undefined) {
		obj.options.rounding = Boolean(args.rounding)
	}
	const ownsInteractivePlayback = Object.prototype.hasOwnProperty.call(args, 'interactivePlayback')
		|| Object.prototype.hasOwnProperty.call(playback, 'interactivePlayback')
		|| Object.prototype.hasOwnProperty.call(normalizedOptionsPatch || {}, 'interactivePlayback')
	const interactivePlayback = Object.prototype.hasOwnProperty.call(args, 'interactivePlayback')
		? args.interactivePlayback
		: Object.prototype.hasOwnProperty.call(playback, 'interactivePlayback')
			? playback.interactivePlayback
			: normalizedOptionsPatch?.interactivePlayback
	if (ownsInteractivePlayback && interactivePlayback !== null) obj.options.interactivePlayback = !!interactivePlayback
	let interactiveTimingAdded = false
	let interactiveTimingRemoved = false
	if (ownsInteractivePlayback && interactivePlayback !== true && typeof slide._rawTimingXml === 'string' && slide._rawTimingXml.trim()) {
		const removed = _removeRawInteractiveMediaTiming(slide, obj.options.spid ?? (rawIndex + 2))
		if (removed.removed) { slide._rawTimingXml = removed.xml; interactiveTimingRemoved = true }
	}
	if (obj.options.interactivePlayback === true && typeof slide._rawTimingXml === 'string' && slide._rawTimingXml.trim()) {
		const ensured = _ensureRawInteractiveMediaTiming(slide, obj.options.spid ?? (rawIndex + 2))
		if (ensured.added) { slide._rawTimingXml = ensured.xml; interactiveTimingAdded = true }
	}
	if (obj.options.interactivePlayback === true && typeof slide._rawTimingXml === 'string' && slide._rawTimingXml.trim()) {
		const narration = (slide._slideObjects || []).find(item => item?._type === 'media' && String(item.mtype || '').toLowerCase() === 'audio' && item.options?.isNarration === true)
		const audioSpid = Number(narration?.options?.spid)
		if (Number.isFinite(audioSpid)) {
			const narrationClock = _ensureRawNarrationStartsImmediately(slide, audioSpid)
			if (narrationClock.changed) slide._rawTimingXml = narrationClock.xml
		}
	}
	const volume = _normalizeMediaVolume(args.volume ?? playback.volume)
	if (volume !== undefined) obj.options.mediaVolume = volume
	const ownsCommandPatch = Object.prototype.hasOwnProperty.call(args, 'command')
		|| Object.prototype.hasOwnProperty.call(args, 'mediaCommand')
		|| Object.prototype.hasOwnProperty.call(playback, 'command')
		|| Object.prototype.hasOwnProperty.call(playback, 'mediaCommand')
	const command = args.command ?? playback.command ?? args.mediaCommand ?? playback.mediaCommand
	let animationAdded = false
	let replacedExistingCommands = false
	const spid = obj.options.spid ?? (rawIndex + 2)
	if (ownsCommandPatch && (command === null || command === '')) {
		replacedExistingCommands = _removeOwnedMediaCommands(slide, obj, spid)
		obj.options._authoredMediaCommands = []
	}
	if (command || args.addCommand || playback.addCommand) {
		if (args.replaceExistingCommands === true || playback.replaceExistingCommands === true) {
			const before = (slide._animations || []).length
			slide._animations = (slide._animations || []).filter(record => !_isMediaAnimationRecord(record, spid, obj))
			replacedExistingCommands = before !== slide._animations.length
			obj.options._authoredMediaCommands = []
		}
		const mediaCommand = validateAnimationFormatOptions({ type: 'media', mediaCommand: String(command || 'playFrom(0.0)') }, 'update_media.command').mediaCommand
		const effect = args.effect || playback.effect || (mediaCommand === 'stop' ? 'mediastop' : mediaCommand === 'togglePause' ? 'mediapause' : 'mediaplay')
		const semanticCommand = normalizeAnimation(validateAnimationFormatOptions({
			type: 'media',
			effect,
			mediaCommand,
			trigger: args.trigger ?? playback.trigger ?? 'onClick',
			delay: args.delay ?? playback.delay ?? 0,
			duration: args.duration ?? playback.duration ?? 1,
			spid,
		}, 'update_media.command'))
		const animationCountBefore = (slide._animations || []).length
		slide.addAnimation(obj, semanticCommand)
		_markOwnedMediaCommands(slide, animationCountBefore)
		if (!Array.isArray(obj.options._authoredMediaCommands)) obj.options._authoredMediaCommands = []
		obj.options._authoredMediaCommands.push({ ...semanticCommand })
		animationAdded = true
		if (slide._rawTimingXml && args.preserveExistingTiming !== true && playback.preserveExistingTiming !== true) delete slide._rawTimingXml
	}
	return {
		ok: true,
		slideIndex: args.slideIndex,
		index,
		rawIndex,
		objectName: obj.options?.objectName,
		interactivePlayback: obj.options.interactivePlayback,
		mediaVolume: obj.options.mediaVolume,
		replacementMedia,
		animationAdded,
		interactiveTimingAdded,
		interactiveTimingRemoved,
		avatarFrameContract: avatarFrame.applied ? 'ellipse-centered-cover-v1' : undefined,
		avatarDurationMs: avatarFrame.durationMs || undefined,
		advanceAfterTime: avatarFrame.advanceAfterTime || undefined,
		duplicatePresenterVisualsRemoved: avatarFrame.duplicatePresenterVisualsRemoved || undefined,
		replacedExistingCommands,
	}
}

// Extract & apply animations. The evolved library rejects inline `animation`
// on object options — animations must be applied via slide.addAnimation(target, props).
// Accepts either a single AnimationProps or an array of them. Returns the lifted animations.
// Friendly aliases → evolved-library registry effect names (lowercase).
// Lets MCP callers use familiar names (fadeIn/fadeOut/swing/grow) without
// memorising the registry's exact spelling. Anything not in the alias map is
// passed through (lowercased) so registry-valid names always work.
const EFFECT_ALIASES = {
	fadein: 'fade',
	fadeout: 'fade',
	fade: 'fade',
	appear: 'appear',
	wipe: 'wipe',
	fly: 'fly',
	flyin: 'fly',
	flyout: 'fly',
	zoom: 'zoom',
	zoomin: 'zoom',
	zoomout: 'zoom',
	spin: 'spin',
	swivel: 'swivel',
	pulse: 'pulse',
	bounce: 'bounce',
	wheel: 'wheel',
	split: 'split',
	peek: 'peek',
	crawl: 'crawl',
	lightspeed: 'lightspeed',
	riseup: 'riseup',
	grow: 'verticalgrow',
	shrink: 'verticalgrow',
	growshrink: 'growshrink',
	float: 'float',
	floatin: 'floatIn',
	floatout: 'floatOut',
	teeter: 'teeter',
	flash: 'flashOnce',
	flicker: 'flicker',
}

const DIRECTIONAL_EFFECTS = new Set([
	'crawl',
	'fly',
	'peek',
	'strips',
	'stretch',
	'wipe',
])

const DIRECTION_ALIASES = {
	fromleft: 'fromLeft',
	fromright: 'fromRight',
	fromtop: 'fromTop',
	frombottom: 'fromBottom',
	toleft: 'toLeft',
	toright: 'toRight',
	totop: 'toTop',
	tobottom: 'toBottom',
	left: 'left',
	right: 'right',
	up: 'top',
	top: 'top',
	down: 'bottom',
	bottom: 'bottom',
}

function normalizeDirectionAlias(direction, type, effect) {
	if (typeof direction !== 'string') return direction
	if (!DIRECTIONAL_EFFECTS.has(effect)) return direction
	const key = direction.replace(/[\s_-]+/g, '').toLowerCase()
	const alias = DIRECTION_ALIASES[key]
	if (!alias) return direction
	if (/^(from|to)[A-Z]/.test(alias)) return alias
	const edge = alias[0].toUpperCase() + alias.slice(1)
	return String(type).toLowerCase() === 'exit' ? `to${edge}` : `from${edge}`
}

// The authoritative set of animation effects pptxgen's frozen ANIMATION_REGISTRY_MERGED can
// build (lowercased). An effect NOT in here — e.g. a world temperament value like 'none' or
// 'gentle', or an author typo — used to pass straight through normalizeAnimation and crash at
// SAVE with `Animation "X" not found in registry` (a class of bug dry-run never catches, since
// dry-run does no pptxgen serialization). We validate here and coerce the unknown to a safe,
// type-appropriate default so an invalid effect degrades gracefully instead of breaking export.
const VALID_ANIMATION_EFFECTS = new Set([
	'appear', 'arcdown', 'arcleft', 'arcright', 'arcup', 'bean', 'blast', 'blinds', 'boldflash', 'boldreveal',
	'boomerang', 'bounce', 'bounceleft', 'bounceright', 'box', 'brushcolor', 'brushonunderline', 'buzzsaw',
	'centerrevolve', 'changefillcolor', 'changefont', 'changefontcolor', 'changefontsize', 'changefontstyle',
	'changelinecolor', 'checkerboard', 'circle', 'circlepath', 'colorreveal', 'colorblend', 'colorwave',
	'complementarycolor', 'complementarycolor2', 'contrastingcolor', 'crawl', 'credits', 'crescentmoon',
	'curvedown', 'curveup', 'curvedsquare', 'curvedx', 'curvyleft', 'curvyright', 'curvystar', 'darken',
	'decayingwave', 'desaturate', 'diagonaldownright', 'diagonalupright', 'diamond', 'diamondpath', 'dissolve',
	'down', 'drop', 'easein', 'equaltriangle', 'expand', 'fade', 'fadedswivel', 'fadedzoom', 'figure8four',
	'flashonce', 'flicker', 'flip', 'float', 'floatin', 'floatout', 'floatinexit', 'floatoutentrance', 'fly',
	'fold', 'football', 'funnel', 'glide', 'growandturn', 'growshrink', 'growwithcolor', 'heart', 'heartbeat',
	'hexagon', 'horizontalfigure8', 'invertedsquare', 'invertedtriangle', 'left', 'lighten', 'lightspeed',
	'loopdeloop', 'mediapause', 'mediaplay', 'mediastop', 'neutron', 'objectcolor', 'octagon', 'parallelogram',
	'pause', 'peanut', 'peek', 'pentagon', 'pinwheel', 'play', 'plus', 'pluspath', 'pointystar', 'pulse',
	'randombars', 'randomeffects', 'right', 'righttriangle', 'riseup', 'scurve1', 'scurve2', 'shimmer',
	'sinewave', 'sling', 'spin', 'spinner', 'spiral', 'spiralleft', 'spiralright', 'split', 'spring',
	'squarepath', 'stairsdown', 'stop', 'stretch', 'stretchy', 'strips', 'styleemphasis', 'swish', 'swivel',
	'swoosh', 'teardrop', 'teeter', 'thinline', 'thread', 'togglepause', 'transparency', 'trapezoid', 'turndown',
	'turnright', 'turnup', 'turnupright', 'underline', 'unfold', 'up', 'verticalfigure8', 'verticalgrow',
	'wave', 'wavepath', 'wedge', 'wheel', 'whip', 'wipe', 'zigzag', 'zip', 'zoom',
	// Native 3D model animations — valid via the runtime's SEPARATE 3D builder (not the standard
	// registry), so they must be allowlisted here or the guard would wrongly coerce them.
	// 'playscene' plays a rigged model's selected embedded ("Scene") clip.
	'arrive', 'turntable', 'swing', 'jumpandturn', 'leave', 'playscene',
])

function safeAnimationEffectFor(type) {
	// entrance/exit → a gentle fade (the most restrained valid entrance); emphasis → pulse.
	return String(type || '').toLowerCase() === 'emphasis' ? 'pulse' : 'fade'
}

// MOTION-PATH vocabulary guard. The merged registry lookup is category-blind, so a motion
// step naming a NON-path effect ("curveDown" is a classic EXIT) would silently become that
// other class — the shape would vanish instead of travel. Paths must resolve INSIDE the
// motion-path category: natural aliases first, then the real path keys; anything else is
// coerced to a neutral straight line WITH a visible coercion record. Custom paths
// (motionPathData / points) bypass the vocabulary entirely.
const MOTION_PATH_ALIASES = {
	curveup: 'arcup', curvedown: 'arcdown', curve: 'scurve1', arc: 'arcup',
	circle: 'circlepath', square: 'squarepath', diamond: 'diamondpath', plus: 'pluspath',
	star: '5pointstar', figure8: 'verticalfigure8', wave: 'wavepath', spiral: 'spiralleft',
	bounce: 'bounceright', stairs: 'stairsdown', triangle: 'equaltriangle',
	line: 'right', lineright: 'right', lineleft: 'left', lineup: 'up', linedown: 'down',
}
// EMPHASIS vocabulary guard (same class-crossing family as motion paths): PowerPoint's
// emphasis menu is the registry's fixed-'emph' set below. A class-flexible effect asked
// as emphasis can silently render as another class — "flashOnce" hardcodes entr|exit in
// its builder, so an emphasis cue made the target VANISH. Natural aliases keep the
// author's intent (flashOnce → flicker = blink for attention); anything else coerces to
// the restrained 'pulse' WITH a visible record.
const EMPHASIS_ALIASES = {
	flashonce: 'flicker', flash: 'boldflash', grow: 'growshrink', shrink: 'growshrink',
	color: 'colorwave', brightness: 'lighten', bright: 'lighten', dim: 'darken', blink: 'flicker',
	bold: 'boldflash', shake: 'teeter', wiggle: 'teeter', wobble: 'teeter',
}
const VALID_EMPHASIS_EFFECTS = new Set([
	'turntable', 'swing', 'jumpandturn', 'shimmer', 'changefillcolor', 'changefont', 'changefontcolor',
	'changefontsize', 'changefontstyle', 'growshrink', 'changelinecolor', 'spin', 'transparency',
	'boldflash', 'blast', 'boldreveal', 'brushcolor', 'brushonunderline', 'underline', 'colorblend',
	'objectcolor', 'colorwave', 'complementarycolor', 'complementarycolor2', 'contrastingcolor',
	'darken', 'desaturate', 'pulse', 'flicker', 'growwithcolor', 'lighten', 'styleemphasis',
	'teeter', 'verticalgrow', 'wave',
])
const VALID_MOTION_PATHS = new Set([
	'circlepath', 'righttriangle', 'diamondpath', 'hexagon', '5pointstar', 'crescentmoon', 'squarepath',
	'trapezoid', 'heart', 'octagon', '6pointstar', 'football', 'equaltriangle', 'parallelogram', 'pentagon',
	'4pointstar', '8pointstar', 'teardrop', 'pointystar', 'curvedsquare', 'curvedx', 'verticalfigure8',
	'curvystar', 'loopdeloop', 'buzzsaw', 'horizontalfigure8', 'peanut', 'figure8four', 'neutron', 'swoosh',
	'bean', 'pluspath', 'invertedtriangle', 'invertedsquare', 'left', 'turnright', 'arcdown', 'zigzag',
	'scurve2', 'sinewave', 'bounceleft', 'down', 'turnup', 'arcup', 'heartbeat', 'spiralright', 'wavepath',
	'curvyleft', 'diagonaldownright', 'turndown', 'arcleft', 'funnel', 'spring', 'bounceright', 'spiralleft',
	'diagonalupright', 'turnupright', 'arcright', 'scurve1', 'decayingwave', 'curvyright', 'stairsdown',
	'up', 'right',
])

// TEAMWORK — an effect coercion changes what the AI ASKED FOR (a typo'd effect silently became
// a fade), so it must be visible in the tool RESPONSE, not only in the server log. normalize-
// Animation runs deep inside handlers with no response context; coercions accumulate here and
// the response-owning handlers drain them into their warnings (tool calls are serialized by the
// deck-mutation lock, so a module-level collector cannot interleave).
let _animationCoercions = []
export function drainAnimationCoercions() {
	const raw = _animationCoercions
	_animationCoercions = []
	if (!raw.length) return []
	const byKey = new Map()
	for (const c of raw) {
		const key = `${c.requestedEffect}|${c.type}|${c.coercedTo}`
		const entry = byKey.get(key) || {
			code: 'ANIMATION_EFFECT_COERCED',
			requestedEffect: c.requestedEffect,
			coercedTo: c.coercedTo,
			type: c.type,
			count: 0,
			message: `Animation effect "${c.requestedEffect}" is not a valid effect; coerced to "${c.coercedTo}" so the deck still saves. If you meant a different effect, pick one from the open animation palette (betterpptx.options catalog) and re-commit.`,
		}
		entry.count += 1
		byKey.set(key, entry)
	}
	return [...byKey.values()]
}

export function normalizeAnimation(a) {
	if (!a || typeof a !== 'object') return a
	const out = { ...a }
	// Public JSON-spec uses the explicit millisecond aliases; the native library
	// carrier remains duration/delay. Normalize once so no timing slider is lost
	// when an animation is lifted from content or a timeline.
	if (out.duration === undefined && out.durationMs !== undefined) out.duration = out.durationMs
	if (out.delay === undefined && out.delayMs !== undefined) out.delay = out.delayMs
	delete out.durationMs
	delete out.delayMs
	if (typeof out.effect === 'string') {
		const k = out.effect.toLowerCase()
		out.effect = EFFECT_ALIASES[k] || k
		// Guard the whole "effect not found in registry" class: coerce an unknown effect to a
		// safe default rather than letting pptxgen throw at save. Motion paths carry the path in
		// motionPath (not effect), so only validate when we actually have an effect string.
		const canon = String(out.effect).toLowerCase()
		const isMotion = String(out.type || '').toLowerCase() === 'motion' || String(out.type || '').toLowerCase() === 'path'
		if (canon && !isMotion && !canon.startsWith('media') && !VALID_ANIMATION_EFFECTS.has(canon)) {
			const safe = safeAnimationEffectFor(out.type)
			try { logEvent('animation.effect.coerced', { requestedEffect: out.effect, coercedTo: safe, type: out.type || null }) } catch { /* logging is best-effort */ }
			_animationCoercions.push({ requestedEffect: out.effect, coercedTo: safe, type: out.type || null })
			out.effect = safe
		}
	}
	// Emphasis steps: keep the effect INSIDE the emphasis category. A class-flexible
	// name asked as emphasis can render as another class (flashOnce's builder hardcodes
	// entr|exit → the "emphasized" shape would VANISH). Aliases preserve intent; unknowns
	// coerce to the restrained pulse with a visible record.
	if (String(out.type || '').toLowerCase() === 'emphasis' && typeof out.effect === 'string' && out.effect) {
		const emphKey = out.effect.toLowerCase().replace(/[\s-]+/g, '')
		// 3D model animations render through the separate native-3D builder (class handled
		// there), so the 3D vocabulary is exempt from the 2D emphasis-category guard.
		const is3D = ['arrive', 'leave', 'turntable', 'swing', 'jumpandturn', 'playscene'].includes(emphKey)
		if (!is3D && !VALID_EMPHASIS_EFFECTS.has(emphKey)) {
			const aliased = EMPHASIS_ALIASES[emphKey]
			if (aliased) {
				out.effect = aliased
			} else {
				try { logEvent('animation.effect.coerced', { requestedEffect: out.effect, coercedTo: 'pulse', type: 'emphasis' }) } catch { /* logging is best-effort */ }
				_animationCoercions.push({ requestedEffect: out.effect, coercedTo: 'pulse', type: 'emphasis' })
				out.effect = 'pulse'
			}
		}
	}
	// Motion steps: keep the path INSIDE the motion-path category (aliases → real keys);
	// an unknown path coerces to a neutral straight line with a visible record instead of
	// silently resolving to a same-named effect of another class (curveDown = an EXIT).
	const isMotionType = ['motion', 'path'].includes(String(out.type || '').toLowerCase())
	if (isMotionType && typeof out.motionPath === 'string' && !out.motionPathData && !out.points) {
		const pathKey = out.motionPath.toLowerCase().replace(/[\s-]+/g, '')
		const resolved = VALID_MOTION_PATHS.has(pathKey) ? pathKey : MOTION_PATH_ALIASES[pathKey]
		if (resolved) {
			out.motionPath = resolved
		} else {
			try { logEvent('animation.motionPath.coerced', { requestedMotionPath: out.motionPath, coercedTo: 'right' }) } catch { /* logging is best-effort */ }
			_animationCoercions.push({ requestedEffect: `motionPath:${out.motionPath}`, coercedTo: 'right (straight line)', type: 'motion' })
			out.motionPath = 'right'
		}
	}
	out.direction = normalizeDirectionAlias(out.direction, out.type, out.effect)
	return out
}

function liftAnimations(opts) {
	if (!opts || opts.animation === undefined) return { anims: [], cleaned: opts }
	const cleaned = { ...opts }
	const raw = Array.isArray(opts.animation) ? opts.animation : [opts.animation]
	const anims = raw.map((item, index) => normalizeAnimation(validateAnimationFormatOptions(item, `animation[${index}]`)))
	delete cleaned.animation
	return { anims, cleaned }
}

function _isPlainObject(value) {
	return value && typeof value === 'object' && !Array.isArray(value)
}

function normalizeRuntimeRichText(text, path = 'text') {
	if (!Array.isArray(text)) return text
	return text.map((item, index) => {
		if (!item || typeof item !== 'object' || Array.isArray(item)) return item
		const options = item.options === undefined
			? undefined
			: normalizeRichRunOptions(item.options, `${path}[${index}].options`, { text: item.text })
		if (options?.softBreakBefore === true && index === 0) options.standaloneBreakParagraph = true
		return { ...item, ...(options !== undefined ? { options } : {}) }
	})
}

function normalizeVisualOptions(opts, path = 'options', currentOptions = null) {
	if (!opts || typeof opts !== 'object' || Array.isArray(opts)) return opts
	let out = _deepCloneData(opts)
	Object.assign(out, normalizeInternalAccessibilityMetadata(out, path))
	if (Array.isArray(out.text)) out.text = normalizeRuntimeRichText(out.text, `${path}.text`)
	const topLevelRunInput = {}
	for (const key of ['fontFace', 'fontFaceComplexScript', 'fontSize', 'color', 'bold', 'italic', 'baseline', 'rtl', 'softBreakBefore', 'field', 'hyperlink']) {
		if (!Object.prototype.hasOwnProperty.call(out, key)) continue
		if (key === 'color' && out[key] !== null && typeof out[key] !== 'string') continue
		topLevelRunInput[key] = out[key]
	}
	if (Object.keys(topLevelRunInput).length) {
		const normalized = normalizeRichRunOptions(topLevelRunInput, path)
		for (const key of Object.keys(topLevelRunInput)) out[key] = normalized[key]
	}
	if (Object.prototype.hasOwnProperty.call(out, 'pictureStyle')) out.pictureStyle = normalizePictureStyle(out.pictureStyle, `${path}.pictureStyle`)
	if (Object.prototype.hasOwnProperty.call(out, 'sizing')) out.sizing = normalizeImageSizing(out.sizing, `${path}.sizing`)
	if (Object.prototype.hasOwnProperty.call(out, 'effects')) {
		if (out.effects == null || (Array.isArray(out.effects) && out.effects.length === 0)) {
			for (const key of ['shadow', 'glow', 'reflection', 'softEdges', 'blur', 'fillOverlay']) out[key] = null
		} else if (!Array.isArray(out.effects)) {
			throw new Error(`${path}.effects must be an array, null, or omitted.`)
		} else {
			out = applyEffectsArray(out, out.effects)
		}
		delete out.effects
	}
	if (out.shadow !== undefined) out.shadow = normalizeShadow(out.shadow)
	if (out.glow !== undefined) out.glow = normalizeGlow(out.glow)
	if (out.reflection !== undefined) out.reflection = normalizeReflection(out.reflection)
	if (out.softEdges !== undefined) out.softEdges = normalizeSoftEdge(out.softEdges)
	if (out.blur !== undefined) out.blur = normalizeBlur(out.blur)
	if (out.fillOverlay !== undefined) out.fillOverlay = normalizeFillOverlay(out.fillOverlay)
	// Text-character effects use the same semantic slider aliases as shape and
	// picture effects, but serialize inside the text run's effectLst. Normalize
	// them on every public/native path so initial authoring and patch/re-edit
	// behave identically and explicit null remains a component reset.
	if (out.textShadow !== undefined) out.textShadow = normalizeShadow(out.textShadow)
	if (out.textReflection !== undefined) out.textReflection = normalizeReflection(out.textReflection)
	if (Object.prototype.hasOwnProperty.call(out, 'textFill')) {
		out.textFill = currentOptions
			? patchTextFill(currentOptions.textFill, out.textFill, `${path}.textFill`)
			: normalizeTextFill(out.textFill, `${path}.textFill`)
		Object.assign(out, textFillCompatibilityOptions(out.textFill))
	}
	if (Object.prototype.hasOwnProperty.call(out, 'textOutline')) {
		const textOutline = normalizeTextOutline(out.textOutline, `${path}.textOutline`)
		if (textOutline === null) {
			out.outline = null
		} else if (textOutline !== undefined) {
			const existing = out.outline && typeof out.outline === 'object' ? out.outline : {}
			const existingColor = existing.color && typeof existing.color === 'object'
				? existing.color
				: (existing.color ? { color: existing.color } : {})
			const color = {
				...existingColor,
				...(textOutline.color !== undefined ? { color: textOutline.color } : {}),
				...(textOutline.transparency !== undefined ? { transparency: textOutline.transparency } : {}),
			}
			out.outline = {
				...existing,
				...(Object.keys(color).length ? { color } : {}),
				...(textOutline.widthPt !== undefined ? { size: textOutline.widthPt } : {}),
			}
		}
	}
	if (Object.prototype.hasOwnProperty.call(out, 'charSpacing')) out.charSpacing = normalizeCharSpacing(out.charSpacing, `${path}.charSpacing`)
	if (Object.prototype.hasOwnProperty.call(out, 'lineSpacing')) out.lineSpacing = normalizeLineSpacing(out.lineSpacing, `${path}.lineSpacing`)
	if (Object.prototype.hasOwnProperty.call(out, 'lineSpacingMultiple')) out.lineSpacingMultiple = normalizeLineSpacingMultiple(out.lineSpacingMultiple, `${path}.lineSpacingMultiple`)
	if (Object.prototype.hasOwnProperty.call(out, 'paraSpaceBefore')) out.paraSpaceBefore = normalizeParagraphSpacing(out.paraSpaceBefore, `${path}.paraSpaceBefore`)
	if (Object.prototype.hasOwnProperty.call(out, 'paraSpaceAfter')) out.paraSpaceAfter = normalizeParagraphSpacing(out.paraSpaceAfter, `${path}.paraSpaceAfter`)
	if (Object.prototype.hasOwnProperty.call(out, 'indent')) out.indent = normalizeParagraphIndent(out.indent, `${path}.indent`)
	if (Object.prototype.hasOwnProperty.call(out, 'hanging')) out.hanging = normalizeParagraphIndent(out.hanging, `${path}.hanging`)
	if (Object.prototype.hasOwnProperty.call(out, 'indentLevel')) out.indentLevel = normalizeIndentLevel(out.indentLevel, `${path}.indentLevel`)
	if (Object.prototype.hasOwnProperty.call(out, 'bullet')) out.bullet = normalizeBulletOptions(out.bullet, `${path}.bullet`)
	if (Object.prototype.hasOwnProperty.call(out, 'tabStops')) out.tabStops = normalizeTabStops(out.tabStops, `${path}.tabStops`)
	if (Object.prototype.hasOwnProperty.call(out, 'margin')) out.margin = normalizeTextBoxMargin(out.margin, `${path}.margin`)
	if (Object.prototype.hasOwnProperty.call(out, 'valign')) out.valign = normalizeTextVerticalAlign(out.valign, `${path}.valign`)
	if (Object.prototype.hasOwnProperty.call(out, 'align')) out.align = normalizeTextAlignment(out.align, `${path}.align`)
	if (Object.prototype.hasOwnProperty.call(out, 'underline')) out.underline = normalizeTextUnderline(out.underline, `${path}.underline`)
	if (Object.prototype.hasOwnProperty.call(out, 'fit')) out.fit = normalizeTextFit(out.fit, `${path}.fit`)
	if (Object.prototype.hasOwnProperty.call(out, 'rtlMode')) out.rtlMode = normalizeTextRtlMode(out.rtlMode, `${path}.rtlMode`)
	if (Object.prototype.hasOwnProperty.call(out, 'lang')) out.lang = normalizeTextLanguage(out.lang, `${path}.lang`)
	if (Object.prototype.hasOwnProperty.call(out, 'wrap')) out.wrap = normalizeTextWrap(out.wrap, `${path}.wrap`)
	if (Object.prototype.hasOwnProperty.call(out, 'vert')) out.vert = normalizeTextDirection(out.vert, `${path}.vert`)
	for (const key of ['strike', 'highlight', 'superscript', 'subscript']) if (Object.prototype.hasOwnProperty.call(out, key)) out = { ...out, ...normalizeRichRunOptions({ [key]: out[key] }, `${path}.${key}`) }
	if (out.wordArt !== undefined) out.wordArt = Object.prototype.hasOwnProperty.call(out.wordArt || {}, 'transform') ? normalizeWordArtOptions(out.wordArt, `${path}.wordArt`) : normalizeWordArtPatch(out.wordArt, `${path}.wordArt`, currentOptions?.wordArt?.transform)
	if (out.text3D !== undefined) out.text3D = normalizeText3DOptions(out.text3D, `${path}.text3D`)
	if (out.effect3D !== undefined) out.effect3D = normalizeText3DOptions(out.effect3D, `${path}.effect3D`)
	if (out.fit !== undefined && out.autoFit === true) delete out.autoFit
	return out
}

function applyAnimations(slide, anims) {
	if (!anims || anims.length === 0) return
	const target = slide._slideObjects[slide._slideObjects.length - 1]
	if (!target) return
	for (const a of anims) slide.addAnimation(target, a)
}

async function handleAddText(args) {
	const slide = getSlide(args.deckId, args.slideIndex)
	let options = args.options ? { ...args.options } : {}
	const isShapeText = Boolean(options.shape)
	const presetId = options.wordArtStylePresetId || (!isShapeText ? options.shapeStylePresetId : null)
	if (presetId) {
		const preset = nativeStylePresetById(presetId)
		if (!preset) throw new Error(`Unknown native style preset: ${presetId}`)
		options = { ...options, ...applyNativeStylePreset(options, presetId).style }
		if (options.shapeStylePresetId) options.shapeStylePresetId = options.shapeStylePresetId
		if (options.wordArtStylePresetId) options.wordArtStylePresetId = options.wordArtStylePresetId
	}
	// textShape is emitted through addText with a native shape geometry.  Apply
	// shape effects here as well as in addShape so an AI-selected shadow/bevel/
	// reflection survives to the text-bearing shape's spPr package state.
	const shapeEffectPresetIds = options.shapeEffectPresetIds || options.shapeEffectPresetId
	if (shapeEffectPresetIds && !isShapeText) {
		options = applyShapeEffectPresets(options, shapeEffectPresetIds).style
		options.shapeEffectPresetIds = shapeEffectPresetIds
		delete options.shapeEffectPresetId
	}
	const textEffectPresetIds = options.textEffectPresetIds || options.textEffectPresetId
	if (textEffectPresetIds) {
		options = applyTextEffectPresets(options, textEffectPresetIds).style
		options.textEffectPresetIds = textEffectPresetIds
		delete options.textEffectPresetId
	}
	const authoredEffects = Object.prototype.hasOwnProperty.call(options, 'effects') ? _deepCloneData(options.effects) : undefined
	options = normalizeVisualOptions(options, 'slide.add_text options')
	if (authoredEffects !== undefined) options.effects = authoredEffects
	if (isShapeText) {
		options = options._shapeFormattingState
			? rehydrateShapeFormattingOptions(options)
			: applyShapeFormattingToOptions(options, null, 'replace').options
	}
	const { anims, cleaned } = liftAnimations(options)
	const text = normalizeRuntimeRichText(args.text, 'slide.add_text text')
	slide.addText(text, cleaned || {})
	applyAnimations(slide, anims)
	return { ok: true, slideIndex: args.slideIndex, animationsApplied: anims.length }
}

async function handleAddEquation(args) {
	const slide = getSlide(args.deckId, args.slideIndex)
	let opts = args.options ? { ...args.options } : {}
	for (const key of ['source', 'sourceFormat', 'display', 'x', 'y', 'w', 'h', 'objectName', 'editHandle', 'fontSize', 'fontFace', 'color', 'italic', 'align', 'lang', 'accessibilityTitle', 'altText', 'isDecorative', 'rotate', 'rotation', 'flipH', 'flipV', 'fallback', 'semanticSlots', 'slots']) {
		if (args[key] !== undefined) opts[key] = args[key]
	}
	const equationPresetId = args.equationGalleryPresetId || args.equationPresetId || opts.equationGalleryPresetId || opts.equationPresetId
	const authoredParameters = args.parameters || args.semanticSlots || opts.parameters || opts.semanticSlots || opts.slots
	const equationPresetResolved = args._equationPresetResolved === true || opts._equationPresetResolved === true
	if (equationPresetId && !equationPresetResolved) opts = applyEquationGalleryPreset(opts, equationPresetId, authoredParameters || {}).options
	delete opts._equationPresetResolved
	const resolvedPresetId = equationPresetId || opts.equationGalleryPresetId || opts.equationPresetId
	delete opts.equationGalleryPresetId
	delete opts.equationPresetId
	delete opts.parameters
	delete opts.semanticSlots
	delete opts.slots
	const normalizedEquation = normalizeEquationOptions(opts, 'slide.add_equation options')
	if (resolvedPresetId) normalizedEquation.equationGalleryPresetId = String(resolvedPresetId)
	if (authoredParameters !== undefined) normalizedEquation.parameters = structuredClone(authoredParameters)
	Object.assign(normalizedEquation, normalizeInternalAccessibilityMetadata(normalizedEquation, 'slide.add_equation options'))
	const { anims, cleaned } = liftAnimations(normalizedEquation)
	if (typeof slide.addEquation !== 'function') throw new Error('Native equation authoring requires a runtime with slide.addEquation support.')
	slide.addEquation(cleaned || {})
	applyAnimations(slide, anims)
	return {
		ok: true,
		slideIndex: args.slideIndex,
		sourceFormat: cleaned?.sourceFormat || (typeof cleaned?.source === 'object' ? 'template' : 'plain'),
		hasFallbackImage: Boolean(cleaned?.fallback && typeof cleaned.fallback === 'object'),
		animationsApplied: anims.length,
	}
}

async function handleUpdateEquation(args) {
	const slide = getSlide(args.deckId, args.slideIndex)
	const { obj, index, rawIndex } = _resolveShapeForTool(slide, args.target, 'update_equation')
	const patch = args.patch && typeof args.patch === 'object' ? { ...args.patch } : {}
	for (const key of ['source', 'sourceFormat', 'display', 'x', 'y', 'w', 'h', 'objectName', 'editHandle', 'fontSize', 'fontFace', 'color', 'italic', 'align', 'lang', 'accessibilityTitle', 'altText', 'isDecorative', 'rotate', 'rotation', 'flipH', 'flipV', 'fallback', 'semanticSlots', 'slots']) {
		if (args[key] !== undefined) patch[key] = args[key]
	}
	// Validate the caller's patch before touching the live object. This makes
	// source:null and malformed OMML fail atomically at the tool boundary.
	normalizeEquationOptions(patch, 'slide.update_equation patch', { allowPatch: true })
	Object.assign(patch, normalizeInternalAccessibilityMetadata(patch, 'slide.update_equation patch'))
	if (!Object.keys(patch).length) throw new Error('update_equation: provide patch or equation fields such as source/sourceFormat.')
	if (_shapeKind(obj) !== 'equation') {
		const rawStructured = exportedRawSourceStructuredFields(obj) ||
			(_shapeKind(obj) === 'passthrough' ? exportedPassthroughEquationFields(obj) : null)
		if (!rawStructured && patch.source === undefined) {
			throw new Error(`update_equation: target "${obj.options?.objectName || index}" is ${_shapeKind(obj) || 'unknown'}, expected equation.`)
		}
		const opts = {
			source: patch.source ?? rawStructured?.fields?.source,
			sourceFormat: patch.sourceFormat ?? rawStructured?.fields?.sourceFormat,
			x: patch.x ?? obj.options?.x,
			y: patch.y ?? obj.options?.y,
			w: patch.w ?? obj.options?.w,
			h: patch.h ?? obj.options?.h,
			objectName: patch.objectName ?? obj.options?.objectName,
			spid: obj.options?.spid,
			fontSize: patch.fontSize,
			fontFace: patch.fontFace,
			color: patch.color,
			italic: patch.italic,
			align: patch.align,
			lang: patch.lang,
			display: patch.display,
			rotate: patch.rotate,
			rotation: patch.rotation,
			flipH: patch.flipH,
			flipV: patch.flipV,
			accessibilityTitle: patch.accessibilityTitle,
			altText: patch.altText,
			isDecorative: patch.isDecorative,
			fallback: patch.fallback,
		}
		if (typeof slide.addEquation !== 'function') throw new Error('update_equation: runtime does not expose slide.addEquation.')
		const relIds = new Set(collectRelationshipIds(obj?.passthrough?.xml || ''))
		const rawRelsRemoved = _removePassthroughRelsForObject(slide, obj, relIds)
		const { replacement } = _replaceSlideObjectInPlace(slide, rawIndex, () => slide.addEquation(cleanUndefinedObject(opts)))
		return {
			ok: true,
			slideIndex: args.slideIndex,
			index,
			rawIndex,
			objectName: replacement?.options?.objectName,
			sourceFormat: opts.sourceFormat || (typeof opts.source === 'object' ? 'template' : 'plain'),
			patchedKeys: Object.keys(patch),
			convertedFromPassthrough: _shapeKind(obj) === 'passthrough' ? 'equation' : 'raw-source-equation',
			rawRelsRemoved,
		}
	}
	const existing = { ...(obj.equation || {}) }
	const oldFallbackRid = Number(obj.fallbackRid)
	if (patch.fallback === undefined && oldFallbackRid > 0 && existing.fallback === undefined) {
		const rel = (slide._relsMedia || []).find(item => Number(item?.rId) === oldFallbackRid)
		if (rel) existing.fallback = { path: rel.path, ...(rel.data ? { data: rel.data } : {}), rendered: true }
	}
	const merged = { ...existing, ...(obj.options || {}), ...patch }
	delete merged._equationPresetResolved
	delete merged.equationGalleryPresetId
	delete merged.equationPresetId
	delete merged.parameters
	delete merged.semanticSlots
	delete merged.slots
	const normalized = normalizeEquationOptions(merged, 'slide.update_equation merged options')
	for (const key of ['equationGalleryPresetId', 'equationPresetId', 'parameters', 'semanticSlots', 'slots']) delete normalized[key]
	if (oldFallbackRid > 0) slide._relsMedia = (slide._relsMedia || []).filter(rel => Number(rel?.rId) !== oldFallbackRid)
	const replaced = _replaceSlideObjectInPlace(slide, rawIndex, () => slide.addEquation(normalized))
	return {
		ok: true,
		slideIndex: args.slideIndex,
		index,
		rawIndex,
		objectName: replaced.replacement?.options?.objectName,
		sourceFormat: replaced.replacement?.equation?.sourceFormat || (typeof replaced.replacement?.equation?.source === 'object' ? 'template' : 'plain'),
		patchedKeys: Object.keys(patch),
		fallbackReset: patch.fallback === null || patch.fallback === false,
	}
}

const EQUATION_SOURCE_FORMATS = Object.freeze(['plain', 'unicodeMath', 'omml', 'template'])
const EQUATION_TEMPLATE_KINDS = Object.freeze([
	'text', 'row', 'group',
	'fraction', 'frac',
	'superscript', 'sup', 'subscript', 'sub', 'subsup',
	'presubsup', 'preSubSup',
	'radical', 'sqrt',
	'nary', 'summation', 'sum', 'integral', 'operator',
	'bracket', 'delimiter', 'cases', 'eqArr',
	'function', 'func', 'log',
	'accent', 'bar', 'overbar', 'underbar',
	'box', 'boxed', 'limit', 'limlow', 'limitUpper', 'limupp',
	'groupChar', 'groupchr',
	'matrix',
])
const EQUATION_COMMON_STRUCTURES = Object.freeze({
	fraction: { kind: 'fraction', numerator: 'dy', denominator: 'dx' },
	superscript: { kind: 'superscript', base: 'x', exponent: '2' },
	radical: { kind: 'radical', radicand: 'x+a' },
	summation: { kind: 'summation', lower: 'i=0', upper: 'n', body: 'i' },
	integral: { kind: 'integral', lower: '0', upper: '1', body: 'f(x)' },
	cases: { kind: 'cases', rows: ['x < 0', 'x >= 0'] },
	matrix: { kind: 'matrix', rows: [['1', '0'], ['0', '1']] },
})

function publicEquationPreset(preset, full = false) {
	const base = {
		id: preset.id,
		gallery: preset.gallery,
		category: preset.category,
		tileIndex: preset.tileIndex,
		label: preset.label,
		description: preset.description,
		parameters: [...(preset.parameters || [])],
		selectionManifestSelectors: { equationGalleryPresetId: preset.id },
	}
	if (!full) return base
	return {
		...base,
		sourceFormat: preset.recipe?.sourceFormat || 'template',
		source: structuredClone(preset.recipe?.source || {}),
	}
}

async function handleEquationCatalog(args = {}) {
	const limit = Math.max(1, Math.min(Number.isFinite(Number(args.limit)) ? Math.floor(Number(args.limit)) : 12, EQUATION_GALLERY_PRESETS.length))
	const offset = Math.max(0, Math.min(Number.isFinite(Number(args.offset)) ? Math.floor(Number(args.offset)) : 0, EQUATION_GALLERY_PRESETS.length))
	const format = args.format === 'full' ? 'full' : 'summary'
	const query = String(args.query || '')
	const templateKind = args.templateKind == null || String(args.templateKind).trim() === '' ? null : String(args.templateKind).trim()
	const selectedId = args.equationGalleryPresetId == null || String(args.equationGalleryPresetId).trim() === '' ? null : String(args.equationGalleryPresetId).trim()
	if (selectedId && !EQUATION_GALLERY_PRESETS.some(preset => preset.id === selectedId)) throw new Error(`Equation gallery preset not found: ${selectedId}`)
	const searchTokens = unrankedCatalogTokens(query, args.requireFeatures)
	const allPresets = EQUATION_GALLERY_PRESETS
		.filter(preset => !selectedId || preset.id === selectedId)
		.filter(preset => !templateKind || String(preset.recipe?.source?.kind || '').toLowerCase() === templateKind.toLowerCase())
		.map(preset => publicEquationPreset(preset, format === 'full'))
		.filter(preset => catalogEntryContainsAll(preset, searchTokens))
		.sort((a, b) => String(a.id).localeCompare(String(b.id)))
	const presets = allPresets.slice(offset, offset + limit)
	return {
		brand: BETTERPPTX_BRAND,
		contractVersion: 'betterpptx.unranked-equation-catalog.v1',
		selectionAuthority: 'ai',
		engineRole: 'catalog-filter-and-exact-id-validator',
		selectionManifestContract: publicSelectionManifestContract('equation'),
		unranked: true,
		catalogOrder: 'id-ascending',
		compatibilityAlias: 'betterpptx.equation.catalog',
		query,
		templateKind,
		pagination: { offset, limit, returned: presets.length, totalMatches: allPresets.length, hasMore: offset + presets.length < allPresets.length },
		sourceFormats: [...EQUATION_SOURCE_FORMATS],
		nativeOutput: 'PowerPoint Office Math XML inside editable equation text bodies',
		fallbackPolicy: 'Native equations are emitted by default. Preview fallback images are supported only when the caller supplies a rendered image path or data URL; the service does not rasterize equations by default.',
		templateKinds: [...EQUATION_TEMPLATE_KINDS],
		commonStructures: structuredClone(EQUATION_COMMON_STRUCTURES),
		presets,
		ribbonPresets: allPresets.filter(preset => String(preset.gallery || '').includes('ribbon') || String(preset.gallery || '').includes('fraction')).map(preset => ({ ...preset })),
		semanticPresets: allPresets.filter(preset => String(preset.gallery || '').includes('semantic')).map(preset => ({ ...preset })),
		selectedPreset: selectedId ? allPresets.find(preset => preset.id === selectedId) || null : null,
	}
}

const SMARTART_REFERENCE_CATALOG_PATH = path.resolve(ASSETS_ROOT, 'outputs', 'smartart-com-matrix', '20260531_105826', 'smartart_catalog.json')
const SMARTART_CURRENT_OFFICE_LAYOUTS_PATH = path.resolve(__dirname, 'smartart-current-office-layouts.json')
const SMARTART_STYLE_APPLICABILITY_PATH = path.resolve(__dirname, 'smartart-style-applicability.json')
const SMARTART_BASIC_BLOCK_LAYOUT_ID = 'urn:microsoft.com/office/officeart/2005/8/layout/default'
const SMARTART_BASIC_BLOCK_QUICK_STYLE_ID = 'urn:microsoft.com/office/officeart/2005/8/quickstyle/simple1'
const SMARTART_BASIC_BLOCK_COLOR_STYLE_ID = 'urn:microsoft.com/office/officeart/2005/8/colors/accent1_2'
let smartArtCatalogCache = null

function stripBom(text) {
	return text && text.charCodeAt(0) === 0xfeff ? text.slice(1) : text
}

function publicSmartArtItem(item) {
	return {
		index: item.Index ?? item.index ?? null,
		name: item.Name || item.name || '',
		category: item.Category || item.category || '',
		id: item.Id || item.id || '',
		description: item.Description || item.description || '',
	}
}

function smartArtSupportFor(layout) {
	const key = smartArtLookupKey(`${layout?.category || ''} ${layout?.name || ''} ${layout?.id || ''}`)
	const picture = key.includes('picture')
	const hierarchy = key.includes('hierarchy') || key.includes('orgchart')
	const topology = smartArtNodeTopologyContractFor(layout)
	return {
		supportStatus: 'supported-native',
		nativeAuthoring: true,
		shapeFallback: true,
		roundtripPolicy: 'structured native authoring plus preserve fallback for imported diagrams',
		applicability: {
			nodeModel: picture ? 'image-per-node' : hierarchy ? 'hierarchical-node-tree' : topology?.nodeModel || 'semantic-node-list',
			children: hierarchy ? 'supported' : topology ? 'required' : 'not-required',
			imagePolicy: picture ? 'required-on-every-node' : 'optional',
			nativeRolePolicy: hierarchy ? 'root-manager-member-peer-node; assistant requires explicit non-native fallback' : 'generic-node-only',
			...(topology ? { topologyContract: topology } : {}),
		},
	}
}

function smartArtPresetSupport(item) {
	const preset = publicSmartArtItem(item)
	return {
		...preset,
		supportStatus: 'supported-native',
	}
}

function smartArtLookupKey(value) {
	return String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, '')
}

async function resolveSmartArtLayoutOption(opts = {}) {
	const catalog = await loadSmartArtCatalog()
	const requested = opts.layoutId || opts.layoutName || opts.layout
	if (!requested) return catalog.layouts.find(item => item.name === 'Basic Block List') || catalog.layouts[0] || null
	const raw = String(requested)
	const key = smartArtLookupKey(raw)
	const defaultByCategory = {
		list: 'Basic Block List',
		process: 'Basic Process',
		cycle: 'Basic Cycle',
		hierarchy: 'Organization Chart',
		relationship: 'Basic Radial',
		matrix: 'Basic Matrix',
		pyramid: 'Basic Pyramid',
		picture: 'Picture Caption List',
		timeline: 'Alternating Circle Process',
		team: 'Meet The Team',
		meettheteam: 'Meet The Team',
	}
	const defaultName = defaultByCategory[key]
	if (defaultName) {
		const byDefault = catalog.layouts.find(item => smartArtLookupKey(item.name) === smartArtLookupKey(defaultName))
		if (byDefault) return byDefault
	}
	return catalog.layouts.find(item =>
		item.id === raw ||
		smartArtLookupKey(item.id) === key ||
		smartArtLookupKey(item.name) === key ||
		smartArtLookupKey(item.category) === key
	) || null
}

function isPictureSmartArtLayout(layout, opts = {}) {
	const requested = [opts.layoutId, opts.layoutName, opts.layout].filter(Boolean).join(' ')
	const key = smartArtLookupKey(`${layout?.category || ''} ${layout?.name || ''} ${layout?.id || ''} ${requested}`)
	return key.includes('picture')
}

function isHierarchySmartArtLayout(layout, opts = {}) {
	const requested = [opts.layoutId, opts.layoutName, opts.layout].filter(Boolean).join(' ')
	const key = smartArtLookupKey(`${layout?.category || ''} ${layout?.name || ''} ${layout?.id || ''} ${requested}`)
	return key.includes('hierarchy') || key.includes('orgchart')
}

function flattenSmartArtNodes(nodes) {
	const out = []
	const visit = (node) => {
		if (node === undefined || node === null) return
		out.push(node)
		if (node && typeof node === 'object' && Array.isArray(node.children)) node.children.forEach(visit)
	}
	if (Array.isArray(nodes)) nodes.forEach(visit)
	return out
}

function smartArtNodeImageValue(node) {
	if (!node || typeof node !== 'object') return ''
	for (const key of ['image', 'imageData', 'imageUrl', 'imagePath', 'src', 'url', 'path']) {
		const value = node[key]
		if (typeof value === 'string' && value.trim()) return value.trim()
	}
	return ''
}

function mimeFromImageExt(ext) {
	switch (String(ext || '').toLowerCase()) {
		case 'jpg':
		case 'jpeg':
			return 'image/jpeg'
		case 'png':
			return 'image/png'
		case 'gif':
			return 'image/gif'
		case 'webp':
			return 'image/webp'
		case 'svg':
			return 'image/svg+xml'
		case 'bmp':
			return 'image/bmp'
		case 'tif':
		case 'tiff':
			return 'image/tiff'
		default:
			return ''
	}
}

function normalizeImageDataUri(raw) {
	const value = String(raw || '').trim()
	if (!value.toLowerCase().startsWith('data:image/')) return ''
	const comma = value.indexOf(',')
	if (comma < 0) return ''
	const header = value.slice(5, comma)
	const contentType = header.split(';')[0] || ''
	const payload = value.slice(comma + 1)
	if (!contentType.toLowerCase().startsWith('image/')) return ''
	if (header.toLowerCase().split(';').includes('base64')) return `data:${contentType};base64,${payload}`
	return `data:${contentType};base64,${Buffer.from(decodeURIComponent(payload), 'utf8').toString('base64')}`
}

async function smartArtImageToDataUri(value) {
	const resolved = resolveGeneratedAssetRefs(value)
	if (typeof resolved !== 'string' || !resolved.trim()) return ''
	const raw = resolved.trim()
	const inline = normalizeImageDataUri(raw)
	if (inline) return inline
	if (isRemoteUrl(raw)) {
		const { buffer, contentType } = await fetchBufferWithLimit(raw, { maxBytes: 12 * 1024 * 1024, timeoutMs: 30000, requireImage: true })
		const ext = inferImageExtension(contentType, buffer, raw)
		const mime = mimeFromImageExt(ext) || String(contentType || '').split(';')[0] || 'image/png'
		return `data:${mime};base64,${buffer.toString('base64')}`
	}
	const localPath = path.resolve(raw)
	if (fsNode.existsSync(localPath) && fsNode.statSync(localPath).isFile()) {
		const buffer = fsNode.readFileSync(localPath)
		const ext = inferImageExtension('', buffer, localPath)
		const mime = mimeFromImageExt(ext) || 'image/png'
		return `data:${mime};base64,${buffer.toString('base64')}`
	}
	return ''
}

async function materializeSmartArtNodeImages(nodes) {
	if (!Array.isArray(nodes)) return nodes
	const normalizeNode = async (node) => {
		if (!node || typeof node !== 'object') return node
		const copy = { ...node }
		const imageValue = smartArtNodeImageValue(copy)
		if (imageValue) copy.image = await smartArtImageToDataUri(imageValue)
		if (Array.isArray(copy.children)) copy.children = await Promise.all(copy.children.map(normalizeNode))
		return copy
	}
	return Promise.all(nodes.map(normalizeNode))
}

async function enforceSmartArtPictureImages(opts = {}) {
	const resolvedLayout = await resolveSmartArtLayoutOption(opts)
	if (!isPictureSmartArtLayout(resolvedLayout, opts)) return { resolvedLayout, imageNodeCount: 0 }
	const nodes = flattenSmartArtNodes(opts.nodes)
	if (nodes.length === 0) {
		throw new Error('Native picture SmartArt layouts require explicit image-bearing nodes. Provide nodes as objects with image, imageUrl, imagePath, or imageData; blank picture placeholders are rejected.')
	}
	const missing = nodes
		.map((node, index) => ({ node, index }))
		.filter(item => !smartArtNodeImageValue(item.node))
	if (missing.length > 0) {
		const sample = missing.slice(0, 5).map(item => item.index + 1).join(', ')
		throw new Error(`Picture SmartArt layout "${resolvedLayout?.name || opts.layout || opts.layoutName || opts.layoutId || 'picture'}" requires an image for every node. Missing image on node(s): ${sample}. Provide node.image/imageUrl/imagePath/imageData or choose a non-picture SmartArt layout.`)
	}
	opts.nodes = await materializeSmartArtNodeImages(opts.nodes)
	const unresolved = flattenSmartArtNodes(opts.nodes)
		.map((node, index) => ({ node, index }))
		.filter(item => !normalizeImageDataUri(smartArtNodeImageValue(item.node)))
	if (unresolved.length > 0) {
		const sample = unresolved.slice(0, 5).map(item => item.index + 1).join(', ')
		throw new Error(`Picture SmartArt layout "${resolvedLayout?.name || 'picture'}" received image references that could not be materialized to base64 data URLs for node(s): ${sample}.`)
	}
	return { resolvedLayout, imageNodeCount: nodes.length }
}

async function enforceSmartArtNodeRoles(opts = {}, resolvedLayout = null) {
	const nodes = Array.isArray(opts.nodes) ? opts.nodes : []
	if (nodes.length === 0) return { resolvedLayout }
	const hierarchy = isHierarchySmartArtLayout(resolvedLayout, opts)
	const picture = isPictureSmartArtLayout(resolvedLayout, opts)
	const allowedHierarchyRoles = new Set(['root', 'manager', 'member', 'peer', 'node', 'assistant'])
	const hierarchyRoles = new Set(['root', 'manager', 'member', 'peer', 'assistant'])
	const walk = (node, nodePath) => {
		const role = node && typeof node === 'object' && typeof node.role === 'string' ? node.role.trim().toLowerCase() : ''
		if (role && hierarchy && !allowedHierarchyRoles.has(role)) throw new Error(`SMARTART_ROLE_NOT_APPLICABLE: role "${role}" is not supported by native hierarchy layout "${resolvedLayout?.name || opts.layout || 'hierarchy'}" at ${nodePath}. Use root, manager, member, peer, node, or assistant.`)
		if (role && !hierarchy && hierarchyRoles.has(role)) throw new Error(`SMARTART_ROLE_NOT_APPLICABLE: hierarchy role "${role}" requires a native hierarchy/org-chart layout, not "${resolvedLayout?.name || opts.layout || 'selected'}".`)
		if (role === 'image' && !picture) throw new Error(`SMARTART_ROLE_NOT_APPLICABLE: image role requires a picture SmartArt layout, not "${resolvedLayout?.name || opts.layout || 'selected'}".`)
		if (node && typeof node === 'object' && Array.isArray(node.children)) node.children.forEach((child, index) => walk(child, `${nodePath}.children[${index}]`))
	}
	nodes.forEach((node, index) => walk(node, `nodes[${index}]`))
	return { resolvedLayout }
}

function enforceSmartArtNodeTopology(opts = {}, resolvedLayout = null) {
	const inspection = inspectSmartArtNodeTopology({
		...opts,
		layoutId: resolvedLayout?.id || opts.layoutId,
		layoutName: resolvedLayout?.name || opts.layoutName,
	})
	if (!inspection || inspection.valid) return inspection
	const error = new Error(`SMARTART_NODE_TOPOLOGY_INVALID: native SmartArt layout "${inspection.contract.layoutName}" requires ${inspection.contract.authoringShape}. Flat top-level nodes can be present in the package but invisible in the PowerPoint render.`)
	error.code = 'SMARTART_NODE_TOPOLOGY_INVALID'
	error.details = inspection
	throw error
}

async function loadSmartArtCatalog() {
	if (smartArtCatalogCache) return smartArtCatalogCache
	let parsed = null
	try {
		parsed = JSON.parse(stripBom(await fs.readFile(SMARTART_REFERENCE_CATALOG_PATH, 'utf8')))
	} catch (_) {
		parsed = {
			counts: { layouts: 1, quickStyles: 1, colors: 1 },
			layouts: [{
				Index: 1,
				Name: 'Basic Block List',
				Category: 'list',
				Id: SMARTART_BASIC_BLOCK_LAYOUT_ID,
				Description: 'Use to show non-sequential or grouped blocks of information.',
			}],
			quickStyles: [{
				Index: 1,
				Name: 'Simple Fill',
				Category: 'simple',
				Id: SMARTART_BASIC_BLOCK_QUICK_STYLE_ID,
				Description: 'Simple Fill',
			}],
			colors: [{
				Index: 1,
				Name: 'Accent 1',
				Category: 'accent',
				Id: SMARTART_BASIC_BLOCK_COLOR_STYLE_ID,
				Description: 'Accent 1',
			}],
		}
	}
	let styleApplicability = null
	try {
		styleApplicability = JSON.parse(stripBom(await fs.readFile(SMARTART_STYLE_APPLICABILITY_PATH, 'utf8')))
	} catch (_) {
		styleApplicability = { layouts: [], counts: { capturedLayouts: 0, quickStyleLayouts: 0, colorLayouts: 0, uniqueQuickStyleIds: 0, uniqueColorIds: 0 } }
	}
	const applicabilityByLayout = new Map((styleApplicability.layouts || []).map(item => [String(item.layoutId), item]))
	// The historical frozen matrix remains the compatibility baseline.  Merge
	// only the separately captured current-Office layout definitions so the
	// public catalog and the executable MCP path stay aligned with the library
	// engine without mutating the frozen reference artifact.
	try {
		const current = JSON.parse(stripBom(await fs.readFile(SMARTART_CURRENT_OFFICE_LAYOUTS_PATH, 'utf8')))
		const existingIds = new Set((parsed.layouts || []).map(item => String(item.id || '')))
		const additions = (current.layouts || []).filter(item => !existingIds.has(String(item.id || '')))
		if (additions.length) {
			parsed = {
				...parsed,
				counts: { ...(parsed.counts || {}), layouts: (parsed.layouts || []).length + additions.length },
				layouts: [...(parsed.layouts || []), ...additions],
			}
		}
	} catch (_) {
		// The current-Office extension is optional at runtime; the frozen catalog
		// remains the safe baseline if the extension artifact is unavailable.
	}
	const layouts = (parsed.layouts || []).map(item => {
		const base = publicSmartArtItem(item)
		return { ...base, ...smartArtSupportFor(base), galleryApplicability: applicabilityByLayout.get(String(base.id)) || null }
	})
	smartArtCatalogCache = {
		counts: {
			layouts: parsed.counts?.layouts || layouts.length,
			quickStyles: parsed.counts?.quickStyles || (parsed.quickStyles || []).length,
			colors: parsed.counts?.colors || (parsed.colors || []).length,
			supportedNativeLayouts: layouts.filter(x => x.supportStatus === 'supported-native').length,
		},
		layouts,
		quickStyles: (parsed.quickStyles || []).map(item => smartArtPresetSupport(item)),
		colors: (parsed.colors || []).map(item => smartArtPresetSupport(item)),
		galleryApplicability: {
			status: styleApplicability.status || 'NOT_CAPTURED',
			claimScope: styleApplicability.claimScope || 'Only captured layout IDs have Ribbon tile applicability evidence.',
			...styleApplicability.counts,
		},
	}
	return smartArtCatalogCache
}

async function handleSmartArtCatalog(args = {}) {
	const request = normalizeSmartArtCatalogRequest(args)
	const catalog = await loadSmartArtCatalog()
	let layouts = catalog.layouts
	if (request.category) {
		layouts = layouts.filter(item => String(item.category || '').trim().toLowerCase() === request.category)
	}
	if (request.supportStatus) {
		layouts = layouts.filter(item => item.supportStatus === request.supportStatus)
	}
	const searchTokens = unrankedCatalogTokens(request.query, request.intent, request.dataShape, request.relationship)
	const searchTextForLayout = item => ({
		index: item.index, name: item.name, category: item.category, id: item.id, description: item.description,
		applicability: {
			nodeModel: item.applicability?.nodeModel,
			children: item.applicability?.children,
			imagePolicy: item.applicability?.imagePolicy,
			nativeRolePolicy: item.applicability?.nativeRolePolicy,
			topologyContract: item.applicability?.topologyContract,
		},
	})
	if (searchTokens.length) layouts = layouts.filter(item => catalogEntryContainsAll(searchTextForLayout(item), searchTokens))
	if (request.needsImages === true) layouts = layouts.filter(item => smartArtLookupKey(`${item.category} ${item.name} ${item.id}`).includes('picture'))
	if (request.layoutId) layouts = layouts.filter(item => item.id === request.layoutId)
	layouts = [...layouts].sort((a, b) => String(a.id).localeCompare(String(b.id)))
	const offset = Math.max(0, Math.min(request.offset, layouts.length))
	const limit = request.limit
	const projectLayout = item => {
		if (request.format === 'full') return item
		const { galleryApplicability, ...compact } = item
		return compact
	}
	const projectSelectedLayout = item => {
		if (!item) return null
		const { galleryApplicability, ...compact } = item
		return compact
	}
	const projectSelectedApplicability = value => value ? {
		layoutId: value.layoutId,
		layoutName: value.layoutName,
		category: value.category,
		status: value.status,
		quickStyleCount: Array.isArray(value.quickStyles) ? value.quickStyles.length : 0,
		colorStyleCount: Array.isArray(value.colors) ? value.colors.length : 0,
		quickStyleIds: Array.isArray(value.quickStyles) ? value.quickStyles.map(item => item.id) : [],
		colorStyleIds: Array.isArray(value.colors) ? value.colors.map(item => item.id) : [],
	} : null
	const pagedLayouts = layouts.slice(offset, offset + limit).map(projectLayout)
	const quickStyles = [...catalog.quickStyles].sort((a, b) => String(a.id).localeCompare(String(b.id)))
	const colors = [...catalog.colors].sort((a, b) => String(a.id).localeCompare(String(b.id)))
	const selectedLayout = request.layoutId ? catalog.layouts.find(item => item.id === request.layoutId) : null
	const selectedQuickStyle = request.quickStyleId ? catalog.quickStyles.find(item => item.id === request.quickStyleId) : null
	const selectedColorStyle = request.colorStyleId ? catalog.colors.find(item => item.id === request.colorStyleId) : null
	if (request.layoutId && !selectedLayout) throw new Error(`SmartArt layout not found: ${request.layoutId}`)
	if (request.quickStyleId && !selectedQuickStyle) throw new Error(`SmartArt quick style not found: ${request.quickStyleId}`)
	if (request.colorStyleId && !selectedColorStyle) throw new Error(`SmartArt color style not found: ${request.colorStyleId}`)
	const selectedApplicability = selectedLayout?.galleryApplicability || null
	if (selectedApplicability && request.quickStyleId && Array.isArray(selectedApplicability.quickStyles) && !selectedApplicability.quickStyles.some(item => item.id === request.quickStyleId)) throw new Error(`SmartArt quick style is not applicable to layout: ${request.quickStyleId}`)
	if (selectedApplicability && request.colorStyleId && Array.isArray(selectedApplicability.colors) && !selectedApplicability.colors.some(item => item.id === request.colorStyleId)) throw new Error(`SmartArt color style is not applicable to layout: ${request.colorStyleId}`)
	return {
		contractVersion: SMARTART_CATALOG_SCHEMA_VERSION,
		selectionAuthority: 'ai',
		engineRole: 'catalog-filter-and-exact-id-validator',
		selectionManifestContract: publicSelectionManifestContract('smartart'),
		unranked: true,
		catalogOrder: 'id-ascending',
		compatibilityAlias: 'betterpptx.smartart.catalog',
		format: request.format,
		query: request.query,
		intent: request.intent ?? null,
		dataShape: request.dataShape ?? null,
		relationship: request.relationship ?? null,
		category: request.category ?? null,
		needsImages: request.needsImages ?? null,
		nativeMode: {
			status: 'full-catalog-authoring',
			supportedLayoutCount: catalog.counts.layouts,
			supportedQuickStyleCount: catalog.counts.quickStyles,
			supportedColorStyleCount: catalog.counts.colors,
			pictureImagePolicy: 'required-per-node',
			selectionPolicy: 'The AI chooses layoutId, quickStyleId, and colorStyleId from this descriptive catalog. The engine validates exact applicability and never scores or recommends a SmartArt design.',
			limitations: [
				'Native authoring emits the PowerPoint layout, quick style, color style, data, and drawing package families.',
				'Imported SmartArt roundtrip still preserves raw diagram packages when structured extraction has not been requested.',
				'Picture SmartArt layouts require caller-provided images on every node; blank picture placeholders are rejected. Use node.image, node.imageUrl, node.imagePath, or node.imageData.',
			],
		},
		legacyCompatibilityDefaults: {
			certificationEligible: false,
			layout: 'Basic Block List',
			quickStyle: 'Polished',
			colorStyle: 'Colorful - Accent Colors',
			rule: 'These values keep omitted-selector legacy specs executable; they are not AI selections and cannot certify first-time-right authorship.',
		},
		categories: [...new Set(catalog.layouts.map(item => String(item.category || '').trim()).filter(Boolean))].sort(),
		counts: catalog.counts,
		galleryApplicability: catalog.galleryApplicability,
		pagination: { offset, limit, returned: pagedLayouts.length, totalMatches: layouts.length, hasMore: offset + pagedLayouts.length < layouts.length },
		layouts: request.includeLayouts === false ? null : pagedLayouts,
		quickStyles,
		colors,
		selectedPlan: (selectedLayout || selectedQuickStyle || selectedColorStyle) ? {
			layoutId: selectedLayout?.id ?? null,
			quickStyleId: selectedQuickStyle?.id ?? null,
			colorStyleId: selectedColorStyle?.id ?? null,
			layout: selectedLayout ? projectSelectedLayout(selectedLayout) : null,
			quickStyle: selectedQuickStyle,
			colorStyle: selectedColorStyle,
			applicability: projectSelectedApplicability(selectedApplicability),
		} : null,
	}
}

async function handleAddShape(args) {
	const slide = getSlide(args.deckId, args.slideIndex)
	let opts = args.options ? { ...args.options } : {}
	if (args.text) opts.text = args.text
	if (args.textOptions) Object.assign(opts, args.textOptions)
	if (opts.wordArtStylePresetId && !opts.shapeStylePresetId) {
		const preset = nativeStylePresetById(opts.wordArtStylePresetId)
		if (!preset) throw new Error(`Unknown native style preset: ${opts.wordArtStylePresetId}`)
		opts = { ...opts, ...applyNativeStylePreset(opts, opts.wordArtStylePresetId).style, wordArtStylePresetId: opts.wordArtStylePresetId }
	}
	const textEffectPresetIds = opts.textEffectPresetIds || opts.textEffectPresetId
	if (textEffectPresetIds) {
		opts = applyTextEffectPresets(opts, textEffectPresetIds).style
		opts.textEffectPresetIds = textEffectPresetIds
		delete opts.textEffectPresetId
	}
	// Resolve opaque public/locked/generated asset handles recursively before
	// normalization. This covers texture.source.asset, texture.asset, and the
	// equivalent picture fields without exposing paths through the public MCP.
	if (opts.fill) opts.fill = resolveNativeFillAssetRefs(opts.fill)
	if (opts.picture) opts.picture = resolveNativeFillAssetRefs({ picture: opts.picture }).picture
	const authoredEffects = Object.prototype.hasOwnProperty.call(opts, 'effects') ? _deepCloneData(opts.effects) : undefined
	opts = normalizeVisualOptions(opts, 'slide.add_shape options') || {}
	if (authoredEffects !== undefined) opts.effects = authoredEffects
	opts = opts._shapeFormattingState
		? rehydrateShapeFormattingOptions(opts)
		: applyShapeFormattingToOptions(opts, null, 'replace').options
	const { anims, cleaned } = liftAnimations(opts)
	slide.addShape(args.shapeName, cleaned)
	applyAnimations(slide, anims)
	return { ok: true, slideIndex: args.slideIndex, animationsApplied: anims.length }
}

async function handleAddConnector(args) {
	const slide = getSlide(args.deckId, args.slideIndex)
	let opts = { ...(args.options || {}) }
	for (const key of ['connectorType', 'routing', 'x', 'y', 'w', 'h', 'startShapeId', 'startConnectionIndex', 'endShapeId', 'endConnectionIndex', 'line', 'objectName', ...CONNECTOR_EFFECT_FIELDS]) {
		if (args[key] !== undefined) opts[key] = args[key]
	}
	Object.assign(opts, normalizeInternalAccessibilityMetadata(opts, 'slide.add_connector options'))
	// Validate the public structural lane before connector-style composition.
	// Internal gallery state is intentionally removed from this validation view;
	// it is reattached only by the typed connector-style resolver below.
	{
		const structuralInput = { ...opts }
		delete structuralInput._connectorStyleState
		delete structuralInput._rawConnectorLineXml
		delete structuralInput._rawConnectorStyleXml
		// The compiler has already lowered the public accessibility vocabulary.
		// Validate that typed metadata above, but do not present its internal names
		// to the closed structural geometry contract or discard it from the object.
		delete structuralInput.isDecorative
		delete structuralInput.accessibilityTitle
		const normalizedStructural = normalizeStructuralConnector(structuralInput, 'slide.add_connector')
		for (const key of ['connectorType', 'routing', 'x', 'y', 'w', 'h', 'startShapeId', 'startConnectionIndex', 'endShapeId', 'endConnectionIndex', 'connectorStylePresetId', 'line', 'objectName', 'editHandle', ...CONNECTOR_EFFECT_FIELDS]) {
			if (Object.prototype.hasOwnProperty.call(normalizedStructural, key)) opts[key] = normalizedStructural[key]
		}
	}
	const hasResolvedState = opts?._connectorStyleState?.schemaVersion === CONNECTOR_STYLE_STATE_VERSION
	const ownsSelector = Object.prototype.hasOwnProperty.call(args, 'connectorStylePresetId') || (!hasResolvedState && Object.prototype.hasOwnProperty.call(opts, 'connectorStylePresetId'))
	const ownsLine = Object.prototype.hasOwnProperty.call(args, 'line') || (!hasResolvedState && Object.prototype.hasOwnProperty.call(opts, 'line'))
	const selector = Object.prototype.hasOwnProperty.call(args, 'connectorStylePresetId') ? args.connectorStylePresetId : opts.connectorStylePresetId
	const authoredLine = Object.prototype.hasOwnProperty.call(args, 'line') ? args.line : opts.line
	if (ownsSelector || ownsLine) {
		delete opts.connectorStylePresetId
		delete opts.line
		const state = resolveConnectorStyleComposition({
			...(ownsSelector ? { connectorStylePresetId: normalizeConnectorStylePresetId(selector, 'slide.add_connector connectorStylePresetId') } : {}),
			...(ownsLine ? { line: normalizeConnectorLineOverrides(authoredLine, 'slide.add_connector line') } : {}),
		})
		opts = applyConnectorStyleComposition(opts, state).options
	}
	const { anims, cleaned } = liftAnimations(opts)
	if (typeof slide.addConnector !== 'function') throw new Error('Native connector authoring requires a runtime with slide.addConnector support.')
	slide.addConnector(cleaned)
	applyAnimations(slide, anims)
	return { ok: true, slideIndex: args.slideIndex, connectorType: cleaned.connectorType || 'straightConnector1', nativeObject: 'connector', animationsApplied: anims.length }
}

async function handleAddGroup(args, context = {}) {
	const slide = getSlide(args.deckId, args.slideIndex)
	const opts = { ...(args.options || {}) }
	if (args.children !== undefined) opts.children = args.children
	if (args.objectName !== undefined) opts.objectName = args.objectName
	const structuralInput = Object.fromEntries(['kind', 'x', 'y', 'w', 'h', 'rotation', 'rotate', 'flipH', 'flipV', 'chOff', 'chExt', 'children', 'objectName', 'editHandle', 'altText'].filter(key => opts[key] !== undefined).map(key => [key, opts[key]]))
	const normalizedStructural = normalizeStructuralGroup(structuralInput, 'slide.add_group')
	for (const key of ['x', 'y', 'w', 'h', 'rotation', 'rotate', 'flipH', 'flipV', 'chOff', 'chExt', 'children', 'objectName', 'editHandle', 'altText']) if (Object.prototype.hasOwnProperty.call(normalizedStructural, key)) opts[key] = normalizedStructural[key]
	Object.assign(opts, normalizeInternalAccessibilityMetadata(opts, 'slide.add_group options'))
	const { anims, cleaned } = liftAnimations(opts)
	if (typeof slide.addGroup !== 'function') throw new Error('Native group authoring requires a runtime with slide.addGroup support.')
	const materializeGroupLeaves = async children => {
		for (const child of children || []) {
			if (Array.isArray(child.children)) await materializeGroupLeaves(child.children)
			if (child.kind === 'connector') {
				const options = { ...child.style, x: child.x, y: child.y, w: child.w, h: child.h, objectName: child.objectName || child.name }
				for (const key of ['connectorType', 'routing', 'startShapeId', 'startConnectionIndex', 'endShapeId', 'endConnectionIndex', 'connectorStylePresetId', 'line', 'rotate', 'flipH', 'flipV', 'altText', ...CONNECTOR_EFFECT_FIELDS]) {
					if (Object.prototype.hasOwnProperty.call(child, key)) options[key] = child[key]
				}
				const before = slide._slideObjects.length
				await handleAddConnector({ deckId: args.deckId, slideIndex: args.slideIndex, options })
				const prepared = slide._slideObjects.splice(before)
				if (prepared.length !== 1 || prepared[0]?._type !== 'connector') throw new Error('A native group connector must materialize as exactly one editable connector.')
				child._nativeObject = prepared[0]
				continue
			}
			if (!['image', 'image-feature'].includes(child.kind)) continue
			const imageOptions = { ...child.style, ...child.imageOptions, x: child.x, y: child.y, w: child.w, h: child.h, objectName: child.objectName || child.name, ...(child.altText !== undefined ? { altText: child.altText } : {}) }
			if (child.source !== undefined) imageOptions.source = child.source
			if (child.assetRef !== undefined) imageOptions.path = child.assetRef
			if (child.data !== undefined) imageOptions.data = child.data
			if (child.path !== undefined) imageOptions.path = child.path
			const before = slide._slideObjects.length
			await handleAddImage({ deckId: args.deckId, slideIndex: args.slideIndex, options: imageOptions }, { ...context, __specCompiler: true })
			const prepared = slide._slideObjects.splice(before)
			if (prepared.length !== 1 || prepared[0]?._type !== 'image') throw new Error('A native group picture must materialize as exactly one editable image.')
			child._nativeObject = prepared[0]
		}
	}
	await materializeGroupLeaves(cleaned.children)
	slide.addGroup(cleaned)
	applyAnimations(slide, anims)
	return { ok: true, slideIndex: args.slideIndex, nativeObject: 'group', childCount: Array.isArray(cleaned.children) ? cleaned.children.length : 0, animationsApplied: anims.length }
}

async function handleAddSmartArt(args) {
	const slide = getSlide(args.deckId, args.slideIndex)
	const opts = args.options ? { ...args.options } : {}
	for (const key of ['mode', 'native', 'layout', 'layoutId', 'layoutName', 'quickStyleId', 'quickStyleName', 'colorStyleId', 'colorStyleName', 'presetFallback', 'rightToLeft', 'nodes', 'x', 'y', 'w', 'h', 'title', 'accessibilityTitle', 'altText', 'isDecorative', 'objectName', 'palette', 'fill', 'line', 'shadow', 'fontFace', 'fontSize', 'color', 'textColors', 'animation']) {
		if (args[key] !== undefined) opts[key] = args[key]
	}
	const normalizedSmartArt = normalizeSmartArtOptions(opts, 'slide.add_smartart options')
	for (const key of Object.keys(opts)) delete opts[key]
	Object.assign(opts, normalizedSmartArt)
	Object.assign(opts, normalizeInternalAccessibilityMetadata(opts, 'slide.add_smartart options'))
	if (opts.mode === undefined && opts.native === undefined) opts.mode = 'native'
	const picturePolicy = await enforceSmartArtPictureImages(opts)
	await enforceSmartArtNodeRoles(opts, picturePolicy.resolvedLayout)
	enforceSmartArtNodeTopology(opts, picturePolicy.resolvedLayout)
	const before = Array.isArray(slide._slideObjects) ? slide._slideObjects.length : 0
	if (typeof slide.addSmartArt !== 'function') throw new Error('SmartArt diagram authoring requires a runtime with slide.addSmartArt support.')
	slide.addSmartArt(opts)
	const after = Array.isArray(slide._slideObjects) ? slide._slideObjects.length : before
	return {
		ok: true,
		slideIndex: args.slideIndex,
		mode: opts.mode || (opts.native ? 'native' : 'shape'),
		layout: opts.layout || 'process',
		nodes: Array.isArray(opts.nodes) ? opts.nodes.length : 3,
		pictureImageNodes: picturePolicy.imageNodeCount,
		objectsAdded: after - before,
	}
}

// Resolve an icon front-door request to a themed PNG data URI. Lucide icons are
// stroke-based SVGs that DO NOT rasterize in the PowerPoint export path; sharp renders
// them to a crisp PNG that does. Two looks: 'plain' (accent glyph on transparent) and
// 'chip' (glyph centered on a rounded accent tile). Colors are pre-resolved by the compiler
// (accent ensured visible on canvas; chip glyph auto-contrasted) so this stays theme-free.
async function materializeIconPng(iconSource = {}) {
	const { icon, query, glyphColor = '64748B', chipColor = null, style = 'plain', cornerRadius = 0, sizePx = 512 } = iconSource || {}
	// Every icon SET (Lucide + Tabler/Iconoir/Phosphor) is monochrome `currentColor` SVG, so the
	// recolor below themes any of them. Dirs are ordered by ASSET_CATALOG preference (Lucide
	// first), so a bare name resolves to the house default and only falls through to other sets
	// for coverage gaps. Prefix a name with a set — icon:"phosphor/heart" — to force one style.
	const iconSetDirs = ASSET_CATALOG.filter(s => s.kind === 'icon').map(s => ({ source: s.source, dir: path.resolve(ASSETS_ROOT, s.root) }))
	const iconSetByName = new Map(iconSetDirs.map(s => [s.source, s.dir]))
	const normBase = value => String(value).trim().toLowerCase().replace(/\s+/g, '-').replace(/\.svg$/i, '')
	const fileInDir = (dir, base) => { const cand = path.join(dir, `${base}.svg`); return dir && fsNode.existsSync(cand) ? cand : null }
	const asSvgFile = value => {
		if (!value) return null
		const raw = String(value).trim()
		const slash = raw.indexOf('/')
		if (slash > 0) {
			// "set/name" targets one set explicitly (e.g. phosphor/heart-fill).
			const setDir = iconSetByName.get(raw.slice(0, slash).toLowerCase())
			if (setDir) { const hit = fileInDir(setDir, normBase(raw.slice(slash + 1))); if (hit) return hit }
		}
		const base = normBase(raw)
		for (const { dir } of iconSetDirs) { const hit = fileInDir(dir, base); if (hit) return hit }
		return null
	}
	const asIconSvg = value => (typeof value === 'string' && /\.svg$/i.test(value) && fsNode.existsSync(value) &&
		iconSetDirs.some(s => value.replace(/\\/g, '/').toLowerCase().startsWith(s.dir.replace(/\\/g, '/').toLowerCase()))) ? value : null
	// Resolution order — prefer an EXACT glyph name over a fuzzy semantic match (an author
	// who writes "shield" means the shield glyph, not the catalog's ranked guess):
	//   1) explicit icon name (or set/name), 2) whole query as a name, 3) any query word,
	//   4) semantic ranking across ALL icon sets.
	let svgPath = asSvgFile(icon) || asSvgFile(query)
	if (!svgPath && (query || icon)) {
		for (const w of String(query || icon || '').toLowerCase().split(/[\s,/]+/).filter(Boolean)) {
			svgPath = asSvgFile(w)
			if (svgPath) break
		}
	}
	if (!svgPath && (query || icon)) {
		try {
			const res = listAssetFiles({ kind: 'icon', query: String(query || icon), maxResults: 1 })
			const top = (res?.results || [])[0]
			svgPath = asIconSvg(top?.path) || asSvgFile(top?.name || top?.title)
		} catch { /* fall through */ }
	}
	if (!svgPath) throw new Error(`icon: could not resolve "${icon || query || ''}" to a catalog glyph.`)
	{
		const head = (await fs.readFile(svgPath, 'utf-8')).slice(0, 400).toLowerCase()
		if (!head.includes('<svg')) throw new Error(`icon: resolved asset for "${icon || query || ''}" is not an SVG glyph.`)
	}
	const glyphHex = String(glyphColor).replace(/^#/, '') || '64748B'
	let svg = (await fs.readFile(svgPath, 'utf-8')).replace(/currentColor/g, `#${glyphHex}`)
	const sharp = (await import('sharp')).default
	const px = Math.max(64, Math.min(2048, Number(sizePx) || 512))
	if (style === 'chip' && chipColor) {
		const chipHex = String(chipColor).replace(/^#/, '')
		const pad = Math.round(px * 0.22)
		const glyph = await sharp(Buffer.from(svg)).resize(px - pad * 2, px - pad * 2, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } }).png().toBuffer()
		const r = Math.round(px * Math.min(0.5, Math.max(0, Number(cornerRadius) || 0)))
		const tileSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="${px}" height="${px}"><rect width="${px}" height="${px}" rx="${r}" ry="${r}" fill="#${chipHex}"/></svg>`
		const tile = await sharp(Buffer.from(tileSvg)).png().toBuffer()
		const composed = await sharp(tile).composite([{ input: glyph, top: pad, left: pad }]).png().toBuffer()
		return `data:image/png;base64,${composed.toString('base64')}`
	}
	const png = await sharp(Buffer.from(svg)).resize(px, px, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } }).png().toBuffer()
	return `data:image/png;base64,${png.toString('base64')}`
}

async function handleAddImage(args, context = {}) {
	const slide = getSlide(args.deckId, args.slideIndex)
	let inOptions = args.options ? { ...args.options } : {}
	// The canonical public lane is closed and source-first. Internal compiler
	// routes that materialize generated/icon/legacy sources remain compatible,
	// but cannot be mistaken for the exact public operation contract.
	if (Object.prototype.hasOwnProperty.call(inOptions, 'source')) {
		if (context.__specCompiler === true) {
			const publicKeys = new Set(Object.keys(ADD_IMAGE_AUTHORING_CORE_SCHEMA.properties))
			const publicOptions = Object.fromEntries(Object.entries(inOptions).filter(([key]) => publicKeys.has(key)))
			const compilerSizing = publicOptions.sizing
			if (compilerSizing && typeof compilerSizing === 'object' && compilerSizing.type) publicOptions.sizing = { type: compilerSizing.type }
			inOptions = {
				...inOptions,
				...validateAddImageAuthoringCore(publicOptions, 'slide.add_image options'),
				...(compilerSizing !== undefined ? { sizing: compilerSizing } : {}),
			}
		} else {
			inOptions = validateAddImageAuthoringCore(inOptions, 'slide.add_image options')
		}
	}
	let authoredImageSource = null
	if (Object.prototype.hasOwnProperty.call(inOptions, 'source')) {
		const source = validateImageAssetSource(inOptions.source, 'slide.add_image options.source')
		if (source === null) throw new Error('slide.add_image options.source cannot be null when creating a picture.')
		authoredImageSource = Object.freeze({ ...source })
		delete inOptions.source
		if (source.kind === 'inline') inOptions.data = source.data
		else if (source.kind === 'https') inOptions.path = source.url
		else inOptions.path = source.ref
	}
	if (!authoredImageSource) authoredImageSource = publicSourceDescriptorForOptions(inOptions, 'image')
	if (Object.prototype.hasOwnProperty.call(inOptions, 'pictureAdjuncts')) {
		const adjuncts = validatePictureAdjuncts(inOptions.pictureAdjuncts, 'slide.add_image options.pictureAdjuncts')
		delete inOptions.pictureAdjuncts
		if (adjuncts) {
			if (Object.prototype.hasOwnProperty.call(adjuncts, 'rounding')) inOptions.rounding = adjuncts.rounding
			if (Object.prototype.hasOwnProperty.call(adjuncts, 'hyperlink')) inOptions.hyperlink = adjuncts.hyperlink
			if (Object.prototype.hasOwnProperty.call(adjuncts, 'placeholder')) {
				const placeholder = adjuncts.placeholder
				if (placeholder && typeof placeholder === 'object') {
					inOptions.placeholder = placeholder.type
					inOptions.phType = placeholder.type
					if (placeholder.idx !== undefined) inOptions.phIdx = placeholder.idx
					if (placeholder.size !== undefined) inOptions.phSz = placeholder.size
					if (placeholder.orient !== undefined) inOptions.phOrient = placeholder.orient
					if (placeholder.hasCustomPrompt !== undefined) inOptions.phHasCustomPrompt = placeholder.hasCustomPrompt
				} else {
					inOptions.placeholder = placeholder
					inOptions.phType = placeholder
				}
			}
		}
	}
	if (inOptions.imageAccessibility !== undefined) {
		const accessibility = validateImageAccessibilityOptions(inOptions.imageAccessibility, 'slide.add_image options.imageAccessibility')
		if (accessibility && Object.prototype.hasOwnProperty.call(accessibility, 'altText')) inOptions.altText = accessibility.altText
		delete inOptions.imageAccessibility
	}
	if (Object.prototype.hasOwnProperty.call(inOptions, 'altText')) validateImageAltText(inOptions.altText, 'slide.add_image options.altText')
	const authoredPictureOptions = { ...inOptions }
	const pictureStylePresetId = args.pictureStylePresetId || inOptions.pictureStylePresetId
	if (pictureStylePresetId) {
		const preset = pictureStylePresetById(pictureStylePresetId)
		if (!preset) throw new Error(`Unknown picture style preset: ${pictureStylePresetId}`)
		inOptions = applyPictureStylePreset(inOptions, pictureStylePresetId).options
		delete inOptions.pictureStylePresetId
	}
	let contextualGeneration = null
	// Authoring Excellence Visual Director: a semantic image block can reach commit with a
	// deterministic visualGeneration brief instead of a pre-generated handle. Generate once,
	// persist tenant-safely, then continue through the exact same gen:// materialization path.
	if (inOptions && typeof inOptions === 'object' && inOptions.visualGeneration && !inOptions.data && !inOptions.path && !inOptions.url) {
		const plan = inOptions.visualGeneration
		const generated = await ensureGeneratedImage(plan.request || {}, context)
		inOptions = { ...inOptions, path: generated.handle }
		authoredImageSource = Object.freeze({ kind: 'asset', ref: generated.handle })
		delete inOptions.visualGeneration
		contextualGeneration = { planId: plan.id || null, handle: generated.handle, cached: generated.cached === true, gpuSeconds: generated.gpuSeconds || 0, qa: generated.qa }
	}
	// Icon front-door: an {kind:'icon'} block compiles to add_image carrying an iconSource.
	// Resolve a native Lucide glyph → themed PNG here (SVG images don't rasterize in the
	// PowerPoint export path; a PNG does). The compiler already resolved the theme colors.
	if (inOptions && typeof inOptions === 'object' && inOptions.iconSource && !inOptions.data && !inOptions.path && !inOptions.url) {
		const data = await materializeIconPng(inOptions.iconSource)
		inOptions = { ...inOptions, data }
	}
	if (inOptions && typeof inOptions === 'object' && 'iconSource' in inOptions) {
		inOptions = { ...inOptions }
		delete inOptions.iconSource
	}
	const resolvedOptions = resolveGeneratedAssetRefs(inOptions)
	// gen:// sources embed a cached Flux generation (data URI) + record the Apache-2.0 license on
	// the deck. Runs BEFORE stock/remote (a gen:// handle is neither a stock handle nor a URL).
	const genResolved = await materializeGeneratedImageOptions(resolvedOptions, args.deckId, context)
	// M21 — stock:// sources resolve through the licensed providers (Pexels/Pixabay);
	// the license record lands on the deck (export/deckMeta) and the fetch flows through
	// the same safe remote materialization as any URL.
	const stockResolved = await materializeStockImageOptions(genResolved, args.deckId)
	const materializedOptions = await materializeRemoteImageOptions(stockResolved)
	// All materialized image sources (generated, stock, remote, and local)
	// should use their real raster dimensions when semantic sizing is
	// serialized. Remote/stock images are materialized to a private local path,
	// while generated images generally arrive as inline data.
	let measuredOptions = materializedOptions
	if (measuredOptions && typeof measuredOptions === 'object'
		&& !(Number(measuredOptions._imageSourceW) > 0 && Number(measuredOptions._imageSourceH) > 0)) {
		try {
			let imageInput = null
			if (typeof measuredOptions.data === 'string' && /^data:image\//i.test(measuredOptions.data)) {
				const comma = measuredOptions.data.indexOf(',')
				imageInput = comma >= 0 ? Buffer.from(measuredOptions.data.slice(comma + 1), 'base64') : null
			} else if (typeof measuredOptions.path === 'string' && measuredOptions.path && !isRemoteUrl(measuredOptions.path)) {
				imageInput = measuredOptions.path
			}
			const metadata = imageInput ? await sharp(imageInput).metadata() : null
			if (Number(metadata?.width) > 0 && Number(metadata?.height) > 0) {
				measuredOptions = { ...measuredOptions, _imageSourceW: Number(metadata.width), _imageSourceH: Number(metadata.height) }
			}
		} catch { /* dimensions are advisory; serializer retains deterministic fallback */ }
	}
	// M21 — declarative raster ops (internal sharp engine; percent regions, deterministic).
	const opsApplied = await applyImageOpsToOptions(measuredOptions)
	const normalizedOptions = normalizeVisualOptions(opsApplied, 'slide.add_image options')
	if (authoredImageSource) normalizedOptions._authoredImageSource = authoredImageSource
	const authoredNormalizedOptions = normalizeVisualOptions(authoredPictureOptions, 'slide.add_image authored options') || {}
	const authoredPictureStyle = Object.prototype.hasOwnProperty.call(authoredNormalizedOptions, 'pictureStyle') ? authoredNormalizedOptions.pictureStyle : undefined
	const authoredPictureStyleOwns = component => authoredPictureStyle && typeof authoredPictureStyle === 'object' && Object.prototype.hasOwnProperty.call(authoredPictureStyle, component)
	if (Object.prototype.hasOwnProperty.call(authoredNormalizedOptions, 'pictureStyle')) {
		if (authoredPictureStyle === null || authoredPictureStyleOwns('geometry')) delete normalizedOptions._rawPicPrstGeomXml
		if (authoredPictureStyle === null || authoredPictureStyleOwns('fill')) delete normalizedOptions._rawFillXml
		if (authoredPictureStyle === null || authoredPictureStyleOwns('line')) delete normalizedOptions._rawLineXml
		if (authoredPictureStyle === null || authoredPictureStyleOwns('effects')) delete normalizedOptions._rawEffectLstXml
		if (authoredPictureStyle === null || authoredPictureStyleOwns('threeD')) delete normalizedOptions._rawSpPrScene3dXml
	}
	if (_patchHasAny(authoredNormalizedOptions, RAW_EFFECT_PATCH_KEYS)) {
		delete normalizedOptions._rawEffectLstXml
		if (!authoredPictureStyleOwns('effects') && normalizedOptions.pictureStyle && typeof normalizedOptions.pictureStyle === 'object') delete normalizedOptions.pictureStyle.effects
	}
	if (_patchHasAny(authoredNormalizedOptions, RAW_LINE_PATCH_KEYS)) {
		delete normalizedOptions._rawLineXml
		if (!authoredPictureStyleOwns('line') && normalizedOptions.pictureStyle && typeof normalizedOptions.pictureStyle === 'object') delete normalizedOptions.pictureStyle.line
	}
	if (Object.prototype.hasOwnProperty.call(authoredNormalizedOptions, 'fill')) {
		delete normalizedOptions._rawFillXml
		if (!authoredPictureStyleOwns('fill') && normalizedOptions.pictureStyle && typeof normalizedOptions.pictureStyle === 'object') delete normalizedOptions.pictureStyle.fill
	}
	if (Object.prototype.hasOwnProperty.call(authoredNormalizedOptions, 'effect3D')) {
		delete normalizedOptions._rawSpPrScene3dXml
		if (!authoredPictureStyleOwns('threeD') && normalizedOptions.pictureStyle && typeof normalizedOptions.pictureStyle === 'object') delete normalizedOptions.pictureStyle.threeD
	}
	if (Object.prototype.hasOwnProperty.call(authoredNormalizedOptions, 'transparency') || Object.prototype.hasOwnProperty.call(authoredNormalizedOptions, 'imageAdjustments')) {
		delete normalizedOptions._rawBlipInnerXml
		if (_patchHasPictureExtAdjustment(authoredNormalizedOptions)) delete normalizedOptions._rawBlipExtLstXml
	}
	const { anims, cleaned } = liftAnimations(normalizedOptions)
	const previousObjectCount = slide._slideObjects?.length || 0
	slide.addImage(cleaned || {})
	// Layer semantics belong to the authored composition, not the picture's
	// closed formatting record. Retain only compiler-owned role metadata on
	// the image just inserted so validation and semantic replay use that role.
	if (context.__specCompiler === true && typeof cleaned?.role === 'string' && cleaned.role) {
		const inserted = (slide._slideObjects || []).slice(previousObjectCount).find(object => _shapeKind(object) === 'image')
		if (inserted) inserted.options.role = cleaned.role
	}
	applyAnimations(slide, anims)
	return {
		ok: true,
		slideIndex: args.slideIndex,
		animationsApplied: anims.length,
		...(contextualGeneration ? {
			contextualGeneration: { planId: contextualGeneration.planId, handle: contextualGeneration.handle, cached: contextualGeneration.cached, qualityGate: contextualGeneration.qa },
			imageCount: 1,
			cached: contextualGeneration.cached,
			_billing: { imageCount: 1, gpuSeconds: contextualGeneration.gpuSeconds, cached: contextualGeneration.cached },
		} : {}),
	}
}

// stock:// handle in path/url → provider resolve (license recorded on the deck entry,
// surfaced via deckMeta/export) → real URL (or data URI) for the standard fetch path.
async function materializeStockImageOptions(options, deckId) {
	if (!options || typeof options !== 'object' || Array.isArray(options)) return options
	const source = options.path || options.url || options.src || options.imageUrl
	const parsed = parseStockHandle(source)
	if (!parsed) return options
	const resolved = await resolveStockHandle(source)
	// SERVER/SERVICE cost only (content is free): record the resolve round-trip here, and the
	// payload size ONLY when the resolve returns inline data: bytes (internal test provider).
	// Real providers resolve to a remote URL whose true download bytes are metered downstream in
	// materializeRemoteImageOptions — so this does NOT double-count. Content licensing = free.
	const resolvedInlineBytes = /^data:/i.test(String(resolved.url || ''))
		? Math.floor(String(resolved.url).split(',')[1]?.length * 0.75 || 0)
		: 0
	recordResourceUsage({ externalCalls: 1, stockResolveBytes: resolvedInlineBytes })
	recordResourceLabels({ stockProvider: parsed.provider, stockKind: parsed.kind })
	registerDeckStockAsset(deckId, { handle: source, objectName: options.objectName || null, ...resolved.license })
	const { url: _url, src: _src, imageUrl: _imageUrl, ...rest } = options
	if (/^data:/i.test(resolved.url)) return { ...rest, path: undefined, data: resolved.url }
	return { ...rest, path: resolved.url }
}

function registerDeckStockAsset(deckId, record) {
	try {
		const entry = deckId ? decks.get(deckId) : null
		if (!entry) return
		entry.stockAssets ||= []
		entry.stockAssets.push(record)
	} catch { /* advisory */ }
}

// gen://flux/image/{hash} → the cached generated bytes (data URI) + an Apache-2.0 license record
// on the deck. The metered USD generation already happened at betterpptx.assets.generate_image
// time, so this ONLY embeds the cached result — it does not re-generate or re-meter the compute.
async function materializeGeneratedImageOptions(options, deckId, context = {}) {
	if (!options || typeof options !== 'object' || Array.isArray(options)) return options
	const source = options.path || options.url || options.src || options.imageUrl
	const parsed = parseGenHandle(source)
	if (!parsed) return options
	const productionPolicyError = generatedImageUnavailableInProductionError()
	if (productionPolicyError) throw productionPolicyError
	const cached = getCachedGeneratedImage(parsed.hash) || await hydrateGeneratedImage(parsed.hash, genAssetTenantFor(context))
	if (!cached) {
		const error = new Error(`gen: ${String(source)} has not been generated or is no longer available for this account — call betterpptx.assets.generate_image first, rehydrate a valid durable handle, or resolve the contextual visual again before compiling.`)
		error.code = 'GENERATED_IMAGE_ASSET_UNAVAILABLE'
		error.details = {
			handle: String(source),
			artifactState: 'unchanged_or_unknown',
			retrySafe: true,
			recovery: 'Use an authorized durable handle that resolves to the exact image bytes, or generate an approved supplied/native alternative.',
		}
		throw error
	}
	recordResourceLabels({ imageGenProvider: cached.provider, imageGenModel: cached.model })
	// Reuse the stock-asset license registry (generic): generated content has no author/sourceUrl.
	registerDeckStockAsset(deckId, { handle: source, objectName: options.objectName || null, provider: 'generated', id: parsed.hash, kind: 'image', ...publicGeneratedLicense('image'), retrievedAt: new Date().toISOString() })
	const { url: _url, src: _src, imageUrl: _imageUrl, path: _path, ...rest } = options
	return {
		...rest,
		data: cached.dataUri,
		// Private engine metadata for semantic cover/contain/crop framing.
		// It never crosses the public tool boundary or enters deck-facing text.
		...(Number(cached.width) > 0 ? { _imageSourceW: Number(cached.width) } : {}),
		...(Number(cached.height) > 0 ? { _imageSourceH: Number(cached.height) } : {}),
	}
}

// gen://trellis/rigged3d/{hash} → the cached rigged GLB written to a temp .glb file (slide.addModel3D
// reads glbFile as a real path). Self-hosted assets are PoC-only; only the personalized Meshy → Mixamo
// pipeline carries a production native-3D license record. The metered GPU generation already
// happened at betterpptx.assets.generate_rigged3d time, so this ONLY embeds the cached result — it does
// not re-generate or re-meter the compute. Mirrors materializeGeneratedImageOptions (bytes→file, not data URI).
async function materializeGeneratedRigged3dOptions(options, deckId) {
	if (!options || typeof options !== 'object' || Array.isArray(options)) return options
	const source = options.glbFile || options.modelAsset || options.model || options.path || options.url
	const parsed = parseGenRigged3dHandle(source)
	if (!parsed) return options
	const cached = getCachedGeneratedRigged3d(parsed.hash)
	if (!cached) {
		throw new Error(`${String(source)} was not generated in this session — call betterpptx.assets.generate_rigged3d first, then use the returned handle as glbFile.`)
	}
	recordResourceLabels({ model3dGenProvider: cached.provider, model3dGenModel: cached.model, model3dGenMeshResolution: cached.meshResolution })
	// Reuse the generic deck asset-license registry (generated content has no author/sourceUrl).
	const productionMeshyMixamo = cached.provider === 'meshy' || cached.tier === 'proven-mixamo'
	registerDeckStockAsset(deckId, { handle: source, objectName: options.objectName || null, provider: productionMeshyMixamo ? 'meshy-mixamo' : 'self-hosted-poc', id: parsed.hash, kind: 'rigged3d', ...(productionMeshyMixamo ? cached.license : publicPocNative3dLicense()), retrievedAt: new Date().toISOString() })
	const dir = path.join(os.tmpdir(), 'betterpptx-gen3d')
	await fs.mkdir(dir, { recursive: true })
	const glbPath = path.join(dir, `${parsed.hash}.glb`)
	await fs.writeFile(glbPath, Buffer.from(cached.glbBase64, 'base64'))
	const { glbFile: _g, modelAsset: _m, model: _mo, path: _p, url: _u, src: _s, ...rest } = options
	const resolved = { ...rest, glbFile: glbPath }
	// AUTO-POSTER: PowerPoint renders an am3d model EMPTY without a raster anchor, and the model3d builder
	// defaults to nativeOnly (no raster). If the baked asset carries a preview (Baker's TRANSPARENT front render)
	// and the caller supplied no poster of their own and did not force nativeOnly, write the preview out and
	// attach it — so EVERY baked presenter renders on the slide with zero per-deck poster wiring.
	// The caller's poster has already been normalized posterAsset -> rasterFile by the add_model3d handler
	// BEFORE this runs, so we key off rasterFile and set rasterFile (what pptxgenjs addModel3D actually reads).
	// We do NOT gate on nativeOnly: nativeOnly:true is the very default that makes the model render empty, so a
	// preview + no caller poster should always attach the raster (flipping nativeOnly off). Caller poster wins.
	const callerPoster = options.rasterFile || options.posterAsset || options.poster
	if (cached.previewBase64 && !callerPoster) {
		const posterPath = path.join(dir, `${parsed.hash}-poster.png`)
		await fs.writeFile(posterPath, Buffer.from(cached.previewBase64, 'base64'))
		resolved.rasterFile = posterPath
		resolved.nativeOnly = false
	}
	return resolved
}

async function applyImageOpsToOptions(options) {
	if (!options || typeof options !== 'object' || !Array.isArray(options.imageOps) || !options.imageOps.length) {
		if (options && typeof options === 'object' && 'imageOps' in options) {
			const { imageOps: _ops, ...rest } = options
			return rest
		}
		return options
	}
	const { imageOps, ...rest } = options
	let buffer = null
	if (typeof rest.data === 'string' && /^data:image\//i.test(rest.data)) {
		buffer = Buffer.from(rest.data.replace(/^data:image\/[a-z+.-]+;base64,/i, ''), 'base64')
	} else if (typeof rest.path === 'string' && rest.path && !isRemoteUrl(rest.path)) {
		buffer = await fs.readFile(path.resolve(rest.path))
	}
	if (!buffer) throw new Error('imageOps: the image source must be local bytes (data URI or file) after materialization.')
	const result = await applyImageOpsToBuffer(buffer, imageOps)
	// SERVER/SERVICE cost: the raster op count is the CPU driver; the metrology fit reads
	// imageOpsOps so this compute stops smearing onto perRichObject/perOutputMb.
	recordResourceUsage({ imageOpsOps: Math.max(0, Number(result.applied) || 0) })
	recordResourceLabels({ imageOps: String(result.applied) })
	const { path: _path, ...withoutPath } = rest
	return { ...withoutPath, data: `data:image/png;base64,${result.buffer.toString('base64')}` }
}

async function handleChartRecommend(args = {}) {
	const {
		CHART_PRESET_CATALOG,
		chartPresetById,
		listChartGalleryUiPresets,
		chartGalleryTilePresetById,
		publicChartGalleryTilePreset,
		listChartStylePresets,
		chartStylePresetById,
		publicChartStylePreset,
		chartStyleCoverageByType,
	} = await loadChartPresetModule()
	const {
		listPublicChartTreatmentPresets,
		chartTreatmentPresetById,
		publicChartTreatmentPreset,
	} = await loadChartTreatmentRuntimeModule()
	const limit = Math.max(1, Math.min(Number(args.limit || 8), CHART_PRESET_CATALOG.length))
	const offset = Math.max(0, Math.min(Number(args.offset || 0), CHART_PRESET_CATALOG.length))
	const format = args.format === 'full' ? 'full' : 'summary'
	const query = String(args.query || args.chartIntent || args.dataShape || args.category || '')
	if (args.chartPresetId && !chartPresetById(String(args.chartPresetId))) {
		throw new Error(`Chart preset not found: ${args.chartPresetId}`)
	}
	const requestedChartType = args.chartType || null
	const galleryLimit = Math.max(1, Math.min(Number(args.galleryLimit || 24), 48))
	const treatmentLimit = Math.max(1, Math.min(Number(args.treatmentLimit || 24), 48))
	const styleLimit = Math.max(1, Math.min(Number(args.styleLimit || 24), 48))
	const requestedGalleryKind = ['styles', 'colors', 'layouts'].includes(String(args.galleryKind || '').toLowerCase())
		? String(args.galleryKind).toLowerCase()
		: null
	const galleryKinds = requestedGalleryKind ? [requestedGalleryKind] : ['styles', 'colors', 'layouts']
	const galleryTiles = galleryKinds.flatMap(galleryKind => listChartGalleryUiPresets({ chartType: requestedChartType, galleryKind, limit: galleryLimit }))
		.map(publicChartGalleryTilePreset)
	const stylePresets = listChartStylePresets({ chartType: requestedChartType, limit: styleLimit })
		.map(publicChartStylePreset)
	const treatmentPresets = listPublicChartTreatmentPresets({ chartType: requestedChartType || undefined, limit: treatmentLimit })
	if (args.chartGalleryTilePresetId) {
		const tile = chartGalleryTilePresetById(String(args.chartGalleryTilePresetId), {
			chartType: requestedChartType || undefined,
			...(requestedGalleryKind ? { galleryKind: requestedGalleryKind } : {}),
		})
		if (!tile) throw new Error(`Chart Ribbon tile preset not found or not applicable: ${args.chartGalleryTilePresetId}`)
	}
	if (args.chartStylePresetId) {
		const style = chartStylePresetById(String(args.chartStylePresetId))
		if (!style || (requestedChartType && !style.supportedChartTypes.includes(requestedChartType))) {
			throw new Error(`Chart style preset not found or not applicable: ${args.chartStylePresetId}`)
		}
	}
	const searchTokens = unrankedCatalogTokens(query, args.requireFeatures)
	const allPresets = CHART_PRESET_CATALOG
		.filter(preset => !args.chartPresetId || preset.id === String(args.chartPresetId))
		.filter(preset => !args.authoringMode || preset.authoringMode === args.authoringMode)
		.filter(preset => !requestedChartType || preset.chartType === requestedChartType || preset.chartTypes?.includes(requestedChartType))
		.filter(preset => !args.category || String(preset.powerPointCategory || '').toLowerCase() === String(args.category).toLowerCase())
		.map(preset => publicChartPreset(preset, format === 'full'))
		.filter(preset => catalogEntryContainsAll(preset, searchTokens))
		.sort((a, b) => String(a.id).localeCompare(String(b.id)))
	const presets = allPresets.slice(offset, offset + limit)
	const selectedTreatmentIds = [
		...(args.chartTreatmentPresetId ? [String(args.chartTreatmentPresetId)] : []),
		...(Array.isArray(args.chartTreatmentPresetIds) ? args.chartTreatmentPresetIds.map(String) : []),
	]
	for (const id of selectedTreatmentIds) {
		const treatment = chartTreatmentPresetById(id)
		if (!treatment) throw new Error(`Chart treatment preset not found: ${id}`)
		if (requestedChartType && treatment.preset.semanticType !== requestedChartType) {
			throw new Error(`Chart treatment preset ${id} is not applicable to ${requestedChartType}`)
		}
	}
	return {
		brand: BETTERPPTX_BRAND,
		contractVersion: 'betterpptx.unranked-chart-catalog.v1',
		selectionAuthority: 'ai',
		engineRole: 'catalog-filter-and-exact-id-validator',
		selectionManifestContract: publicSelectionManifestContract('chart'),
		unranked: true,
		catalogOrder: 'id-ascending',
		compatibilityAlias: 'betterpptx.chart.recommend',
		query,
		chartIntent: args.chartIntent || null,
		dataShape: args.dataShape || null,
		pagination: { offset, limit, returned: presets.length, totalMatches: allPresets.length, hasMore: offset + presets.length < allPresets.length },
		nativeChartTypes: ['area', 'bar', 'bar3D', 'bubble', 'bubble3D', 'doughnut', 'line', 'pie', 'radar', 'scatter', 'treemap', 'sunburst', 'histogram', 'pareto', 'boxWhisker', 'waterfall', 'funnel', 'regionMap'],
		pickerCategoryPolicy: {
			native: ['Column via bar + barDir=col', 'Bar', 'Line', 'Pie', 'Doughnut', 'Area', 'X Y (Scatter)', 'Bubble', 'Radar', 'Combo from supported native base types', 'Treemap', 'Sunburst', 'Histogram', 'Pareto', 'Box & Whisker', 'Waterfall', 'Funnel', 'Filled Map / regionMap'],
			shapeBuiltOrPreserveOnly: ['Stock', 'Surface'],
			rule: 'Use preset.chartType as slide.add_chart chartType when authoringMode is native. ChartEx picker families are native-editable for new authoring; exact imported ChartEx stays passthrough until the first update_chart edit promotes it to native editable ChartEx.',
		},
		presets,
		catalog: {
			galleryTiles,
			stylePresets,
			treatmentPresets,
			coverage: chartStyleCoverageByType(requestedChartType || undefined),
		},
		selectedPlan: (selectedTreatmentIds.length || args.chartPresetId || args.chartGalleryTilePresetId || args.chartStylePresetId)
			? {
				...(args.chartPresetId ? { chartPresetId: String(args.chartPresetId) } : {}),
				...(requestedChartType ? { chartType: requestedChartType } : {}),
				...(args.chartGalleryTilePresetId ? { chartGalleryTilePresetId: String(args.chartGalleryTilePresetId) } : {}),
				...(args.chartStylePresetId ? { chartStylePresetId: String(args.chartStylePresetId) } : {}),
				...(selectedTreatmentIds.length ? { chartTreatmentPresetIds: selectedTreatmentIds } : {}),
			}
			: null,
	}
}

