function normalizeMcpChartData(chartType, data) {
	const type = typeof chartType === 'string' ? chartType : ''
	if (!Array.isArray(data)) return data
	if (!['scatter', 'bubble', 'bubble3D'].includes(type)) return data
	const hasShorthand = data.some(item => item && (Array.isArray(item.xValues) || Array.isArray(item.yValues)))
	if (!hasShorthand) return data
	const first = data.find(item => item && Array.isArray(item.xValues)) || data[0] || {}
	const xValues = Array.isArray(first.xValues) ? first.xValues : Array.from({ length: Math.max(...data.map(item => Array.isArray(item?.yValues) ? item.yValues.length : 0), 0) }, (_v, index) => index + 1)
	const series = data.map((item, index) => ({
		name: item?.name || `Series ${index + 1}`,
		values: Array.isArray(item?.yValues) ? item.yValues : (Array.isArray(item?.values) ? item.values : []),
		...(Array.isArray(item?.sizes) ? { sizes: item.sizes } : {}),
	})).filter(item => item.values.length > 0)
	return [{ name: 'X-Axis', values: xValues }, ...series]
}

function normalizeMcpChartMulti(chartMulti) {
	if (!Array.isArray(chartMulti)) return chartMulti
	return chartMulti.map(item => {
		if (!item || typeof item !== 'object') return item
		return { ...item, data: normalizeMcpChartData(item.type, item.data) }
	})
}

async function handleAddChart(args, context = {}) {
	const validationArgs = context.__specCompiler === true && args.options && typeof args.options === 'object'
		? { ...args, options: Object.fromEntries(Object.entries(args.options).filter(([key]) => key !== '_authoringExplicitOptionKeys')) }
		: args
	validateDirectChartAdd(validationArgs)
	const slide = getSlide(args.deckId, args.slideIndex)
	const selectorKeys = [
		'chartPresetId', 'chartGalleryTilePresetId', 'chartStylePresetId',
		'chartGalleryVariant', 'chartStyleId', 'chartStyleModernId',
		'chartColorStyleId', 'chartLayoutPresetId', 'chartTreatmentPresetId',
		'chartTreatmentPresetIds',
	]
	const requestedOptions = {
		...(args.options && typeof args.options === 'object' ? args.options : {}),
		...Object.fromEntries(selectorKeys.filter(key => args[key] !== undefined).map(key => [key, args[key]])),
	}
	const chartPlan = await resolveProductChartPlan({ chartType: args.chartType, chartMulti: args.chartMulti, options: requestedOptions })
	// Catalog plans supply native resources/defaults; explicit AI options remain
	// authoritative and therefore win after plan resolution.
	const resolvedOptions = mergeResolvedChartOptions(chartPlan.plan || {}, requestedOptions)
	const selectedChartType = chartPlan.selectedChartType || args.chartType
	const { anims, cleaned } = liftAnimations(resolvedOptions)
	const authoredSelectors = Object.fromEntries(CHART_SELECTOR_FIELDS.filter(key => requestedOptions[key] !== undefined && requestedOptions[key] !== null).map(key => [key, requestedOptions[key]]))
	const authoredState = authoredChartState(authoredSelectors, args.options || {})
	const chartOptions = { ...(cleaned || {}), _chartAuthoringState: authoredState }
	if (args.chartMulti) {
		slide.addChart(normalizeMcpChartMulti(args.chartMulti), chartOptions)
	} else {
		slide.addChart(selectedChartType, normalizeMcpChartData(selectedChartType, args.data), chartOptions)
	}
	applyAnimations(slide, anims)
	return {
		ok: true,
		slideIndex: args.slideIndex,
		animationsApplied: anims.length,
		...(chartPlan.mode !== 'none' ? {
			chartPlan: {
				mode: chartPlan.mode,
				chartType: selectedChartType,
				...(requestedOptions.chartPresetId ? { chartPresetId: String(requestedOptions.chartPresetId) } : {}),
				...(requestedOptions.chartGalleryTilePresetId ? { chartGalleryTilePresetId: String(requestedOptions.chartGalleryTilePresetId) } : {}),
				...(requestedOptions.chartStylePresetId ? { chartStylePresetId: String(requestedOptions.chartStylePresetId) } : {}),
				...(requestedOptions.chartTreatmentPresetId ? { chartTreatmentPresetId: String(requestedOptions.chartTreatmentPresetId) } : {}),
				...(Array.isArray(requestedOptions.chartTreatmentPresetIds) ? { chartTreatmentPresetIds: requestedOptions.chartTreatmentPresetIds.map(String) } : {}),
			},
		} : {}),
	}
}

async function handleAddTable(args) {
	validateDirectTableAdd(args)
	const slide = getSlide(args.deckId, args.slideIndex)
	const requestedOptions = {
		...(args.options || {}),
		...Object.fromEntries(TABLE_SELECTOR_FIELDS.filter(key => args[key] !== undefined).map(key => [key, args[key]])),
	}
	const plan = await _resolveAuthoredTablePlan(requestedOptions, args.rows)
	const { anims, cleaned } = liftAnimations(plan.options)
	slide.addTable(plan.rows, cleaned || {})
	applyAnimations(slide, anims)
	return {
		ok: true,
		slideIndex: args.slideIndex,
		animationsApplied: anims.length,
		rows: plan.rows.length,
		columns: Math.max(0, ...plan.rows.map(row => row.length)),
		...(plan.state.selectors?.tablePresetId ? { tablePresetId: plan.state.selectors.tablePresetId } : {}),
		...(plan.state.selectors?.tableStylePresetId ? { tableStylePresetId: plan.state.selectors.tableStylePresetId } : {}),
		...(plan.options.tableStyleId ? { tableStyleId: plan.options.tableStyleId } : {}),
	}
}

function canonicalImageExtension(value) {
	const ext = String(value || '').toLowerCase().replace(/^\./, '')
	return ext === 'jpeg' ? 'jpg' : ext === 'tif' ? 'tiff' : ext
}

async function materializeMediaCoverDataUri(source) {
	if (source === undefined || source === null || source === '') return source
	if (typeof source !== 'string') throw new Error('media cover must be an authorized string reference or inline image data.')
	const materialized = await materializeSpecAssetSource({
		...(source.toLowerCase().includes('base64,') ? { data: source }
			: /^https?:\/\//i.test(source) ? { url: source }
				: /^asset:\/\/locked\//i.test(source) ? { handle: source }
					: { path: source }),
		kind: 'media cover',
		maxBytes: REMOTE_IMAGE_MAX_BYTES,
	})
	const bytes = Buffer.from(materialized.bytes || [])
	const detected = canonicalImageExtension(inferImageExtension('', bytes, ''))
	const declared = canonicalImageExtension(inferImageExtension(materialized.mimeType, null, source))
	if (!detected || !mimeForExt(detected).startsWith('image/')) {
		const error = new Error('media cover payload is not a supported image.')
		error.code = 'MEDIA_COVER_TYPE_INVALID'
		throw error
	}
	if (declared && declared !== detected) {
		const error = new Error(`media cover declared ${declared} but its bytes are ${detected}.`)
		error.code = 'MEDIA_COVER_TYPE_MISMATCH'
		throw error
	}
	return `data:${mimeForExt(detected)};base64,${bytes.toString('base64')}`
}

async function handleAddMedia(args, context = {}) {
	const slide = getSlide(args.deckId, args.slideIndex)
	let authoredOptions = args.options && typeof args.options === 'object' ? { ...args.options } : {}
	// Direct public creation is one closed, source-first operation. The spec
	// compiler retains a private compatibility lane for imported/generated
	// sources, but canonical compiler output is validated by the same contract.
	if (context.__specCompiler === true) {
		if (Object.prototype.hasOwnProperty.call(authoredOptions, 'source')) {
			const publicKeys = new Set(Object.keys(ADD_MEDIA_AUTHORING_CORE_SCHEMA.properties))
			const publicOptions = Object.fromEntries(Object.entries(authoredOptions).filter(([key]) => publicKeys.has(key)))
			authoredOptions = { ...authoredOptions, ...validateAddMediaAuthoringCore(publicOptions, 'slide.add_media options') }
		}
	} else {
		authoredOptions = validateAddMediaAuthoringCore(authoredOptions, 'slide.add_media options')
	}
	const commandTiming = authoredOptions.mediaCommandTiming
	delete authoredOptions.mediaCommandTiming
	if (commandTiming !== undefined) {
		const commands = Array.isArray(commandTiming) ? commandTiming : [commandTiming]
		const animations = commands.map(mediaCommandTimingAnimation).filter(Boolean)
		const existing = authoredOptions.animation === undefined
			? []
			: Array.isArray(authoredOptions.animation) ? authoredOptions.animation : [authoredOptions.animation]
		authoredOptions.animation = [...existing, ...animations]
	}
	const playbackContractKeys = ['type', 'extn', 'source', 'cover', 'sizing', 'transparency', 'rounding', 'interactivePlayback', 'mediaVolume', 'showWhenStopped', 'endOnStopAudio', 'closedCaptionTracks']
	const playbackContractInput = Object.fromEntries(playbackContractKeys
		.filter(key => Object.prototype.hasOwnProperty.call(authoredOptions, key))
		.map(key => [key, authoredOptions[key]]))
	const validatedPlayback = Object.keys(playbackContractInput).length
		? validateMediaAssetPlayback(playbackContractInput, 'add_media.options')
		: {}
	Object.assign(authoredOptions, validatedPlayback || {})
	if (Object.prototype.hasOwnProperty.call(authoredOptions, 'source')) {
		const source = authoredOptions.source
		if (source === null || source === '') throw new Error('add_media.options.source cannot be null when creating media.')
		delete authoredOptions.source
		if (String(authoredOptions.type || '').toLowerCase() === 'online') authoredOptions.link = source
		else if (/^data:/i.test(String(source))) authoredOptions.data = source
		else if (/^https:\/\//i.test(String(source))) authoredOptions.link = source
		else authoredOptions.path = source
	}
	const authoredMediaSource = publicSourceDescriptorForOptions(authoredOptions, 'media')
	const authoredMediaCover = authoredOptions.cover ? publicSourceDescriptorForOptions({ source: authoredOptions.cover }, 'media cover') : null
	let resolvedOptions = validateMediaFormatOptions(resolveGeneratedAssetRefs(authoredOptions) || {}, 'add_media.options')
	const recordStudioReserved = ['isNarration', '_nativeRecordStudioCapture', '_nativeRecordStudioOrigin', 'avatarFrameContract']
	const attemptedReserved = recordStudioReserved.filter(key => Object.prototype.hasOwnProperty.call(resolvedOptions, key))
	if (attemptedReserved.length) {
		const err = new Error('Generic media cannot declare Avatar talking-head identity. Author the talking-head video through the supported narration/Avatar semantic path.')
		err.code = 'NATIVE_RECORD_STUDIO_CAPTURE_REQUIRED'
		err.details = { reservedFields: attemptedReserved }
		throw err
	}
	// M21 — a stock:// video resolves through the licensed providers first; the license
	// record lands on the deck, then the standard link materialization downloads it.
	const stockSource = resolvedOptions.path || resolvedOptions.link || resolvedOptions.url
	const stockParsed = parseStockHandle(stockSource)
	if (stockParsed) {
		const resolved = await resolveStockHandle(stockSource)
		recordResourceUsage({ externalCalls: 1 })
		recordResourceLabels({ stockProvider: stockParsed.provider, stockKind: stockParsed.kind })
		registerDeckStockAsset(args.deckId, { handle: stockSource, objectName: resolvedOptions.objectName || null, ...resolved.license })
		const { path: _stockPath, url: _stockUrl, ...restOpts } = resolvedOptions
		resolvedOptions = { ...restOpts, link: resolved.url, type: resolvedOptions.type || (stockParsed.kind === 'audio' ? 'audio' : 'video') }
	}
	// Materialize a downloadable media LINK (a direct .mp4/.webm/.mp3 etc.) to a local
	// file before addMedia — pptxgenjs addMedia for a real video/audio needs `data`/`path`,
	// not a `link` (which only embeds a YouTube/Vimeo ONLINE player). This makes video/audio
	// premium-ingestible by link, the same way images already are. ONLINE embeds keep the link.
	const _link = resolvedOptions.link || resolvedOptions.url
	const _type = String(resolvedOptions.type || '').toLowerCase()
	const _isOnlineEmbed = _type === 'online' || /youtube\.com|youtu\.be|vimeo\.com|dailymotion\.com/i.test(String(_link || ''))
	if (_link && !resolvedOptions.path && !resolvedOptions.data && !_isOnlineEmbed) {
		const materialized = await materializeSpecAssetSource({
			url: resolvedOptions.url,
			link: resolvedOptions.link,
			kind: 'media',
			maxBytes: Number(process.env.BETTERPPTX_SPEC_RESOLVE_MAX_MEDIA_MB || 64) * 1048576,
		})
		assertRemoteMediaPayload(materialized, _type || 'video')
		const mime = materialized.mimeType || mimeForExt(materialized.extn) || 'video/mp4'
		// remote fetch returns bytes (no temp file) → embed as a data URI; a local path returns filePath.
		const sourced = materialized.filePath
			? { path: materialized.filePath }
			: { data: `data:${mime};base64,${Buffer.from(materialized.bytes).toString('base64')}` }
		resolvedOptions = { ...resolvedOptions, ...sourced, type: _type === 'online' || !_type ? 'video' : resolvedOptions.type }
		delete resolvedOptions.link
		delete resolvedOptions.url
		if (!resolvedOptions.extn && materialized.extn) resolvedOptions.extn = materialized.extn
	}
	if (authoredOptions.cover) resolvedOptions.cover = await materializeMediaCoverDataUri(authoredOptions.cover)
	const { anims, cleaned } = liftAnimations(resolvedOptions)
	const mediaOptions = cleaned || {}
	if (authoredMediaSource) mediaOptions._authoredMediaSource = authoredMediaSource
	if (authoredMediaCover) mediaOptions._authoredMediaCover = authoredMediaCover
	const authoredCommands = anims.filter(animation => String(animation?.type || '').toLowerCase() === 'media'
		|| String(animation?.effect || '').toLowerCase().startsWith('media')
		|| animation?.mediaCommand)
	if (authoredCommands.length) mediaOptions._authoredMediaCommands = authoredCommands.map(animation => ({ ...animation }))
	slide.addMedia(mediaOptions)
	applyAnimations(slide, anims)
	return { ok: true, slideIndex: args.slideIndex, animationsApplied: anims.length }
}

// Same pure source check/sampler is used in dryRun and at insertion. Resolve
// only already-authorized opaque assets: no arbitrary path or network fetch.
function prepareStaticPoseForAsset(modelAsset, request) {
	const staticPose = normalizeStaticPose(request)
	if (staticPose === undefined) throw staticPoseError('STATIC_POSE_INVALID', 'staticPose must specify motionId and timeMs, or null to restore the original pose.')
	let sourceBuffer
	try {
		const parsed = parseGenRigged3dHandle(modelAsset)
		if (parsed) {
			const cached = getCachedGeneratedRigged3d(parsed.hash)
			if (cached?.glbBase64) sourceBuffer = Buffer.from(cached.glbBase64, 'base64')
		} else if (isPublicSpecAssetRef(modelAsset)) {
			const resolved = resolveGeneratedAssetRefs(modelAsset)
			if (typeof resolved === 'string' && resolved !== modelAsset && fsNode.statSync(resolved).isFile()) sourceBuffer = fsNode.readFileSync(resolved)
		}
	} catch { /* Source details stay private; fail with an actionable public error. */ }
	if (!sourceBuffer) throw staticPoseError('STATIC_POSE_SOURCE_UNAVAILABLE', 'staticPose needs the original approved presenter asset to be available as an authorized asset handle before validation. Unresolved or remote-only sources are not supported.')
	if (staticPose === null) return { sourceBuffer, ...assertApprovedOrdinaryPresenterSource(sourceBuffer), report: { staticPose: null, appliesTo: 'stopped-edit-view', playbackStartOffsetApplied: false, animationDataPreserved: true, appearanceDataPreserved: true } }
	return { ...prepareApprovedPresenterStaticPose(sourceBuffer, staticPose), sourceBuffer }
}

function prepareMotionFramingForAsset(modelAsset, options = {}) {
	const motionFraming = normalizeModel3dMotionFraming(options.motionFraming)
	if (!motionFraming) throw motionFramingError('An explicit selected-motion framing request is required.')
	let sourceBuffer
	try {
		if (isPublicSpecAssetRef(modelAsset)) {
			const parsed = parseGenRigged3dHandle(modelAsset)
			if (parsed) {
				const cached = getCachedGeneratedRigged3d(parsed.hash)
				if (cached?.glbBase64) sourceBuffer = Buffer.from(cached.glbBase64, 'base64')
			} else {
				const resolved = resolveGeneratedAssetRefs(modelAsset)
				if (typeof resolved === 'string' && resolved !== modelAsset && fsNode.statSync(resolved).isFile()) sourceBuffer = fsNode.readFileSync(resolved)
			}
		}
	} catch { /* Never return paths or resolver details from the public lane. */ }
	if (!sourceBuffer) throw motionFramingError('Motion framing requires an available authorized 3-D asset handle; unresolved sources are not supported.', 'MODEL3D_MOTION_FRAMING_SOURCE_UNAVAILABLE')
	if (options.staticPose != null) sourceBuffer = prepareStaticPoseForAsset(modelAsset, options.staticPose).buffer
	try {
		const { mode: _mode, ...controls } = motionFraming
		return computeModel3dMotionFraming(sourceBuffer, { animationIndex: options.scene?.animId, frame: { w: options.w, h: options.h }, ...controls })
	} catch (error) {
		// The sampler's geometry and implementation diagnostics are maintainer
		// evidence, not public asset metadata or endpoint error text.
		throw motionFramingError('The selected 3-D motion or frame is not supported for automatic motion framing. Use a supported selected motion and frame, or ordinary view settings.', String(error?.code || '').startsWith('MODEL3D_MOTION_FRAMING_') ? error.code : 'MODEL3D_MOTION_FRAMING_UNSUPPORTED')
	}
}

async function handleAddModel3D(args, context = {}) {
	const slide = getSlide(args.deckId, args.slideIndex)
	let options = args.options ? { ...args.options } : {}
	const model3dViewPresetId = args.model3dViewPresetId || options.model3dViewPresetId
	const publicViewInput = Object.fromEntries(['model3dViewPresetId', 'camera', 'trans', 'ambientLight', 'ptLights', 'objViewport', 'nativeOnly', 'rotate', 'flipH', 'flipV', 'scene', 'posterAsset', 'staticPose', 'motionFraming'].filter(key => Object.prototype.hasOwnProperty.call(options, key)).map(key => [key, options[key]]))
	if (args.model3dViewPresetId !== undefined) publicViewInput.model3dViewPresetId = args.model3dViewPresetId
	normalizeModel3dOptions(publicViewInput, 'slide.add_model3d options')
	validateModel3DViewOptions(Object.fromEntries(['camera', 'trans', 'ambientLight', 'ptLights', 'objViewport'].filter(key => Object.prototype.hasOwnProperty.call(options, key)).map(key => [key, options[key]])), 'slide.add_model3d options')
	const authoredViewOverrides = {}
	for (const key of ['camera', 'trans', 'ambientLight', 'ptLights', 'objViewport']) {
		if (Object.prototype.hasOwnProperty.call(options, key)) authoredViewOverrides[key] = _deepCloneData(options[key])
	}
	if (model3dViewPresetId) {
		if (!model3dViewPresetById(model3dViewPresetId)) throw new Error(`Unknown Model 3D view preset: ${model3dViewPresetId}`)
		options = applyModel3dViewPreset(options, model3dViewPresetId).options
		// Keep the selector on the in-memory object for semantic export/readback,
		// while gen-model3d ignores this private bookkeeping field in its XML path.
		options._model3dViewPresetId = String(model3dViewPresetId)
		options._model3dAuthoredOverrides = authoredViewOverrides
		delete options.model3dViewPresetId
	} else if (Object.keys(authoredViewOverrides).length) {
		options._model3dAuthoredOverrides = authoredViewOverrides
	}
	// Normalize alternate handle aliases onto modelAsset for direct primitive callers.
	if (!options.modelAsset && (options.model3DAsset || options.model)) options.modelAsset = options.model3DAsset || options.model
	delete options.model3DAsset
	delete options.model
	// Semantic front-door safety net: the block authored intent (query/context) but no
	// resolver ran at compile time (e.g. a patch-only compile or a direct primitive call).
	// Resolve the best native catalog model now — same ranking as the compile-time pick.
	let selection = options._model3dSelection || null
	if (!options.modelAsset && !options.glbFile) {
		const picked = selectCatalogModel3d(options)
		if (picked) {
			options.modelAsset = picked.handle
			if (!options.posterAsset && picked.posterHandle) options.posterAsset = picked.posterHandle
			selection = { handle: picked.handle, title: picked.title, source: picked.source }
		}
	}
	// Selector/provenance fields must never reach pptxgenjs addModel3D.
	for (const key of ['query', 'context', 'prompt', 'intent', 'useCase', 'aiContext', 'sizePolicy', 'preferNative', 'maxModelSizeMb', 'kind3d', '_model3dSelection']) {
		delete options[key]
	}
	if (options.modelAsset && !options.glbFile) options.glbFile = options.modelAsset
	if (options.posterAsset && !options.rasterFile) options.rasterFile = options.posterAsset
	const originalModelRef = options.glbFile
	const originalPosterRef = options.rasterFile
	const staticPose = normalizeStaticPose(options.staticPose)
	const motionFraming = normalizeModel3dMotionFraming(options.motionFraming)
	if (options.scene !== undefined) options.scene = normalizeStaticPoseScene(options.scene, staticPose)
	delete options.staticPose
	delete options.motionFraming
	delete options.modelAsset
	delete options.posterAsset
	const resolvedOptions = resolveGeneratedAssetRefs(options)
	// gen://trellis/rigged3d/ → cached rigged GLB written to a temp .glb (glbFile path) + MIT license on
	// the deck. Runs for both direct add_model3d calls and the spec-first path (both route here).
	// G3: a gen:// handle may live only in the durable tenant store (restart / other instance) —
	// hydrate it into the process cache before the materializer resolves it.
	{
		const genSrc = resolvedOptions.glbFile || resolvedOptions.modelAsset || resolvedOptions.model || resolvedOptions.path || resolvedOptions.url
		const genParsed = parseGenRigged3dHandle(genSrc)
		if (genParsed && !getCachedGeneratedRigged3d(genParsed.hash)) await hydrateGeneratedRigged3d(genParsed.hash, genAssetTenantFor(context))
	}
	if (options.scene?.preparedVariantId !== undefined) {
		if (staticPose !== undefined) throw new Error('A prepared scene cannot use an ordinary staticPose selector.')
		const parsed = parseGenRigged3dHandle(originalModelRef)
		const preparedScene = resolvePreparedMotionScene(parsed ? getCachedGeneratedRigged3d(parsed.hash) : null, options.scene)
		options.scene = preparedScene; resolvedOptions.scene = preparedScene
	}
	const poseValidation = staticPose || options.scene?.motionId ? prepareStaticPoseForAsset(originalModelRef, staticPose) : null
	const posed = poseValidation?.buffer ? poseValidation : null
	const rigged3dResolved = await materializeGeneratedRigged3dOptions(resolvedOptions, args.deckId)
	let durableModelRef = isPublicSpecAssetRef(originalModelRef) ? originalModelRef : null
	let durablePosterRef = isPublicSpecAssetRef(originalPosterRef) ? originalPosterRef : null
	if (posed) {
		durableModelRef = lockGeneratedAssetBufferDescriptor(posed.sourceBuffer, 'model3d-source', { extn: 'glb' }).handle
		const derived = lockGeneratedAssetBufferDescriptor(posed.buffer, 'model3d-static-pose', { extn: 'glb' })
		rigged3dResolved.glbFile = resolveLockedAssetHandle(derived.handle)
		// Preserve the existing compatibility anchor, without rendering or changing
		// it. A native pose is not evidence that the raster fallback was re-posed.
		if (!durablePosterRef && rigged3dResolved.rasterFile && fsNode.existsSync(rigged3dResolved.rasterFile)) {
			durablePosterRef = lockGeneratedAssetBufferDescriptor(fsNode.readFileSync(rigged3dResolved.rasterFile), 'model3d-poster', { extn: path.extname(rigged3dResolved.rasterFile).slice(1) || 'png' }).handle
		}
	}
	let motionFramingReport = null
	if (motionFraming) {
		// Resolve only an already-authorized asset. Do not permit a new filesystem
		// or network source lane through this opt-in calculation.
		const fit = prepareMotionFramingForAsset(originalModelRef, { ...rigged3dResolved, staticPose, motionFraming })
		Object.assign(rigged3dResolved, { trans: fit.trans, camera: fit.camera, objViewport: fit.objViewport })
		motionFramingReport = fit.report
	}
	const { anims, cleaned } = liftAnimations(rigged3dResolved)
	slide.addModel3D(cleaned || {})
	const inserted = slide._slideObjects?.at(-1)
	if (inserted?.options) {
		if (durableModelRef) inserted.options._model3dSourceRef = durableModelRef
		if (durablePosterRef) inserted.options._model3dPosterRef = durablePosterRef
		if (staticPose !== undefined) inserted.options.staticPose = _deepCloneData(staticPose)
		if (motionFraming !== undefined) inserted.options.motionFraming = _deepCloneData(motionFraming)
		if (motionFramingReport) inserted.options._model3dMotionFramingReport = _deepCloneData(motionFramingReport)
		if (posed) inserted.options._model3dStaticPoseReport = _deepCloneData(posed.report)
	}
	applyAnimations(slide, anims)
	return { ok: true, slideIndex: args.slideIndex, animationsApplied: anims.length, ...(selection ? { model3d: selection } : {}), ...(posed ? { staticPose: posed.report } : {}) }
}

async function handleAddCameo(args) {
	const slide = getSlide(args.deckId, args.slideIndex)
	const options = args.options ? { ...args.options } : {}
	const { anims, cleaned } = liftAnimations(options)
	slide.addCameo(cleaned || {})
	applyAnimations(slide, anims)
	return { ok: true, slideIndex: args.slideIndex, animationsApplied: anims.length }
}

function zoomTargetSlideId(pptx, slide, obj) {
	const options = obj?.options || {}
	if (typeof options._betterpptxZoomTargetSlideId === 'string' && options._betterpptxZoomTargetSlideId.trim()) {
		return options._betterpptxZoomTargetSlideId.trim()
	}
	const relation = (slide?._rels || []).find(rel => Number(rel?.rId) === Number(options._zoomSlideRid) && String(rel?.data || '').toLowerCase() === 'slide')
	const targetSlideNumber = Number(relation?.Target || (Number(options._zoomSldId) - 255))
	return String(pptx?.slides?.[targetSlideNumber - 1]?._betterpptxSemanticId || '') || null
}

function normalizedZoomPatchGeometry(value, path) {
	if (value === null) return null
	if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`${path} must be a bbox object or null.`)
	const out = {}
	for (const key of ['x', 'y', 'w', 'h']) {
		const number = Number(value[key])
		if (!Number.isFinite(number)) throw new Error(`${path}.${key} must be a finite number.`)
		if ((key === 'w' || key === 'h') && number <= 0) throw new Error(`${path}.${key} must be greater than zero.`)
		out[key] = number
	}
	return out
}

// A Slide Zoom owns a coordinated Choice/Fallback pair plus thumbnail and
// target-slide relationships. Editing any semantic field therefore replaces
// the native object atomically instead of sending it through update_shape.
async function handleUpdateZoom(args) {
	const { pptx } = getDeck(args.deckId)
	const slide = getSlide(args.deckId, args.slideIndex)
	const resolved = _resolveTypedShape(slide, args.target, ['zoom'], 'deck.generate_from_spec slideZoom patch')
	const current = resolved.obj
	const currentOptions = current.options || {}
	const patch = args.patch && typeof args.patch === 'object' && !Array.isArray(args.patch) ? { ...args.patch } : {}
	if (Object.prototype.hasOwnProperty.call(patch, 'bbox') && Object.prototype.hasOwnProperty.call(patch, 'rect')) {
		throw new Error('slideZoom patch cannot provide both bbox and rect.')
	}

	const currentTargetSlideId = zoomTargetSlideId(pptx, slide, current)
	const targetSlideId = Object.prototype.hasOwnProperty.call(patch, 'targetSlideId') ? patch.targetSlideId : currentTargetSlideId
	if (typeof targetSlideId !== 'string' || !targetSlideId.trim()) throw new Error('slideZoom patch targetSlideId must name an existing semantic slide.')
	const targetSlideIndex = (pptx.slides || []).findIndex(candidate => String(candidate?._betterpptxSemanticId || '') === targetSlideId.trim())
	if (targetSlideIndex < 0) throw new Error('slideZoom patch targetSlideId must name an existing semantic slide.')
	if (targetSlideIndex === args.slideIndex) throw new Error('slideZoom patch targetSlideId cannot name the Slide Zoom\'s own source slide.')

	let geometry = {
		x: currentOptions.x,
		y: currentOptions.y,
		w: currentOptions.w,
		h: currentOptions.h,
	}
	if (Object.prototype.hasOwnProperty.call(patch, 'bbox') || Object.prototype.hasOwnProperty.call(patch, 'rect')) {
		const key = Object.prototype.hasOwnProperty.call(patch, 'bbox') ? 'bbox' : 'rect'
		geometry = normalizedZoomPatchGeometry(patch[key], `slideZoom patch.${key}`) || {}
	}

	const returnToParent = Object.prototype.hasOwnProperty.call(patch, 'returnToParent')
		? (patch.returnToParent === null ? false : patch.returnToParent)
		: Boolean(currentOptions._zoomReturnToParent)
	if (typeof returnToParent !== 'boolean') throw new Error('slideZoom patch.returnToParent must be a boolean or null.')
	const transitionDur = Object.prototype.hasOwnProperty.call(patch, 'transitionDur')
		? (patch.transitionDur === null ? 1000 : Number(patch.transitionDur))
		: (Number.isFinite(Number(currentOptions._zoomTransitionDur)) ? Number(currentOptions._zoomTransitionDur) : 1000)
	if (!Number.isInteger(transitionDur) || transitionDur < 0 || transitionDur > 600000) throw new Error('slideZoom patch.transitionDur must be an integer from 0 through 600000 or null.')

	const accessibilityPatch = {}
	for (const key of ['title', 'altText', 'decorative', 'hiddenFromAccessibility']) {
		if (Object.prototype.hasOwnProperty.call(patch, key)) accessibilityPatch[key] = patch[key]
	}
	const nextAccessibility = {
		...(Object.prototype.hasOwnProperty.call(currentOptions, 'accessibilityTitle') ? { accessibilityTitle: currentOptions.accessibilityTitle } : {}),
		...(Object.prototype.hasOwnProperty.call(currentOptions, 'altText') ? { altText: currentOptions.altText } : {}),
		...(Object.prototype.hasOwnProperty.call(currentOptions, 'isDecorative') ? { isDecorative: currentOptions.isDecorative } : {}),
		...(Object.keys(accessibilityPatch).length ? normalizeAccessibilityMetadata(accessibilityPatch, 'slideZoom patch') : {}),
	}
	for (const key of Object.keys(nextAccessibility)) if (nextAccessibility[key] === null) delete nextAccessibility[key]
	if (nextAccessibility.isDecorative === true && (nextAccessibility.accessibilityTitle != null || nextAccessibility.altText != null)) {
		throw new Error('slideZoom patch cannot combine effective decorative=true with a non-null title or altText; reset the text metadata in the same patch.')
	}

	let authoredThumbnailDataUri = currentOptions._betterpptxZoomThumbnailDataUri
	if (Object.prototype.hasOwnProperty.call(patch, 'thumbnailDataUri')) authoredThumbnailDataUri = patch.thumbnailDataUri
	if (authoredThumbnailDataUri !== undefined && authoredThumbnailDataUri !== null) {
		if (typeof authoredThumbnailDataUri !== 'string' || !/^data:image\/(?:png|jpeg);base64,[A-Za-z0-9+/]+={0,2}$/.test(authoredThumbnailDataUri)) {
			throw new Error('slideZoom patch.thumbnailDataUri must be a PNG/JPEG data URI or null.')
		}
	}

	const nextOptions = {
		...geometry,
		targetSlide: targetSlideIndex + 1,
		objectName: currentOptions.objectName,
		returnToParent,
		transitionDur,
		...nextAccessibility,
		...(typeof authoredThumbnailDataUri === 'string' ? { thumbnailDataUri: authoredThumbnailDataUri } : {}),
	}
	const oldImageRid = Number(current.imageRid)
	const oldSlideRid = Number(currentOptions._zoomSlideRid)
	const oldSpid = currentOptions.spid
	const oldEditHandle = currentOptions._decypherEditHandle

	// addZoom validates and constructs the complete replacement before the old
	// object or either old relationship is removed.
	slide.addZoom(nextOptions)
	const replacement = slide._slideObjects?.pop()
	if (!replacement || _shapeKind(replacement) !== 'zoom') throw new Error('slideZoom patch failed to construct a native replacement.')
	if (oldSpid !== undefined) replacement.options.spid = oldSpid
	replacement.options._betterpptxZoomTargetSlideId = targetSlideId.trim()
	if (typeof authoredThumbnailDataUri === 'string') replacement.options._betterpptxZoomThumbnailDataUri = authoredThumbnailDataUri
	if (oldEditHandle) replacement.options._decypherEditHandle = oldEditHandle
	slide._slideObjects.splice(resolved.rawIndex, 1, replacement)
	if (Number.isFinite(oldImageRid)) slide._relsMedia = (slide._relsMedia || []).filter(rel => Number(rel?.rId) !== oldImageRid)
	if (Number.isFinite(oldSlideRid)) slide._rels = (slide._rels || []).filter(rel => Number(rel?.rId) !== oldSlideRid)

	return {
		ok: true,
		slideIndex: args.slideIndex,
		objectName: replacement.options.objectName,
		targetSlideId: targetSlideId.trim(),
		returnToParent,
		transitionDur,
		geometryReset: (patch.bbox === null || patch.rect === null),
		thumbnailReset: patch.thumbnailDataUri === null,
	}
}

async function handleAddZoom(args) {
	const { pptx } = getDeck(args.deckId)
	const slide = getSlide(args.deckId, args.slideIndex)
	const options = args.options ? { ...args.options } : {}
	const semanticTargetSlideId = typeof options.targetSlideId === 'string' && options.targetSlideId.trim()
		? options.targetSlideId.trim()
		: String(pptx.slides[Number(options.targetSlide) - 1]?._betterpptxSemanticId || '') || null
	const authoredThumbnailDataUri = Object.prototype.hasOwnProperty.call(options, 'thumbnailDataUri')
		? options.thumbnailDataUri
		: undefined
	const editHandle = options.editHandle
	delete options.targetSlideId
	delete options.editHandle
	const { anims, cleaned } = liftAnimations(options)
	slide.addZoom(cleaned || {})
	const inserted = slide._slideObjects?.[slide._slideObjects.length - 1]
	if (inserted?.options) {
		if (semanticTargetSlideId) inserted.options._betterpptxZoomTargetSlideId = semanticTargetSlideId
		if (authoredThumbnailDataUri !== undefined) inserted.options._betterpptxZoomThumbnailDataUri = authoredThumbnailDataUri
		if (editHandle) inserted.options._decypherEditHandle = { id: String(editHandle), source: { kind: 'generated', objectName: inserted.options.objectName || null } }
	}
	applyAnimations(slide, anims)
	return { ok: true, slideIndex: args.slideIndex, animationsApplied: anims.length }
}

function semanticSectionId(section, index = 0) {
	const existing = String(section?._betterpptxSemanticId || '').trim()
	if (existing) return existing
	const fallback = `section-${index + 1}`
	if (section && typeof section === 'object') section._betterpptxSemanticId = fallback
	return fallback
}

function sectionBySemanticId(pptx, id) {
	const target = String(id || '').trim()
	if (!target) return null
	const sections = pptx?.sections || []
	const index = sections.findIndex((section, sectionIndex) => semanticSectionId(section, sectionIndex) === target)
	return index < 0 ? null : { section: sections[index], index }
}

function sectionZoomTargetSectionId(pptx, obj) {
	const explicit = String(obj?.options?._betterpptxZoomTargetSectionId || '').trim()
	if (explicit) return explicit
	const nativeId = String(obj?.options?._zoomSectionId || '').toUpperCase()
	const sections = pptx?.sections || []
	const index = sections.findIndex(section => String(section?._id || '').toUpperCase() === nativeId)
	return index < 0 ? null : semanticSectionId(sections[index], index)
}

async function handleAddSectionZoom(args) {
	const { pptx } = getDeck(args.deckId)
	const slide = getSlide(args.deckId, args.slideIndex)
	const options = args.options ? { ...args.options } : {}
	const semanticTargetSectionId = String(options.targetSectionId || '').trim()
	if (semanticTargetSectionId) {
		const resolved = sectionBySemanticId(pptx, semanticTargetSectionId)
		if (!resolved) throw new Error(`slide.add_section_zoom: targetSectionId ${semanticTargetSectionId} does not name an existing semantic section.`)
		options.targetSection = resolved.index + 1
	}
	const authoredThumbnailDataUri = Object.prototype.hasOwnProperty.call(options, 'thumbnailDataUri') ? options.thumbnailDataUri : undefined
	delete options.targetSectionId
	const { anims, cleaned } = liftAnimations(options)
	slide.addSectionZoom(cleaned || {})
	const inserted = slide._slideObjects?.[slide._slideObjects.length - 1]
	if (inserted?.options) {
		const resolvedId = semanticTargetSectionId || sectionZoomTargetSectionId(pptx, inserted)
		if (resolvedId) inserted.options._betterpptxZoomTargetSectionId = resolvedId
		if (authoredThumbnailDataUri !== undefined) inserted.options._betterpptxZoomThumbnailDataUri = authoredThumbnailDataUri
	}
	applyAnimations(slide, anims)
	return { ok: true, slideIndex: args.slideIndex, targetSectionId: semanticTargetSectionId || sectionZoomTargetSectionId(pptx, inserted), animationsApplied: anims.length }
}

function summaryZoomObject(pptx) {
	for (const [slideIndex, slide] of (pptx?.slides || []).entries()) {
		for (const [rawIndex, obj] of (slide?._slideObjects || []).entries()) {
			if (_shapeKind(obj) === 'summaryZoom') return { slide, slideIndex, obj, rawIndex }
		}
	}
	return null
}

function summaryZoomSectionIds(pptx, obj) {
	const explicit = Array.isArray(obj?.options?._betterpptxSummaryZoomSectionIds)
		? obj.options._betterpptxSummaryZoomSectionIds.map(String).filter(Boolean)
		: []
	if (explicit.length) return explicit
	const sections = pptx?.sections || []
	return (obj?.options?._summaryObjs || []).map(item => {
		const index = sections.findIndex(section => String(section?._id || '').toUpperCase() === String(item?.sectionId || '').toUpperCase())
		return index < 0 ? null : semanticSectionId(sections[index], index)
	}).filter(Boolean)
}

function exportedSummaryZoom(pptx) {
	const found = summaryZoomObject(pptx)
	if (!found) return null
	const { slide, obj } = found
	const opts = obj.options || {}
	const sectionIds = summaryZoomSectionIds(pptx, obj)
	if (!sectionIds.length) return null
	const ownSection = (pptx.sections || []).find(section => (section?._slides || []).includes(slide))
	const objectName = String(opts.objectName || 'summary-zoom')
	const owner = String(opts._betterpptxSummaryZoomOwner || slide?._betterpptxSummaryZoomOwner || objectName)
	return {
		name: /^[A-Za-z0-9._:-]+$/.test(owner) ? owner : 'summary-zoom',
		objectName,
		sectionIds,
		summarySectionId: String(opts._betterpptxSummarySectionId || ownSection?._betterpptxSemanticId || `${owner}-section`),
		summarySlideId: String(opts._betterpptxSummarySlideId || slide?._betterpptxSemanticId || `${owner}-slide`),
		summarySectionTitle: String(ownSection?.title || 'Summary Section'),
		transitionDur: Number.isFinite(Number(opts._zoomTransitionDur)) ? Number(opts._zoomTransitionDur) : 1000,
		...(typeof opts._betterpptxZoomThumbnailDataUri === 'string' ? { thumbnailDataUri: opts._betterpptxZoomThumbnailDataUri } : {}),
		...publicAccessibilityMetadataFromOptions(opts),
	}
}

async function handleAddSummaryZoom(args) {
	const { pptx } = getDeck(args.deckId)
	const options = args.options ? { ...args.options } : {}
	const sectionIds = Array.isArray(options.sectionIds) && options.sectionIds.length
		? options.sectionIds.map(String)
		: (pptx.sections || []).filter(section => !section?._betterpptxSummaryZoomOwner && (section?._slides || []).length).map((section, index) => semanticSectionId(section, index))
	const resolvedSections = sectionIds.map(id => {
		const resolved = sectionBySemanticId(pptx, id)
		if (!resolved || !(resolved.section?._slides || []).length) throw new Error(`deck.add_summary_zoom: sectionIds references missing or empty semantic section ${id}.`)
		return resolved
	})
	if (new Set(sectionIds).size !== sectionIds.length) throw new Error('deck.add_summary_zoom: sectionIds must not contain duplicates.')
	const owner = String(options.name || options.objectName || 'summary-zoom')
	const summarySectionId = String(options.summarySectionId || `${owner}-section`)
	const summarySlideId = String(options.summarySlideId || `${owner}-slide`)
	const authoredThumbnailDataUri = Object.prototype.hasOwnProperty.call(options, 'thumbnailDataUri') ? options.thumbnailDataUri : undefined
	options.sections = resolvedSections.map(({ index }) => index + 1)
	delete options.sectionIds
	delete options.summarySectionId
	delete options.summarySlideId
	delete options.name
	const summarySlide = pptx.addSummaryZoom(options)
	const summarySlideIndex = pptx.slides.indexOf(summarySlide)
	const summarySection = (pptx.sections || []).find(section => (section?._slides || []).includes(summarySlide))
	if (summarySection) {
		summarySection._betterpptxSemanticId = summarySectionId
		summarySection._betterpptxSummaryZoomOwner = owner
	}
	summarySlide._betterpptxSemanticId = summarySlideId
	summarySlide._betterpptxSummaryZoomOwner = owner
	const inserted = (summarySlide._slideObjects || []).find(obj => _shapeKind(obj) === 'summaryZoom')
	if (inserted?.options) {
		inserted.options._betterpptxSummaryZoomOwner = owner
		inserted.options._betterpptxSummaryZoomSectionIds = [...sectionIds]
		inserted.options._betterpptxSummarySectionId = summarySectionId
		inserted.options._betterpptxSummarySlideId = summarySlideId
		if (authoredThumbnailDataUri !== undefined) inserted.options._betterpptxZoomThumbnailDataUri = authoredThumbnailDataUri
	}
	for (const obj of summarySlide._slideObjects || []) {
		if (obj !== inserted && obj?.options?.objectName === 'summary-zoom-title') obj.options._betterpptxSummaryZoomOwner = owner
	}
	return { ok: true, summarySlideIndex, summarySectionId, summarySlideId, sectionIds, sectionCount: pptx.sections.length }
}

function removeSummaryZoomGraph(pptx) {
	const found = summaryZoomObject(pptx)
	if (!found) return { removed: false }
	const { slide, slideIndex, obj } = found
	const owner = String(obj?.options?._betterpptxSummaryZoomOwner || slide?._betterpptxSummaryZoomOwner || '')
	const sections = pptx._sections || pptx.sections || []
	const ownSection = sections.find(section => section?._betterpptxSummaryZoomOwner === owner || (section?._slides || []).includes(slide))
	const slides = pptx._slides || pptx.slides || []
	slides.splice(slideIndex, 1)
	for (const section of sections) section._slides = (section._slides || []).filter(item => item !== slide)
	if (ownSection) sections.splice(sections.indexOf(ownSection), 1)
	_normalizeDeckSlideMetadata(pptx)
	return { removed: true, owner, slideIndex }
}

function sectionZoomPatchPayload(value = {}) {
	const patch = value?.patch && typeof value.patch === 'object' && !Array.isArray(value.patch) ? { ...value.patch } : {}
	for (const key of ['targetSectionId', 'transitionDur', 'thumbnailDataUri', 'bbox', 'rect', 'title', 'altText', 'decorative', 'hiddenFromAccessibility']) {
		if (Object.prototype.hasOwnProperty.call(value, key)) patch[key] = value[key]
	}
	return patch
}

async function handleUpdateSectionZoom(args) {
	const { pptx } = getDeck(args.deckId)
	const slide = getSlide(args.deckId, args.slideIndex)
	const resolved = _resolveTypedShape(slide, args.target, ['sectionZoom'], 'deck.generate_from_spec sectionZoom patch')
	const current = resolved.obj
	const currentOptions = current.options || {}
	const patch = args.patch && typeof args.patch === 'object' && !Array.isArray(args.patch) ? { ...args.patch } : {}
	if (Object.prototype.hasOwnProperty.call(patch, 'bbox') && Object.prototype.hasOwnProperty.call(patch, 'rect')) throw new Error('sectionZoom patch cannot provide both bbox and rect.')
	const targetSectionId = String(Object.prototype.hasOwnProperty.call(patch, 'targetSectionId') ? patch.targetSectionId : sectionZoomTargetSectionId(pptx, current)).trim()
	const target = sectionBySemanticId(pptx, targetSectionId)
	if (!target || !(target.section?._slides || []).length) throw new Error('sectionZoom patch targetSectionId must name an existing nonempty semantic section.')
	let geometry = { x: currentOptions.x, y: currentOptions.y, w: currentOptions.w, h: currentOptions.h }
	if (Object.prototype.hasOwnProperty.call(patch, 'bbox') || Object.prototype.hasOwnProperty.call(patch, 'rect')) {
		const key = Object.prototype.hasOwnProperty.call(patch, 'bbox') ? 'bbox' : 'rect'
		geometry = normalizedZoomPatchGeometry(patch[key], `sectionZoom patch.${key}`) || {}
	}
	const transitionDur = Object.prototype.hasOwnProperty.call(patch, 'transitionDur')
		? (patch.transitionDur === null ? 1000 : Number(patch.transitionDur))
		: (Number.isFinite(Number(currentOptions._zoomTransitionDur)) ? Number(currentOptions._zoomTransitionDur) : 1000)
	if (!Number.isInteger(transitionDur) || transitionDur < 0 || transitionDur > 600000) throw new Error('sectionZoom patch.transitionDur must be an integer from 0 through 600000 or null.')
	const accessibilityPatch = {}
	for (const key of ['title', 'altText', 'decorative', 'hiddenFromAccessibility']) if (Object.prototype.hasOwnProperty.call(patch, key)) accessibilityPatch[key] = patch[key]
	const nextAccessibility = {
		...(Object.prototype.hasOwnProperty.call(currentOptions, 'accessibilityTitle') ? { accessibilityTitle: currentOptions.accessibilityTitle } : {}),
		...(Object.prototype.hasOwnProperty.call(currentOptions, 'altText') ? { altText: currentOptions.altText } : {}),
		...(Object.prototype.hasOwnProperty.call(currentOptions, 'isDecorative') ? { isDecorative: currentOptions.isDecorative } : {}),
		...(Object.keys(accessibilityPatch).length ? normalizeAccessibilityMetadata(accessibilityPatch, 'sectionZoom patch') : {}),
	}
	for (const key of Object.keys(nextAccessibility)) if (nextAccessibility[key] === null) delete nextAccessibility[key]
	let thumbnailDataUri = currentOptions._betterpptxZoomThumbnailDataUri
	if (Object.prototype.hasOwnProperty.call(patch, 'thumbnailDataUri')) thumbnailDataUri = patch.thumbnailDataUri
	if (thumbnailDataUri != null && (typeof thumbnailDataUri !== 'string' || !/^data:image\/(?:png|jpeg);base64,[A-Za-z0-9+/]+={0,2}$/.test(thumbnailDataUri))) throw new Error('sectionZoom patch.thumbnailDataUri must be a PNG/JPEG data URI or null.')
	const nextOptions = {
		...geometry,
		targetSection: target.index + 1,
		objectName: currentOptions.objectName,
		transitionDur,
		...nextAccessibility,
		...(typeof thumbnailDataUri === 'string' ? { thumbnailDataUri } : {}),
	}
	const oldImageRid = Number(current.imageRid)
	const oldSlideRid = Number(currentOptions._zoomSlideRid)
	const oldSpid = currentOptions.spid
	const oldEditHandle = currentOptions._decypherEditHandle
	slide.addSectionZoom(nextOptions)
	const replacement = slide._slideObjects?.pop()
	if (!replacement || _shapeKind(replacement) !== 'sectionZoom') throw new Error('sectionZoom patch failed to construct a native replacement.')
	if (oldSpid !== undefined) replacement.options.spid = oldSpid
	replacement.options._betterpptxZoomTargetSectionId = targetSectionId
	if (typeof thumbnailDataUri === 'string') replacement.options._betterpptxZoomThumbnailDataUri = thumbnailDataUri
	if (oldEditHandle) replacement.options._decypherEditHandle = oldEditHandle
	slide._slideObjects.splice(resolved.rawIndex, 1, replacement)
	if (Number.isFinite(oldImageRid)) slide._relsMedia = (slide._relsMedia || []).filter(rel => Number(rel?.rId) !== oldImageRid)
	if (Number.isFinite(oldSlideRid)) slide._rels = (slide._rels || []).filter(rel => Number(rel?.rId) !== oldSlideRid)
	return { ok: true, slideIndex: args.slideIndex, objectName: replacement.options.objectName, targetSectionId, transitionDur, geometryReset: patch.bbox === null || patch.rect === null, thumbnailReset: patch.thumbnailDataUri === null }
}

async function handleUpdateSummaryZoom(args) {
	const { pptx } = getDeck(args.deckId)
	const found = summaryZoomObject(pptx)
	const current = found?.obj
	const currentOptions = current?.options || {}
	const patch = args.patch && typeof args.patch === 'object' && !Array.isArray(args.patch) ? { ...args.patch } : {}
	const sectionIds = Object.prototype.hasOwnProperty.call(patch, 'sectionIds') ? patch.sectionIds : (current ? summaryZoomSectionIds(pptx, current) : [])
	if (!Array.isArray(sectionIds) || !sectionIds.length || new Set(sectionIds.map(String)).size !== sectionIds.length) throw new Error('summaryZoom.sectionIds must be a non-empty unique array.')
	for (const id of sectionIds) {
		const resolved = sectionBySemanticId(pptx, id)
		if (!resolved || !(resolved.section?._slides || []).length || resolved.section?._betterpptxSummaryZoomOwner) throw new Error(`summaryZoom.sectionIds references missing or generated semantic section ${id}.`)
	}
	const transitionDur = Object.prototype.hasOwnProperty.call(patch, 'transitionDur') ? (patch.transitionDur === null ? 1000 : Number(patch.transitionDur)) : (Number.isFinite(Number(currentOptions._zoomTransitionDur)) ? Number(currentOptions._zoomTransitionDur) : 1000)
	if (!Number.isInteger(transitionDur) || transitionDur < 0 || transitionDur > 600000) throw new Error('summaryZoom.transitionDur must be an integer from 0 through 600000 or null.')
	let thumbnailDataUri = currentOptions._betterpptxZoomThumbnailDataUri
	if (Object.prototype.hasOwnProperty.call(patch, 'thumbnailDataUri')) thumbnailDataUri = patch.thumbnailDataUri
	if (thumbnailDataUri != null && (typeof thumbnailDataUri !== 'string' || !/^data:image\/(?:png|jpeg);base64,[A-Za-z0-9+/]+={0,2}$/.test(thumbnailDataUri))) throw new Error('summaryZoom.thumbnailDataUri must be a PNG/JPEG data URI or null.')
	const currentExport = current ? exportedSummaryZoom(pptx) : null
	const accessibilityPatch = {}
	for (const key of ['title', 'altText', 'decorative', 'hiddenFromAccessibility']) if (Object.prototype.hasOwnProperty.call(patch, key)) accessibilityPatch[key] = patch[key]
	const accessibility = {
		...(currentExport ? { title: currentExport.title, altText: currentExport.altText, decorative: currentExport.decorative } : {}),
		...accessibilityPatch,
	}
	for (const key of Object.keys(accessibility)) if (accessibility[key] == null) delete accessibility[key]
	if (Object.keys(accessibility).length) normalizeAccessibilityMetadata(accessibility, 'summaryZoom patch')
	const options = {
		name: String(args.name || currentExport?.name || 'summary-zoom'),
		objectName: String(args.objectName || currentOptions.objectName || 'summary-zoom'),
		sectionIds: sectionIds.map(String),
		summarySectionId: String(args.summarySectionId || currentExport?.summarySectionId || 'summary-zoom-section'),
		summarySlideId: String(args.summarySlideId || currentExport?.summarySlideId || 'summary-zoom-slide'),
		summarySectionTitle: Object.prototype.hasOwnProperty.call(patch, 'summarySectionTitle') ? (patch.summarySectionTitle === null ? 'Summary Section' : patch.summarySectionTitle) : (currentExport?.summarySectionTitle || 'Summary Section'),
		transitionDur,
		...(typeof thumbnailDataUri === 'string' ? { thumbnailDataUri } : {}),
		...normalizeAccessibilityMetadata(accessibility, 'summaryZoom patch'),
	}
	removeSummaryZoomGraph(pptx)
	return handleAddSummaryZoom({ deckId: args.deckId, options })
}

async function handleAddFreeform(args) {
	const slide = getSlide(args.deckId, args.slideIndex)
	let opts = args.options && typeof args.options === 'object' ? cloneJson(args.options) : {}
	const reserved = new Set(['deckId', 'slideIndex', 'options', 'idempotencyKey', 'idempotency_key'])
	for (const [key, value] of Object.entries(args || {})) {
		if (reserved.has(key) || value === undefined) continue
		opts[key] = cloneJson(value)
	}
	opts = normalizeVisualOptions(opts, 'slide.add_freeform options') || {}
	const structuralInput = { points: opts.points, ...(opts.paths !== undefined ? { paths: opts.paths } : {}), ...(opts.booleanOperation !== undefined ? { booleanOperation: opts.booleanOperation } : {}), ...(opts.operation !== undefined ? { operation: opts.operation } : {}), ...(opts.operands !== undefined ? { operands: opts.operands } : {}), ...(opts.handle !== undefined ? { handle: opts.handle } : {}), ...(opts.geometryId !== undefined ? { geometryId: opts.geometryId } : {}), ...(opts.x !== undefined ? { x: opts.x } : {}), ...(opts.y !== undefined ? { y: opts.y } : {}), ...(opts.w !== undefined ? { w: opts.w } : {}), ...(opts.h !== undefined ? { h: opts.h } : {}) }
	const normalizedStructural = normalizeStructuralGeometry(structuralInput, 'slide.add_freeform')
	if (!Array.isArray(normalizedStructural.points)) throw new Error('slide.add_freeform requires points, paths, operands, or a materialized geometry handle.')
	opts.points = normalizedStructural.points
	for (const key of ['paths', 'booleanOperation', 'operation', 'operands', 'handle', 'geometryId']) if (Object.prototype.hasOwnProperty.call(normalizedStructural, key)) opts[key] = normalizedStructural[key]
	for (const key of ['x', 'y', 'w', 'h']) {
		if (opts[key] === undefined || opts[key] === null || opts[key] === '') throw new Error(`${key} is required for slide.add_freeform`)
	}
	const { anims, cleaned } = liftAnimations(opts)
	slide.addShape('custGeom', cleaned)
	applyAnimations(slide, anims)
	return { ok: true, slideIndex: args.slideIndex, animationsApplied: anims.length, points: cleaned.points.length }
}

function annotationNumber(value, fallback, { min = null } = {}) {
	const n = Number(value)
	if (!Number.isFinite(n)) return fallback
	return min == null ? n : Math.max(min, n)
}

function annotationPointValue(value, extent, relative) {
	const n = Number(value)
	if (!Number.isFinite(n)) return 0
	return relative ? n * extent : n
}

function normalizeAnnotationPoints(points, box, coordinateMode = 'relative') {
	const relative = coordinateMode !== 'box'
	const source = Array.isArray(points) && points.length >= 2
		? points
		: [
			{ x: 0.05, y: 0.55 },
			{ x: 0.25, y: 0.22, curve: { type: 'quadratic', x1: 0.14, y1: 0.1 } },
			{ x: 0.58, y: 0.62, curve: { type: 'cubic', x1: 0.38, y1: 0.38, x2: 0.47, y2: 0.86 } },
			{ x: 0.95, y: 0.3, curve: { type: 'quadratic', x1: 0.78, y1: 0.05 } },
		]
	return source.map((point, index) => {
		if (point && typeof point === 'object' && point.close) return { close: true }
		const out = point && typeof point === 'object' ? cloneJson(point) : {}
		out.x = annotationPointValue(out.x, box.w, relative)
		out.y = annotationPointValue(out.y, box.h, relative)
		if (out.curve && typeof out.curve === 'object') {
			if (out.curve.x1 !== undefined) out.curve.x1 = annotationPointValue(out.curve.x1, box.w, relative)
			if (out.curve.y1 !== undefined) out.curve.y1 = annotationPointValue(out.curve.y1, box.h, relative)
			if (out.curve.x2 !== undefined) out.curve.x2 = annotationPointValue(out.curve.x2, box.w, relative)
			if (out.curve.y2 !== undefined) out.curve.y2 = annotationPointValue(out.curve.y2, box.h, relative)
			if (out.curve.wR !== undefined) out.curve.wR = annotationPointValue(out.curve.wR, box.w, relative)
			if (out.curve.hR !== undefined) out.curve.hR = annotationPointValue(out.curve.hR, box.h, relative)
		}
		if (index === 0) {
			delete out.curve
			out.moveTo = true
		}
		return out
	})
}

function annotationBox(args, defaults) {
	return {
		x: annotationNumber(args.x ?? args.options?.x, defaults.x),
		y: annotationNumber(args.y ?? args.options?.y, defaults.y),
		w: annotationNumber(args.w ?? args.options?.w, defaults.w, { min: 0.05 }),
		h: annotationNumber(args.h ?? args.options?.h, defaults.h, { min: 0.05 }),
	}
}

function inkStrokeDefaults(inkType) {
	const type = String(inkType || 'pen').toLowerCase()
	if (type === 'highlighter') return { color: 'FDE047', width: 12, transparency: 48 }
	if (type === 'marker') return { color: 'F97316', width: 5.5, transparency: 12 }
	return { color: '2563EB', width: 2.6, transparency: 0 }
}

async function handleAddInk(args) {
	const box = annotationBox(args, { x: 0.8, y: 1.2, w: 3.6, h: 1.4 })
	const rawStrokes = Array.isArray(args.strokes) && args.strokes.length
		? args.strokes
		: [Array.isArray(args.points) ? args.points : null]
	let strokesAdded = 0
	let pointsAdded = 0
	const objectNames = []
	for (const [index, rawStroke] of rawStrokes.entries()) {
		const stroke = Array.isArray(rawStroke) ? { points: rawStroke } : (rawStroke && typeof rawStroke === 'object' ? rawStroke : {})
		const type = stroke.inkType || args.inkType || 'pen'
		const defaults = inkStrokeDefaults(type)
		const color = cleanHex(stroke.color || args.color, defaults.color)
		const width = annotationNumber(stroke.width ?? args.width, defaults.width, { min: 0.1 })
		const transparency = annotationNumber(stroke.transparency ?? args.transparency, defaults.transparency)
		const objectName = stroke.objectName || args.objectName && (rawStrokes.length === 1 ? args.objectName : `${args.objectName}-${index + 1}`) || `ink-${String(type).toLowerCase()}-${index + 1}`
		const points = normalizeAnnotationPoints(stroke.points, box, stroke.coordinateMode || args.coordinateMode || 'relative')
		const options = normalizeVisualOptions({
			...(args.options && typeof args.options === 'object' ? cloneJson(args.options) : {}),
			...(stroke.options && typeof stroke.options === 'object' ? cloneJson(stroke.options) : {}),
			x: stroke.x ?? box.x,
			y: stroke.y ?? box.y,
			w: stroke.w ?? box.w,
			h: stroke.h ?? box.h,
			points,
			fill: { color: 'FFFFFF', transparency: 100 },
			line: { color, width, transparency },
			objectName,
			animation: stroke.animation ?? args.animation,
		}, 'slide.add_ink options')
		const { anims, cleaned } = liftAnimations(options)
		const slide = getSlide(args.deckId, args.slideIndex)
		slide.addShape('custGeom', cleaned)
		applyAnimations(slide, anims)
		strokesAdded++
		pointsAdded += points.length
		objectNames.push(objectName)
	}
	return {
		ok: true,
		slideIndex: args.slideIndex,
		strokesAdded,
		pointsAdded,
		objectNames,
		editableAs: 'custom-geometry annotation',
	}
}

async function handleAddLaserPointer(args) {
	const box = annotationBox(args, { x: 0.8, y: 1.0, w: 4.2, h: 2.4 })
	const color = cleanHex(args.color, 'FF2D55')
	const width = annotationNumber(args.width, 2.4, { min: 0.1 })
	const transparency = annotationNumber(args.transparency, 0)
	const beamObjectName = args.objectName || 'laser-pointer-beam'
	const points = normalizeAnnotationPoints(args.points || [
		{ x: 0.05, y: 0.78 },
		{ x: 0.36, y: 0.2, curve: { type: 'quadratic', x1: 0.18, y1: 0.3 } },
		{ x: 0.72, y: 0.48, curve: { type: 'quadratic', x1: 0.58, y1: 0.02 } },
		{ x: 0.96, y: 0.18, curve: { type: 'quadratic', x1: 0.86, y1: 0.32 } },
	], box, args.coordinateMode || 'relative')
	const defaultAnimation = {
		type: 'entrance',
		effect: 'wipe',
		direction: 'fromLeft',
		trigger: 'afterPrevious',
		duration: annotationNumber(args.durationMs, 650, { min: 1 }),
		delay: annotationNumber(args.startDelayMs, 0, { min: 0 }),
	}
	const staticAnnotation = args.static === true || args.staticDemo === true
	const options = normalizeVisualOptions({
		...(args.options && typeof args.options === 'object' ? cloneJson(args.options) : {}),
		x: box.x,
		y: box.y,
		w: box.w,
		h: box.h,
		points,
		fill: { color: 'FFFFFF', transparency: 100 },
		line: { color, width, transparency, endArrowType: 'oval' },
		glow: args.glow || { color, size: 14, opacity: 0.72 },
		objectName: beamObjectName,
		...(staticAnnotation ? {} : { animation: args.animation || defaultAnimation }),
	}, 'slide.add_laser_pointer options')
	const { anims, cleaned } = liftAnimations(options)
	const slide = getSlide(args.deckId, args.slideIndex)
	slide.addShape('custGeom', cleaned)
	applyAnimations(slide, anims)

	let dotObjectName = null
	if (args.dot !== false) {
		const end = points.slice().reverse().find(point => point && point.x !== undefined && point.y !== undefined) || { x: box.w, y: box.h / 2 }
		const dotSize = Math.max(0.1, width / 18)
		dotObjectName = `${beamObjectName}-dot`
		slide.addShape('ellipse', normalizeVisualOptions({
			x: box.x + Number(end.x) - dotSize / 2,
			y: box.y + Number(end.y) - dotSize / 2,
			w: dotSize,
			h: dotSize,
			fill: { color, transparency: 0 },
			line: { color, transparency: 100 },
			glow: args.glow || { color, size: 18, opacity: 0.82 },
			objectName: dotObjectName,
		}, 'slide.add_laser_pointer dot options'))
	}
	return {
		ok: true,
		slideIndex: args.slideIndex,
		beamObjectName,
		dotObjectName,
		points: points.length,
		editableAs: 'custom-geometry laser pointer overlay',
	}
}

async function handleAddNotes(args) {
	const slide = getSlide(args.deckId, args.slideIndex)
	slide.addNotes(args.notes)
	return { ok: true, slideIndex: args.slideIndex }
}

function reviewCommentList(entry) {
	const imported = Array.isArray(entry?.reviewComments) ? entry.reviewComments : []
	const pending = Array.isArray(entry?.pendingReviewComments) ? entry.pendingReviewComments : []
	const resolved = entry?.resolvedReviewComments instanceof Map ? entry.resolvedReviewComments : new Map()
	return [...imported, ...pending].map(comment => {
		const resolution = resolved.get(String(comment.id))
		return resolution ? { ...comment, status: 'resolved', resolutionNote: resolution.note || null, resolvedAt: resolution.at } : comment
	})
}

function normalizeReviewAuthor(args = {}) {
	const name = String(args.author || 'BetterPPTX Review').trim().slice(0, 128) || 'BetterPPTX Review'
	const initials = String(args.authorInitials || name.split(/\s+/).map(part => part[0]).join('').slice(0, 3) || 'BPX').toUpperCase().slice(0, 3)
	return { name, initials }
}

async function handleAddComment(args) {
	const entry = getDeck(args.deckId)
	const slideIndex = Number(args.slideIndex)
	const slide = getSlide(args.deckId, slideIndex)
	const text = String(args.text || '').trim()
	if (!text) throw new Error('slide.add_comment: text is required.')
	const author = normalizeReviewAuthor(args)
	let x = Number(args.x)
	let y = Number(args.y)
	if (!Number.isFinite(x) || !Number.isFinite(y)) {
		const target = args.targetObjectName ? findSlideObjectByName(slide, args.targetObjectName) : null
		const opts = target?.options || {}
		x = Number.isFinite(Number(opts.x)) ? Number(opts.x) : 0.5
		y = Number.isFinite(Number(opts.y)) ? Number(opts.y) : 0.5
	}
	const comment = {
		id: `bpx-comment-${crypto.randomUUID()}`,
		slideIndex,
		text,
		author: author.name,
		authorInitials: author.initials,
		x: Math.max(0, x),
		y: Math.max(0, y),
		...(args.targetObjectName ? { targetObjectName: String(args.targetObjectName) } : {}),
		status: args.status === 'resolved' ? 'resolved' : 'open',
		createdAt: new Date().toISOString(),
	}
	entry.pendingReviewComments = entry.pendingReviewComments || []
	entry.pendingReviewComments.push(comment)
	if (comment.status === 'resolved') {
		entry.resolvedReviewComments = entry.resolvedReviewComments || new Map()
		entry.resolvedReviewComments.set(comment.id, { at: comment.createdAt, note: 'Resolved at creation.' })
	}
	invalidatePublicPreviewFreeze(entry)
	entry.deckVersion = deckVersion(entry) + 1
	return { ok: true, slideIndex, commentId: comment.id, status: comment.status, nativeEditable: true, next: { recommendedTool: 'betterpptx.deck.save', reason: 'Save to write the review comment into the PowerPoint Review pane.' } }
}

async function handleListComments(args) {
	const entry = getDeck(args.deckId)
	const includeResolved = args.includeResolved !== false
	const slideIndex = args.slideIndex == null ? null : Number(args.slideIndex)
	const comments = reviewCommentList(entry).filter(comment => {
		if (slideIndex != null && comment.slideIndex !== slideIndex) return false
		return includeResolved || comment.status !== 'resolved'
	})
	return { ok: true, comments: cloneForResult(comments), count: comments.length, reviewMode: 'semantic-native-comments' }
}

async function handleResolveComment(args) {
	const entry = getDeck(args.deckId)
	const commentId = String(args.commentId || '').trim()
	if (!commentId) throw new Error('slide.resolve_comment: commentId is required.')
	const known = reviewCommentList(entry).find(comment => String(comment.id) === commentId)
	if (!known) {
		const err = new Error(`slide.resolve_comment: unknown commentId ${commentId}.`)
		err.code = 'REVIEW_COMMENT_NOT_FOUND'
		throw err
	}
	entry.resolvedReviewComments = entry.resolvedReviewComments || new Map()
	entry.resolvedReviewComments.set(commentId, { at: new Date().toISOString(), note: String(args.note || '').trim() || null })
	invalidatePublicPreviewFreeze(entry)
	entry.deckVersion = deckVersion(entry) + 1
	return { ok: true, commentId, status: 'resolved', persistence: 'native-when-supported-or-typed-review-audit-fallback', next: { recommendedTool: 'betterpptx.deck.save', reason: 'Save to persist the review resolution.' } }
}

function findSlideObjectByName(slide, objectName) {
	const objects = _editableSlideObjects(slide)
	const want = String(objectName)
	// 1) exact compiled objectName.
	for (const { obj } of objects) {
		if (obj?.options?.objectName === want) return obj
	}
	// 2) author block-name match: the compiler names objects slideId.blockName.role, but a
	//    narration cue is usually authored against the block NAME ("b2"), which the AI knows —
	//    not the prefixed compiled name. Accept a target equal to any dot-delimited segment.
	const seg = want.toLowerCase()
	for (const { obj } of objects) {
		const nm = String(obj?.options?.objectName || '').toLowerCase()
		if (nm && nm.split('.').includes(seg)) return obj
	}
	return null
}

function narrationMs(value, fallback = 0) {
	const n = Math.round(Number(value ?? fallback) || 0)
	return Math.max(0, n)
}

function narrationDurationMs(value, fallback = 250) {
	const n = Math.round(Number(value ?? fallback) || 0)
	return Math.max(1, n)
}

function normalizeNarrationTimingArgs(args = {}) {
	const timing = args.timing || args.timeline || args.narrationTiming || {}
	if (!timing || typeof timing !== 'object') return args
	return {
		...args,
		startDelayMs: args.startDelayMs ?? timing.startDelayMs,
		paddingMs: args.paddingMs ?? timing.paddingMs,
		cues: args.cues ?? timing.cues,
		expectedDurationMs: args.expectedDurationMs ?? timing.expectedDurationMs ?? timing.durationMs,
		timingToleranceMs: args.timingToleranceMs ?? timing.timingToleranceMs ?? timing.toleranceMs,
	}
}

function assertPublicNarrationHasNoOverlayCaptions(args = {}) {
	if (!isPublicBlackBoxMode()) return
	const field = findNonNativeCaptionOverlayField(args, 'narration')
	if (!field) return
	const issue = nonNativeCaptionOverlayIssue(field)
	const err = new Error(issue.message)
	err.code = issue.code
	err.details = {
		status: 'invalid_semantic_input',
		field,
		reason: issue.reason,
		fix: issue.fix,
	}
	throw err
}

function closedCaptionTracksForArgs(args = {}, { cues = [], script = '' } = {}) {
	const sources = [
		['narration.closedCaptionTracks', args.closedCaptionTracks],
		['narration.audio.closedCaptionTracks', args.audio?.closedCaptionTracks],
		['narration.mediaOptions.closedCaptionTracks', args.mediaOptions?.closedCaptionTracks],
	].filter(([, value]) => value !== undefined)
	if (sources.length > 1) {
		const error = new Error(`Caption tracks have multiple sources (${sources.map(([path]) => path).join(', ')}). Keep one explicit source.`)
		error.code = 'CAPTION_TRACKS_AMBIGUOUS_SOURCE'
		error.details = { paths: sources.map(([path]) => path) }
		throw error
	}
	return materializeClosedCaptionTracks(sources[0]?.[1], { cues, script })
}

function segmentCaptionTracksForArgs(args = {}, segments = []) {
	const active = segments.filter(segment => segment && (segment.script != null || segment.audio))
	if (active.length > 1) {
		const slideTracks = [args.closedCaptionTracks, args.audio?.closedCaptionTracks, args.mediaOptions?.closedCaptionTracks]
		if (slideTracks.some(tracks => Array.isArray(tracks) && tracks.length)) {
			const error = new Error('Multi-clip narration requires WebVTT tracks on each segments[].closedCaptionTracks or segments[].audio.closedCaptionTracks, timed from that clip\'s start. A slide-level track cannot be attached to one clip without losing later captions.')
			error.code = 'NARRATION_SEGMENT_CAPTION_SCOPE_REQUIRED'
			throw error
		}
	}
	return active.map(segment => closedCaptionTracksForArgs(
		active.length === 1 && segment.closedCaptionTracks === undefined && segment.audio?.closedCaptionTracks === undefined && segment.mediaOptions?.closedCaptionTracks === undefined ? args : segment,
		{ cues: segment.cues || [], script: String(segment.script ?? '') },
	))
}

function narrationMediaFrame(pptx, args = {}, index = 0) {
	const slideSize = exportedSlideSize(pptx)
	const widthInches = slideSize.width > 10000 ? slideSize.width / 914400 : slideSize.width
	const heightInches = slideSize.height > 10000 ? slideSize.height / 914400 : slideSize.height
	const w = args.w ?? 0.22
	const h = args.h ?? 0.18
	return {
		x: args.x ?? Math.max(0, widthInches - w - 0.24),
		y: args.y ?? Math.max(0, heightInches - h - 0.24 - (index % 4) * 0.24),
		w, h,
	}
}

function narrationTimingToleranceMs(value, expectedDurationMs = 0) {
	if (value !== undefined && value !== null) return narrationMs(value)
	if (expectedDurationMs) return Math.max(250, Math.round(expectedDurationMs * 0.08))
	return 250
}

// BEAT ANCHORING — the sync intelligence. An emphasis cue can be authored against a SPOKEN
// PHRASE (atPhrase/atWord) instead of a guessed millisecond; here we map that phrase to its
// real moment in the synthesized audio (proportional to its character position — speech is
// roughly linear in characters, so a forced-aligner would only refine this). So "pulse the
// KPI when I say 9,800" fires on the word, derived from the REAL TTS, not a guess. Also maps
// objectName→target for convenience.
// A generated shape added to an UPLOADED slide must not collide with PRESERVED source shape
// ids: the writer ids generated shapes by POSITION (idx+2) while imported shapes keep their
// ORIGINAL spids — two id worlds that can overlap (duplicate p:cNvPr ids make PowerPoint
// refuse the file). Every shape the narration engine adds gets an explicitly pinned free spid.
function _nextFreeSlideSpid(slide) {
	const objs = slide?._slideObjects || []
	let max = objs.length + 2   // ceiling of the position-based ids for shapes without explicit spid
	for (const o of objs) {
		const s = Number(o?.options?.spid)
		if (Number.isFinite(s)) max = Math.max(max, s)
	}
	return max + 1
}
function resolveCueAnchors(cues, script, audioDurationMs) {
	const text = String(script || '')
	const total = text.length || 1
	const dur = narrationMs(audioDurationMs)
	return (Array.isArray(cues) ? cues : []).map((cue, cueIndex) => {
		const out = canonicalNarrationCue(cue, { script: text, durationMs: dur, cueIndex })
		if (out.atMs == null && out.delay == null) {
			const phrase = out.atPhrase || out.atWord
			if (!(dur > 0)) {
				const error = new Error(`Narration cue phrase "${phrase}" cannot be anchored without a positive measured audio duration.`)
				error.code = 'NARRATION_CUE_ANCHOR_UNRESOLVED'
				throw error
			}
			const idx = text.toLowerCase().indexOf(String(phrase).toLowerCase())
			if (idx < 0) {
				const error = new Error(`Narration cue phrase "${phrase}" is not present in the authored narration.`)
				error.code = 'NARRATION_CUE_ANCHOR_UNRESOLVED'
				throw error
			}
			out.atMs = Math.max(0, Math.round((idx / total) * dur))
			out._anchoredFrom = phrase
			out.anchorMethod = NARRATION_CUE_ANCHOR_METHOD
		}
		return out
	})
}

// SEGMENTED BEAT ANCHORING — a slide's narration can be a sequence of clips (segments) with
// silence gaps between them. A top-level cue authored against a spoken phrase is resolved to
// an ABSOLUTE timeline millisecond by finding which segment contains the phrase and mapping
// its character position within that segment's own audio, then offsetting by the segment's
// start on the slide timeline. Explicit atMs on a top-level cue is already absolute (baseDelay 0).
function resolveCueAnchorsMultiSegment(cues, segInfos = []) {
	const scripts = segInfos.map(segment => String(segment?.script || ''))
	return (Array.isArray(cues) ? cues : []).map((cue, cueIndex) => {
		const out = canonicalNarrationCue(cue, { scripts, cueIndex })
		if (out.atMs == null && out.delay == null) {
			const phrase = out.atPhrase || out.atWord
			for (const seg of segInfos) {
				const text = String(seg.script || '')
				const idx = text.toLowerCase().indexOf(String(phrase).toLowerCase())
				if (idx >= 0 && narrationMs(seg.durationMs) > 0) {
					out.atMs = Math.max(0, Math.round(narrationMs(seg.startMs) + (idx / (text.length || 1)) * narrationMs(seg.durationMs)))
					out._anchoredFrom = phrase
					out.anchorMethod = NARRATION_CUE_ANCHOR_METHOD
					break
				}
			}
			if (out.atMs == null) {
				const error = new Error(`Narration cue phrase "${phrase}" cannot be anchored to a positive measured segment duration.`)
				error.code = 'NARRATION_CUE_ANCHOR_UNRESOLVED'
				throw error
			}
		}
		return out
	})
}

// AESTHETIC BALANCE LAYER for the narration-synced build. Text is master of WHEN a reveal
// fires, but the motion must stay beautiful — never too fast (chaotic), too slow, or jittery.
// This operates on the auto-synced-build beats AFTER they resolve to real audio ms: it enforces
// the world's minimum breathing interval so closely-spoken reveals never stack, and if honoring
// that would overflow the audio it falls back to a CALM, even cadence across the narration
// (ordered, never chaotic) rather than distorting the motion. Hand-placed cues are untouched;
// the animation's own duration (set per-world by the compiler) is never stretched to chase audio.
function balanceSyncedBuildBeats(cues, options = {}) {
	const list = Array.isArray(cues) ? cues : []
	const auto = list.filter(c => c && c.autoSyncedBuild && c.atMs != null)
	if (auto.length < 2) return list
	const minIntervalMs = Math.max(1, Math.round(Number(options.minIntervalMs) || 0)) || 650
	const dur = Math.max(0, Math.round(Number(options.audioDurationMs) || 0))
	auto.sort((a, b) => (Number(a.atMs) || 0) - (Number(b.atMs) || 0))
	const first = Math.max(0, Number(auto[0].atMs) || 0)
	const needed = first + minIntervalMs * (auto.length - 1)
	if (dur && needed > dur) {
		// Word-anchored spacing would overflow the audio → calm, even cadence across [first, end].
		const step = Math.max(0, dur - first) / (auto.length - 1)
		auto.forEach((c, i) => { c.atMs = Math.round(first + step * i); c.balancedBy = 'even' })
	} else {
		let prev = -Infinity
		for (const c of auto) {
			let t = Math.max(0, Number(c.atMs) || 0)
			if (t < prev + minIntervalMs) { t = prev + minIntervalMs; c.balancedBy = 'spaced' }
			c.atMs = t
			prev = t
		}
		if (dur) for (const c of auto) if (c.atMs > dur) c.atMs = dur
	}
	return list
}

function applyNarrationCues(slide, cues = [], options = {}) {
	const baseDelayMs = narrationMs(options.baseDelayMs)
	let applied = 0
	let maxEndMs = baseDelayMs
	const timings = []
	for (const cue of cues || []) {
		if (!cue || (cue.atMs == null && cue.delay == null)) {
			const error = new Error('Narration cue reached execution without a resolved atMs/delay anchor.')
			error.code = 'NARRATION_CUE_ANCHOR_UNRESOLVED'
			throw error
		}
		if (!cue || cue.target == null) continue
		const target = typeof cue.target === 'string'
			? findSlideObjectByName(slide, cue.target)
			: _editableSlideObjects(slide)[Number(cue.target)]?.obj
		if (!target) continue
		const atMs = narrationMs(cue.atMs ?? cue.delay)
		const delay = baseDelayMs + atMs
		const duration = narrationDurationMs(cue.duration ?? cue.durationMs ?? cue.animation?.duration, 250)
		const targetName = typeof cue.target === 'string' ? cue.target : (target?.options?.objectName || String(cue.target))
		if (cue.bindExistingPresenterMotion === true) {
			const records = (slide._animations || []).filter(record => record?.target === target && String(record?.animation?.effect || '').toLowerCase().replace(/[\s_-]+/g, '') === 'playscene')
			if (records.length !== 1) continue
			const record = records[0]
			const boundDuration = narrationDurationMs(record.animation?.duration, duration)
			record.animation = {
				...record.animation,
				trigger: 'withPrevious',
				delay,
				_presenterMotionNarrationBound: true,
			}
			applied++
			maxEndMs = Math.max(maxEndMs, delay + boundDuration)
			timings.push({ target: targetName, atMs, delayMs: delay, durationMs: boundDuration, endMs: delay + boundDuration, presenterMotion: true, ...(cue.motionId ? { motionId: cue.motionId } : {}), ...(cue.anchorMethod ? { anchorMethod: cue.anchorMethod } : {}) })
			continue
		}
		const animation = cue.animation || {}
		// Tag the applied animation as narration-driven (_narrationCue) so re-narration can purge
		// the stale beat and re-anchor it on the NEW audio instead of leaving old-clock motion.
		slide.addAnimation(target, Object.assign(normalizeAnimation({
			...animation,
			type: cue.type || animation.type || 'entrance',
			effect: cue.effect || animation.effect || 'fade',
			// Forward motion-path + direction so a cue can move an object along a PATH or give an
			// exit/entrance a direction (open animation palette: entrance/emphasis/exit/motion).
			...(cue.motionPath || animation.motionPath ? { motionPath: cue.motionPath || animation.motionPath } : {}),
			...(cue.direction || animation.direction ? { direction: cue.direction || animation.direction } : {}),
			trigger: 'withPrevious',
			delay,
			duration,
		}), { _narrationCue: true }))
		applied++
		maxEndMs = Math.max(maxEndMs, delay + duration)
		timings.push({ target: targetName, atMs, delayMs: delay, durationMs: duration, endMs: delay + duration, ...(cue.balancedBy ? { balancedBy: cue.balancedBy } : {}), ...(cue.autoSyncedBuild ? { autoSyncedBuild: true } : {}), ...(cue.anchorMethod ? { anchorMethod: cue.anchorMethod } : {}) })
	}
	return { applied, maxEndMs, timings }
}

function captionFallbackText(text, maxChars = 150) {
	const normalized = String(text || '').replace(/\s+/g, ' ').trim()
	if (!normalized) return ''
	const firstSentence = (normalized.match(/^(.{24,}?[.!?])\s/) || [])[1] || normalized
	return firstSentence.length > maxChars ? `${firstSentence.slice(0, maxChars - 3).trim()}...` : firstSentence
}

function applyNarrationCaptions(_slide, _captions, _cues = [], _fallbackText = '', options = {}) {
	return { applied: 0, maxEndMs: narrationMs(options.baseDelayMs), timings: [] }
}

async function handleNarrationVoices(args) {
	return publicVoiceCatalog(isPublicBlackBoxMode()
		? {
			includeCandidates: false,
			allowUnreviewedVoices: false,
			gender: args.gender,
			language: args.language || args.lang,
			query: args.query,
		}
		: {
			includeCandidates: !!args.includeCandidates,
			allowUnreviewedVoices: !!args.allowUnreviewedVoices,
			gender: args.gender,
			language: args.language || args.lang,
			query: args.query,
		})
}

function publicNarrationSynthesisResult(result) {
	const artifact = lockGeneratedAssetDescriptor(result.wavPath, 'narration-audio', {
		extn: 'wav',
		mimeType: 'audio/wav',
		durationMs: result.durationMs,
	})
	return {
		ok: result.ok,
		audio: {
			ref: artifact.handle,
			durationMs: result.durationMs,
			extn: 'wav',
			mimeType: 'audio/wav',
		},
		durationMs: result.durationMs,
		voice: publicNarrationVoice(result.voice),
		warnings: publicNarrationWarnings(result.warnings),
		textHash: result.textHash,
	}
}

function narrationPreparationDigestPayload(manifest = {}) {
	const { preparationId: _preparationId, manifestDigest: _manifestDigest, manifestHandle: _manifestHandle, ...payload } = manifest
	return payload
}

function narrationPreparationDigest(manifest = {}) {
	return crypto.createHash('sha256').update(JSON.stringify(stableForHash(narrationPreparationDigestPayload(manifest)))).digest('hex')
}

function lockNarrationPreparation(prepared = {}) {
	const segmentLocks = (prepared.segments || []).map(segment => {
		const lockedAudio = lockGeneratedAssetDescriptor(segment.filePath, 'narration-audio', {
			extn: 'wav',
			mimeType: 'audio/wav',
			durationMs: segment.durationMs,
			provider: segment.provider || null,
		})
		return { segment, lockedAudio }
	})
	const assembledAudio = lockGeneratedAssetDescriptor(prepared.assembled.filePath, 'narration-audio', {
		extn: 'wav',
		mimeType: 'audio/wav',
		durationMs: prepared.assembled.durationMs,
		provider: prepared.provider || null,
	})
	const manifestBody = {
		schemaVersion: NARRATION_PREPARATION_SCHEMA_VERSION,
		requestDigest: prepared.requestDigest,
		scriptDigest: prepared.scriptDigest,
		audio: {
			ref: assembledAudio.handle,
			digest: assembledAudio.digest,
			durationMs: assembledAudio.durationMs,
			extn: assembledAudio.extn || 'wav',
			mimeType: assembledAudio.mimeType || 'audio/wav',
		},
		segments: segmentLocks.map(({ segment, lockedAudio }) => ({
			id: segment.id,
			slideId: segment.slideId || null,
			textDigest: segment.textHash || hashText(segment.text),
			audio: { ref: lockedAudio.handle, digest: lockedAudio.digest, durationMs: lockedAudio.durationMs, extn: lockedAudio.extn || 'wav', mimeType: lockedAudio.mimeType || 'audio/wav' },
			durationMs: lockedAudio.durationMs,
			gapBeforeMs: segment.gapBeforeMs,
			gapAfterMs: segment.gapAfterMs,
			startMs: segment.startMs,
			endMs: segment.endMs,
			timingEvidence: segment.timingEvidence || 'measured-audio-segment-boundary',
		})),
		voice: publicNarrationVoice(prepared.voice),
		settings: prepared.settings || {},
		timingEvidence: prepared.timingEvidence,
		warnings: publicNarrationWarnings(prepared.warnings),
		retention: 'opaque locked asset handles remain valid while the configured session/tenant retention policy permits them',
		reuse: 'Copy preparedNarration.manifestHandle and preparationId into the semantic narration block; for a multi-slide preparation, select that slide\'s clips with preparedNarration.segmentIds or preparedNarration.slideId. Final generation reuses the exact measured audio and does not synthesize again.',
	}
	const manifestDigest = narrationPreparationDigest(manifestBody)
	const preparationId = `narration-preparation://${manifestDigest}`
	const manifest = { ...manifestBody, preparationId, manifestDigest }
	const manifestArtifact = lockGeneratedAssetBufferDescriptor(Buffer.from(JSON.stringify(stableForHash(manifest)), 'utf8'), 'narration-preparation', {
		extn: 'json',
		mimeType: 'application/json',
	})
	return {
		manifest,
		manifestHandle: manifestArtifact.handle,
		preparationId,
		operationId: preparationId,
		assembledAudio,
		segmentLocks,
	}
}

function preparedNarrationReference(value = {}) {
	if (typeof value === 'string') return { manifestHandle: value }
	if (!value || typeof value !== 'object' || Array.isArray(value)) return {}
	const segmentIds = Array.isArray(value.segmentIds)
		? [...new Set(value.segmentIds.map(id => String(id || '').trim()).filter(Boolean))]
		: []
	return {
		manifestHandle: value.manifestHandle || value.manifest || value.handle,
		preparationId: value.preparationId,
		manifestDigest: value.manifestDigest,
		...(segmentIds.length ? { segmentIds } : {}),
		...(value.slideId != null && String(value.slideId).trim() ? { slideId: String(value.slideId).trim() } : {}),
	}
}

function selectedPreparedNarrationSegments(manifest = {}, reference = {}) {
	const all = Array.isArray(manifest.segments) ? manifest.segments : []
	const requestedIds = Array.isArray(reference.segmentIds) ? reference.segmentIds : []
	const requestedSlideId = String(reference.slideId || '').trim()
	let selected = all
	if (requestedIds.length) {
		const byId = new Map(all.map(segment => [String(segment?.id || ''), segment]))
		const missing = requestedIds.filter(id => !byId.has(id))
		if (missing.length) {
			const error = new Error(`Prepared narration segment selection contains unknown id(s): ${missing.join(', ')}.`)
			error.code = 'NARRATION_PREPARATION_SEGMENT_NOT_FOUND'
			error.details = { status: 'prepared_segment_not_found', missingSegmentIds: missing }
			throw error
		}
		selected = requestedIds.map(id => byId.get(id))
	} else if (requestedSlideId) {
		selected = all.filter(segment => String(segment?.slideId || '').trim() === requestedSlideId)
	}
	if (requestedSlideId) {
		const mismatched = selected.filter(segment => String(segment?.slideId || '').trim() !== requestedSlideId)
		if (mismatched.length) {
			const error = new Error(`Prepared narration segment selection does not belong to slide "${requestedSlideId}".`)
			error.code = 'NARRATION_PREPARATION_SLIDE_MISMATCH'
			error.details = { status: 'prepared_segment_slide_mismatch', slideId: requestedSlideId, segmentIds: mismatched.map(segment => segment?.id).filter(Boolean) }
			throw error
		}
	}
	if ((requestedIds.length || requestedSlideId) && !selected.length) {
		const error = new Error(`Prepared narration contains no segments for slide "${requestedSlideId || 'unspecified'}".`)
		error.code = 'NARRATION_PREPARATION_SEGMENT_NOT_FOUND'
		error.details = { status: 'prepared_segment_selection_empty', slideId: requestedSlideId || null, segmentIds: requestedIds }
		throw error
	}
	return selected
}

function preparedNarrationTimingView(segments = []) {
	let cursor = 0
	const scheduled = segments.map(segment => {
		const gapBeforeMs = Math.max(0, Number(segment?.gapBeforeMs) || 0)
		const gapAfterMs = Math.max(0, Number(segment?.gapAfterMs) || 0)
		const durationMs = Math.max(0, Number(segment?.durationMs ?? segment?.audio?.durationMs) || 0)
		const startMs = cursor + gapBeforeMs
		const endMs = startMs + durationMs
		cursor = endMs + gapAfterMs
		return {
			id: segment.id,
			slideId: segment.slideId || null,
			text: segment.text,
			durationMs,
			gapBeforeMs,
			gapAfterMs,
			startMs,
			endMs,
			audio: { ref: segment.audio?.ref, durationMs: segment.audio?.durationMs },
		}
	})
	return { segments: scheduled, durationMs: cursor }
}

async function resolvePreparedNarration(value = {}) {
	await authorizeAssetReferences(value)
	const reference = preparedNarrationReference(value)
	if (!reference.manifestHandle) {
		const error = new Error('A measured narration preparation requires manifestHandle from betterpptx.narration.synthesize.')
		error.code = 'NARRATION_PREPARATION_REQUIRED'
		error.details = {
			status: 'preparation_handle_missing',
			nextAction: { tool: 'betterpptx.narration.synthesize', reason: 'Prepare and measure the narration before requesting a quote or final generation.' },
		}
		throw error
	}
	let manifestPath
	try { manifestPath = resolveLockedAssetHandle(reference.manifestHandle) } catch {
		const error = new Error('The narration preparation handle is missing or expired. Prepare the narration again and use the returned handle.')
		error.code = 'NARRATION_PREPARATION_EXPIRED'
		error.details = { status: 'preparation_handle_unavailable', manifestHandle: reference.manifestHandle, retryable: false }
		throw error
	}
	let manifest
	try { manifest = JSON.parse(assertAssetBytes(reference.manifestHandle, await fs.readFile(manifestPath)).toString('utf8')) } catch {
		const error = new Error('The narration preparation manifest is unreadable.')
		error.code = 'NARRATION_PREPARATION_INVALID'
		error.details = { status: 'preparation_manifest_unreadable' }
		throw error
	}
	await authorizeAssetReferences(manifest)
	const computedDigest = narrationPreparationDigest(manifest)
	if (!manifest.manifestDigest || manifest.manifestDigest !== computedDigest || (reference.manifestDigest && reference.manifestDigest !== manifest.manifestDigest)) {
		const error = new Error('The narration preparation manifest digest does not match the returned preparation.')
		error.code = 'NARRATION_PREPARATION_INVALID'
		error.details = { status: 'preparation_manifest_digest_mismatch' }
		throw error
	}
	if (reference.preparationId && reference.preparationId !== manifest.preparationId) {
		const error = new Error('The narration preparation identifier does not match its manifest.')
		error.code = 'NARRATION_PREPARATION_INVALID'
		error.details = { status: 'preparation_id_mismatch' }
		throw error
	}
	const audioRef = manifest.audio?.ref
	let audioPath
	try { audioPath = resolveLockedAssetHandle(audioRef) } catch {
		const error = new Error('The prepared narration audio asset is missing or expired.')
		error.code = 'NARRATION_PREPARATION_EXPIRED'
		error.details = { status: 'prepared_audio_unavailable' }
		throw error
	}
	const audioBytes = await fs.readFile(audioPath)
	const audioDigest = crypto.createHash('sha256').update(audioBytes).digest('hex')
	const measured = (await import('./narration/wavDuration.mjs')).parseWavDuration(audioBytes)
	if (manifest.audio.digest !== audioDigest || !measured || measured.durationMs !== Number(manifest.audio.durationMs)) {
		const error = new Error('The prepared narration audio failed its digest or measured-duration check.')
		error.code = 'NARRATION_PREPARATION_INVALID'
		error.details = { status: 'prepared_audio_integrity_failed' }
		throw error
	}
	for (const segment of Array.isArray(manifest.segments) ? manifest.segments : []) {
		let segmentPath
		try { segmentPath = resolveLockedAssetHandle(segment.audio?.ref) } catch {
			const error = new Error(`Prepared narration segment "${segment.id || 'unknown'}" is missing or expired.`)
			error.code = 'NARRATION_PREPARATION_EXPIRED'
			throw error
		}
		const segmentBytes = await fs.readFile(segmentPath)
		const segmentDigest = crypto.createHash('sha256').update(segmentBytes).digest('hex')
		const segmentMeasured = (await import('./narration/wavDuration.mjs')).parseWavDuration(segmentBytes)
		if (segment.audio.digest !== segmentDigest || !segmentMeasured || segmentMeasured.durationMs !== Number(segment.audio.durationMs)) {
			const error = new Error(`Prepared narration segment "${segment.id || 'unknown'}" failed its integrity or duration check.`)
			error.code = 'NARRATION_PREPARATION_INVALID'
			throw error
		}
	}
	const selectedManifestSegments = selectedPreparedNarrationSegments(manifest, reference)
	// A preparation can contain clips for many slides.  Manifest start/end values
	// describe the preparation-wide assembly, while a slide-level selection owns a
	// local clock beginning at zero.  Rebase selected clips without changing their
	// immutable audio, digest, text, or authored gaps.
	const selectedTiming = preparedNarrationTimingView(selectedManifestSegments).segments
	const selectedSegments = selectedManifestSegments.map((segment, index) => ({
		...segment,
		startMs: selectedTiming[index]?.startMs ?? 0,
		endMs: selectedTiming[index]?.endMs ?? Number(segment?.audio?.durationMs || 0),
		durationMs: selectedTiming[index]?.durationMs ?? Number(segment?.audio?.durationMs || 0),
		gapBeforeMs: selectedTiming[index]?.gapBeforeMs ?? 0,
		gapAfterMs: selectedTiming[index]?.gapAfterMs ?? 0,
	}))
	const selection = {
		segmentIds: selectedSegments.map(segment => String(segment.id)),
		...(reference.slideId ? { slideId: reference.slideId } : {}),
	}
	let selectedAudio = {
		filePath: audioPath,
		extn: manifest.audio.extn || 'wav',
		durationMs: measured.durationMs,
		source: 'prepared-narration',
	}
	if ((reference.segmentIds?.length || reference.slideId) && selectedSegments.length === 1) {
		const segment = selectedSegments[0]
		selectedAudio = {
			filePath: resolveLockedAssetHandle(segment.audio.ref),
			extn: segment.audio.extn || 'wav',
			durationMs: Number(segment.audio.durationMs),
			source: 'prepared-narration-segment',
		}
	}
	return {
		manifest,
		selectedSegments,
		selection,
		preparedNarration: {
			preparationId: manifest.preparationId,
			manifestHandle: reference.manifestHandle,
			manifestDigest: manifest.manifestDigest,
			audioRef,
			...(reference.segmentIds?.length ? { segmentIds: selection.segmentIds } : {}),
			...(reference.slideId ? { slideId: reference.slideId } : {}),
		},
		audio: selectedAudio,
	}
}

function preparedNarrationReferenceInSpec(value, depth = 0) {
	if (!value || typeof value !== 'object' || depth > 8) return null
	for (const key of ['preparedNarration', 'narrationPreparation', 'preparedAudio']) {
		const candidate = value[key]
		if (candidate && typeof candidate === 'object' && !Array.isArray(candidate)) return candidate
		if (typeof candidate === 'string' && candidate.trim()) return { manifestHandle: candidate }
	}
	if (Array.isArray(value)) {
		for (const child of value) {
			const found = preparedNarrationReferenceInSpec(child, depth + 1)
			if (found) return found
		}
		return null
	}
	for (const [key, child] of Object.entries(value)) {
		if (key === 'preparedNarration' || key === 'narrationPreparation' || key === 'preparedAudio') continue
		const found = preparedNarrationReferenceInSpec(child, depth + 1)
		if (found) return found
	}
	return null
}

// Read and validate prepared manifests before the compiler creates a quote or
// a dry-run timeline. The returned view contains only opaque handles and
// measured metadata; filesystem paths remain inside resolvePreparedNarration.
async function preparedNarrationTimingBySlideForSpec(spec = {}) {
	const map = {}
	for (const [slideIndex, slide] of (Array.isArray(spec?.slides) ? spec.slides : []).entries()) {
		const reference = preparedNarrationReferenceInSpec(slide)
		if (!reference) continue
		const resolved = await resolvePreparedNarration(reference)
		const manifest = resolved.manifest
		const timing = preparedNarrationTimingView(resolved.selectedSegments)
		map[slideIndex] = {
			manifestDigest: manifest.manifestDigest,
			audio: { durationMs: timing.durationMs, ...(timing.segments.length === (manifest.segments || []).length ? { ref: manifest.audio?.ref } : {}) },
			durationMs: timing.durationMs,
			segments: timing.segments,
			selection: resolved.selection,
			timingEvidence: manifest.timingEvidence,
		}
	}
	return Object.keys(map).length ? map : null
}

function publicNarrationPreparationResult(prepared = {}) {
	const locked = lockNarrationPreparation(prepared)
	const manifest = locked.manifest
	return {
		ok: true,
		state: 'succeeded',
		preparationId: locked.preparationId,
		operationId: locked.operationId,
		manifestHandle: locked.manifestHandle,
		manifestDigest: manifest.manifestDigest,
		schemaVersion: NARRATION_PREPARATION_SCHEMA_VERSION,
		scriptDigest: manifest.scriptDigest,
		audio: {
			ref: locked.assembledAudio.handle,
			digest: locked.assembledAudio.digest,
			durationMs: locked.assembledAudio.durationMs,
			extn: locked.assembledAudio.extn || 'wav',
			mimeType: locked.assembledAudio.mimeType || 'audio/wav',
		},
		durationMs: locked.assembledAudio.durationMs,
		voice: manifest.voice,
		settings: manifest.settings,
		segments: manifest.segments,
		timingEvidence: manifest.timingEvidence,
		retention: manifest.retention,
		reuse: manifest.reuse,
		warnings: manifest.warnings,
		billing: {
			stage: 'preparation',
			quoteBeforeFinalGeneration: true,
			finalGenerationReusesPreparedAudio: true,
			duplicateSynthesisOnReuse: false,
		},
		next: {
			recommendedTool: 'betterpptx.billing.estimate',
			reason: 'Use the returned manifestHandle and preparationId in each semantic narration block. For one multi-slide preparation, bind each slide with preparedNarration.segmentIds or preparedNarration.slideId before accepting the final presentation quote.',
		},
	}
}

async function handleNarrationSynthesize(args) {
	const prepared = await prepareNarrationAudio(args)
	return isPublicBlackBoxMode() ? publicNarrationPreparationResult(prepared) : { ...prepared, ...publicNarrationPreparationResult(prepared) }
}

function resolveNarrationAudioReference(audio) {
	if (audio === undefined || audio === null) return audio
	if (typeof audio === 'string') return { path: resolveGeneratedAssetRefs(audio) }
	if (typeof audio !== 'object' || Array.isArray(audio)) return audio
	const out = resolveGeneratedAssetRefs(audio)
	if (!out.path && !out.data && typeof out.ref === 'string') {
		out.path = resolveGeneratedAssetRefs(audio.ref)
	}
	delete out.ref
	delete out.mimeType
	return out
}

function narrationAudioInputHasSource(audio) {
	if (typeof audio === 'string') return audio.trim().length > 0
	if (!audio || typeof audio !== 'object' || Array.isArray(audio)) return false
	return Boolean(audio.path || audio.handle || audio.url || audio.data || audio.filePath || audio.buffer)
}

function normalizeNarrationProviderContractArgs(args = {}) {
	if (!Object.prototype.hasOwnProperty.call(args, 'narration')) return args
	const narration = validateNarrationProvider(args.narration, 'narration')
	const out = { ...args }
	delete out.narration
	if (narration === null) return { ...out, resetNarration: true }
	if (!narration) return out
	out.script = narration.text ?? out.script
	out.voice = narration.voiceId ?? out.voice
	out.lang = narration.language ?? out.lang
	out.gender = narration.gender ?? out.gender
	out.cues = narration.cues ?? out.cues
	out.timing = narration.timing ?? out.timing
	if (narration.audioRef) out.audio = { ref: narration.audioRef }
	if (narration.autoplay) {
		out.autoplay = narration.autoplay
		if (narration.autoplay.enabled === false) out.useAsTimingAuthority = false
	}
	return out
}

function removeAuthoredNarrationFromSlide(args = {}) {
	const entry = getDeck(args.deckId)
	const slide = getSlide(args.deckId, args.slideIndex)
	const removedObjects = _removeSlideNarration(slide)
	if (entry.narrationManifest?.slides) {
		entry.narrationManifest.slides = entry.narrationManifest.slides.filter(item => Number(item.slideIndex) !== Number(args.slideIndex))
	}
	const hasNarration = Boolean(entry.narrationManifest?.slides?.length || entry.avatarManifest?.slides?.length)
	if (!hasNarration && entry.pptx.showSettings) {
		delete entry.pptx.showSettings.showNarration
		if (!(entry.pptx.slides || []).some(item => (item._animations || []).length)) delete entry.pptx.showSettings.showAnimation
		if (!(entry.pptx.slides || []).some(item => Number(item.transition?.advanceAfterTime) > 0)) delete entry.pptx.showSettings.useTimings
	}
	markDirectorTimelineContract(entry, hasNarration ? 'avatar' : 'none')
	return {
		ok: true,
		slideIndex: args.slideIndex,
		reset: true,
		removedObjects,
		showSettings: entry.pptx.showSettings || {},
	}
}

async function addNarrationToSlide(args) {
	args = normalizeNarrationTimingArgs(args)
	assertPublicNarrationHasNoOverlayCaptions(args)
	if (Array.isArray(args.segments) && args.segments.filter(s => s && (s.script != null || s.audio)).length) {
		return await addSegmentedNarrationToSlide(args)
	}
	// A prepared narration may select several immutable clips by segmentIds or
	// slideId without repeating those segments in the authored slide.  Treat that
	// selection as a first-class segmented narration.  Falling through to the
	// single-clip path would embed the preparation's assembled master track on
	// every slide, defeating both the selection and its measured timing.
	if (args.preparedNarration) {
		const preparedSelection = await resolvePreparedNarration(args.preparedNarration)
		if (Array.isArray(preparedSelection.selectedSegments) && preparedSelection.selectedSegments.length > 1) {
			const selectedTiming = preparedNarrationTimingView(preparedSelection.selectedSegments).segments
			return await addSegmentedNarrationToSlide({
				...args,
				segments: selectedTiming.map(segment => ({
					id: segment.id,
					script: segment.text || '',
					gapBeforeMs: segment.gapBeforeMs,
					gapAfterMs: segment.gapAfterMs,
					audio: { path: segment.audio?.ref, durationMs: segment.audio?.durationMs },
				})),
			})
		}
	}
	const entry = getDeck(args.deckId)
	const { pptx } = entry
	const slide = getSlide(args.deckId, args.slideIndex)
	const script = args.script != null ? String(args.script) : ''
	const prepared = args.preparedNarration ? await resolvePreparedNarration(args.preparedNarration) : null
	if (!script && !args.audio && !prepared && args.synthesizeAudio !== false) throw new Error('slide.add_narration requires script, a prepared narration, or audio.')
	if (args.synthesizeAudio === false) {
		if (args.preserveInNotes !== false && script) _addNarrationNotes(slide, script)
		const startDelayMs = narrationMs(args.startDelayMs)
		const expectedDurationMs = narrationMs(args.expectedDurationMs) || narrationMs(slide.transition?.advanceAfterTime) || 0
		const cueTiming = applyNarrationCues(slide, resolveCueAnchors(args.cues || [], script, expectedDurationMs || 1), { baseDelayMs: startDelayMs })
		const paddingMs = args.paddingMs === undefined ? 0 : narrationMs(args.paddingMs)
		const advanceAfterTime = expectedDurationMs
			? clampAdvanceMs(Math.max(expectedDurationMs, cueTiming.maxEndMs || 0) + Math.max(0, paddingMs), 1000)
			: (slide.transition?.advanceAfterTime || null)
		if (advanceAfterTime && (args.useAsTimingAuthority !== false)) {
			pptx.showSettings = {
				...(pptx.showSettings || {}),
				useTimings: true,
				showAnimation: true,
				showNarration: false,
			}
			slide.transition = {
				...(slide.transition || { type: 'fade', speed: 'medium' }),
				advanceOnClick: false,
				advanceAfterTime,
			}
			_retimeRawTransitionXml(slide, advanceAfterTime)
		}
		if (args.useAsTimingAuthority === false) {
			// Notes-only output still contains native cue animations; advertise that
			// animation lane without claiming that authored notes own slide dwell.
			pptx.showSettings = { ...(pptx.showSettings || {}), showAnimation: true }
		}
		// SILENT/TIMED-NOTES is an explicit authored output variant, not a
		// best-effort fallback. It still needs the same durable manifest channel
		// as synthesized narration so export_spec, the opaque edition sidecar,
		// and a save→open_uploaded cycle retain authored cues and timing.
		entry.narrationManifest = entry.narrationManifest || { schemaVersion: 1, slides: [] }
		const authoredSync = _captureAuthoredSync(args)
		const normalizedScript = script.replace(/\s+/g, ' ').trim()
		const silentSlideEntry = {
			slideIndex: args.slideIndex,
			silentTimedNotes: true,
			synthesizedAudio: false,
			preserveInNotes: args.preserveInNotes !== false,
			...(normalizedScript ? { scriptHash: hashText(normalizedScript) } : {}),
			expectedDurationMs: expectedDurationMs || undefined,
			...(args.useAsTimingAuthority !== false && advanceAfterTime ? { advanceAfterTime } : {}),
			startDelayMs,
			paddingMs,
			cueTimelineEndMs: cueTiming.maxEndMs,
			timelineEndMs: Math.max(startDelayMs, cueTiming.maxEndMs || 0, expectedDurationMs || 0),
			requestedCues: Array.isArray(args.cues) ? args.cues.length : 0,
			cues: cueTiming.applied,
			cueTimings: cueTiming.timings,
			...authoredSync,
		}
		entry.narrationManifest.slides = entry.narrationManifest.slides.filter(s => s.slideIndex !== args.slideIndex)
		entry.narrationManifest.slides.push(silentSlideEntry)
		return {
			ok: true,
			synthesizedAudio: false,
			preserveInNotes: args.preserveInNotes !== false,
			useAsTimingAuthority: args.useAsTimingAuthority !== false,
			scriptCharacters: script.length,
			cues: cueTiming.applied,
			advanceAfterTime: advanceAfterTime || undefined,
			warnings: [],
		}
	}
	const resolved = prepared
		? {
			audio: prepared.audio,
			voice: null,
			license: null,
			warnings: [],
			textHash: prepared.manifest.scriptDigest,
			provider: null,
			preparedNarration: prepared.preparedNarration,
		}
		: await resolveNarrationAudio({
			script,
			synthesisText: args.synthesisText,
			audio: resolveNarrationAudioReference(args.audio),
			voice: args.voice,
			lang: args.lang,
			gender: args.gender,
			provider: args.provider,
			speaker: args.speaker,
			lengthScale: args.lengthScale,
			noiseScale: args.noiseScale,
			noiseWScale: args.noiseWScale,
			allowUnreviewedVoices: args.allowUnreviewedVoices,
		})
	const expectedDurationMs = narrationMs(args.expectedDurationMs)
	const timingToleranceMs = narrationTimingToleranceMs(args.timingToleranceMs, expectedDurationMs)
	const durationDriftMs = expectedDurationMs ? Math.abs(narrationMs(resolved.audio.durationMs) - expectedDurationMs) : 0
	const timingWarnings = [...(resolved.warnings || [])]
	if (expectedDurationMs && durationDriftMs > timingToleranceMs) {
		timingWarnings.push({
			code: 'NARRATION_DURATION_DRIFT',
			message: `Resolved narration duration ${resolved.audio.durationMs}ms differs from authored expectedDurationMs ${expectedDurationMs}ms by ${durationDriftMs}ms.`,
			expectedDurationMs,
			actualDurationMs: resolved.audio.durationMs,
			toleranceMs: timingToleranceMs,
		})
	}
	_addNarrationNotes(slide, script)

	const objectName = args.objectName || makeNarrationObjectName(args.slideIndex)
	slide.addMedia({
		type: 'audio',
		path: resolved.audio.filePath,
		extn: resolved.audio.extn || 'wav',
		cover: args.cover || TRANSPARENT_PIXEL_PNG,
		transparency: args.transparency ?? 100,
		...narrationMediaFrame(pptx, args),
		objectName,
		spid: _nextFreeSlideSpid(slide),
		isNarration: true,
		showWhenStopped: false,
		endOnStopAudio: true,
		interactivePlayback: false,
		closedCaptionTracks: closedCaptionTracksForArgs(args, { cues: args.cues || [], script }),
		altText: args.altText || args.options?.altText || 'Narration audio for this slide.',
	})
	const mediaObj = slide._slideObjects[slide._slideObjects.length - 1]
	mediaObj.options = mediaObj.options || {}
	mediaObj.options.altText = args.altText || args.options?.altText || 'Narration audio for this slide.'
	const startDelayMs = narrationMs(args.startDelayMs)
	slide.addAnimation(mediaObj, normalizeAnimation({
		type: 'media',
		effect: 'mediaplay',
		mediaCommand: 'playFrom(0.0)',
		trigger: args.playTrigger || 'afterPrevious',
		delay: startDelayMs,
		duration: 1,
	}))

	// The inline narration path has just resolved its own audio. Avatar attach
	// uses a separate helper below; do not reference that path's variables here.
	const narrationDurationMs = narrationMs(resolved.audio.durationMs)
	const cueTiming = applyNarrationCues(slide, balanceSyncedBuildBeats(resolveCueAnchors(args.cues || [], script, narrationDurationMs), { minIntervalMs: narrationMs(args.syncBuildMinIntervalMs) || 650, audioDurationMs: narrationDurationMs }), { baseDelayMs: startDelayMs })
	const captionConfig = args.avatarAwareCaptions === true || entry._avatarAwareSlides?.has(Number(args.slideIndex))
		? makeAvatarAwareCaptionConfig({
			captions: args.captions,
			avatarBox: avatarVideoBox({}),
			slideHeight: previewSlideLayout(pptx).heightInches,
			footerHeight: 0.62,
		})
		: args.captions
	const captionTiming = applyNarrationCaptions(slide, captionConfig, args.cues || [], script, { baseDelayMs: startDelayMs, audioDurationMs: resolved.audio.durationMs })
	const requestedCues = Array.isArray(args.cues) ? args.cues.length : 0
	if (requestedCues > cueTiming.applied) {
		timingWarnings.push({
			code: 'NARRATION_CUE_TARGET_MISSING',
			severity: 'warning',
			message: `${requestedCues - cueTiming.applied} narration cue target(s) were not found; create visual objects before narration and target stable objectName values.`,
			requestedCues,
			appliedCues: cueTiming.applied,
			reason: 'One or more authored narration cues could not resolve to a visible semantic object, so the requested spoken-to-visual beat was not applied.',
			fix: 'Create or name the target visual before narration, target a stable content[].name/objectName, or remove the stale cue and rerun dryRun.',
			evidence: { requestedCues, appliedCues: cueTiming.applied, missingCues: requestedCues - cueTiming.applied, targetAuthority: 'stable semantic object name' },
		})
	}
	const paddingMs = args.paddingMs === undefined ? 700 : narrationMs(args.paddingMs)
	const audioEndMs = startDelayMs + narrationMs(resolved.audio.durationMs)
	// TEXT IS THE MASTER: the narration governs the dwell — dwell = max(audioEnd, beats) + tail.
	// The visual-comfort floor is ADVISORY only (it never extends the dwell); if the audio can't
	// cover it we flag the AI to fix the TEXT, we never pad the slide into trailing silence.
	const visualFloorMs = narrationMs(args.visualFloorMs) || 0
	const timelineEndMs = Math.max(audioEndMs, cueTiming.maxEndMs, captionTiming.maxEndMs)
	const advanceAfterTime = clampAdvanceMs(timelineEndMs + Math.max(0, paddingMs), 1000)
	assertLikelyMilliseconds(advanceAfterTime, 'narration advanceAfterTime')
	if (visualFloorMs && audioEndMs < visualFloorMs * 0.85) {
		 timingWarnings.push({
			code: 'NARRATION_TOO_SHORT_FOR_CONTENT',
			severity: 'warning',
			message: `Narration audio (${resolved.audio.durationMs}ms) is shorter than the time needed to read/reveal this slide's content (~${visualFloorMs}ms). Text is the master clock, so the slide advances at ${advanceAfterTime}ms (with the words) — lengthen or slow the narration, split it into segments with pauses, or reduce on-slide content so the words carry it.`,
			audioDurationMs: resolved.audio.durationMs,
			visualFloorMs,
			reason: 'The spoken text ends before the engine-measured visual comfort/read time, so the slide would feel rushed if the words remain unchanged.',
			fix: 'Lengthen or slow the narration, split it into segments with real pauses, or reduce on-slide content; the engine will not pad silence into the timing.',
			evidence: { audioDurationMs: resolved.audio.durationMs, visualFloorMs, advanceAfterTime, timingAuthority: 'narration-text' },
		})
	}
	const autoplayEnabled = args.autoplay?.enabled !== false && args.useAsTimingAuthority !== false
	pptx.showSettings = {
		...(pptx.showSettings || {}),
		...(autoplayEnabled ? { useTimings: true } : {}),
		showAnimation: true,
		showNarration: true,
		...(args.autoplay?.loop !== undefined ? { loop: args.autoplay.loop } : {}),
		...(args.autoplay?.mode ? { mode: args.autoplay.mode } : {}),
	}
	if (autoplayEnabled) {
		slide.transition = {
			...(slide.transition || { type: 'fade', speed: 'medium' }),
			advanceOnClick: false,
			advanceAfterTime,
		}
		// Uploaded decks preserve their transition as raw XML which outranks slide.transition at
		// write — re-time the advance inside it too, keeping the original transition visual.
		_retimeRawTransitionXml(slide, advanceAfterTime)
	}
	entry.narrationManifest = entry.narrationManifest || { schemaVersion: 1, slides: [] }
	const slideEntry = {
		slideIndex: args.slideIndex,
		audioObjectName: objectName,
		audioPath: resolved.audio.filePath,
		durationMs: resolved.audio.durationMs,
		expectedDurationMs: expectedDurationMs || undefined,
		timingToleranceMs,
		durationDriftMs,
		...(autoplayEnabled ? { advanceAfterTime } : {}),
		startDelayMs,
		paddingMs,
		audioEndMs,
		cueTimelineEndMs: cueTiming.maxEndMs,
		captionTimelineEndMs: captionTiming.maxEndMs,
		timelineEndMs,
		scriptHash: script ? hashText(script.replace(/\s+/g, ' ').trim()) : resolved.textHash,
		voiceId: resolved.voice?.id || null,
		gender: resolved.voice?.gender || args.gender || null,
		...(resolved.voice?.speaker !== undefined ? { speaker: resolved.voice.speaker } : {}),
		provider: resolved.provider || (args.audio ? 'external-audio' : args.provider || process.env.BETTERPPTX_TTS_PROVIDER || 'piper-http'),
		license: resolved.license || null,
		requestedCues,
		cues: cueTiming.applied,
		captions: captionTiming.applied,
		cueTimings: cueTiming.timings,
		captionTimings: captionTiming.timings,
		..._captureAuthoredSync(args),
		...(resolved.preparedNarration ? { preparedNarration: resolved.preparedNarration, timingEvidence: prepared.manifest.timingEvidence } : {}),
	}
	entry.narrationManifest.slides = entry.narrationManifest.slides.filter(s => s.slideIndex !== args.slideIndex)
	entry.narrationManifest.slides.push(slideEntry)
	logEvent('narration.embed.audio', {
		deckId: args.deckId,
		slideIndex: args.slideIndex,
		objectName,
		durationMs: resolved.audio.durationMs,
		advanceAfterTime,
		autoplayEnabled,
		voiceId: resolved.voice?.id,
		provider: slideEntry.provider,
		cuesApplied: cueTiming.applied,
		captionsApplied: captionTiming.applied,
		timelineEndMs,
		warnings: timingWarnings,
	})
	return {
		ok: true,
		slideIndex: args.slideIndex,
		audio: isPublicBlackBoxMode()
			? { durationMs: resolved.audio.durationMs, extn: resolved.audio.extn || 'wav' }
			: { wavPath: resolved.audio.filePath, durationMs: resolved.audio.durationMs, extn: resolved.audio.extn },
		advanceAfterTime,
		autoplayEnabled,
		timing: { startDelayMs, audioEndMs, cueTimelineEndMs: cueTiming.maxEndMs, captionTimelineEndMs: captionTiming.maxEndMs, timelineEndMs, paddingMs },
		cues: cueTiming.applied,
		captions: captionTiming.applied,
		voice: isPublicBlackBoxMode() ? publicNarrationVoice(resolved.voice) : resolved.voice,
		...(resolved.preparedNarration ? { preparedNarration: resolved.preparedNarration, timingEvidence: prepared.manifest.timingEvidence } : {}),
		...(isPublicBlackBoxMode() ? {} : { license: resolved.license }),
		warnings: isPublicBlackBoxMode() ? publicNarrationWarnings(timingWarnings) : timingWarnings,
	}
}

// SEGMENTED NARRATION — a slide's narration is an ORDERED TIMELINE of clips + silences instead
// of one continuous clip. Each segment is synthesized as its own audio (rate-adjustable per
// segment), placed on the slide timeline at an absolute offset via a mediaplay animation, and
// the gap between one clip's end and the next clip's start is REAL silence (no SSML needed).
// This makes pauses live INSIDE a slide and lets builds/emphasis lock to the exact clip that
// speaks them. Falls back to the single-clip path when no segments[] are given.
async function addSegmentedNarrationToSlide(args) {
	const entry = getDeck(args.deckId)
	const { pptx } = entry
	const slide = getSlide(args.deckId, args.slideIndex)
	const rawSegments = (Array.isArray(args.segments) ? args.segments : []).filter(s => s && (s.script != null || s.audio))
	if (!rawSegments.length) throw new Error('slide.add_narration segments[] requires each segment to have script or audio.')
	// Caption timestamps are local to their native media owner, not the slide.
	// Resolve every track before audio preparation or slide mutation.
	const segmentCaptionTracks = segmentCaptionTracksForArgs(args, rawSegments)
	const prepared = args.preparedNarration ? await resolvePreparedNarration(args.preparedNarration) : null
	if (prepared && (!Array.isArray(prepared.selectedSegments) || prepared.selectedSegments.length < rawSegments.length)) {
		const error = new Error('The prepared narration manifest does not contain one measured clip for every authored segment.')
		error.code = 'NARRATION_PREPARATION_INVALID'
		throw error
	}

	const startDelayMs = narrationMs(args.startDelayMs)
	const defaultGapMs = narrationMs(args.segmentGapMs)
	const timingWarnings = []

	// 1) Resolve every clip's audio first so durations are known before scheduling.
	const clips = []
	for (const [segmentIndex, seg] of rawSegments.entries()) {
		const segScript = seg.script != null ? String(seg.script) : ''
		const preparedSegment = prepared?.selectedSegments?.[segmentIndex]
		const resolved = preparedSegment
			? {
				audio: {
					filePath: resolveLockedAssetHandle(preparedSegment.audio.ref),
					extn: preparedSegment.audio.extn || 'wav',
					durationMs: preparedSegment.audio.durationMs,
					source: 'prepared-narration',
				},
				voice: null,
				license: null,
				warnings: [],
				textHash: preparedSegment.textDigest,
				provider: null,
			}
			: await resolveNarrationAudio({
				script: segScript,
				synthesisText: seg.synthesisText,
				audio: resolveNarrationAudioReference(seg.audio),
				voice: seg.voice ?? args.voice,
				lang: seg.lang ?? args.lang,
				gender: seg.gender ?? args.gender,
				provider: seg.provider ?? args.provider,
				speaker: seg.speaker ?? args.speaker,
				lengthScale: seg.lengthScale ?? args.lengthScale,
				noiseScale: seg.noiseScale ?? args.noiseScale,
				noiseWScale: seg.noiseWScale ?? args.noiseWScale,
				allowUnreviewedVoices: seg.allowUnreviewedVoices ?? args.allowUnreviewedVoices,
			})
		clips.push({ seg, script: segScript, resolved })
		timingWarnings.push(...(resolved.warnings || []))
	}

	// 2) Schedule clips on the timeline; gapBefore/gapAfter (or segmentGapMs) are the silences.
	const baseName = args.objectName || makeNarrationObjectName(args.slideIndex)
	let cursor = startDelayMs
	let cueApplied = 0
	let requestedCues = 0
	let cueMaxEndMs = startDelayMs
	const cueTimingsAll = []
	const scheduled = []
	const combinedScriptParts = []
	const captionItems = []
	for (let i = 0; i < clips.length; i++) {
		const { seg, script, resolved } = clips[i]
		const gapBefore = narrationMs(seg.gapBeforeMs ?? seg.pauseBeforeMs ?? (i === 0 ? 0 : defaultGapMs))
		cursor += gapBefore
		const segStartMs = cursor
		const durationMs = narrationMs(resolved.audio.durationMs)
		const preparedSegment = prepared?.selectedSegments?.[i]
		if (preparedSegment && (Number(preparedSegment.startMs) !== segStartMs || Number(preparedSegment.endMs) !== segStartMs + durationMs)) {
			const error = new Error(`Segment "${preparedSegment.id}" no longer matches the measured preparation timeline.`)
			error.code = 'NARRATION_PREPARATION_TIMING_MISMATCH'
			error.details = { segmentId: preparedSegment.id, preparedStartMs: preparedSegment.startMs, authoredStartMs: segStartMs, preparedEndMs: preparedSegment.endMs, authoredEndMs: segStartMs + durationMs }
			throw error
		}
		const objectName = seg.objectName || `${baseName}-seg${i + 1}`
		slide.addMedia({
			type: 'audio',
			path: resolved.audio.filePath,
			extn: resolved.audio.extn || 'wav',
			cover: args.cover || TRANSPARENT_PIXEL_PNG,
			transparency: args.transparency ?? 100,
			...narrationMediaFrame(pptx, args, i),
			objectName,
			spid: _nextFreeSlideSpid(slide),
			isNarration: true,
			showWhenStopped: false,
			endOnStopAudio: true,
			interactivePlayback: false,
			altText: args.altText || args.options?.altText || `Narration audio segment ${i + 1}: ${script || 'spoken content'}`,
			closedCaptionTracks: segmentCaptionTracks[i],
		})
		const mediaObj = slide._slideObjects[slide._slideObjects.length - 1]
		mediaObj.options = mediaObj.options || {}
		mediaObj.options.altText = args.altText || args.options?.altText || `Narration audio segment ${i + 1}: ${script || 'spoken content'}`
		// Absolute scheduling: clip 0 keeps afterPrevious (identical to the single-clip path);
		// later clips use withPrevious + an absolute delay so each starts exactly at segStartMs.
		slide.addAnimation(mediaObj, normalizeAnimation({
			type: 'media',
			effect: 'mediaplay',
			mediaCommand: 'playFrom(0.0)',
			trigger: i === 0 ? 'afterPrevious' : 'withPrevious',
			delay: segStartMs,
			duration: 1,
		}))
		// Per-segment cues anchor INSIDE this clip (baseDelay = the clip's start).
		if (Array.isArray(seg.cues) && seg.cues.length) {
			requestedCues += seg.cues.length
			const ct = applyNarrationCues(slide, resolveCueAnchors(seg.cues, script, durationMs), { baseDelayMs: segStartMs })
			cueApplied += ct.applied
			cueMaxEndMs = Math.max(cueMaxEndMs, ct.maxEndMs)
			cueTimingsAll.push(...ct.timings)
		}
		// Overlay captions from segment text are removed. Native WebVTT is media-track only.
		combinedScriptParts.push(script)
		const gapAfter = narrationMs(seg.gapAfterMs ?? seg.pauseAfterMs ?? 0)
		let authoredSegCues
		if (Array.isArray(seg.cues) && seg.cues.length) { try { authoredSegCues = JSON.parse(JSON.stringify(seg.cues)) } catch { authoredSegCues = undefined } }
		scheduled.push({ objectName, segStartMs, durationMs, gapBeforeMs: gapBefore, gapAfterMs: gapAfter, endMs: segStartMs + durationMs, script, voiceId: resolved.voice?.id || null, gender: resolved.voice?.gender || seg.gender || null, speaker: resolved.voice?.speaker ?? seg.speaker, cues: authoredSegCues, scriptHash: script ? hashText(script.replace(/\s+/g, ' ').trim()) : resolved.textHash })
		cursor = segStartMs + durationMs + gapAfter
	}

	// 3) Top-level cues resolve across the whole multi-segment timeline (absolute atMs).
	if (Array.isArray(args.cues) && args.cues.length) {
		requestedCues += args.cues.length
		const anchored = resolveCueAnchorsMultiSegment(args.cues, scheduled.map((s, i) => ({ script: clips[i].script, startMs: s.segStartMs, durationMs: s.durationMs })))
		const spanEndMs = scheduled.reduce((m, s) => Math.max(m, s.endMs), startDelayMs)
		const balanced = balanceSyncedBuildBeats(anchored, { minIntervalMs: narrationMs(args.syncBuildMinIntervalMs) || 650, audioDurationMs: spanEndMs })
		const ct = applyNarrationCues(slide, balanced, { baseDelayMs: 0 })
		cueApplied += ct.applied
		cueMaxEndMs = Math.max(cueMaxEndMs, ct.maxEndMs)
		cueTimingsAll.push(...ct.timings)
	}

	const combinedScript = combinedScriptParts.filter(Boolean).join(' ')
	_addNarrationNotes(slide, combinedScript)

	const lastClipEndMs = scheduled.reduce((m, s) => Math.max(m, s.endMs), startDelayMs)
	const captionsCfg = captionItems.length ? { ...(args.captions || {}), items: captionItems } : args.captions
	const captionTiming = applyNarrationCaptions(slide, captionsCfg, args.cues || [], combinedScript, { baseDelayMs: startDelayMs, audioDurationMs: Math.max(0, lastClipEndMs - startDelayMs) })

	if (requestedCues > cueApplied) {
		timingWarnings.push({
			code: 'NARRATION_CUE_TARGET_MISSING',
			severity: 'warning',
			message: `${requestedCues - cueApplied} narration cue target(s) were not found; create visual objects before narration and target stable objectName values.`,
			requestedCues,
			appliedCues: cueApplied,
			reason: 'One or more authored narration cues could not resolve to a visible semantic object, so the requested spoken-to-visual beat was not applied.',
			fix: 'Create or name the target visual before narration, target a stable content[].name/objectName, or remove the stale cue and rerun dryRun.',
			evidence: { requestedCues, appliedCues: cueApplied, missingCues: requestedCues - cueApplied, targetAuthority: 'stable semantic object name' },
		})
	}

	const paddingMs = args.paddingMs === undefined ? 700 : narrationMs(args.paddingMs)
	const visualFloorMs = narrationMs(args.visualFloorMs) || 0
	// TEXT IS THE MASTER: the segment timeline (clips + author-authored silence gaps) governs
	// the dwell. cursor includes any trailing gapAfter on the last segment (intentional end
	// silence, which the author put there). The visual-comfort floor is advisory only.
	const audioSpanEndMs = Math.max(lastClipEndMs, cursor)
	const timelineEndMs = Math.max(audioSpanEndMs, cueMaxEndMs, captionTiming.maxEndMs)
	const advanceAfterTime = clampAdvanceMs(timelineEndMs + Math.max(0, paddingMs), 1000)
	assertLikelyMilliseconds(advanceAfterTime, 'narration advanceAfterTime')
	if (visualFloorMs && audioSpanEndMs < visualFloorMs * 0.85) {
		timingWarnings.push({
			code: 'NARRATION_TOO_SHORT_FOR_CONTENT',
			severity: 'warning',
			message: `Segmented narration ends at ${audioSpanEndMs}ms, shorter than the time needed to read/reveal this slide's content (~${visualFloorMs}ms). Text is the master clock, so the slide advances at ${advanceAfterTime}ms (with the words) — lengthen a segment, slow the voice, add a gap, or reduce on-slide content.`,
			audioDurationMs: audioSpanEndMs - startDelayMs,
			visualFloorMs,
			reason: 'The spoken segment timeline ends before the engine-measured visual comfort/read time, so the slide would feel rushed if the words remain unchanged.',
			fix: 'Lengthen or slow a segment, add a real authored gap, or reduce on-slide content; the engine will not pad silence into the timing.',
			evidence: { audioDurationMs: audioSpanEndMs - startDelayMs, visualFloorMs, advanceAfterTime, segmentCount: scheduled.length, timingAuthority: 'narration-text' },
		})
	}

	const autoplayEnabled = args.autoplay?.enabled !== false && args.useAsTimingAuthority !== false
	pptx.showSettings = {
		...(pptx.showSettings || {}),
		...(autoplayEnabled ? { useTimings: true } : { useTimings: false }),
		showAnimation: true,
		showNarration: true,
	}
	if (autoplayEnabled) {
		slide.transition = {
			...(slide.transition || { type: 'fade', speed: 'medium' }),
			advanceOnClick: false,
			advanceAfterTime,
		}
		_retimeRawTransitionXml(slide, advanceAfterTime)
	} else {
		slide.transition = {
			...(slide.transition || { type: 'fade', speed: 'medium' }),
			advanceOnClick: true,
		}
		delete slide.transition.advanceAfterTime
	}

	const totalSpokenMs = scheduled.reduce((sum, s) => sum + s.durationMs, 0)
	entry.narrationManifest = entry.narrationManifest || { schemaVersion: 1, slides: [] }
	const slideEntry = {
		slideIndex: args.slideIndex,
		segmented: true,
		segmentCount: scheduled.length,
		audioObjectName: scheduled[0]?.objectName,
		audioPath: clips[0]?.resolved?.audio?.filePath,
		durationMs: Math.max(0, lastClipEndMs - startDelayMs),
		totalSpokenMs,
		...(autoplayEnabled ? { advanceAfterTime } : {}),
		autoplayEnabled,
		startDelayMs,
		paddingMs,
		audioEndMs: lastClipEndMs,
		cueTimelineEndMs: cueMaxEndMs,
		captionTimelineEndMs: captionTiming.maxEndMs,
		timelineEndMs,
		scriptHash: combinedScript ? hashText(combinedScript.replace(/\s+/g, ' ').trim()) : undefined,
		voiceId: clips[0]?.resolved?.voice?.id || null,
		gender: clips[0]?.resolved?.voice?.gender || args.gender || null,
		...(clips[0]?.resolved?.voice?.speaker !== undefined ? { speaker: clips[0].resolved.voice.speaker } : {}),
		provider: clips[0]?.resolved?.provider || args.provider || process.env.BETTERPPTX_TTS_PROVIDER || 'piper-http',
		license: clips[0]?.resolved?.license || null,
		requestedCues,
		cues: cueApplied,
		captions: captionTiming.applied,
		cueTimings: cueTimingsAll,
		// R-SEG — the segment TIMELINE INCLUDING each clip's spoken script + voice + silences +
		// authored cues, so export_spec round-trips the real multi-clip structure, beats included.
		segments: scheduled.map(s => ({ objectName: s.objectName, startMs: s.segStartMs, durationMs: s.durationMs, gapBeforeMs: s.gapBeforeMs, gapAfterMs: s.gapAfterMs, endMs: s.endMs, script: s.script, voiceId: s.voiceId, gender: s.gender, ...(s.speaker !== undefined ? { speaker: s.speaker } : {}), ...(s.caption ? { caption: s.caption } : {}), ...(Array.isArray(s.cues) && s.cues.length ? { cues: s.cues } : {}) })),
		segmentsSignature: _segmentsSignature(scheduled.map(s => ({ script: s.script, gapBeforeMs: s.gapBeforeMs, gapAfterMs: s.gapAfterMs, voice: s.voiceId, gender: s.gender, speaker: s.speaker }))),
		...(prepared ? { preparedNarration: prepared.preparedNarration, timingEvidence: prepared.manifest.timingEvidence } : {}),
		..._captureAuthoredSync(args),
	}
	entry.narrationManifest.slides = entry.narrationManifest.slides.filter(s => s.slideIndex !== args.slideIndex)
	entry.narrationManifest.slides.push(slideEntry)
	logEvent('narration.embed.segmented', {
		deckId: args.deckId,
		slideIndex: args.slideIndex,
		segmentCount: scheduled.length,
		totalSpokenMs,
		...(autoplayEnabled ? { advanceAfterTime } : {}),
		autoplayEnabled,
		voiceId: slideEntry.voiceId,
		provider: slideEntry.provider,
		cuesApplied: cueApplied,
		captionsApplied: captionTiming.applied,
		timelineEndMs,
		warnings: timingWarnings,
	})
	return {
		ok: true,
		slideIndex: args.slideIndex,
		segmented: true,
		segments: scheduled.map((s, i) => ({
			objectName: s.objectName,
			startMs: s.segStartMs,
			gapBeforeMs: s.gapBeforeMs,
			...(isPublicBlackBoxMode()
				? { durationMs: s.durationMs, extn: clips[i]?.resolved?.audio?.extn || 'wav' }
				: { wavPath: clips[i]?.resolved?.audio?.filePath, durationMs: s.durationMs, extn: clips[i]?.resolved?.audio?.extn }),
		})),
		advanceAfterTime,
		timing: { startDelayMs, audioEndMs: lastClipEndMs, cueTimelineEndMs: cueMaxEndMs, captionTimelineEndMs: captionTiming.maxEndMs, timelineEndMs, paddingMs, totalSpokenMs },
		cues: cueApplied,
		captions: captionTiming.applied,
		voice: isPublicBlackBoxMode() ? publicNarrationVoice(clips[0]?.resolved?.voice) : clips[0]?.resolved?.voice,
		...(prepared ? { preparedNarration: prepared.preparedNarration, timingEvidence: prepared.manifest.timingEvidence } : {}),
		...(isPublicBlackBoxMode() ? {} : { license: clips[0]?.resolved?.license }),
		warnings: isPublicBlackBoxMode() ? publicNarrationWarnings(timingWarnings) : timingWarnings,
	}
}

async function handleSlideAddNarration(args) {
	args = normalizeNarrationProviderContractArgs(args)
	if (args.resetNarration === true) return removeAuthoredNarrationFromSlide(args)
	const result = await addNarrationToSlide(args)
	markDirectorTimelineContract(getDeck(args.deckId), 'narration')
	return result
}

async function handleDeckAddNarration(args) {
	const { pptx } = getDeck(args.deckId)
	const slides = Array.isArray(args.slides) ? args.slides : []
	if (!slides.length) throw new Error('deck.add_narration requires slides[].')
	const results = []
	for (const item of slides) {
		const normalizedItem = normalizeNarrationProviderContractArgs(item)
		const slideArgs = {
			...normalizedItem,
			deckId: args.deckId,
			voice: normalizedItem.voice ?? args.tts?.voice ?? args.voice,
			lang: normalizedItem.lang ?? args.tts?.lang ?? args.lang,
			gender: normalizedItem.gender ?? args.tts?.gender ?? args.gender,
			provider: normalizedItem.provider ?? args.tts?.provider ?? args.provider,
			speaker: normalizedItem.speaker ?? args.tts?.speaker,
			lengthScale: normalizedItem.lengthScale ?? args.tts?.lengthScale,
			noiseScale: normalizedItem.noiseScale ?? args.tts?.noiseScale,
			noiseWScale: normalizedItem.noiseWScale ?? args.tts?.noiseWScale,
			paddingMs: normalizedItem.paddingMs ?? normalizedItem.timing?.paddingMs ?? normalizedItem.timeline?.paddingMs ?? normalizedItem.narrationTiming?.paddingMs ?? args.autoplay?.paddingMs ?? args.paddingMs,
			closedCaptionTracks: normalizedItem.closedCaptionTracks || normalizedItem.audio?.closedCaptionTracks || args.closedCaptionTracks,
			allowUnreviewedVoices: normalizedItem.allowUnreviewedVoices ?? args.allowUnreviewedVoices,
		}
		results.push(slideArgs.resetNarration === true ? removeAuthoredNarrationFromSlide(slideArgs) : await addNarrationToSlide(slideArgs))
	}
	markDirectorTimelineContract(getDeck(args.deckId), 'narration')
	pptx.showSettings = {
		useTimings: true,
		showAnimation: true,
		showNarration: true,
		loop: args.autoplay?.loop ?? args.loop ?? false,
		mode: args.autoplay?.mode || args.mode || 'present',
		showMediaControls: args.showMediaControls ?? true,
	}
	const estimatedRuntimeMs = results.reduce((sum, r) => sum + (r.advanceAfterTime || 0), 0)
	logEvent('narration.timing.plan', {
		deckId: args.deckId,
		slides: results.length,
		estimatedRuntimeMs,
		showSettings: pptx.showSettings,
	})
	return { ok: true, slides: results, estimatedRuntimeMs, showSettings: pptx.showSettings }
}

function avatarVideoBox(args = {}) {
	return {
		// Shared accepted talking-head window: engine-owned ellipse with
		// centered cover. Semantic clients do not author this geometry, and
		// primitive callers cannot move it into a rectangular presenter frame.
		x: 10.993,
		y: 5.160,
		w: 2.25,
		h: 2.25,
	}
}

function recordAvatarManifestSlide(entry, slideEntry) {
	entry.avatarManifest = entry.avatarManifest || { schemaVersion: 1, slides: [] }
	entry.avatarManifest.slides = entry.avatarManifest.slides.filter(s => s.slideIndex !== slideEntry.slideIndex)
	entry.avatarManifest.slides.push(slideEntry)
}

function publicAvatarManifest(manifest) {
	if (!manifest || typeof manifest !== 'object') return null
	return {
		schemaVersion: manifest.schemaVersion,
		slides: (manifest.slides || []).map(({ videoPath, posterPath, provider, cacheKey, ...slide }) => ({
			...slide,
			video: { extn: 'mp4', durationMs: slide.durationMs },
		})),
	}
}

function addResolvedNarrationAudioObject({ entry, pptx, slide, slideIndex, resolved, args = {}, objectName }) {
	args = normalizeNarrationTimingArgs(args)
	const audioObjectName = objectName || `avatar-native-audio-s${Number(slideIndex) + 1}`
	slide.addMedia({
		type: 'audio',
		path: resolved.audio.filePath,
		extn: resolved.audio.extn || 'wav',
		cover: TRANSPARENT_PIXEL_PNG,
		transparency: 100,
		x: 12.55,
		y: 7.0,
		w: 0.22,
		h: 0.18,
		objectName: audioObjectName,
		// Audio is commonly added after a visual avatar/video object. Pin a
		// genuinely free SPID here instead of relying on the writer's positional
		// fallback, which can reuse the avatar's explicit ID and collapse the two
		// media clocks into one video node.
		spid: _nextFreeSlideSpid(slide),
		isNarration: true,
		showWhenStopped: false,
		endOnStopAudio: true,
		interactivePlayback: false,
		closedCaptionTracks: closedCaptionTracksForArgs(args),
	})
	const mediaObj = slide._slideObjects[slide._slideObjects.length - 1]
	const startDelayMs = narrationMs(args.startDelayMs)
	const paddingMs = args.paddingMs === undefined ? 700 : narrationMs(args.paddingMs)
	const expectedDurationMs = narrationMs(args.expectedDurationMs)
	const timingToleranceMs = narrationTimingToleranceMs(args.timingToleranceMs, expectedDurationMs)
	const durationDriftMs = expectedDurationMs ? Math.abs(narrationMs(resolved.audio.durationMs) - expectedDurationMs) : 0
	const audioEndMs = startDelayMs + narrationMs(resolved.audio.durationMs)
	const timelineEndMs = audioEndMs
	const advanceAfterTime = clampAdvanceMs(timelineEndMs + Math.max(0, paddingMs), 1000)
	slide.addAnimation(mediaObj, normalizeAnimation({
		type: 'media',
		effect: 'mediaplay',
		mediaCommand: 'playFrom(0.0)',
		trigger: 'afterPrevious',
		delay: startDelayMs,
		duration: 1,
	}))
	entry.narrationManifest = entry.narrationManifest || { schemaVersion: 1, slides: [] }
	entry.narrationManifest.slides = entry.narrationManifest.slides.filter(s => s.slideIndex !== slideIndex)
	entry.narrationManifest.slides.push({
		slideIndex,
		audioObjectName,
		audioPath: resolved.audio.filePath,
		durationMs: resolved.audio.durationMs,
		expectedDurationMs: expectedDurationMs || undefined,
		timingToleranceMs,
		durationDriftMs,
		advanceAfterTime,
		startDelayMs,
		paddingMs,
		audioEndMs,
		cueTimelineEndMs: startDelayMs,
		captionTimelineEndMs: startDelayMs,
		timelineEndMs,
		scriptHash: args.script ? hashText(String(args.script).replace(/\s+/g, ' ').trim()) : resolved.textHash,
		voiceId: resolved.voice?.id || null,
		provider: resolved.provider || (args.audio ? 'external-audio' : args.provider || process.env.BETTERPPTX_TTS_PROVIDER || 'piper-http'),
		license: resolved.license || null,
		cues: 0,
		captions: 0,
	})
	return audioObjectName
}

async function prepareAvatarVideoForPlacement(avatarVideo = {}, args = {}) {
	let prepared = { ...avatarVideo }
	try {
		const mediaInfo = await probeMedia({ filePath: avatarVideo.normalizedVideoPath })
		const video = (mediaInfo.streams || []).find(stream => stream?.codec_type === 'video')
		const audio = (mediaInfo.streams || []).find(stream => stream?.codec_type === 'audio')
		prepared = {
			...prepared,
			...(video?.width > 0 && video?.height > 0 ? { videoWidth: Number(video.width), videoHeight: Number(video.height) } : {}),
			hasAudioStream: Boolean(audio),
		}
	} catch {}
	if (Number.isFinite(Number(prepared.videoWidth)) && Number.isFinite(Number(prepared.videoHeight)) && Number(prepared.videoWidth) > 0 && Number(prepared.videoHeight) > 0) return prepared
	// ffprobe is intentionally optional in some maintainer/test environments.
	// The poster is extracted from the same normalized video, so its pixel
	// geometry is a safe aspect-ratio fallback and still prevents stretching.
	const cover = prepared.coverDataUri || args.options?.cover || args.cover
	if (typeof cover === 'string' && cover.includes('base64,')) {
		try {
			const encoded = cover.slice(cover.indexOf('base64,') + 7)
			const metadata = await sharp(Buffer.from(encoded, 'base64')).metadata()
			if (metadata.width > 0 && metadata.height > 0) return { ...prepared, videoWidth: Number(metadata.width), videoHeight: Number(metadata.height) }
		} catch {}
	}
	return prepared
}

async function insertAvatarVideoOnSlide({ entry, deckId, slideIndex, avatarVideo, args = {}, resolvedAudio = null, script = '' }) {
	avatarVideo = await prepareAvatarVideoForPlacement(avatarVideo, args)
	args = normalizeNarrationTimingArgs(args)
	assertPublicNarrationHasNoOverlayCaptions(args)
	const { pptx } = entry
	const slide = getSlide(deckId, slideIndex)
	const mode = normalizeAvatarMode(args.mode)
	if (mode !== 'videoWithAudio') {
		const err = new Error('An Avatar talking-head video must contain its narration audio in one synchronized video. A muted companion video plus separate audio remains ordinary media and cannot satisfy this contract.')
		err.code = 'NATIVE_RECORD_STUDIO_CAPTURE_REQUIRED'
		throw err
	}
	if (!String(script || '').trim()) {
		const err = new Error('Avatar talking-head capture requires narration text for the final speaker-notes block.')
		err.code = 'RECORD_STUDIO_NARRATION_REQUIRED'
		throw err
	}
	if (avatarVideo.hasAudioStream === false) {
		const err = new Error('The rendered Avatar talking-head video has no audio stream. It requires measured narration audio and the generated talking head in one synchronized capture.')
		err.code = 'RECORD_STUDIO_AUDIO_STREAM_REQUIRED'
		throw err
	}
	if (args.replaceExistingRecordStudio === true) {
		const existingCapture = (slide._slideObjects || []).find(object => object?._type === 'media'
			&& String(object.mtype || '').toLowerCase() === 'video'
			&& object.options?._nativeRecordStudioCapture === true)
		if (!existingCapture) {
			const err = new Error('No authentic Avatar talking-head capture is available to replace on this slide.')
			err.code = 'NATIVE_RECORD_STUDIO_CAPTURE_REQUIRED'
			throw err
		}
		_removeSlideNarration(slide)
		if (entry.avatarManifest?.slides) {
			entry.avatarManifest.slides = entry.avatarManifest.slides.filter(item => Number(item.slideIndex) !== Number(slideIndex))
		}
		delete slide._nativeRecordStudioSession
	}
	_addNarrationNotes(slide, script)
	const box = avatarVideoBox(args)
	const objectName = args.options?.objectName || args.objectName || `avatar-video-s${Number(slideIndex) + 1}`
	const cover = avatarVideo.coverDataUri || args.options?.cover || args.cover
	if (!cover || !String(cover).toLowerCase().includes('data:image/png') || !String(cover).toLowerCase().includes('base64,')) {
		const err = new Error('Avatar video requires a PNG poster data URI cover.')
		err.code = 'MEDIA_UNSUPPORTED_INPUT'
		throw err
	}
	// Imported decks can have sparse/non-sequential top-level shape IDs, while
	// newly authored shapes may not carry an explicit `options.spid` (the XML
	// writer assigns their IDs from position). Use the shared allocator so a
	// companion video never reuses an implicit ID already occupied by a title,
	// footer, or another generated object. Duplicate p:cNvPr IDs make PowerPoint
	// report the package as corrupted/unreadable.
	const nextSpid = _nextFreeSlideSpid(slide)
	const replacementRequested = args.replaceExistingNarrationWithVideo === true && typeof slide._rawTimingXml === 'string' && slide._rawTimingXml.trim()
	slide.addRecordStudioCapture({
		type: 'video',
		path: avatarVideo.normalizedVideoPath,
		extn: 'mp4',
		cover,
		...box,
		// PowerPoint otherwise stretches a media frame to the target rectangle.
		// Use the probed source geometry to emit a native srcRect cover crop.
		...(avatarVideo.videoWidth && avatarVideo.videoHeight ? {
			sizing: { type: 'cover', w: box.w, h: box.h },
			_sizingSourceW: avatarVideo.videoWidth,
			_sizingSourceH: avatarVideo.videoHeight,
		} : {}),
		objectName,
		spid: nextSpid,
		_nativeRecordStudioOrigin: 'ai-generated',
		// Record Studio's recorded-media contract includes an interactive timing
		// sequence (togglePause/endSync), so the avatar must participate in the
		// same pause/resume clock by default.  Keep the explicit opt-out for the
		// audio-first muted companion mode, where the separate native narration
		// object remains the authoritative clock.
		// Record Studio behavior is the default for every avatar mode, including
		// the audio-first muted companion mode: clicking the avatar must toggle
		// playback and the timing tree must remain pause/resume-capable.
		interactivePlayback: args.options?.interactivePlayback ?? true,
		// Authoring Excellence Director contract: a talking head is always the
		// accepted centered-crop ellipse window.  Keep the preset geometry explicit
		// instead of relying on a renderer default, so the video and its required
		// poster preview cannot diverge into a rectangular presenter.
		rounding: true,
		_picPrstGeom: 'ellipse',
		avatarFrameContract: 'ellipse-centered-cover-v1',
		mediaVolume: args.options?.mediaVolume,
		altText: args.altText || args.options?.altText || 'Talking-head avatar synchronized to the slide narration.',
	})
	const mediaObj = slide._slideObjects[slide._slideObjects.length - 1]
	mediaObj.options = mediaObj.options || {}
	mediaObj.options.altText = args.altText || args.options?.altText || 'Talking-head avatar synchronized to the slide narration.'
	slide._nativeRecordStudioSession = {
		origin: 'ai-generated',
		videoObjectName: objectName,
		spid: Number(mediaObj.options.spid),
		notesRubric: BETTERPPTX_NARRATION_RUBRIC,
		notesOwnership: 'user-before-marker/betterpptx-after-marker',
		scriptHash: avatarScriptHash(script, avatarVideo.scriptHash || null),
	}
	const replaceNativeNarration = replacementRequested
	let replacedNativeNarration = false
	if (replaceNativeNarration) {
		const rawHasNarration = /<p:audio\b[^>]*\bisNarration="1"/.test(slide._rawTimingXml)
		const existingNarrationAudio = (slide._slideObjects || []).find(obj => obj?._type === 'media' && String(obj.mtype || '').toLowerCase() === 'audio' && (obj.options?.isNarration === true || /narration[-.]audio/i.test(String(obj.options?.objectName || ''))))
		const existingAudio = existingNarrationAudio || (rawHasNarration ? (slide._slideObjects || []).find(obj => obj?._type === 'media' && String(obj.mtype || '').toLowerCase() === 'audio') : null)
		const narrationSpid = Number(existingAudio?.options?.spid)
		const videoSpid = Number(mediaObj.options?.spid)
		if (existingAudio && Number.isFinite(narrationSpid) && Number.isFinite(videoSpid)) {
			const replacedTiming = _replaceRawNarrationWithVideo(slide._rawTimingXml, narrationSpid, videoSpid)
			if (replacedTiming !== slide._rawTimingXml) {
				slide._rawTimingXml = replacedTiming
				const removedRids = new Set(_mediaRelationshipIds(existingAudio))
				slide._slideObjects = (slide._slideObjects || []).filter(obj => obj !== existingAudio)
				if (Array.isArray(slide._relsMedia) && removedRids.size) {
					slide._relsMedia = slide._relsMedia.filter(rel => !removedRids.has(Number(rel?.rId)))
				}
				replacedNativeNarration = true
			}
		}
	}
	for (const existing of slide._slideObjects || []) {
		if (existing?._type === 'media' && String(existing.mtype || '').toLowerCase() === 'audio' && existing.options?.isNarration === true) {
			existing.options = existing.options || {}
			existing.options.altText = existing.options.altText || 'Narration audio for this slide.'
		}
	}
	const startDelayMs = narrationMs(args.startDelayMs ?? args.options?.startDelayMs)
	if (!replacedNativeNarration) {
		slide.addAnimation(mediaObj, normalizeAnimation({
			type: 'media',
			effect: 'mediaplay',
			mediaCommand: 'playFrom(0.0)',
			trigger: args.playTrigger || args.options?.playTrigger || 'afterPrevious',
			delay: startDelayMs,
			duration: 1,
		}))
	}
	let nativeAudioObjectName = null
	let reusedNarrationEntry = null
	if (mode === 'mutedVideoPlusNativeAudio') {
		// An uploaded/foreign deck may already contain the authoritative native
		// narration audio and timing tree. In that case the avatar is a visual
		// companion only: mute the video and reuse the existing audio rather than
		// adding a second copy (which would double-play narration).
		const reuseExistingNarration = args.reuseExistingNarration === true
		const existingNarrationEntry = reuseExistingNarration
			? entry.narrationManifest?.slides?.find(item => Number(item.slideIndex) === Number(slideIndex))
			: null
		const existingNarrationObject = reuseExistingNarration
			? (slide._slideObjects || []).find(obj => obj?._type === 'media'
				&& String(obj.mtype || '').toLowerCase() === 'audio'
				&& (obj.options?.isNarration === true || /narration[-.]audio/i.test(String(obj.options?.objectName || ''))))
			: null
		const canReuseExistingNarration = Boolean(existingNarrationEntry || existingNarrationObject)
		if (!resolvedAudio && !canReuseExistingNarration) {
			const err = new Error('mutedVideoPlusNativeAudio requires resolved narration audio.')
			err.code = 'MEDIA_UNSUPPORTED_INPUT'
			throw err
		}
		if (resolvedAudio && !canReuseExistingNarration) {
			nativeAudioObjectName = addResolvedNarrationAudioObject({ entry, pptx, slide, slideIndex, resolved: resolvedAudio, args, objectName: `avatar-native-audio-s${Number(slideIndex) + 1}` })
		}
		reusedNarrationEntry = canReuseExistingNarration ? existingNarrationEntry : null
	}
	// Completed-job attachment has no inline TTS `resolved` object. When the caller
	// explicitly reuses the slide's native narration, that existing manifest is the
	// authoritative clock; the avatar MP4 duration must never collapse the slide to
	// the 1-second safety floor.
	const narrationDurationMs = narrationMs(resolvedAudio?.audio?.durationMs || reusedNarrationEntry?.durationMs || avatarVideo.durationMs)
	const cueTiming = applyNarrationCues(slide, balanceSyncedBuildBeats(resolveCueAnchors(args.cues || [], script, narrationDurationMs), { minIntervalMs: narrationMs(args.syncBuildMinIntervalMs) || 650, audioDurationMs: narrationDurationMs }), { baseDelayMs: startDelayMs })
	const captionTiming = applyNarrationCaptions(slide, makeAvatarAwareCaptionConfig({
		captions: args.captions,
		avatarBox: box,
		slideHeight: previewSlideLayout(pptx).heightInches,
		footerHeight: 0.62,
	}), args.cues || [], script, { baseDelayMs: startDelayMs, audioDurationMs: avatarVideo.durationMs })
	const requestedCues = Array.isArray(args.cues) ? args.cues.length : 0
	const expectedDurationMs = narrationMs(args.expectedDurationMs)
	const timingToleranceMs = narrationTimingToleranceMs(args.timingToleranceMs, expectedDurationMs)
	const durationDriftMs = expectedDurationMs ? Math.abs(narrationMs(avatarVideo.durationMs) - expectedDurationMs) : 0
	const timingWarnings = [...(avatarVideo.warnings || [])]
	if (expectedDurationMs && durationDriftMs > timingToleranceMs) {
		timingWarnings.push({
			code: 'AVATAR_NARRATION_DURATION_DRIFT',
			message: `Resolved avatar narration duration ${avatarVideo.durationMs}ms differs from authored expectedDurationMs ${expectedDurationMs}ms by ${durationDriftMs}ms.`,
			expectedDurationMs,
			actualDurationMs: avatarVideo.durationMs,
			toleranceMs: timingToleranceMs,
		})
	}
	if (requestedCues > cueTiming.applied) {
		timingWarnings.push({
			code: 'AVATAR_CUE_TARGET_MISSING',
			message: `${requestedCues - cueTiming.applied} avatar narration cue target(s) were not found; create visual objects before narration and target stable objectName values.`,
			requestedCues,
			appliedCues: cueTiming.applied,
		})
	}
	const paddingMs = args.paddingMs === undefined ? 700 : narrationMs(args.paddingMs)
	const mediaEndMs = startDelayMs + narrationMs(avatarVideo.durationMs)
	const timelineEndMs = Math.max(mediaEndMs, cueTiming.maxEndMs, captionTiming.maxEndMs)
	const reusedAdvanceAfterTime = narrationMs(reusedNarrationEntry?.advanceAfterTime)
	const advanceAfterTime = reusedAdvanceAfterTime > 0
		? reusedAdvanceAfterTime
		: clampAdvanceMs(timelineEndMs + Math.max(0, paddingMs), 1000)
	assertLikelyMilliseconds(advanceAfterTime, 'avatar narration advanceAfterTime')
	pptx.showSettings = {
		...(pptx.showSettings || {}),
		useTimings: true,
		showAnimation: true,
		showNarration: true,
		// Native PowerPoint media controls are part of the default talking-head
		// authoring contract; callers may explicitly hide them when required.
		showMediaControls: args.showMediaControls ?? true,
	}
	slide.transition = {
		...(slide.transition || { type: 'fade', speed: 'medium' }),
		advanceOnClick: false,
		advanceAfterTime,
	}
	// Uploaded decks may retain a raw transition XML block. Ensure the native
	// narration/autoplay contract is reflected there as well, otherwise the
	// source's omitted advClick attribute can leave the validator (and some
	// PowerPoint builds) treating the slide as click-advancable.
	if (typeof slide._rawTransitionXml === 'string' && slide._rawTransitionXml.trim()) {
		try {
			const transitionDoc = new DOMParser().parseFromString(slide._rawTransitionXml, 'text/xml')
			const transitionNodes = []
			const visit = node => {
				if (!node) return
				if (node.nodeType === 1 && String(node.nodeName || '').split(':').pop() === 'transition') transitionNodes.push(node)
				for (let i = 0; node.childNodes && i < node.childNodes.length; i++) visit(node.childNodes[i])
			}
			visit(transitionDoc?.documentElement)
			for (const transitionNode of transitionNodes) transitionNode.setAttribute('advClick', '0')
			if (transitionNodes.length) slide._rawTransitionXml = new XMLSerializer().serializeToString(transitionDoc)
		} catch {}
	}
	const slideEntry = {
		slideIndex,
		videoObjectName: objectName,
		videoPath: avatarVideo.normalizedVideoPath,
		posterPath: avatarVideo.posterPath || null,
		durationMs: avatarVideo.durationMs,
		expectedDurationMs: expectedDurationMs || undefined,
		timingToleranceMs,
		durationDriftMs,
		advanceAfterTime,
		startDelayMs,
		paddingMs,
		mediaEndMs,
		cueTimelineEndMs: cueTiming.maxEndMs,
		captionTimelineEndMs: captionTiming.maxEndMs,
		timelineEndMs,
		mode,
		nativeAudioObjectName,
		scriptHash: avatarScriptHash(script, avatarVideo.scriptHash || null),
		provider: avatarVideo.provider || null,
		cacheKey: avatarVideo.cacheKey || null,
		cacheHit: !!avatarVideo.cacheHit,
		requestedCues,
		cues: cueTiming.applied,
		captions: captionTiming.applied,
		cueTimings: cueTiming.timings,
		captionTimings: captionTiming.timings,
	}
	recordAvatarManifestSlide(entry, slideEntry)
	logEvent('avatar.embed.video', {
		deckId,
		slideIndex,
		objectName,
		durationMs: avatarVideo.durationMs,
		advanceAfterTime,
		mode,
		cacheHit: !!avatarVideo.cacheHit,
		cuesApplied: cueTiming.applied,
		captionsApplied: captionTiming.applied,
		timelineEndMs,
		warnings: timingWarnings,
	})
	return {
		ok: true,
		slideIndex,
		objectName,
		video: isPublicBlackBoxMode()
			? { durationMs: avatarVideo.durationMs, extn: 'mp4', cacheHit: !!avatarVideo.cacheHit }
			: { path: avatarVideo.normalizedVideoPath, durationMs: avatarVideo.durationMs, extn: 'mp4', cacheHit: !!avatarVideo.cacheHit },
		advanceAfterTime,
		timing: { startDelayMs, mediaEndMs, cueTimelineEndMs: cueTiming.maxEndMs, captionTimelineEndMs: captionTiming.maxEndMs, timelineEndMs, paddingMs },
		cues: cueTiming.applied,
		captions: captionTiming.applied,
		mode,
		warnings: isPublicBlackBoxMode() ? publicAvatarWarnings(timingWarnings) : timingWarnings,
	}
}

async function resolveAvatarNarrationAudioForArgs(args = {}) {
	const script = args.script != null ? String(args.script) : ''
	if (!script && !args.audio) throw new Error('Avatar narration requires script or audio.')
	return {
		script,
		resolved: await resolveNarrationAudio({
			script,
			audio: resolveNarrationAudioReference(args.audio),
			voice: args.voice,
			lang: args.lang,
			gender: args.gender,
			provider: args.provider,
			speaker: args.speaker,
			lengthScale: args.lengthScale,
			noiseScale: args.noiseScale,
			noiseWScale: args.noiseWScale,
			allowUnreviewedVoices: args.allowUnreviewedVoices,
		}),
	}
}

function avatarRenderProviderFromArgs(args = {}) {
	return resolveAvatarProvider(
		args.avatarProvider || args.qualityProvider || args.providerMode || process.env.BETTERPPTX_AVATAR_PROVIDER,
		{ fallback: 'test-static' },
	)
}

function avatarRenderProviderName(args = {}) {
	return String(avatarRenderProviderFromArgs(args) || '').trim().toLowerCase()
}

function assertInlineAvatarRenderAllowed(args = {}) {
	const providerName = avatarRenderProviderName(args)
	if (isPublicBlackBoxMode() && providerName && providerName !== 'test-static') {
		const err = new Error('Model-backed avatar rendering must use an asynchronous render job.')
		err.code = 'AVATAR_JOB_REQUIRED'
		throw err
	}
}

async function renderAvatarFromToolArgs(args = {}, context = {}) {
	assertAvatarGenerationInput(args.avatar)
	const { script, resolved } = await resolveAvatarNarrationAudioForArgs(args)
	const avatarVideo = await renderAvatarNarrationVideo({
		avatar: resolveGeneratedAssetRefs(args.avatar),
		audioPath: resolved.audio.filePath,
		durationMs: resolved.audio.durationMs,
		scriptHash: resolved.textHash || avatarScriptHash(script),
		provider: avatarRenderProviderFromArgs(args),
		quality: args.avatarQuality || args.quality || 'default',
		mode: normalizeAvatarMode(args.mode),
		options: {
			...(args.avatarOptions || args.options || {}),
			// Identity hints are used only for tenant-scoped durable artifact storage;
			// they never enter public handles or worker payloads.
			accountId: context.accountId || undefined,
			licenseId: context.licenseId || undefined,
			tenantId: context.installHash || context.tenantId || undefined,
		},
		sessionId: context.installHash || context.resourceIdentityHash || context.sessionId || '',
		deckId: args.deckId || '',
		idempotencyKey: args.idempotencyKey || args.idempotency_key || '',
	})
	return { script, resolved, avatarVideo }
}

async function finalizeAvatarJobBilling({ gate, args, result }) {
	if (result?.cacheHit) {
		await releaseBillingReservation({ gate, reason: 'avatar-cache-hit-no-charge' })
		return
	}
	await finalizeBillingReservation({ gate, name: 'betterpptx.avatar.render_job', args, result })
	if (gate?.active && process.env.BETTERPPTX_USAGE_AUTO_FLUSH !== '0') {
		try {
			await runBillingUsageReconciler({ limit: Number(process.env.BETTERPPTX_USAGE_FLUSH_LIMIT || 20) })
		} catch (err) {
			logEvent('avatar.billing.flush_failed', { code: err?.code || 'BILLING_USAGE_FLUSH_FAILED' })
		}
	}
}

function isNoChargeAvatarCacheHit(name, data) {
	if (name === 'betterpptx.slide.add_avatar_narration') return !!data?.video?.cacheHit
	if (name === 'betterpptx.deck.add_avatar_narration') {
		const slides = Array.isArray(data?.slides) ? data.slides : []
		return slides.length > 0 && slides.every(slide => slide?.video?.cacheHit)
	}
	return false
}

async function handleAvatarRenderJob(args, context = {}) {
	assertAvatarGenerationInput(args.avatar)
	const billingGate = context.__billingGate || null
	const job = await createAvatarJob({
		sessionId: context.sessionId || '',
		executionKey: billingGate?.reservation?.reservationId || billingGate?.operationId || '',
		deckId: args.deckId || '',
		billing: billingGate ? { active: !!billingGate.active, amountCredits: billingGate.amountCredits } : null,
		task: async () => {
			const rendered = await renderAvatarFromToolArgs(args, context)
			const ref = registerGeneratedAsset(rendered.avatarVideo.normalizedVideoPath, 'avatar-video')
			const posterRef = rendered.avatarVideo.posterPath
				? registerGeneratedAsset(rendered.avatarVideo.posterPath, 'avatar-poster')
				: null
			const result = {
				...rendered.avatarVideo,
				ref,
				posterRef,
				publicVideo: publicAvatarVideo({ ...rendered.avatarVideo, ref, posterRef }),
			}
			return result
		},
		onSuccess: async result => {
			await finalizeAvatarJobBilling({ gate: billingGate, args, result })
		},
		onFailure: async err => {
			await releaseBillingReservation({ gate: billingGate, reason: err?.code || 'avatar-job-failed-before-value' })
		},
		onUncertain: async err => {
			if (billingGate?.active && billingGate?.reservation) await billingGate.store?.markReservationUncertain?.({ reservationId: billingGate.reservation.reservationId, reason: err?.code || 'avatar-outcome-unknown' })
		},
	})
	if (context.__durableOperationWorker) {
		// A Cloud Tasks worker must not acknowledge the durable operation while
		// the actual avatar render is still only process-local. Wait for the
		// persisted job state to become terminal; the normal public path stays
		// asynchronous and returns the queued job immediately.
		const completed = await waitForAvatarJob(job.jobId, {
			timeoutMs: Math.max(1000, Number(process.env.BETTERPPTX_AVATAR_DURABLE_WAIT_MS || 900000)),
		})
		return publicAvatarJob(completed)
	}
	return job
}

async function handleAvatarJobStatus(args, context = {}) {
	const job = assertAvatarJobAccess(await getAvatarJobAsync(args.jobId, context), context)
	const base = publicAvatarJob(job, context)
	if (isPublicBlackBoxMode()) return base
	return {
		...base,
		result: job.result,
		error: job.error,
	}
}

async function avatarVideoFromCompletedResult(args = {}, context = {}) {
	if (args.jobId) {
		const job = assertAvatarJobAccess(await getAvatarJobAsync(args.jobId, context), context)
		if (job.status !== 'succeeded' || !job.result) {
			const err = new Error('Avatar job has not completed successfully.')
			err.code = 'AVATAR_JOB_NOT_READY'
			throw err
		}
		const result = job.result?.publicVideo || job.result
		await authorizeAssetReferences(result)
		if (enforceAssetOwnership() && !result?.ref) throw new AssetGrantError('ASSET_NOT_FOUND', 'The asset handle is unavailable.')
		if (result?.ref && (enforceAssetOwnership() || !result.normalizedVideoPath)) {
			const normalizedVideoPath = resolveGeneratedAssetRefs(result.ref)
			const posterPath = result.posterRef ? resolveGeneratedAssetRefs(result.posterRef) : null
			const coverDataUri = posterPath ? await coverDataUriFromPng({ posterPath }) : null
			return { ...result, normalizedVideoPath, posterPath, coverDataUri }
		}
		return job.result
	}
	if (args.avatarAsset) {
		const resolved = resolveGeneratedAssetRefs(args.avatarAsset)
		if (typeof resolved !== 'string') throw new Error('avatarAsset must resolve to a video asset.')
		let cover = args.cover || args.options?.cover
		if (typeof cover === 'string' && (/^asset:\/\/(?:locked|generated)\//i.test(cover))) {
			// Completed avatar jobs return opaque video/poster handles. Resolve the
			// poster inside the engine and convert it to the required PNG data URI;
			// clients never need to know filesystem paths or hand-wire a poster.
			cover = await coverDataUriFromPng({ posterPath: resolveGeneratedAssetRefs(cover) })
		}
		if (typeof cover === 'string' && !cover.includes('base64,') && fsNode.existsSync(cover)) {
			// Local maintainer canary mode may keep the generated asset as a path;
			// normalize it at the same engine boundary. Public clients never pass
			// paths because the black-box guard rejects them before this handler.
			cover = await coverDataUriFromPng({ posterPath: cover })
		}
		return {
			normalizedVideoPath: resolved,
			coverDataUri: cover,
			durationMs: Math.round(Number(args.durationMs || 0) || 0),
			cacheHit: false,
			warnings: [],
		}
	}
	throw new Error('avatar.attach_result requires jobId or avatarAsset.')
}

async function handleAvatarAttachResult(args, context = {}) {
	const entry = getDeck(args.deckId)
	const avatarVideo = await avatarVideoFromCompletedResult(args, context)
	let resolvedAudio = null
	if (normalizeAvatarMode(args.mode) === 'mutedVideoPlusNativeAudio' && args.audio) {
		const script = args.script != null ? String(args.script) : ''
		resolvedAudio = await resolveNarrationAudio({
			script,
			audio: resolveNarrationAudioReference(args.audio),
			voice: args.voice,
			lang: args.lang,
			gender: args.gender,
			provider: args.provider,
			speaker: args.speaker,
			lengthScale: args.lengthScale,
			noiseScale: args.noiseScale,
			noiseWScale: args.noiseWScale,
			allowUnreviewedVoices: args.allowUnreviewedVoices,
		})
	}
	return insertAvatarVideoOnSlide({
		entry,
		deckId: args.deckId,
		slideIndex: args.slideIndex,
		avatarVideo,
		args,
		resolvedAudio,
		script: args.script || '',
	})
}

async function handleSlideAddAvatarNarration(args, context = {}) {
	const entry = getDeck(args.deckId)
	if (args.renderMode === 'job') return handleAvatarRenderJob(args, context)
	if (args.renderMode === 'completedAsset' || args.jobId || args.avatarAsset) return handleAvatarAttachResult(args, context)
	assertInlineAvatarRenderAllowed(args)
	const { script, resolved, avatarVideo } = await renderAvatarFromToolArgs(args, context)
	return insertAvatarVideoOnSlide({
		entry,
		deckId: args.deckId,
		slideIndex: args.slideIndex,
		avatarVideo,
		args,
		resolvedAudio: resolved,
		script,
	})
}

async function handleDeckAddAvatarNarration(args, context = {}) {
	const slides = Array.isArray(args.slides) ? args.slides : []
	if (!slides.length) throw new Error('deck.add_avatar_narration requires slides[].')
	const results = []
	for (const item of slides) {
		results.push(await handleSlideAddAvatarNarration({
			...item,
			deckId: args.deckId,
			avatar: item.avatar || args.avatar,
			voice: item.voice ?? args.tts?.voice ?? args.voice,
			lang: item.lang ?? args.tts?.lang ?? args.lang,
			gender: item.gender ?? args.tts?.gender ?? args.gender,
			provider: item.provider ?? args.tts?.provider ?? args.provider,
			avatarProvider: item.avatarProvider ?? args.avatarProvider,
			avatarQuality: item.avatarQuality ?? args.avatarQuality,
			mode: item.mode ?? args.mode,
			paddingMs: item.paddingMs ?? item.timing?.paddingMs ?? item.timeline?.paddingMs ?? item.narrationTiming?.paddingMs ?? args.autoplay?.paddingMs ?? args.paddingMs,
			closedCaptionTracks: item.closedCaptionTracks || item.audio?.closedCaptionTracks || args.closedCaptionTracks,
			allowUnreviewedVoices: item.allowUnreviewedVoices ?? args.allowUnreviewedVoices,
		}, context))
	}
	const estimatedRuntimeMs = results.reduce((sum, r) => sum + (r.advanceAfterTime || 0), 0)
	return { ok: true, slides: results, estimatedRuntimeMs }
}

async function handlePassthroughXml(args) {
	const slide = getSlide(args.deckId, args.slideIndex)
	slide.addPassthroughXml(args.xml)
	return { ok: true, slideIndex: args.slideIndex }
}

function previewEscapeXml(value) {
	return String(value ?? '').replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&apos;' }[ch]))
}

function previewCleanHex(value, fallback = 'FFFFFF') {
	const raw = String(value || '').replace(/^#/, '').trim()
	return /^[0-9A-Fa-f]{6}$/.test(raw) ? raw.toUpperCase() : fallback
}

function previewOpacity(transparency) {
	const n = Number(transparency)
	if (!Number.isFinite(n)) return 1
	return Math.max(0, Math.min(1, 1 - (n / 100)))
}

function previewInches(value, totalInches, fallback = 0) {
	if (typeof value === 'string' && value.trim().endsWith('%')) {
		const n = Number(value.trim().slice(0, -1))
		return Number.isFinite(n) ? totalInches * n / 100 : fallback
	}
	const n = Number(value)
	if (!Number.isFinite(n)) return fallback
	return Math.abs(n) > 1000 ? n / 914400 : n
}

function previewSlideLayout(pptx) {
	const layout = pptx?.presLayout || pptx?._presLayout || {}
	let width = Number(layout.width || layout._sizeW || 0)
	let height = Number(layout.height || layout._sizeH || 0)
	if (!Number.isFinite(width) || width <= 0) width = 12192000
	if (!Number.isFinite(height) || height <= 0) height = 6858000
	if (width > 1000) width = width / 914400
	if (height > 1000) height = height / 914400
	return { widthInches: width || 13.333, heightInches: height || 7.5 }
}

function previewPixelContext(pptx, args = {}) {
	const layout = previewSlideLayout(pptx)
	const width = Math.max(320, Math.min(2560, Math.round(Number(args.width || 1280) || 1280)))
	const scale = width / layout.widthInches
	const height = Math.max(180, Math.round(layout.heightInches * scale))
	return { ...layout, width, height, scale }
}

function previewBox(opts = {}, ctx) {
	const x = previewInches(opts.x, ctx.widthInches, 0) * ctx.scale
	const y = previewInches(opts.y, ctx.heightInches, 0) * ctx.scale
	const w = Math.max(1, previewInches(opts.w, ctx.widthInches, 1) * ctx.scale)
	const h = Math.max(1, previewInches(opts.h, ctx.heightInches, 1) * ctx.scale)
	return { x, y, w, h, cx: x + w / 2, cy: y + h / 2 }
}

function previewGradientFill(fill, ctx, fallback = 'EEF2F7') {
	if (!fill || typeof fill !== 'object' || !Array.isArray(fill.gradientStops) || fill.gradientStops.length === 0) {
		return { fill: `#${previewCleanHex(fill?.color || fill, fallback)}`, opacity: previewOpacity(fill?.transparency) }
	}
	const id = `g${ctx.nextGradient++}`
	const stops = fill.gradientStops.map((stop, i) => {
		const posRaw = stop?.position ?? (fill.gradientStops.length === 1 ? 0 : i / (fill.gradientStops.length - 1))
		const pos = Number(posRaw) <= 1 ? Number(posRaw) * 100 : Number(posRaw)
		const color = stop?.color && typeof stop.color === 'object' ? (stop.color.color || stop.color.scheme || stop.color.preset) : stop?.color
		const opacity = stop?.transparency != null ? previewOpacity(stop.transparency) : (stop?.color && typeof stop.color === 'object' && stop.color.opacity != null ? previewOpacity((1 - Number(stop.color.opacity)) * 100) : '1')
		return `<stop offset="${Math.max(0, Math.min(100, Number.isFinite(pos) ? pos : 0))}%" stop-color="#${previewCleanHex(color, fallback)}" stop-opacity="${opacity}"/>`
	}).join('')
	ctx.defs.push(`<linearGradient id="${id}" x1="0%" y1="0%" x2="100%" y2="100%">${stops}</linearGradient>`)
	return { fill: `url(#${id})`, opacity: previewOpacity(fill?.transparency) }
}

function previewFillAttrs(fill, ctx, fallback = 'EEF2F7') {
	if (fill === null || fill === false || fill?.type === 'none' || fill?.color === 'none') return 'fill="none"'
	const f = previewGradientFill(fill, ctx, fallback)
	return `fill="${f.fill}" fill-opacity="${f.opacity}"`
}

function previewStrokeAttrs(line = {}, fallback = 'CBD5E1') {
	if (line === false || line?.type === 'none' || line?.color === 'none' || line?.transparency >= 100) return 'stroke="none"'
	const width = Math.max(0.5, Number(line?.width || line?.size || 1))
	const dash = line?.dash || line?.dashType
	const dashAttr = dash && dash !== 'solid' ? ' stroke-dasharray="8 6"' : ''
	return `stroke="#${previewCleanHex(line?.color, fallback)}" stroke-opacity="${previewOpacity(line?.transparency)}" stroke-width="${width}"${dashAttr}`
}

function previewTransform(opts = {}, box) {
	const rotate = Number(opts.rotate || 0)
	if (!Number.isFinite(rotate) || rotate === 0) return ''
	return ` transform="rotate(${rotate} ${box.cx} ${box.cy})"`
}

function previewTextRuns(value) {
	if (value == null) return ''
	if (typeof value === 'string' || typeof value === 'number') return String(value)
	if (Array.isArray(value)) return value.map(item => {
		if (typeof item === 'string' || typeof item === 'number') return String(item)
		return String(item?.text ?? '')
	}).join('')
	if (typeof value === 'object') return String(value.text ?? value.value ?? '')
	return String(value)
}

function previewTextWidth(text, fontPx, opts = {}) {
	const fontFace = String(opts.fontFace || '').toLowerCase()
	const mono = /mono|courier|consolas|menlo|monaco|source code|jetbrains/.test(fontFace)
	let units = 0
	for (const ch of String(text || '')) {
		if (/\s/.test(ch)) units += mono ? 0.62 : 0.34
		else if (mono) units += 0.62
		else if (/[MW@#%&]/.test(ch)) units += 0.82
		else if (/[A-Z0-9]/.test(ch)) units += 0.62
		else if (/[ilI.,:;|!']/.test(ch)) units += 0.32
		else units += 0.55
	}
	return units * fontPx * (opts.bold ? 1.04 : 1)
}

function previewSplitLongWord(word, maxWidth, fontPx, opts = {}) {
	const chunks = []
	let current = ''
	for (const ch of String(word || '')) {
		const next = current + ch
		if (current && previewTextWidth(next, fontPx, opts) > maxWidth) {
			chunks.push(current)
			current = ch
		} else {
			current = next
		}
	}
	if (current) chunks.push(current)
	return chunks.length ? chunks : [word]
}

function previewEllipsizeLine(line, maxWidth, fontPx, opts = {}) {
	let out = String(line || '').trimEnd()
	if (previewTextWidth(out, fontPx, opts) <= maxWidth) return out
	while (out.length > 1 && previewTextWidth(`${out}...`, fontPx, opts) > maxWidth) out = out.slice(0, -1).trimEnd()
	return `${out || ''}...`
}

function previewWrapText(text, maxWidth, fontPx, maxLines = 12, opts = {}) {
	const clean = String(text || '').replace(/\s+/g, ' ').trim()
	if (!clean) return []
	const words = clean.split(' ').flatMap(word => (
		previewTextWidth(word, fontPx, opts) > maxWidth
			? previewSplitLongWord(word, maxWidth, fontPx, opts)
			: [word]
	))
	const lines = []
	let current = ''
	let consumed = 0
	for (const word of words) {
		const next = current ? `${current} ${word}` : word
		if (previewTextWidth(next, fontPx, opts) <= maxWidth || !current) current = next
		else {
			lines.push(current)
			current = word
		}
		consumed += 1
		if (lines.length >= maxLines) break
	}
	if (current && lines.length < maxLines) lines.push(current)
	if (lines.length === maxLines && consumed < words.length) {
		lines[lines.length - 1] = previewEllipsizeLine(lines[lines.length - 1].replace(/\.*$/, ''), maxWidth, fontPx, opts)
	}
	return lines
}

// Normalize text into paragraphs so the preview reflects what the spec authored:
// an array of { text, options } keeps per-paragraph size/weight/colour/bullets; a
// plain string is split on newlines. Previously array text was flattened to one
// run at one size, so KPI value+label and bulleted lists rendered run-together.
function previewParagraphs(text, baseOpts = {}) {
	if (Array.isArray(text)) {
		return text.map(p => (p && typeof p === 'object')
			? { text: String(p.text ?? ''), o: { ...baseOpts, ...(p.options || {}) } }
			: { text: String(p ?? ''), o: baseOpts })
	}
	return String(text ?? '').split('\n').map(t => ({ text: t, o: baseOpts }))
}

function wantsPowerPointPreview(args = {}) {
	const renderer = String(args.renderer || process.env.BETTERPPTX_PREVIEW_RENDERER || '').trim().toLowerCase()
	return renderer === 'powerpoint' || renderer === 'ppt' || renderer === 'office'
}

function powerpointPreviewError(message, details = {}, code = 'POWERPOINT_PREVIEW_UNAVAILABLE') {
	const err = new Error(message)
	err.code = code
	err.details = details
	return err
}

function authoritativePreviewInfrastructureStatus() {
	const policy = publicVerificationPolicy()
	const available = previewInfrastructureAvailable()
	return {
		schemaVersion: 'betterpptx.authoritative-preview-capability.v1',
		status: available ? 'available' : 'external-infrastructure-required',
		available,
		renderer: 'powerpoint',
		policy: policy.policy,
		rendererRequiredForSave: policy.rendererRequiredForSave,
		certificationImpact: policy.rendererRequiredForSave
			? (available ? 'first-save-preview-enabled' : 'public-save-blocked')
			: 'not-required-for-production-save',
		requirement: policy.rendererRequiredForSave
			? 'The exact frozen PPTX package must be rendered by an approved authoritative PowerPoint-capable service before public save under the release-powerpoint policy.'
			: 'PowerPoint preview is intentionally outside the production save path. Production uses deterministic non-rendering validation; PowerPoint remains a release-qualification capability.',
		nextAction: policy.rendererRequiredForSave
			? (available
				? 'Validate the current deckVersion, render every slide in batches, and require one stable packageSha256 before save.'
				: 'Configure an approved authoritative PowerPoint render service for the release-powerpoint environment; production-non-rendering save is a separate policy.')
			: 'Use deck.validate_quality and the applicable package/media/timing validators, then save; request deck.preview only when release or explicit visual inspection is required.',
	}
}

function assertPowerPointPreviewAvailable(args = {}) {
	const capability = authoritativePreviewInfrastructureStatus()
	if (isPublicBlackBoxMode() && !capability.available) {
		throw powerpointPreviewError(
			'PowerPoint preview is not configured for this endpoint. Production save uses deterministic non-rendering validation; use the release-powerpoint environment when an actual PowerPoint preview is required.',
			{ status: 'blocked_external_infrastructure', artifactStatus: 'not_saved', releaseInfrastructure: { authoritativePreview: capability } },
			'AUTHORITATIVE_PREVIEW_INFRASTRUCTURE_REQUIRED',
		)
	}
	if (!isLocalMaintainerMode() && !capability.available) {
		throw powerpointPreviewError('Requested preview renderer is unavailable on this endpoint.')
	}
	if (!capability.available) {
		throw powerpointPreviewError('PowerPoint preview export is available only on Windows maintainer desktops.')
	}
}

function powerShellExe() {
	const candidate = process.env.SystemRoot
		? path.join(process.env.SystemRoot, 'System32', 'WindowsPowerShell', 'v1.0', 'powershell.exe')
		: ''
	return candidate && fsNode.existsSync(candidate) ? candidate : 'powershell.exe'
}

export function runPowerPointPreviewExport({ pptxPath, outDir, slideIndexes, width, height, native3dRequirementsPath, includeNativeModelPreviews = false, timeoutMs = 180000 }) {
	const script = `
$ErrorActionPreference = 'Stop'
$ppt = $null
$pres = $null
$existingPresentationCount = 0
try {
  $pptxPath = $env:BETTERPPTX_PREVIEW_PPTX
  $outDir = $env:BETTERPPTX_PREVIEW_OUTDIR
  $width = [int]$env:BETTERPPTX_PREVIEW_WIDTH
  $height = [int]$env:BETTERPPTX_PREVIEW_HEIGHT
  $nativeRequirements = ConvertFrom-Json -InputObject ([System.IO.File]::ReadAllText($env:BETTERPPTX_PREVIEW_NATIVE3D_REQUIREMENTS))
  $nativeCount = 0
  foreach ($nativeSlide in $nativeRequirements.slides) { $nativeCount += @($nativeSlide.targets).Count }
  if ($nativeCount -gt 0) {
${NATIVE3D_PREVIEW_HYDRATION_POWERSHELL}
${NATIVE3D_STATIC_APPEARANCE_POWERSHELL}
  }
  $slidesParsed = ConvertFrom-Json -InputObject $env:BETTERPPTX_PREVIEW_SLIDES
  $slides = New-Object System.Collections.ArrayList
  if ($slidesParsed -is [System.Array]) {
    foreach ($slideValue in $slidesParsed) { [void]$slides.Add([int]$slideValue) }
  } else {
    [void]$slides.Add([int]$slidesParsed)
  }
  New-Item -ItemType Directory -Path $outDir -Force | Out-Null
  $msoTrue = -1
  $msoFalse = 0
  $ppt = New-Object -ComObject PowerPoint.Application
  $existingPresentationCount = $ppt.Presentations.Count
  try { $ppt.DisplayAlerts = 1 } catch {}
  # Public preview is evidence for the release boundary, so PowerPoint must not
  # repair the package on our behalf. Open2007's fifth argument is
  # OpenAndRepair; a successful hidden, read-only open with it explicitly false
  # is the evidence reported below.
  $pres = $ppt.Presentations.Open2007($pptxPath, $msoTrue, $msoFalse, $msoFalse, $msoFalse)
  $items = New-Object System.Collections.ArrayList
  foreach ($idx in $slides) {
    $slideNo = [int]$idx + 1
    if ($slideNo -lt 1 -or $slideNo -gt $pres.Slides.Count) { throw "Slide index out of range: $idx" }
    $file = Join-Path $outDir ("powerpoint_preview_slide_{0}.png" -f $slideNo)
    $nativeRequirement = $nativeRequirements.slides | Where-Object { [int]$_.slideIndex -eq [int]$idx } | Select-Object -First 1
    $native3dHydration = $null
    $native3dStaticAppearance = $null
    if (@($nativeRequirement.targets).Count -gt 0) {
      $hasTrustedPoster = @($nativeRequirement.targets | Where-Object { $null -ne $_.trustedStaticPoster }).Count -gt 0
      if ($hasTrustedPoster) {
        $native3dStaticAppearance = Export-Native3dStaticAppearanceSlide ($pres.Slides.Item($slideNo)) $nativeRequirement $nativeRequirements.slideSizeEmu $nativeRequirements.packageSha256 $file $width $height $outDir
      } else {
        $native3dHydration = Export-Native3dReadySlide ($pres.Slides.Item($slideNo)) $nativeRequirement $nativeRequirements.slideSizeEmu $file $width $height $outDir
      }
    } else {
      $pres.Slides.Item($slideNo).Export($file, 'PNG', $width, $height)
    }
    if (-not (Test-Path $file)) { throw "PowerPoint did not export slide $slideNo" }
    $item = Get-Item $file
    # Do not depend on the optional Microsoft.PowerShell.Utility module.  The
    # public preview worker may run with a deliberately minimal PSModulePath;
    # SHA-256 remains available through the base .NET runtime in Windows
    # PowerShell and PowerShell Core.
    $sha256 = [System.Security.Cryptography.SHA256]::Create()
    try {
      $hashBytes = $sha256.ComputeHash([System.IO.File]::ReadAllBytes($file))
      $renderSha256 = [System.BitConverter]::ToString($hashBytes).Replace('-', '').ToLowerInvariant()
    } finally {
      $sha256.Dispose()
    }
    $nativeModelPreviews = New-Object System.Collections.ArrayList
    if ($env:BETTERPPTX_PREVIEW_INCLUDE_NATIVE_MODELS -eq '1' -and ($null -ne $native3dHydration -or $null -ne $native3dStaticAppearance)) {
      foreach ($target in $nativeRequirement.targets) {
        $probeFile = Join-Path $outDir ("native3d_probe_{0}_{1}.png" -f $slideNo, $target.shapeId)
        if (-not (Test-Path -LiteralPath $probeFile)) { throw 'POWERPOINT_PREVIEW_3D_NOT_READY: The verified native model preview is unavailable.' }
        [void]$nativeModelPreviews.Add([pscustomobject]@{
          shapeId = [int]$target.shapeId
          filePath = $probeFile
          renderSha256 = [BetterPptxNativeRaster]::FileHash($probeFile)
        })
      }
    }
    [void]$items.Add([pscustomobject]@{
      slideIndex = ($slideNo - 1)
      slideNumber = $slideNo
      filePath = $item.FullName
      bytes = $item.Length
      renderSha256 = $renderSha256
      native3dHydration = $native3dHydration
      native3dStaticAppearance = $native3dStaticAppearance
      nativeModelPreviews = $nativeModelPreviews
    })
  }
  [pscustomobject]@{
    ok = $true
    slideCount = $pres.Slides.Count
    width = $width
    height = $height
    powerPointOpen = [pscustomobject]@{
      method = 'Presentations.Open2007'
      readOnly = $true
      withWindow = $false
      openAndRepair = $false
      repaired = $false
      evidence = 'successful-read-only-open-and-render-with-repair-disabled'
    }
    items = $items
  } | ConvertTo-Json -Depth 8 -Compress
} catch {
  $failureCode = if ($_.Exception.Message.StartsWith('POWERPOINT_PREVIEW_3D_NOT_READY:')) { 'POWERPOINT_PREVIEW_3D_NOT_READY' } else { 'POWERPOINT_PREVIEW_UNAVAILABLE' }
  [pscustomobject]@{ ok = $false; error = $_.Exception.Message; code = $failureCode } | ConvertTo-Json -Depth 4 -Compress
  exit 1
} finally {
  if ($pres -ne $null) { try { $pres.Close() } catch {} }
  if ($ppt -ne $null -and $existingPresentationCount -eq 0) { try { $ppt.Quit() } catch {} }
  if ($pres -ne $null) { try { [void][System.Runtime.InteropServices.Marshal]::ReleaseComObject($pres) } catch {} }
  if ($ppt -ne $null) { try { [void][System.Runtime.InteropServices.Marshal]::ReleaseComObject($ppt) } catch {} }
  [GC]::Collect()
  [GC]::WaitForPendingFinalizers()
}
`
	let stdout = ''
	try {
		stdout = execFileSync(powerShellExe(), ['-NoProfile', '-STA', '-ExecutionPolicy', 'Bypass', '-Command', script], {
			encoding: 'utf8',
			timeout: Math.max(30000, Number(timeoutMs) || 180000),
			env: {
				...process.env,
				BETTERPPTX_PREVIEW_PPTX: pptxPath,
				BETTERPPTX_PREVIEW_OUTDIR: outDir,
				BETTERPPTX_PREVIEW_SLIDES: JSON.stringify(slideIndexes),
				BETTERPPTX_PREVIEW_WIDTH: String(width),
				BETTERPPTX_PREVIEW_HEIGHT: String(height),
				BETTERPPTX_PREVIEW_NATIVE3D_REQUIREMENTS: native3dRequirementsPath,
				BETTERPPTX_PREVIEW_INCLUDE_NATIVE_MODELS: includeNativeModelPreviews ? '1' : '0',
			},
		})
	} catch (error) {
		const raw = String(error?.stdout || stdout || '').trim()
		const line = raw.split(/\r?\n/).reverse().find(item => item.trim().startsWith('{'))
		let parsed = null
		try { parsed = line ? JSON.parse(line) : null } catch {}
		throw powerpointPreviewError('PowerPoint preview export failed.', { reason: parsed?.error || error?.message || String(error) }, parsed?.code === 'POWERPOINT_PREVIEW_3D_NOT_READY' ? parsed.code : 'POWERPOINT_PREVIEW_UNAVAILABLE')
	}
	const line = String(stdout || '').trim().split(/\r?\n/).reverse().find(item => item.trim().startsWith('{'))
	let parsed = null
	try { parsed = line ? JSON.parse(line) : null } catch {}
	if (!parsed?.ok) throw powerpointPreviewError('PowerPoint preview export failed.', { reason: parsed?.error || 'No JSON result returned.' }, parsed?.code === 'POWERPOINT_PREVIEW_3D_NOT_READY' ? parsed.code : 'POWERPOINT_PREVIEW_UNAVAILABLE')
	return parsed
}

// White-box tests may replace only the final authoritative export adapter. The
// public MCP surface cannot supply this callback, and production always resets
// to the PowerPoint implementation above.
let _powerPointPreviewExporter = runPowerPointPreviewExport

function setPowerPointPreviewExporterForTest(exporter = null) {
	if (exporter !== null && typeof exporter !== 'function') {
		throw new TypeError('Preview exporter override must be a function or null.')
	}
	_powerPointPreviewExporter = exporter || runPowerPointPreviewExport
}

function verifiedPowerPointOpenEvidence(result = {}) {
	const evidence = result?.powerPointOpen
	const valid = evidence?.method === 'Presentations.Open2007' &&
		evidence?.readOnly === true &&
		evidence?.withWindow === false &&
		evidence?.openAndRepair === false &&
		evidence?.repaired === false
	if (!valid && isPublicBlackBoxMode()) {
		throw powerpointPreviewError(
			'PowerPoint preview did not provide a successful repair-disabled open proof.',
			{
				status: 'repair_proof_required',
				artifactStatus: 'not_saved',
				recommendation: 'Use an authoritative PowerPoint preview worker that opens the package read-only with repair disabled.',
			},
			'POWERPOINT_PREVIEW_REPAIR_PROOF_REQUIRED',
		)
	}
	if (!valid) return null
	return {
		method: 'powerpoint-read-only-open',
		readOnly: true,
		withWindow: false,
		openAndRepair: false,
		repaired: false,
		evidence: 'successful-open-and-render-with-repair-disabled',
	}
}

function releaseGradePowerPointOpenEvidence(evidence = {}) {
	return evidence?.method === 'powerpoint-read-only-open' &&
		evidence?.readOnly === true &&
		evidence?.withWindow === false &&
		evidence?.openAndRepair === false &&
		evidence?.repaired === false
}

async function publishPreviewFileArtifact(entry, deckId, slideIndex, sourcePath, rendered, args = {}) {
	const format = 'png'
	const fileName = args.fileName || `betterpptx_preview_slide_${slideIndex + 1}.${format}`
	const artifact = await _artifactStore.prepareArtifactTarget({
		fileName,
		outputDir: args.outputDir,
		deckId,
		kind: 'preview',
		extension: `.${format}`,
		contentType: 'image/png',
	})
	await fs.copyFile(sourcePath, artifact.target)
	const publishedBytes = await fs.readFile(artifact.target)
	const stat = await fs.stat(artifact.target)
	const renderSha256 = sha256Buffer(publishedBytes)
	if (isPublicBlackBoxMode() && rendered.renderSha256 && String(rendered.renderSha256).toLowerCase() !== renderSha256) {
		try { await fs.rm(artifact.target, { force: true }) } catch {}
		throw powerpointPreviewError(
			'Published preview bytes did not match the PowerPoint render hash.',
			{
				status: 'render_hash_mismatch',
				artifactStatus: 'not_saved',
				slideIndex,
				recommendation: 'Discard this preview batch and rerun it on a healthy authoritative preview worker.',
			},
			'POWERPOINT_PREVIEW_HASH_MISMATCH',
		)
	}
	const finalizedArtifact = _artifactStore.finalizeSaveTarget ? await _artifactStore.finalizeSaveTarget(artifact) : artifact
	if (isPublicBlackBoxMode() && !String(finalizedArtifact.downloadUrl || '').trim()) {
		// A server-local file that the caller cannot retrieve is not a preview.
		// Fail before the slide is credited to the frozen-package coverage set.
		try { await fs.rm(artifact.target, { force: true }) } catch {}
		throw powerpointPreviewError(
			'The rendered slide could not be published as a client-accessible preview artifact.',
			{
				status: 'preview_artifact_unavailable',
				artifactStatus: 'not_saved',
				slideIndex,
				recommendation: 'Configure public preview artifact delivery, then render this frozen-package batch again.',
			},
			'PUBLIC_PREVIEW_ARTIFACT_UNAVAILABLE',
		)
	}
	return {
		slideIndex,
		slideNumber: slideIndex + 1,
		format,
		width: rendered.width,
		height: rendered.height,
		objectCount: rendered.objectCount,
		bytes: stat.size,
		renderSha256,
		...(rendered.powerPointOpen ? { powerPointOpen: rendered.powerPointOpen } : {}),
		...(rendered.native3dHydration ? { native3dHydration: rendered.native3dHydration } : {}),
		...(rendered.native3dStaticAppearance ? { native3dStaticAppearance: rendered.native3dStaticAppearance } : {}),
		artifact: {
			state: finalizedArtifact.downloadUrl ? 'download_ready' : 'saved',
			expiresAt: finalizedArtifact.expiresAt,
		},
		...(finalizedArtifact.downloadUrl ? { downloadUrl: finalizedArtifact.downloadUrl, downloadName: finalizedArtifact.downloadName } : {}),
		...(isPublicBlackBoxMode() ? {} : { filePath: artifact.target }),
	}
}

async function renderPowerPointPreviewArtifacts(entry, deckId, slideIndexes, args = {}, packageBytes = null) {
	assertPowerPointPreviewAvailable(args)
	const { pptx } = entry
	const ctx = previewPixelContext(pptx, args)
	const token = `${String(deckId || 'deck').replace(/[^A-Za-z0-9_-]/g, '_')}-${Date.now().toString(36)}-${crypto.randomBytes(4).toString('hex')}`
	const tmpRoot = path.resolve(process.env.BETTERPPTX_PREVIEW_TMP_DIR || path.join(process.cwd(), 'outputs', 'powerpoint-preview-tmp'))
	const tmpDir = path.join(tmpRoot, token)
	const exportDir = path.join(tmpDir, 'slides')
	const pptxPath = path.join(tmpDir, 'preview-source.pptx')
	await fs.mkdir(exportDir, { recursive: true })
	try {
		if (packageBytes) {
			await fs.writeFile(pptxPath, packageBytes)
		} else {
			ensureBetterPptxMetadata(pptx)
			await pptx.writeFile({ fileName: pptxPath, compression: args.compression !== false })
		}
		const sourceBytes = packageBytes || await fs.readFile(pptxPath)
		const rawNativeRequirements = await readNative3dPreviewRequirements(sourceBytes, slideIndexes)
		const nativeBindings = await readNativeModelPreviewBindings(sourceBytes, rawNativeRequirements)
		const packageSha256 = sha256Buffer(sourceBytes)
		const nativeRequirements = await bindTrustedNative3dPosters(rawNativeRequirements, nativeBindings, native3dPosterReceipts, packageSha256)
		const native3dRequirementsPath = path.join(tmpDir, 'native3d-preview-requirements.json')
		await fs.writeFile(native3dRequirementsPath, JSON.stringify(nativeRequirements))
		const result = _powerPointPreviewExporter({
			pptxPath,
			outDir: exportDir,
			slideIndexes,
			width: ctx.width,
			height: ctx.height,
			native3dRequirementsPath,
			includeNativeModelPreviews: args.includeNativeModelPreviews === true,
			timeoutMs: Number(args.timeoutMs || process.env.BETTERPPTX_POWERPOINT_PREVIEW_TIMEOUT_MS || 180000),
		})
		const powerPointOpen = verifiedPowerPointOpenEvidence(result)
		const byIndex = new Map((result.items || []).map(item => [Number(item.slideIndex), item]))
		const previews = []
		for (const slideIndex of slideIndexes) {
			const item = byIndex.get(Number(slideIndex))
			if (!item?.filePath) throw powerpointPreviewError('PowerPoint preview export did not return every requested slide.', { slideIndex })
			const requirement = nativeRequirements.slides.find(item => item.slideIndex === slideIndex)
			const nativeCount = requirement?.targets.length || 0
			const nativeHydrationVerified = native3dHydrationProofComplete(item.native3dHydration, nativeCount)
			const staticAppearanceVerified = native3dStaticAppearanceProofComplete(item.native3dStaticAppearance, nativeCount, packageSha256, requirement?.targets)
			if (!nativeHydrationVerified && !staticAppearanceVerified) {
				throw powerpointPreviewError('Native 3D content was not verified ready; a compatibility preview cannot approve this slide.', { slideIndex, status: 'native_content_not_ready', artifactStatus: 'not_saved' }, 'POWERPOINT_PREVIEW_3D_NOT_READY')
			}
			const slide = pptx.slides[slideIndex]
			const preview = await publishPreviewFileArtifact(entry, deckId, slideIndex, item.filePath, {
				width: Number(result.width || ctx.width),
				height: Number(result.height || ctx.height),
				objectCount: (slide?._slideObjects || []).filter(obj => String(obj?._type || obj?.type || '').toLowerCase() !== 'notes').length,
				renderSha256: String(item.renderSha256 || '').toLowerCase() || null,
				powerPointOpen,
				...(nativeCount && nativeHydrationVerified ? { native3dHydration: item.native3dHydration } : {}),
				...(staticAppearanceVerified ? { native3dStaticAppearance: item.native3dStaticAppearance } : {}),
			}, {
				...args,
				format: 'png',
				fileName: slideIndexes.length === 1 ? args.fileName : undefined,
			})
			if (args.includeNativeModelPreviews === true) {
				preview.nativeModelPreviews = []
				const probes = Array.isArray(item.nativeModelPreviews) ? item.nativeModelPreviews : []
				for (const target of requirement.targets) {
					const probe = probes.find(item => Number(item.shapeId) === target.shapeId)
					const binding = nativeBindings.get(`${slideIndex}:${target.shapeId}`)
					if (!probe?.filePath || !binding) throw powerpointPreviewError('A verified native model preview is unavailable.', { slideIndex }, 'POWERPOINT_PREVIEW_3D_NOT_READY')
					// Static re-exports must reuse the original trusted PNG. They may
					// not mint a new native-hydration receipt from a matching fallback.
					let previewFile = probe.filePath
					let previewHash = probe.renderSha256
					if (staticAppearanceVerified && target.trustedStaticPoster) {
						previewFile = path.join(exportDir, `trusted_native_poster_${slideIndex}_${target.shapeId}.png`)
						await fs.writeFile(previewFile, Buffer.from(target.posterBase64, 'base64'))
						previewHash = target.trustedStaticPoster.posterSha256
					}
					const metadata = await sharp(previewFile).metadata()
					if (metadata.format !== 'png' || !metadata.hasAlpha) throw powerpointPreviewError('A native model preview did not preserve its transparent frame.', { slideIndex }, 'POWERPOINT_PREVIEW_3D_NOT_READY')
					const modelArtifact = await publishPreviewFileArtifact(entry, deckId, slideIndex, previewFile, {
						width: metadata.width, height: metadata.height, objectCount: 1,
						renderSha256: previewHash, powerPointOpen,
					}, { format: 'png', fileName: `betterpptx_model_preview_${slideIndex + 1}_${target.shapeId}.png` })
					const asset = lockGeneratedAssetDescriptor(previewFile, 'model3d-poster', { mimeType: 'image/png' })
					const descriptor = nativeModelPreviewDescriptor({
						packageSha256, deckVersion: deckVersion(entry), slideIndex, shapeId: target.shapeId, binding,
						frameEmu: target.frameEmu, slideSizeEmu: nativeRequirements.slideSizeEmu, renderWidth: ctx.width, renderHeight: ctx.height,
						imageWidth: metadata.width, imageHeight: metadata.height, asset, artifact: modelArtifact,
						appearanceEvidence: staticAppearanceVerified ? 'trusted-pose-view-frame-bound-poster' : 'non-fallback-native-object-export',
					})
					if (nativeHydrationVerified) await native3dPosterReceipts.record({ posterSha256: asset.digest, binding, packageSha256, powerPointOpen, native3dHydration: item.native3dHydration, expectedCount: nativeCount })
					preview.nativeModelPreviews.push(descriptor)
				}
			}
			previews.push(preview)
		}
		return previews
	} finally {
		if (process.env.BETTERPPTX_KEEP_POWERPOINT_PREVIEW_TMP !== '1') {
			try { await fs.rm(tmpDir, { recursive: true, force: true }) } catch {}
		}
	}
}

function previewRendererInfo() {
	return {
		name: 'betterpptx-powerpoint-preview',
		fidelity: 'powerpoint-export',
		type: 'frozen-pptx-render',
		powerPointExact: true,
		openPolicy: {
			readOnly: true,
			withWindow: false,
			openAndRepair: false,
			repairEvidence: 'successful-open-and-render-with-repair-disabled',
		},
		renderBinding: 'sha256-per-slide-and-canonical-render-set',
		notRepresented: ['PowerPoint animation playback', 'video playback', 'audio playback', 'Morph runtime interpolation timing'],
		notes: [
			'Rendered by exporting the deck through desktop PowerPoint — pixel-faithful to PowerPoint.',
			'Public deck preview batches and deck.save are bound to the same frozen packageSha256.',
			'The prior SVG approximation has been removed; preview is always a true PowerPoint export.',
			'A trusted pose/view/frame-bound compatibility poster may prove static appearance only. Such evidence explicitly leaves live native hydration unverified and never certifies animation playback.',
		],
	}
}

const PUBLIC_PREVIEW_BATCH_LIMIT = 12

function sha256Buffer(value) {
	return crypto.createHash('sha256').update(value).digest('hex')
}

function invalidatePublicPreviewFreeze(entry) {
	if (!entry || typeof entry !== 'object') return
	delete entry.publicPreviewFreeze
}

function currentPublicPreviewFreeze(entry) {
	const freeze = entry?.publicPreviewFreeze
	if (!freeze) return null
	const slideCount = Array.isArray(entry?.pptx?.slides) ? entry.pptx.slides.length : 0
	const validation = currentVersionValidationVerification(entry)
	if (freeze.deckVersion !== deckVersion(entry) ||
		freeze.slideCount !== slideCount ||
		validation.complete !== true ||
		freeze.validationEvidenceSha256 !== validation.validationEvidenceSha256) {
		invalidatePublicPreviewFreeze(entry)
		return null
	}
	return freeze
}

function snapshotPackageProjectionState(entry) {
	const pptx = entry.pptx
	const own = (target, key) => ({ present: Object.prototype.hasOwnProperty.call(target, key), value: target[key] })
	return {
		rawPackageParts: own(pptx, '_rawPackageParts'),
		rawPresentationExtraRels: own(pptx, '_rawPresentationExtraRels'),
		slideRawRels: (pptx.slides || []).map(slide => ({
			present: Object.prototype.hasOwnProperty.call(slide, '_rawRels'),
			value: Array.isArray(slide._rawRels) ? [...slide._rawRels] : slide._rawRels,
		})),
		entryFields: Object.fromEntries([
			'pendingReviewComments',
			'reviewComments',
			'pendingReviewReplies',
			'editionAudit',
		].map(key => [key, {
			present: Object.prototype.hasOwnProperty.call(entry, key),
			value: cloneForResult(entry[key]),
		}])),
	}
}

function restorePackageProjectionState(entry, snapshot) {
	const restore = (target, key, state) => {
		if (state.present) target[key] = state.value
		else delete target[key]
	}
	const pptx = entry.pptx
	restore(pptx, '_rawPackageParts', snapshot.rawPackageParts)
	restore(pptx, '_rawPresentationExtraRels', snapshot.rawPresentationExtraRels)
	for (const [index, state] of snapshot.slideRawRels.entries()) {
		const slide = pptx.slides?.[index]
		if (slide) restore(slide, '_rawRels', state)
	}
	for (const [key, state] of Object.entries(snapshot.entryFields)) restore(entry, key, state)
}

async function buildPublicPreviewPackageBytes(entry, args = {}) {
	const { pptx } = entry
	const snapshot = snapshotPackageProjectionState(entry)
	try {
		ensureBetterPptxMetadata(pptx)
		// These projections are part of the deliverable, so they must be present
		// before PowerPoint renders the package. The snapshot keeps preview itself
		// mutation-free; only the frozen bytes carry the projections.
		_injectEditionSidecar(entry)
		_injectNativeReviewComments(entry)
		_injectReviewReplies(entry)
		_injectEditionAuditComments(entry)
		let packageBytes = Buffer.from(await pptx.write({ outputType: 'nodebuffer', compression: args.compression !== false }))
		try {
			const producedZip = await JSZip.loadAsync(packageBytes)
			const scrubbed = await scrubProducedPackageVocabulary(producedZip)
			const publicAvatarScrubbed = await scrubPublicAvatarDiagnostics(producedZip)
			if (Object.keys(scrubbed).length || Object.keys(publicAvatarScrubbed).length) {
				packageBytes = await producedZip.generateAsync({ type: 'nodebuffer', compression: args.compression !== false ? 'DEFLATE' : 'STORE' })
			}
		} catch (err) {
			try { logEvent('blackbox.vocabulary.scrub.error', { message: String(err?.message || err) }) } catch { /* best-effort */ }
		}
		return Buffer.from(packageBytes)
	} finally {
		restorePackageProjectionState(entry, snapshot)
	}
}

function throwFrozenPackageSafetyError(safety) {
	const err = new Error('Generated Office package failed package safety validation; preview freeze was not created.')
	err.code = 'PPTX_PACKAGE_SAFETY_FAILED'
	err.details = {
		status: 'failed',
		artifactStatus: 'not_saved',
		qualityGate: { success: false, failed: ['packageSafety'] },
		validation: { packageSafety: safety },
	}
	throw err
}

function throwFrozenSelectionVerificationError(selectionVerification) {
	const err = new Error('Generated Office package did not preserve every required AI-authored native selection; preview freeze was not created.')
	err.code = 'PPTX_SELECTION_VERIFICATION_FAILED'
	err.details = {
		status: 'failed',
		artifactStatus: 'not_saved',
		qualityGate: { success: false, failed: ['selectionManifest'] },
		validation: { selectionManifest: selectionVerification },
	}
	throw err
}

async function validatePublicPreviewPackage(entry, packageBytes) {
	const tempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'betterpptx-preview-freeze-'))
	const packagePath = path.join(tempDir, 'approved-preview.pptx')
	try {
		await fs.writeFile(packagePath, packageBytes)
		const packageSafety = await validateSavedPackageSafety(packagePath, {
			publicMode: true,
			metadataLeakOptions: metadataLeakOptionsForEntry(entry),
		})
		if (!packageSafety.ok) throwFrozenPackageSafetyError(packageSafety)
		const selectionVerification = await verifySelectionManifestInPackage(packagePath, entry.aiSelectionManifest, { rootDir: path.resolve(__dirname, '..') })
		if (!selectionVerification.ok) throwFrozenSelectionVerificationError(selectionVerification)
		return { packageSafety, selectionVerification }
	} finally {
		try { await fs.rm(tempDir, { recursive: true, force: true }) } catch {}
	}
}

async function ensurePublicPreviewFreeze(entry, args = {}) {
	const existing = currentPublicPreviewFreeze(entry)
	if (existing) return existing
	const validation = currentVersionValidationVerification(entry)
	if (isPublicBlackBoxMode() && validation.complete !== true) throwCurrentVersionValidationRequired(entry)
	const packageBytes = await buildPublicPreviewPackageBytes(entry, args)
	const verified = await validatePublicPreviewPackage(entry, packageBytes)
	const nativeRequirements = await readNative3dPreviewRequirements(packageBytes, Array.from({ length: entry.pptx.slides.length }, (_, index) => index), { includePosterData: false })
	const freeze = {
		deckVersion: deckVersion(entry),
		slideCount: entry.pptx.slides.length,
		validationDeckVersion: validation.verifiedDeckVersion,
		validationEvidenceSha256: validation.validationEvidenceSha256,
		packageBytes,
		packageSha256: sha256Buffer(packageBytes),
		native3dModelCounts: nativeRequirements.slides.map(slide => slide.targets.length),
		previewedSlideIndexes: new Set(),
		renderEvidenceBySlide: new Map(),
		packageSafety: verified.packageSafety,
		selectionVerification: verified.selectionVerification,
		createdAt: new Date().toISOString(),
	}
	entry.publicPreviewFreeze = freeze
	return freeze
}

function normalizedPreviewBatch(args, slideCount, alreadyPreviewed = new Set()) {
	const all = Array.from({ length: slideCount }, (_value, index) => index)
	const explicit = args.slides !== undefined && args.slides !== null && (!Array.isArray(args.slides) || args.slides.length > 0)
	if (explicit && !Array.isArray(args.slides)) {
		const err = new Error('deck.preview: slides must be an array of zero-based slide indexes.')
		err.code = 'INVALID_PREVIEW_SLIDES'
		err.details = { slideCount, batchLimit: PUBLIC_PREVIEW_BATCH_LIMIT }
		throw err
	}
	const raw = explicit ? args.slides : []
	const invalid = raw.filter(value => typeof value !== 'number' || !Number.isInteger(value) || value < 0 || value >= slideCount)
	if (invalid.length) {
		const err = new Error(`deck.preview: every slide index must be an integer from 0 through ${Math.max(0, slideCount - 1)}.`)
		err.code = 'INVALID_PREVIEW_SLIDES'
		err.details = { invalidSlideIndexes: invalid, slideCount, batchLimit: PUBLIC_PREVIEW_BATCH_LIMIT }
		throw err
	}
	const requested = explicit
		? Array.from(new Set(raw))
		: (() => {
			const remaining = all.filter(index => !alreadyPreviewed.has(index))
			return remaining.length ? remaining : all
		})()
	return {
		requestedSlideIndexes: requested,
		renderSlideIndexes: requested.slice(0, PUBLIC_PREVIEW_BATCH_LIMIT),
	}
}

function publicPreviewVerification(entry, freeze = currentPublicPreviewFreeze(entry)) {
	const slideCount = Array.isArray(entry?.pptx?.slides) ? entry.pptx.slides.length : 0
	const validationVerification = currentVersionValidationVerification(entry)
	const rawPreviewedSlideIndexes = freeze
		? [...freeze.previewedSlideIndexes].filter(index => Number.isInteger(index) && index >= 0 && index < slideCount).sort((a, b) => a - b)
		: []
	const renderEvidenceBySlide = freeze?.renderEvidenceBySlide instanceof Map ? freeze.renderEvidenceBySlide : new Map()
	const previewedSlideIndexes = rawPreviewedSlideIndexes.filter(index => {
		const evidence = renderEvidenceBySlide.get(index)
		const expectedNativeCount = freeze?.native3dModelCounts?.[index]
		return /^[a-f0-9]{64}$/.test(String(evidence?.renderSha256 || '')) && releaseGradePowerPointOpenEvidence(evidence?.powerPointOpen)
			&& Number.isInteger(expectedNativeCount) && expectedNativeCount >= 0
			&& (native3dHydrationProofComplete(evidence?.native3dHydration, expectedNativeCount) || native3dStaticAppearanceProofComplete(evidence?.native3dStaticAppearance, expectedNativeCount, freeze.packageSha256))
	})
	const covered = new Set(previewedSlideIndexes)
	const remainingSlideIndexes = Array.from({ length: slideCount }, (_value, index) => index).filter(index => !covered.has(index))
	const renderEvidence = previewedSlideIndexes.map(slideIndex => ({
		slideIndex,
		renderSha256: renderEvidenceBySlide.get(slideIndex).renderSha256,
		...(renderEvidenceBySlide.get(slideIndex).native3dStaticAppearance ? { native3dStaticAppearance: renderEvidenceBySlide.get(slideIndex).native3dStaticAppearance } : {}),
	}))
	const renderSetSha256 = freeze && renderEvidence.length
		? sha256Buffer(Buffer.from(JSON.stringify({ packageSha256: freeze.packageSha256, renders: renderEvidence.map(({ slideIndex, renderSha256 }) => ({ slideIndex, renderSha256 })) })))
		: null
	const powerPointOpen = previewedSlideIndexes.length
		? {
			method: 'powerpoint-read-only-open',
			readOnly: true,
			withWindow: false,
			openAndRepair: false,
			repaired: false,
			evidence: 'every-credited-render-opened-and-rendered-with-repair-disabled',
			verifiedSlideCount: previewedSlideIndexes.length,
		}
		: null
	return {
		status: freeze ? (remainingSlideIndexes.length ? 'incomplete' : 'verified') : 'required',
		deckVersion: deckVersion(entry),
		validationVerification,
		validationEvidenceSha256: freeze?.validationEvidenceSha256 || validationVerification.validationEvidenceSha256,
		packageSha256: freeze?.packageSha256 || null,
		powerPointOpen,
		renderSetSha256,
		renderEvidence,
		slideCount,
		previewedSlideIndexes,
		remainingSlideIndexes,
		complete: Boolean(freeze && remainingSlideIndexes.length === 0),
		batchLimit: PUBLIC_PREVIEW_BATCH_LIMIT,
	}
}

const PUBLIC_VALIDATION_CORRECTION_TOOL = 'betterpptx.deck.generate_from_spec'

function validationRecoveryTool(recommendedTool, localFallback = 'betterpptx.slide.revise') {
	const localTool = recommendedTool || localFallback
	if (!isPublicBlackBoxMode()) return localTool
	// A finding must never strand a public client on a mutation tool that the
	// spec-first surface intentionally blocks. Keep callable lifecycle/read-only
	// recommendations; send every blocked correction back through semantic JSON.
	return isPublicToolAllowed(localTool) ? localTool : PUBLIC_VALIDATION_CORRECTION_TOOL
}

function normalizeValidationFinding(issue, index = 0) {
	if (issue && typeof issue === 'object') {
		const slide = issue.slide ?? issue.slideIndex ?? (Number.isInteger(issue.slideNumber) ? issue.slideNumber - 1 : null)
		const resolvedIssue = issue.issue || issue.message || String(issue.code || 'Validation issue')
		const isEquivalentAngleNormalization = /^TEXT3D_ROTATION_NORMALIZED$/i.test(String(issue.code || ''))
		return {
			severity: issue.severity || issue.level || 'warning',
			code: issue.code || `VALIDATION_${index + 1}`,
			slide,
			objectHandle: issue.objectHandle || issue.editHandle || issue.objectName || issue.shapeName || null,
			issue: resolvedIssue,
			message: resolvedIssue,
			reason: issue.reason || issue.whyItMatters || resolvedIssue,
			fix: isEquivalentAngleNormalization
				? 'No correction is required. The authored negative angle is preserved in semantic readback and serialized to its equivalent canonical PowerPoint angle.'
				: typeof issue.fix === 'string' && issue.fix.trim()
				? issue.fix
				: 'Apply the recommended semantic correction and rerun the quality gate before saving.',
			evidence: issue.evidence || { source: 'package-validation', slide, objectHandle: issue.objectHandle || issue.editHandle || issue.objectName || issue.shapeName || null, code: issue.code || `VALIDATION_${index + 1}` },
			whyItMatters: isEquivalentAngleNormalization
				? 'This is an informational serialization equivalence record, not a defect or repair request.'
				: issue.whyItMatters || issue.reason || 'Unresolved layout or package issues can make the deck harder to edit, preview, or save reliably.',
			recommendedTool: isEquivalentAngleNormalization ? null : validationRecoveryTool(issue.recommendedTool),
			examplePatch: isEquivalentAngleNormalization ? null : (issue.examplePatch || null),
		}
	}
	const text = String(issue || 'Validation issue')
	const slideMatch = text.match(/slide\s+(\d+)/i)
	const slide = slideMatch ? Math.max(0, Number(slideMatch[1]) - 1) : null
	return {
		severity: /error|invalid|off-slide|overflow|missing/i.test(text) ? 'warning' : 'info',
		code: `VALIDATION_${index + 1}`,
		slide,
		objectHandle: null,
		issue: text,
		message: text,
		reason: text,
		fix: 'Apply the recommended semantic correction and rerun the quality gate before saving.',
		evidence: { source: 'package-validation', slide, code: `VALIDATION_${index + 1}` },
		whyItMatters: 'Validation findings identify content that may render poorly, fall off-slide, or need a targeted edit before save.',
		recommendedTool: validationRecoveryTool(),
		examplePatch: null,
	}
}

function annotateValidationResult(result) {
	if (!result || typeof result !== 'object') return result
	const issues = Array.isArray(result.issues) ? result.issues : []
	result.findings = issues.map(normalizeValidationFinding)
	return result
}

// Preview renders EXCLUSIVELY through desktop PowerPoint (renderer:"powerpoint"). The old
// SVG approximation was removed entirely — this lab only trusts a true PowerPoint export.
async function handleSlidePreview(args) {
	const entry = getDeck(args.deckId)
	const slideIndex = Number(args.slideIndex)
	if (!Number.isInteger(slideIndex)) throw new Error('slide.preview: slideIndex must be a zero-based integer.')
	const previews = await renderPowerPointPreviewArtifacts(entry, args.deckId, [slideIndex], args)
	return { ok: true, authoringRoute: cloneForResult(entry.authoringRoute || null), preview: previews[0], renderer: previewRendererInfo() }
}

async function handleDeckPreview(args) {
	const entry = getDeck(args.deckId)
	const slideCount = entry.pptx.slides.length
	if (!slideCount) throw new Error('deck.preview: the deck has no slides to preview.')
	const publicMode = isPublicBlackBoxMode()
	if (publicMode) assertPowerPointPreviewAvailable(args)
	const freeze = publicMode ? await ensurePublicPreviewFreeze(entry, args) : null
	const alreadyPreviewed = freeze?.previewedSlideIndexes || new Set()
	const batch = normalizedPreviewBatch(args, slideCount, alreadyPreviewed)
	if (!batch.renderSlideIndexes.length) throw new Error(`deck.preview: no valid slide indexes for deck with ${slideCount} slides.`)
	const previews = await renderPowerPointPreviewArtifacts(entry, args.deckId, batch.renderSlideIndexes, args, freeze?.packageBytes || null)
	if (freeze) {
		if (!(freeze.renderEvidenceBySlide instanceof Map)) freeze.renderEvidenceBySlide = new Map()
		for (const preview of previews) {
			const slideIndex = Number(preview.slideIndex)
			freeze.previewedSlideIndexes.add(slideIndex)
			freeze.renderEvidenceBySlide.set(slideIndex, {
				renderSha256: preview.renderSha256,
				powerPointOpen: preview.powerPointOpen,
				...(preview.native3dHydration ? { native3dHydration: preview.native3dHydration } : {}),
				...(preview.native3dStaticAppearance ? { native3dStaticAppearance: preview.native3dStaticAppearance } : {}),
			})
		}
	}
	const verification = publicMode
		? publicPreviewVerification(entry, freeze)
		: (() => {
			const rendered = new Set(batch.renderSlideIndexes)
			const remainingSlideIndexes = Array.from({ length: slideCount }, (_value, index) => index).filter(index => !rendered.has(index))
			return {
				previewedSlideIndexes: [...rendered].sort((a, b) => a - b),
				remainingSlideIndexes,
				complete: remainingSlideIndexes.length === 0,
				batchLimit: PUBLIC_PREVIEW_BATCH_LIMIT,
			}
		})()
	return {
		ok: true,
		authoringRoute: cloneForResult(entry.authoringRoute || null),
		slideCount,
		...(freeze ? {
			packageSha256: freeze.packageSha256,
			validationEvidenceSha256: verification.validationEvidenceSha256,
			validationVerification: verification.validationVerification,
			powerPointOpen: verification.powerPointOpen,
			renderSetSha256: verification.renderSetSha256,
		} : {}),
		requestedSlideIndexes: batch.requestedSlideIndexes,
		renderedSlideIndexes: batch.renderSlideIndexes,
		previewedSlideIndexes: verification.previewedSlideIndexes,
		remainingSlideIndexes: verification.remainingSlideIndexes,
		complete: verification.complete,
		batchLimit: verification.batchLimit,
		previews,
		renderer: previewRendererInfo(),
	}
}

async function handleSummary(args) {
	const entry = getDeck(args.deckId)
	const { pptx, createdAt } = entry
	const slides = pptx.slides.map((s, i) => ({
		index: i,
		slideNum: s._slideNum,
		objects: (s._slideObjects || []).length,
		hasTransition: !!s.transition,
		hasBackground: !!s.background,
		layoutName: s._slideLayout && s._slideLayout._name,
	}))
	return {
		deckId: args.deckId,
		title: pptx.title,
		layout: pptx.layout,
		createdAt,
		slideCount: pptx.slides.length,
		sectionCount: pptx.sections.length,
		slides,
		// E1: per-object ROLE classification (title/body/kpi/image/chart/footer/…) so the AI can
		// understand ANY opened deck before elevating it the world way. Best-effort + confidence.
		...(args.roles === false ? {} : {
			roles: classifyDeckRoles(entry),
			rolesNote: 'PROPOSED classification (deterministic heuristic) — teamwork: confirm or correct any role at elevate time via elevate.roles = { "<slideId>": { "<objectName>": "<role>" } }.',
		}),
		morphPreviewCoverage: collectMorphPreviewCoverage(entry),
		designQuality: collectDesignQuality(entry, { profile: 'modern', minScore: 70 }),
	}
}

function referenceInventory(entry) {
	const slides = (entry?.pptx?.slides || []).map((slide, index) => {
		const editable = _editableSlideObjects(slide)
		const counts = {}
		for (const { obj } of editable) {
			const kind = _shapeKind(obj) || String(obj?._type || obj?.type || 'object')
			counts[kind] = (counts[kind] || 0) + 1
		}
		return {
			slideIndex: index,
			slideNumber: index + 1,
			title: slide._slideLayout?._name || `Slide ${index + 1}`,
			objectCount: editable.length,
			objectKinds: counts,
			hasTransition: Boolean(slide.transition),
			hasBackground: Boolean(slide.background || slide.color),
		}
	})
	return {
		slideCount: slides.length,
		objectCount: slides.reduce((sum, slide) => sum + slide.objectCount, 0),
		slides,
	}
}

function makeReferenceHandle(deckId, inventory) {
	return `ref_${crypto.createHash('sha256').update(`${deckId}|${JSON.stringify(inventory)}|${Date.now()}`).digest('hex').slice(0, 20)}`
}

function resolveReferenceAnalysis(args = {}) {
	if (args.referenceHandle && referenceAnalyses.has(args.referenceHandle)) return referenceAnalyses.get(args.referenceHandle)
	if (args.referenceDeckId || args.deckId) {
		const deckId = args.referenceDeckId || args.deckId
		const entry = getDeck(deckId)
		const inventory = referenceInventory(entry)
		const handle = makeReferenceHandle(deckId, inventory)
		const analysis = {
			referenceHandle: handle,
			sourceDeckId: deckId,
			createdAt: new Date().toISOString(),
			inventory,
		}
		referenceAnalyses.set(handle, analysis)
		return analysis
	}
	const err = new Error('Reference workflow requires referenceHandle, referenceDeckId, or deckId.')
	err.code = 'REFERENCE_NOT_FOUND'
	throw err
}

async function handleAnalyzeReference(args = {}) {
	const entry = getDeck(args.deckId)
	const inventory = referenceInventory(entry)
	const referenceHandle = makeReferenceHandle(args.deckId, inventory)
	const analysis = {
		referenceHandle,
		sourceDeckId: args.deckId,
		createdAt: new Date().toISOString(),
		inventory,
	}
	referenceAnalyses.set(referenceHandle, analysis)
	return {
		ok: true,
		referenceHandle,
		slideCount: inventory.slideCount,
		objectCount: inventory.objectCount,
		slides: inventory.slides,
		findings: [
			{
				severity: 'info',
				code: 'REFERENCE_ANALYZED',
				message: 'Reference analysis is public-safe and summarizes supported editable signals only.',
			},
		],
		next: {
			recommendedTool: 'betterpptx.deck.generate_from_spec',
			reason: 'Use this analysis to author an exact AI-owned composition; generation and editing preserve the submitted frames.',
		},
	}
}

function referenceRecreationPlan(analysis) {
	const slides = analysis.inventory.slides.length ? analysis.inventory.slides : [{ slideIndex: 0, slideNumber: 1, objectCount: 0, objectKinds: {} }]
	return {
		title: 'Reference Recreation Candidate',
		objective: 'Create an editable recreation candidate from a public-safe reference summary.',
		slides: slides.map(slide => ({
			slideId: `reference-slide-${slide.slideNumber}`,
			slideNumber: slide.slideNumber,
			title: `Reference Slide ${slide.slideNumber}`,
			message: `Editable recreation scaffold for ${slide.objectCount} observed object${slide.objectCount === 1 ? '' : 's'}.`,
			items: Object.entries(slide.objectKinds || {}).length
				? Object.entries(slide.objectKinds).map(([kind, count]) => `${count} ${kind} object${count === 1 ? '' : 's'} observed`)
				: ['No editable objects were observed.'],
			notes: 'Use compare_reference and visual preview to decide what needs deeper recreation.',
		})),
	}
}

async function handleRecreateReference(args = {}, context = {}) {
	const err = new Error('Reference recreation is no longer a separate construction path. Compile an exact Authoring Excellence spec through betterpptx.deck.generate_from_spec; the consuming AI owns geometry, styling, layering, and timing.')
	err.code = 'JSON_SPEC_AUTHORING_REQUIRED'
	err.details = {
		blockedTool: 'betterpptx.deck.recreate_reference',
		reason: 'Observed-reference reconstruction and original exact composition both use the governed JSON-spec authoring path.',
		nextAction: { recommendedTool: 'betterpptx.deck.generate_from_spec', reason: 'Use the appropriate AI-owned placement policy and provide exact rect/bbox coordinates or declared source-pixel frames.' },
	}
	throw err
}

async function handleCompareReference(args = {}) {
	const analysis = resolveReferenceAnalysis({ referenceHandle: args.referenceHandle, deckId: args.referenceDeckId })
	const generated = getDeck(args.generatedDeckId)
	const generatedInventory = referenceInventory(generated)
	const mismatches = []
	if (analysis.inventory.slideCount !== generatedInventory.slideCount) {
		mismatches.push({
			severity: 'warning',
			code: 'SLIDE_COUNT_MISMATCH',
			reference: analysis.inventory.slideCount,
			generated: generatedInventory.slideCount,
			recommendedTool: 'betterpptx.deck.generate_from_spec',
		})
	}
	for (let i = 0; i < Math.min(analysis.inventory.slides.length, generatedInventory.slides.length); i += 1) {
		const ref = analysis.inventory.slides[i]
		const gen = generatedInventory.slides[i]
		if (ref.objectCount !== gen.objectCount) {
			mismatches.push({
				severity: 'info',
				code: 'OBJECT_COUNT_DELTA',
				slideIndex: i,
				reference: ref.objectCount,
				generated: gen.objectCount,
				recommendedTool: 'betterpptx.slide.revise',
			})
			}
		}
		return {
		ok: true,
		referenceHandle: analysis.referenceHandle,
		generatedDeckId: args.generatedDeckId,
		comparator: {
			mode: 'public-safe-summary',
			visualOracleRequired: true,
			packageSafetyRequired: true,
		},
		summary: {
			referenceSlides: analysis.inventory.slideCount,
			generatedSlides: generatedInventory.slideCount,
			mismatchCount: mismatches.length,
		},
		mismatches,
		next: mismatches.length
			? { recommendedTool: 'betterpptx.deck.preview', reason: 'Preview mismatched slides and revise supported objects by handle.' }
			: { recommendedTool: 'betterpptx.deck.validate', reason: 'Validate package and design before saving.' },
	}
}

async function handleValidate(args) {
	const entry = getDeck(args.deckId)
	const { pptx } = entry
	const result = pptx.validate({ mode: args.mode || 'normal', autoFix: !!args.autoFix })
	const tableIssues = tableGeometryValidationIssues(entry)
	if (tableIssues.length && result && typeof result === 'object') {
		result.issues = [...(Array.isArray(result.issues) ? result.issues : []), ...tableIssues]
		result.issueCount = Number(result.issueCount || 0) + tableIssues.length
		result.errorCount = Number(result.errorCount || 0) + tableIssues.length
		result.valid = false
	}
	const morphPreviewCoverage = collectMorphPreviewCoverage(entry)
	result.morphPreviewCoverage = morphPreviewCoverage
	result.authoringRoute = cloneForResult(entry.authoringRoute || null)
	return annotateValidationResult(result)
}

function visualReferenceExpectedCarriers(spec = {}) {
	const expected = { text: 0, shape: 0, connector: 0, group: 0, customGeometry: 0, graphicFrame: 0, picture: 0, effects: 0, animations: 0, transitions: 0, backgrounds: 0 }
	const walk = block => {
		if (!block || typeof block !== 'object' || Array.isArray(block)) return
		const kind = String(block.kind || '').trim().toLowerCase()
		if (['text', 'textbox', 'textshape'].includes(kind)) expected.text += 1
		else if (kind === 'connector') expected.connector += 1
		else if (kind === 'group') expected.group += 1
		else if (['freeform', 'customgeometry', 'custom-geometry'].includes(kind)) expected.customGeometry += 1
		else if (['chart', 'chart-panel', 'table', 'table-panel', 'smartart'].includes(kind)) expected.graphicFrame += 1
		else if (['image', 'image-feature'].includes(kind)) expected.picture += 1
		else if (!['model3d', 'media', 'video', 'audio', 'avatarnarration', 'cameo', 'narration'].includes(kind)) expected.shape += 1
		const effectSource = { ...(block.style && typeof block.style === 'object' ? block.style : {}), ...block }
		if (['shadow', 'glow', 'reflection', 'softEdges', 'blur', 'fillOverlay'].some(key => effectSource[key])) expected.effects += 1
		const animations = block.animation ?? block.animations ?? block.style?.animation ?? block.style?.animations
		expected.animations += Array.isArray(animations) ? animations.length : (animations ? 1 : 0)
		if (Array.isArray(block.children)) block.children.forEach(walk)
	}
	for (const slide of spec.slides || []) {
		if (slide?.background) expected.backgrounds += 1
		if (slide?.transition) expected.transitions += 1
		expected.animations += Array.isArray(slide?.timeline) ? slide.timeline.length
			: (Array.isArray(slide?.timeline?.cues) ? slide.timeline.cues.length : 0)
		const narration = slide?.narration || slide?.voiceover
		if (narration && narration.enabled !== false) {
			const narrationCues = narration.cues || narration.timing?.cues || narration.timeline?.cues
			expected.animations += Array.isArray(narrationCues) ? narrationCues.length : 0
		}
		for (const block of slide?.content || []) walk(block)
	}
	return expected
}

function descendantsByLocalName(node, name) {
	return Array.from(node?.getElementsByTagName?.('*') || []).filter(item => String(item.localName || item.nodeName || '').split(':').pop() === name)
}

async function nativeVisualPackageAudit(entry, spec = {}) {
	const packageBytes = Buffer.from(await entry.pptx.write({ outputType: 'nodebuffer', compression: true }))
	const zip = await JSZip.loadAsync(packageBytes)
	const actual = { text: 0, shape: 0, connector: 0, group: 0, customGeometry: 0, graphicFrame: 0, picture: 0, effects: 0, animations: 0, transitions: 0, backgrounds: 0 }
	const objectEvidence = []
	const authoredNamesBySlide = new Map()
	const narrationMediaNamesBySlide = new Map()
	for (let slideIndex = 0; slideIndex < (spec.slides || []).length; slideIndex += 1) {
		const sourceSlide = spec.slides[slideIndex]
		const names = new Set()
		const collect = block => {
			if (!block || typeof block !== 'object' || Array.isArray(block)) return
			const name = String(block.name || block.objectName || '').trim()
			if (name) names.add(name)
			for (const child of block.children || []) collect(child)
		}
		for (const block of sourceSlide?.content || []) collect(block)
		authoredNamesBySlide.set(slideIndex, names)
		const narration = sourceSlide?.narration || sourceSlide?.voiceover
		const mediaNames = new Set()
		if (narration && typeof narration === 'object' && narration.enabled !== false) {
			const baseName = narration.objectName || `${sourceSlide.id}.narration.audio`
			if (Array.isArray(narration.segments) && narration.segments.length) {
				narration.segments.forEach((segment, index) => mediaNames.add(segment?.objectName || `${baseName}-seg${index + 1}`))
			} else mediaNames.add(baseName)
		}
		narrationMediaNamesBySlide.set(slideIndex, mediaNames)
	}
	// ZIP entry order and lexicographic sorting are not slide order once slide10
	// exists. The authored source and OOXML slide parts are both one-based in
	// presentation order, so compare their numeric indexes.
	const slideNames = Object.keys(zip.files)
		.filter(name => /^ppt\/slides\/slide\d+\.xml$/i.test(name))
		.sort((left, right) => Number(left.match(/slide(\d+)\.xml$/i)[1]) - Number(right.match(/slide(\d+)\.xml$/i)[1]))
	let timingTreeCount = 0
	for (let slideOffset = 0; slideOffset < slideNames.length; slideOffset += 1) {
		const name = slideNames[slideOffset]
		const xml = await zip.file(name).async('string')
		const doc = new DOMParser().parseFromString(xml, 'application/xml')
		for (const shape of descendantsByLocalName(doc, 'sp')) {
			actual.shape += 1
			if (descendantsByLocalName(shape, 'txBody').length) actual.text += 1
		}
		actual.connector += descendantsByLocalName(doc, 'cxnSp').length
		actual.group += descendantsByLocalName(doc, 'grpSp').length
		actual.customGeometry += descendantsByLocalName(doc, 'custGeom').length
		actual.graphicFrame += descendantsByLocalName(doc, 'graphicFrame').length
		actual.picture += descendantsByLocalName(doc, 'pic').length
		actual.effects += ['outerShdw', 'innerShdw', 'glow', 'reflection', 'softEdge', 'blur', 'fillOverlay'].reduce((sum, key) => sum + descendantsByLocalName(doc, key).length, 0)
		timingTreeCount += descendantsByLocalName(doc, 'timing').length
		// A timing tree is a container for many effects (and native narration
		// commands). Count authored animation-effect owners in the same unit as
		// source animation declarations, excluding media play/pause/stop calls.
		actual.animations += descendantsByLocalName(doc, 'cTn')
			.filter(node => node.hasAttribute('presetID') && node.getAttribute('presetClass') !== 'mediacall').length
		actual.transitions += descendantsByLocalName(doc, 'transition').length
		actual.backgrounds += descendantsByLocalName(doc, 'bg').length
		for (const carrier of ['sp', 'cxnSp', 'grpSp', 'graphicFrame', 'pic']) {
			for (const node of descendantsByLocalName(doc, carrier)) {
				const identity = descendantsByLocalName(node, 'cNvPr')[0]
				const objectName = String(identity?.getAttribute?.('name') || '').trim()
				if (!objectName) continue
				const effects = ['outerShdw', 'innerShdw', 'glow', 'reflection', 'softEdge', 'blur', 'fillOverlay']
					.filter(effect => descendantsByLocalName(node, effect).length > 0)
				const accessibilityTitleSupport = carrier === 'sp' && objectName === 'slide-title'
				const narrationMediaCarrier = carrier === 'pic' && (narrationMediaNamesBySlide.get(slideOffset) || new Set()).has(objectName)
				const authoredNames = authoredNamesBySlide.get(slideOffset) || new Set()
				const authoredOwner = [...authoredNames].find(name => objectName === name || objectName.includes(`.${name}.`)) || null
				const exactAuthored = Boolean(authoredOwner)
				const componentOwner = exactAuthored ? null : [...authoredNames].find(name => objectName.startsWith(`${name}.`) || objectName.includes(`.${name}.`)) || null
				const origin = accessibilityTitleSupport
					? 'framework-accessibility-support'
					: narrationMediaCarrier ? 'ai-authored-narration-media'
					: exactAuthored ? 'ai-authored' : componentOwner ? 'authored-component-expansion' : 'unexplained'
				objectEvidence.push({
					slideIndex: slideOffset,
					objectName,
					nativeCarrier: carrier,
					effects,
					origin,
					sourceOwner: accessibilityTitleSupport ? 'betterpptx-accessibility' : (narrationMediaCarrier || exactAuthored || componentOwner ? 'consuming-ai' : 'unknown'),
					...(componentOwner ? { componentOwner } : {}),
					purpose: accessibilityTitleSupport ? 'native slide-title placeholder for assistive technology and outline navigation' : narrationMediaCarrier ? 'native audio segment and caption carrier for authored narration' : (componentOwner ? 'native expansion of an authored component' : 'presentation content'),
					visibility: accessibilityTitleSupport || narrationMediaCarrier ? 'non-visible-transparent' : 'visible-or-source-defined',
					pricingRole: accessibilityTitleSupport ? 'excluded-support-object' : narrationMediaCarrier ? 'excluded-narration-media-object' : 'content-carrier',
					currentSourceTreatment: accessibilityTitleSupport ? 'regenerated-from-slide.title; intentionally omitted from slides[].content' : narrationMediaCarrier ? 'regenerated-from-slide.narration.segments' : 'represented-by-semantic-or-preserved-source',
				})
			}
		}
	}
	const mediaHashes = new Set()
	for (const name of Object.keys(zip.files).filter(name => !zip.files[name].dir && /^(?:ppt\/media|ppt\/embeddings)\//i.test(name))) {
		mediaHashes.add(sha256Buffer(await zip.file(name).async('nodebuffer')))
	}
	const chartPointEvidence = []
	for (const name of Object.keys(zip.files).filter(name => /^ppt\/charts\/chart\d+\.xml$/i.test(name)).sort()) {
		const xml = await zip.file(name).async('string')
		const doc = new DOMParser().parseFromString(xml, 'application/xml')
		const points = descendantsByLocalName(doc, 'dPt').map(point => {
			const indexNode = descendantsByLocalName(point, 'idx')[0]
			const colorNode = descendantsByLocalName(point, 'srgbClr')[0]
			return {
				index: Number(indexNode?.getAttribute?.('val')),
				color: String(colorNode?.getAttribute?.('val') || '').toUpperCase(),
			}
		}).filter(point => Number.isInteger(point.index) && /^[0-9A-F]{6}$/.test(point.color))
		chartPointEvidence.push({ chartPart: name.replace(/^ppt\/charts\//i, ''), points })
	}
	const declarations = Array.isArray(spec?.visualReference?.mediaAssets) ? spec.visualReference.mediaAssets : []
	const declarationProof = declarations.map(item => {
		const digest = String(item?.sha256 || String(item?.assetRef || '').match(/[a-f0-9]{64}/i)?.[0] || '').toLowerCase()
		return { name: String(item?.name || ''), digest }
	})
	const missingHashProof = declarationProof.filter(item => !/^[a-f0-9]{64}$/.test(item.digest)).map(item => item.name)
	const absentFromPackage = declarationProof.filter(item => /^[a-f0-9]{64}$/.test(item.digest) && !mediaHashes.has(item.digest)).map(item => item.name)
	const expected = visualReferenceExpectedCarriers(spec)
	const deficits = []
	for (const key of Object.keys(expected)) if (actual[key] < expected[key]) deficits.push({ carrier: key, expected: expected[key], actual: actual[key] })
	const selectedEffectFailures = []
	const effectXmlNames = { shadow: ['outerShdw', 'innerShdw'], glow: ['glow'], reflection: ['reflection'], softEdges: ['softEdge'], blur: ['blur'], fillOverlay: ['fillOverlay'] }
	for (let slideIndex = 0; slideIndex < (spec.slides || []).length; slideIndex += 1) {
		const inspect = (block, pointer) => {
			if (!block || typeof block !== 'object' || Array.isArray(block)) return
			const objectName = String(block.name || block.objectName || '').trim()
			const effectSource = { ...(block.style && typeof block.style === 'object' ? block.style : {}), ...block }
			for (const [control, xmlNames] of Object.entries(effectXmlNames)) {
				if (!effectSource[control]) continue
				const candidates = objectEvidence.filter(item => item.slideIndex === slideIndex &&
					(item.objectName === objectName || item.objectName.startsWith(`${objectName}.`) || item.objectName.includes(`.${objectName}.`)))
				if (candidates.some(item => xmlNames.some(xmlName => item.effects.includes(xmlName)))) continue
				selectedEffectFailures.push({ slideIndex, objectName, control, jsonPointer: `${pointer}/${Object.prototype.hasOwnProperty.call(block, control) ? control : `style/${control}`}`, expectedNativeEffects: xmlNames, serializedCarriers: candidates.map(item => ({ objectName: item.objectName, nativeCarrier: item.nativeCarrier, effects: item.effects })) })
			}
			for (let childIndex = 0; childIndex < (block.children || []).length; childIndex += 1) inspect(block.children[childIndex], `${pointer}/children/${childIndex}`)
		}
		for (let blockIndex = 0; blockIndex < (spec.slides[slideIndex]?.content || []).length; blockIndex += 1) inspect(spec.slides[slideIndex].content[blockIndex], `/slides/${slideIndex}/content/${blockIndex}`)
	}
	const supportObjects = objectEvidence.filter(item => item.pricingRole === 'excluded-support-object')
	const narrationMediaObjects = objectEvidence.filter(item => item.pricingRole === 'excluded-narration-media-object')
	const contentObjects = objectEvidence.filter(item => item.pricingRole === 'content-carrier')
	const unexplainedObjects = objectEvidence.filter(item => item.origin === 'unexplained')
	const missingNarrationMedia = [...narrationMediaNamesBySlide.entries()].flatMap(([slideIndex, names]) => [...names]
		.filter(objectName => !narrationMediaObjects.some(item => item.slideIndex === slideIndex && item.objectName === objectName))
		.map(objectName => ({ slideIndex, objectName })))
	return {
		ok: deficits.length === 0 && selectedEffectFailures.length === 0 && unexplainedObjects.length === 0 && missingNarrationMedia.length === 0 && missingHashProof.length === 0 && absentFromPackage.length === 0,
		packageSha256: sha256Buffer(packageBytes), bytes: packageBytes.length, slideCount: slideNames.length,
		expected, actual, timingTreeCount, carrierDeficits: deficits, selectedEffectFailures, objectEvidence, chartPointEvidence,
		inventoryReconciliation: {
			serializedCarrierCount: objectEvidence.length,
			contentCarrierCount: contentObjects.length,
			supportCarrierCount: supportObjects.length,
			narrationMediaCarrierCount: narrationMediaObjects.length,
			expectedNarrationMediaCarrierCount: [...narrationMediaNamesBySlide.values()].reduce((sum, names) => sum + names.size, 0),
			missingNarrationMedia,
			unexplainedCarrierCount: unexplainedObjects.length,
			unexplainedObjects,
			supportObjects,
			note: 'Transparent accessibility titles and narration audio-segment carriers are separately traced to slide.title and slide.narration; neither is visible authored content or counted as a content object.',
		},
		mediaBinding: { declared: declarations.length, packageMediaAssets: mediaHashes.size, missingHashProof, absentFromPackage },
	}
}

function featureRealizationLedger(spec = {}, packageAudit = null) {
	const packageByName = new Map((packageAudit?.objectEvidence || []).map(item => [item.objectName, item]))
	const controls = []
	const add = ({ slideId, objectName, controlId, jsonPointer, requested, normalized = requested, carrier = null, evidence = null }) => {
		const serializationEvidence = evidence || (carrier
			? { status: 'structurally-validated', slideIndex: carrier.slideIndex, objectName: carrier.objectName }
			: { status: 'not-verified-for-this-artifact' })
		controls.push({
			slideId, objectName, controlId, jsonPointer,
			requested, normalized, effective: normalized,
			transformation: Object.is(requested, normalized) ? 'none' : 'lossless-normalization',
			nativeCarrier: carrier?.nativeCarrier || null,
			serializationEvidence,
			verificationLevel: serializationEvidence.status === 'structurally-validated' ? 'structurally-validated' : 'untested',
		})
	}
	for (let slideIndex = 0; slideIndex < (spec.slides || []).length; slideIndex += 1) {
		const slide = spec.slides[slideIndex] || {}
		for (let objectIndex = 0; objectIndex < (slide.content || []).length; objectIndex += 1) {
			const block = slide.content[objectIndex] || {}
			const objectName = String(block.name || block.objectName || '')
			const carrier = packageByName.get(objectName) || null
			const base = `/slides/${slideIndex}/content/${objectIndex}`
			const text3D = block.text3D || block.options?.text3D || block.style?.text3D
			if (text3D && typeof text3D === 'object') {
				for (const [key, value] of Object.entries(text3D)) {
					const normalized = /^rotation[XY]$/i.test(key) && Number.isFinite(Number(value))
						? ((Number(value) % 360) + 360) % 360 : value
					add({ slideId: slide.id, objectName, controlId: `text3D.${key}`, jsonPointer: `${base}/text3D/${key}`, requested: value, normalized, carrier })
				}
			}
			const fill = block.fill || block.options?.fill || block.style?.fill
			if (Array.isArray(fill?.gradientStops)) {
				add({ slideId: slide.id, objectName, controlId: 'fill.gradientStops', jsonPointer: `${base}/fill/gradientStops`, requested: fill.gradientStops, carrier, evidence: carrier ? { status: 'structurally-validated', authoredStopCount: fill.gradientStops.length, objectName } : null })
			}
			if (String(block.kind || '').toLowerCase() === 'animated-table') {
				const prefix = `${objectName}.`
				const namedChildren = (packageAudit?.objectEvidence || []).filter(item => item.objectName === objectName || item.objectName.startsWith(prefix)).map(item => item.objectName)
				add({ slideId: slide.id, objectName, controlId: 'animated-table.identity', jsonPointer: `${base}/name`, requested: objectName, carrier, evidence: { status: namedChildren.length ? 'structurally-validated' : 'not-verified-for-this-artifact', namedChildren } })
			}
			const chartColors = block.chartOptions?.chartColors
			const series = Array.isArray(block.data) ? block.data : []
			if (Array.isArray(chartColors) && series.length === 1 && Array.isArray(series[0]?.values) && chartColors.length === series[0].values.length) {
				const expectedPoints = chartColors.map((color, index) => ({ index, color: String(color || '').replace(/^#/, '').toUpperCase() }))
				const packagePoints = (packageAudit?.chartPointEvidence || []).find(item => item.points.length === expectedPoints.length)?.points || []
				const realized = expectedPoints.length > 0 && expectedPoints.every(expected => packagePoints.some(actual => actual.index === expected.index && actual.color === expected.color))
				add({
					slideId: slide.id, objectName, controlId: 'chart.dataPointColors',
					jsonPointer: `${base}/chartOptions/chartColors`, requested: expectedPoints, carrier,
					evidence: {
						status: realized ? 'structurally-validated' : 'not-verified-for-this-artifact',
						expectedPoints, packagePoints,
					},
				})
			}
		}
		for (let cueIndex = 0; cueIndex < (slide.timeline?.cues || []).length; cueIndex += 1) {
			const cue = slide.timeline.cues[cueIndex]
			add({ slideId: slide.id, objectName: String(cue?.target || cue?.objectName || ''), controlId: 'timeline.cue', jsonPointer: `/slides/${slideIndex}/timeline/cues/${cueIndex}`, requested: cue, evidence: { status: packageAudit?.actual?.animations > 0 ? 'structurally-validated' : 'not-verified-for-this-artifact', packageAnimationEffects: packageAudit?.actual?.animations || 0, packageTimingTrees: packageAudit?.timingTreeCount || 0 } })
		}
	}
	return {
		schemaVersion: 'betterpptx.feature-realization-ledger.v1',
		selectedControlCount: controls.length,
		controls,
		appearanceVerification: { status: 'not-performed', renderPerformed: false },
		playbackVerification: { status: 'not-performed-for-this-artifact' },
	}
}

async function handleValidateNativeVisuals(args = {}) {
	const entry = getDeck(args.deckId)
	const profile = String(args.profile || 'native-visuals').trim().toLowerCase()
	const requireAiReconstructionRoute = args.requireAiReconstructionRoute === true || profile === 'g6b-ai-reconstruction'
	const spec = entry?.canonicalRecompileSpec || entry?.spec || {}
	const nodes = (spec.slides || []).flatMap(slide => [
		...(slide.htmlFallbacks || []).flatMap(item => item.atmosphereNodes || []),
		...(slide.atmosphereReadback || []).flatMap(item => item.nodes || []),
	])
	const fallbacks = (spec.slides || []).flatMap(slide => slide.htmlFallbacks || [])
	const objects = []
	for (const slide of entry?.pptx?._slides || entry?.pptx?.slides || []) {
		for (const obj of slide._slideObjects || slide.data || []) {
			const opts = obj.options || {}
			objects.push({
				name: opts.objectName || obj.objectName,
				shadow: Boolean(opts.shadow),
				glow: Boolean(opts.glow),
				blur: Boolean(opts.blur),
				reflection: Boolean(opts.reflection),
				softEdges: Boolean(opts.softEdges),
				fillOverlay: Boolean(opts.fillOverlay),
				imageAdjustments: Boolean(opts.imageAdjustments),
				patternFill: opts.fill?.type === 'pattern',
			})
		}
	}
	const wholeSlideRasterized = fallbacks.some(item => item.wholeSlideRasterized === true)
	const semanticRaster = fallbacks.filter(item => /text|shape/i.test(String(item.sourceRepresentation || '')) && item.needsIsolatedRaster).length
	const reopenAvailable = Boolean(entry?.motionEvidence?.timingTreePersistedAfterReopen || entry?.authoritativeReopen)
	const requireReopen = args.requireAuthoritativeReopen === true || profile === 'g6b-ai-reconstruction'
	const issues = []
	let packageAudit = null
	try {
		packageAudit = await nativeVisualPackageAudit(entry, spec)
	} catch {
		packageAudit = { ok: false, error: 'The native package could not be audited.' }
	}
	if (packageAudit?.ok !== true) {
		issues.push({
			code: 'NATIVE_PACKAGE_AUDIT_FAILED',
			message: 'The serialized native package does not reconcile with the authored carriers or could not be audited.',
			carrierDeficits: packageAudit?.carrierDeficits || [],
			selectedEffectFailures: packageAudit?.selectedEffectFailures || [],
			unexplainedCarrierCount: packageAudit?.inventoryReconciliation?.unexplainedCarrierCount ?? null,
			missingNarrationMedia: packageAudit?.inventoryReconciliation?.missingNarrationMedia || [],
			missingMediaHashProof: packageAudit?.mediaBinding?.missingHashProof || [],
			absentDeclaredMedia: packageAudit?.mediaBinding?.absentFromPackage || [],
		})
	}
	const nativeRepresentation = {
		route: cloneForResult(entry.authoringRoute || null),
		policy: isVisualReferenceReconstruction(spec) ? 'native-except-media' : 'native-first',
		nativeObjects: 0,
		mediaObjects: 0,
		declaredMedia: Array.isArray(spec?.visualReference?.mediaAssets) ? spec.visualReference.mediaAssets.length : 0,
		undeclaredMedia: [],
		nonMediaRasterFallbacks: 0,
	}
	const declarations = new Set((spec?.visualReference?.mediaAssets || []).map(item => String(item?.name || '')))
	const seenMedia = new Set()
	const mediaKinds = new Set(['image', 'image-feature', 'model3d', 'media', 'video', 'audio', 'avatarNarration', 'cameo', 'narration'])
	const walk = block => {
			if (!block || typeof block !== 'object' || Array.isArray(block)) return
			const name = String(block.name || block.objectName || '')
			const kind = String(block.kind || '')
			if (mediaKinds.has(kind)) {
				nativeRepresentation.mediaObjects += 1
				seenMedia.add(name)
				if (!declarations.has(name)) nativeRepresentation.undeclaredMedia.push(name || '(unnamed)')
			} else {
				nativeRepresentation.nativeObjects += 1
				if (block.needsIsolatedRaster === true || block.rasterFallback === true || block.fallback?.rendered === true) nativeRepresentation.nonMediaRasterFallbacks += 1
			}
			if (Array.isArray(block.children)) block.children.forEach(walk)
	}
	for (const slide of spec.slides || []) for (const block of slide.content || []) walk(block)
	if (isVisualReferenceReconstruction(spec)) {
		for (const name of declarations) if (!seenMedia.has(name)) issues.push({ code: 'DECLARED_MEDIA_UNUSED', message: `Declared media ${name} is not used by a visual-reference object.` })
		if (nativeRepresentation.undeclaredMedia.length) issues.push({ code: 'MEDIA_DECLARATION_REQUIRED', message: 'Every visual-reference media object must have a matching declared true-media role.', objects: nativeRepresentation.undeclaredMedia })
		if (nativeRepresentation.nonMediaRasterFallbacks) issues.push({ code: 'NON_MEDIA_RASTER_FORBIDDEN', message: 'Ordinary presentation content requested raster fallback in native-except-media mode.' })
		if (entry.authoringRoute?.id !== 'visualReference-ai') issues.push({ code: 'AI_RECONSTRUCTION_ROUTE_MISMATCH', message: 'The deck is not proven to originate from the principal visualReference AI route.' })
	}
	if (wholeSlideRasterized) issues.push({ code: 'WHOLE_SLIDE_RASTER_FORBIDDEN', message: 'A whole-slide screenshot was recorded. Only effect-only textures may cover the canvas.' })
	if (semanticRaster) issues.push({ code: 'SEMANTIC_CONTENT_RASTERIZED', message: 'Semantic text or shape content was rasterized while a native equivalent should exist.' })
	if (requireAiReconstructionRoute && entry.authoringRoute?.g6bAiReconstructionEligible !== true) issues.push({ code: 'G6B_AI_RECONSTRUCTION_ROUTE_REQUIRED', message: 'This certification profile requires the principal visualReference-ai route. The secondary htmlConversion route cannot certify AI reconstruction.' })
	if (profile === 'g6b-ai-reconstruction' && packageAudit?.ok !== true) issues.push({ code: 'G6B_NATIVE_PACKAGE_PROOF_REQUIRED', message: 'The G6B profile requires native package carriers and content-hash-bound media for every declared visual-reference object.', evidence: packageAudit })
	if (requireReopen && !reopenAvailable) issues.push({ code: 'POWERPOINT_REOPEN_REQUIRED', message: 'Authoritative desktop PowerPoint reopen evidence was explicitly requested for this release/application qualification profile.' })
	return {
		ok: issues.length === 0,
		profile,
		authoringRoute: cloneForResult(entry.authoringRoute || null),
		nativeRepresentation,
		packageAudit,
		featureRealizationLedger: featureRealizationLedger(spec, packageAudit),
		atmosphereReadback: atmosphereReadback(nodes),
		objectEffects: {
			count: objects.length,
			withNativeEffects: objects.filter(item => item.shadow || item.glow || item.blur || item.reflection || item.softEdges || item.fillOverlay || item.imageAdjustments || item.patternFill).length,
		},
		wholeSlideRasterized,
		semanticContentRasterized: semanticRaster,
		ownerLinkedFallbacks: fallbacks.filter(item => item.effectOwnerId).length,
		unsupportedSourceNodes: fallbacks.flatMap(item => item.fallbackComponents || []),
		authoritativePowerPointReopen: {
			status: reopenAvailable ? 'observed' : (requireReopen ? 'required-for-requested-qualification' : 'not-requested'),
			timingTreePersistedAfterReopen: Boolean(entry?.motionEvidence?.timingTreePersistedAfterReopen),
			note: requireReopen
				? 'Application reopen evidence is required only for the explicitly requested release/application qualification profile.'
				: 'Renderer-free production validation inspected package, media, selection and timing structure. No visual or playback approval is claimed.',
		},
		issues,
		editabilityLevels: ['ui-editable', 'native-preserved', 'declared-media-asset'],
	}
}

function isGradientFill(fill) {
	return !!(fill && typeof fill === 'object' && (
		fill.type === 'gradient' ||
		fill.gradientDirection ||
		fill.gradientPreset ||
		Array.isArray(fill.gradientStops)
	))
}

// Exact native Shape/WordArt gallery tiles can replace the ordinary fallback
// fill at serialization time. Quality accounting must measure that native
// payload rather than count a suppressed fallback gradient that never appears
// in PowerPoint. This affects measurement only; the selected native tile remains
// the execution authority.
function renderedGradientStateForObject(obj = {}) {
	const opts = obj.options || {}
	const presetId = opts.shapeStylePresetId || opts.wordArtStylePresetId || obj.shapeStylePresetId || obj.wordArtStylePresetId
	const preset = presetId ? nativeStylePresetById(presetId) : null
	const recipe = preset?.recipe || {}
	// The execution handler resolves the preset before adding the object and then
	// removes the public preset id, so inspect both the resolved payload retained
	// on the object and the catalog recipe when the id is still present.
	const nativeFillPayloads = [opts._rawFillXml, opts._rawRprChildXmlExact, recipe._rawFillXml, recipe._rawRprChildXmlExact].filter(value => typeof value === 'string' && value.length > 0)
	if (nativeFillPayloads.length) {
		return {
			gradient: nativeFillPayloads.some(value => value.includes('<a:gradFill')),
			fill: null,
			nativeStyleControlled: true,
		}
	}
	return { gradient: isGradientFill(opts.fill), fill: opts.fill, nativeStyleControlled: false }
}

function collectGradientStops(fill, colors) {
	if (!fill || typeof fill !== 'object') return
	for (const stop of fill.gradientStops || []) {
		if (stop?.color) colors.add(String(stop.color).replace(/^#/, '').toUpperCase())
	}
}

function hasDepth(opts = {}) {
	return !!(opts.shadow || opts.glow || opts.reflection || opts.softEdges || opts.text3D)
}

function hasDisplayText(obj) {
	if (typeof obj?.text === 'string') return obj.text.trim().length > 0
	if (Array.isArray(obj?.text)) return obj.text.some(t => String(t?.text || '').trim().length > 0)
	if (typeof obj?.options?.text === 'string') return obj.options.text.trim().length > 0
	return false
}

function hasAudienceFacingDisplayText(obj) {
	if (!hasDisplayText(obj)) return false
	const opts = obj?.options || {}
	const objectName = String(opts.objectName || obj?.objectName || '')
	// The compiler preserves a fully transparent title placeholder so PowerPoint,
	// assistive technology, and outline/navigation views retain the semantic slide
	// title. It is not audience-facing typography and must not contaminate visible
	// readability measurements or pressure the AI to remove accessibility metadata.
	if (objectName === 'slide-title' && opts.placeholder === 'title' && Number(opts.transparency) >= 99) return false
	return true
}

function hexToRgb(hex) {
	const value = String(hex || '').replace(/^#/, '')
	if (!/^[0-9A-Fa-f]{6}$/.test(value)) return null
	return {
		r: parseInt(value.slice(0, 2), 16),
		g: parseInt(value.slice(2, 4), 16),
		b: parseInt(value.slice(4, 6), 16),
	}
}

function isAccentColor(hex) {
	const rgb = hexToRgb(hex)
	if (!rgb) return false
	const max = Math.max(rgb.r, rgb.g, rgb.b)
	const min = Math.min(rgb.r, rgb.g, rgb.b)
	const luminance = (0.2126 * rgb.r + 0.7152 * rgb.g + 0.0722 * rgb.b) / 255
	return max - min >= 35 && luminance > 0.16 && luminance < 0.92
}

function componentScore(actual, target, points) {
	if (target <= 0) return points
	return Math.round(Math.min(1, actual / target) * points)
}

function designIssue(severity, code, message, suggestion) {
	const recommendedTool = validationRecoveryTool('betterpptx.slide.revise')
	return {
		severity,
		code,
		message,
		suggestion,
		reason: `The engine detected ${code} while evaluating the semantic composition.`,
		fix: suggestion,
		evidence: { code, message, recommendedTool },
		recommendedTool,
		examplePatch: code && /overflow|font|text/i.test(code)
			? { fit: 'shrink' }
			: { emphasis: 'high' },
	}
}

const COMPOSITION_TEXT_PRIMITIVES = new Set(['text', 'textBox', 'textShape', 'title', 'body', 'quote', 'callout'])
const COMPOSITION_VISUAL_PRIMITIVES = new Set(['image', 'media', 'chart', 'table', 'model3d', 'freeform', 'shape'])
function isNarrationMedia(obj = {}, objectName = '') {
	const type = String(obj.type || obj._type || '').toLowerCase()
	const mediaType = String(obj.mediaType || obj.options?.mediaType || '').toLowerCase()
	return obj.options?.isNarration === true || /narration[.-]audio/i.test(objectName) || type === 'audio' || mediaType === 'audio'
}
function compositionRect(obj = {}) {
	const opts = obj.options || {}
	const values = { x: Number(opts.x), y: Number(opts.y), w: Number(opts.w), h: Number(opts.h) }
	if (!Object.values(values).every(Number.isFinite)) return null
	// Imported/native table and media objects can retain PowerPoint EMU values
	// in their diagnostic options while generated semantic objects use inches.
	// Normalize only the obviously-EMU form so visual lint does not report a
	// false off-slide error for an otherwise valid package.
	const maxAbs = Math.max(...Object.values(values).map(value => Math.abs(value)))
	if (maxAbs > 1000) for (const key of Object.keys(values)) values[key] /= 914400
	return values
}
function compositionText(obj = {}) {
	const value = obj.text ?? obj.options?.text ?? ''
	if (typeof value === 'string') return value
	if (Array.isArray(value)) return value.map(item => typeof item === 'string' ? item : item?.text || '').join('\n')
	return ''
}
function compositionIntersects(a, b, tolerance = 0.02) {
	if (!a || !b) return false
	return Math.min(a.x + a.w, b.x + b.w) - Math.max(a.x, b.x) > tolerance &&
		Math.min(a.y + a.h, b.y + b.h) - Math.max(a.y, b.y) > tolerance
}
function compositionIssue(severity, code, message, fix, evidence = {}) {
	const spatialDiagnostic = ['OBJECT_OVERLAP', 'TEXT_VISUAL_OVERLAP', 'CAPTION_VISUAL_OVERLAP', 'CAPTION_FOOTER_OVERLAP'].includes(code)
	return {
		severity,
		code,
		message,
		reason: spatialDiagnostic
			? 'The engine measured a spatial relationship. Spatial intent, layering, occlusion, timing, and correction remain AI-authoring decisions.'
			: `The engine detected ${code} because semantic composition constraints are not satisfied.`,
		fix,
		evidence: { code, ...evidence },
		recommendedTool: validationRecoveryTool('betterpptx.slide.revise'),
	}
}
function compositionOverexpandedTextShape(obj = {}, rect = null) {
	// Keep this diagnostic aligned with the compiler's semantic-layout warning.
	// It is intentionally limited to explicit textShape rectangles: uploaded or
	// legacy decks may preserve source geometry, but validation must still tell an
	// AI when a short card has inherited a large, visibly empty panel.
	const primitive = String(obj.type || obj._type || '').toLowerCase()
	// Compiled IR calls this primitive `textShape`, while the materialized
	// PowerPoint object is a normal text object carrying an explicit `options.shape`.
	// Recognize both forms so post-commit validation sees the same finding as dryRun.
	const materializedTextShape = primitive === 'text' && Object.prototype.hasOwnProperty.call(obj.options || {}, 'shape')
	if (!(primitive === 'textshape' || materializedTextShape) || !rect) return null
	const intentionalQuietSpace = obj.keep === true || obj.decorative === true || obj.options?.keep === true || obj.options?.decorative === true
	if (intentionalQuietSpace) return null
	const text = compositionText(obj).trim()
	const area = rect.w * rect.h
	const density = area > 0 ? text.length / area : 0
	if (!(rect.w >= 2.2 && rect.h >= 3 && text.length <= 180 && density <= 18)) return null
	return {
		textCharacters: text.length,
		rect,
		characterDensityPerSquareIn: Math.round(density * 100) / 100,
		thresholds: { minWidthIn: 2.2, minHeightIn: 3, maxTextCharacters: 180, maxCharacterDensityPerSquareIn: 18 },
	}
}

function compositionFitText(obj = {}) {
	if (typeof obj.text === 'string' || typeof obj.text === 'number') return String(obj.text)
	if (Array.isArray(obj.text)) {
		return obj.text.map(run => {
			const value = typeof run === 'string' || typeof run === 'number' ? String(run) : String(run?.text || '')
			return `${value}${run?.options?.breakLine === true ? '\n' : ''}`
		}).join('')
	}
	if (typeof obj.options?.text === 'string' || typeof obj.options?.text === 'number') return String(obj.options.text)
	return ''
}

function compositionDirectTextFontSizes(obj = {}) {
	const values = []
	const push = value => {
		const size = Number(value)
		if (Number.isFinite(size) && size > 0) values.push(size)
	}
	push(obj.options?.fontSize)
	if (Array.isArray(obj.text)) for (const run of obj.text) push(run?.options?.fontSize)
	return values
}

function compositionNativeTextFitGeometry(rect, options = {}) {
	// Materialized text margins follow the native point contract, while the
	// general layout estimator accepts inch padding. Preserve each side instead
	// of treating the largest [top,right,bottom,left] inset as four inch margins.
	const pointInsets = Array.isArray(options.margin) && options.margin.length === 4
		? options.margin
		: typeof options.margin === 'number' ? Array(4).fill(options.margin) : null
	if (!pointInsets || !pointInsets.every(value => Number.isFinite(value) && value >= 0)) {
		return { rect, margin: options.margin ?? 0.08 }
	}
	const [top, right, bottom, left] = pointInsets.map(value => value / 72)
	return {
		rect: {
			...rect, x: rect.x + left, y: rect.y + top,
			w: Math.max(0.1, rect.w - left - right),
			h: Math.max(0.1, rect.h - top - bottom),
		},
		margin: 0,
	}
}

function compositionTextFitIssue(obj = {}, rect = null, slideIndex = 0, slideObjects = [], honorReferenceTypeSize = false) {
	if (!rect || !hasAudienceFacingDisplayText(obj)) return null
	const opts = obj.options || {}
	// Imported raw text can carry exact body/paragraph metrics that are not fully
	// represented in the public object model. Keep those in rendered review; this
	// objective estimate is authoritative for newly materialized editable text.
	if (opts._nativeMinimal === true || opts._rawBodyPrXml || opts._rawBodyPrChildXml) return null
	if (Number(opts.transparency) >= 99) return null
	if (opts.fit === 'resize' || opts.autoFit === true || opts._bodyProp?.autoFit === true) return null
	const vertical = String(opts.vert || opts._bodyProp?.vert || '').toLowerCase()
	if (vertical && vertical !== 'horz') return null
	const text = compositionFitText(obj)
	if (!text.trim()) return null
	const sizes = compositionDirectTextFontSizes(obj)
	if (!sizes.length) return null
	const role = readabilityRoleForObject(obj, slideIndex, slideObjects)
	// Reference reconstruction retains an explicitly authored type size. The
	// readability warning still reports the semantic floor independently; do not
	// enlarge the words only inside the fit estimator and call that an overflow.
	const semanticFloorPt = readabilityFloorForRole(role)
	const floorPt = honorReferenceTypeSize ? Math.min(semanticFloorPt, ...sizes) : semanticFloorPt
	// Use the smallest declared run size as the conservative lower-bound model for
	// mixed runs. If even that cannot fit at the semantic floor, no legal uniform
	// PowerPoint shrink can rescue the frame without violating readability.
	const requestedFontSize = Math.max(floorPt, Math.min(...sizes))
	const fitGeometry = compositionNativeTextFitGeometry(rect, opts)
	const fit = estimateTextFit({
		text,
		rect: fitGeometry.rect,
		fontSize: requestedFontSize,
		minFontSize: floorPt,
		margin: fitGeometry.margin,
		fontFace: opts.fontFace || 'Aptos',
		charSpacing: opts.charSpacing,
		bullet: opts.bullet === true || (Array.isArray(obj.text) && obj.text.some(run => run?.options?.bullet)),
	})
	if (!fit.overflow) return null
	const objectName = String(opts.objectName || obj.objectName || '')
	const pairedShapeBuiltLabel = Boolean(readabilityShapeBuiltLabelBacking(obj, slideObjects))
	return compositionIssue(
		'error',
		'TEXT_OVERFLOW_RISK',
		`Text cannot fit inside its materialized frame at the ${floorPt}pt ${role} floor.`,
		'Shorten or split the copy, or enlarge the AI-authored text frame; fit:"shrink" cannot reduce text below the role floor.',
		{
			slideIndex,
			objectName,
			role,
			frame: rect,
			textCharacters: text.length,
			requestedFontSize: Math.min(...sizes),
			minimumFontSize: floorPt,
			resolvedFontSize: fit.fontSize,
			lineCount: fit.lines,
			estimatedHeightIn: Math.round(Number(fit.height || 0) * 10000) / 10000,
			availableHeightIn: Math.round(Number(fit.usableHeightIn || 0) * 10000) / 10000,
			fitPolicy: opts.fit || null,
			pairedShapeBuiltLabel,
			measurementSource: 'materialized-text-frame',
			fontSizeAuthority: honorReferenceTypeSize ? 'authored-reference' : 'semantic-floor',
		},
	)
}

function collectCompositionIssues(entry, slideSize = { w: 13.333, h: 7.5 }) {
	const issues = []
	// A faithful HTML source is an authored visual composition, not a newly
	// typeset semantic deck. Its deliberately small labels and microcopy are
	// preserved for visual parity; readability floors remain reported by the
	// design/readability contract, but the generic materialized-frame estimate
	// must not turn every faithful source label into a blocking overflow. Other
	// authoring profiles retain the strict fit gate.
	const faithfulHtml = entry?.readabilityPolicy === 'faithful-html'
		|| readabilityPolicyForSpec(entry?.canonicalSpecState?.spec || {}) === 'faithful-html'
	const exactVisualReference = entry?.authoringRoute?.id === 'visualReference-ai'
		&& isVisualReferenceReconstruction(entry?.canonicalRecompileSpec || {})
	for (const [slideIndex, slide] of (entry?.pptx?.slides || []).entries()) {
		const slideObjects = _editableSlideObjects(slide).map(({ obj }) => obj)
		const items = slideObjects.map(obj => ({ obj, rect: compositionRect(obj) })).filter(item => item.rect)
		const performanceProof = entry.presenterPerformanceValidation?.deckVersion === deckVersion(entry)
			? (entry.presenterPerformanceValidation.slides || []).filter(proof => proof.slideIndex === slideIndex) : []
		const performanceByActor = new Map(performanceProof.filter(proof => {
			const actor = items.find(item => String(item.obj.options?.objectName || item.obj.objectName || '') === proof.actor)
			return actor && Array.isArray(proof.samples) && proof.samples.length && ['x', 'y', 'w', 'h'].every(key => Math.abs(actor.rect[key] - Number(proof.frame?.[key])) < 0.001)
		}).map(proof => [proof.actor, proof]))
		for (const { obj, rect } of items) {
			const name = String(obj.options?.objectName || obj.objectName || '')
			const role = String(obj.role || obj.options?.role || '')
			const text = compositionText(obj)
			if (/\\n/.test(text)) issues.push(compositionIssue('error', 'LITERAL_NEWLINE_TEXT', 'Visible text contains a literal \\n escape; normalize it to a real line break before rendering.', 'Replace the literal escape with a real line break in the semantic text, then rerun validation.', { slideIndex, objectName: name, literal: '\\n' }))
			const intentionalBleed = obj.bleed === true || role === 'background' || role === 'decorative'
			const hiddenEntry = performanceByActor.get(name)?.entry
			const entryStage = hiddenEntry?.stageFrame
			// Only a version-bound compiled entrance may start wholly above the canvas.
			// Require its exact current frame, in-bounds destination, and native path;
			// an arbitrary off-slide object or edited animation still fails this gate.
			const stagedEntrance = ['drop', 'fade', 'appear'].includes(hiddenEntry?.type) && rect.y + rect.h < -0.01
				&& ['x', 'y', 'w', 'h'].every(key => Math.abs(rect[key] - Number(hiddenEntry.initialFrame?.[key])) < 0.001)
				&& entryStage?.x >= 0 && entryStage?.y >= 0
				&& entryStage.x + entryStage.w <= slideSize.w + 0.001
				&& entryStage.y + entryStage.h <= slideSize.h + 0.001
				&& (slide._animations || []).some(record => record.target === obj
					&& record.animation?.type === 'motion' && record.animation.trigger === 'withPrevious'
					&& record.animation.motionPathData === hiddenEntry.motionPathData
					&& record.animation.delay === hiddenEntry.startMs && record.animation.duration === hiddenEntry.durationMs)
			if (!intentionalBleed && !stagedEntrance && (rect.x < -0.01 || rect.y < -0.01 || rect.x + rect.w > slideSize.w + 0.01 || rect.y + rect.h > slideSize.h + 0.01)) {
				issues.push(compositionIssue('error', 'VISUAL_OFF_SLIDE', 'Object extends outside the slide canvas.', 'Remove authored geometry and choose a semantic region/layoutIntent so the engine keeps the visual inside the canvas.', { slideIndex, objectName: name, rect, slideSize }))
			}
			const overexpanded = compositionOverexpandedTextShape(obj, rect)
			if (overexpanded) issues.push({
				severity: 'warning',
				code: 'LAYOUT_TEXTSHAPE_OVEREXPANDED',
				slideIndex,
				objectName: name,
				message: 'Explicit textShape geometry is substantially larger than its short copy and may render as an empty panel.',
				reason: 'The preserved textShape rectangle has low content density; source geometry is retained for fidelity, but new authoring should let semantic layout compact it.',
				fix: 'Remove explicit geometry and choose a semantic region/layoutIntent so the engine can compact and vertically balance the card; use keep:true only for intentional quiet space.',
				evidence: overexpanded,
				suggestions: ['remove explicit geometry', 'choose a semantic region', { keep: true }],
			})
			const textFit = faithfulHtml ? null : compositionTextFitIssue(obj, rect, slideIndex, slideObjects, exactVisualReference)
			if (textFit) issues.push(textFit)
			if (/^narration-caption-/i.test(name)) {
				const footer = { x: 0, y: slideSize.h - 0.62, w: slideSize.w, h: 0.62 }
				if (compositionIntersects(rect, footer)) issues.push(compositionIssue('warning', 'CAPTION_FOOTER_OVERLAP', 'Measured caption/footer spatial overlap.', 'AI authoring must decide whether the caption should occupy this band; the engine reports the measured relation and does not relocate or suppress it.', { slideIndex, objectName: name, rect, reservedBand: footer, measurementSpace: 'slide-inches', spatialConflictPolicy: 'report-only', authoringAuthority: 'ai', engineAction: 'report-only' }))
			}
		}
		for (let i = 0; i < items.length; i += 1) {
			for (let j = i + 1; j < items.length; j += 1) {
				const a = items[i]; const b = items[j]
				const aName = String(a.obj.options?.objectName || a.obj.objectName || '')
				const bName = String(b.obj.options?.objectName || b.obj.objectName || '')
				const performance = performanceByActor.get(aName) || performanceByActor.get(bName)
				let performanceCollision = null
				if (performance) {
					const other = performance.actor === aName ? b : a
					const otherName = performance.actor === aName ? bName : aName
					const animations = (slide._animations || []).filter(record => record.target === other.obj).map(record => record.animation).filter(Boolean)
					performanceCollision = findPresenterPerformanceCollision({ samples: performance.samples, rect: other.rect, animations })
					if (!performanceCollision) continue
					if ((performance.contactTargets || []).some(contact => contact.objectName === otherName)) continue
				} else if (!compositionIntersects(a.rect, b.rect)) continue
				// World depth may add a backing frame behind a generated image/media. The
				// frame and visible raster intentionally share the host rectangle; match
				// generated semantic names even when the runtime object omits blockName.
				const backingVisualPair = (leftName, rightName) => {
					const left = String(leftName).replace(/\.(?:image-frame|media-frame)$/i, '')
					const right = String(rightName).replace(/\.(?:image|media)$/i, '')
					const reverseLeft = String(rightName).replace(/\.(?:image-frame|media-frame)$/i, '')
					const reverseRight = String(leftName).replace(/\.(?:image|media)$/i, '')
					const leftSupport = /\.native-effect-support(?:-\d+)?\.shape$/i.test(String(leftName))
					const rightSupport = /\.native-effect-support(?:-\d+)?\.shape$/i.test(String(rightName))
					return (String(leftName).toLowerCase().endsWith('.image-frame') && String(rightName).toLowerCase().endsWith('.image') && left === right)
						|| (String(leftName).toLowerCase().endsWith('.media-frame') && String(rightName).toLowerCase().endsWith('.media') && left === right)
						|| (String(rightName).toLowerCase().endsWith('.image-frame') && String(leftName).toLowerCase().endsWith('.image') && reverseLeft === reverseRight)
						|| (String(rightName).toLowerCase().endsWith('.media-frame') && String(leftName).toLowerCase().endsWith('.media') && reverseLeft === reverseRight)
						|| (leftSupport && String(rightName).toLowerCase().endsWith('.image'))
						|| (rightSupport && String(leftName).toLowerCase().endsWith('.image'))
						|| (leftSupport && String(rightName).toLowerCase().endsWith('.media'))
						|| (rightSupport && String(leftName).toLowerCase().endsWith('.media'))
				}
				if (backingVisualPair(aName, bName)) continue
				// Native narration audio is a timing carrier, not a visible visual
				// object. It may share the footer's package-level anchor without any
				// presentation overlap; never report it as a text/visual collision.
				if (isNarrationMedia(a.obj, aName) || isNarrationMedia(b.obj, bName)) continue
				const aPrimitive = a.obj.type || a.obj._type
				const bPrimitive = b.obj.type || b.obj._type
				const captionPair = /^narration-caption-/i.test(aName) || /^narration-caption-/i.test(bName)
				if (captionPair && (COMPOSITION_VISUAL_PRIMITIVES.has(aPrimitive) || COMPOSITION_VISUAL_PRIMITIVES.has(bPrimitive))) {
					issues.push(compositionIssue('warning', 'CAPTION_VISUAL_OVERLAP', 'Measured caption/visual spatial overlap.', 'AI authoring must decide whether the caption should layer over this visual; the engine reports the measured relation and does not move, hide, or substitute either object.', { slideIndex, objects: [aName, bName], measurementSpace: 'slide-inches', spatialConflictPolicy: 'report-only', authoringAuthority: 'ai', engineAction: 'report-only' }))
					continue
				}
				// Faithful HTML is an authored layered composition: images, support
				// shapes, text overlays, and masks may intentionally share a frame.
				// Preserve that source geometry and leave rendered visual review as the
				// authority; do not reinterpret every authored layer as a new semantic
				// collision. Caption safety remains strict above.
				if (faithfulHtml) continue
				// PowerPoint also represents native empty geometry as a text-capable
				// shape. Its type is not evidence of visible words: an empty ring or
				// floor treatment behind a model cannot obscure text that does not exist.
				// Spatial policy belongs to the AI; this validator reports the measured
				// relation and must not reject or repair an authored overlap.
				const aHasText = COMPOSITION_TEXT_PRIMITIVES.has(aPrimitive) && hasAudienceFacingDisplayText(a.obj)
				const bHasText = COMPOSITION_TEXT_PRIMITIVES.has(bPrimitive) && hasAudienceFacingDisplayText(b.obj)
				const textVisualPair = (aHasText && COMPOSITION_VISUAL_PRIMITIVES.has(bPrimitive)) || (bHasText && COMPOSITION_VISUAL_PRIMITIVES.has(aPrimitive))
				if (!textVisualPair) continue
				const decorative = [a.obj, b.obj].some(obj => obj.bleed === true || ['background', 'decorative'].includes(String(obj.role || obj.options?.role || '').toLowerCase())) || (!performanceCollision && /(?:orb|glow|ring|wash|background|canvas|accent|stage|surface|shell)/i.test(`${aName} ${bName}`))
				if (decorative) continue
				issues.push(compositionIssue('warning', 'TEXT_VISUAL_OVERLAP', performanceCollision ? 'Measured presenter/text spatial overlap during the authored performance.' : 'Measured text/visual spatial overlap in the authored composition.', 'AI authoring must choose whether to keep, layer, move, resize, hide, or retime the objects. The engine reports the relation and compiles the authored choice without applying a spatial policy.', { slideIndex, objects: [aName, bName], measurementSpace: 'slide-inches', spatialConflictPolicy: 'report-only', authoringAuthority: 'ai', engineAction: 'report-only', ...(performanceCollision ? { sampledAtMs: performanceCollision.atMs, visibleBodyRect: performanceCollision.rect } : {}) }))
			}
		}
		const cards = items.filter(({ obj }) => ['textShape', 'stat', 'kpi'].includes(obj.type || obj._type))
		if (cards.length >= 4) issues.push(compositionIssue('warning', 'CARD_GRID_OVERUSE', 'Slide uses a dense card grid; prefer one composition or a narrative visual when the cards do not materially clarify the story.', 'Reduce repetitive cards and express the message as one composition, a narrative visual, or a smaller semantic family.', { slideIndex, objectCount: cards.length }))
	}
	return issues
}

const MORPH_PREVIEW_KIND_DETAILS = [
	{ key: 'textBox', label: 'Text boxes', suggestion: 'Add at least one named text box on slide 1 and carry a related named text/accessory object into slide 2 when it should evolve.' },
	{ key: 'shape', label: 'Shapes', suggestion: 'Add a named shape, arrow, connector, badge, or callout that can move, resize, rotate, or restyle through Morph.' },
	{ key: 'image', label: 'Images', suggestion: 'Add a named image/logo/product visual that can move, resize, crop/reframe, or change transparency.' },
	{ key: 'wordArt', label: 'WordArt', suggestion: 'Add a named WordArt headline/accent and keep transform changes restrained across Morph.' },
	{ key: 'text3D', label: 'Text3D', suggestion: 'Add a named Text3D title/accent and morph position, style, or depth carefully.' },
	{ key: 'model3d', label: '3D models / GLB', suggestion: 'Add a named 3D model and change position, size, camera/view, or rotation for a premium hero reveal.' },
	{ key: 'shapeBuiltSmartArt', label: 'Shape-built SmartArt', suggestion: 'Add a shape-built process/list diagram so its inner pieces behave as normal Morph-friendly shapes.' },
]

function morphPreviewKindFromObject(obj = {}) {
	const opts = obj.options || {}
	const kind = obj.type || obj._type || ''
	const objectName = String(opts.objectName || obj.objectName || '')
	const shapeName = String(opts.shapeName || obj.shapeName || '')
	const hasTextPayload = obj.text != null || opts.text != null || Array.isArray(obj.text)
	const hasShapeSignal = kind === 'shape' || kind === 'freeform' || obj.shape || opts.shapeName || opts.shape || shapeName || /shape/i.test(objectName)
	const namedAsShape = /(^|[^a-z0-9])(shape|badge|callout|arrow|connector|line|card|hex|rect|circle)([^a-z0-9]|$)/i.test(objectName)
	if (kind === 'model3d') return 'model3d'
	if (kind === 'image') return 'image'
	if (kind === 'smartart') {
		const mode = String(opts.mode || (opts.native === true ? 'native' : '')).toLowerCase()
		return mode === 'shape' || opts.native === false ? 'shapeBuiltSmartArt' : null
	}
	if (/shape[-_\s]*built[-_\s]*smartart/i.test(objectName)) return 'shapeBuiltSmartArt'
	if (opts.text3D) return 'text3D'
	if (opts.wordArt) return 'wordArt'
	if (namedAsShape || (hasShapeSignal && !hasTextPayload)) return 'shape'
	if (kind === 'text') return 'textBox'
	if (hasShapeSignal) return 'shape'
	return null
}

function collectMorphPreviewCoverage(entry) {
	return {
		applicable: false,
		ok: true,
		mode: 'not-requested',
		enforcement: 'none',
		policy: {
			creativeFeatureGate: 'none',
			principle: 'Morph is available when the AI deliberately authors it; no commercial policy requires it.',
		},
		required: [],
		present: [],
		missing: [],
		counts: {},
		perSlide: [],
		recommendation: 'No Morph recommendation is emitted unless the AI or user requests Morph.',
	}
}

function model3DRotationOf(opts = {}) {
	const rot = opts.trans?.rot || opts.model3d?.trans?.rot || {}
	// Public semantic/model-view presets serialize DrawingML axis-angle values as
	// ax/ay/az in 1/60000 degree units, while direct authoring may use x/y/z in
	// degrees. Quality readback must understand both or an intentionally angled
	// native gallery view is falsely reported as a flat/front-on model.
	const degrees = (plain, ooxml) => {
		const direct = Number(rot[plain])
		if (Number.isFinite(direct)) return direct
		const encoded = Number(rot[ooxml])
		return Number.isFinite(encoded) ? encoded / 60000 : 0
	}
	return {
		x: degrees('x', 'ax'),
		y: degrees('y', 'ay'),
		z: degrees('z', 'az'),
		rotate: Number(opts.rotate || 0),
	}
}

function isExpressiveModel3D(opts = {}, obj = {}) {
	// A presenter/model with an authored or engine-solved scene clip is
	// expressive even when its neutral transform is front-facing. The gesture
	// itself is the pose authority; requiring an arbitrary static yaw/roll would
	// damage calibrated identity framing.
	if (obj.animation || obj.scene || opts.animation || opts.scene) return true
	const rot = model3DRotationOf(opts)
	const axes = [rot.x, rot.y, rot.z].filter(v => Math.abs(v) >= 10).length
	const magnitude = Math.hypot(rot.x, rot.y, rot.z, rot.rotate * 0.45)
	return axes >= 2 || Math.abs(rot.y) >= 28 || Math.abs(rot.z) >= 16 || magnitude >= 34
}

function gradientQualityPolicyForEntry(entry = {}) {
	const styleIntent = entry.authoredStyleIntent && typeof entry.authoredStyleIntent === 'object' ? entry.authoredStyleIntent : {}
	const policy = gradientPolicyForArtDirection({ styleIntent })
	return { expected: policy.expected, source: policy.world, rule: policy.rule }
}

function accentQualityPolicyForEntry(entry = {}) {
	const styleIntent = entry.authoredStyleIntent && typeof entry.authoredStyleIntent === 'object' ? entry.authoredStyleIntent : {}
	return accentPolicyForArtDirection({ styleIntent })
}

function depthQualityPolicyForEntry(entry = {}) {
	const styleIntent = entry.authoredStyleIntent && typeof entry.authoredStyleIntent === 'object' ? entry.authoredStyleIntent : {}
	return depthPolicyForArtDirection({ styleIntent })
}

function readabilityFontSizesForObject(obj = {}) {
	const values = []
	const push = value => {
		const number = Number(value)
		if (Number.isFinite(number) && number > 0) values.push(number)
	}
	push(obj.options?.fontSize)
	if (Array.isArray(obj.text)) {
		for (const run of obj.text) push(run?.options?.fontSize)
	}
	const seen = new WeakSet()
	const visitTableText = value => {
		if (!value || typeof value !== 'object') return
		if (seen.has(value)) return
		seen.add(value)
		if (Array.isArray(value)) {
			for (const child of value) visitTableText(child)
			return
		}
		push(value.options?.fontSize)
		if (value.text && typeof value.text === 'object') visitTableText(value.text)
		if (value._tableCells && typeof value._tableCells === 'object') visitTableText(value._tableCells)
	}
	visitTableText(obj.arrTabRows)
	return values
}

function readabilityRoleForObject(obj = {}, slideIndex = 0, slideObjects = []) {
	const kind = String(obj.type || obj._type || '').toLowerCase()
	const role = String(obj.role || obj.options?.role || '').toLowerCase()
	const name = String(obj.options?.objectName || obj.objectName || '').toLowerCase()
	const signal = `${kind} ${role} ${name}`
	if (readabilityShapeBuiltLabelBacking(obj, slideObjects)) return 'diagramLabel'
	if (/(?:^|[.\s_-])(?:footer|metadata|eyebrow|source|slide[-_ ]?number)(?:$|[.\s_-])/.test(signal)) return 'metadata'
	if (/(?:^|[.\s_-])(?:subtitle|subhead|section[-_ ]?heading|callout[-_ ]?header)(?:$|[.\s_-])/.test(signal)) return 'subheading'
	if (kind === 'title' || role === 'title' || /^(?:deck[\s_-]?title|slide[\s_-]?title|title)$/.test(name)) return slideIndex === 0 ? 'deckTitle' : 'slideTitle'
	if (kind === 'table') return 'tableCell'
	if (kind === 'smartart' || /(?:^|[.\s_-])(?:process|timeline|step)(?:$|[.\s_-])/.test(signal)) return 'diagramLabel'
	if (kind === 'chart' || /(?:^|[.\s_-])(?:metric(?:-grid|-card)?|stat|kpi)(?:$|[.\s_-])/.test(signal)) return 'dataLabel'
	return 'body'
}

function readabilityFloorForRole(role = 'body') {
	const floors = publicReadabilityContract().typeFloorsPt
	return Number(floors[role] || floors.body)
}

function readabilitySolidColor(value) {
	const color = typeof value === 'string' ? value : value?.color
	const normalized = String(color || '').replace(/^#/, '').toUpperCase()
	return /^[0-9A-F]{6}$/.test(normalized) ? normalized : null
}

function readabilityTextSamples(obj = {}, fallbackSize = 0) {
	const baseColor = readabilitySolidColor(obj.options?.color)
	const parsedBaseSize = Number(obj.options?.fontSize)
	const baseSize = Number.isFinite(parsedBaseSize) && parsedBaseSize > 0 ? parsedBaseSize : Number(fallbackSize) || 0
	const baseBold = obj.options?.bold === true
	if (Array.isArray(obj.text)) {
		const samples = []
		obj.text.forEach((run, runIndex) => {
			if (!String(run?.text || '').trim()) return
			const parsedSize = Number(run?.options?.fontSize)
			samples.push({
				runIndex,
				color: readabilitySolidColor(run?.options?.color) || baseColor,
				size: Number.isFinite(parsedSize) && parsedSize > 0 ? parsedSize : baseSize,
				bold: run?.options?.bold === true || (run?.options?.bold === undefined && baseBold),
			})
		})
		if (samples.length) return samples
	}
	return [{ runIndex: null, color: baseColor, size: baseSize, bold: baseBold }]
}

function readabilityNativeFillColor(obj = {}, themeScheme = {}) {
	const opts = obj.options || {}
	const rawFill = String(opts._rawFillXml || '')
	const rawStyle = String(opts._rawShapeStyleXml || '')
	if (opts._nativeMinimal !== true && !rawFill && !rawStyle) return { authoritative: false, color: null, transparent: false }
	const xml = rawFill || rawStyle
	if (!xml) return { authoritative: false, color: null, transparent: false }
	try {
		const wrapped = `<root xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main">${xml}</root>`
		const doc = new DOMParser().parseFromString(wrapped, 'application/xml')
		const root = doc.documentElement
		if (_xmlFirstDescendant(root, 'noFill')) return { authoritative: true, color: null, transparent: true }
		if (_xmlFirstDescendant(root, 'gradFill') || _xmlFirstDescendant(root, 'pattFill') || _xmlFirstDescendant(root, 'blipFill')) return { authoritative: true, color: null, transparent: false }
		const fillRef = _xmlFirstDescendant(root, 'fillRef')
		// The generated Office theme's fill-style index 1 is the solid phClr slot.
		// Higher indices are gradients whose lighting cannot be reduced to one RGB
		// value and therefore stay in the mandatory rendered-review bucket.
		if (fillRef && Number(_xmlAttr(fillRef, 'idx')) !== 1) return { authoritative: true, color: null, transparent: false }
		const colorHost = fillRef || root
		const srgb = _xmlFirstDescendant(colorHost, 'srgbClr')
		const sys = _xmlFirstDescendant(colorHost, 'sysClr')
		const scheme = _xmlFirstDescendant(colorHost, 'schemeClr')
		const colorNode = srgb || sys || scheme
		if (!colorNode) return { authoritative: true, color: null, transparent: false }
		// Tint/shade/luminance transforms require rendered review until the
		// diagnostic has a complete DrawingML colour-transform evaluator.
		if (_xmlElementChildren(colorNode).length) return { authoritative: true, color: null, transparent: false }
		if (srgb) return { authoritative: true, color: readabilitySolidColor(_xmlAttr(srgb, 'val')), transparent: false }
		if (sys) return { authoritative: true, color: readabilitySolidColor(_xmlAttr(sys, 'lastClr')), transparent: false }
		const aliases = { tx1: 'dk1', bg1: 'lt1', tx2: 'dk2', bg2: 'lt2' }
		const key = aliases[String(_xmlAttr(scheme, 'val') || '')] || String(_xmlAttr(scheme, 'val') || '')
		return { authoritative: true, color: readabilitySolidColor(themeScheme[key]), transparent: false }
	} catch (_) {
		return { authoritative: true, color: null, transparent: false }
	}
}

function readabilityOwnBackgroundColor(obj = {}, themeScheme = {}) {
	const native = readabilityNativeFillColor(obj, themeScheme)
	if (native.authoritative) {
		if (native.transparent) return { matched: false, color: null }
		// A native gradient, pattern, image fill, or unresolved colour transform
		// is still the object's real surface.  Keep it in manual rendered review;
		// never fall through and pretend the slide canvas is the background.
		return { matched: true, color: native.color }
	}
	const fill = obj.options?.fill
	if (fill) {
		const fillType = String(fill.type || '').toLowerCase()
		const transparency = Number(fill.transparency || 0)
		if (fillType === 'none' || transparency >= 95) return { matched: false, color: null }
		if (isGradientFill(fill) || transparency > 5) return { matched: true, color: null }
		return { matched: true, color: readabilitySolidColor(fill) }
	}
	return { matched: false, color: null }
}

function readabilityObjectRect(obj = {}) {
	const opts = obj.options || {}
	const rect = { x: Number(opts.x), y: Number(opts.y), w: Number(opts.w), h: Number(opts.h) }
	return Object.values(rect).every(Number.isFinite) && rect.w > 0 && rect.h > 0 ? rect : null
}

function readabilityRectContains(outer, inner, tolerance = 0.02) {
	if (!outer || !inner) return false
	return inner.x >= outer.x - tolerance
		&& inner.y >= outer.y - tolerance
		&& inner.x + inner.w <= outer.x + outer.w + tolerance
		&& inner.y + inner.h <= outer.y + outer.h + tolerance
}

function readabilityShapeBuiltLabelBacking(obj = {}, slideObjects = []) {
	const objectName = String(obj.options?.objectName || obj.objectName || '')
	const match = objectName.match(/^(.*)-label-(\d+)$/i)
	if (!match) return null
	const backingName = `${match[1]}-node-${match[2]}`
	const labelIndex = slideObjects.indexOf(obj)
	const candidates = labelIndex >= 0 ? slideObjects.slice(0, labelIndex).reverse() : slideObjects
	const backing = candidates.find(candidate => String(candidate?.options?.objectName || candidate?.objectName || '') === backingName)
	return backing && readabilityRectContains(readabilityObjectRect(backing), readabilityObjectRect(obj)) ? backing : null
}

function readabilityShapeBuiltLabelBackground(obj = {}, slideObjects = [], themeScheme = {}) {
	const backing = readabilityShapeBuiltLabelBacking(obj, slideObjects)
	if (!backing) return { matched: false, color: null }
	const backingBackground = readabilityOwnBackgroundColor(backing, themeScheme)
	return backingBackground.matched ? backingBackground : { matched: false, color: null }
}

function readabilityBackgroundColor(obj = {}, slide = {}, themeScheme = {}, slideObjects = []) {
	const own = readabilityOwnBackgroundColor(obj, themeScheme)
	if (own.matched) return own.color
	// Shape-mode SmartArt is emitted as an editable backing node followed by a
	// separate editable text label.  The label itself is intentionally no-fill;
	// measure it against its paired node, not against the slide canvas behind the
	// pair.  Exact stable names plus geometric containment keep this conservative.
	const shapeBuiltBacking = readabilityShapeBuiltLabelBackground(obj, slideObjects, themeScheme)
	if (shapeBuiltBacking.matched) return shapeBuiltBacking.color
	const background = slide.background
	if (background && !isGradientFill(background)) return readabilitySolidColor(background)
	return null
}

function readabilityRelativeLuminance(hex) {
	const rgb = hexToRgb(hex)
	if (!rgb) return null
	const linear = component => {
		const value = component / 255
		return value <= 0.03928 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4
	}
	return 0.2126 * linear(rgb.r) + 0.7152 * linear(rgb.g) + 0.0722 * linear(rgb.b)
}

function readabilityContrastRatio(foreground, background) {
	const left = readabilityRelativeLuminance(foreground)
	const right = readabilityRelativeLuminance(background)
	if (!Number.isFinite(left) || !Number.isFinite(right)) return null
	return (Math.max(left, right) + 0.05) / (Math.min(left, right) + 0.05)
}

function readabilityEmbeddedFontSamples(obj = {}) {
	const opts = obj.options || {}
	const kind = String(obj.type || obj._type || '').toLowerCase()
	const dataLabelsVisible = ['showValue', 'showLabel', 'showPercent', 'showSerName'].some(key => opts[key] === true)
	const samples = []
	const push = (field, role) => {
		const size = Number(opts[field])
		if (Number.isFinite(size) && size > 0) samples.push({ field, role, size })
	}
	if (kind === 'chart') {
		if (opts.showTitle === true) samples.push({
			field: 'title',
			role: 'dataLabel',
			size: Number(opts.titleFontSize) > 0 ? Number(opts.titleFontSize) : 18,
			color: readabilitySolidColor(opts.titleColor) || '000000',
			bold: opts.titleBold === true,
		})
		if (opts.catAxisHidden !== true) for (const field of ['catAxisLabelFontSize', 'catAxisTitleFontSize']) push(field, 'dataLabel')
		if (opts.valAxisHidden !== true) for (const field of ['valAxisLabelFontSize', 'valAxisTitleFontSize']) push(field, 'dataLabel')
		if (dataLabelsVisible) push('dataLabelFontSize', 'dataLabel')
		if (opts.showLegend === true) push('legendFontSize', 'dataLabel')
	}
	if (kind === 'table') {
		push('fontSize', 'tableCell')
		const seen = new WeakSet()
		const visit = (value, field) => {
			if (!value || typeof value !== 'object' || seen.has(value)) return
			seen.add(value)
			if (Array.isArray(value)) {
				value.forEach((child, index) => visit(child, `${field}[${index}]`))
				return
			}
			const size = Number(value.options?.fontSize)
			if (Number.isFinite(size) && size > 0) samples.push({ field: `${field}.options.fontSize`, role: 'tableCell', size })
			if (value.text && typeof value.text === 'object') visit(value.text, `${field}.text`)
			if (value._tableCells && typeof value._tableCells === 'object') visit(value._tableCells, `${field}._tableCells`)
		}
		visit(obj.arrTabRows, 'arrTabRows')
	}
	if (kind === 'smartart') push('fontSize', 'diagramLabel')
	return samples
}

function readabilityEmbeddedBackgroundColor(obj = {}, slide = {}, themeScheme = {}) {
	const chartAreaFill = obj.options?.chartArea?.fill
	if (chartAreaFill && !isGradientFill(chartAreaFill)) {
		if (String(chartAreaFill.type || '').toLowerCase() === 'none') return readabilityBackgroundColor(obj, slide, themeScheme)
		const transparency = Number(chartAreaFill.transparency || 0)
		if (transparency <= 5) return readabilitySolidColor(chartAreaFill)
		if (transparency < 95) return null
	}
	return readabilityBackgroundColor(obj, slide, themeScheme)
}

function collectDesignQuality(entry, args = {}) {
	const { pptx } = entry
	const slides = pptx.slides || []
	const slideCount = Math.max(1, slides.length)
	const profile = normalizeQualityProfile(args.profile || 'modern')
	const requireNarration = args.requireNarration ?? profile === 'narrated'
	const requireMotion = args.requireMotion ?? profile !== 'static'
	const requireVisualProof = args.requireVisualProof ?? true
	const requireExpressive3D = args.requireExpressive3D ?? true
	const minScore = Number(args.minScore ?? (profile === 'narrated' ? 80 : 70))
	const gradientPolicy = gradientQualityPolicyForEntry(entry)
	const accentPolicy = accentQualityPolicyForEntry(entry)
	const depthPolicy = depthQualityPolicyForEntry(entry)
	const colors = new Set()
	// Native gallery styles frequently reference scheme colours rather than
	// writing literal RGB values on each object. Seed the quality measurement
	// from the same resolved World theme that PowerPoint renders; otherwise a
	// genuinely multi-accent deck can be misreported as single-accent merely
	// because its native objects remain theme-linked and editable.
	if (entry.authoredStyleIntent && typeof entry.authoredStyleIntent === 'object') {
		const scheme = themeColorSchemeForSpec({ styleIntent: entry.authoredStyleIntent })
		for (const value of Object.values(scheme || {})) if (/^[0-9A-F]{6}$/i.test(String(value || ''))) colors.add(String(value).toUpperCase())
	}
	const fontSizes = []
	const metric = {
		gradientSurfaces: 0,
		depthObjects: 0,
		visualProofObjects: 0,
		diagramSlides: 0,
		textObjects: 0,
		titleScaleTextObjects: 0,
		animatedObjects: 0,
		animatedSlides: 0,
		model3DObjects: 0,
		model3DSlides: 0,
		expressiveModel3DObjects: 0,
		model3DMotionSlides: 0,
		narratedSlides: narrationCoverageForManifests(entry.narrationManifest, entry.avatarManifest).coveredSlideCount,
		captionObjects: 0,
		captionSlides: 0,
		objectCount: 0,
		readabilityTextObjects: 0,
		smallTextObjects: 0,
		evaluableContrastPairs: 0,
		lowContrastPairs: 0,
		manualContrastReviewObjects: 0,
	}
	const smallTextEvidence = []
	const lowContrastEvidence = []
	const readabilityThemeScheme = {
		dk1: '000000',
		lt1: 'FFFFFF',
		dk2: '44546A',
		lt2: 'E7E6E6',
		...(entry.pptx?.theme?.palette || {}),
	}

	for (const [slideIndex, slide] of slides.entries()) {
		let slideHasAnimation = false
		let slideCaptionObjects = 0
		let visualShapeCount = 0
		let slideHasDiagram = false
		let slideHasModel3D = false
		let slideHasModel3DMotion = false
		if (isGradientFill(slide.background)) {
			metric.gradientSurfaces++
			collectGradientStops(slide.background, colors)
		}
		if (slide.background?.color) colors.add(String(slide.background.color).replace(/^#/, '').toUpperCase())
		const objects = _editableSlideObjects(slide).map(x => x.obj)
		metric.objectCount += objects.length
		for (const obj of objects) {
			const opts = obj.options || {}
			const kind = obj.type || obj._type
			const objectName = String(opts.objectName || obj.objectName || '')
			const semanticRole = String(obj.role || opts.role || '')
			if (String(kind || '').toLowerCase() === 'smartart' || semanticRole.toLowerCase() === 'smartart') slideHasDiagram = true
			_collectColors(opts, colors)
			_collectColors(obj.text, colors)
			const renderedGradient = renderedGradientStateForObject(obj)
			if (renderedGradient.gradient) {
				metric.gradientSurfaces++
				collectGradientStops(renderedGradient.fill, colors)
			}
			if (hasDepth(opts)) metric.depthObjects++
			if (hasAudienceFacingDisplayText(obj)) {
				metric.textObjects++
				metric.readabilityTextObjects++
				const sizes = readabilityFontSizesForObject(obj)
				const size = sizes.length ? Math.min(...sizes) : 0
				for (const value of sizes) fontSizes.push(value)
				if (size >= 22) metric.titleScaleTextObjects++
				const readabilityRole = readabilityRoleForObject(obj, slideIndex, objects)
				const readabilityFloor = readabilityFloorForRole(readabilityRole)
				if (size > 0 && size < readabilityFloor) {
					metric.smallTextObjects++
					if (smallTextEvidence.length < 12) smallTextEvidence.push({ slideNumber: slideIndex + 1, objectName, role: readabilityRole, actualPt: size, floorPt: readabilityFloor })
				}
				const background = readabilityBackgroundColor(obj, slide, readabilityThemeScheme, objects)
				let unresolvedContrast = false
				for (const sample of readabilityTextSamples(obj, size)) {
					const foreground = sample.color
					const ratio = foreground && background ? readabilityContrastRatio(foreground, background) : null
					if (!Number.isFinite(ratio)) {
						unresolvedContrast = true
						continue
					}
					metric.evaluableContrastPairs++
					const large = sample.size >= 24 || (sample.size >= 18 && sample.bold)
					const target = large ? publicReadabilityContract().contrastTargets.largeText : publicReadabilityContract().contrastTargets.normalText
					if (ratio < target) {
						metric.lowContrastPairs++
						if (lowContrastEvidence.length < 12) lowContrastEvidence.push({ slideNumber: slideIndex + 1, objectName, runIndex: sample.runIndex, actualPt: sample.size, foreground, background, ratio: Math.round(ratio * 100) / 100, target })
					}
				}
				if (unresolvedContrast) metric.manualContrastReviewObjects++
			}
			let unresolvedEmbeddedContrast = false
			for (const sample of readabilityEmbeddedFontSamples(obj)) {
				fontSizes.push(sample.size)
				const floor = readabilityFloorForRole(sample.role)
				if (sample.size < floor) {
					metric.smallTextObjects++
					if (smallTextEvidence.length < 12) smallTextEvidence.push({ slideNumber: slideIndex + 1, objectName, role: sample.role, field: sample.field, actualPt: sample.size, floorPt: floor })
				}
				if (sample.color) {
					const background = readabilityEmbeddedBackgroundColor(obj, slide, readabilityThemeScheme)
					const ratio = background ? readabilityContrastRatio(sample.color, background) : null
					if (!Number.isFinite(ratio)) {
						unresolvedEmbeddedContrast = true
						continue
					}
					metric.evaluableContrastPairs++
					const large = sample.size >= 24 || (sample.size >= 18 && sample.bold)
					const target = large ? publicReadabilityContract().contrastTargets.largeText : publicReadabilityContract().contrastTargets.normalText
					if (ratio < target) {
						metric.lowContrastPairs++
						if (lowContrastEvidence.length < 12) lowContrastEvidence.push({ slideNumber: slideIndex + 1, objectName, field: sample.field, actualPt: sample.size, foreground: sample.color, background, ratio: Math.round(ratio * 100) / 100, target })
					}
				}
			}
			if (unresolvedEmbeddedContrast) metric.manualContrastReviewObjects++
			if (/^narration-caption-/i.test(String(opts.objectName || ''))) {
				metric.captionObjects++
				slideCaptionObjects++
			}
			const isNarrationAudio = /^narration-audio-/i.test(objectName)
			// Semantic Director blocks are concrete proof even when their persisted
			// object is a textShape: KPI/metric cards, comparison panels, and
			// process/timeline steps are visual evidence, not ordinary body copy.
			// Count them here so the quality gate agrees with contentSignals.visualProof
			// and does not ask the AI to add decorative raster/chart filler.
			const semanticProof = /^(?:metric(?:-grid|-card)?|stat|kpi|comparison(?:-panel)?|process|timeline|step|text-shape|equation)$/i.test(semanticRole)
				|| /(?:^|[.-])(?:metric-grid|metric-card|stat|kpi|comparison-panel|process|timeline|step|textshape|text-shape|equation)(?:[.-]|$)/i.test(objectName)
			if (!isNarrationAudio && (['image', 'chart', 'table', 'model3d', 'passthrough', 'freeform', 'customGeometry', 'textShape', 'equation'].includes(kind) || semanticProof)) {
				metric.visualProofObjects++
			}
			if (kind === 'model3d') {
				metric.model3DObjects++
				slideHasModel3D = true
				if (isExpressiveModel3D(opts, obj)) metric.expressiveModel3DObjects++
				// Presenter-director scene choreography is lowered into the native
				// animation package, so the persisted object may not retain a simple
				// graphic-frame animation field. The stable presenter contract itself
				// is evidence of motion coverage for this quality metric.
				if (obj.animation || obj.scene || opts.animation || opts.scene || /presenter/i.test(String(opts.objectName || obj.objectName || ''))) slideHasModel3DMotion = true
			}
			if (obj.shape && opts.fill && !hasDisplayText(obj)) visualShapeCount++
		}
		if (visualShapeCount >= 3 || slideHasDiagram) metric.diagramSlides++
		const animations = slide._animations || []
		const nonMediaAnimations = animations.filter(a => {
			const animation = a.animation || {}
			const effect = String(animation.effect || '').toLowerCase()
			if (slideHasModel3D && ['turntable', 'swing', 'jumpandturn', 'arrive', 'playscene', 'play-scene'].includes(effect)) slideHasModel3DMotion = true
			return animation.type !== 'media' && !effect.startsWith('media')
		})
		if (nonMediaAnimations.length) {
			metric.animatedObjects += nonMediaAnimations.length
			slideHasAnimation = true
		}
		if (slideHasAnimation) metric.animatedSlides++
		if (slideHasModel3DMotion) metric.model3DMotionSlides++
		if (slideHasModel3D) metric.model3DSlides++
		if (slideCaptionObjects) metric.captionSlides++
	}

	const uniqueColors = Array.from(colors).filter(c => /^[0-9A-F]{6}$/i.test(c))
	const accentColors = uniqueColors.filter(isAccentColor)
	const minFont = fontSizes.length ? Math.min(...fontSizes) : 0
	const maxFont = fontSizes.length ? Math.max(...fontSizes) : 0
	const fontRange = maxFont - minFont
	const proofObjects = metric.visualProofObjects + metric.diagramSlides
	// Proof is a deck-level story resource, not a requirement to decorate every
	// rhetorical opener or closer. A strong modern deck should provide concrete
	// proof on most slides; the AI still decides which slides legitimately remain
	// typographic or decision-led.
	const visualProofTarget = requireVisualProof ? Math.max(1, Math.ceil(slideCount * 0.75)) : 0
	const hasModel3D = metric.model3DObjects > 0
	const expressive3DTarget = hasModel3D ? metric.model3DObjects : 0
	const components = [
		{ key: 'gradient', label: 'Gradient surfaces', points: componentScore(metric.gradientSurfaces, gradientPolicy.expected ? slideCount : 0, 15), maxPoints: 15, actual: metric.gradientSurfaces, target: gradientPolicy.expected ? slideCount : null },
		{ key: 'depth', label: 'World depth treatments', points: componentScore(metric.depthObjects, slideCount * depthPolicy.minimumDepthObjectsPerSlide, 15), maxPoints: 15, actual: metric.depthObjects, target: depthPolicy.minimumDepthObjectsPerSlide > 0 ? slideCount * depthPolicy.minimumDepthObjectsPerSlide : null },
		{ key: 'palette', label: 'World accent palette', points: Math.min(10, componentScore(accentColors.length, accentPolicy.minimumDistinctAccents, 7) + componentScore(uniqueColors.length, 6, 3)), maxPoints: 10, actual: accentColors.length, target: accentPolicy.minimumDistinctAccents },
		{ key: 'hierarchy', label: 'Typography hierarchy', points: Math.min(12, componentScore(metric.titleScaleTextObjects, slideCount, 7) + componentScore(fontRange, 12, 5)), maxPoints: 12, actual: Math.round(fontRange * 10) / 10, target: 12 },
		{ key: 'visualProof', label: 'Visual proof objects', points: componentScore(proofObjects, visualProofTarget, 10), maxPoints: 10, actual: proofObjects, target: visualProofTarget || null },
		{ key: 'motion', label: 'Synchronized motion', points: componentScore(metric.animatedSlides, requireMotion ? slideCount : Math.ceil(slideCount / 2), 10), maxPoints: 10, actual: metric.animatedSlides, target: requireMotion ? slideCount : Math.ceil(slideCount / 2) },
		{ key: 'expressive3D', label: 'Expressive 3D pose', points: hasModel3D ? componentScore(metric.expressiveModel3DObjects, expressive3DTarget, 10) : 10, maxPoints: 10, actual: metric.expressiveModel3DObjects, target: expressive3DTarget || null },
		{ key: 'narration', label: 'Narration when required', points: componentScore(metric.narratedSlides, requireNarration ? slideCount : 0, 18), maxPoints: 18, actual: metric.narratedSlides, target: requireNarration ? slideCount : null },
	]
	const score = components.reduce((sum, c) => sum + c.points, 0)
	const morphPreviewCoverage = collectMorphPreviewCoverage(entry)
	const issues = []
	if (gradientPolicy.expected && metric.gradientSurfaces < slideCount) issues.push(designIssue('warning', 'LOW_GRADIENT_COVERAGE', 'The selected World expects gradient surfaces as part of its visual system.', 'Add a gradient canvas, panel, chart fill, or semantic accent band; do not add gradients when the selected World intentionally uses a flat or wireframe treatment.'))
	const depthTarget = slideCount * depthPolicy.minimumDepthObjectsPerSlide
	if (depthTarget > 0 && metric.depthObjects < depthTarget) issues.push(designIssue('warning', 'LOW_DEPTH_COVERAGE', 'The selected World expects meaningful depth treatment on important visual objects.', 'Add one semantic frame, shadow, glow, reflection, or subtle 3D treatment per slide where the story calls for it; do not add decorative depth.'))
	if (accentColors.length < accentPolicy.minimumDistinctAccents) issues.push(designIssue('warning', 'LOW_ACCENT_DIVERSITY', `Palette has fewer than ${accentPolicy.minimumDistinctAccents} World-approved accent color${accentPolicy.minimumDistinctAccents === 1 ? '' : 's'}.`, accentPolicy.minimumDistinctAccents === 1
		? 'Use the selected World\'s restrained accent treatment; do not add decorative colour merely to raise a score.'
		: 'Use neutral surfaces plus at least two distinct accent colors.'))
	if (metric.titleScaleTextObjects < slideCount || fontRange < 12) issues.push(designIssue('warning', 'WEAK_TEXT_HIERARCHY', 'Typography hierarchy is not strong enough for a modern deck.', 'Use clear title, subtitle, label, and metadata text levels.'))
	if (metric.smallTextObjects > 0 && readabilityPolicyForSpec(entry.canonicalSpecState?.spec || { authoringContract: { readabilityPolicy: entry.readabilityPolicy } }) !== 'faithful-html' && entry.readabilityPolicy !== 'faithful-html') issues.push({
		...designIssue('warning', 'SMALL_TEXT_READABILITY_RISK', `${metric.smallTextObjects} text or data-label treatment${metric.smallTextObjects === 1 ? '' : 's'} fall below the default presentation-size floor for their semantic role.`, 'Shorten or split the copy, strengthen the type role, or enlarge/recompose the AI-authored frame; do not shrink text merely to make it fit. A PowerPoint render is optional release qualification, not a production save gate.'),
		evidence: { code: 'SMALL_TEXT_READABILITY_RISK', count: metric.smallTextObjects, examples: smallTextEvidence, typeFloorsPt: publicReadabilityContract().typeFloorsPt },
	})
	if (metric.lowContrastPairs > 0) issues.push({
		...designIssue('warning', 'LOW_TEXT_CONTRAST', `${metric.lowContrastPairs} measurable foreground/background pair${metric.lowContrastPairs === 1 ? '' : 's'} fall below the readability contrast target.`, 'Choose a clearer World, palette, surface, or exact native variant; then inspect the full-slide render because lighting, gradients, images, effects, and transparency can change perceived contrast.'),
		evidence: { code: 'LOW_TEXT_CONTRAST', count: metric.lowContrastPairs, examples: lowContrastEvidence, contrastTargets: publicReadabilityContract().contrastTargets },
	})
	if (requireVisualProof && proofObjects < visualProofTarget) issues.push(designIssue('warning', 'LOW_VISUAL_PROOF', 'The deck needs more concrete visual proof.', 'Add story-serving charts, data/KPI blocks, images, 3D assets, architecture, or process visuals where evidence is missing; rhetorical openers and closers may remain typographic.'))
	if (requireMotion && metric.animatedSlides < slideCount) {
		// Keep the correction grounded in the actual authoring contract.  A modern
		// deck may be intentionally non-narrated; telling that author to animate
		// objects "discussed by narration" is misleading and makes the public
		// Director readback imply a voice track that does not exist.  Narrated
		// decks get the phrase-anchor guidance, while static-story decks get the
		// semantic-story guidance.  Neither path suggests animating scaffolding.
		const motionFix = metric.narratedSlides > 0 || requireNarration
			? 'Add cue-timed entrance or emphasis animations for the meaningful objects discussed by narration; retain AI-authored geometry and animate only story-serving objects.'
			: 'Add cue-timed entrance or emphasis animations for meaningful story objects when movement improves comprehension; retain AI-authored geometry.'
		issues.push(designIssue('warning', 'LOW_MOTION_COVERAGE', 'Motion is not applied across the full story.', motionFix))
	}
	if (requireExpressive3D && hasModel3D && metric.expressiveModel3DObjects < metric.model3DObjects) issues.push(designIssue('warning', 'LOW_3D_POSE_EXPRESSIVENESS', 'Some 3D models read as flat/front-on in exported slide previews.', 'Use varied pose/view settings, non-zero x/y/z model rotations, 2D rotate for fallback posters, and turntable/swing emphasis.'))
	const model3DMotionTarget = Math.min(metric.model3DSlides, Math.ceil(metric.model3DSlides * 0.7))
	if (requireExpressive3D && hasModel3D && metric.model3DMotionSlides < model3DMotionTarget) {
		const modelMotionFix = metric.narratedSlides > 0 || requireNarration
			? 'Apply turntable, swing, jump-and-turn, or morph-driven rotation to the models named in the narration.'
			: 'Apply turntable, swing, jump-and-turn, or morph-driven rotation to model objects when movement improves comprehension; keep the motion story-serving.'
		issues.push(designIssue('warning', 'LOW_3D_MOTION_COVERAGE', '3D models need stronger motion coverage on the slides where they appear.', modelMotionFix))
	}
	if (requireNarration && metric.narratedSlides < slideCount) issues.push(designIssue(
		'error',
		'MISSING_NARRATION_COVERAGE',
		'Narrated profile requires narration on every slide.',
		isPublicBlackBoxMode()
			? 'Add semantic narration directives for every slide in the JSON spec, then rerun the narration and quality validators.'
			: 'Use slide.add_narration or deck.add_narration for all slides.',
	))
	if (morphPreviewCoverage.applicable && morphPreviewCoverage.missing?.length) {
		issues.push(designIssue('info', 'MORPH_PREVIEW_OBJECT_COVERAGE_OPTIONAL', 'Optional Morph-friendly object kinds are not all present.', morphPreviewCoverage.recommendation))
	}
	if (score < minScore) {
		const timingNeed = requireNarration ? 'cue-timed motion, and narration' : 'and story-serving motion'
		issues.push(designIssue('error', 'DESIGN_SCORE_BELOW_THRESHOLD', `Design score ${score} is below required threshold ${minScore}.`, gradientPolicy.expected
			? `Apply the selected World's visual language: meaningful gradient surfaces, depth, hierarchy, visual proof, ${timingNeed}.`
			: `Apply the selected World's visual language: appropriate surfaces, depth, hierarchy, visual proof, ${timingNeed}; do not add gradients unless the World expects them.`))
	}

	return {
		ok: score >= minScore && !issues.some(i => i.severity === 'error'),
		profile,
		score,
		minScore,
		components,
		metrics: {
			...metric,
			uniqueColors: uniqueColors.length,
			accentColors: accentColors.length,
			minFontSize: minFont || null,
			maxFontSize: maxFont || null,
			fontSizeRange: fontRange || null,
			avgObjectsPerSlide: Math.round((metric.objectCount / slideCount) * 10) / 10,
		},
		morphPreviewCoverage,
		gradientPolicy,
		accentPolicy,
		depthPolicy,
		readability: {
			...publicReadabilityContract(),
			measurements: {
				textObjects: metric.readabilityTextObjects,
				smallTextObjects: metric.smallTextObjects,
				evaluableContrastPairs: metric.evaluableContrastPairs,
				lowContrastPairs: metric.lowContrastPairs,
				manualContrastReviewObjects: metric.manualContrastReviewObjects,
				minFontSize: minFont || null,
				maxFontSize: maxFont || null,
			},
			findings: {
				smallText: smallTextEvidence,
				lowContrast: lowContrastEvidence,
			},
			manualVisualReviewRequired: true,
		},
		issues,
	}
}

async function handleValidateDesign(args) {
	const entry = getDeck(args.deckId)
	const profile = normalizeQualityProfile(args.profile || (args.requireNarration === true ? 'narrated' : 'modern'))
	const quality = collectDesignQuality(entry, { ...args, profile })
	const previewLayout = previewSlideLayout(entry?.pptx)
	const compositionIssues = collectCompositionIssues(entry, { w: previewLayout.widthInches, h: previewLayout.heightInches })
	const issues = [...(quality.issues || []), ...compositionIssues]
	// The score is useful direction, but the old score ingredients (gradients,
	// shadows, card density) are not universal laws. They must not block an
	// editorial, blueprint, brutalist, luxe, mist, or bespoke world. A caller
	// can still request strict score enforcement explicitly with minScore or
	// enforceScore; composition and explicit narration contracts always block.
	const enforceScore = args.enforceScore === true || args.minScore !== undefined
	const blockingIssues = issues.filter(issue => issue.severity === 'error' && (enforceScore || issue.code !== 'DESIGN_SCORE_BELOW_THRESHOLD'))
	const passed = blockingIssues.length === 0
	const reportedIssues = issues.map(issue => !enforceScore && issue.code === 'DESIGN_SCORE_BELOW_THRESHOLD'
		? { ...issue, severity: 'warning', advisory: true }
		: issue)
	return {
		ok: passed,
		deactivated: false,
		profile,
		score: quality.score,
		minScore: quality.minScore,
		passed,
		issues: reportedIssues,
		findings: compositionIssues,
		metrics: quality.metrics,
		components: quality.components,
		gradientPolicy: quality.gradientPolicy,
		accentPolicy: quality.accentPolicy,
		depthPolicy: quality.depthPolicy,
		readability: quality.readability,
		scoreAdvisory: !enforceScore,
		assessmentBasis: 'deterministic-structural-heuristic',
		appearanceVerified: false,
		playbackVerified: false,
		note: 'Design validation is active across worlds: geometry, text/visual collisions, literal line breaks, hierarchy, readability measurements, proof, motion, and accessibility-adjacent composition checks are evaluated without imposing a single visual skin. The score is structural and heuristic, not perceptual approval. Rendered full-slide review is optional release qualification unless a stronger profile is explicitly requested.',
	}
}

function qualityIssue({ code, gate, severity = 'error', slide = null, objectHandle = null, issue, recommendedTool, suggestedFix = null, reason = null, fix = null, evidence = null }) {
	const resolvedIssue = issue || `${code || 'QUALITY_FINDING'} requires semantic review.`
	const resolvedFix = typeof fix === 'string' && fix.trim()
		? fix
		: typeof suggestedFix === 'string' && suggestedFix.trim()
		? suggestedFix
		: 'Revise the semantic input identified by this finding and rerun the quality gate; do not patch returned geometry or native package data.'
	return compactObject({
		code,
		gate,
		severity,
		slide,
		objectHandle,
		issue: resolvedIssue,
		message: resolvedIssue,
		reason: reason || resolvedIssue,
		fix: resolvedFix,
		evidence: evidence || { gate, slide, objectHandle, code },
		recommendedTool: validationRecoveryTool(recommendedTool),
		suggestedFix,
	})
}

function collectDirectorValidation(entry) {
	const status = publicDirectorStatus(entry)
	const mode = status.mode
	if (mode === 'ai-sovereign') {
		return {
			ok: true,
			blocking: false,
			mode,
			missingStages: [],
			missingDomains: [],
			status,
			issues: [],
			warnings: [],
		}
	}
	const missingStages = directorPlanningMissingStages(entry)
	const domainCoverage = directorDomainCoverage(entry)
	const issues = missingStages.map(stage => ({
		stage,
		code: 'DIRECTOR_STAGE_MISSING',
		issue: `${DIRECTOR_STAGE_NAMES[stage] || stage} is required before primitive authoring and save.`,
		recommendedTool: validationRecoveryTool(DIRECTOR_STAGE_TOOLS[stage], 'betterpptx.deck.director_status'),
	}))
	if (!domainCoverage.complete) issues.push({
		stage: 'domain-composition',
		code: 'DIRECTOR_DOMAIN_REQUIRED',
		issue: `The ${domainCoverage.missing.map(key => DIRECTOR_DOMAIN_NAMES[key]).join(', ')} must be composed before primitive authoring and save.`,
		recommendedTool: validationRecoveryTool('betterpptx.deck.define_message_architecture'),
	})
	const blocking = mode === 'director-strict' || directorIsNewDeck(entry)
	return {
		ok: !blocking || issues.length === 0,
		blocking,
		mode,
		missingStages,
		missingDomains: domainCoverage.missing,
		status,
		issues: blocking ? issues : [],
		warnings: mode === 'director-guided' ? issues : [],
	}
}

async function handleValidateQuality(args) {
	const entry = getDeck(args.deckId)
	const declaredNarratedAutoplay = entry.deliveryExperience?.mode === 'narrated-autoplay'
	const profile = normalizeQualityProfile(args.profile || (args.requireNarration === true || declaredNarratedAutoplay ? 'narrated' : 'modern'))
	const strictness = String(args.strictness || args.mode || 'normal').toLowerCase()
	const requireNarration = declaredNarratedAutoplay || (args.requireNarration ?? profile === 'narrated')
	markDirectorTimelineContract(entry, entry.narrationManifest?.slides?.length
		? 'narration'
		: entry.avatarManifest?.slides?.length
			? 'avatar-narration'
			: 'explicit-director-timeline')
	let directorValidation = collectDirectorValidation(entry)
	const packageValidation = await handleValidate({ deckId: args.deckId, mode: args.mode || 'normal', autoFix: false })
	const designValidation = await handleValidateDesign({
		...args,
		profile,
		requireNarration,
	})
	const accessibilityValidation = await handleValidateAccessibility({
		deckId: args.deckId,
		mode: args.accessibilityMode || 'basic',
	})
	const hasNarration = Boolean(entry.narrationManifest?.slides?.length || entry.avatarManifest?.slides?.length)
	const narrationValidation = (requireNarration || hasNarration)
		? await handleValidateNarration({
			deckId: args.deckId,
			filePath: args.filePath,
			compression: args.compression !== false,
		})
		: {
			ok: true,
			skipped: true,
			reason: 'No narration manifest was present and narration was not required for this profile.',
		}
	const savedPackagePath = args.filePath || entry.lastSavedPath || null
	const savedPackageSafety = savedPackagePath
		? await validateSavedPackageSafety(savedPackagePath, {
			publicMode: isPublicBlackBoxMode(),
			metadataLeakOptions: metadataLeakOptionsForEntry(entry),
		})
		: {
			ok: true,
			skipped: true,
			reason: 'No saved package is available for durable metadata checks yet.',
	}
	const blockingIssues = []
	const warnings = []
	const packageGatePassed = packageValidation.valid === true && Number(packageValidation.errorCount || 0) === 0
	// Most design findings remain advisory because visual worlds are intentionally
	// diverse. Objective materialized-frame overflow is different: once text cannot
	// fit at its semantic readability floor, the aggregate pre-save quality gate
	// must not report a pass merely because PowerPoint can apply `fit:"shrink"`.
	const blockingDesignIssues = (designValidation.issues || []).filter(item =>
		item?.severity === 'error' && item?.code === 'TEXT_OVERFLOW_RISK')
	const requireEveryValidatorPass = isPublicBlackBoxMode()
	const designGatePassed = blockingDesignIssues.length === 0 && (!requireEveryValidatorPass || designValidation.ok === true)

	if (directorValidation.ok !== true) {
		for (const item of directorValidation.issues || []) {
			blockingIssues.push(qualityIssue({
				code: item.code,
				gate: 'director',
				issue: item.issue,
				recommendedTool: validationRecoveryTool(item.recommendedTool),
				suggestedFix: 'Complete the director planning stages before slide primitives or save.',
				reason: item.reason || item.issue,
				evidence: { gate: 'director', stage: item.stage, code: item.code },
			}))
		}
	}
	for (const item of directorValidation.warnings || []) {
		warnings.push(qualityIssue({
			code: item.code,
			gate: 'director',
			severity: 'warning',
			issue: item.issue,
			recommendedTool: validationRecoveryTool(item.recommendedTool),
			suggestedFix: 'Complete the director planning stages for stronger generated presentation quality.',
			reason: item.reason || item.issue,
			evidence: { gate: 'director', stage: item.stage, code: item.code },
		}))
	}

	if (!packageGatePassed) {
		const findings = packageValidation.findings?.length
			? packageValidation.findings
			: (packageValidation.issues || []).map(normalizeValidationFinding)
		if (findings.length) {
			for (const finding of findings) {
				blockingIssues.push(qualityIssue({
					code: finding.code || 'PACKAGE_VALIDATION_FAILED',
					gate: 'package',
					slide: finding.slide,
					objectHandle: finding.objectHandle,
					issue: finding.issue || 'Package/layout validation failed.',
					recommendedTool: finding.recommendedTool || 'betterpptx.deck.validate',
					suggestedFix: finding.fix || 'Apply the recommended semantic correction and rerun the quality gate before saving.',
					reason: finding.reason || finding.whyItMatters || finding.issue,
					evidence: finding.evidence || { gate: 'package', slide: finding.slide, objectHandle: finding.objectHandle, code: finding.code || 'PACKAGE_VALIDATION_FAILED' },
				}))
			}
		} else {
			blockingIssues.push(qualityIssue({
				code: 'PACKAGE_VALIDATION_FAILED',
				gate: 'package',
				issue: 'Package/layout validation failed.',
				recommendedTool: 'betterpptx.deck.validate',
				suggestedFix: 'Run deck.validate and fix the first reported package or layout issue.',
			}))
		}
	}

	for (const item of designValidation.issues || []) {
		const target = blockingDesignIssues.includes(item) ? blockingIssues : warnings
		target.push(qualityIssue({
			code: item.code || 'DESIGN_ADVISORY',
			gate: 'design',
			severity: item.severity || 'warning',
			slide: item.slide ?? item.slideIndex ?? item.evidence?.slideIndex ?? null,
			objectHandle: item.objectHandle || item.evidence?.objectName || null,
			issue: item.message || item.issue || 'Design quality advisory.',
			recommendedTool: validationRecoveryTool(item.recommendedTool),
			suggestedFix: item.fix || item.suggestion || null,
			reason: item.reason || item.message || item.issue,
			evidence: item.evidence || { gate: 'design', code: item.code || 'DESIGN_ADVISORY' },
		}))
	}
	if (requireEveryValidatorPass && !designGatePassed && blockingDesignIssues.length === 0) {
		blockingIssues.push(qualityIssue({
			code: 'DESIGN_VALIDATION_FAILED',
			gate: 'design',
			issue: 'Design validation did not pass for the current deck version.',
			recommendedTool: validationRecoveryTool('betterpptx.deck.revise'),
			suggestedFix: 'Revise the semantic design intent and resolve the reported design findings, then rerun the aggregate quality gate.',
			reason: 'A completed design check is insufficient when its own passed result is false.',
			evidence: { gate: 'design', score: designValidation.score, minScore: designValidation.minScore },
		}))
	}
	for (const item of accessibilityValidation.findings || []) {
		const target = requireEveryValidatorPass ? blockingIssues : warnings
		target.push(qualityIssue({
			code: item.code || 'ACCESSIBILITY_VALIDATION_FAILED',
			gate: 'accessibility',
			severity: requireEveryValidatorPass ? 'error' : (item.severity || 'warning'),
			slide: item.slide,
			objectHandle: item.objectHandle,
			issue: item.issue || 'Accessibility advisory.',
			recommendedTool: validationRecoveryTool(item.recommendedTool),
			suggestedFix: item.fix || null,
			reason: item.reason || item.whyItMatters || item.issue,
			evidence: item.evidence || { gate: 'accessibility', slide: item.slide, objectHandle: item.objectHandle, code: item.code || 'ACCESSIBILITY_VALIDATION_FAILED' },
		}))
	}
	if (narrationValidation.ok !== true) {
		for (const item of narrationValidation.issues || ['Narration package/timing validation failed.']) {
			blockingIssues.push(qualityIssue({
				code: 'NARRATION_TIMING_INVALID',
				gate: 'narration',
				issue: String(item),
				recommendedTool: 'betterpptx.deck.validate_narration',
				suggestedFix: 'Regenerate narration timing or increase slide advance duration before saving.',
				reason: 'Narration timing or package validation did not satisfy the authored timing contract.',
				evidence: { gate: 'narration', detail: String(item) },
			}))
		}
	}
	if (savedPackageSafety.ok !== true) {
		for (const item of savedPackageSafety.issues || []) {
			blockingIssues.push(qualityIssue({
				code: item.code || 'SAVED_PACKAGE_SAFETY_FAILED',
				gate: item.scope === 'metadata' || item.scope === 'relationship target' ? 'saved-package-metadata' : 'saved-package',
				issue: item.message || 'Saved package safety validation failed.',
				recommendedTool: item.scope === 'metadata' || item.scope === 'relationship target' ? 'betterpptx.deck.save' : 'betterpptx.deck.validate',
				suggestedFix: item.scope === 'metadata' || item.scope === 'relationship target'
					? 'Remove private metadata/path disclosure and save again.'
					: 'Fix package serialization and save again.',
				reason: item.reason || item.message || 'The saved package did not satisfy the delivery safety contract.',
				evidence: item.evidence || { gate: 'saved-package', scope: item.scope || null, code: item.code || 'SAVED_PACKAGE_SAFETY_FAILED' },
			}))
		}
	}
	for (const item of savedPackageSafety.warnings || []) {
		warnings.push(qualityIssue({
			code: item.code || 'SAVED_PACKAGE_METADATA_WARNING',
			gate: 'saved-package-metadata',
			severity: 'warning',
			issue: item.message || 'Saved package metadata warning.',
			recommendedTool: 'betterpptx.deck.save',
			suggestedFix: 'Remove private metadata/path disclosure before public delivery.',
			reason: item.reason || item.message || 'The saved package contains metadata that should be removed before public delivery.',
			evidence: item.evidence || { gate: 'saved-package-metadata', scope: item.scope || null, code: item.code || 'SAVED_PACKAGE_METADATA_WARNING' },
		}))
	}

	const checks = [
		{
			key: 'director',
			ok: directorValidation.ok === true,
			blocking: directorValidation.blocking === true,
			mode: directorValidation.mode,
			missingStages: directorValidation.missingStages,
			recommendedTool: validationRecoveryTool(
				directorValidation.missingStages?.length ? DIRECTOR_STAGE_TOOLS[directorValidation.missingStages[0]] : 'betterpptx.deck.director_status',
				'betterpptx.deck.director_status',
			),
		},
		{
			key: 'package',
			ok: packageGatePassed,
			blocking: true,
			errors: packageValidation.errorCount || 0,
			warnings: packageValidation.warningCount || 0,
			recommendedTool: 'betterpptx.deck.validate',
		},
		{
			key: 'design',
			ok: designGatePassed,
			advisoryOk: designValidation.ok === true,
			blocking: requireEveryValidatorPass ? designGatePassed !== true : blockingDesignIssues.length > 0,
			score: designValidation.score,
			minScore: designValidation.minScore,
			issues: designValidation.issues?.length || 0,
			recommendedTool: 'betterpptx.deck.validate_design',
		},
		{
			key: 'accessibility',
			ok: requireEveryValidatorPass ? accessibilityValidation.passed === true : true,
			advisoryOk: accessibilityValidation.passed === true,
			blocking: requireEveryValidatorPass ? accessibilityValidation.passed !== true : false,
			score: accessibilityValidation.score,
			findings: accessibilityValidation.findings?.length || 0,
			recommendedTool: 'betterpptx.deck.validate_accessibility',
		},
		{
			key: 'narration',
			ok: narrationValidation.ok === true,
			blocking: true,
			skipped: narrationValidation.skipped === true,
			issues: narrationValidation.issues?.length || 0,
			recommendedTool: 'betterpptx.deck.validate_narration',
		},
		{
			key: 'saved-package',
			ok: savedPackageSafety.ok === true,
			blocking: true,
			skipped: savedPackageSafety.skipped === true,
			issues: savedPackageSafety.issueCount || 0,
			warnings: savedPackageSafety.warningCount || 0,
			recommendedTool: 'betterpptx.deck.save',
		},
	]
	const failed = checks.filter(check => check.blocking && check.ok !== true)
	const firstBlocker = blockingIssues[0]
	// A successful aggregate gate is durable verification for both newly compiled
	// and imported decks. Existing decks run in guided Director mode, but their
	// saved output still needs the same evidence before save.
	if (blockingIssues.length === 0) {
		const verifiedDeckVersion = deckVersion(entry)
		const validationResultSha256 = crypto.createHash('sha256').update(JSON.stringify(stableForHash({
			profile,
			strictness,
			checks: checks.map(check => ({
				key: check.key,
				ok: check.ok === true,
				advisoryOk: check.advisoryOk,
				blocking: check.blocking === true,
				skipped: check.skipped === true,
				score: check.score,
				minScore: check.minScore,
				errors: check.errors,
				warnings: check.warnings,
				issues: check.issues,
				findings: check.findings,
				missingStages: check.missingStages,
			})),
			blockingIssues: blockingIssues.map(issue => ({ code: issue.code, gate: issue.gate, slide: issue.slide, objectHandle: issue.objectHandle })),
			warnings: warnings.map(issue => ({ code: issue.code, gate: issue.gate, slide: issue.slide, objectHandle: issue.objectHandle })),
		}))).digest('hex')
		const previousEvidence = entry.director?.verificationEvidence
		const preserveVerifiedAt = previousEvidence?.schemaVersion === 'betterpptx.current-version-validation.v1' &&
			previousEvidence.deckVersion === verifiedDeckVersion &&
			previousEvidence.validationResultSha256 === validationResultSha256
		const verifiedAt = preserveVerifiedAt && previousEvidence.verifiedAt
			? previousEvidence.verifiedAt
			: new Date().toISOString()
		completeDirectorStage(entry.director, 'verification', {
			profile,
			checks: checks.map(check => ({ key: check.key, ok: check.ok === true, blocking: check.blocking === true })),
		}, {
			source: 'betterpptx.deck.validate_quality',
			verifiedAt,
			deckVersion: verifiedDeckVersion,
		})
		entry.director.verificationEvidence = {
			schemaVersion: 'betterpptx.current-version-validation.v1',
			ok: true,
			profile,
			verifiedAt,
			deckVersion: verifiedDeckVersion,
			validationResultSha256,
			qualityValid: true,
			blockingIssueCount: 0,
			packageValid: packageGatePassed,
			designValidated: true,
			designPassed: designValidation.ok === true,
			designBlockingClear: blockingDesignIssues.length === 0,
			accessibilityValidated: true,
			accessibilityPassed: accessibilityValidation.passed === true,
			narrationValid: narrationValidation.ok === true,
		}
		// `collectDirectorValidation` runs before the aggregate checks so it can
		// contribute planning blockers.  Once those checks pass, verification is
		// completed above; refresh the public status before returning it.  Without
		// this readback refresh a green quality response could still report the
		// stale pre-verification `readyForSave:false` / incomplete verification
		// state to the authoring AI.
		directorValidation = collectDirectorValidation(entry)
	} else {
		// A failed aggregate rerun for this same version must revoke any older
		// passing release proof. Otherwise a stricter or newly failing check could
		// leave a previously previewed package eligible for public save.
		invalidatePublicPreviewFreeze(entry)
		invalidateDirectorVerification(entry, 'betterpptx.deck.validate_quality:failed')
		directorValidation = collectDirectorValidation(entry)
	}
	const verificationPolicy = publicVerificationPolicy()
	const publicPreviewGate = isPublicBlackBoxMode() && verificationPolicy.rendererRequiredForSave ? publicPreviewVerification(entry) : null
	return {
		ok: blockingIssues.length === 0,
		profile,
		strictness,
		checks,
		failed,
		blockingIssues,
		warnings,
		packageValidation,
		directorValidation,
		designValidation,
		accessibilityValidation,
		narrationValidation,
		savedPackageSafety,
		verificationPolicy,
		guidance: publicPresentationQualityGuidance(profile, gradientQualityPolicyForEntry(entry), accentQualityPolicyForEntry(entry), depthQualityPolicyForEntry(entry)),
		next: firstBlocker
			? { recommendedTool: firstBlocker.recommendedTool, reason: firstBlocker.issue }
			: publicPreviewGate && publicPreviewGate.complete !== true
					? { recommendedTool: 'betterpptx.deck.preview', reason: 'No deterministic quality blockers remain; preview every current-version slide until complete is true before release-policy save.' }
					: verificationPolicy.rendererRequiredForSave && warnings.length && !publicPreviewGate
						? { recommendedTool: 'betterpptx.deck.preview', reason: 'No deterministic blockers remain; preview and decide whether to address advisory warnings before release-policy save.' }
					: { recommendedTool: 'betterpptx.deck.save', reason: verificationPolicy.rendererRequiredForSave
						? 'No deterministic quality blockers remain and the current frozen package is fully previewed; publish it with one stable idempotencyKey.'
						: 'No deterministic quality blockers remain; publish with one stable idempotencyKey under the production non-rendering policy. PowerPoint preview is not required for this save.' },
	}
}

function accessibilityFinding({ severity = 'warning', code, slideIndex, objectName = null, issue, whyItMatters, examplePatch }) {
	return {
		severity,
		code,
		slide: slideIndex,
		objectHandle: objectName,
		issue,
		message: issue,
		reason: whyItMatters || issue,
		fix: typeof examplePatch === 'string' && examplePatch.trim()
			? examplePatch
			: 'Apply the semantic accessibility correction and rerun the accessibility gate before saving.',
		evidence: { source: 'accessibility-validation', slide: slideIndex, objectHandle: objectName, code, examplePatch: examplePatch && typeof examplePatch === 'object' ? examplePatch : null },
		whyItMatters,
		recommendedTool: validationRecoveryTool(objectName ? 'betterpptx.slide.revise' : 'betterpptx.deck.revise'),
		examplePatch,
	}
}

function objectTextValue(obj) {
	return previewTextRuns(obj?.text ?? obj?.options?.text ?? '')
}

function isLikelySlideTitle(obj) {
	const opts = obj?.options || {}
	const objectName = String(opts.objectName || '').toLowerCase()
	const text = objectTextValue(obj).trim()
	const fontSize = Number(opts.fontSize || 0)
	const y = Number(opts.y || 0)
	return Boolean(text) && (
		objectName.includes('title') ||
		(fontSize >= 22 && y <= 1.25) ||
		// A prominent display heading (large type) reads as the slide title wherever it sits —
		// a centered cover wordmark or a lower hero headline is still the title.
		fontSize >= 40
	)
}

function hasAltText(obj) {
	const opts = obj?.options || {}
	return Boolean(String(opts.altText || opts.descr || opts.description || '').trim())
}

async function handleValidateAccessibility(args = {}) {
	const entry = getDeck(args.deckId)
	const findings = []
	const slides = entry.pptx.slides || []
	for (let slideIndex = 0; slideIndex < slides.length; slideIndex += 1) {
		const slide = slides[slideIndex]
		const objects = _editableSlideObjects(slide).map(item => item.obj)
		// A slide is titled if the author declared a slide.title (recorded on the slide) OR a
		// title-like object is present (named "title", top-anchored, or a large display heading).
		if (!slide._betterpptxTitle && !objects.some(isLikelySlideTitle)) {
			findings.push(accessibilityFinding({
				code: 'MISSING_SLIDE_TITLE',
				slideIndex,
				issue: 'Slide is missing a clear title object.',
				whyItMatters: 'Screen readers and navigation panes rely on slide titles to identify slide purpose.',
				examplePatch: { target: { objectName: 'slide-title' }, patch: { text: `Slide ${slideIndex + 1} title`, fit: 'shrink' } },
			}))
		}
		for (const obj of objects) {
			const kind = _accessibilityShapeKind(obj)
			const objectName = obj?.options?.objectName || null
			if (!objectName) {
				findings.push(accessibilityFinding({
					code: 'MISSING_READING_ORDER_NAME',
					slideIndex,
					issue: 'Editable object is missing a stable objectName for reading-order targeting.',
					whyItMatters: 'Stable names let an AI client target and repair reading-order or alt-text issues without indexes.',
					examplePatch: { objectName: 'stable-object-name' },
				}))
			}
			if (['image', 'model3d', 'media', 'smartart'].includes(kind) && !hasAltText(obj)) {
				findings.push(accessibilityFinding({
					code: 'MISSING_ALT_TEXT',
					slideIndex,
					objectName,
					issue: `${kind} object is missing alt text.`,
					whyItMatters: 'Non-text visual content needs a text alternative for assistive technology.',
					examplePatch: { style: {}, altText: 'Describe the visual purpose.' },
				}))
			}
			if (['chart', 'table'].includes(kind) && !hasAltText(obj)) {
				findings.push(accessibilityFinding({
					code: 'MISSING_DATA_SUMMARY',
					slideIndex,
					objectName,
					issue: `${kind} object is missing a concise data summary.`,
					whyItMatters: 'Charts and tables need concise summaries so the data story is understandable without visual inspection.',
					examplePatch: { altText: 'Summarize the key data takeaway.' },
				}))
			}
		}
	}
	const errorCount = findings.filter(item => item.severity === 'error').length
	const warningCount = findings.filter(item => item.severity === 'warning').length
	const score = Math.max(0, Math.round(100 - warningCount * 12 - errorCount * 25))
	return {
		ok: true,
		passed: findings.length === 0,
		score,
		checks: ['slide-titles', 'visual-alt-text', 'chart-table-summaries', 'stable-reading-order-names'],
		findings,
		next: findings.length
			? { recommendedTool: validationRecoveryTool('betterpptx.deck.revise'), reason: 'Revise the semantic JSON spec for the accessibility findings, then rerun the accessibility gate before save.' }
			: { recommendedTool: 'betterpptx.deck.validate', reason: 'Run package validation before saving.' },
	}
}

async function validateNarrationPackage(filePath, manifest = null, options = {}) {
	const buf = await fs.readFile(filePath)
	const zip = await JSZip.loadAsync(buf)
	const files = Object.keys(zip.files)
	const issues = []
	const presProps = await zip.file('ppt/presProps.xml')?.async('string') || ''
	const isSilentTimedNotes = entry => entry?.silentTimedNotes === true || entry?.synthesizedAudio === false
	const silentOnlyManifest = Boolean(manifest?.slides?.length) && manifest.slides.every(isSilentTimedNotes)
	const manualOnlyManifest = Boolean(manifest?.slides?.length) && manifest.slides.every(entry => isSilentTimedNotes(entry) || entry?.autoplayEnabled === false)
	for (const [flag, attr] of [['showNarration', 'showNarration="1"'], ['showAnimation', 'showAnimation="1"'], ['useTimings', 'useTimings="1"']]) {
		// A silent-timed-notes artifact is an explicit no-audio variant. It owns
		// speaker notes, authored cues, and optional timing, but deliberately has
		// no narration media or showNarration flag. Do not mistake that contract
		// for a broken narrated package.
		if (silentOnlyManifest && flag === 'showNarration') continue
		if ((silentOnlyManifest || manualOnlyManifest) && flag === 'useTimings' && !manifest.slides.some(entry => Number(entry?.advanceAfterTime) > 0)) continue
		if (!presProps.includes(attr)) issues.push(`ppt/presProps.xml missing ${flag}=1`)
	}
	const vttParts = files.filter(n => /^ppt\/media\/.+\.vtt$/i.test(n))
	let nativeCaptionTrackCount = 0
	let verifiedNativeCaptionTrackCount = 0
	let nativeCaptionCueCount = 0
	let generatedCaptionTextShapeCount = 0
	const mediaParts = files.filter(n => /^ppt\/media\/.+\.(wav|mp3|m4a|aac)$/i.test(n))
	const videoParts = files.filter(n => /^ppt\/media\/.+\.(mp4|mov|webm|m4v)$/i.test(n))
	const mediaRequiredCount = manifest?.slides?.filter(entry => !isSilentTimedNotes(entry)).length || 0
	if (mediaRequiredCount && mediaParts.length < mediaRequiredCount && videoParts.length < mediaRequiredCount) {
		issues.push(`Expected at least ${mediaRequiredCount} narration media parts (audio or video), found ${mediaParts.length + videoParts.length}`)
	}
	const slideEntries = manifest?.slides?.length
		? manifest.slides
		: files.filter(n => /^ppt\/slides\/slide\d+\.xml$/.test(n)).map(n => ({ slideIndex: Number(n.match(/slide(\d+)\.xml$/)[1]) - 1 }))
	if (Number.isInteger(options.expectedSlideCount) && options.expectedSlideCount > 0) {
		const covered = new Set((manifest?.slides || []).filter(entry => !isSilentTimedNotes(entry)).map(entry => Number(entry.slideIndex)))
		for (let index = 0; index < options.expectedSlideCount; index += 1) {
			if (!covered.has(index)) issues.push(`slide ${index + 1}: declared narrated autoplay has no native narration manifest`)
		}
	}
	const perSlide = []
	for (const entry of slideEntries) {
		const slideNum = Number(entry.slideIndex) + 1
		const slidePath = `ppt/slides/slide${slideNum}.xml`
		const relsPath = `ppt/slides/_rels/slide${slideNum}.xml.rels`
		const notesPath = `ppt/notesSlides/notesSlide${slideNum}.xml`
		const xml = await zip.file(slidePath)?.async('string') || ''
		const rels = await zip.file(relsPath)?.async('string') || ''
		const notes = await zip.file(notesPath)?.async('string') || ''
		const slideIssues = []
		if (isSilentTimedNotes(entry)) {
			if (entry.preserveInNotes !== false && !notes) slideIssues.push('missing authored narration notes')
			perSlide.push({
				slideIndex: entry.slideIndex,
				silentTimedNotes: true,
				hasNotes: Boolean(notes),
				advanceAfterTime: null,
				startDelayMs: narrationMs(entry.startDelayMs),
				expectedDurationMs: narrationMs(entry.expectedDurationMs) || null,
				durationDriftMs: 0,
				timingToleranceMs: narrationTimingToleranceMs(entry.timingToleranceMs, narrationMs(entry.expectedDurationMs)),
				audioEndMs: 0,
				cueTimelineEndMs: narrationMs(entry.cueTimelineEndMs),
				captionTimelineEndMs: narrationMs(entry.captionTimelineEndMs),
				timelineEndMs: narrationMs(entry.timelineEndMs),
				requiredAdvanceMs: narrationMs(entry.advanceAfterTime),
				issues: slideIssues,
			})
			if (slideIssues.length) issues.push(`slide ${slideNum}: ${slideIssues.join('; ')}`)
			continue
		}
		const audioNodeCount = (xml.match(/<p:audio\b/g) || []).length
		const videoNodeCount = (xml.match(/<p:video\b/g) || []).length
		const hasAudioNode = audioNodeCount > 0 && /<p:cMediaNode\b/.test(xml)
		const hasVideoNode = /<p:video\b/.test(xml) && /<p:cMediaNode\b/.test(xml)
		const hasNativeNarration = /<p:audio\b[^>]*\bisNarration="1"/.test(xml)
		const hasShowWhenStoppedFalse = /<p:cMediaNode\b[^>]*\bshowWhenStopped="0"/.test(xml)
		const hasEndOnStopAudio = /\bevt="onStopAudio"/.test(xml)
		const hasMediaCall = /presetClass="mediacall"/.test(xml) && /cmd="playFrom\(0\.0\)"/.test(xml)
		const adv = Number((xml.match(/\badvTm="(\d+)"/) || [])[1] || 0)
		const hasAdvClick0 = /\badvClick="0"/.test(xml)
		const hasAudioRel = /relationships\/(?:audio|media|video)"/.test(rels) || /Type="[^"]+\/relationships\/(?:audio|media|video)"/.test(rels)
		const hasVideoNarration = hasVideoNode && /relationships\/(?:video|media)"/.test(rels)
		const isVideoNarrationReplacement = !hasAudioNode && hasVideoNarration
		if (!hasAudioNode && !hasVideoNarration) slideIssues.push('missing p:audio/p:video cMediaNode')
		if (!hasNativeNarration && !hasVideoNarration) slideIssues.push('missing native narration media marker')
		if (!isVideoNarrationReplacement && !hasShowWhenStoppedFalse) slideIssues.push('missing native narration showWhenStopped="0"')
		if (!isVideoNarrationReplacement && !hasEndOnStopAudio) slideIssues.push('missing native narration onStopAudio end condition')
		if (!hasMediaCall) slideIssues.push('missing mediacall playFrom(0.0)')
		if (!hasAudioRel) slideIssues.push('missing audio/media slide relationship')
		if (isVideoNarrationReplacement && !hasAdvClick0) slideIssues.push('missing advClick="0"')
		const manualAdvance = entry?.autoplayEnabled === false
		if (!manualAdvance && !adv) slideIssues.push('missing advTm')
		if (options.requireAutoAdvance === true && !hasAdvClick0) slideIssues.push('declared narrated autoplay requires advClick="0"')
		if (adv && adv < 1000) slideIssues.push(`advTm too small (${adv})`)
		if (Number(entry?.segmentCount || 0) > 1 && audioNodeCount < Number(entry.segmentCount)) {
			slideIssues.push(`expected ${entry.segmentCount} narration audio nodes, found ${audioNodeCount}`)
		}
		const startDelayMs = narrationMs(entry.startDelayMs)
		const durationMs = narrationMs(entry.durationMs)
		const expectedDurationMs = narrationMs(entry.expectedDurationMs)
		const timingToleranceMs = narrationTimingToleranceMs(entry.timingToleranceMs, expectedDurationMs)
		const durationDriftMs = expectedDurationMs ? Math.abs(durationMs - expectedDurationMs) : narrationMs(entry.durationDriftMs)
		const audioEndMs = narrationMs(entry.audioEndMs, startDelayMs + durationMs)
		const timelineEndMs = narrationMs(entry.timelineEndMs, Math.max(audioEndMs, narrationMs(entry.cueTimelineEndMs), narrationMs(entry.captionTimelineEndMs)))
		const paddingMs = narrationMs(entry.paddingMs)
		const requiredAdvanceMs = Math.max(
			startDelayMs + durationMs,
			audioEndMs,
			timelineEndMs,
			timelineEndMs + paddingMs,
			narrationMs(entry.advanceAfterTime)
		)
		if (durationMs && adv && adv < startDelayMs + durationMs) slideIssues.push(`advTm ${adv} is shorter than narration end ${startDelayMs + durationMs}`)
		if (timelineEndMs && adv && adv < timelineEndMs) slideIssues.push(`advTm ${adv} is shorter than narration animation timeline ${timelineEndMs}`)
		if (requiredAdvanceMs && adv && adv < requiredAdvanceMs) slideIssues.push(`advTm ${adv} is shorter than required narrated slide duration ${requiredAdvanceMs}`)
		if (expectedDurationMs && durationDriftMs > timingToleranceMs) slideIssues.push(`resolved narration duration drift ${durationDriftMs}ms exceeds tolerance ${timingToleranceMs}ms`)
		if (Number(entry.requestedCues || 0) > Number(entry.cues || 0)) slideIssues.push(`only ${entry.cues || 0} of ${entry.requestedCues} authored cue target(s) were applied`)
		const hasCaptionTextShape = /narration-caption-/i.test(xml)
		const captionEvidence = await inspectNativeCaptionTracks(zip, entry.slideIndex, entry)
		nativeCaptionTrackCount += captionEvidence.trackCount
		verifiedNativeCaptionTrackCount += captionEvidence.verifiedTrackCount
		nativeCaptionCueCount += captionEvidence.cueCount
		slideIssues.push(...captionEvidence.issues)
		const effectiveCaptionEndMs = captionEvidence.captionTimelineEndMs || 0
		const effectiveTimelineEndMs = Math.max(timelineEndMs, effectiveCaptionEndMs)
		const effectiveRequiredAdvanceMs = Math.max(requiredAdvanceMs, effectiveCaptionEndMs + paddingMs)
		if (effectiveCaptionEndMs && adv && adv < effectiveRequiredAdvanceMs) {
			slideIssues.push(`advTm ${adv} is shorter than the native WebVTT cue timeline plus padding ${effectiveRequiredAdvanceMs}`)
		}
		if (hasCaptionTextShape) generatedCaptionTextShapeCount += 1
		if (slideIssues.length) issues.push(`slide ${slideNum}: ${slideIssues.join('; ')}`)
		perSlide.push({
			slideIndex: entry.slideIndex,
			audioNodeCount,
			videoNodeCount,
			hasAudioNode,
			hasVideoNode,
			hasNativeNarration,
			hasVideoNarration,
			isVideoNarrationReplacement,
			hasShowWhenStoppedFalse,
			hasEndOnStopAudio,
			hasMediaCall,
			hasAudioRel,
			hasNotes: Boolean(notes),
			advanceAfterTime: adv || null,
			startDelayMs,
			expectedDurationMs: expectedDurationMs || null,
			durationDriftMs,
			timingToleranceMs,
			audioEndMs,
			cueTimelineEndMs: narrationMs(entry.cueTimelineEndMs),
			captionTimelineEndMs: captionEvidence.trackCount ? captionEvidence.captionTimelineEndMs : narrationMs(entry.captionTimelineEndMs),
			captionTimingSource: captionEvidence.captionTimingSource,
			nativeCaptionTrackCount: captionEvidence.trackCount,
			verifiedNativeCaptionTrackCount: captionEvidence.verifiedTrackCount,
			nativeCaptionCueCount: captionEvidence.cueCount,
			captionTracks: captionEvidence.tracks,
			timelineEndMs: effectiveTimelineEndMs,
			requiredAdvanceMs: effectiveRequiredAdvanceMs,
			issues: slideIssues,
		})
	}
	return {
		ok: issues.length === 0,
		filePath,
		mediaParts,
		vttPartCount: vttParts.length,
		nativeCaptionTrackCount,
		verifiedNativeCaptionTrackCount,
		nativeCaptionCueCount,
		generatedCaptionTextShapeCount,
		nativeCaptionTracks: nativeCaptionTrackCount,
		nonNativeCaptionObjectsGenerated: generatedCaptionTextShapeCount,
		perSlide,
		issues,
	}
}

async function handleValidateNarration(args) {
	const entry = getDeck(args.deckId)
	const { pptx } = entry
	let filePath = args.filePath || entry.lastSavedPath
	let temporary = false
	if (!filePath) {
		const dir = path.resolve(process.env.BETTERPPTX_OUT_DIR || path.join(process.cwd(), 'outputs', 'narration-validation'))
		await fs.mkdir(dir, { recursive: true })
		filePath = path.join(dir, `validate-narration-${args.deckId}-${Date.now().toString(36)}.pptx`)
		ensureBetterPptxMetadata(pptx)
		await pptx.writeFile({ fileName: filePath, compression: args.compression !== false })
		temporary = true
	}
	const narratedAutoplay = entry.deliveryExperience?.mode === 'narrated-autoplay'
	const result = await validateNarrationPackage(filePath, entry.narrationManifest, narratedAutoplay
		? { expectedSlideCount: pptx.slides.length, requireAutoAdvance: true }
		: {})
	const inspectedPackageSha256 = temporary ? null : sha256Buffer(await fs.readFile(filePath))
	logEvent('narration.validate.result', {
		deckId: args.deckId,
		filePath,
		temporary,
		ok: result.ok,
		issues: result.issues,
	})
	const publicResult = isPublicBlackBoxMode() ? { ...result, filePath: undefined } : result
	if (publicResult.filePath === undefined) delete publicResult.filePath
	const manifest = entry.narrationManifest || null
	const visibleManifest = isPublicBlackBoxMode() ? publicNarrationManifest(manifest) : manifest
	const evidenceBySlide = new Map(result.perSlide.map(slide => [Number(slide.slideIndex), slide]))
	const projectedManifest = visibleManifest ? {
		...visibleManifest,
		slides: (visibleManifest.slides || []).map(slide => {
			const evidence = evidenceBySlide.get(Number(slide.slideIndex))
			return evidence?.nativeCaptionTrackCount
				? { ...slide, captionTimelineEndMs: evidence.captionTimelineEndMs, captionTimingSource: evidence.captionTimingSource, nativeCaptionTrackCount: evidence.nativeCaptionTrackCount }
				: slide
		}),
	} : null
	return {
		...publicResult,
		temporary,
		validationSource: temporary ? 'current-source-temporary-package' : 'saved-publication-package',
		...(inspectedPackageSha256 ? { packageSha256: inspectedPackageSha256 } : {}),
		manifest: projectedManifest,
	}
}

async function handleValidateAvatarNarration(args) {
	const entry = getDeck(args.deckId)
	const { pptx } = entry
	let filePath = args.filePath || entry.lastSavedPath
	let temporary = false
	if (!filePath) {
		const dir = path.resolve(process.env.BETTERPPTX_OUT_DIR || path.join(process.cwd(), 'outputs', 'avatar-validation'))
		await fs.mkdir(dir, { recursive: true })
		filePath = path.join(dir, `validate-avatar-narration-${args.deckId}-${Date.now().toString(36)}.pptx`)
		ensureBetterPptxMetadata(pptx)
		await pptx.writeFile({ fileName: filePath, compression: args.compression !== false })
		temporary = true
	}
	const structural = await validateAvatarNarrationPackage(filePath, entry.avatarManifest)
	const mediaInspection = await inspectAvatarMediaInPackage(filePath, entry.avatarManifest)
	const result = {
		...structural,
		ok: structural.ok === true && mediaInspection.ok === true,
		mediaInspection,
	}
	logEvent('avatar.validate.result', {
		deckId: args.deckId,
		filePath,
		temporary,
		ok: result.ok,
		issues: result.issues,
		mediaInspection: result.mediaInspection,
	})
	const publicResult = isPublicBlackBoxMode() ? { ...result, filePath: undefined } : result
	if (publicResult.filePath === undefined) delete publicResult.filePath
	const manifest = entry.avatarManifest || null
	const publicManifest = isPublicBlackBoxMode() ? publicAvatarManifest(manifest) : manifest
	return { ...publicResult, temporary, manifest: publicManifest }
}

// ---- Download publishing (remote transports) --------------------------------
// When the server runs behind a public HTTPS endpoint (e.g. cloudflared), saved
// files live on the SERVER, unreachable by a remote web client (ChatGPT /
// claude.ai). If a public base + served root are configured, save writes the
// deck DIRECTLY into the served root behind an unguessable token (one write, no
// copy) and returns a public `downloadUrl`. The artifact store is DISK, not RAM:
// generation is transient, the file is streamed on GET, and old/over-budget
// files are evicted — so the resident memory footprint never depends on how many
// files are awaiting download. Generic + transport-agnostic.
let _downloadBase = (process.env.BETTERPPTX_PUBLIC_BASE || '').replace(/\/+$/, '')
let _downloadRoot = process.env.BETTERPPTX_DOWNLOAD_ROOT ? path.resolve(process.env.BETTERPPTX_DOWNLOAD_ROOT) : ''
const DOWNLOAD_BUDGET_BYTES = Number(process.env.BETTERPPTX_DOWNLOAD_BUDGET_MB || 2048) * 1048576
let _artifactStore = createArtifactStore({ base: _downloadBase, root: _downloadRoot, budgetBytes: DOWNLOAD_BUDGET_BYTES })
const _deckStateStore = createDeckStateStore()
const _deckSnapshotStore = createDeckSnapshotStore()
const _lockedAssetStore = createLockedAssetStore()
const _operationStore = createOperationStore()
const _operationDispatcher = createOperationDispatcher()
// Maintainer-owned startup composition; never a public tool or context option.
// Product startup supplies only the private trusted registry. The worker and
// cache are composed here from the engine's existing lease, grant and asset
// stores so callers cannot substitute an unowned cache or output producer.
export function configureMotionPreparationRuntime(configuration = {}) {
	if (configuration?.testOnly === true) {
		const { testOnly, ...dependencies } = configuration
		configureMotionPreparationService({ ...dependencies, store: _operationStore, dispatcher: _operationDispatcher })
		return
	}
	const catalogWidthEnvironment = process.env.BETTERPPTX_MOTION_CATALOG_METADATA_CONCURRENCY
	const catalogMetadataConcurrency = configuration?.catalogMetadataConcurrency !== undefined ? configuration.catalogMetadataConcurrency
		: catalogWidthEnvironment === undefined ? undefined : (/^([1-9]|[1-5][0-9]|6[0-4])$/.test(catalogWidthEnvironment) ? Number(catalogWidthEnvironment) : NaN)
	if (!configuration || Object.keys(configuration).some(key => !['trustedRepository', 'deliverPreparedFiles', 'catalogMetadataConcurrency'].includes(key)) || !configuration.trustedRepository
		|| (configuration.deliverPreparedFiles !== undefined && typeof configuration.deliverPreparedFiles !== 'boolean')
		|| (catalogMetadataConcurrency !== undefined && (!Number.isSafeInteger(catalogMetadataConcurrency) || catalogMetadataConcurrency < 1 || catalogMetadataConcurrency > 64 || (typeof configuration.trustedRepository.resolvePreparationInputs !== 'function' && catalogMetadataConcurrency > 8)))) {
		throw new TypeError('A private trusted motion-preparation registry is required.')
	}
	const cache = createGeneratedMotionPreparationCache({
		currentResourceOwner,
		assetGrants,
		getCached: hash => getCachedGeneratedRigged3d(hash),
		getStaged: hash => getCachedGeneratedRigged3dUnchecked(hash),
		hydrate: hash => hydratePreparedNativeAsset({
			hash, owner: currentResourceOwner(), currentOwner: currentResourceOwner, assetGrants,
			load: loadPersistedGeneratedRigged3d, bundleBytes: generatedRigged3dBytes,
			cache: (key, entry) => {
				cacheGeneratedRigged3d({ ...entry, promptHash: key })
				return getCachedGeneratedRigged3d(key)
			},
		}),
		registerLocal: input => registerLocalRigged3d(input),
		persist: (hash, tenant) => persistGeneratedRigged3d(hash, tenant),
		bundleBytes: entry => generatedRigged3dBytes(entry),
		produceOutput: async ({ operation, handle, bytes }) => {
			const result = await assetGrants.produce({ operation, source: 'owned-derivation', requireReady: true }, receipt => {
				receipt.capture(handle, bytes)
				return { ok: true }
			})
			return result?.ok === true
		},
	})
	const runtime = createMotionPreparationRuntime({ trustedRepository: configuration.trustedRepository, cache, catalogMetadataConcurrency })
	const deliverPreparedArtifact = configuration.deliverPreparedFiles === false ? undefined
		: createMotionPreparedFileDelivery({ cache, artifactStore: _artifactStore, currentResourceOwner, writeBytes: (target, bytes) => fs.writeFile(target, bytes) })
	const resolvePreparedModelAsset = async ({ prepared, plan, owner, assertLease }) => {
		await assertLease()
		const modelAsset = await cache.readVerifiedModelAsset({ prepared, plan, owner })
		await assertLease()
		return modelAsset
	}
	configureMotionPreparationService({ ...runtime.dependencies, deliverPreparedArtifact, resolvePreparedModelAsset, store: _operationStore, dispatcher: _operationDispatcher,
		captureRequestContinuation: (context, inputDigest, args) => {
			if (!mcpAuthoringAuthorized(context)) { const error = new Error('The preparation request context is unavailable.'); error.code = 'OPERATION_REQUEST_INVALID'; throw error }
			return captureQueuedMcpContinuation(context, inputDigest, idempotencyArgsHash(cloneForResult(args)))
		},
	})
}
export function setDownloadConfig({ base, root } = {}) {
	if (base !== undefined) _downloadBase = String(base || '').replace(/\/+$/, '')
	if (root !== undefined) _downloadRoot = root ? path.resolve(root) : ''
	_artifactStore.configure({ base: _downloadBase, root: _downloadRoot })
	logEvent('engine.download_config', { ..._artifactStore.describe() })
	return _artifactStore.describe()
}
export function getDownloadConfig() { return _artifactStore.describe() }

const PUBLIC_OUTPUT_SHAPE_MIN_SLIDES = Math.max(4, Number(process.env.BETTERPPTX_PUBLIC_OUTPUT_SHAPE_MIN_SLIDES || 5))
const PUBLIC_OUTPUT_FEATURE_SURFACE_RE = /\b(?:animations?|transitions?|effects?|motion paths?|smart\s*art|smartart|word\s*art|wordart|equations?|chart\s+types?|table\s+styles?|shape\s+types?|layout\s+presets?|presets?|variants?|enums?)\b/i
const PUBLIC_OUTPUT_FEATURE_ID_RE = /\b(?:anim(?:ation)?|trans(?:ition)?|smart\s*art|smartart|word\s*art|wordart|effect|motion\s*path|preset|layout|shape|chart|table|feature|option|enum|fixture|specimen|case)\s*(?::|#|\b(?:id|type|name|effect|preset|layout|variant|sample|case|style|option|enum|fixture|specimen)\b)\s*[a-z0-9][a-z0-9_.-]*|\b(?:anim(?:ation)?|trans(?:ition)?|smart\s*art|smartart|word\s*art|wordart|effect|motion\s*path|preset|layout|shape|chart|table|feature|option|enum|fixture|specimen|case)\s*[-_]\s*(?:id|type|name|effect|preset|layout|variant|sample|case|style|option|enum|fixture|specimen|v?\d+|[a-z]?\d{1,4})\b/i
const PUBLIC_OUTPUT_NUMBERED_FEATURE_RE = /\b(?:feature|case|specimen|fixture)\s*#?\s*\d+\b/i
const PUBLIC_OUTPUT_INTERNAL_LABEL_RE = /\b(?:ooxml|drawingml|raw\s+xml|xml\s+part|r:id|rid\d+|spid|cnvpr|txbody|graphicframe|p14|p15|p16|decypher|comparator|parity|frozen\s+reference|capability\s+ledger|option\s+registry|preset\s+id|source\s+path|filesystem|package\s+relationship)\b/i
const PUBLIC_OUTPUT_CATALOG_PHRASE_RE = /\b(?:all|complete|full|exhaustive|systematic|matrix|catalog|gallery|inventory|coverage|reference|sample\s+deck|test\s+deck|fixture\s+deck)\b.{0,80}\b(?:animations?|transitions?|effects?|motion paths?|smart\s*art|word\s*art|equations?|chart\s+types?|table\s+styles?|shape\s+types?|layout\s+presets?|presets?|variants?|enums?)\b|\b(?:animations?|transitions?|effects?|motion paths?|smart\s*art|word\s*art|equations?|chart\s+types?|table\s+styles?|shape\s+types?|layout\s+presets?|presets?|variants?|enums?)\b.{0,80}\b(?:catalog|matrix|gallery|inventory|coverage|reference|all|complete|full|exhaustive|systematic)\b/i
const PUBLIC_OUTPUT_ANIMATION_LABEL_RE = /\b(?:animation|animations|effect|effects|motion\s*path|motion\s*paths)\b/i
const PUBLIC_OUTPUT_TRANSITION_LABEL_RE = /\btransitions?\b/i

function _publicOutputLabel(value) {
	if (value == null) return ''
	return String(value).replace(/\s+/g, ' ').trim()
}

function _publicOutputGeneratedObjectName(value) {
	const s = _publicOutputLabel(value)
	if (!s) return false
	return /^(?:html|svg)(?:[-_ ](?:source|lowered|generated))?[-_ ](?:text|shape|image|picture|line|ellipse|rect|rectangle|path|group|vector|background|decorative)(?:[-_ ]|$)/i.test(s)
		|| /^slide[-_. ]?\d+[-_. ](?:background|text|shape|image|picture|line|ellipse|rect|rectangle|path|group|vector|custom[-_. ]geometry|native[-_. ]effect)(?:[-_. ]|$)/i.test(s)
		|| /^(?:native[-_. ]background|native[-_. ]effect[-_. ]support)(?:[-_. ]|$)/i.test(s)
}

function _publicOutputObjectKind(obj) {
	return String(obj?.type || obj?._type || obj?.shape || '').toLowerCase()
}

function _publicOutputSlideObjects(slide) {
	return (slide?._slideObjects || []).filter(obj => _publicOutputObjectKind(obj) !== 'notes')
}

function _publicOutputObjectLabels(obj) {
	const labels = []
	const add = value => {
		const s = _publicOutputLabel(value)
		if (s) labels.push(s)
	}
	const addObjectName = value => {
		const s = _publicOutputLabel(value)
		if (s && !_publicOutputGeneratedObjectName(s)) labels.push(s)
	}
	if (typeof obj?.text === 'string') add(obj.text)
	else if (Array.isArray(obj?.text)) {
		for (const run of obj.text) {
			if (typeof run === 'string') add(run)
			else {
				add(run?.text)
				addObjectName(run?.options?.objectName)
				add(run?.options?.altText)
				add(run?.options?.title)
			}
		}
	}
	addObjectName(obj?.options?.objectName)
	add(obj?.options?.altText)
	add(obj?.options?.title)
	addObjectName(obj?.options?.name)
	addObjectName(obj?.objectName)
	addObjectName(obj?.name)
	return [...new Set(labels)].slice(0, 24)
}

function _publicOutputCoordBucket(value) {
	const n = Number(value)
	return Number.isFinite(n) ? Math.round(n * 4) / 4 : null
}

function _publicOutputGridLike(objects, featureLabelCount) {
	if (objects.length < 12 || featureLabelCount < 6) return false
	const xs = new Set()
	const ys = new Set()
	for (const obj of objects) {
		const x = _publicOutputCoordBucket(obj?.options?.x)
		const y = _publicOutputCoordBucket(obj?.options?.y)
		if (x != null) xs.add(x)
		if (y != null) ys.add(y)
	}
	return xs.size >= 3 && ys.size >= 3
}

function _publicOutputFeatureBucket(label) {
	const s = _publicOutputLabel(label).toLowerCase()
	const m = s.match(/\b(animation|transition|effect|motion\s*path|smart\s*art|smartart|word\s*art|wordart|equation|chart|table|shape|preset|layout|feature|option|variant|enum|fixture|specimen|case)\b/)
	return m ? m[1].replace(/\s+/g, '') : null
}

function _publicOutputTransitionType(transition) {
	if (!transition) return null
	if (typeof transition === 'string') return transition.toLowerCase()
	const value = transition.type || transition.name || transition.transition || transition.prst
	return value ? String(value).toLowerCase() : null
}

function _publicOutputAnimationEffects(slide) {
	const out = []
	for (const item of slide?._animations || []) {
		const animation = item?.animation || item
		const effect = animation?.effect || animation?.preset || animation?.type
		if (effect) out.push(String(effect).toLowerCase())
	}
	return out
}

function evaluatePublicOutputShapeGate(entry) {
	if (!isPublicBlackBoxMode()) return { ok: true }
	if (['existing', 'uploaded', 'spec-roundtrip'].includes(String(entry?.sourceType || '')) || entry?.roundtripSpecTrusted === true) return { ok: true }
	const pptx = entry?.pptx
	const slides = Array.isArray(pptx?.slides) ? pptx.slides : []
	const slideCount = slides.length
	if (slideCount === 0) return { ok: true }

	const transitionTypes = new Set()
	const animationEffects = new Set()
	const featureBuckets = new Map()
	const perSlide = slides.map((slide, index) => {
		const objects = _publicOutputSlideObjects(slide)
		const labels = objects.flatMap(_publicOutputObjectLabels)
		const haystack = labels.join(' | ')
		const featureSurfaceHits = labels.filter(label => PUBLIC_OUTPUT_FEATURE_SURFACE_RE.test(label)).length
		const featureIdHits = labels.filter(label => PUBLIC_OUTPUT_FEATURE_ID_RE.test(label) || PUBLIC_OUTPUT_NUMBERED_FEATURE_RE.test(label)).length
		const internalHits = labels.filter(label => PUBLIC_OUTPUT_INTERNAL_LABEL_RE.test(label)).length
		const catalogPhrase = PUBLIC_OUTPUT_CATALOG_PHRASE_RE.test(haystack)
		const animationLabel = labels.some(label => PUBLIC_OUTPUT_ANIMATION_LABEL_RE.test(label))
		const transitionLabel = labels.some(label => PUBLIC_OUTPUT_TRANSITION_LABEL_RE.test(label))
		for (const label of labels) {
			const bucket = _publicOutputFeatureBucket(label)
			if (bucket) featureBuckets.set(bucket, (featureBuckets.get(bucket) || 0) + 1)
		}
		const transitionType = _publicOutputTransitionType(slide.transition)
		if (transitionType) transitionTypes.add(transitionType)
		const effects = _publicOutputAnimationEffects(slide)
		for (const effect of effects) animationEffects.add(effect)
		return {
			index,
			objectCount: objects.length,
			labelCount: labels.length,
			featureSurfaceHits,
			featureIdHits,
			internalHits,
			catalogPhrase,
			animationLabel,
			transitionLabel,
			animationEffectCount: effects.length,
			gridLike: _publicOutputGridLike(objects, featureSurfaceHits),
			oneFeatureLike: objects.length <= 3 && (featureIdHits > 0 || internalHits > 0 || catalogPhrase),
		}
	})

	const oneFeatureSlides = perSlide.filter(s => s.oneFeatureLike).length
	const gridSlides = perSlide.filter(s => s.gridLike).length
	const catalogPhraseSlides = perSlide.filter(s => s.catalogPhrase).length
	const featureLabelSlides = perSlide.filter(s => s.featureSurfaceHits > 0 || s.featureIdHits > 0).length
	const internalLabelSlides = perSlide.filter(s => s.internalHits > 0).length
	const featureSurfaceTotal = perSlide.reduce((sum, s) => sum + s.featureSurfaceHits, 0)
	const animationLabelSlides = perSlide.filter(s => s.animationLabel && (s.featureIdHits > 0 || s.animationEffectCount > 0 || s.catalogPhrase)).length
	const transitionLabelSlides = perSlide.filter(s => s.transitionLabel && (s.featureIdHits > 0 || s.catalogPhrase)).length
	const featureIdTotal = perSlide.reduce((sum, s) => sum + s.featureIdHits, 0)
	const internalHitTotal = perSlide.reduce((sum, s) => sum + s.internalHits, 0)
	const repeatedFeatureBuckets = [...featureBuckets.values()].filter(count => count >= Math.max(3, Math.ceil(slideCount * 0.35))).length

	const reasons = []
	const majoritySlides = Math.max(4, Math.ceil(slideCount * 0.6))
	if (slideCount >= PUBLIC_OUTPUT_SHAPE_MIN_SLIDES && oneFeatureSlides >= majoritySlides) {
		reasons.push('Deck resembles a feature-by-feature reference inventory.')
	}
	if (gridSlides > 0 && (featureIdTotal >= 4 || catalogPhraseSlides > 0 || internalHitTotal > 0)) {
		reasons.push('Deck contains a systematic grid or matrix of presentation effects.')
	}
	if (catalogPhraseSlides > 0 && (featureIdTotal >= 4 || oneFeatureSlides >= 3 || gridSlides > 0)) {
		reasons.push('Deck is shaped like a capability catalog or extraction reference.')
	}
	if (transitionTypes.size >= 5 && transitionLabelSlides >= Math.max(4, Math.ceil(slideCount * 0.5))) {
		reasons.push('Deck systematically enumerates transition behavior.')
	}
	if (animationEffects.size >= 6 && animationLabelSlides >= Math.max(4, Math.ceil(slideCount * 0.5))) {
		reasons.push('Deck systematically enumerates animation behavior.')
	}
	if (internalHitTotal >= 3 && internalLabelSlides >= 3) {
		reasons.push('Deck includes repeated implementation-oriented labels.')
	}
	if (repeatedFeatureBuckets >= 3 && featureLabelSlides >= majoritySlides && featureIdTotal >= 4) {
		reasons.push('Deck repeats internal-style feature labels across many slides.')
	}

	return {
		ok: reasons.length === 0,
		reasons,
		metrics: {
			slideCount,
			oneFeatureSlides,
			gridSlides,
			catalogPhraseSlides,
			featureSurfaceTotal,
			featureLabelSlides,
			internalLabelSlides,
			transitionTypeCount: transitionTypes.size,
			animationEffectCount: animationEffects.size,
			repeatedFeatureBuckets,
		},
	}
}

function assertPublicOutputShapeAllowed(entry) {
	const gate = evaluatePublicOutputShapeGate(entry)
	if (gate.ok) return
	logEvent('deck.save.public_output_shape_blocked', {
		reasons: gate.reasons,
		metrics: gate.metrics,
	})
	const err = new Error('Save blocked because this deck looks like a generated capability inventory rather than a user-facing presentation.')
	err.code = 'PUBLIC_OUTPUT_SHAPE_LIMIT'
	err.details = {
		status: 'blocked',
		artifactStatus: 'not_saved',
		qualityGate: { success: false, failed: ['publicOutputShape'] },
		reasons: gate.reasons,
		recommendation: 'Create a user-facing deck focused on a topic, audience, and story instead of an exhaustive feature catalog or extraction reference.',
	}
	throw err
}

function normalizeDeckSaveOutputFormat(args = {}) {
	const explicit = String(args.outputFormat || args.format || '').trim().toLowerCase()
	if (explicit) {
		if (['pptx', 'potx', 'thmx'].includes(explicit)) return explicit
		const err = new Error('deck.save outputFormat must be "pptx", "potx", or "thmx".')
		err.code = 'INVALID_OUTPUT_FORMAT'
		err.details = { supported: ['pptx', 'potx', 'thmx'] }
		throw err
	}
	const ext = path.extname(String(args.fileName || '')).toLowerCase()
	if (ext === '.potx') return 'potx'
	if (ext === '.thmx') return 'thmx'
	return 'pptx'
}

function makeThemeExportUnavailableError() {
	const err = new Error('Theme package export is unavailable on this endpoint. Save as pptx or potx, or use an endpoint with theme export enabled.')
	err.code = 'THEME_EXPORT_UNAVAILABLE'
	err.details = {
		status: 'failed',
		artifactStatus: 'not_saved',
		outputFormat: 'thmx',
		supportedFallbacks: ['pptx', 'potx'],
	}
	return err
}

const THEME_EXPORT_PS = `
param(
	[Parameter(Mandatory=$true)][string]$InputPath,
	[Parameter(Mandatory=$true)][string]$OutputPath
)
$ErrorActionPreference = 'Stop'
$powerPoint = $null
$presentation = $null
try {
	$powerPoint = New-Object -ComObject PowerPoint.Application
	$presentation = $powerPoint.Presentations.Open($InputPath, $true, $false, $false)
	if (Test-Path -LiteralPath $OutputPath) { Remove-Item -LiteralPath $OutputPath -Force }
	$presentation.SaveAs($OutputPath, 31)
	$presentation.Close()
	$presentation = $null
	$powerPoint.Quit()
	$powerPoint = $null
	if (!(Test-Path -LiteralPath $OutputPath)) { throw 'Theme export did not produce an output file.' }
	$item = Get-Item -LiteralPath $OutputPath
	if ($item.Length -lt 1024) { throw 'Theme export output is unexpectedly small.' }
	'OK'
}
finally {
	if ($presentation -ne $null) {
		try { $presentation.Close() } catch {}
		try { [void][Runtime.InteropServices.Marshal]::ReleaseComObject($presentation) } catch {}
	}
	if ($powerPoint -ne $null) {
		try { $powerPoint.Quit() } catch {}
		try { [void][Runtime.InteropServices.Marshal]::ReleaseComObject($powerPoint) } catch {}
	}
	[GC]::Collect()
	[GC]::WaitForPendingFinalizers()
}
`

async function exportThemePackageViaOffice(pptx, target, args = {}) {
	if (process.platform !== 'win32') throw makeThemeExportUnavailableError()
	const tempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'betterpptx-theme-'))
	const sourcePptx = path.join(tempDir, 'source.pptx')
	const scriptPath = path.join(tempDir, 'export-theme.ps1')
	try {
		await pptx.writeFile({ fileName: sourcePptx, compression: args.compression !== false })
		await fs.writeFile(scriptPath, THEME_EXPORT_PS, 'utf8')
		try {
			execFileSync('powershell.exe', [
				'-NoProfile',
				'-ExecutionPolicy',
				'Bypass',
				'-File',
				scriptPath,
				'-InputPath',
				sourcePptx,
				'-OutputPath',
				target,
			], {
				windowsHide: true,
				encoding: 'utf8',
				maxBuffer: 1024 * 1024,
				timeout: Math.max(10_000, Number(process.env.BETTERPPTX_THMX_EXPORT_TIMEOUT_MS || 120_000) || 120_000),
			})
		} catch (err) {
			logEvent('deck.save.theme_export_failed', {
				code: err?.code || null,
				status: err?.status || null,
				message: err?.message || String(err),
			})
			throw makeThemeExportUnavailableError()
		}
	} finally {
		try { await fs.rm(tempDir, { recursive: true, force: true }) } catch {}
	}
}

function assertPublicSaveIdempotencyKey(args = {}) {
	if (!isPublicBlackBoxMode()) return
	if (getIdempotencyKey(args)) return
	const err = new Error('Public deck.save requires a stable idempotencyKey. Retry the same logical save with the same key and identical arguments.')
	err.code = 'IDEMPOTENCY_KEY_REQUIRED'
	err.details = {
		status: 'idempotency_key_required',
		artifactStatus: 'not_saved',
		recommendation: 'Choose one stable retry key for this logical save and reuse it unchanged for every retry.',
	}
	throw err
}

function requireCompletePublicPreview(entry, outputFormat, args = {}) {
	if (!isPublicBlackBoxMode()) return null
	const verificationPolicy = publicVerificationPolicy()
	const validationVerification = currentVersionValidationVerification(entry)
	if (validationVerification.complete !== true) throwCurrentVersionValidationRequired(entry)
	if (outputFormat !== 'pptx') {
		const err = new Error('Public save publishes a PPTX artifact under the deployment-selected verification policy; outputFormat must be "pptx".')
		err.code = 'PUBLIC_SAVE_OUTPUT_FORMAT_REQUIRED'
		err.details = { status: 'not_saved', artifactStatus: 'not_saved', outputFormat, supported: ['pptx'] }
		throw err
	}
	if (!verificationPolicy.rendererRequiredForSave) return null
	const freeze = currentPublicPreviewFreeze(entry)
	const verification = publicPreviewVerification(entry, freeze)
	if (!freeze) {
		const err = new Error('Public deck.save requires PowerPoint preview of every slide for the current deck version before the first save.')
		err.code = 'PREVIEW_REQUIRED'
		err.details = {
			status: 'preview_required',
			artifactStatus: 'not_saved',
			previewVerification: verification,
			nextAction: { recommendedTool: 'betterpptx.deck.preview', reason: 'Render the first preview batch, then continue until complete is true.' },
		}
		throw err
	}
	if (!verification.complete) {
		const err = new Error('Public deck.save requires every slide in the current frozen package to be previewed before save.')
		err.code = 'PREVIEW_INCOMPLETE'
		err.details = {
			status: 'preview_incomplete',
			artifactStatus: 'not_saved',
			previewVerification: verification,
			nextAction: { recommendedTool: 'betterpptx.deck.preview', reason: 'Preview remainingSlideIndexes in batches until complete is true.' },
		}
		throw err
	}
	if (freeze.validationEvidenceSha256 !== validationVerification.validationEvidenceSha256) {
		invalidatePublicPreviewFreeze(entry)
		throwCurrentVersionValidationRequired(entry)
	}
	const idempotencyKey = getIdempotencyKey(args)
	if (freeze.publishedIdempotencyKey && freeze.publishedIdempotencyKey !== idempotencyKey) {
		const err = new Error('This frozen preview package was already published under a different idempotencyKey. Reuse the original key for the same logical save.')
		err.code = 'IDEMPOTENCY_CONFLICT'
		err.details = { status: 'conflict', artifactStatus: 'unchanged', recommendation: 'Retry with the original save idempotencyKey, or create and preview a new semantic deck version before a new logical save.' }
		throw err
	}
	return freeze
}

async function inspectAvatarMediaInPackage(filePath, manifest = null) {
	const zip = await JSZip.loadAsync(await fs.readFile(filePath))
	const mediaParts = Object.keys(zip.files).filter(name => /^ppt\/media\/[^/]+\.mp4$/i.test(name)).sort()
	const issues = []
	const durationsMs = []
	const tracks = []
	const tempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'betterpptx-avatar-package-'))
	try {
		for (let index = 0; index < mediaParts.length; index += 1) {
			const part = mediaParts[index]
			const tempPath = path.join(tempDir, `media-${index + 1}.mp4`)
			await fs.writeFile(tempPath, await zip.file(part).async('nodebuffer'))
			try {
				const info = await probeMedia({ filePath: tempPath })
				const streams = Array.isArray(info.streams) ? info.streams : []
				const video = streams.find(stream => stream?.codec_type === 'video')
				const audio = streams.find(stream => stream?.codec_type === 'audio')
				const durationSeconds = Number(info.format?.duration || video?.duration || audio?.duration || 0)
				const durationMs = Number.isFinite(durationSeconds) && durationSeconds > 0 ? Math.round(durationSeconds * 1000) : 0
				durationsMs.push(durationMs)
				tracks.push({ video: Boolean(video), audio: Boolean(audio), durationMs })
				if (!video) issues.push(`media ${index + 1} has no video track`)
				if (!audio) issues.push(`media ${index + 1} has no audio track`)
				if (!durationMs) issues.push(`media ${index + 1} has no positive measured duration`)
				const expected = Number(manifest?.slides?.[index]?.durationMs || 0)
				if (expected > 0 && durationMs > 0 && Math.abs(durationMs - expected) > Math.max(250, Math.round(expected * 0.08))) {
					issues.push(`media ${index + 1} duration differs from its authored measured duration beyond tolerance`)
				}
			} catch (error) {
				issues.push(`media ${index + 1} could not be measured`)
				tracks.push({ video: false, audio: false, durationMs: 0 })
			}
		}
	} finally {
		try { await fs.rm(tempDir, { recursive: true, force: true }) } catch {}
	}
	if (!mediaParts.length) issues.push('no embedded MP4 media part was found')
	return {
		schemaVersion: 'betterpptx.avatar.media-inspection.v1',
		ok: issues.length === 0,
		mediaCount: mediaParts.length,
		tracks,
		durationsMs,
		totalDurationMs: durationsMs.reduce((total, value) => total + value, 0),
		issues,
	}
}

async function handleSave(args) {
	const entry = getDeck(args.deckId)
	// Public black-box: a customer never addresses the host filesystem — saves go through the
	// artifact store (download handle), so local fileName/outputDir arguments are refused.
	assertNoPublicLocalPathArgs({ fileName: args.fileName, outputDir: args.outputDir }, ['deck.save'])
	assertPublicSaveIdempotencyKey(args)
	return runDeckIdempotent(entry, 'betterpptx.deck.save', args, async () => {
		const { pptx } = entry
		ensureBetterPptxMetadata(pptx)
		assertPublicOutputShapeAllowed(entry)
		const outputFormat = normalizeDeckSaveOutputFormat(args)
		const verificationPolicy = publicVerificationPolicy()
		const publicPreviewFreeze = requireCompletePublicPreview(entry, outputFormat, args)
		const deliveryFileName = isPublicBlackBoxMode()
			? sanitizePublicArtifactName(args.fileName)
			: args.fileName
		const artifact = outputFormat === 'potx'
			? await _artifactStore.prepareArtifactTarget({
				fileName: deliveryFileName,
				outputDir: args.outputDir,
				deckId: args.deckId,
				kind: 'template',
				extension: '.potx',
				contentType: POTX_CONTENT_TYPE,
			})
			: outputFormat === 'thmx'
				? await _artifactStore.prepareArtifactTarget({
					fileName: deliveryFileName,
					outputDir: args.outputDir,
					deckId: args.deckId,
					kind: 'theme',
					extension: '.thmx',
					contentType: THMX_CONTENT_TYPE,
				})
				: await _artifactStore.prepareSaveTarget({
					fileName: deliveryFileName,
				outputDir: args.outputDir,
				deckId: args.deckId,
			})
		if (publicPreviewFreeze) {
			// This byte-for-byte copy is the public FTR boundary. No serialization,
			// comment projection, sidecar projection, or vocabulary scrub may run
			// after the user has approved the PowerPoint renders.
			await fs.writeFile(artifact.target, publicPreviewFreeze.packageBytes)
		} else if (outputFormat === 'potx') {
			const previousContentType = pptx._rawPresentationContentType
			try {
				pptx._rawPresentationContentType = POTX_MAIN_CONTENT_TYPE
				const buf = await pptx.write({ outputType: 'nodebuffer', compression: args.compression !== false })
				await fs.writeFile(artifact.target, buf)
			} finally {
				if (previousContentType == null) delete pptx._rawPresentationContentType
				else pptx._rawPresentationContentType = previousContentType || PPTX_MAIN_CONTENT_TYPE
			}
		} else if (outputFormat === 'thmx') {
			await exportThemePackageViaOffice(pptx, artifact.target, args)
		} else {
			// EDITION SIDECAR — carry the edition context in the saved file so a future upload
			// of this deck edits as richly as this session (incremental renarrate, segments,
			// beats, world, layout intents).
			_injectEditionSidecar(entry)
			// REVIEW COMMENTS — write semantic review comments as native PowerPoint comments
			// before replies/audit records so all review material is present in one save.
			_injectNativeReviewComments(entry)
			// TWO-WAY REVIEW — write queued acknowledgments as native replies on the user's
			// comment threads (before the audit records, so classic fallbacks ride this save).
			_injectReviewReplies(entry)
			// EDITION AUDIT TRAIL — write the accumulated edit records as native PowerPoint
			// comments so the user reads what changed in their own review pane.
			_injectEditionAuditComments(entry)
			await pptx.writeFile({ fileName: artifact.target, compression: args.compression !== false })
		}
		// BLACKBOX VOCABULARY FIREWALL — never let the internal motion vocabulary (a coined
		// token like "colorWave"/"flashOnce") ride out as VISIBLE content text and expose the
		// engine. Scrub the produced package's visible text runs (slides/notes/SmartArt/charts)
		// at the boundary; the safety validator below then asserts none remain. Structural
		// transition/animation markup, the private edition sidecar, and English homographs
		// (fade/up/morph) are untouched by design. Templates (thmx) carry no slide content.
		if (!publicPreviewFreeze && outputFormat !== 'thmx') {
			try {
				const producedZip = await JSZip.loadAsync(await fs.readFile(artifact.target))
				const scrubbed = await scrubProducedPackageVocabulary(producedZip)
				const publicAvatarScrubbed = isPublicBlackBoxMode()
					? await scrubPublicAvatarDiagnostics(producedZip)
					: {}
				if (Object.keys(scrubbed).length || Object.keys(publicAvatarScrubbed).length) {
					const rebuilt = await producedZip.generateAsync({ type: 'nodebuffer', compression: args.compression !== false ? 'DEFLATE' : 'STORE' })
					await fs.writeFile(artifact.target, rebuilt)
				}
			} catch (err) {
				try { logEvent('blackbox.vocabulary.scrub.error', { message: String(err?.message || err) }) } catch { /* best-effort */ }
			}
		}
		let avatarValidation = null
		if (outputFormat === 'pptx' && entry.avatarManifest?.slides?.length) {
			const structure = await validateAvatarNarrationPackage(artifact.target, entry.avatarManifest)
			const mediaInspection = await inspectAvatarMediaInPackage(artifact.target, entry.avatarManifest)
			avatarValidation = {
				schemaVersion: 'betterpptx.avatar.package-validation.v1',
				ok: structure.ok === true && mediaInspection.ok === true,
				structural: { ok: structure.ok === true, slideCount: structure.perSlide?.length || 0, issueCount: structure.issues?.length || 0 },
				media: mediaInspection,
			}
			if (!avatarValidation.ok) {
				try { await fs.rm(artifact.target, { force: true }) } catch {}
				const err = new Error('Avatar talking-head media or timing failed deterministic package validation; save aborted before delivery.')
				err.code = 'AVATAR_MEDIA_VALIDATION_FAILED'
				err.details = {
					status: 'failed',
					artifactStatus: 'invalid-media',
					qualityGate: { success: false, failed: ['avatarMedia'] },
					validation: avatarValidation,
					nextAction: { recommendedTool: 'betterpptx.deck.validate_avatar_narration', reason: 'Resolve the reported talking-head package, track, duration, poster, or timing issue before saving again.' },
				}
				throw err
			}
		}
		if (outputFormat === 'pptx' && entry.deliveryExperience?.mode === 'narrated-autoplay') {
			const narration = await validateNarrationPackage(artifact.target, entry.narrationManifest, {
				expectedSlideCount: pptx.slides.length,
				requireAutoAdvance: true,
			})
			if (!narration.ok) {
				try { await fs.rm(artifact.target, { force: true }) } catch {}
				const err = new Error('Declared narrated autoplay failed native package or timeline validation; save aborted before delivery.')
				err.code = 'NARRATED_AUTOPLAY_VALIDATION_FAILED'
				err.details = {
					status: 'failed', artifactStatus: 'invalid-narrated-autoplay',
					issues: narration.issues,
					nextAction: { recommendedTool: 'betterpptx.deck.validate_narration', reason: 'Repair native narration coverage, playback settings, or slide timing and validate again.' },
				}
				throw err
			}
		}
		const safety = await validateSavedPackageSafety(artifact.target, {
			metadataLeakOptions: metadataLeakOptionsForEntry(entry),
		})
		if (!safety.ok) {
			try { await fs.rm(artifact.target, { force: true }) } catch {}
			const err = new Error('Generated Office package failed package safety validation; save aborted before delivery.')
			err.code = 'PPTX_PACKAGE_SAFETY_FAILED'
			err.details = {
				status: 'failed',
				artifactStatus: 'unsafe',
				qualityGate: { success: false, failed: ['packageSafety'] },
				validation: { packageSafety: safety },
			}
			throw err
		}
		const selectionVerification = outputFormat === 'thmx'
			? { schemaVersion: 'betterpptx.selection-package-verification.v1', ok: true, status: 'NOT_APPLICABLE_TO_THEME', selectionCount: 0, verifiedCount: 0, results: [] }
			: await verifySelectionManifestInPackage(artifact.target, entry.aiSelectionManifest, { rootDir: path.resolve(__dirname, '..') })
		if (!selectionVerification.ok) {
			try { await fs.rm(artifact.target, { force: true }) } catch {}
			const err = new Error('Generated Office package did not preserve every required AI-authored native selection; save aborted before delivery.')
			err.code = 'PPTX_SELECTION_VERIFICATION_FAILED'
			err.details = {
				status: 'failed',
				artifactStatus: 'selection-mismatch',
				qualityGate: { success: false, failed: ['selectionManifest'] },
				validation: { selectionManifest: selectionVerification },
			}
			throw err
		}
		entry.selectionPackageVerification = cloneForResult(selectionVerification)
		const stat = await fs.stat(artifact.target)
		const packageSha256 = sha256Buffer(await fs.readFile(artifact.target))
		if (publicPreviewFreeze && packageSha256 !== publicPreviewFreeze.packageSha256) {
			try { await fs.rm(artifact.target, { force: true }) } catch {}
			const err = new Error('Frozen preview package changed before publication; save aborted.')
			err.code = 'PREVIEW_FREEZE_MISMATCH'
			err.details = {
				status: 'failed',
				artifactStatus: 'not_saved',
				expectedPackageSha256: publicPreviewFreeze.packageSha256,
				actualPackageSha256: packageSha256,
			}
			throw err
		}
		const finalizedArtifact = _artifactStore.finalizeSaveTarget
			? await _artifactStore.finalizeSaveTarget(artifact)
			: artifact
		if (publicPreviewFreeze) publicPreviewFreeze.publishedIdempotencyKey = getIdempotencyKey(args)
		entry.lastSavedPath = finalizedArtifact.localPathAvailable === false ? null : artifact.target
		entry.lastArtifact = {
			objectName: finalizedArtifact.objectName,
			downloadUrl: finalizedArtifact.downloadUrl,
			downloadLinkExpiresAt: finalizedArtifact.downloadLinkExpiresAt,
			downloadName: finalizedArtifact.downloadName,
			bytes: stat.size,
			packageSha256,
			authoringRoute: cloneForResult(entry.authoringRoute || null),
			expiresAt: finalizedArtifact.expiresAt,
			savedAt: new Date().toISOString(),
		}
		entry.pinUntilSave = false
		logEvent('deck.save.file_written', {
			deckId: args.deckId,
			remote: finalizedArtifact.remote,
			filePath: artifact.target,
			bytes: stat.size,
			slideCount: pptx.slides.length,
			downloadReady: Boolean(finalizedArtifact.downloadUrl),
			downloadName: finalizedArtifact.downloadName,
			artifactStore: { provider: finalizedArtifact.provider, shared: finalizedArtifact.shared },
		})
		return {
			ok: true,
			idempotentReplay: false,
			deckVersion: deckVersion(entry),
			...(isPublicBlackBoxMode() ? {} : { filePath: artifact.target }),
			outputFormat,
			bytes: stat.size,
			slideCount: pptx.slides.length,
			packageSha256,
			authoringRoute: cloneForResult(entry.authoringRoute || null),
			...(publicPreviewFreeze ? { previewVerification: publicPreviewVerification(entry, publicPreviewFreeze) } : {}),
			...(!publicPreviewFreeze && isPublicBlackBoxMode() ? {
				verification: {
					schemaVersion: 'betterpptx.non-rendering-verification.v1',
					policy: verificationPolicy.policy,
					environmentMode: verificationPolicy.environmentMode,
					engineBuild: `${PUBLIC_SEMANTIC_VERSION}+${TOOL_SCHEMA_VERSION}`,
					renderPerformed: false,
					previewStatus: 'not-performed-by-policy',
					packageSha256,
					deckVersion: deckVersion(entry),
					validationEvidenceSha256: currentVersionValidationVerification(entry).validationEvidenceSha256,
					packageSafety: { passed: true },
					selectionVerification: selectionVerification.status === 'SELECTIONS_VERIFIED_IN_PACKAGE'
						? { status: 'verified', passed: true, verifiedCount: selectionVerification.verifiedCount }
						: selectionVerification.ok === false
							? { status: 'failed', passed: false, failedCount: selectionVerification.failedCount || 0 }
							: { status: 'not-requested', verifiedCount: 0 },
					...(avatarValidation ? { avatarMediaInspection: avatarValidation } : {}),
					statement: 'Generated by the release-qualified engine build; this exact package passed the applicable non-rendering validation. PowerPoint rendering and visual/playback review were not performed for this production save.',
				},
			} : {}),
			morphPreviewCoverage: collectMorphPreviewCoverage(entry),
			selectionVerification: {
				status: selectionVerification.status,
				selectionCount: selectionVerification.selectionCount,
				verifiedCount: selectionVerification.verifiedCount,
				failedCount: selectionVerification.failedCount || 0,
			},
			artifact: {
				state: finalizedArtifact.downloadUrl ? 'download_ready' : 'saved',
				expiresAt: finalizedArtifact.expiresAt,
				...(finalizedArtifact.downloadLinkExpiresAt ? { downloadLinkExpiresAt: finalizedArtifact.downloadLinkExpiresAt } : {}),
			},
			...(finalizedArtifact.downloadUrl ? { downloadUrl: finalizedArtifact.downloadUrl, downloadName: finalizedArtifact.downloadName } : {}),
		}
	})
}

function walkElements(node, visit) {
	if (!node || !node.childNodes) return
	for (let i = 0; i < node.childNodes.length; i++) {
		const child = node.childNodes.item(i)
		if (child && child.nodeType === 1) {
			visit(child)
			walkElements(child, visit)
		}
	}
}

function xmlLocalName(node) {
	return String(node?.localName || node?.nodeName || '').split(':').pop()
}

function parsePackageXmlPart(partName, xml, issues) {
	let parseIssues = []
	const doc = new DOMParser({
		errorHandler: {
			warning: () => {},
			error: message => { parseIssues.push(String(message)) },
			fatalError: message => { parseIssues.push(String(message)) },
		},
	}).parseFromString(xml, 'application/xml')
	const parserErrors = doc.getElementsByTagName('parsererror')
	if (parserErrors.length || parseIssues.length) {
		issues.push({
			code: 'XML_PARSE_ERROR',
			part: partName,
			message: 'Generated package contains an XML part that cannot be parsed.',
		})
		return null
	}
	return doc
}

function validatePackageXmlSafety(partName, doc, issues) {
	for (const pathNode of [...Array.from(doc.getElementsByTagName('a:path')), ...Array.from(doc.getElementsByTagName('path'))]) {
		const pathValue = pathNode.getAttribute('path')
		if (pathValue && pathValue !== 'circle' && pathValue !== 'rect' && pathValue !== 'shape') {
			issues.push({
				code: 'INVALID_GRADIENT_PATH',
				part: partName,
				message: `Gradient path "${pathValue}" is not valid DrawingML. Use circle, rect, or shape.`,
			})
		}
	}

	function checkFixedPercentage(node, attr, code) {
		const rawValue = node.getAttribute(attr)
		if (rawValue == null) return
		const value = Number(rawValue)
		if (!Number.isInteger(value) || value < 0 || value > 100000) {
			issues.push({
				code,
				part: partName,
				message: `${node.nodeName} ${attr}="${rawValue}" is outside the PowerPoint-safe fixed percentage range 0..100000.`,
			})
		}
	}
	for (const alphaNode of [...Array.from(doc.getElementsByTagName('a:alpha')), ...Array.from(doc.getElementsByTagName('alpha'))]) {
		checkFixedPercentage(alphaNode, 'val', 'INVALID_ALPHA_VALUE')
	}
	for (const reflectionNode of [...Array.from(doc.getElementsByTagName('a:reflection')), ...Array.from(doc.getElementsByTagName('reflection'))]) {
		checkFixedPercentage(reflectionNode, 'stA', 'INVALID_REFLECTION_ALPHA')
		checkFixedPercentage(reflectionNode, 'endA', 'INVALID_REFLECTION_ALPHA')
		checkFixedPercentage(reflectionNode, 'stPos', 'INVALID_REFLECTION_POSITION')
		checkFixedPercentage(reflectionNode, 'endPos', 'INVALID_REFLECTION_POSITION')
	}

	const fallbacks = [...Array.from(doc.getElementsByTagName('mc:Fallback')), ...Array.from(doc.getElementsByTagName('Fallback'))]
	for (const fallback of fallbacks) {
		walkElements(fallback, node => {
			const name = String(node.nodeName || '')
			if (name.startsWith('p14:') || name.startsWith('p15:') || name.startsWith('p159:')) {
				issues.push({
					code: 'INVALID_ALTERNATECONTENT_FALLBACK',
					part: partName,
					message: `mc:Fallback contains advanced transition element "${name}". Fallback must use legacy p:* content.`,
				})
			}
		})
	}

	const fixedAngleMax = 360 * 60000
	for (const rotNode of [...Array.from(doc.getElementsByTagName('a:rot')), ...Array.from(doc.getElementsByTagName('rot'))]) {
		if (xmlLocalName(rotNode.parentNode) !== 'camera') continue
		for (const attr of ['lat', 'lon', 'rev']) {
			const rawValue = rotNode.getAttribute(attr)
			if (rawValue == null) continue
			const value = Number(rawValue)
			if (!Number.isFinite(value) || value < 0 || value > fixedAngleMax) {
				issues.push({
					code: 'INVALID_SCENE3D_CAMERA_ROTATION',
					part: partName,
					message: `scene3d camera rotation ${attr}="${rawValue}" is not a PowerPoint-safe fixed angle. Use a finite value from 0 to ${fixedAngleMax}; negative degree inputs should be normalized modulo 360 before serialization.`,
				})
			}
		}
	}

	for (const warpNode of [...Array.from(doc.getElementsByTagName('a:prstTxWarp')), ...Array.from(doc.getElementsByTagName('prstTxWarp'))]) {
		const preset = warpNode.getAttribute('prst')
		if (preset && !isValidWordArtTransform(preset)) {
			issues.push({
				code: 'INVALID_WORDART_TRANSFORM',
				part: partName,
				message: `WordArt transform prst="${preset}" is not a valid DrawingML preset. Use textWave4 instead of textDoubleWave2, and textChevronInverted instead of textChevronDown. Call betterpptx.options.catalog with surface:"wordArt" for canonical values.`,
			})
		}
	}
}

async function validateChartExPackageSafety(zip, issues) {
	const names = Object.keys(zip.files)
	const partSet = new Set(names.filter(name => !zip.files[name].dir))
	const contentTypesXml = zip.file('[Content_Types].xml')
		? await zip.file('[Content_Types].xml').async('string')
		: ''
	const chartExParts = names.filter(name => /^ppt\/charts\/chartEx\d+\.xml$/.test(name) && !zip.files[name].dir)
	for (const chartExPart of chartExParts) {
		const base = path.posix.basename(chartExPart)
		const relsPart = `ppt/charts/_rels/${base}.rels`
		if (!partSet.has(relsPart)) {
			issues.push({
				code: 'CHARTEX_RELS_MISSING',
				part: chartExPart,
				message: 'ChartEx chart parts must include a chart relationship part with chartStyle and chartColorStyle relationships.',
			})
			continue
		}
		const relIssues = []
		const relDoc = parsePackageXmlPart(relsPart, await zip.file(relsPart).async('string'), relIssues)
		issues.push(...relIssues)
		if (!relDoc) continue
		const relNodes = relDoc.getElementsByTagName('Relationship')
		let styleTarget = null
		let colorsTarget = null
		for (let i = 0; i < relNodes.length; i++) {
			const node = relNodes.item(i)
			const type = node?.getAttribute('Type') || ''
			const target = node?.getAttribute('Target') || ''
			if (type.endsWith('/chartStyle')) styleTarget = target
			if (type.endsWith('/chartColorStyle')) colorsTarget = target
		}
		for (const [kind, target, contentType] of [
			['chartStyle', styleTarget, 'application/vnd.ms-office.chartstyle+xml'],
			['chartColorStyle', colorsTarget, 'application/vnd.ms-office.chartcolorstyle+xml'],
		]) {
			if (!target) {
				issues.push({
					code: 'CHARTEX_STYLE_REL_MISSING',
					part: relsPart,
					message: `ChartEx relationship part is missing the ${kind} relationship required by PowerPoint.`,
				})
				continue
			}
			const targetPart = path.posix.normalize(path.posix.join('ppt/charts', target))
			if (!partSet.has(targetPart)) {
				issues.push({
					code: 'CHARTEX_STYLE_TARGET_MISSING',
					part: relsPart,
					message: `ChartEx ${kind} relationship target "${target}" does not exist in the package.`,
				})
			}
			if (!contentTypesXml.includes(`PartName="/${targetPart}"`) || !contentTypesXml.includes(`ContentType="${contentType}"`)) {
				issues.push({
					code: 'CHARTEX_STYLE_CONTENT_TYPE_MISSING',
					part: '[Content_Types].xml',
					message: `ChartEx ${kind} target "${targetPart}" is missing its required content type override.`,
				})
			}
		}
	}
}

async function validateSavedPackageSafety(filePath, options = {}) {
	const publicMode = options.publicMode ?? isPublicBlackBoxMode()
	const issues = []
	const warnings = []
	let metadataLeak = null
	let zip
	try {
		zip = await JSZip.loadAsync(await fs.readFile(filePath))
	} catch {
		return {
			ok: false,
			issueCount: 1,
			issues: [{ code: 'ZIP_PARSE_ERROR', message: 'Generated PPTX package could not be opened as a ZIP archive.' }],
		}
	}
	for (const partName of Object.keys(zip.files).sort()) {
		const file = zip.files[partName]
		if (file.dir || !(partName.endsWith('.xml') || partName.endsWith('.rels'))) continue
		const xml = await file.async('string')
		const doc = parsePackageXmlPart(partName, xml, issues)
		if (doc) validatePackageXmlSafety(partName, doc, issues)
	}
	await validateChartExPackageSafety(zip, issues)
	metadataLeak = await validatePackageMetadataLeaksFromZip(zip, options.metadataLeakOptions || {})
	if (!metadataLeak.ok) {
		if (publicMode) issues.push(...metadataLeak.issues)
		else warnings.push(...metadataLeak.issues.map(issue => ({ ...issue, severity: 'warning' })))
	}
	// BLACKBOX VOCABULARY FIREWALL assertion — the save-path scrub should have removed any
	// internal motion vocabulary from visible content; this proves it. A residual token aborts
	// a public save (same contract as a metadata leak); locally it is surfaced as a warning.
	const contentVocabulary = await validateContentVocabularyFromZip(zip)
	if (!contentVocabulary.ok) {
		if (publicMode) issues.push(...contentVocabulary.issues)
		else warnings.push(...contentVocabulary.issues.map(issue => ({ ...issue, severity: 'warning' })))
	}
	const publicAvatarDiagnostics = await validatePublicAvatarDiagnosticsFromZip(zip)
	if (!publicAvatarDiagnostics.ok && publicMode) {
		issues.push(...publicAvatarDiagnostics.issues)
	}
	// TECH-STACK FIREWALL assertion — the private tech stack (voice models, avatar/imaging
	// engines, GPU class, packaging library) must appear in NO part of the package. With the
	// sidecar now encoded, its voice model is inside the opaque blob and this passes.
	const techStack = await validateTechStackVocabularyFromZip(zip)
	if (!techStack.ok) {
		if (publicMode) issues.push(...techStack.issues)
		else warnings.push(...techStack.issues.map(issue => ({ ...issue, severity: 'warning' })))
	}
	return { ok: issues.length === 0, issueCount: issues.length, warningCount: warnings.length, issues, warnings, metadataLeak, contentVocabulary, publicAvatarDiagnostics, techStack }
}

async function handleDispose(args) {
	getDeck(args.deckId)
	const had = decks.delete(args.deckId)
	return { ok: had }
}

async function handleList() {
	return { decks: publicDeckList() }
}

async function handleDeckRecent() {
	return {
		ok: true,
		idleTtlMs: DECK_TTL_MS,
		maxDecks: MAX_DECKS,
		pinUntilSave: true,
		decks: publicDeckList(),
	}
}

async function handleOperationRecent() {
	return {
		ok: true,
		operations: _recentOperations.filter(record => !isPublicBlackBoxMode() || canAccessResource(record)).slice(0, RECENT_OPERATION_LIMIT).map(({ resourceOwner, ...record }) => record),
	}
}

