function hasIdempotencyKey(args = {}) {
	return !!String(args.idempotencyKey || args.idempotency_key || '').trim()
}

function isMutatingTool(name) {
	return !isReadOnlyTool(name)
}

const JSON_SPEC_LIFECYCLE_MUTATIONS = new Set([
	'betterpptx.deck.generate_from_spec',
	'betterpptx.deck.save',
	'betterpptx.deck.dispose',
	'betterpptx.deck.open_uploaded',
	'betterpptx.deck.open_existing',
])

const FORBIDDEN_DIRECT_DECK_CREATORS = new Set([
	'betterpptx.deck.new',
	'betterpptx.deck.load_template',
	'betterpptx.deck.recreate_reference',
])

function mcpAuthoringAuthorized(context = {}) {
	return context?.[MCP_AUTHORING_CAPABILITY] === true
}

function isDeckAuthoringInvocation(name, args = {}) {
	if (name === 'betterpptx.deck.generate_from_spec') return true
	if (FORBIDDEN_DIRECT_DECK_CREATORS.has(name)) return true
	if (['betterpptx.deck.open_uploaded', 'betterpptx.deck.open_existing'].includes(name)) return true
	return Boolean(args?.deckId && isMutatingTool(name) && name !== 'betterpptx.deck.dispose')
}

function throwMcpAuthoringPipelineRequired(name) {
	const err = new Error('Presentation changes require an authorized BetterPPTX authoring workflow.')
	err.code = 'MCP_AUTHORING_PIPELINE_REQUIRED'
	err.details = {
		status: 'mcp_authoring_pipeline_required',
		blockedTool: name,
		reason: 'A cold AI client must discover the Authoring Excellence JSON-spec contract from the MCP endpoint and compile through betterpptx.deck.generate_from_spec.',
		nextAction: {
			recommendedTool: 'betterpptx.help.capabilities',
			reason: 'Connect to BetterPPTX, discover the public contract, then submit the AI-authored specification through generate_from_spec.',
		},
	}
	throw err
}

function assertMcpAuthoringPipeline(name, args = {}, context = {}) {
	if (!isDeckAuthoringInvocation(name, args)) return
	if (!mcpAuthoringAuthorized(context)) throwMcpAuthoringPipelineRequired(name)
}

function throwJsonSpecAuthoringRequired(name) {
	const err = new Error('Direct deck/slide authoring is disabled. The only construction and editing front door is betterpptx.deck.generate_from_spec.')
	err.code = 'JSON_SPEC_AUTHORING_REQUIRED'
	err.details = {
		status: 'json_spec_authoring_required',
		blockedTool: name,
		reason: 'All slide structure, design, motion, narration, presenter, and media changes must be represented in a governed AI-sovereign or Director-assisted JSON spec and compiled atomically.',
		nextAction: {
			recommendedTool: 'betterpptx.deck.generate_from_spec',
			reason: 'Use createNew, append, replaceDeck, or patch through the JSON-spec compiler.',
		},
	}
	throw err
}

function assertJsonSpecOnlyAuthoring(name, args = {}) {
	if (FORBIDDEN_DIRECT_DECK_CREATORS.has(name)) throwJsonSpecAuthoringRequired(name)
	if (!args?.deckId || !isMutatingTool(name)) return
	if (!JSON_SPEC_LIFECYCLE_MUTATIONS.has(name)) throwJsonSpecAuthoringRequired(name)
	if (name !== 'betterpptx.deck.save') return
	const entry = decks.get(args.deckId)
	if (!entry || entry.sourceType !== 'new') return
	const provenance = entry.authoringProvenance
	if (entry.creationPath !== 'betterpptx.deck.generate_from_spec' ||
		entry.director?.specCompiled?.specDigest == null ||
		![DIRECTOR_WORKFLOW, AI_SOVEREIGN_WORKFLOW].includes(provenance?.workflow) ||
		provenance?.transport !== 'mcp') {
		throwJsonSpecAuthoringRequired(name)
	}
}

function isDeckScopedMutationTool(name, args = {}) {
	if (name === 'betterpptx.deck.generate_from_spec') {
		const phase = String(args.phase || (args.dryRun === true ? 'dryRun' : 'commit')).toLowerCase()
		if (args.dryRun === true || phase === 'dryrun' || phase === 'lockeddryrun' || phase === 'resolve') return false
	}
	return !!args?.deckId && isMutatingTool(name)
}

const CURRENT_VERSION_SERIALIZED_READ_TOOLS = new Set([
	'betterpptx.deck.validate_quality',
	'betterpptx.deck.preview',
])

function isCurrentVersionSerializedRead(name, args = {}) {
	return isPublicBlackBoxMode() && !!args?.deckId && CURRENT_VERSION_SERIALIZED_READ_TOOLS.has(name)
}

function suppliedDeckVersion(args = {}) {
	const raw = args.deckVersion ?? args.ifDeckVersion ?? args.expectedDeckVersion
	if (raw === undefined || raw === null || raw === '') return null
	const n = Number(raw)
	return Number.isInteger(n) && n >= 0 ? n : NaN
}

function assertDeckVersionFresh(name, args = {}) {
	if (!isDeckScopedMutationTool(name, args)) return
	const expected = suppliedDeckVersion(args)
	if (expected === null) return
	if (Number.isNaN(expected)) {
		const err = new Error('deckVersion must be a non-negative integer.')
		err.code = 'INVALID_DECK_VERSION'
		err.details = { status: 'invalid_deck_version' }
		throw err
	}
	const entry = decks.get(args.deckId)
	if (!entry) return
	const current = deckVersion(entry)
	if (expected !== current) {
		const err = new Error(`Deck version conflict: client has ${expected}, current version is ${current}. Re-inspect the deck before retrying.`)
		err.code = 'DECK_VERSION_CONFLICT'
		err.details = {
			status: 'stale_deck_version',
			currentDeckVersion: current,
			clientDeckVersion: expected,
			nextAction: {
				recommendedTool: 'betterpptx.deck.summary',
				reason: 'Refresh the deck state before retrying the mutation.',
			},
		}
		throw err
	}
}

function assertDirectorAllowsTool(name, args = {}) {
	if (!args?.deckId) return
	if (DIRECTOR_SETUP_TOOLS.has(name)) return
	if (!DIRECTOR_GATED_TOOLS.has(name)) return
	const entry = decks.get(args.deckId)
	if (!entry) return
	const director = ensureDirectorState(entry)
	if (director.mode === 'ai-sovereign') {
		if (name === 'betterpptx.deck.save') {
			const validationVerification = currentVersionValidationVerification(entry)
			if (validationVerification.complete !== true) {
				const err = new Error('Complete current-version validation is required before saving an AI-sovereign deck.')
				err.code = 'CURRENT_VERSION_VALIDATION_REQUIRED'
				err.details = {
					status: 'verification_required',
					blockedTool: name,
					validationVerification,
					nextAction: { recommendedTool: 'betterpptx.deck.validate_quality', reason: 'Run complete package, design, accessibility, media, narration, and selection validation for the current deckVersion before save.' },
				}
				throw err
			}
		}
		return
	}
	if (director.mode !== 'director-strict' && !directorIsNewDeck(entry)) return
	const missingPlanning = directorPlanningMissingStages(entry)
	const domainCoverage = directorDomainCoverage(entry)
	if (missingPlanning.length) {
		const first = missingPlanning[0]
		const err = new Error(`Director stage required before ${name}: complete ${DIRECTOR_STAGE_NAMES[first]}.`)
		err.code = 'DIRECTOR_STAGE_REQUIRED'
		err.details = {
			status: 'director_stage_required',
			mode: director.mode,
			blockedTool: name,
			missingStages: missingPlanning,
			requiredTools: missingPlanning.map(stage => DIRECTOR_STAGE_TOOLS[stage]),
			nextAction: {
			recommendedTool: DIRECTOR_STAGE_TOOLS[first],
			reason: `Complete ${DIRECTOR_STAGE_NAMES[first]} before primitive authoring or save.`,
		},
		}
		throw err
	}
	if (!domainCoverage.complete && !['betterpptx.deck.define_message_architecture', 'betterpptx.deck.assign_slide_roles', 'betterpptx.deck.define_design_system'].includes(name)) {
		const err = new Error(`Director domain composition required before ${name}: complete Content / Story, Visual / Design, and Motion / Time.`)
		err.code = 'DIRECTOR_DOMAIN_REQUIRED'
		err.details = {
			status: 'director_domain_required',
			blockedTool: name,
			missingDomains: domainCoverage.missing,
			requiredDomains: DIRECTOR_DOMAIN_KEYS,
			nextAction: {
				recommendedTool: domainCoverage.missing.includes('content-story') ? 'betterpptx.deck.define_message_architecture' : 'betterpptx.deck.define_design_system',
			reason: 'Declare the three composition domains before adding or compiling slide primitives.',
		},
		}
		throw err
	}
	if (name === 'betterpptx.deck.autoplay') {
		const hasFixedTiming = args.secondsPerSlide !== undefined && args.secondsPerSlide !== null
		const timelineSource = String(args.timingSource || args.source || '').trim().toLowerCase()
		if (hasFixedTiming || !directorTimelineComplete(entry)) {
			const err = new Error('Fixed secondsPerSlide autoplay is disabled for Director decks; timing must come from measured narration or an explicit Director timeline.')
			err.code = 'DIRECTOR_TIMELINE_REQUIRED'
			err.details = {
				status: 'director_timeline_required',
				blockedTool: name,
				reason: 'Hard-coded per-slide autoplay creates a second clock and can desynchronize narration, animation, and transitions.',
				nextAction: { recommendedTool: 'betterpptx.deck.add_narration', reason: 'Add measured narration timing, then let the narration timeline own slide dwell.' },
			}
			throw err
		}
	}
	if (name === 'betterpptx.slide.add' && args.transition && args.transition.advanceAfterTime !== undefined && args.timingSource !== 'director-timeline' && args.timingSource !== 'narration') {
		const err = new Error('Hard-coded slide advance timing is disabled for Director decks; author timing through narration or an explicit Director timeline.')
		err.code = 'DIRECTOR_TIMELINE_REQUIRED'
		err.details = { status: 'director_timeline_required', blockedTool: name, nextAction: { recommendedTool: 'betterpptx.deck.add_narration', reason: 'Let measured narration own slide dwell and transition timing.' } }
		throw err
	}
	if (name === 'betterpptx.deck.save') {
		if (director.stages?.['primitive-instantiation']?.completed !== true) {
			const err = new Error('Director primitive instantiation is required before save.')
			err.code = 'DIRECTOR_PRIMITIVE_REQUIRED'
			err.details = { status: 'director_primitive_required', blockedTool: name, nextAction: { recommendedTool: 'betterpptx.slide.add', reason: 'Instantiate the authored slides through the Director path.' } }
			throw err
		}
		if (!domainCoverage.complete) {
			const err = new Error('Content / Story, Visual / Design, and Motion / Time domain composition is required before save.')
			err.code = 'DIRECTOR_DOMAIN_REQUIRED'
			err.details = { status: 'director_domain_required', blockedTool: name, missingDomains: domainCoverage.missing, requiredDomains: DIRECTOR_DOMAIN_KEYS }
			throw err
		}
		if (!directorTimelineComplete(entry)) {
			const err = new Error('A measured Director timeline is required before save.')
			err.code = 'DIRECTOR_TIMELINE_REQUIRED'
			err.details = { status: 'director_timeline_required', blockedTool: name, timelineContract: director.timelineContract, nextAction: { recommendedTool: 'betterpptx.deck.add_narration', reason: 'Add narration or an explicit per-slide Director timeline; do not use hard-coded autoplay.' } }
			throw err
		}
		const validationVerification = currentVersionValidationVerification(entry)
		if ((isPublicBlackBoxMode() && validationVerification.complete !== true) ||
			(!isPublicBlackBoxMode() && director.stages?.verification?.completed !== true)) {
			const err = new Error('Director verification is required before save.')
			err.code = isPublicBlackBoxMode() ? 'CURRENT_VERSION_VALIDATION_REQUIRED' : 'DIRECTOR_VERIFICATION_REQUIRED'
			err.details = {
				status: 'director_verification_required',
				blockedTool: name,
				...(isPublicBlackBoxMode() ? { validationVerification } : {}),
				nextAction: { recommendedTool: 'betterpptx.deck.validate_quality', reason: 'Run the aggregate package, design, accessibility, and narration quality gate for the current deckVersion before save.' },
			}
			throw err
		}
	}
	if (name === 'betterpptx.deck.apply_auto_timings' && director.stages?.['primitive-instantiation']?.completed !== true) {
		const err = new Error('Director primitive instantiation is required before applying timing.')
		err.code = 'DIRECTOR_PRIMITIVE_REQUIRED'
		err.details = { status: 'director_primitive_required', blockedTool: name }
		throw err
	}
}

function bumpDeckVersionAfterMutation(name, args = {}, data) {
	if (!isDeckScopedMutationTool(name, args)) return
	if (name === 'betterpptx.deck.dispose') return
	if (data && typeof data === 'object' && data.ok === false) return
	const entry = decks.get(args.deckId)
	if (!entry) return
	// Save stays in the per-deck serialization queue so a semantic mutation cannot
	// race publication, but publishing immutable bytes is not itself a semantic
	// version change. This also keeps same-key retries valid with deckVersion.
	if (name === 'betterpptx.deck.save') return
	invalidatePublicPreviewFreeze(entry)
	invalidateDirectorVerification(entry, name)
	if (directorIsNewDeck(entry) && entry.director?.mode !== 'ai-sovereign' && DIRECTOR_GATED_TOOLS.has(name) && !['betterpptx.deck.save', 'betterpptx.deck.autoplay', 'betterpptx.deck.apply_auto_timings'].includes(name)) {
		markDirectorPrimitiveInstantiation(entry, name)
	}
	entry.previousDeckVersionForDurableState = deckVersion(entry)
	entry.deckVersion = deckVersion(entry) + 1
	if (name === 'betterpptx.deck.generate_from_spec' && entry.presenterPerformanceValidation?.pendingCompiledVersionUpdate && entry.presenterPerformanceValidation.deckVersion === entry.previousDeckVersionForDurableState) {
		entry.presenterPerformanceValidation.deckVersion = entry.deckVersion
		delete entry.presenterPerformanceValidation.pendingCompiledVersionUpdate
	}
}

async function runSerializedDeckMutation(name, args = {}, operation) {
	const mutating = isDeckScopedMutationTool(name, args)
	if (!mutating && !isCurrentVersionSerializedRead(name, args)) return operation()
	const entry = getDeck(args.deckId)
	const previous = entry.mutationQueue || Promise.resolve()
	const queued = previous.catch(() => {}).then(async () => {
		if (mutating) assertDeckVersionFresh(name, args)
		const data = await operation()
		if (mutating) bumpDeckVersionAfterMutation(name, args, data)
		addDeckVersionToData(data, args)
		return data
	})
	entry.mutationQueue = queued.catch(() => {})
	return queued
}

function supportsDeckIdempotency(name, args = {}) {
	return IDEMPOTENT_DECK_MUTATION_TOOLS.has(name) && !!args?.deckId
}

function supportsDeckIdempotencyReplay(name, args = {}) {
	return IDEMPOTENT_DECK_REPLAY_TOOLS.has(name) && !!args?.deckId
}

function supportsSessionIdempotency(name, args = {}) {
	// Long-running identity media and narration use the durable operation ledger
	// when configured. A process-local session record must not mask the durable
	// result after the MCP transport or worker reconnects.
	if (['betterpptx.avatar.render_job', 'betterpptx.narration.synthesize'].includes(name) && hasIdempotencyKey(args) && durableOperationStoreEnabled()) return false
	return IDEMPOTENT_SESSION_MUTATION_TOOLS.has(name)
}

function durableOperationStoreEnabled() {
	return Boolean(_operationStore && !_operationStore.disabled)
}

function durableOperationExecutionMode() {
	const mode = String(process.env.BETTERPPTX_OPERATION_EXECUTION_MODE || 'inline').trim().toLowerCase()
	return mode === 'queued' || mode === 'queue' || mode === 'async' ? 'queued' : 'inline'
}

function durableOperationQueuedMode() {
	return durableOperationExecutionMode() === 'queued'
}

function specGenerationPhaseForDurableOperation(name, args = {}) {
	if (name !== 'betterpptx.deck.generate_from_spec') return undefined
	try {
		return normalizeSpecGenerationPhase(args)
	} catch {
		// Let the spec handler return the precise phase/argument finding. Invalid
		// requests cannot mutate a deck and should not be masked by an idempotency
		// prerequisite or persisted as durable operations.
		return null
	}
}

function isNonMutatingSpecGenerationInvocation(name, args = {}) {
	const phase = specGenerationPhaseForDurableOperation(name, args)
	return phase === null || phase === 'dryRun' || phase === 'lockedDryRun'
}

function supportsDurableOperationLedger(name, args = {}) {
	if (name === 'betterpptx.motion.prepare_variant') return false
	if (!durableOperationStoreEnabled()) return false
	if (!hasIdempotencyKey(args)) return false
	if (isReadOnlyTool(name)) return false
	if (name.startsWith('betterpptx.billing.') || name.startsWith('betterpptx.auth.')) return false
	if (isNonMutatingSpecGenerationInvocation(name, args)) return false
	return Boolean(
		DECK_CREATION_TOOLS.has(name)
		|| supportsDeckIdempotency(name, args)
		|| supportsDeckIdempotencyReplay(name, args)
		|| HEAVY_TOOLS.has(name),
	)
}

function durableOperationIdempotencyRequired(name, args = {}) {
	return process.env.BETTERPPTX_REQUIRE_DURABLE_OPERATION_IDEMPOTENCY === '1'
		&& durableOperationStoreEnabled()
		&& isMutatingTool(name)
		&& !isNonMutatingSpecGenerationInvocation(name, args)
		&& !name.startsWith('betterpptx.billing.')
		&& !name.startsWith('betterpptx.auth.')
		&& !hasIdempotencyKey(args)
}

function durableOperationQueuedTakeoverMs() {
	return Math.max(1000, Number(process.env.BETTERPPTX_DURABLE_OPERATION_QUEUED_TAKEOVER_MS || 15000))
}

function durableOperationLeaseMs(name) {
	const base = Number(process.env.BETTERPPTX_DURABLE_OPERATION_LEASE_MS || 10 * 60 * 1000)
	const heavy = HEAVY_TOOLS.has(name) ? Number(process.env.BETTERPPTX_DURABLE_HEAVY_OPERATION_LEASE_MS || 30 * 60 * 1000) : base
	return Math.max(1000, Number.isFinite(heavy) ? heavy : base)
}

function durableOperationInput(name, args = {}, context = {}) {
	const deckId = String(args.deckId || '')
	const expectedDeckVersion = suppliedDeckVersion(args)
	const inputDigest = idempotencyArgsHash(args)
	const executionArgs = durableOperationQueuedMode() ? cloneForResult(args || {}) : null
	const request = executionArgs ? {
		args: executionArgs,
		...(mcpAuthoringAuthorized(context)
			? captureQueuedMcpContinuation(context, inputDigest, idempotencyArgsHash(executionArgs))
			: { context: { installHash: context.installHash || '', resourceIdentityHash: context.resourceIdentityHash || '', sessionId: context.sessionId || '' } }),
	} : null
	return {
		installHash: String(context.installHash || context.resourceIdentityHash || context.billingCustomerHash || context.sessionId || 'anonymous'),
		toolName: name,
		deckId,
		deckHash: deckId ? digestOperationPayload({ deckId }) : '',
		expectedDeckVersion: Number.isNaN(expectedDeckVersion) ? null : expectedDeckVersion,
		inputDigest,
		pricingInputDigest: '',
		queueClass: HEAVY_TOOLS.has(name) ? 'heavy' : 'default',
		idempotencyKey: getIdempotencyKey(args),
		metadata: {
			phase: String(args.phase || (args.dryRun === true ? 'dryRun' : 'commit')),
		},
		request,
	}
}

function annotateDurableOperationData(data, operation = {}, replay = false) {
	if (data && typeof data === 'object' && !Array.isArray(data)) {
		data.durableOperation = {
			operationId: operation.operationId,
			replay,
			state: operation.state,
		}
	}
	return data
}

async function attachCompletedSaveOperation(replay, args = {}, context = {}) {
	if (!_operationStore?.findOperationByIdempotencyKey || !getIdempotencyKey(args)) return replay
	const identity = durableOperationInput('betterpptx.deck.save', args, context)
	const operation = await _operationStore.findOperationByIdempotencyKey(identity)
	if (!operation || operation.state !== 'succeeded' || operation.toolName !== 'betterpptx.deck.save'
		|| operation.deckId !== args.deckId || operation.installHash !== identity.installHash
		|| operation.result?.packageSha256 !== replay?.packageSha256) return replay
	replay.operationId = operation.operationId
	return annotateDurableOperationData(replay, operation, true)
}

async function replayCompletedSaveFromDurableLedger(args = {}, context = {}) {
	if (!_operationStore?.findOperationByIdempotencyKey || !getIdempotencyKey(args)) return null
	const identity = durableOperationInput('betterpptx.deck.save', args, context)
	const operation = await _operationStore.findOperationByIdempotencyKey(identity)
	if (!operation) return null
	if (operation.installHash !== identity.installHash || operation.toolName !== identity.toolName
		|| operation.deckId !== identity.deckId || operation.expectedDeckVersion !== identity.expectedDeckVersion
		|| operation.inputDigest !== identity.inputDigest) {
		const err = new Error('The save idempotency key belongs to a different request.')
		err.code = 'OPERATION_IDEMPOTENCY_CONFLICT'
		throw err
	}
	if (operation.state !== 'succeeded') return null
	const result = await durableOperationSuccessResult(operation, 'betterpptx.deck.save', args)
	result.data.operationId = operation.operationId
	result.data.idempotentReplay = true
	return result
}

async function durableOperationSuccessResult(operation, name, args = {}) {
	const data = annotateDurableOperationData(restorePersistedSpecHandoffProvenance(cloneForResult(operation?.result || {})), operation, true)
	if (data && typeof data === 'object' && !Array.isArray(data)) {
		addDeckVersionToData(data, args)
		addSuccessEnvelope(data, name, args)
		if (typeof data.downloadUrl === 'string' && typeof data.downloadName === 'string') {
			// Legacy private records may carry the storage object key. Only the
			// owner-authorized download pair belongs in the public replay result.
			delete data.objectName
			// A cold instance has no local delivery attestation. Recover through
			// the store's owner/immutable-publication checks before sanitation can
			// rewrite signed bytes. Issuance cannot extend the original file expiry
			// or regenerate the saved package; the persisted success stays intact.
			try {
				const fresh = await _artifactStore.issueBrowserDownload({
					downloadUrl: data.downloadUrl, downloadName: data.downloadName,
				})
				data.downloadUrl = fresh.downloadUrl
				data.artifact = { ...(data.artifact || {}), downloadLinkExpiresAt: fresh.downloadLinkExpiresAt }
			} catch {
				// Publication success and present delivery availability are distinct.
				// Never leak a stale capability or private storage failure details.
				data.downloadUrl = null
				data.artifact = { ...(data.artifact || {}), state: 'unavailable' }
			}
		}
	}
	return { ok: true, data: sanitizePublicResult(data) }
}

function durableOperationPendingResult(operation, reason = 'operation-in-progress') {
	return sanitizePublicResult(normalizePublicErrorResult({
		ok: false,
		error: {
			code: 'OPERATION_PENDING',
			message: 'This idempotent operation is already running or waiting. Retry with the same idempotency key.',
			recoverable: true,
			retry_safe: true,
			artifact_state: 'unchanged_or_pending',
			details: {
				status: 'operation_pending',
				reason,
				operationId: operation?.operationId || '',
				state: operation?.state || 'unknown',
				attempt: operation?.attempt || 0,
				leaseExpiresAt: operation?.leaseExpiresAt || '',
			},
		},
	}))
}

function durableOperationDispatchError(operation = {}) {
	const error = new Error('Dispatch could not be confirmed. First check operation status. Do not start a replacement mutation; if replay is needed, send the identical request with its original idempotency key.')
	error.code = 'OPERATION_DISPATCH_UNAVAILABLE'
	error.retryable = true
	error.details = {
		operationId: String(operation.operationId || ''),
		dispatchStatus: 'unconfirmed',
	}
	return error
}

function durableOperationFailedResult(operation) {
	const error = operation?.error || {}
	return sanitizePublicResult(normalizePublicErrorResult({
		ok: false,
		error: {
			code: error.code || 'OPERATION_FAILED',
			message: error.message || 'This idempotent operation failed. Use a new idempotency key after changing the request.',
			recoverable: false,
			retry_safe: false,
			artifact_state: 'unchanged_or_unknown',
			details: {
				...(error.details || {}),
				status: 'operation_failed',
				operationId: operation?.operationId || '',
				state: operation?.state || 'failed',
			},
		},
	}))
}

async function beginDurableOperation(name, args = {}, context = {}) {
	if (!supportsDurableOperationLedger(name, args)) return null
	const started = await _operationStore.createOrGetOperation(durableOperationInput(name, args, context))
	const operation = started.operation
	if (!started.created) {
		if (operation.state === 'succeeded') return { replayResult: await durableOperationSuccessResult(operation, name, args) }
		if (operation.state === 'failed' || operation.state === 'cancelled') return { replayResult: durableOperationFailedResult(operation) }
		if (operation.state === 'queued') {
			const updatedAtMs = Date.parse(operation.updatedAt || operation.createdAt || '')
			const staleQueued = Number.isFinite(updatedAtMs) && Date.now() - updatedAtMs >= durableOperationQueuedTakeoverMs()
			if (!staleQueued) return { replayResult: durableOperationPendingResult(operation, 'queued') }
		}
	}
	if (durableOperationQueuedMode()) {
		if (operation.state === 'running') return { replayResult: durableOperationPendingResult(operation, 'leased') }
		if (operation.state === 'queued' || operation.state === 'retry') {
			try {
				await _operationDispatcher.dispatchOperation({
					operationId: operation.operationId,
					queueClass: operation.queueClass || 'default',
				})
			} catch {
				// The operation is already durable. Preserve it as recoverable because
				// a task may exist even when its create response was lost; status and
				// same-key retry are safe through the operation/task idempotency keys.
				throw durableOperationDispatchError(operation)
			}
			return { replayResult: durableOperationPendingResult(operation, started.created ? 'queued-dispatched' : 'queued-redispatched') }
		}
		return { replayResult: durableOperationPendingResult(operation, 'queued-mode') }
	}
	try {
		const claim = await _operationStore.claimOperation(operation.operationId, {
			leaseOwner: `${process.pid}:${context.sessionId || 'stdio-default'}`,
			leaseMs: durableOperationLeaseMs(name),
		})
		if (!claim.claimed && claim.terminal && claim.operation?.state === 'succeeded') {
			return { replayResult: await durableOperationSuccessResult(claim.operation, name, args) }
		}
		if (!claim.claimed) return { replayResult: durableOperationPendingResult(claim.operation || operation, 'terminal-or-unclaimable') }
		return { operation: claim.operation, lease: claim.lease }
	} catch (err) {
		if (err?.code === 'OPERATION_ALREADY_LEASED') {
			return { replayResult: durableOperationPendingResult(operation, 'leased') }
		}
		throw err
	}
}

async function failDurableOperation(run = null, error = {}, { retryable = false } = {}) {
	if (!run?.operation?.operationId || !run?.lease?.leaseToken) return
	try {
		await _operationStore.failOperation(run.operation.operationId, {
			leaseToken: run.lease.leaseToken,
			error: {
				code: error?.code || 'OPERATION_FAILED',
				message: String(error?.message || error || 'Operation failed.'),
				details: error?.details || {},
			},
			retryable,
		})
	} catch (storeErr) {
		logEvent('durable_operation.fail_record_failed', {
			operationId: run.operation.operationId,
			code: storeErr?.code || 'DURABLE_OPERATION_FAIL_RECORD_FAILED',
			message: String(storeErr?.message || storeErr),
		})
	}
}

function restorePersistedSpecHandoffProvenance(data) {
	// This carrier exists only in a server-owned successful operation record. It
	// is never accepted from tool arguments and never survives public sanitation.
	if (data?.phase === 'resolve' && data.lockedSpec && data._authoredSpecLiterals) {
		data.lockedSpec = sanitizePublicAuthoredSpec(data.lockedSpec, data._authoredSpecLiterals)
	}
	if (data && typeof data === 'object') delete data._authoredSpecLiterals
	return data
}

function persistedSpecHandoffResult(data = {}) {
	const result = cloneForResult(data || {})
	const literals = data?.phase === 'resolve' ? authoredSpecLiteralSnapshot(data.lockedSpec) : null
	if (literals) result._authoredSpecLiterals = literals
	return result
}

async function completeDurableOperation(run = null, data = {}) {
	if (!run?.operation?.operationId || !run?.lease?.leaseToken) return null
	try {
		return await _operationStore.completeOperation(run.operation.operationId, {
			leaseToken: run.lease.leaseToken,
			result: persistedSpecHandoffResult(data),
		})
	} catch (cause) {
		if (['OPERATION_NOT_FOUND', 'OPERATION_LEASE_STALE'].includes(cause?.code)) throw cause
		// A lost transaction acknowledgement is not a failed transaction. Recover
		// only a confirmed success for the same owned immutable request, without
		// repeating its handler or introducing another billing/publication event.
		try {
			const recorded = await _operationStore.getOperation(run.operation.operationId)
			if (recorded?.state === 'succeeded'
				&& recorded.installHash === run.operation.installHash
				&& recorded.toolName === run.operation.toolName
				&& recorded.inputDigest === run.operation.inputDigest
				&& recorded.requestDigest === run.operation.requestDigest) return recorded
		} catch { /* unconfirmed remains unconfirmed */ }
		// Completion can fail after materialization. Do not expose provider internals
		// or imply rollback; the owned operation is the authorized recovery anchor.
		logEvent('durable_operation.result_persistence_failed', {
			operationId: run.operation.operationId,
			code: cause?.code || 'RESULT_PERSISTENCE_FAILED',
		})
		throw Object.assign(new Error('The operation result could not be recorded. Inspect the owned operation before starting another mutation.'), {
			code: 'OPERATION_RESULT_PERSISTENCE_FAILED',
			details: { operationId: run.operation.operationId, artifactStatus: 'unchanged_or_unknown' },
		})
	}
}

function durableWorkerRetryableError(code = '') {
	return [
		'BUSY',
		'BILLING_TEMPORARILY_UNAVAILABLE',
		'OPERATION_PENDING',
		'AVATAR_JOB_NOT_READY',
	].includes(String(code || ''))
}

export async function runDurableOperationById(operationId, { leaseOwner = '' } = {}) {
	if (!_operationStore || _operationStore.disabled || typeof _operationStore.getOperation !== 'function') {
		const err = new Error('Durable operation execution is not enabled.')
		err.code = 'OPERATION_STORE_DISABLED'
		throw err
	}
	const id = String(operationId || '').trim()
	const existing = await _operationStore.getOperation(id)
	if (!existing) {
		const err = new Error('Operation was not found.')
		err.code = 'OPERATION_NOT_FOUND'
		throw err
	}
	if (existing.state === 'succeeded' || existing.state === 'failed' || existing.state === 'cancelled') {
		return publicDurableOperationStatus(existing)
	}
	const request = existing.request || {}
	if (!request.args || !existing.toolName) {
		const err = new Error('Operation request payload is missing.')
		err.code = 'OPERATION_REQUEST_MISSING'
		throw err
	}
	if (existing.installHash !== durableOperationInput(existing.toolName, request.args, request.context || {}).installHash) {
		const err = new Error('The stored operation and its request have inconsistent ownership.')
		err.code = 'OPERATION_REQUEST_IDENTITY_MISMATCH'
		throw err
	}
	const requestContinuation = isQueuedMcpContinuation(request, existing, idempotencyArgsHash(request.args))
	if (request.mcpContinuation && !requestContinuation) {
		const err = new Error('The stored operation continuation does not match its admitted request.')
		err.code = 'OPERATION_REQUEST_INVALID'
		throw err
	}
	let claim
	try {
		claim = await _operationStore.claimOperation(id, {
			leaseOwner: leaseOwner || `worker:${process.pid}`,
			leaseMs: durableOperationLeaseMs(existing.toolName),
		})
	} catch (err) {
		if (err?.code === 'OPERATION_ALREADY_LEASED') return publicDurableOperationStatus(existing)
		throw err
	}
	if (!claim.claimed) return publicDurableOperationStatus(claim.operation || existing)
	const preparationContinuation = existing.toolName === 'betterpptx.motion.prepare_variant' && requestContinuation
	const workerContext = {
		...(requestContinuation ? request.context : {
			installHash: request.context?.installHash || '',
			resourceIdentityHash: request.context?.resourceIdentityHash || '',
			sessionId: request.context?.sessionId || '',
		}),
		sessionId: request.context?.sessionId || `durable-worker:${id}`,
		// Only the authenticated private worker may resume a server-owned request.
		// Admission checked this module-private capability before persisting it;
		// JSON cannot retain Symbols. Restore it here, never from public arguments
		// or a client-supplied string flag. All owner/quote/asset/save gates still run.
		[MCP_AUTHORING_CAPABILITY]: existing.toolName !== 'betterpptx.motion.prepare_variant' || preparationContinuation,
		__skipDurableOperationLedger: true,
		__durableOperationWorker: true,
		__claimedDurableOperation: { operation: claim.operation, lease: claim.lease },
	}
	const result = await callBetterPptxTool(existing.toolName, request.args, workerContext)
	const current = await _operationStore.getOperation(id)
	if (result?.error?.code === 'TOOL_TIMEOUT' || ['succeeded', 'failed', 'cancelled'].includes(current?.state)) {
		// The engine's still-running completion owns the same fenced lease. A
		// response timeout must not turn it into a failed/retryable operation.
		return publicDurableOperationStatus(current || claim.operation)
	}
	const avatarJobFailed = existing.toolName === 'betterpptx.avatar.render_job'
		&& result?.ok === true
		&& result?.data?.status === 'failed'
	if (result?.ok === true && !avatarJobFailed) {
		const completed = await completeDurableOperation({ operation: claim.operation, lease: claim.lease }, result.data || {})
		return publicDurableOperationStatus(completed)
	}
	const error = result?.error || result?.data?.error || (avatarJobFailed
		? { code: 'AVATAR_FAILED', message: 'Avatar render job failed.' }
		: { code: 'OPERATION_FAILED', message: 'Operation failed.' })
	const retryable = durableWorkerRetryableError(error.code)
	const failed = await _operationStore.failOperation(id, {
		leaseToken: claim.lease.leaseToken,
		error,
		retryable,
	})
	return publicDurableOperationStatus(failed)
}

function maintenanceResult(code, message) {
	return normalizePublicErrorResult({
		ok: false,
		error: {
			code,
			message,
			recoverable: true,
			retry_safe: true,
			artifact_state: 'unchanged_or_unknown',
		},
	})
}

function isReadOnlyTool(name) {
	return MONETIZED_MCP_READ_ONLY_TOOLS.has(String(name || '')) ||
		String(name || '') === 'betterpptx.motion.candidates.get' ||
		READ_ONLY_TOOL_RE.test(String(name || ''))
}

function isAvatarGenerationRequest(args = {}) {
	return args.renderMode !== 'completedAsset' && !args.jobId && !args.avatarAsset
}

function assertAvatarConsentBeforeBilling(name, args = {}) {
	if (name === 'betterpptx.avatar.render_job' || name === 'betterpptx.slide.add_avatar_narration') {
		if (isAvatarGenerationRequest(args)) assertAvatarGenerationInput(args.avatar)
	}
	if (name === 'betterpptx.deck.add_avatar_narration') {
		for (const item of args.slides || []) {
			if (isAvatarGenerationRequest(item)) assertAvatarGenerationInput(item.avatar || args.avatar)
		}
	}
}

function checkDeckCreationQuota(name, context = {}, args = {}) {
	if (!DECK_CREATION_TOOLS.has(name)) return null
	// Local maintainer / research mode: no anti-abuse deck cap. The per-session
	// hourly quota is a public-abuse guard; a trusted local maintainer running a
	// calibration batch was silently hitting it at ~20 decks. Consistent with the
	// maintainer-mode billing bypass (see handleGenerateFromSpec).
	if (isLocalMaintainerMode()) return null
	if (name === 'betterpptx.deck.generate_from_spec') {
		let phase
		try { phase = normalizeSpecGenerationPhase(args) }
		catch (err) { return buildToolErrorResult(err, name, args) }
		// Use the execution contract, including legacy aliases and conflict checks.
		// Planning never allocates a deck; existing-deck commits are edits, not creates.
		if (phase === 'dryRun' || phase === 'resolve' || phase === 'lockedDryRun' || args.deckId) return null
	}
	const sessionId = String(context.installHash || context.resourceIdentityHash || context.sessionId || 'stdio-default')
	const now = Date.now()
	const windowMs = 60 * 60 * 1000
	let record = sessionDeckWindows.get(sessionId)
	if (!record || now - record.startedAt >= windowMs) {
		record = { startedAt: now, count: 0 }
		sessionDeckWindows.set(sessionId, record)
	}
	if (record.count >= SESSION_DECKS_PER_HOUR) {
		return normalizePublicErrorResult({
			ok: false,
			error: {
				code: 'RATE_LIMITED',
				message: 'This session has reached the current deck creation quota. Retry later or continue editing an existing deck.',
				recoverable: true,
				retry_safe: true,
				artifact_state: 'unchanged_or_unknown',
				details: {
					limit: SESSION_DECKS_PER_HOUR,
					resetAt: new Date(record.startedAt + windowMs).toISOString(),
				},
			},
		})
	}
	record.count += 1
	return null
}

function withToolTimeout(promise, timeoutMs, name) {
	let timer
	const timeout = new Promise((_, reject) => {
		timer = setTimeout(() => {
			const err = new Error(`Tool call timed out after ${timeoutMs}ms.`)
			err.code = 'TOOL_TIMEOUT'
			err.details = { tool: name, timeoutMs }
			reject(err)
		}, timeoutMs)
		timer.unref?.()
	})
	return Promise.race([promise, timeout]).finally(() => clearTimeout(timer))
}

function publicNextActionsForError(code, details = {}) {
	if (code === 'OPERATION_RESULT_PERSISTENCE_FAILED') {
		return [{ type: 'recover_operation', tool: 'betterpptx.operation.status',
			description: 'Inspect the existing owned operation before any new mutation; result persistence failure does not establish rollback.',
			...(details.operationId ? { input: { operationId: details.operationId } } : {}),
		}]
	}
	// Spec validation can fail before the compiler produces a top-level error code. Keep the
	// outer envelope recoverable, but let a cold AI act on the typed inner finding immediately.
	const nestedSpecCode = code === 'SPEC_COMPILE_FAILED' && Array.isArray(details?.errors)
		? details.errors.find(item => item && typeof item === 'object' && item.code)?.code
		: null
	if (nestedSpecCode === 'SPEC_REQUIRED') {
		return [{ type: 'provide_spec', tool: 'betterpptx.deck.generate_from_spec', description: 'Provide a semantic spec with schemaVersion, title, and slides, then rerun phase:"dryRun".' }]
	}
	if (nestedSpecCode === 'SPEC_PHASE_INVALID' || nestedSpecCode === 'SPEC_PHASE_CONFLICT') {
		return [{ type: 'choose_phase', tool: 'betterpptx.deck.generate_from_spec', description: 'Choose one non-conflicting phase: dryRun, resolve, lockedDryRun, or commit, then rerun the semantic request.' }]
	}
	if (nestedSpecCode === 'SPEC_COMMIT_MODE_REQUIRED' || nestedSpecCode === 'SPEC_COMMIT_MODE_CONFLICT') {
		return [{ type: 'correct_commit_mode', tool: 'betterpptx.deck.generate_from_spec', description: 'Use createNew without deckId, or append/replaceDeck/patch with an existing deckId, then rerun dryRun.' }]
	}
	if (nestedSpecCode === 'SPEC_INVALID') {
		return [{ type: 'revise_spec', tool: 'betterpptx.deck.generate_from_spec', description: 'Revise the semantic fields named by the finding, then rerun dryRun before commit.' }]
	}
	if (nestedSpecCode === 'SPEC_NOT_LOCKED') {
		return [{ type: 'resolve_lock', tool: 'betterpptx.deck.generate_from_spec', description: 'Run phase:"resolve" first or provide locked media/avatar/template handles, then rerun lockedDryRun.' }]
	}
	if (nestedSpecCode === 'SMARTART_TEXT_POLARITY_UNRESOLVED') {
		return [{ type: 'choose_smartart_text_polarity', tool: 'betterpptx.deck.generate_from_spec', description: 'Use AI design judgment to set a whole-diagram style.color/textColorRole or nodes[].color/textColorRole for every unresolved native SmartArt node, then rerun dryRun and inspect the full PowerPoint render.' }]
	}
	if (nestedSpecCode === 'SMARTART_NODE_TOPOLOGY_INVALID') {
		return [{ type: 'correct_smartart_node_topology', tool: 'betterpptx.deck.generate_from_spec', description: 'Restructure nodes to match the selected layout topologyContract—for Radial Cluster, one Level 1 root with 1–7 Level 2 children—then rerun dryRun and inspect the full PowerPoint render.' }]
	}
	if (nestedSpecCode === 'MODEL3D_POSTER_ANIMATION_UNSUPPORTED') {
		return [{ type: 'remove_unsupported_model3d_poster_animation', tool: 'betterpptx.deck.generate_from_spec', description: 'Remove scene.posterAnimId, use a presentation-ready GLB base pose or governed static-mode asset, then rerun dryRun and inspect the full PowerPoint render.' }]
	}
	if (nestedSpecCode === 'PRESENTER_STAGE_TREATMENT_INVALID') {
		return [{ type: 'choose_presenter_stage_treatment', tool: 'betterpptx.deck.generate_from_spec', description: 'Choose the exact unranked presenter.stageTreatment ID none or floor-ellipse, then rerun dryRun.' }]
	}
	const catalogRecovery=motionCatalogRecovery(nestedSpecCode||code)
	if (catalogRecovery) return catalogRecovery
	if (/^MOTION_/.test(code) || /^MOTION_/.test(String(nestedSpecCode || ''))) {
		return [{ type: 'revise_motion_selection', tool: 'betterpptx.deck.generate_from_spec', description: 'Choose exact executable motion IDs returned by betterpptx.authoring.catalog, keep each presenter bundle at 18 or fewer, ensure every slide motion is in that bundle, then rerun dryRun.' }]
	}
	switch (code) {
		case 'SERVICE_DISABLED':
			return [
				{ type: 'retry_later', description: 'The presentation service is temporarily unavailable. Retry after maintenance ends.' },
			]
		case 'READ_ONLY':
			return [
				{ type: 'use_read_only_tools', description: 'Inspect or validate existing work, then retry mutating operations when editing is enabled again.' },
			]
		case 'RATE_LIMITED':
			return [
				{ type: 'retry_later', description: 'Retry after the current rate-limit window resets.' },
			]
		case 'TOOL_TIMEOUT':
			return [
				{ type: 'retry_smaller_step', description: 'Retry with a smaller operation or split the deck work into smaller chunks.' },
			]
		case 'OPERATION_DISPATCH_UNAVAILABLE':
		case 'OPERATION_PENDING': {
			const operationId = String(details?.operationId || '')
			if (!/^op_[0-9a-f]{32}$/i.test(operationId)) {
				return [{ type: 'retry_same_request', description: 'If retrying, send the identical request with its original idempotency key.' }]
			}
			return [{
				type: 'check_operation_status',
				tool: 'betterpptx.operation.status',
				request: { operationId },
				description: 'First check operation status and poll while it is queued or running. If an identical replay is needed, resend the exact original request with its original idempotency key; do not change the payload.',
			}]
		}
		case 'UPLOAD_TOO_LARGE':
			return [
				{ type: 'reduce_upload', description: 'Upload a smaller PowerPoint file or reduce embedded media before retrying.' },
			]
		case 'REQUIRES_UPGRADE':
		case 'QUOTA_EXCEEDED':
		case 'INSUFFICIENT_CREDITS':
			if (String(process.env.BETTERPPTX_BILLING_MODEL || '').trim().toLowerCase() === 'pay_per_job') {
				return [
					{ type: 'job_payment', tool: 'price-listing', description: 'Price the exact authored specification, then approve one x402 payment for that bounded job; no reusable BetterPPTX balance is created.' },
					{ type: 'job_recovery', tool: 'betterpptx.billing.job_status', description: 'If payment or execution was interrupted, poll the same job with its opaque purchaseContext; do not submit another payment or use a transaction hash as the credential.' },
					{ type: 'free_fallback', description: details?.suggestion || 'Continue with the best free-tier fallback without silently changing the requested feature.' },
				]
			}
			return [
				{ type: 'payment_options', tool: 'betterpptx.billing.payment_options', description: 'Choose the browser, app, or agent-native payment path for this installation, then retry the requested step.' },
				{ type: 'billing', tool: 'betterpptx.billing.portal', description: 'Get the identity-bound top-up link and current credit balance.' },
				{ type: 'free_fallback', description: details?.suggestion || 'Continue with the best free-tier fallback without silently dropping the requested feature.' },
			]
		case 'BILLING_SETUP_INCOMPLETE':
			return [
				{ type: 'activate', tool: 'betterpptx.auth.activate_key', description: 'Retry activation with the checkout key so the billing customer can be linked.' },
				{ type: 'billing', tool: 'betterpptx.billing.portal', description: 'Open billing if the checkout completed but the key is still not linked.' },
			]
		case 'BILLING_TEMPORARILY_UNAVAILABLE':
			return [
				{ type: 'retry_later', description: 'Retry the same billable operation after billing balance verification recovers.' },
				{ type: 'use_read_only_tools', description: 'Continue inspecting or editing locally without running checkpoint or heavy billable work.' },
			]
		case 'BILLING_CONFIRMATION_REQUIRED':
			return [
				{ type: 'confirm_billing', description: 'Ask the user to confirm the estimated credit cost before retrying with billingConfirmed enabled.' },
				{ type: 'reduce_scope', description: 'Reduce deck size, media, narration, or batch scope before retrying.' },
			]
		case 'INVALID_PREMIUM_PREVIEW_TRANSITION':
			return [
				{ type: 'correct_transition', tool: 'betterpptx.slide.set_transition', description: 'Set slide 2 to Morph by object when that supports the story.' },
				{ type: 'continue', description: 'Keep slides 1 and 2 as normal story progression; do not duplicate content only for coverage.' },
			]
		case 'BUSY':
			return [
				{ type: 'retry', description: 'Retry the same call after a short delay.' },
			]
		case 'BLACK_BOX':
			return [
				{ type: 'use_public_input', description: 'Use uploaded bytes, HTTPS URLs, opaque handles, or public-safe selectors instead of local server paths or private diagnostics.' },
			]
		case 'SAFE_FETCH_REFUSED':
		case 'SAFE_FETCH_INVALID_CONTENT_TYPE':
		case 'SAFE_FETCH_TOO_LARGE':
		case 'SAFE_FETCH_TIMEOUT':
		case 'SAFE_FETCH_FAILED':
			return [
				{ type: 'use_media_url', description: 'Use a direct public HTTPS media URL that returns the expected media content type.' },
				{ type: 'upload_asset', description: 'Upload the media bytes through the AI client and use that asset instead.' },
			]
		case 'AVATAR_UNAVAILABLE':
		case 'MEDIA_PROBE_FAILED':
		case 'MEDIA_NORMALIZE_FAILED':
		case 'MEDIA_UNSUPPORTED_INPUT':
			return [
				{ type: 'retry_later', description: 'Retry after avatar media generation is configured, or use a completed avatar asset.' },
			]
		case 'AVATAR_SELFIE_REQUIRED':
			return [
				{ type: 'upload_selfie', description: 'Upload the user selfie with consentAffirmed:true in this generation request, then retry.' },
				{ type: 'voice_only', description: 'Continue with ordinary voice narration without a talking-head video.' },
			]
		case 'AVATAR_CONSENT_REQUIRED':
			return [
				{ type: 'confirm_consent', description: 'Only retry with uploaded presenter images after the user confirms ownership or permission.' },
			]
		case 'AVATAR_JOB_NOT_READY':
			return [
				{ type: 'poll_status', tool: 'betterpptx.avatar.job_status', description: 'Poll the avatar render job until it succeeds before attaching it.' },
			]
		case 'AVATAR_JOB_REQUIRED':
			return [
				{ type: 'start_job', tool: 'betterpptx.avatar.render_job', description: 'Start an avatar render job, poll it, then attach the completed result.' },
				{ type: 'attach_result', tool: 'betterpptx.avatar.attach_result', description: 'Attach the completed avatar video after the job succeeds.' },
			]
		case 'NARRATION_SYNTHESIS_RUNTIME_UNAVAILABLE':
		case 'NARRATION_SYNTHESIS_RUNTIME_TIMEOUT':
			return [
				{ type: 'check_readiness', tool: 'betterpptx.narration.voices', description: 'Check synthesisRuntimeAvailable, mode, and productionReady; retry synthesis only when the configured runtime is available.' },
				{ type: 'retry_preparation', tool: 'betterpptx.narration.synthesize', description: 'Retry the same bounded preparation request with its idempotencyKey after the approved synthesis runtime recovers.' },
			]
		case 'NARRATION_SYNTHESIS_FAILED':
			return [
				{ type: 'inspect_preparation', tool: 'betterpptx.narration.synthesize', description: 'Correct the rejected preparation input or voice selection, then retry with the same idempotencyKey only when the request is unchanged.' },
			]
		case 'NARRATION_PREPARATION_REQUIRED':
		case 'NARRATION_PREPARATION_EXPIRED':
		case 'NARRATION_PREPARATION_INVALID':
		case 'NARRATION_PREPARATION_TIMING_MISMATCH':
			return [
				{ type: 'prepare_measured_audio', tool: 'betterpptx.narration.synthesize', description: 'Prepare the exact script/segments again, then copy the returned preparationId, manifestHandle, and manifestDigest into the narrated spec before requesting the final quote.' },
				{ type: 'inspect_voice_readiness', tool: 'betterpptx.narration.voices', description: 'Confirm the selected voice remains catalogued, runtime-ready, caller-authorized, and production-approved before retrying preparation.' },
			]
		case 'QUOTE_BINDING_REQUIRED':
			return [
				{ type: 'request_final_quote', tool: 'betterpptx.billing.estimate', description: 'Request the final read-only quote with the exact authored spec and prepared narration manifest, then copy its complete quoteBinding into generate_from_spec.' },
				{ type: 'inspect_preparation', tool: 'betterpptx.narration.synthesize', description: 'If narration is present, prepare and measure the exact script first; the final quote cannot be created from notes or an estimated duration.' },
			]
		case 'QUOTE_BINDING_MISMATCH':
			return [
				{ type: 'request_fresh_quote', tool: 'betterpptx.billing.estimate', description: 'Request a new quote for the unchanged final spec and exact prepared narration manifest, then pass its quoteBinding unchanged.' },
				{ type: 'preserve_prepared_audio', tool: 'betterpptx.narration.synthesize', description: 'Do not synthesize again unless the script, voice, or segment inputs changed; reuse the valid preparation manifest.' },
			]
		case 'IMAGE_GENERATION_UNAVAILABLE_IN_PRODUCTION':
			return [
				{ type: 'author_native_visual', tool: 'betterpptx.deck.generate_from_spec', description: 'Keep the visual concept in the AI-authored spec and express it with native editable objects; do not include a gen://image handle.' },
				{ type: 'use_approved_media', tool: 'betterpptx.assets.search_stock', description: 'Choose an approved supplied or licensed stock asset when a real media asset is necessary.' },
			]
		case 'IMAGE_GENERATION_DISABLED_BY_DEPLOYMENT_POLICY':
			return [
				{ type: 'author_native_visual', tool: 'betterpptx.deck.generate_from_spec', description: 'Keep the visual concept in authored intent or attach an approved supplied/stock asset while this deployment policy is disabled.' },
			]
		case 'GENERATED_IMAGE_ASSET_UNAVAILABLE':
			return [
				{ type: 'rehydrate_asset', tool: 'betterpptx.assets.generate_image', description: 'Use an authorized durable generated-image handle that resolves for the current caller, or generate the visual through the governed route before compiling.' },
				{ type: 'use_approved_media', tool: 'betterpptx.assets.search_stock', description: 'Use an approved supplied or licensed stock asset when the generated-image asset cannot be rehydrated.' },
			]
		case 'DECK_EXPIRED_OR_UNKNOWN':
			return [
				{ type: 'reopen_or_recreate', description: 'Reopen the uploaded deck or recreate the deck, then continue from the latest valid state.' },
			]
		case 'DECK_VERSION_CONFLICT':
			return [
				{ type: 'reinspect', tool: 'betterpptx.deck.summary', description: 'Refresh the deck state and retry the mutation against the current deckVersion.' },
			]
		case 'DIRECTOR_STAGE_REQUIRED':
			return [
				{ type: 'define_message', tool: 'betterpptx.deck.define_message_architecture', description: 'Define the audience, thesis, story arc, slide messages, and word budget.' },
				{ type: 'assign_roles', tool: 'betterpptx.deck.assign_slide_roles', description: 'Assign a communicative role or layout archetype to each planned slide.' },
				{ type: 'define_system', tool: 'betterpptx.deck.define_design_system', description: 'Define the seven-pillar design system before primitive slide construction.' },
			]
		case 'DIRECTOR_CONTRACT_REQUIRED':
		case 'DIRECTOR_DOMAIN_REQUIRED':
		case 'DIRECTOR_PRIMITIVE_REQUIRED':
		case 'DIRECTOR_TIMELINE_REQUIRED':
		case 'DIRECTOR_VERIFICATION_REQUIRED':
		case 'CURRENT_VERSION_VALIDATION_REQUIRED':
			return [
				{ type: 'director_workflow', tool: 'betterpptx.help.workflow', description: 'Continue through the Authoring Excellence Director stages; hard-coded primitive/direct creation and fixed autoplay are not supported.' },
				{ type: 'validate', tool: 'betterpptx.deck.validate_quality', description: 'Run the aggregate Director quality gate before saving.' },
			]
		case 'SPEC_COMPILE_FAILED':
			return [
				{ type: 'revise_spec', tool: 'betterpptx.deck.generate_from_spec', description: 'Fix deterministic spec errors, especially object kind, stable names, semantic layout intent, verified evidence, and shape/text separation, then dry-run again.' },
			]
		case 'CONNECTOR_FILE_MISSING':
		case 'UNSUPPORTED_FILE_REFERENCE':
		case 'UPLOAD_SESSION_EXPIRED':
			return [
				{ type: 'attach_connector_file', tool: 'betterpptx.assets.upload', description: 'Attach the required true media asset or portable BetterPPTX JSON spec through the host connector file parameter, data URI, or HTTPS URL.' },
			]
		case 'PACKAGE_TOO_LARGE':
			return [
				{ type: 'reduce_package', description: 'Upload a zip at or under the allowed package size, then retry assets.upload.' },
			]
		case 'INVALID_ZIP':
		case 'ENTRY_FILE_NOT_FOUND':
		case 'RELATIVE_ASSET_MISSING':
			return [
				{ type: 'repair_html_package', tool: 'betterpptx.assets.upload', description: 'Upload a zip that contains the HTML entry file and its relative images, then inspect the handle.' },
			]
		case 'INVALID_IDEMPOTENCY_KEY':
		case 'IDEMPOTENCY_CONFLICT':
			return [
				{ type: 'use_new_idempotency_key', description: 'Use a fresh retry key for a different operation, or retry with the exact original arguments.' },
			]
		case 'IDEMPOTENCY_KEY_REQUIRED':
			return [
				{ type: 'supply_idempotency_key', description: 'Choose one stable idempotencyKey for this side-effecting operation and reuse it with identical arguments on every retry. This is retry protection, not payment authorization.' },
			]
		case 'PREVIEW_REQUIRED':
		case 'PREVIEW_INCOMPLETE':
		case 'PREVIEW_FREEZE_MISMATCH':
		case 'PUBLIC_PREVIEW_OUTPUT_FORMAT_REQUIRED':
			return [
				{ type: 'preview_remaining_slides', tool: 'betterpptx.deck.preview', description: 'Preview every remaining current-version slide in batches of at most 12, then save outputFormat:"pptx" using one stable idempotencyKey.' },
			]
		case 'AUTHORITATIVE_PREVIEW_INFRASTRUCTURE_REQUIRED':
			if (!publicVerificationPolicy().rendererRequiredForSave) {
				return [
					{ type: 'continue_non_rendering_save', tool: 'betterpptx.deck.validate_quality', description: 'PowerPoint preview is unavailable by the production policy; run deterministic package, media, timing, accessibility, and selection validation, then save if the current version passes.' },
					{ type: 'release_qualification', tool: 'betterpptx.help.capabilities', description: 'Use the release-powerpoint environment when PowerPoint visual or playback qualification is required; do not label this production package as previewed.' },
				]
			}
			return [
				{ type: 'configure_authoritative_preview', description: 'An approved PowerPoint-capable render service must be configured before public preview or release-policy save can proceed.' },
				{ type: 'inspect_capability', tool: 'betterpptx.help.capabilities', description: 'Read releaseInfrastructure.authoritativePreview and keep the release candidate unsaved while status is external-infrastructure-required.' },
			]
		case 'PUBLIC_PREVIEW_ARTIFACT_UNAVAILABLE':
			return [
				{ type: 'configure_preview_delivery', description: 'Enable client-accessible preview artifact delivery, then retry the same frozen-package preview batch.' },
				{ type: 'keep_unsaved', description: 'Keep the release candidate unsaved because an inaccessible render cannot count as visual review evidence.' },
			]
		case 'POWERPOINT_PREVIEW_REPAIR_PROOF_REQUIRED':
		case 'POWERPOINT_PREVIEW_HASH_MISMATCH':
		case 'POWERPOINT_PREVIEW_3D_NOT_READY':
			return [
				{ type: 'repair_authoritative_preview', description: 'Use a healthy PowerPoint preview worker that opens read-only with repair disabled and returns verifiable per-slide render hashes.' },
				{ type: 'keep_unsaved', description: 'Keep the release candidate unsaved because unverified render or repair evidence cannot satisfy the release boundary.' },
			]
		case 'PPTX_PACKAGE_SAFETY_FAILED':
		case 'PUBLIC_OUTPUT_SHAPE_LIMIT':
			return [
				{ type: 'repair_content', description: details?.recommendation || 'Revise the deck content and retry validation before saving.' },
			]
		case 'INVALID_ACTIVATION_KEY':
		case 'LICENSE_REVOKED':
		case 'LICENSE_EXPIRED':
		case 'LICENSE_VALIDATION_FAILED':
		case 'LICENSE_VALIDATION_UNAVAILABLE':
			return [
				{ type: 'check_key', description: 'Ask the user to verify the license key from checkout and try activation again.' },
				{ type: 'billing', tool: 'betterpptx.billing.portal', description: 'Offer the billing portal or checkout link if the user needs account help.' },
			]
		default:
			return [
				{ type: 'inspect_request', description: 'Review the tool arguments, preserve valid work so far, and retry with a smaller public-safe step.' },
			]
	}
}

