function publicArtifactStateForError(code, details = {}) {
	if (details?.artifactStatus) return details.artifactStatus
	if (code === 'OPERATION_DISPATCH_UNAVAILABLE') return 'unknown_or_pending'
	if (code === 'REQUIRES_UPGRADE' || code === 'INVALID_PREMIUM_PREVIEW_TRANSITION') return 'work_so_far_valid'
	if (code === 'PPTX_PACKAGE_SAFETY_FAILED') return 'not_delivered'
	if (code === 'PUBLIC_OUTPUT_SHAPE_LIMIT') return 'not_saved'
	if (['IDEMPOTENCY_KEY_REQUIRED', 'CURRENT_VERSION_VALIDATION_REQUIRED', 'PREVIEW_REQUIRED', 'PREVIEW_INCOMPLETE', 'PREVIEW_FREEZE_MISMATCH', 'PUBLIC_PREVIEW_OUTPUT_FORMAT_REQUIRED', 'AUTHORITATIVE_PREVIEW_INFRASTRUCTURE_REQUIRED', 'POWERPOINT_PREVIEW_REPAIR_PROOF_REQUIRED', 'POWERPOINT_PREVIEW_HASH_MISMATCH', 'POWERPOINT_PREVIEW_3D_NOT_READY'].includes(code)) return 'not_saved'
	if (code === 'DECK_EXPIRED_OR_UNKNOWN') return 'deck_handle_unavailable'
	if (code === 'UPLOAD_TOO_LARGE') return 'not_imported'
	if (code === 'DECK_VERSION_CONFLICT') return 'unchanged'
	if (code === 'IDEMPOTENCY_CONFLICT') return 'unchanged_or_unknown'
	return 'unchanged_or_unknown'
}

function recommendedNextForSuccess(name, args = {}, data = {}) {
	if (data?.next) return data.next
	if (name === 'betterpptx.deck.new') {
		if (isPublicBlackBoxMode()) {
			return { recommendedTool: 'betterpptx.deck.generate_from_spec', reason: 'Author the complete governed JSON spec and dry-run it through generate_from_spec before commit.' }
		}
		if (data?.director?.requiredBeforePrimitives) {
			return { recommendedTool: 'betterpptx.deck.define_message_architecture', reason: 'Define message architecture before slide primitives in director-strict mode.' }
		}
		return { recommendedTool: 'betterpptx.slide.add', reason: 'Add the first slide, then compose content with public slide primitives.' }
	}
	if (name === 'betterpptx.deck.define_message_architecture') {
		return { recommendedTool: 'betterpptx.deck.assign_slide_roles', reason: 'Assign a communicative role or layout archetype to each planned slide.' }
	}
	if (name === 'betterpptx.deck.assign_slide_roles') {
		return { recommendedTool: 'betterpptx.deck.define_design_system', reason: 'Define the global seven-pillar design system before primitive instantiation.' }
	}
	if (name === 'betterpptx.deck.define_design_system') {
		return data?.completed
			? { recommendedTool: 'betterpptx.slide.add', reason: 'Director planning is complete; start primitive slide construction.' }
			: { recommendedTool: 'betterpptx.deck.define_design_system', reason: 'Complete missing design-system pillars before primitive instantiation.' }
	}
	if (name === 'betterpptx.deck.save') {
		return { recommendedTool: null, reason: 'Deck package is saved; share the download artifact if present.' }
	}
	if (/^betterpptx\.slide\./.test(name)) {
		return publicVerificationPolicy().rendererRequiredForSave
			? { recommendedTool: 'betterpptx.slide.preview', reason: 'Complete the selected release preview after this change.' }
			: { recommendedTool: 'betterpptx.deck.validate_quality', reason: 'Run deterministic quality and selected-control validation before renderer-free production save.' }
	}
	if (/^betterpptx\.deck\./.test(name)) {
		return publicVerificationPolicy().rendererRequiredForSave
			? { recommendedTool: 'betterpptx.deck.preview', reason: 'Complete the selected release preview after this change.' }
			: { recommendedTool: 'betterpptx.deck.validate_quality', reason: 'Run deterministic quality and selected-control validation before renderer-free production save.' }
	}
	return { recommendedTool: 'betterpptx.deck.summary', reason: 'Inspect current deck state before the next mutation.' }
}

function addSuccessEnvelope(data, name, args = {}) {
	if (!data || typeof data !== 'object' || Array.isArray(data)) return data
	if (MONETIZED_MCP_PROTOCOL_TOOLS.has(name)) return data
	if (!isMutatingTool(name)) return data
	data.schemaVersion ||= TOOL_RESPONSE_VERSION
	data.ok = data.ok !== false
	if (!Array.isArray(data.warnings)) data.warnings = []
	if (!Array.isArray(data.artifacts)) data.artifacts = []
	data.next ||= recommendedNextForSuccess(name, args, data)
	return data
}

function normalizePublicErrorResult(result) {
	if (!isPublicBlackBoxMode() || !result || result.ok !== false || !result.error) return result
	const current = result.error
	const details = current.details && typeof current.details === 'object' ? current.details : {}
	const baseCode = String(current.code || details.code || 'TOOL_ERROR')
	const nestedSpecCode = baseCode === 'SPEC_COMPILE_FAILED' && Array.isArray(details.errors)
		? details.errors.find(item => item && typeof item === 'object' && item.code)?.code
		: null
	const nestedMotionCode = baseCode === 'SPEC_COMPILE_FAILED' && Array.isArray(details.errors)
		? details.errors.map(item => String(item?.code || '')).find(item => /^(?:MOTION_|PRESENTER_)/.test(item))
		: null
	const code = nestedMotionCode || baseCode
	if (unclassifiedRuntimeErrorCode(baseCode)) {
		// Unknown runtime failures are not authoring findings. Keep the recovery
		// anchor without leaking dependencies, provider paths or private internals.
		return { ...result, error: {
			code: baseCode, message: 'The presentation operation could not be confirmed.',
			recoverable: true, retry_safe: false, retryable: false, artifact_state: 'unchanged_or_unknown',
			...(details.operationId ? { details: { operationId: details.operationId },
				next_actions: [{ type: 'recover_operation', tool: 'betterpptx.operation.status', input: { operationId: details.operationId } }],
			} : {}),
		} }
	}
	const findingFixes = {
		SPEC_REQUIRED: 'Provide a semantic JSON spec with schemaVersion, title, and slides, then rerun dryRun.',
		SPEC_PHASE_INVALID: 'Choose phase dryRun, resolve, lockedDryRun, or commit and rerun the request.',
		SPEC_PHASE_CONFLICT: 'Use either phase or dryRun, not conflicting values in the same request.',
		SPEC_COMMIT_MODE_REQUIRED: 'Supply commitMode append, replaceDeck, or patch with an existing deckId, or omit deckId for createNew.',
		SPEC_COMMIT_MODE_CONFLICT: 'Match commitMode to deckId: createNew for a new deck, or append/replaceDeck/patch for an existing deck.',
		SPEC_INVALID: 'Revise the semantic spec using the reported validation message and rerun dryRun.',
		SPEC_NOT_LOCKED: 'Run phase resolve first or provide locked media/avatar/template handles before lockedDryRun.',
		SMARTART_TEXT_POLARITY_UNRESOLVED: 'Choose an explicit whole-diagram or per-node native SmartArt text colour with AI design judgment, then rerun dryRun and inspect the full PowerPoint render.',
		SMARTART_NODE_TOPOLOGY_INVALID: 'Restructure nodes to match the selected native layout topologyContract, then rerun dryRun and inspect the full PowerPoint render.',
		MODEL3D_POSTER_ANIMATION_UNSUPPORTED: 'Remove scene.posterAnimId and use a presentation-ready GLB base pose or governed static-mode asset before rerunning dryRun.',
		MOTION_BUNDLE_LIMIT_EXCEEDED: 'Select no more than 18 unique public motion IDs for this presenter bundle, then rerun dryRun.',
		MOTION_ID_UNKNOWN: 'Choose an exact motion ID returned by betterpptx.authoring.catalog, then rerun dryRun.',
		MOTION_NOT_EXECUTABLE: 'Choose a currently executable motion ID from the default public catalog view.',
		MOTION_ID_DUPLICATE: 'Remove the duplicate motion ID from this presenter bundle.',
		MOTION_NOT_IN_BUNDLE: 'Add this motion ID to the presenter bundle or choose a slide motion already present in that bundle.',
		MOTION_PRESENTER_UNKNOWN: 'Match presenterId to the top-level presenter or a presenters.cast entry.',
		MOTION_PRESENTER_BASE_UNAVAILABLE: 'Use a resolvable rigged presenter identity before selecting its motion bundle.',
		PRESENTER_STAGE_TREATMENT_INVALID: 'Choose none or floor-ellipse from the unranked public presenter-stage vocabulary, then rerun dryRun.',
	}
	const normalizeFindingList = (value, scope) => Array.isArray(value)
		? value.map((finding, index) => {
			const source = finding && typeof finding === 'object' ? finding : { message: String(finding || 'Authoring request failed.') }
			const findingCode = String(source.code || code || `${scope.toUpperCase()}_FAILED`)
			const message = String(source.message || source.issue || source.reason || current.message || 'The semantic authoring request failed.')
			return {
				...source,
				code: findingCode,
				severity: source.severity || 'error',
				message,
				reason: source.reason || message,
				fix: source.fix || findingFixes[findingCode] || 'Change the semantic input identified by this finding and rerun dryRun; do not patch engine geometry or native package data.',
				evidence: source.evidence || { scope, code: findingCode, index },
			}
		})
		: value
	const normalizedDetails = {
		...details,
		...(Array.isArray(details.errors) ? { errors: normalizeFindingList(details.errors, 'spec-error') } : {}),
		...(Array.isArray(details.warnings) ? { warnings: normalizeFindingList(details.warnings, 'spec-warning') } : {}),
		...(Array.isArray(details.issues) ? { issues: normalizeFindingList(details.issues, 'spec-issue') } : {}),
	}
	return {
		...result,
		error: {
			code,
			message: String(current.message || 'The presentation tool call failed.'),
			recoverable: current.recoverable ?? publicRecoverableForError(code),
			next_actions: (baseCode === 'SPEC_COMPILE_FAILED' && nestedSpecCode)
				? publicNextActionsForError(baseCode, details)
				: current.next_actions || publicNextActionsForError(code, details),
			retry_safe: current.retry_safe ?? publicRetrySafeForError(code),
			retryable: current.retryable ?? current.retry_safe ?? publicRetrySafeForError(code),
			artifact_state: current.artifact_state || publicArtifactStateForError(code, details),
			...(Array.isArray(current.acceptedInputFields) ? { acceptedInputFields: current.acceptedInputFields } : {}),
			...(current.requestId ? { requestId: current.requestId } : {}),
			...(Object.keys(normalizedDetails).length ? { details: normalizedDetails } : {}),
		},
	}
}

function buildToolErrorResult(err, internalName, args = {}) {
	const error = {
		message: String(err && err.message || err),
		code: err?.code || 'TOOL_ERROR',
		retryable: err?.retryable === true || err?.details?.retryable === true,
		...(Array.isArray(err?.acceptedInputFields) ? { acceptedInputFields: err.acceptedInputFields } : {}),
		...(err?.details ? { details: err.details } : {}),
		...(!isPublicBlackBoxMode() && err?.stack ? { stack: err.stack } : {}),
	}
	if (error.code === 'TOOL_TIMEOUT' && isMutatingTool(internalName) && !hasIdempotencyKey(args)) {
		error.retry_safe = false
		error.artifact_state = 'unchanged_or_unknown'
		error.details = {
			...(error.details || {}),
			status: 'timeout_after_mutation_started',
			recommendation: 'Retry mutating calls with an idempotencyKey so a delayed original operation cannot create duplicate content.',
		}
	}
	return sanitizePublicResult(normalizePublicErrorResult({ ok: false, error }))
}

function finishToolCall(trace, internalName, result) {
	const durationMs = trace?.startedAt ? Number(process.hrtime.bigint() - trace.startedAt) / 1e6 : 0
	recordToolTelemetry(internalName, result, { durationMs })
	// createNew commits only learn their deckId here — label it so deck build-time
	// (first op -> save) reconstructs from the observations log.
	try {
		const resultDeckId = result?.deckId || result?.data?.deckId
		if (resultDeckId) recordResourceLabels({ deckHash: hashDeckId(resultDeckId).slice(-16) })
	} catch { /* advisory */ }
	finishResourceMeasure(trace?.resourceMeasure, {
		ok: result?.ok !== false && !result?.error,
		errorCode: result?.error?.code || result?.data?.error?.code || '',
		result,
	})
	logToolEnd(trace, result)
	return result
}

function hasNestedOwnKey(value, key) {
	if (!value || typeof value !== 'object') return false
	if (Object.prototype.hasOwnProperty.call(value, key)) return true
	return Object.values(value).some(child => hasNestedOwnKey(child, key))
}

function requestsRetiredGenericImageGeneration(value) {
	if (!value || typeof value !== 'object') return false
	if (Object.prototype.hasOwnProperty.call(value, 'visualGeneration')) return true
	const kind = String(value.kind || '').toLowerCase()
	const imageKind = kind === 'image' || kind === 'image-feature'
	const hasVisualIntent = value.visualIntent && typeof value.visualIntent === 'object'
	const hasSuppliedSource = ['assetRef', 'image', 'path', 'url', 'data', 'imageUrl', 'imageBase64']
		.some(key => value[key] !== undefined && value[key] !== null && value[key] !== '')
	if (imageKind && hasVisualIntent && !hasSuppliedSource) return true
	return Object.values(value).some(child => requestsRetiredGenericImageGeneration(child))
}

