		const retired = Object.assign(new Error('The specification requests retired server-side generic image generation. Generate or edit the image in the AI client, upload it, and reference the resulting asset handle in the authored spec.'), {
			code: 'IMAGE_GENERATION_RETIRED',
			retryable: false,
			details: { fields: ['visualGeneration', 'source-less image.visualIntent'], alternativeTool: 'betterpptx.assets.upload' },
		})
		const result = buildToolErrorResult(retired, internalName, args)
